/* AMERICAN DICTATOR, cs deck translations (lazy-loaded). Falls back to English per field. */
AD.CARDT.cs = {"crowd-size":{"t":"Čísla","x":"Letecké fotografie z inaugurace jsou venku. Dav je skutečný, je nadšený a je zhruba tak velký jako krajská výstava psů. Beacon zveřejnil obě fotky vedle sebe.","c":[["Pošlete Kaylee ven, ať řekne, že to byl největší dav v historii. Tečka.","Řekne to s naprostým přesvědčením. Nikdo jí nevěří. Všichni si ale všimnou, že to řekla stejně, a o to šlo."],["„Davy jsou posedlost médií. Další otázka.“","Kauza umírá za čtyřicet minut. Něco ve vás umírá s ní."],["Nařiďte Správě parků, ať zveřejní „opravená“ čísla.","Kariérní fotoarchivář je přeřazen do místnosti bez oken v Suitlandu. Číslo je teď 1,9 milionu. Je zapsané. Je oficiální."],["Zveřejněte fotku úplně jiného, většího davu.","Je to snímek z oslavného průvodu basketbalového týmu z roku 1998. Všimne si toho devět lidí. V oficiálních záznamech to zůstane čtyři roky."]]},"day-one-binder":{"t":"Šanon","x":"Deborah položí na stůl šanon velký jako dlažební kostka. „Dvě stě jedenáct exekutivních nařízení, předem sepsaných lidmi, které jste nikdy nepotkal, z institutu, který jste nikdy nenavštívil. Rádi by je měli všechny do pátku.“","c":[["Podepište je všechny živě v televizi.","Podepisujete devadesát minut. Čtyřicet jedna je do pondělí zablokováno soudem. Sedmnáct ne, a těch sedmnáct rozhoduje o všem."],["Podepište jen těch čtyřicet oblíbených. Zbytek odložte.","Zdrženlivý začátek. Institut posílá vzkaz, ve kterém vás popisuje jako „slibného“."],["„Kdo tohle psal? Ať sem přijdou. Chci ty, za které se styděli.“","Existuje druhý šanon. Je tenčí a mnohem horší. Vezmete si ten."],["Podepisujte je v náhodném pořadí, živě, bez čtení, jako charitativní sbírku.","Vyberete 2,1 milionu dolarů pro dětskou nemocnici a omylem na devět dní zrušíte Úřad pro správu půdy."]]},"clemency-cannon":{"t":"Kanón milosti","x":"Bo Slaughter má seznam zhruba patnácti set lidí odsouzených za dobytí federální budovy ve vaší věci. „Pane, v právním smyslu jsou vinni. V politickém smyslu jsou to vaši nejspolehlivější voliči.“","c":[["Omilostněte všech patnáct set. Před obědem.","Vězeňské dveře se otevírají na rozdělené televizní obrazovce. Muž v přilbě s rohy dává rozhovor z Applebee's. Vaše základna vás nikdy nemilovala víc."],["Omilostněte ty nenásilné. Ostatním zmírněte tresty.","Právnicky korektní. Obhajitelné. Nikdo si o tom neudělá tričko."],["Omilostněte je a pozvěte vůdce na státní večeři.","Zasedací pořádek unikne na veřejnost. Dva velvyslanci náhle onemocní chřipkou. Fotografie přežijí všechny, kdo jsou na nich."],["Omilostněte je podle abecedy. Skončete u G. Zbytku slibte příští rok.","Čtyři sta lidí je na svobodě a jedenáct set čeká u telefonu. Aplikoval jste na milost předplatitelský model."]]},"ig-purge":{"t":"Sedmnáct hlídacích psů","x":"„Sedmnáct generálních inspektorů. Celou jejich práci tvoří psaní zpráv o tom, co jsme udělali. Zákon říká, že musíme dát Kongresu třicetidenní výpovědní lhůtu, než někoho odvoláme.“ Odmlčí se. „Zákon ale neříká, co se stane, když to neuděláme.“","c":[["Vyhoďte všech sedmnáct dnes večer. E-mailem.","Soudkyně později rozhodne, že to bylo protiprávní, ale nikoho nevrátí do funkce, protože usoudí, že byste je stejně znovu vyhodil, tentokrát správně. Má pravdu."],["Dodržte třicet dní. Pak vyhoďte všech sedmnáct.","Papírování je bezchybné. Výsledek je stejný. Deborah se na vás podívá s něčím, co připomíná respekt."],["Nechte je. Místo toho jim seškrtejte rozpočty.","Jejich zprávy teď chodí s jedenáctiměsíčním zpožděním, černobílé, nesešité. Nikdo je nečte."],["Nechte všech sedmnáct. Ať vyšetřují jeden druhého.","Sedmnáct hlídacích psů, sedmnáct vyšetřování, nula zpráv o vás. Pořád to běží. Je to nejelegantnější věc, kterou jste nikdy neplánoval."]]},"broom-founded":{"t":"Muž s dřezem","x":"Nejbohatší muž na planetě právě vešel do zasedací místnosti vlády s kuchyňským dřezem v náručí, z důvodů, které považuje za samozřejmé. Chce úřad. Chce, aby se jmenoval BROOM. Chce root přístup do platebního systému ministerstva financí.","c":[["Dejte mu všechno. Sledujte, co se stane.","Do týdne přestanou existovat čtyři úřady, jeden z nich měl na starosti sledování ptačí chřipky. Zveřejní o tom graf."],["Dejte mu titul a odznak. Žádný přístup do systému.","Je zuřivý způsobem, který vygeneruje 4 miliardy zhlédnutí, což je svým způsobem taky politika."],["„Prezident je tu jeden. Vezměte si dřez a jděte.“","Do čtvrtka si koupí konkurenční politické hnutí. Vytvořil jste si drahého nepřítele s neomezeným volným časem."],["Vraťte mu dřez. Rozpočet na dřez si nechte.","Odchází s dřezem a bez úřadu. Nikdo v místnosti pak neumí vysvětlit, co se vlastně rozhodlo, včetně vás."]]},"confuffle":{"t":"Confuffle","x":"Ve 3:47 ráno jste napsal příspěvek se slovem „confuffle“ a šel spát. Bylo to retweetnuto 900 000krát. Beacon si najal lingvistu na plný úvazek. Ministerstvo zahraničí Northmarku požádalo o vysvětlení.","c":[["„Kdo přijde na skutečný význam slova confuffle? Bavte se!“","Vytvořil jste slovo. Dostane se do dvou slovníků jako „záměrná nejasnost použitá ke změně tématu“. Upřímně? Užitečné."],["Smažte to. Popřete to. Sveďte to na zaměstnance.","Té zaměstnankyni je 24 let a nic neudělala. Teď má smlouvu na knihu."],["Udělejte z „confuffle“ oficiální heslo pro odvolání jaderné pohotovosti.","Náčelníci štábů to respektují, protože v celém velitelském řetězci nikdo nemá pravomoc říct: „ne, to je hloupost.“"],["Oznamte, že confuffle je teď oficiální název pro středu.","Čtyři federální úřady si aktualizují plánovací software. Mzdový systém v Ohiu jedenáct hodin nefunguje. Středa je v pořádku."]]},"ocean-rename":{"t":"Kartografie","x":"„Požádal jste mě, abych prozkoumala možnost přejmenovat Atlantský oceán na Oceán svobody. Prozkoumala jsem to. Můžeme ho přejmenovat na našich mapách. Nemůžeme ho přejmenovat na mapách nikoho jiného. A oceán se to nedozví.“","c":[["Udělejte to. Na všech federálních mapách. Okamžitě.","Stojí to 40 milionů dolarů a nedosáhne se tím ničeho měřitelného, což z toho dělá nejčistší dosud vyzkoušený projev exekutivní moci."],["Nechte to být. Máme celé oceány skutečných problémů.","Brayden to nazve „naprosto nejhorším rozhodnutím vlády dosud“. Je mu devatenáct."],["Přejmenujte ho A vyžadujte, aby nový název používala i média, pokud chtějí akreditaci.","Jedna zpravodajská agentura odmítne. Zakážete jí vstup do budovy. Šedesát dalších médií to sleduje a potichu si upraví redakční pravidla."],["Místo toho ho pojmenujte po své matce. Proti tomu nikdo nic nenamítne.","Nikdo nic nenamítá. Je to opravdu dojemné. Kartografové po celém světě to z čirého zmatku respektují a na mapách to zůstane deset let."]]},"wire-service":{"t":"Zpravodajská agentura","x":"Zpravodajská agentura, které jste zakázal vstup, vysoudila předběžné opatření. Soudce, váš soudce, kterého jste jmenoval a váš Senát potvrdil, vám nařídil, abyste je pustil zpátky do místnosti.","c":[["Uposlechněte. Pak úplně zrušte stálé místo pro agenturní zpravodaje.","Uposlechl jste příkaz a zničil jste přitom to, co měl chránit. Deborah napíše na ubrousek slovo „elegantní“ a sní ho."],["Uposlechněte úplně. Viditelně se urážejte.","Systém fungoval. Někdo by měl systému říct, že to není kompliment."],["Odvolejte se. Po dobu odvolání je nepouštějte dovnitř. Odvolejte se proti odvolání.","Po dvou letech soudních sporů je otázka bezpředmětná, protože agentura byla mezitím prodána hedgeovému fondu, který vlastní i námořní přístav."],["Uposlechněte, ale posaďte je do sedacího vaku.","Příkaz je splněn do písmene. Zkušený zpravodaj jedenáct měsíců referuje patnáct centimetrů nad podlahou a získá za to ocenění."]]},"enemy-of-people":{"t":"Seznam nepřátel","x":"Brayden připravil příspěvek, ve kterém označuje čtyři jmenované redakce za „skutečné nepřátele amerického lidu“. Je nesmírně pyšný na velká písmena.","c":[["Zveřejněte to. Pro zábavu přidejte páté médium.","Náklad všech pěti vyskočí o 30 procent. Jejich reportéři teď dostávají výhrůžky domů. Obojí se teď stává trvalou součástí amerického života."],["Zmírněte to na „některá média“. Zveřejněte to.","Kličkování, které nikoho neoklame a nic nestojí. Volba profesionála."],["Smažte to. Zavolejte šéfredaktorovi. Buďte místo toho okouzlující.","Zpravodajství se na jedenáct dní zlepší. Brayden se na vás dívá tak, jak pes zírá na zavřené dveře."],["Místo toho napište jedné z nich pětihvězdičkovou recenzi.","Čtyři slova nečekané chvály způsobí v té redakci větší institucionální zmatek než čtyři roky útoků."]]},"hamberders":{"t":"HAMBERDERS","x":"Uspořádal jste recepci pro vítězný univerzitní tým a naservíroval jim 1000 hamburgerů z rychlého občerstvení pod zlatými svícny. Pak jste napsal příspěvek o „hamberders“. Ten překlep se teď prodává jako merch.","c":[["Jděte do toho naplno. Prodávejte oficiální kšiltovky Hamberder.","Za devadesát dní vyděláte 18 milionů dolarů. Historici to jednou označí za okamžik, kdy se prezidentský úřad a suvenýrový obchod oficiálně sloučily."],["Potichu opravte překlep.","Internet si stihne udělat screenshot originálu za čtyři sekundy, protože internet to tak dělá."],["„Píše se to tak, jak jsem to napsal.“ Nařiďte, ať to doplní do stylistické příručky.","Vládní tiskový úřad přidá „hamberder“ jako uznávanou variantu. Jazykový korektor po 31 letech odchází z funkce."],["Vyhlaste hamberder chráněnou regionální potravinou.","Federální označení, které se běžně uděluje sýrům. Dva okresy si podávají konkurenční žádosti o původ a spor trvá devět let."]]},"schedule-q":{"t":"Schedule Q","x":"„Dva miliony státních zaměstnanců mají ochranu pracovního místa. Ty, kteří se dotýkají tvorby politik, můžeme překlasifikovat do nové kategorie, kde slouží podle libosti. Vaší libosti. Ta kategorie zatím nemá jméno.“","c":[["Nazvěte to Schedule Q. Překlasifikujte 50 000 lidí.","Lidé, kteří píší pravidla, teď pracují pro muže, o kterém ta pravidla jsou. Nic dalšího, co za toto období uděláte, nebude mít takovou váhu."],["Překlasifikujte jen 4000, jen ty nejvyšší.","Chirurgicky přesné. Popiratelné. Skoro stejně účinné a jen s dvanáctinou soudních sporů."],["Nechte státní správu na pokoji. Najměte si loajalisty navrch.","Teď máte ve stejné budově dvě vlády a ta starší ví, kde je co."],["Překlasifikujte jen lidi, kteří vlastní loď.","Jedenáct set federálních zaměstnanců je přeřazeno na základě záznamů z přístavišť. Nikdo úspěšně nenapadne to kritérium, protože mu nikdo nemůže uvěřit."]]},"sharpie":{"t":"Fixa","x":"Řekl jste národu, že hurikán Delores zasáhne stát Kansaw. Nezasáhne. Oficiální předpovědní mapa bude na pódiu za devět minut a stát Kansaw na ní není.","c":[["Prodlužte kužel fixou. Prezentujte to tak, jak to je.","Smyčka černého inkoustu je vidět i z posledních řad. Národní meteorologické službě je nařízeno vydat podpůrné prohlášení. Vydá ho. A na tom nakonec záleží."],["„Řekl jsem Kansaw. Myslel jsem tím obecně okolí Kansaw.“","Slovo „okolí“ odvádí v této větě obrovský kus práce a není za to zaplaceno."],["Na začátku brífinku se čistě opravte.","Jedenáct minut vás chválí. Vaše základna stráví těch jedenáct minut úvahami, kdo na vás zapůsobil."],["Nakreslete hurikánu usmívající se obličej.","Oficiální materiál Národního hurikánového centra teď má usmívající se obličej. Zapojení do příprav na krizi stoupne o 31 procent. Je to, čirou náhodou, nejlepší rozhodnutí v oblasti veřejné bezpečnosti za celý rok."]]},"stable-genius":{"t":"Velmi stabilní génius","x":"Kniha tvrdí, že vás poradci považují za nevyzpytatelného. Požádal jste kontradmirála Prinea, aby vydal prohlášení o vašich kognitivních schopnostech. Chtěl by vědět, jak nadšené to prohlášení má být.","c":[["„Řekněte, že jsem velmi stabilní génius. Použijte přesně tahle slova.“","Ta fráze se stává trvalou jednotkou americké ironie. Uslyšíte ji i na vlastním pohřbu."],["Zveřejněte skutečné, nudné lékařské výsledky.","Váš cholesterol se stane dvoudenní mediální kauzou. Je to aspoň dvoudenní mediální kauza o cholesterolu."],["Ať řekne, že jste dosáhl „nejvyššího skóre, jaké kdy bylo zaznamenáno“ v kognitivním testu.","Podrobně ten test popisujete. Zahrnuje rozpoznání slona. Označíte to za obtížné."],["Místo toho vydejte prohlášení od psa.","Jednoodstavcové prohlášení podporující vaše kognitivní schopnosti, podepsané otiskem tlapky. Je to nejsdílenější tiskové prohlášení Bílého domu za čtyři desetiletí."]]},"paper-towels":{"t":"Pomoc při katastrofě","x":"Jste v centru pomoci obětem katastrofy na území, které je šest týdnů bez elektřiny. Je tam dav, hromada rolí papírových utěrek a řada kamer. Nikdo vám neřekl, co máte dělat s rukama.","c":[["Házejte papírové utěrky do davu. Jako střelu z výskoku.","Záznam trvá čtrnáct vteřin a bude se přehrávat při každém dalším hurikánu do konce vašeho života."],["Rozdávejte je jednu po druhé. Podávejte lidem ruku.","Nudné, slušné a ve večerním zpravodajství to úplně chybí, protože to vede zpráva o počtu mrtvých."],["Zpochybněte z pódia počet mrtvých.","Tři tisíce lidí se zredukují na rétorickou pozici. Území na to nezapomene. Sčítání lidu taky ne."],["Zůstaňte a šest hodin vykládejte náklaďáky. Nikomu to neříkejte.","Žádné kamery, žádné prohlášení, šest hodin. O jedenáct dní později to unikne z telefonu dobrovolníka a má to větší cenu než všechny projevy toho roku."]]},"dog":{"t":"První pes","x":"Každý prezident od Hoovera měl psa. Vy jste nikdy psa neměl. Jeden dárce vám poslal psa. Je obrovský, je v Modrém salonku a už si o Modrém salonku udělal vlastní úsudek.","c":[["Nechte si ho. Pojmenujte ho po sobě. Přidělte mu ochranku.","Pes má v průzkumech 71procentní podporu, což je 71 procent, tedy víc než vy."],["Vraťte psa. Jste alergický na závazky.","Fotka psa nakládaného do dodávky je na titulní straně nad ohybem. Je to zatím nejškodlivější snímek celého vašeho prezidentství."],["Udělte psovi federální jmenování.","Pes je potvrzen poměrem 61:39. Šest senátorů hlasuje pro, aby něco naznačili ohledně procesu. Nikdo to nepochopí."],["Jmenujte psa do vlády. Dejte mu resort.","Ministr morálky. Zúčastní se čtyř schůzí, na všech prospí, a má vyšší preference než všichni ostatní ministři dohromady."]]},"birthright":{"t":"Čtrnáctý dodatek","x":"„Chcete exekutivním nařízením zrušit občanství podle místa narození. Příslušný text má jednu větu, je v Ústavě a znamená to samé od roku 1868.“ Odloží pero. „Sepíšu, co budete chtít.“","c":[["Podepište to. Ať se s tím soudí dva roky.","Je to zablokováno do sedmdesáti dvou hodin. Ale po těch sedmdesát dva hodin to je zákon a několik nemocnic se podle toho zařídí. Ten precedent teď existuje."],["Pošlete to Kongresu jako ústavní dodatek.","Umírá to ve výboru, tam totiž končí dodatky, když chce někdo jen předvést, že se o něco snažil."],["Nepodepisujte. Místo toho nařiďte úřadům, ať s dokumentací zdržují.","Žádné nařízení, žádná žaloba, žádný titulek. Jen fronta, která se nikdy nehne. Funguje to lépe a nikdo to nemůže vyfotit."],["Podepište to voskovkou, aby se dalo později tvrdit, že to nebylo myšleno vážně.","Obhajoba voskovkou zazní i při ústním jednání. Předsedkyně Nejvyššího soudu se ptá, zda prezident zamýšlel, aby bylo nařízení závazné. Váš právník odpoví: „částečně“."]]},"tranquility":{"t":"Centrum klidu","x":"Panama vám nabídla prostory ve věznici, kterou popisuje jako „megazařízení pro protiteroristické zadržování“. Duane chce použít válečný zákon z roku 1798 a lidi tam letecky přepravovat bez individuálních slyšení. „Nikdy nebyl zrušen, pane.“","c":[["Naplňte letadla. Dnes večer.","Soudce nařídí letadla otočit. Už jsou nad mořem. Nikdo je neotočí. Byla překročena hranice a ukázalo se, že byla z papíru."],["Použijte to, ale nejdřív každému dejte pětiminutové slyšení.","Pět minut stačí na zjištění jména. Na cokoliv jiného ne. A přesně tak to bylo zamýšlené."],["To je moc. Deportujte přes běžné soudy.","Běžné soudy mají čtyřletý skluz. Vaše základna to čte jako slabost, a abychom byli spravedliví, je to skluz."],["Pošlete letadla prázdná, jako test. Uvidíte, kdo si stěžuje.","Čtyři letouny letí do Panamy bez jediného pasažéra. Stojí to 9 milionů dolarů a přesně odhalí, kteří úředníci byli ochotní pomoct, což byla informace, kterou jste vlastně potřeboval."]]},"admin-error":{"t":"Administrativní chyba","x":"„Poslali jsme do Centra klidu muže, kterého chránilo platné soudní rozhodnutí. O tom není sporu. V podání jsme to označili za administrativní chybu. Nejvyšší soud nám jednomyslně nařídil, abychom usnadnili jeho návrat.“","c":[["„Usnadnit“ je velké slovo. Usnadňujte to velmi pomalu.","Měsíce slyšení o významu jednoho slovesa. Nakonec se vrátí. Precedent, že „nakonec“ je přijatelná odpověď Nejvyššímu soudu, se ale nikam nevrací."],["Přepravte ho domů ještě tento týden. Omluvte se písemně.","Právní stát ten týden přežije. Tři televizní moderátoři vás popíší jako zlomeného. Obojí hodnocení je správné."],["Argumentujte, že žádný soud nemůže prezidentovi nařídit, co má dělat v zahraničí.","Jedna soudkyně napíše v odlišném stanovisku, že podle vaší teorie by vláda mohla bez následků deportovat kohokoli, i občany. Vaši právníci odmítnou říct, že se mýlí."],["Sveďte to na stážistu, který neexistuje. Dejte mu jméno.","„Kevin“ je citován v devíti podáních během dvou let. Novinář nakonec zjistí, že Kevin nemá žádnou personální složku, žádný odznak ani rodný list."]]},"liberation-tariffs":{"t":"Den osvobození","x":"Lyle má tři grafy. „Univerzální cla na úplně všechny, včetně dvou neobydlených ostrovů obývaných výhradně tučňáky. Zákon, který byste použil, nikdy nikdo takhle nevykládal. Trhy s tím nepočítají, protože to nikdo nepovažoval za možné.“","c":[["Všechno. Oznamte to v Růžové zahradě s obřím posterem.","Šest bilionů dolarů se vypaří za čtyři dny. Označíte to za „nezbytně nutný zákrok“, což je přesně to, co chirurgové říkají, než se věci pokazí."],["Uvalte clo na jednoho soupeře. Ostatní jen vyhrožujte.","Hrozba udělá víc práce než samotné clo. Deborah si to poznamená, uloží a nikdy vám na to nezapomene připomenout."],["Zrušte to. Ať za únik informací nese vinu Lyle.","Lyle je do hodiny v televizi a vysvětluje, že špatně pochopil vlastní grafy. Dělá to dobře. Už to zažil."],["Uvalte clo jen na tučňáčí ostrovy. Nic jiného.","Desetiprocentní clo na vývoz z neobydleného území. Nic to nestojí, nikomu to neškodí, a ekonomické přednášky to třicet let citují jako nejracionálnější obchodní politiku své doby."]]},"market-crash":{"t":"Číslo šlo dolů","x":"Trh je za týden dole o 12 procent, nejhůř od pandemie. Volali čtyři dárci. Jeden z nich plakal. Lyle drží vytištěný list papíru, který pořád otáčí, jako by na druhé straně bylo něco jiného.","c":[["Pozastavte to na 90 dní. Označte to za strategickou pauzu, kterou jste vždy plánoval.","Trh během odpoledne vystřelí o 9 procent nahoru. Několik lidí, kteří o pauze věděli o čtyřicet minut dřív, je teď podstatně bohatších."],["Držte linii. „Tohle je lék.“","Penzijní účty po celé zemi utrpí ránu. Vaše preference u lidí nad 60 let dělají něco, co průzkumníci popisují jako „propast“."],["Pozastavte cla a osobně nakupte na propadu.","Vaše jmění vzroste o částku, kterou by se dal financovat středně velký federální úřad. Dva etické úřady zahájí šetření. Ani jeden nemá rozpočet."],["Zavřete trh. Jen na chvíli. Než se to uklidní.","Trh zavřít nemůžete. Postupně vám to vysvětlí čtyři lidé, každý výše postavený než ten předchozí."]]},"prez-coin":{"t":"$PREZ","x":"Sy má prezentaci. „Memecoin. Vaše tvář. Spuštěný tři dny před inaugurací. Z každé transakce jde procento vám. Právně je to sběratelský předmět, což znamená, že to právně není vůbec nic.“","c":[["Spusťte to. Večeře pro 220 největších držitelů.","Vyšplhá se to na hodnotu 15 miliard dolarů a pak spadne o 97 procent. Na vydání jste stejně vydělal. Někdo v Ohiu ne."],["Spusťte to. Bez večeře. Nic, co by vypadalo jako přístup k moci.","Absenci večeře si pochvalně všimne přesně jeden komentátor a nikdo jiný na světě."],["Zrušte to. Prezidentský úřad není obchod.","Sy na vás zírá. „Pane. Se vší úctou. Je to naprosto obchod.“ Nemá sice pravdu, ale jen protože je moc brzy."],["Spusťte druhý coin, který spekuluje proti tomu prvnímu.","Jste na obou stranách obchodu. Není to nelegální, protože žádný zákon nepočítal s tím, že by tohle dělal prezident. Vyděláte 700 milionů dolarů a dva regulátoři rezignují."]]},"qadira-jet":{"t":"Dar","x":"Katarský sultanát by vám rád daroval letoun za 400 milionů dolarů k použití jako Air Force One. Muriel pečlivě volí slova. „Pane, klauzule o odměnách je docela krátká. To je na ní ten problém. Těžko se dá vyložit špatně.“","c":[["Přijměte to. Po odchodu z úřadu to věnujte své budoucí knihovně.","Přestavba stojí daňové poplatníky víc než nové letadlo. Ve všech dokumentech je to popsáno jako dar. Nikdo pořádně neumí vysvětlit komu."],["Zdvořile odmítněte. Místo toho si vezměte velmi výhodnou obchodní dohodu.","Dostanete peníze bez fotky. Takhle vypadá kompetentní korupce a je to hluboce neuspokojivé."],["Přijměte to a veřejně tvrďte, že to bylo nevyžádané.","O čtyři týdny později se objeví zpráva, že si o to nejdřív řekl váš vlastní úřad. Slovo „nevyžádané“ přibývá na rostoucí seznam slov, která jste osobně vyřadil z oběhu."],["Přijměte to a rovnou to věnujte charitě pro dětskou nemocnici.","Stane se z toho létající nemocnice. Katar je nadšený, problém s odměnami se vypaří a nikdo vás za to nemůže napadnout z žádné strany."]]},"yardvard":{"t":"Yardvard","x":"„Yardvard má nadační fond větší než šedesát zemí a 2,2 miliardy dolarů ve federálních grantech. Poslali jsme jim seznam požadavků ohledně náboru, přijímacího řízení a toho, co smí zaznít v seminární místnosti. Odmítli.“","c":[["Zmrazte těch 2,2 miliardy. Ještě dnes.","Soudce o pět měsíců později rozhodne, že to bylo protiprávní. Za těch pět měsíců jedenáct dalších univerzit potichu vyhoví, aniž by je někdo žádal. A o to celé šlo."],["Zmrazte peníze menší škole, jako varovný výstřel.","Colonnade se do devíti dnů podvolí. Yardvard si toho všimne. Všichni si toho všimnou. Nikdo nemusel psát žádný oběžník."],["Vyjednávejte. Vezměte si společné prohlášení o „názorové rozmanitosti“.","Vznikne výbor. Zprávu podá v roce 2031. Ten výbor je ten ústupek."],["Zapište se. Absolvujte jeden předmět. Sledujte je zevnitř.","Čtyřikrát se zúčastníte pokročilého semináře o výkladu ústavy. Přepis vašich otázek vyjde v roce 2041 a je skutečně zajímavý."]]},"law-firms":{"t":"Perkins & Coy","x":"„Exekutivní nařízení, které advokátním kancelářím zastupujícím vaše odpůrce odebere bezpečnostní prověrky, federální zakázky a přístup do budov. Pane, jsou to právníci. Celá jejich profese spočívá v žalování lidí, kteří tohle dělají.“","c":[["Podepište nařízení proti všem třem kancelářím.","Jedna kancelář zažaluje a jednoznačně vyhraje. Čtyři další, aniž by je někdo žádal, přislíbí dohromady 600 milionů dolarů bezplatné právní práce na věci, které máte rád. Ty, co bojovaly, nejsou to hlavní téma."],["Jen jedna kancelář. Ta nejhlasitější.","Vzkaz dorazí ke všem advokátům přibližně za devadesát minut. Levnější než tři nařízení a stejně účinné."],["Nedělejte to. Místo toho si najměte lepší právníky.","Sy si potichu ztrojnásobí vlastní honorář a přitom vážně přikyvuje nad tématem právního státu."],["Najměte si všechny tři kanceláře sám. Vyřaďte je kvůli střetu zájmů.","Kancelář, kterou si najmete, pak nesmí jednat proti vám. Tři smlouvy, 40 milionů dolarů, a vaši odpůrci přijdou o právníky bez jediného exekutivního nařízení."]]},"kennedy-center":{"t":"Umění","x":"„Správní rada národního centra scénických umění slouží podle vaší vůle. Mohl byste ji odvolat a jmenovat se předsedou sám.“ Zaváhá. „Dosud jste o scénická umění nikdy neprojevil zájem.“","c":[["Odvolejte radu. Předsedou jste teď vy. Přejmenujte budovu.","Dva uznávaní skladatelé na protest rezignují. Prodej vstupenek klesne o 40 procent. Ve foyer teď visí váš portrét, na kterém se díváte kamsi doleva."],["Nahraďte polovinu rady dárci. Sami se nikde neuvádějte.","Budova uvádí přesně to, co byste naprogramoval sám, a přitom jste nemusel navštívit jedinou operu."],["Umění nechte být. O baletu nikdo nehlasuje.","Vzácný, nikým nevynucený akt zdrženlivosti. Všimne si ho 400 lidí a všichni vás už předtím neměli rádi."],["Zařaďte do programu jedno představení. Muzikál. O vás.","Hraje se jedenáct týdnů při 34procentní návštěvnosti a dostane jednu pozitivní recenzi, kterou si necháte zarámovat a kterou její autor deset let popírá, že napsal."]]},"chirpgate":{"t":"Chirpgate","x":"Váš bezpečnostní tým plánoval živý vojenský úder ve skupinovém chatu na běžné komunikační aplikaci. Omylem do něj přidali šéfredaktora celostátního magazínu. Má časový harmonogram. Měl ho dřív než piloti.","c":[["„Nikdo neposílal válečné plány.“ Nikoho nevyhoďte.","Magazín zveřejní snímky obrazovky. Obsahují slova „válečné plány“. Nikdo není vyhozen. To je skutečné ponaučení z celé kauzy."],["Vyhoďte ministra obrany. Veřejně. Okamžitě.","Odpovědnost. Zní to v ústech divně, jako cizí slovo."],["Vyšetřete únik. Ne chat. Únik.","Tři kariérní úředníci, kteří v chatu vůbec nebyli, jsou postaveni mimo službu. Lidé, kteří v chatu byli, jsou povýšeni. Celá vláda teď chápe, jak systém odměn funguje."],["Přidejte do chatu celý tiskový sbor. Radikální transparentnost.","Nikdo nemůže vynést chat, ve kterém už je. Čtyři plánované operace jsou zrušeny a problém s úniky je natrvalo vyřešen."]]},"shutdown":{"t":"Odstávka","x":"Hal Grimes má většinu o dvou křeslech a jedenáct poslanců, kteří považují vládnutí za formu kapitulace. Vláda se za 40 hodin zastaví. „Pane, dokážu prosadit cokoliv, pokud to je vlastně nic.“","c":[["Zastavte to. Denně vinu svalujte na opozici.","Řídící letového provozu pracují 34 dní bez výplaty. Dvě letiště přestanou fungovat ve stejný pátek a odstávka skončí ještě do večeře."],["Ustupte. Podepište čistý návrh zákona.","Chvilkové vládnutí. Vaše základna použije slovo „zrada“ do půlnoci 400 000krát."],["Zastavte to a stejně utraťte schválené peníze.","Zjistil jste, že jedinou skutečnou mocí Kongresu je rozpočet, a že rozpočet je jen budova plná lidí, kteří vám zvednou telefon, když zavoláte."],["Udržte to v chodu tím, že federálním zaměstnancům zaplatíte z vlastní kapsy.","Stojí vás to 1,2 miliardy dolarů a jedenáct dní. Je to protiústavní zhruba čtyřmi různými způsoby a žádný soud nedokáže přijít na to, kdo by měl právo si na to stěžovat."]]},"impoundment":{"t":"Peníze schválené Kongresem","x":"„Kongres schválil 9 miliard dolarů na věci, které se vám nelíbí. Zákon o kontrole zadržování prostředků říká, že je musíte utratit. Zákon má sankční ustanovení. Přečetl jsem si ho jedenáctkrát. Žádnou sankci neobsahuje.“","c":[["Neutraťte ani cent. Ať vás klidně zažalují.","Soudní spor trvá 26 měsíců. Peníze propadnou na konci fiskálního roku za 7. Objevil jste směnný kurz mezi soudními spory a kalendářem."],["Utraťte to, ale pomalu, a na nesprávné věci.","Formálně v souladu se zákonem. Funkčně identické. Nikdo nemůže žalovat kvůli „zpoždění zadávacího řízení“."],["Utraťte to přesně tak, jak bylo schváleno. Vyměňte to za něco většího.","Za to dostanete jmenování soudce. Hal to nazve výhrou. Hal nazve výhrou úplně všechno."],["Utraťte všech devět miliard na jednu věc. Velmi velkou věc.","Devět miliard dolarů do jednoho mostu. Je dokončen dřív, než se čekalo, je nádherný a slouží městečku se čtyřmi tisíci obyvateli."]]},"vp-smiles":{"t":"Chet se usmívá","x":"Chet Danforth pronesl projev o „hnutí, které je větší než kterýkoli jednotlivec“. Vaše jméno zmínil jednou, v devatenácté minutě. Teď stojí ve vaší kanceláři a ptá se, jestli se vám to líbilo.","c":[["„Miloval jsem to. Jdi udělat dalších čtyřicet.“","Základna roste. Roste kolem něj. Právě jste zalil rostlinu, která vám jednou zastíní světlo."],["Mírně ho ponižte před novináři.","Přijme to s úsměvem, který mu vůbec nedosáhne do očí. Zapamatuje si to. Je to člověk, který si vede seznam."],["Pošlete ho do zahraničí. Někam s mizerným signálem.","Šest týdnů v regionu bez pokrytí domácími televizemi. Vrátí se opálený, tichý a nějak nebezpečnější."],["Pochvalte projev. Pak ho nechte v hlavním vysílacím čase číst telefonní seznam.","Čtyřicet minut Cheta Danfortha, jak s úsměvem bezchybně čte jména v abecedním pořadí. A jeho preference to nějak zvedne."]]},"broom-divorce":{"t":"Rozvod","x":"Roscoe Vandermeer zveřejnil vlákno o 4000 slovech, ve kterém popisuje váš vlajkový zákon jako „odpornou ohavnost“. Je největším dárcem v zemi a nikdy nespí.","c":[["Zrušte mu federální zakázky, živě v televizi.","Jeho firmy vynášejí do vesmíru americké astronauty a provozují polovinu federálního cloudu. Zrušit ho je jako zrušit gravitaci: na papíře možné, v praxi trapné."],["Zavolejte mu. Polichoťte mu. Dejte mu nějakou vesmírnou hračku.","Jeden telefonát a příležitost dát něčemu jméno. Vlákno je smazáno. Místo toho zveřejní fotku rakety."],["Neříkejte nic. Nechte ho, ať sám vyhoří.","Z nudy zafinancuje tři vyzyvatele v primárkách. Dva z nich vyhrají. Sám nevyhoří ani v jednu chvíli."],["Vyzvěte ho na souboj v kleci. Veřejně. S konkrétním datem.","Je to oznámeno, propagováno a nikdy se to nekoná. Vzbudí to větší pozornost než jakákoliv politika za celé volební období a oba dva přesně víte, proč jste to udělali."]]},"blackwood":{"t":"Spisy Blackwood","x":"Vašemu hnutí bylo roky slibováno zveřejnění spisu. Bo si spis teď prošel. „Žádný seznam tam není, pane. Nikdy žádný nebyl. Říct jim to bude nejhorší týden mého života.“","c":[["Zveřejněte všechno. Ať to dopadne, jak to dopadne.","Obsahuje tři trapné večeře a žádné spiknutí. Vaše základna tomu nevěří, protože hnutí postavené na skrytém spisu nemůže přežít prázdný spis."],["Oznamte, že žádný spis neexistuje. Řekněte jim, ať to nechají být.","První skutečná vzpoura vašeho prezidentství přichází z vašich vlastních řad, a je hlasitější než cokoliv, co kdy dokázala opozice."],["Zveřejněte 40 procent, začerněné, v pátek večer, jako PDF fotokopie.","Předmětem zájmu se stanou začerněné pasáže, což je lepší, než kdyby se jím stal samotný spis. Bo za jeden víkend zestárne o čtyři roky."],["Zveřejněte spis. Je to čtyři sta stránek účtenek z obědů.","Opravdu jsou to jen účtenky z obědů. Tomu taky nikdo nevěří. Jedenáct let je analyzují lidé přesvědčení, že je to šifra."]]},"squad-post":{"t":"Vraťte se","x":"Čtyři opoziční kongresmanky vás zkritizovaly. Brayden připravil příspěvek, který naznačuje, že by se měly „vrátit“ do zemí, odkud pocházejí. Tři z nich se narodily v téhle. Čtvrtá je naturalizovaná občanka.","c":[["Zveřejněte to.","Sněmovna to hlasováním odsoudí. Přidají se čtyři členové vaší vlastní strany. Na dalším mítinku dav vymyslí pokřik a vy ho necháte třináct vteřin běžet, aniž byste ho přerušil."],["Místo toho útočte na jejich politiku. Nemilosrdně, ale věcně.","Účinné, zapomenutelné a do čtvrtka je po všem."],["Zveřejněte to, pak popřete, že to znamenalo to, co to jasně znamenalo.","Mistrovská ukázka, jak něco říct a zase odvolat, zatímco to ještě visí ve vzduchu. To popření není pro kritiky. Je pro lidi, kteří potřebují svolení, aby vás mohli dál podporovat."],["Zveřejněte fotku sebe se všemi čtyřmi, jak se usmíváte.","Je z roku 2011 a všichni na ní vypadají nadšeně. Zneškodní to kauzu a rozzuří to naprosto všechny, což je svým způsobem úspěch."]]},"anthem":{"t":"Klečení","x":"Sportovci klečí během hymny. Nadia má čísla. „Pane, klečení má podporu 38 procent. Váš útok na klečení má podporu 41 procent. Ale spotřebuje to celý měsíc pozornosti.“","c":[["„Toho parchanta dostaňte z hřiště pryč.“ Řekněte to na mítinku.","Do neděle je do toho vtažena celá liga, sponzoři i televize. Dokázal jste, že dokážete určovat agendu celé země z pódia na venkovském jarmarku."],["Řekněte, že sportovci mají mít svobodu protestovat a stejně tak svobodu být kritizováni.","Opravdu obhajitelný postoj, jasně vyjádřený, a doslova všichni na něj do dne zapomenou."],["Podmiňte federální dotace na stadiony chováním při hymně.","Proměnil jste kulturní válku v podmínku financování. To je ten tah. Všechno další je jen výběr dalšího rukojmího."],["Poklekněte si sám. Řekněte, že je to za vojáky.","Pokleknete na stadionu a uvedete důvod, se kterým nikdo nemůže polemizovat. Čtyři komentátoři mají viditelné potíže o tom vůbec cokoli říct."]]},"glacia":{"t":"Írán","x":"„Požádal jste mě, abych spočítala cenu za získání Íránu. Je to autonomní území Northmarku. Žije tam 56 000 obyvatel, všichni jsou to lidé, s vlastními názory a hlasovacím právem.“","c":[["Nabídněte, že to koupíte. Veřejně. S konkrétní částkou.","Premiérka Northmarku označí ten nápad za „absurdní“. Vy ji nazvete „protivnou“ a zrušíte státní návštěvu. Vztahy se spojencem v NATO teď visí na jednom přídavném jméně."],["Odmítněte vyloučit použití síly.","Každý spojenec v alianci si potichu začne počítat, jak by vypadala budoucnost bez vás. Osm let na tom nezáleží, a pak na tom náhle záleží obrovsky."],["Nechte to být. Místo toho podepište dohodu o nerostných surovinách.","Dostanete většinu z toho, co jste skutečně chtěl, tedy suroviny, a nic z toho, co jste chtěl emocionálně, tedy mapu."],["Nabídněte za to výměnou jeden ze států. Jmenujte který.","Northmark odmítne. Jmenovaný stát se cítí hluboce uražen a jeho dva senátoři se na čtyři roky stanou trvalou překážkou všeho, co chcete."]]},"fifty-first":{"t":"Padesátý první stát","x":"Začal jste kanadskému premiérovi říkat „guvernér“. Prohlásil jste, že byste na anexi země použil „hospodářskou sílu“. Kanada teď na hokejových zápasech bučí na vaší hymnu.","c":[["Pokračujte v oslovování „guvernér“. Je to zadarmo.","Národ o 40 milionech lidí si za deset týdnů vytvoří jednotnou národní identitu, z velké části postavenou na odporu vůči vám. Jejich turistika do vaší země klesne o 38 procent."],["Uvalte na ně cla, dokud sami nepožádají o připojení.","Zvolí drtivou většinou toho jediného politika, který sliboval, že se vám postaví, přestože ještě nedávno zaostával o 20 bodů. Jste nejúčinnější kampaňový manažer desetiletí, pro druhou stranu."],["Omluvte se. Tak trochu. Nepřímo.","Řeknete „mám ke Kanadě velkou úctu“ tónem, který naznačuje, že to čtete z kartičky, což čtete."],["Místo toho podejte žádost o připojení ke Kanadě.","Formální žádost je odeslána jako vtip. Jejich parlament o ní devadesát minut vážně debatuje a přepis jednání je mistrovské dílo."]]},"riviera":{"t":"Plán Riviéra","x":"Navrhl jste, aby Spojené státy „převzaly“ válkou zničené území a přebudovaly ho na koridor luxusních letovisek. Muriel přinesla vytištěný návrh. Je tam vizualizace. Někdo tu vizualizaci skutečně vytvořil.","c":[["Oznamte to z pódia. Ukažte vizualizaci.","Do šesti hodin to odsoudí každá vláda v regionu. Vizualizace s vyhlídkovým bazénem je teď natrvalo spojená s odkazem vaší zahraniční politiky."],["Vypusťte to jako „koncept“ přes přátelské médium.","Popiratelné, testovatelné, a posune to hranici toho, co lze říct nahlas, přesně o jeden stupínek. K tomu zkušební balonek vlastně slouží."],["Zrušte to. Podpořte místo toho nudný mnohostranný plán.","Možná to i bude fungovat, což znamená, že to bude trvat jedenáct let a nikdo si k tomu nepřipojí vaše jméno."],["Postavte letovisko. Na federálních pozemcích. V Nevadě.","Všechna ta ambice, žádné válečné zločiny. Otevře se za šest let, vede se mu dobře a je to vůbec nejméně kontroverzní věc, na které je vaše jméno."]]},"oval-ambush":{"t":"Schůzka","x":"Ukrajinský prezident stojí v Oválné pracovně před čtyřiceti kamerami. Právě zdvořile odmítl podruhé vám poděkovat. Chet už se naklání dopředu ve svém křesle.","c":[["Seřvěte ho. Před kamerou. „Hrajete si s třetí světovou válkou.“","Odejde bez oběda. Devět evropských lídrů zveřejní během hodiny prakticky identická prohlášení, což se ještě nikdy nestalo."],["Přesuňte se do soukromé místnosti. Křičte tam místo toho.","Dohoda je podepsána. Nikdo nemá záznam. Chet je viditelně zklamaný, že žádný záznam neexistuje."],["Bohatě ho pochvalte, pak potichu zastavte pomoc.","Nejvřelejší tisková konference celého vašeho funkčního období, po ní následuje položka, která zmizí ve čtvrtečním schvalování rozpočtu. Takhle se to opravdu dělá."],["Dejte mu své křeslo. Posaďte se na to malé.","Fotka amerického prezidenta v hostovském křesle. Čtyři evropská ministerstva zahraničí si vyžádají kopie. Vykoupí vám to deset let dobré vůle."]]},"dictator-joke":{"t":"Jen první den","x":"Moderátor se vás přímo zeptá, jestli hodláte být diktátorem. Existuje způsob, jak na to odpovědět tak, aby to téma skončilo. A existuje i způsob, jak na to odpovědět tak, aby neskončilo.","c":[["„Ne. Kromě prvního dne.“ Zasmějte se. Jděte dál.","Ten vtip funguje zároveň jako vtip i jako zkušební balonek. Než všichni přestanou hádat se, jestli to byl vtip, ten „první den“ už trvá čtrnáct měsíců."],["„Naprosto ne.“ Strohé. Bez úsměvu.","Čisté popření. Ten záznam proti vám později použijí lidé z vašeho vlastního tábora, kteří to brali jako slib."],["„Definujte diktátora.“","Čtyři sta komentářů se pokusí definovat diktátora. Zatímco se o to snaží, vy překlasifikujete dalších devět tisíc federálních zaměstnanců."],["„Byl bych hrozný diktátor. Ani lidi nedokážu propustit.“","Je to sebeironické, zjevně nepravdivé a naprosto odzbrojující. Tři připravené doplňující otázky jsou opuštěny."]]},"weaponization":{"t":"Konec zneužívání","x":"„Exekutivní nařízení nazvané Konec zneužívání federální vlády. Jeho skutečným účinkem je nasměrovat federální vládu na seznam jmen. Ten název odvádí obrovský kus práce, pane.“","c":[["Podepište to. Začněte tím seznamem.","Ve třech obvodech jsou svolány velké poroty. Dva žalobci raději rezignují, než by podepsali obžaloby. Dva to neudělají, a přesně ty dva bylo potřeba."],["Podepište to, ale vyšetřujte jen instituce. Ne jednotlivce.","Instituce mají compliance oddělení a žádnou kapacitu na rozhořčení. Podvolí se rychleji než lidé."],["Nepodepisujte. Řekněte, že jste „příliš zaneprázdněný vítězením“.","Vaše základna chtěla odplatu a dostala heslo. Hesla mají svou trvanlivost a téhle už prošla."],["Podepište to a nejdřív důkladně vyšetřete sám sebe.","Devítiměsíční šetření vlastního jednání, vedené vašimi vlastními lidmi, které vás očistí. Je transparentně zbytečné a vaši zastánci ho citují celé roky."]]},"guard-portland":{"t":"Vojáci v Portsmouthu","x":"Generál Tarrant stojí velmi zpříma. „Chcete zfederalizovat 400 příslušníků Národní gardy a poslat je do amerického města proti vůli jeho guvernéra. Pane, uposlechnu zákonný rozkaz. Žádám vás, abyste ho udělal zákonným.“","c":[["Nasaďte je. Vyhlaste kvůli tomu nouzový stav kvůli kriminalitě.","Obrněná vozidla na ulici s farmářskými trhy. Soudce to za jedenáct dní zablokuje, ale ten obraz už existuje navždy a příští nasazení bude jednodušší."],["Místo toho pošlete federální maršály. Menší. Tišší.","Žádné tanky, žádné fotky, stejní ozbrojení muži. Zjišťujete, že jediné, proti čemu má kdokoli námitky, je uniforma."],["Ustupte. Guvernérovi místo toho nabídněte federální peníze.","Nepokoje samy odezní za tři týdny, jak to tak bývá. Nikdo vám to nepřipíše k dobru, protože se nic nestalo, a to, že se nic nestalo, není žádná zpráva."],["Jeďte tam sám. Bez ochranky. Hodinu se tam procházejte.","Promluvíte si se zhruba čtyřiceti lidmi, několik z nich vás nesnáší, nikdo z nich to nečekal. Nepokoje skončí za devět dní z důvodů, které nikdo pořádně neumí vysvětlit."]]},"posse":{"t":"Rychlá zásahová jednotka","x":"„Žádáte o stálou celostátní jednotku rychlé reakce. Domácí. Podřízenou vám. Existuje o tom zákon z roku 1878. Je to jediná věc, kterou každý důstojník v téhle budově umí citovat zpaměti.“","c":[["Založte ji. Nazvěte ji „prvkem občanské podpory“.","Teď máte vojáky, jejichž nasazení nevyžaduje žádného guvernéra, žádný soud ani žádné hlasování. Je to největší přesun moci za celé vaše prezidentství a byl oznámen v poznámce pod čarou."],["Založte ji jen na papíře. Bez přidělených vojáků.","Pravomoc existuje. Jednotka ne. Pravomoci, které existují, mají svůj způsob, jak si najít jednotku."],["Odmítněte. Některé dveře se prostě neotevírají.","Tarrant udělá něco, co jste u generála ještě neviděl. Vydechne."],["Místo toho ji založte pro přírodní katastrofy.","Jedenáct tisíc lidí, kteří dorazí do šesti hodin od zásahu hurikánu. Za dva roky to podle odhadů zachrání čtyři sta životů a nikdo tomu nikdy neřekne autoritářství."]]},"vermin":{"t":"To slovo","x":"Brayden napsal řečnickou pasáž, ve které popisuje vaše odpůrce jako „havěť žijící uvnitř hranic naší země“. Dva historici už preventivně napsali komentáře o posledních dvou mužích, kteří to slovo použili.","c":[["Řekněte to. Dvakrát. Pomalu.","To srovnání se objeví na každé titulní straně. Váš tým na to reaguje tvrzením, že životy kritiků „budou rozdrceny“, což situaci nezlepší a ani to nemělo být záměrem."],["Řekněte místo toho „radikálové“. Stejná energie, méně historiků.","Získáte 90 procent účinku a žádné archivní záběry. Deborah tomu říká „výprodej“."],["Tu pasáž vyškrtněte. Mluvte o potravinách.","Cena vajec je politicky nejsilnější téma v celé zemi a k smrti vás nudí."],["Přednete tu pasáž, ale o vosách. Jenom o vosách.","Jedenáct minut skutečného, stupňujícího se zuření o vosách. Je to nejoblíbenější projev celého vašeho prezidentství a entomologové na něj napíšou čtyři reakce."]]},"health-advice":{"t":"Lékařská rada","x":"Stojíte za pódiem vedle skutečných vědců. Chystáte se improvizovat o běžném léku a jedné dětské nemoci. Admirál Prine má výraz ve tváři, pro který zatím neexistuje název.","c":[["Řekněte to. Máte na to pocit.","Volání do toxikologického centra vzroste za týden o 21 procent. Dvě lékařské asociace vydají prohlášení. Vaše základna to vnímá jako odvahu."],["Přečtěte připravený text. Slovo od slova.","Nejnudnějších jedenáct minut celého vašeho prezidentství a objektivně nejužitečnějších."],["Řekněte to, pak řekněte, že to byl sarkasmus.","Obrana sarkasmem se používá tak často, že už to není obrana, ale žánr."],["Nechte to na vědcích. Nahlas. Jmenovitě.","V živém vysílání řeknete „zeptejte se jí, ví toho víc než já“. Ten záznam se deset let přehrává lidem, kteří tvrdí, že jste to celou dobu uměl."]]},"antifa-designation":{"t":"Označení","x":"„Chcete decentralizované protestní hnutí označit za domácí teroristickou organizaci. Pane, nemá to žádné vůdce, žádné členy ani bankovní účet. Označit to znamená označit přídavné jméno.“","c":[["Označte to. Pak vyšetřujte každého, koho lze tím přídavným jménem popsat.","Protože ta kategorie není definovaná, je nekonečná. Dvanáct neziskovek přijde do měsíce o bankovní služby. Nikdo nemusel o žádné z nich nic dokazovat."],["Označte to symbolicky. Žádné vodítko pro vymáhání.","Tiskové prohlášení, kolem kterého visí síla zákona jako pach. Vodítko pro vymáhání se dá vždycky vydat později."],["Nedělejte to. Stíhejte skutečné zločiny se skutečnými důkazy.","Bo Slaughter na chvíli vypadá jako člověk, který na právech studoval z nějakého důvodu."],["Označte přídavné jméno. Jakékoliv. Uvidíte, jestli vás někdo zastaví.","Označíte „nekázeň“. Nařízení je zveřejněno ve Federálním registru. Čtyři úřady žádají o vysvětlení a žádný ho nedostane."]]},"six-three":{"t":"Šest ku třem","x":"Předsedkyně Nejvyššího soudu si vyžádala zdvořilostní hovor. Volá vám oznámit, že soud poměrem šest ku třem zrušil vaše vlajkové ekonomické nařízení a že dva ze tří soudců, které jste jmenoval, byli mezi většinou.","c":[["Zaútočte na soud jmenovitě. Žádejte impeachmenty.","Předsedkyně soudu vydá vzácné veřejné prohlášení. Vaše základna se dozví, že i soud je nepřítel, čímž se seznam nepřátel rozšíří na úplně každou instituci v zemi."],["Uposlechněte, pochvalte soud a vydejte tu politiku znovu podle jiného zákona.","Prohrál jste soudní spor a přesto si udržel politiku. Takhle vypadá, když někdo skutečně rozumí tomu, jak stroj funguje."],["Uposlechněte úplně. Řekněte, že systém funguje.","Chválí vás lidé, kteří vás nikdy nevolí, v médiích, která vaši voliči nečtou."],["Pošlete soudu košík ovoce a vzkaz „dobrý rozsudek“.","Košík je zaevidován, oceněn na 61 dolarů a podle etických pravidel odmítnut. Vzkaz odmítnut není. Prý pořád leží v zásuvce."]]},"vacancy":{"t":"Uvolněné místo","x":"Zemřel soudce. Máte 53 senátorů, užší seznam a poprvé skutečnou volbu: brilantní právničku, která proti vám bude občas rozhodovat, nebo loajálního soudce, který nikdy.","c":[["Toho loajálního. Potvrďte za 27 dní.","Potvrzen poměrem 51:49. Napíše svůj první posudek ve váš prospěch ještě před koncem funkčního období a necituje vůbec nic. Koupil jste si třicet let."],["Tu brilantní. Budujte odkaz.","Je potvrzena poměrem 78:22 a do osmnácti měsíců proti vám rozhodne, obsáhle, zdrcujícím způsobem, tak, že se to bude učit ve školách."],["Nechte místo neobsazené. Nechte je viset rok.","Prázdné místo má větší hodnotu než obsazené. Každý senátor, který chce mít slovo, teď od vás každý týden něco potřebuje."],["Nominujte psa.","Nominace je odeslána Senátu. Ústavně-právní výbor naplánuje slyšení dřív, než si kdokoli v budově nahlas přizná, co se to vlastně děje."]]},"poll-collapse":{"t":"Zase ta čísla","x":"Nadia hlásí vaši podporu na 37 procentech. „Dobrá zpráva je, že vaše dno je 34 a nikdy se nehnulo. Špatná zpráva je, že váš strop je 46 a taky se nikdy nehnul. Pane, vy nemáte voliče. Máte kongregaci.“","c":[["Krmte kongregaci. Mítink každý týden.","Dvanáct mítinků za devět týdnů. Dno stoupne na 39 a ztvrdne v něco, co už na žádné události vůbec nereaguje."],["Otočte se ke středu. Oznamte plán zaměstnanosti.","Získáte čtyři body u lidí, kterým se nikdy nezalíbíte, a ztratíte devět u lidí, kteří by za vás umřeli. Špatný obchod."],["Přestaňte s průzkumy. Zakažte interní průzkumy. Zakažte to slovo.","Nadia je přeřazena na pozici „architektura sdělení“, práci, která neexistuje. Teď vládnete výhradně na základě hluku davu."],["Udělejte průzkum na otázku „jsou průzkumy skutečné?“ a zveřejněte jen ten.","Čtyřicet jedna procent řekne ne. Správně to citujete jako důkaz, že se průzkumům nevěří, což je opravdu neprůstřelný kruhový argument."]]},"donor-dinner":{"t":"Žádost","x":"Sy shromáždil čtyřicet lidí v soukromé místnosti. Každý napsal velmi vysoký šek. Každý by chtěl něco konkrétního, malého a technicky legálního. Má na to laminovanou kartičku.","c":[["Dejte jim úplně všechno. Přečtěte kartičku nahlas.","Jedenáct regulatorních výjimek je zavedeno oběžníkem. Stojí to zemi zhruba 30 miliard dolarů a trvalo to čtyřicet minut."],["Vezměte peníze. Nedejte jim nic.","Nemohou si veřejně stěžovat, aniž by popsali, co si vlastně koupili. Je to nejbezpečnější krádež v americkém životě."],["Tu místnost odmítněte. Vybírejte místo toho drobné příspěvky.","Vyberete stejnou částku, po dvaceti dolarech, od lidí, kteří si to nemohou dovolit, a nikomu z nich nic nedlužíte. Vlastně mrazivé."],["Vezměte peníze. Naservírujte jim fast food na stříbře.","Čtyřicet nejbohatších lidí v zemi jí hamburgery z rychlého občerstvení ze státního porcelánu. Devět z nich to upřímně označí za nejlepší večer svého života."]]},"settlement":{"t":"Vyrovnání","x":"„Zažaloval jste televizní síť o 20 miliard dolarů kvůli sestřihu. Ta žaloba je, podle mého odborného názoru, naprostý nesmysl. Nabídli 16 milionů dolarů a žádnou omluvu. Jejich mateřská společnost příští čtvrtletí potřebuje regulatorní souhlas k fúzi.“","c":[["Vezměte peníze. Poznamenejte, že fúze se pořád posuzuje.","Předvedl jste, že bezvýznamná žaloba plus čekající schválení se rovná platba. Tři další televizní sítě teď urovnávají spory, které ani nebyly podány."],["Vezměte peníze. Nic víc. Žádná souvislost s ničím.","Jejich vlastní zpravodajové to ve vlastním vysílání nazvou úplatkem. Společnost vydá prohlášení o „běžném soudním riziku“."],["Stáhněte žalobu. Vždycky to byl nesmysl.","Sy vám naúčtuje 400 000 dolarů za výsadu nikoho nežalovat."],["Podejte protižalobu na jeden dolar a omluvu od matky moderátora.","Matka, které je 84 let, místo toho poskytne rozhovor. Je zdrcující, mimořádně vtipná a stane se pravidelným hostem té stanice."]]},"fcc-license":{"t":"Licence","x":"„Vysílací regulátor zahájil šetření dotýkající se čtyř televizních sítí. Veřejně jste prohlásil, že jedna z nich by měla „přijít o licenci“. Pane, právně regulátora neřídíte. Prakticky jste ho jmenoval vy.“","c":[["Řekněte to znovu. Hlasitěji. Jmenujte tu stanici.","Žádná licence se nikdy neodebere. Čtyři televizní sítě potichu změní svou dramaturgii nočního vysílání. Nebyl porušen žádný zákon a výsledek je stejný, jako by byl."],["Veřejně neříkejte nic. Ať zavolá předseda úřadu.","Žádný záznam, žádný citát, žádná kauza. Pořad je zrušen z „programových důvodů“. Přesně tahle verze funguje."],["Veřejně prohlaste, že byste do udělování licencí nikdy nezasahoval.","Věta, na kterou se dá navždy odkazovat. Nic nestojí a kupuje překvapivě velký manévrovací prostor."],["Sám si zažádejte o vysílací licenci.","Žádost je podána a je, trapně pro všechny zúčastněné, naprosto platná. Šest let leží ve frontě vedle žádostí od církevních rozhlasových stanic."]]},"general-strike":{"t":"Neovladatelní","x":"Tři města přestala fungovat. Zaměstnanci dopravy, učitelé a přístavní posádky se poprvé za devadesát let zkoordinovali. Duane má dvě složky. Jednu z nich drží mnohem pevněji.","c":[["Rozbijte to. Uplatněte nouzové pracovněprávní pravomoci.","Přístavy se za jedenáct dní znovu otevřou pod federálním dohledem. Něco ve vztahu mezi zemí a její vlastní vládou se natrvalo přenastavilo, a obě strany to vědí."],["Vyjednávejte. Dejte jim většinu toho, co chtějí.","Skončí to za týden a stojí to 40 miliard dolarů. Vaše základna tomu říká kapitulace. Vlaky jezdí."],["Nedělejte nic. Veřejně. Hlasitě. Nechte to samo dohořet.","Za pět týdnů to samo vyhasne, poté co díky vyčerpání dosáhne většiny svých požadavků. Konec si přičtete k dobru."],["Přidejte se ke stávkující frontě. Přineste kávu.","Prezident Spojených států rozdává kávu u brány přístavu. Na tohle nemá nikdo scénář. Stávka skončí za čtyři dny a nikdo se neshodne, kdo vlastně vyhrál."]]},"parade":{"t":"Přehlídka","x":"„Chcete tanky na hlavní třídě. Tanky na hlavní třídě vám dokážu zajistit. Jen podotýkám, že ta třída nebyla stavěná pro tanky a tanky z ní odstraní zhruba za 21 milionů dolarů povrchu.“","c":[["Udělejte to. Přelet letadel. Všechno. Postavte mě na tribunu.","Vysílá se to živě. Fotka, na které salutujete vlastní armádě ve svých vlastních narozeninách, se stává navěky standardní ilustrační fotkou u každého článku o vás, po celém světě."],["Udělejte to bez tanků. Jen kapely a přelety letadel.","Veselé, levné, a nevznikne z toho jediná znepokojivá fotka. Promarněná příležitost, dalo by se říct."],["Zrušte to. Peníze místo toho věnujte veteránům.","Peníze se dostanou ke skutečným veteránům. Nikdo to nefilmuje. Je to nejlepší věc, kterou celý rok uděláte."],["Uspořádejte to, ale jen s pochodovými kapelami. Se všemi.","Čtyři sta středoškolských kapel ze všech států, šest hodin, žádná obrněná technika. Je to obrovské, radostné a nedá se to s ničím zlověstným srovnat."]]},"currency":{"t":"Měna","x":"„Existuje zákon zakazující portrét žijící osoby na americké měně. Platí od roku 1866.“ Polkne. „Je to zákon. Ne ústava.“","c":[["Zrušte ho. Dejte mě na stodolarovku.","Projde to poměrem 218:215 při čtvrtečním nočním hlasování připojeném k zákonu o dálnicích. Teď existuje verze americké měny s vaší tváří a už se to nevrátí zpátky."],["Místo toho pamětní mince. Bez oběhu.","Prodáte jich 4 miliony po 100 dolarech. Finančně je to nejlepší rozhodnutí celého vašeho prezidentství."],["Nechte peníze na pokoji.","Lyle si poprvé za devět měsíců pořádně vydechne."],["Dejte na stodolarovku psa.","Projde to poměrem 397:38. Bankovka se do tří let stane nejpadělanější na světě, protože ji chce mít každý."]]},"loyalty-oath":{"t":"Přísaha","x":"„Nový nástupní dotazník pro každého federálního zaměstnance. Čtyři otázky. Dvě z nich se týkají posledních voleb. Pane, tohle je ta věc. Všechno ostatní se dalo vrátit zpět. Tohle mění, z čeho se vláda vůbec skládá.“","c":[["Zaveďte to. Každý úřad. Každý nástup.","Do roka tvoří federální pracovní sílu 400 000 lidí, kteří na dvě otázky odpověděli správně. Není žádné nařízení, které by se dalo zrušit. Existuje jen personál."],["Jen politicky jmenovaní. Ne kariérní úředníci.","Čtyři tisíce lidí místo čtyř set tisíc. Čtyři tisíce, jak se ukáže, stačí bohatě."],["Zrušte to. Tohle je hranice.","Deborah beze slova vezme složku zpátky. Už ji nikdy nepřinese. Na tuhle chvíli budete ještě dlouho vzpomínat."],["Udělejte z dotazníku otázky o pizze.","Čtyři otázky, všechny o pizze. Právně naprosto v pořádku, nikoho to neprofiluje, a do roka si personalisté potichu vyvodí, jakou odpověď preferujete."]]},"state-broadcast":{"t":"Vysílání lidu","x":"„Vykuchali jsme mezinárodní vysílatele i veřejnoprávní síť. Zbylo tam kmitočtové spektrum, personál i distribuční smlouva. Mohli bychom prostě... vytvořit vlastní. Naše. Vysílané všemi pobočkami v rámci systému nouzového varování.“","c":[["Vytvořte ho. Každý večer. Vysílané všude.","Šedesát milionů domácností teď dostává večerní vysílání vyrobené v budově, kde se tvoří politika. Dvě ze čtyř televizních sítí ho začnou simultánně přebírat, aby zůstaly konkurenceschopné."],["Vytvořte ho jako streamovací kanál. Dobrovolné přebírání.","Jedenáct milionů předplatitelů a žádná žaloba. Pomalejší. Čistší. Dostane se to tam."],["Nedělejte to. Soukromé televize to už dělají zadarmo.","Přesné a znepokojivé zhodnocení mediálního prostředí."],["Vytvořte ho, a udělejte ho celý o počasí.","Nepřetržitý federální kanál o počasí. Je vynikající, důvěryhodný, zachrání životy při třech hurikánech a vaše jméno navždy zůstane v rohu obrazovky."]]},"election-commission":{"t":"Integrita voleb","x":"„Federální komise s pravomocí předvolávat výpisy voličů, volební stroje a okresní úředníky. Volby vedou jednotlivé státy, pane. Všech padesát. A kolem tohohle si postavily nejvíc hradeb.“","c":[["Založte ji. Předvolejte úplně všechno.","Třicet jedna států odmítne. Devatenáct vyhoví. Teď máte v devatenácti státech mechanismus, kterým lze zpochybnit výsledek ještě předtím, než je vyhlášen."],["Dobrovolná komise. Jen poradní.","Vydá zprávu. Ta zpráva se stane faktickým základem pro všechno, co následuje. To bylo od začátku jejím úkolem."],["Ne. Volby jsou to jediné, čeho se nedotýkáte.","Nakreslil jste hranici na jediném místě, kde nějaká hranice kdy skutečně vydržela."],["Založte ji a do čela postavte opozici.","Nikdo nemůže napadat závěry komise, které předsedá jeho vlastní tábor. Je to nejcyničtější možná cesta ke skutečné legitimitě a naprosto funguje."]]},"third-term":{"t":"Dvaadvacátý dodatek","x":"„Uvažujete o třetím funkčním období. Dvaadvacátý dodatek má 87 slov a je neobvykle dobře napsaný. Nicméně.“ Sy obrátí stránku. „Omezuje být *zvolen*. Existuje argument o tom, být *dosazen*. Je to špatný argument.“","c":[["Vypusťte to. Prodávejte kšiltovky. Sledujte, kdo bude protestovat.","Kšiltovky se vyprodají za čtyři hodiny. Jedenáct senátorů vaší vlastní strany neřekne vůbec nic, a jejich mlčení je ta skutečná zpráva."],["„Budu se řídit ústavou.“ Řekněte to jednou. Nikdy víc.","Jediná čistá věta, pronesená bez přesvědčení, která vám koupí šest měsíců, kdy se na to nikdo neptá."],["Ať přátelský zákonodárný sbor přijme usnesení, které o to žádá.","Vy jste o to nepožádal. Bylo to vyžádáno. Zákonodárným sborem. Tenhle rozdíl bude nosnou zdí celé argumentace."],["Místo toho oznamte kandidaturu na starostu malého města.","Zhruba devět dní to myslíte naprosto vážně. Čtyřtisícové městečko v Nebrasce zažívá nejpodivnější čtrnáct dní ve své historii."]]},"governor-arrest":{"t":"Guvernérka","x":"„Máme připravenou obžalobu na úřadující opoziční guvernérku. Jednání, o které jde, se skutečně pravděpodobně stalo a nikdo za to dosud nebyl obžalován. Bylo by to první zatčení svého druhu.“","c":[["Zatkněte ji. Ranní razie. Kamery u toho.","Její stát obžalobu neuzná. Devět dní si nárok na stejné území dělají dvě vlády a nikdo si není jistý, komu vlastně velí státní policie."],["Obžalujte potichu. Žádná razie. Nechte to protáhnout se soudy.","Dva roky slyšení ji politicky zničí, aniž by vznikl jediný obraz, kolem kterého by se mohl kdokoli semknout. Tohle je ta krutější verze."],["Zametěte to pod koberec. Ještě ne.","Bo dá spis do zásuvky. Zásuvka není zamčená. Všichni vědí, do které."],["Místo toho ji pozvěte na večeři. Jen vy dva.","Tři hodiny, žádní poradci, žádné telefony. Ani jeden z vás nikdy neřekne, o čem jste mluvili. Obě administrativy se poté prokazatelně snáz vychází."]]},"nomenclature":{"t":"Nomenklatura","x":"„Žádosti o přejmenování věcí po vás: jedenáct letišť, jedna hora, čtyři dálnice, federální soudní budova, letadlová loď, a tahle přišla od žáka čtvrté třídy, měsíc.“","c":[["Všechno. Včetně měsíce. Zejména měsíc.","Přejmenování měsíce je symbolické a nevymahatelné, což vystihuje zhruba 60 procent vaší exekutivní činnosti a nic z jejího účinku."],["Jen letiště. Skromné. Prezidentské.","Čtyřicet milionů lidí ročně teď mimoděk vysloví vaše jméno, když si přerezervovávají přípoj."],["Odmítněte to všechno. Pojmenujte je po veteránech.","Skutečně ušlechtilý čin. Zpráva se objeví v jednom zpravodajském cyklu a pak je zapomenuta, jak už to s ušlechtilostí bývá."],["Přejmenujte měsíc po té žákyni čtvrté třídy, co o to požádala.","Jmenuje se Priya. Je to symbolické a nevymahatelné, je jí devět let, čtyři dny je to ve zprávách a je nejšťastnějším člověkem v Americe."]]},"cabinet-praise":{"t":"Zasedání vlády","x":"Chet navrhl, aby se televizní zasedání vlády zahájilo tím, že postupně kolem stolu každý ministr řekne, co pro něj znamená sloužit vám. Říká, že to „polidšťuje tým“. Přitom se dívá přímo na vás.","c":[["Udělejte to. Projděte stůl dvakrát.","Čtyřicet jedna minut dospělých lidí, jak děkují jednomu muži za výsadu zaměstnání. Vysílá se to živě. Někde profesor srovnávací politologie zastaví záznam a nahlas řekne: „tady to je“."],["Udělejte to, ale po čtyřech to ukončete.","Čtyři stačí na to, aby se ustanovila norma, aniž by vznikl kompletní sestřih."],["„Tohle dělat nebudeme. Podejte zprávu o svých úřadech.“","Schůzka je produktivní, informativní a Chet celou dobu píše do malého zápisníku."],["Projděte stůl a místo toho ať vás každý zkritizuje.","Dvacet dva úředníků řekne v živém vysílání jednu pravdivou kritickou věc. Čtyři z nich jsou mimořádně konkrétní. Je to nejlepší zasedání vlády, jaké kdy který prezident svolal."]]},"purge-generals":{"t":"Důstojnický sbor","x":"„Požádal jste o prověrku vyššího důstojnického sboru podle „souladu“. Chci mít jasno v tom, co slyším. Žádáte mě, abych vám předal seznam důstojníků podle loajality. Sloužím 38 let. Ten seznam nenapíšu.“","c":[["Dobře. Odešlete ho do výslužby. Napíše ho někdo jiný.","Někdo jiný ho napíše do čtyř dnů. Jedenáct generálů odejde do měsíce do výslužby. Velitelský řetězec teď vede přes lidi, kteří byli vybráni podle toho, co odmítnout nedokážou."],["Stáhněte tu žádost. Nechte si Tarranta.","Neděkuje vám. Prostě se vrátí do práce, což je v jeho profesi nejvyšší možná pocta."],["Nechte si Tarranta. Seznam sestavte přes civilní složku.","Seznam existuje. Tarrant o něm neví. Dozví se to v nejhorší možný okamžik pro vás oba."],["Požádejte Tarranta o seznam důstojníků, kteří by odmítli nezákonný rozkaz.","Napíše ho za devět minut. Má na sobě čtyři sta jedenáct jmen. Podá vám ho se slovy „tohle je ten dobrý seznam, pane“, a má pravdu."]]},"emergency-standing":{"t":"Nouzový stav","x":"„Existuje 41 zákonných pravomocí, které se odemknou při vyhlášení celostátního nouzového stavu. Vyhlásil jste šest nouzových stavů. Žádný z nich nebyl nikdy ukončen. Pane, podle zákona je můžete ukončit jedině vy.“","c":[["Vyhlaste sedmý. Sjednoťte je všechny pod jedno nařízení.","Jedno nařízení, 41 pravomocí, doba trvání neomezená, ukončit ho může jen ten, komu prospívá. Nikdo o tom nehlasoval. Všichni volili lidi, kteří to odmítli zastavit."],["Nechte dva propadnout. Ty užitečné si nechte.","Ty dva, které jste nechal propadnout, stejně nikdo nepoužíval. Tomu se říká dobré hospodaření."],["Ukončete je všechny. Vládněte, jako by bylo obyčejné úterý.","Dobrovolně jste se vzdal víc moci než kterýkoli prezident v živé paměti. Zprávy o tom se objeví až za jedenáct dní."],["Vyhlaste celostátní nouzový stav kvůli nouzovým stavům.","Metanouzový stav, vyhlášený na základě nouzových pravomocí, týkající se počtu nouzových stavů. Odemkne to čtyři další pravomoci. Nikdo nedokáže určit, jestli je to legální."]]},"succession-plan":{"t":"Náhradník","x":"„Vaše podpora ve straně je 94 procent. Chetova 91. Přitom nevedl žádnou kampaň. Neutratil ani dolar. Pane, když hnutí naroste do téhle velikosti, přestane potřebovat osobu a začne potřebovat tvář, a tváře jsou nahraditelné.“","c":[["Vyřaďte ho z kandidátky. Veřejně. Bez milosti.","Odejde s grácií, přednese jeden projev a stane se mučedníkem s 91procentní podporou a žádnou odpovědností. Tohle možná byla ta horší varianta."],["Přivažte ho blíž. Dejte mu všechno, o co požádá.","Teď má vlastní resort, tým i voličskou základnu. Vybudoval jste mu administrativu uvnitř vlastní administrativy."],["Nechte ho potichu vyšetřit. Lidmi, kteří vám něco dluží.","Nic se nenajde, protože nic najít nejde. O vyšetřování se dozví druhý den od přítele a nikdy o tom neřekne ani slovo."],["Udělejte z Cheta velvyslance v zemi, která je z větší části led.","Přijme to s obrovskou grácií, slouží skvěle a vrátí se za tři roky s opálením, knižní smlouvou a podporou čtyř severních států."]]},"st-no-ballot":{"t":"Žádné příští volby","x":"„Každá prognóza, kterou jsem pro vás kdy sestavila, měla proměnnou nazvanou „příští volby“. Odstranila jsem ji.“ Nadia otočí notebook k vám. Je tam spousta prázdného místa. „Pane, já už nevím, k čemu ten model vlastně je.“","c":[["„Tak přestaňte modelovat. Začněte plánovat harmonogram.“","Průzkumy klesají z omezujícího faktoru na pouhou zdvořilost. Do měsíce vám nikdo v budově neumí říct, co si země myslí, a nikdo se na to neptá."],["Pokračujte v průzkumech. Vědět má stále cenu.","Zůstáváte nejlépe informovaným autoritářem v budově, což se ukáže jako skutečná konkurenční výhoda."],["Zjišťujte jen jednu otázku: přijali by třetí funkční období?","Třicet jedna procent ano. Nadia to označí za katastrofální. Podotknete, že třicet jedna procent je zhruba účast v posledních třech primárkách dohromady."],["Uspořádejte fingované volby proti kartonové figuríně. Prohrajte.","V průzkumu mezi vlastními příznivci prohrajete s figurínou o devět bodů. Odbudete to smíchem. Přemýšlíte o tom pak ještě hodně dlouho."]]},"st-lame-duck":{"t":"To slovo","x":"Hal Grimes použil na živý mikrofon frázi „chromá kachna“. Za jedenáct minut se čtyřikrát omluvil. Nemá nepravdu, a každý v sále si spočítal to samé co on.","c":[["Postavte proti němu vyzyvatele v primárkách. Oznamte to z pódia, jmenovitě.","Radši odejde do důchodu, než aby prohrál. Příští předseda Sněmovny to celé sledoval a nemá vůbec žádný vlastní názor."],["„Má pravdu. A právě proto to letos dotáhneme do konce.“","Proměnil jste vlastní datum spotřeby v termín. Všechno se teď hýbe rychleji, i věci, které by neměly."],["Nechte to být. I kachna může pořád něco podepisovat.","Velkorysost vyznívá jako slabost přesně u lidí, kteří se vás musí bát."],["Sežente si skutečnou kachnu. Umístěte ji do Oválné pracovny.","Živá kachna jménem Dodatek. Zůstane tam do konce funkčního období a je jediným členem administrativy, kterého z ničeho nikdy neobviní."]]},"st-library":{"t":"Knihovna","x":"„Vaše prezidentská knihovna. Čtyři sta milionů, soukromě vybraných, žádná povinnost zveřejňovat dárce, a každé vyrovnání, které jste kdy vysoudil, je na ni už předem vyhrazeno.“ Sy se odmlčí. „Strukturálně je to naprosto nejčistší způsob, jak v americkém veřejném životě dostat peníze.“","c":[["Postavte ji. Přijímejte zahraniční dary. Nic nezveřejňujte.","Přispěje jedenáct vlád. Nikdo se jich neptá proč. Budova má taneční sál, což u knihoven není zrovna standardní výbava."],["Postavte ji a zveřejněte všechny dárce.","To zveřejnění je nudné, úplné a potichu nejuklidňujícím dokumentem, jaký vaše administrativa kdy vydala."],["Knihovnu vynechte. Postavte místo ní monument.","Šedesát metrů žuly s vaším profilem, na federálních pozemcích, financováno přílepkem, který nikdo nečetl. Přežije všechna exekutivní nařízení, která jste kdy podepsal."],["Postavte ji, naplňte ji skutečnými knihami a pusťte tam kohokoli.","Čtyři sta tisíc svazků, volný veřejný přístup, otevřeno sedm dní v týdnu. Stane se nejvyužívanější budovou ve státě a přežije všechny spory o vás."]]},"st-old-guard":{"t":"Ti, kteří zůstali","x":"„Jedenáct tisíc kariérních úředníků přežilo první funkční období tím, že drželi hlavy dole a papíry v naprostém pořádku. Jsou důvodem, proč vůbec něco funguje.“ Deborah položí seznam na stůl. „Jsou i důvodem, proč některé věci nefungovaly.“","c":[["Překlasifikujte všech jedenáct tisíc. Nahraďte je.","Vláda ztratí za čtrnáct dní čtyři sta let institucionální paměti a získá pracovní sílu bez jakékoli paměti, což bylo přesně zadání."],["Povyšte ty, co nikdy nic nenamítali. Zbytek pošlete do důchodu.","Žádné výpovědi, žádné žaloby, žádná kauza. Jen kariérní žebřík, který neviditelně a natrvalo vybírá podle mlčenlivosti."],["Nechte je být. Někdo přece musí vědět, kde co je.","Vlaky jezdí, šeky se proplácejí, zprávy se píší. Je to nejméně efektní rozhodnutí, jaké je k dispozici, a je to důvod, proč země pořád funguje."],["Povyšte všech jedenáct tisíc. O jeden stupeň. Všechny.","Stojí to 400 milionů dolarů a koupí to loajalitu celé stálé vlády. Je to nejlevnější věc, kterou jste kdy koupil, a nikdo mimo budovu si toho nevšimne."]]},"st-successor":{"t":"Pomazání","x":"Chet Danforth by rád vaši podporu pro příští volební cyklus. Přinesl návrh prohlášení. Je napsané vaším hlasem. Je velmi dobré. Očividně ho má hotové už nějakou dobu.","c":[["Podepište to. Bude vám za ten úřad vděčný do konce života.","Vděčnost je v politice nejkrátkodoběji trvající emocí. Právě jste odevzdal jedinou věc, které se v tomhle městě ještě někdo bál."],["Odmítněte. Nikoho nepodporujte. Nechte je všechny hádat.","Šest kandidátů teď od vás každý týden něco potřebuje. Nevyužitá podpora má vždycky větší hodnotu než ta vyčerpaná."],["„Žádný příští cyklus nebude, Chete.“","Zasměje se. Vy ne. Ticho, které následuje, trvá devět vteřin a oba si ho budete pamatovat do konce života."],["Podpořte osobu, která neexistuje, a uvidíte, jak daleko to dojde.","„Guvernér Ray Halloway“ má do čtrnácti dnů v průzkumech 22 procent a získá 9 milionů dolarů na darech, než někdo zjistí, že to není skutečná osoba."]]},"st-machine-runs":{"t":"Nikdo se neptal","x":"„Tři úřady tento týden udělaly něco, co jsme nenařídili. Udělaly to, protože vydedukovaly, co bychom asi chtěli.“ Deborah poprvé za osm let vypadá opravdu znepokojeně. „Pane, to teď běží bez nás.“","c":[["Výborně. Přestaňte úplně vydávat rozkazy.","Administrativu, která nepotřebuje pokyny, nelze přistihnout, jak nějaký vydává. Není žádný oběžník, který by šlo předvolat, protože žádný oběžník nikdy nebyl."],["Zkroťte to. Rozkaz, který jste nevydal, je riziko.","Strávíte čtrnáct dní tím, že vládě říkáte, ať dělá méně. Je to nejpodivnější práce vaší kariéry a ani se úplně nepovede."],["Sepište to. Formalizujte to jako politiku. Přiznejte se k tomu.","Co bylo popiratelné, je teď podepsané. Je to silnější, rychlejší, a existuje teď dokument s vaším jménem dole."],["Vydejte jeden záměrně absurdní rozkaz a sledujte, jestli se splní.","Nařídíte přemalovat všechny federální budovy na konkrétní odstín béžové. Čtyři sta jich je přemalováno dřív, než se kdokoli zeptá proč. Teď přesně víte, co jste vybudoval."]]},"referendum":{"t":"Otázka","x":"„Celostátní referendum o „kontinuitě vedení v období nouzového stavu“. Nezávazné. Poradní. Hlas ano by nezměnil zákon.“ Odmlčí se. „Změnilo by to, k čemu zákon slouží.“","c":[["Uspořádejte ho. Otázku si napište sám.","Projde to poměrem 54:46 při 31procentní účasti. To číslo je teď v každém podání citováno jako „vyjádřená vůle amerického lidu“. Není to závazné. Nic už nemusí být závazné."],["Uspořádejte ho jen v přátelských státech. Jako pilotní projekt.","Devět států hlasuje drtivě ano. Devět států není celá země, ale devět států je precedent, a precedent je jediná zbývající měna."],["Zrušte ho. Je to moc na hraně.","Deborah souhlasí, což je nějak znepokojivější, než kdyby s vámi nesouhlasila."],["Uspořádejte referendum, ale o tom, zda se mají referenda konat.","Projde to poměrem 61:39. Nikdo nedokáže určit, co se vlastně rozhodlo, včetně lidí, kteří ho vedli, a výsledek obě strany citují ještě deset let."]]},"a-not-a-ban":{"t":"Jak tomu říkat","x":"Nařízení jmenuje šest zemí. V každé z nich žije většinově muslimské obyvatelstvo, což je buď náhoda, nebo záměr, a Kaylee má otázku, kterou dnes odpoví čtyřicetkrát, než na ni odpoví poprvé.","c":[["„Tohle není náboženský zákaz.“ Tečka, žádné vysvětlování.","Ta věta se opakuje tak často, že začne svědčit sama proti sobě; do dne se objeví čtyři klipy z kampaně, všechny čtyři na záznamu, vaším hlasem, nepopřené."],["Uveďte bezpečnostní zdůvodnění. Zveřejněte hodnocení hrozby.","Hodnocení podpoří dvě ze šesti zemí a potichu zdemoluje zbylé čtyři. Ukáže se, že poctivost je drahá volba, a stojí vás dvě třetiny nařízení."],["Řekněte, že je to přesně to, jak to vypadá.","Upřímnost je vzrušující přesně do chvíle, kdy ji soudní zapisovatel přepíše, a pak přestává být osobnostním rysem a stává se důkazem číslo jedna."],["Kvůli vyváženosti přidejte na seznam většinově křesťanskou zemi.","Lichtenštejnsko. 40 000 obyvatel, nula žadatelů o azyl v evidenci, a ministerstvo zahraničí odpoví prohlášením tak pobaveně solidárním, že přežije celou vaši administrativu."]]},"a-second-draft":{"t":"Třetí verze","x":"„Dvě verze zrušil soud. Tohle je třetí.“ Bo to rozloží na stole. „Stejných šest zemí. Nové jsou čtyři odstavce procesních náležitostí přišroubované na začátek, a přesně těch pár odstavců je celá právní strategie.“","c":[["Podepište třetí verzi. Ať tu práci odvedou ty odstavce.","Přezkum přežije. Ty odstavce si mimo čtyři právnické fakulty nikdo nikdy nepřečte, a přitom jsou jediným důvodem, proč je to vůbec pořád legální."],["Podepište to a veřejně řekněte, že je to stejné nařízení jako předtím.","Jedna poznámka na mítinku zmaří čtyři odstavce pečlivé právničiny. Je to počtvrté zrušeno soudem a vaši vlastní větu vám v odůvodnění rozsudku citují zpátky."],["Vzdejte to. Dva soudy jsou dva soudy.","Nic se nepodepíše. Politika potichu zanikne a vaše základna si osvojí ponaučení, že soudce dokáže věci prostě ukončit, což není lekce, kterou jste chtěl učit tak brzy."],["Podepište všechny tři verze najednou.","Tři protichůdná nařízení teď najednou upravují stejnou hranici. Celní úřad si čtyřikrát vyžádá vysvětlení a pokaždé dostane všechny tři nařízení sešité dohromady."]]},"a-language-denial":{"t":"Použitá slova","x":"Dva lidé v místnosti si přesně pamatují, co jste řekl o určitých zemích. Deborah připravila popření. „Zpochybňuje to formulaci, ne samotnou schůzku. Pane, to jsou velmi úzké dveře, za kterými se dá schovat.“","c":[["Zveřejněte to úzké popření. Nic dál nevysvětlujte.","Čtyři lidé z té místnosti odmítnou vás podpořit. O roky později tu frázi sám potvrdíte před kamerou, očividně jste zapomněl, že jste ji kdy popřel."],["Nic nepopírejte. Řekněte, že schůzka byla soukromá.","Odmítnutí se vůbec vyjádřit je lepší než popření, které se dá ověřit. Vydrží to, čistě, celé čtyři roky."],["Potvrďte to a obhajte tu podstatu.","Devět velvyslanců si do týdne vyžádá schůzku. Ministerstvo zahraničí naplánuje všech devět a každému z nich nabídne mírně jinou verzi událostí."],["Sveďte to na chybu tlumočníka. Žádný tlumočník tam nebyl.","Všichni v místnosti mluvili anglicky, na což okamžitě někdo upozorní. Chybu označíte za „koncepční“, což nikdo nedokáže vyvrátit, protože to nikdo nedokáže rozklíčovat."]]},"a-wall-emergency":{"t":"Nouzový stav kvůli zdi","x":"Kongres vám před čtyřmi dny hlasováním schválil 1,4 miliardy dolarů a zbytek odmítl. „Vyhlášení nouzového stavu odemkne peníze na vojenskou výstavbu bez ohledu na to,“ říká Bo. „Kongres řekl ne. V tom je celá ta nouze.“","c":[["Vyhlaste ho. Vezměte si peníze na výstavbu.","Prohrané hlasování jste proměnil ve vyhrané tím, že jste tu prohru prostě nazval nouzovým stavem. Obě komory přijmou usnesení o jeho ukončení a vy ho taky vetujete."],["Vyhlaste ho, ale utraťte jen položku na boj proti drogám.","Méně fotogenické, méně žalované, stejný beton. Nikdo neprotestuje proti rozpočtové položce o zadržování drog, a v tom je celý trik."],["Postavte to, na co stačí 1,4 miliardy. Řekněte, že to byl vždycky plán.","Sto čtyřicet pět kilometrů, v rozpočtu, dokončeno předčasně, postaveno přesně tam, kde to doporučili inženýři. Nikdo si toho vůbec nevšimne, což je zjevně cena kompetence."],["Vyhlaste nouzový stav kvůli nedostatku nouzových stavů.","Federální registr to zveřejní, protože Federální registr zveřejní cokoli, co dostane. Čtyři úřady si vyžádají prováděcí pokyny, které nikdo nikdy nenapíše."]]},"a-blood":{"t":"Věta o krvi","x":"Gideon upozornil na větu v zítřejším návrhu, o tom, co imigrace dělá se zemí, a sloveso, které podtrhl, je z lékařské terminologie. „Pane, dva historici budou mít komentář hotový dřív, než tu větu dořeknete.“","c":[["Nechte ji tam. Přednesete ji dvakrát.","Komentáře vyjdou do hodiny a oba citují identický projev z dvacátých let. Váš tým označí kritiky za posedlé historií, což je pravda, a zároveň to není vůbec žádná obhajoba."],["Změňte sloveso. Argument nechte.","Stejná politika, stejný hluk davu, žádné archivní záběry, které by vás pronásledovaly. Gideon tomu říká nejlevnější úprava celé jeho kariéry."],["Vyškrtněte ji. Mluvte místo toho o konkurenci na trhu práce.","Ekonomický argument, o kterém se dá diskutovat, je obhajitelný a nudný jako sádrokarton. Přesvědčí o čtyři sta tisíc lidí víc než ta druhá verze a nenadchne přesně nikoho."],["Přednete ji, ale o zásobování vodou.","Jedenáct minut o fluoridaci vodovodní vody, pronesených s naprostým přesvědčením. Čtyři státní zdravotní úřady vydají vysvětlení, o která nikdo nežádal."]]},"a-energy-emergency":{"t":"Energetický nouzový stav","x":"Cassandra Doyle má připravený balíček na první den: vyhlášení energetického nouzového stavu a zrušení jedenácti nařízení předchůdce. „Produkce je na rekordní úrovni, pane. Přesně to číslo musí to vyhlášení přežít.“","c":[["Vyhlaste ho stejně. Rekordní produkce, přesto nouzový stav.","Vyhlášení odemkne povolovací pravomoci, které nemají s nedostatkem nic společného, protože o nedostatek nikdy vlastně nešlo, a rekordní čísla produkce se stejně měsíčně dál zveřejňují."],["Zrušte ta nařízení. Nouzový stav přeskočte.","Stejný praktický efekt, o vyhlášení už není co soudit. Čtyři ekologické skupiny místo toho zažalují ta zrušení a prohrají kvůli chybějící aktivní legitimaci."],["Nechte ta nařízení být. Rekordní produkci si přisvojte.","Ten rekord vznikl dva roky před vámi. Přisvojíte si ho stejně a nikoho se nechce obtěžovat vás opravovat."],["Vyhlaste energetický nouzový stav i přebytek, ve stejné ráno.","Dvě prohlášení, dvacet minut od sebe, přímo si odporující, obě stále v platnosti. Odborný časopis se na 4000 slovech pokusí je sladit dohromady a nepodaří se mu to."]]},"a-wind":{"t":"Moratorium","x":"„Zastavení nových pronájmů pro větrné elektrárny na federálních pozemcích. Jedenáct projektů ve fázi konečného povolování, čtyři tisíce pracovních míst, a většina z toho ve státech, kde jste vyhrál s dvouciferným náskokem.“ Cassandra čeká.","c":[["Zastavte to všechno. Okamžitě.","Čtyři tisíce pracovních míst zamrznou v pěti státech, které jste vyhrál. Dva guvernéři z vaší vlastní strany protestují oficiálně, a jeden z nich je na každém vašem užším seznamu."],["Zastavte nové pronájmy. Nechte těch jedenáct dokončit.","Symbolika bez obětí. Vaše základna slyší slovo „zastaveno“ a těch jedenáct projektů neslyší vůbec nic."],["Žádné moratorium. Schvalte je a přestřihněte pásku.","Pózujete v přilbě před turbínou. Váš vlastní tábor s tou fotkou proti vám bojuje ještě další čtyři roky."],["Zakažte vítr na federálních pozemcích, pak si turbíny sám odkupte.","Získáte jedenáct rozestavěných větrných farem se slevou, kterou vytvořilo vaše vlastní nařízení. Čtyři etické úřady otevřou spisy a ani jeden nedokáže pojmenovat skutečné porušení."]]},"a-pipelines":{"t":"Dva plynovody","x":"Dva plynovody, oba zastavené minulou administrativou, oba obnovitelné pouhým memorandem. „Jeden protíná řeku čtyři sta metrů nad vodním přívodem rezervace. V tom je celý spor.“","c":[["Schvalte oba. Memorandum, ještě dnes.","Výstavba začne za devět týdnů. Protestní tábor, který vznikne proti proudu, vydrží jedenáct měsíců a vznikne z něj definující protestní fotka vašeho prvního roku."],["Schvalte jeden. Druhý přetrasujte.","Přetrasování stojí 400 milionů dolarů a dva roky navíc, ale nevyvolá žádnou žalobu. Oba plynovody čerpají do roku 2031."],["Schvalte oba a financujte rezervaci nový vodní přívod.","90 milionů dolarů na úpravnu vody vyřeší námitku v samém základu. Čtyři náčelníci kmenů to veřejně potvrdí, což překvapí naprosto všechny, včetně jich samotných."],["Schvalte třetí plynovod, který nikdo nenavrhl.","Nemá trasu, provozovatele ani žádost. Je oznámen na mítinku a objeví se ve čtyřech státních energetických plánech dřív, než kdokoli potvrdí, že vůbec neexistuje."]]},"a-climate-money":{"t":"Přísliby","x":"Třem zemím bylo na základě amerického podpisu přislíbeno financování transformace. Muriel: „Můžeme to stáhnout, bylo to přislíbeno, ne schváleno rozpočtem. Problém je, že už začaly stavět.“","c":[["Stáhněte všechny tři přísliby.","Dva ze tří projektů si do osmnácti měsíců najdou jiné financování. Neušetřil jste ani dolar, jen jste ten vztah předal někomu jinému."],["Stáhněte dva. Dodržte ten, který se už staví.","Rozlišení, o které nikdo nežádal, koupené za 600 milionů dolarů, které zachová přesně jeden vztah. Muriel tomu říká nejlepší odpoledne jejího roku."],["Dodržte všechny tři. Program pojmenujte po sobě.","Projekty se postaví, cedule říkají to, co jste chtěl, a tři vlády vám teď dluží laskavost, kterou nikdy nevyberete."],["Stáhněte peníze a místo toho nabídněte uhlí.","Všechny tři to odmítnou. Jedna to udělá dopisem tak dokonale zdvořilým, že si ho nechají zarámovat a pověsit na svém velvyslanectví ve Washingtonu."]]},"a-tapes-post":{"t":"Nahrávky","x":"Připravil jste příspěvek naznačující, že muž, kterého jste právě vyhodil, by měl doufat, že neexistují žádné nahrávky vašich rozhovorů. Sy: „Pane, to se dá číst dvěma způsoby. Buď je to blaf. Nebo na té nahrávce něco skutečně je.“","c":[["Zveřejněte to. Ať se trápí domněnkami.","Výboru poví, že přesně kvůli vašemu příspěvku si schovával poznámky. Jednou větou jste zdarma vyvolal přesně to zveřejnění, kterému jste se chtěl vyhnout."],["Zveřejněte to, pak o měsíc později potvrďte, že žádné nahrávky nejsou.","Celý měsíc celonárodních spekulací o nahrávacím systému, který nikdy neexistoval, ukončený vámi, bez nákladů pro kohokoli, kromě toho měsíce."],["Neříkejte nic. Je vyhozený a je to za vámi.","Opravdu je to za vámi. Sy to nazve jednoznačně nejlepším rozhodnutím prvního roku a myslí to naprosto vážně."],["Nainstalujte nahrávací systém, pak to zveřejněte.","Vyrobíte si důkaz, abyste jím mohl někomu vyhrožovat. Čtyři právníci vám postupně vysvětlí ten problém, každé vysvětlení ponuřejší než to předchozí."]]},"a-let-this-go":{"t":"\"Doufám, že to dokážete\"","x":"Požádal jste všechny ostatní, aby opustili místnost. Ředitelka Quistová je pořád tady. Vyšetřování vašeho poradce pro národní bezpečnost běží už devět týdnů a vy se k němu chystáte něco říct.","c":[["\"Doufám, že najdete způsob, jak to nechat plavat.\"","O dvacet minut později si to zapíše ve svém autě, opatří datem a předá kopie třem lidem. O slovu \"doufám\" se pak dva roky soudí."],["Neříkejte o té kauze nic. Mluvte o čemkoli jiném.","Jedenáct minut o politice vůči rukojmím. Odejde zmatená a nezapíše si nic, což je jediný výsledek, který vám skutečně pomůže."],["Zeptejte se jí oficiálně, se záznamem, za přítomnosti právníka.","Nevhodný dotaz před svědkem promění popíratelný rozhovor v zdokumentovaný, ale aspoň je to rozhovor, který dokážete obhájit."],["Požádejte ji, ať radši vyšetřuje vás, jako odvedení pozornosti.","Otevře spis. Je to skutečný spis se skutečným číslem. V roce 2029 je pořád otevřený a nikdo z toho, kdo se na tom podílel, to takhle nechtěl."]]},"a-no-quid":{"t":"Tři slova","x":"Kaylee to spočítala: stejnou tříslovnou latinskou frázi jste za čtyři dny použil jedenáctkrát. \"Pane, tuhle frázi nikdo ve veřejném životě nepoužil deset let. Teď je na hrnku na kávu.\"","c":[["Použijte ji znovu. Hlasitěji. Je to dobrá fráze.","Opakování popření, o které nikdo nežádal, je způsob, jak vyvolat otázku, kterou nikdo nepoložil. Do třetího týdne je fráze zkratkou pro přesně to, co popírá."],["Přestaňte ji úplně používat. Nikdy víc.","Ticho to umoří za devět dní. Je to správné rozhodnutí, a zevnitř to vypadá přesně jako prohra."],["Zveřejněte záznam hovoru a nechte lidi, ať si ho přečtou.","Je to horší než souhrn a lepší než dohady. Zveřejnění zabije čtyři soupeřící fámy a spustí jednu přesnou."],["Prodávejte ten hrnek.","Čtyři sta tisíc kusů po 28 dolarech, druhý nejprodávanější předmět, jaký hnutí kdy vyrobilo, a přímo na boku je vytištěná latina pro \"není to úplatek\"."]]},"a-withheld-aid":{"t":"Pozastávka","x":"\"Čtyři sta milionů dolarů, schválených, alokovaných, a v tuhle chvíli zamrzlých na pozastávce, která vede zpátky do téhle budovy.\" Lyle zvedne oči. \"Nikdo na ministerstvu mi nedokáže říct, kdo ji nařídil a proč.\"","c":[["Nechte pozastávku být. Bez udání důvodu.","Nevysvětlená pozastávka schválených peněz spustí čtyři samostatná šetření, dvě z nich ze zákona, a ani jednomu se nevyhnete."],["Uvolněte je. Řekněte, že šlo o kontrolu.","Uvolněny o 55 dní později, s dvouřádkovým vysvětlením. Auditor si toho zpoždění všimne. Nikdo jiný ne."],["Nechte je zablokované, ale svažte to s formální podmínkou politiky.","Písemná podmínka je nástroj politiky. Nepsaná je laskavost. Napsat ji je ta méně katastrofální ze dvou špatných možností."],["Uvolněte je v měně, kterou nemůžou utratit.","Převod dorazí v jednotce, kterou nikdo nepoužil od roku 1971. Jejich ministerstvo financí stráví čtyři měsíce jejím převáděním a stejně pošle děkovný dopis."]]},"a-fifty-forty-eight":{"t":"Padesát ku čtyřiceti osmi","x":"Hal má sečteno: padesát pro, čtyřicet osm proti, a dva členové se rozhodnou až v poslední hodinu. Slyšení bylo mimořádné způsobem, na který v té místnosti nikdo nezapomene.","c":[["Prožeňte to plénem ještě dnes večer. Dva hlasy jsou většina.","Potvrzen o dva hlasy. Odslouží třicet let a slyšení se přehrává při každém dalším potvrzování, oběma stranami, z opačných důvodů."],["Odložte to o týden na doplňující šetření.","Šetření nic nevyřeší ani jedním směrem. O devět dní později je potvrzen poměrem 53:45; ten týden navíc vás nic nestojí a přinese čtyřem senátorům politické krytí."],["Stáhněte ho. Navrhněte dalšího.","Náhradník je potvrzen 61:39 a je ve všech ohledech spolehlivěji nakloněný vám. Vaše základna prožívá to stažení jako totální, neodpustitelnou porážku."],["Navrhněte oba. Jedno místo, jedno hlasování.","Volné je přesně jedno místo. Druhá nominace se přesto pošle a zůstává na senátním kalendáři čtyři roky, technicky, věčně nevyřízená."]]},"a-eight-days":{"t":"Osm dní do voleb","x":"Soudce zemřel osm dní před volbami. Bo: \"Není proti tomu žádné pravidlo. Je tu ale jedna věc, kterou čtyři senátoři řekli v roce 2016 a kterou teď budou muset spolknout, na kameru, jeden po druhém.\"","c":[["Potvrďte ho před volbami. Osm dní je osm dní.","Složí přísahu se šesti dny v rezervě. Čtyři senátoři si na kameru spolknou svůj starý výrok, jeden po druhém, a všichni jsou stejně znovuzvoleni."],["Navrhněte teď, potvrďte až po volbách. Stejný výsledek, méně žáru.","Totožný výsledek o čtrnáct dní později se třetinovým mediálním pokrytím. Ukáže se, že jediná proměnná, na které záleželo, bylo načasování, a stálo to za víc než ta hádka."],["Nechte to na tom, kdo vyhraje.","Volby i to místo prohrajete. Je to nejzásadovější věc, kterou za čtyři roky uděláte, a stojí vás to čtyři vztahy uvnitř vlastní strany."],["Potvrďte ho na místo, které není volné.","Desátá soudkyně je potvrzena na soud, který má devět míst. Nastoupí, dostane kancelář a čtyři roky potichu dělá právní rešerše."]]},"a-order-struck":{"t":"Trvale zrušeno","x":"Soudkyně zrušila váš příkaz proti té firmě, natrvalo, v rozhodnutí, které slovo \"protiústavní\" použije devětkrát. Sy: \"Nepozastavila ho, pane. Zrušila ho. Není co odvolávat.\"","c":[["Napadněte rozhodnutí. Podepište téměř identický příkaz.","Druhý příkaz zruší za jedenáct dní tatáž soudkyně, obšírně citující vlastní rozhodnutí a přišpendlující ten první jako přílohu."],["Podřiďte se. Obnovte prověrky. Neříkejte nic.","Firma je do čtrnácti dní odškodněna v plné výši. Čtyři další firmy, které už potichu kapitulovaly, své ústupky odvolávají zpátky, a to je ta skutečná cena."],["Podřiďte se, ale zaměřte firmu přes veřejné zakázky místo toho.","Žádný příkaz, žádné rozhodnutí, žádný titulek, jen smlouvy, které se potichu přestávají obnovovat. Funguje to, a není co by kterýkoli soudce mohl zrušit."],["Najměte tu soudkyni.","Odmítne dopisem o čtyřech větách. Dopis je založen do spisu, zveřejněn a stane se nejzábavnějším dokumentem, jaký ten rok kdo podal."]]},"a-accountability-order":{"t":"Příkaz o odpovědnosti","x":"\"Příkaz nařizující agenturám prošetřit chování jmenovaných bývalých úředníků.\" Bo obrátí stránku. \"Pane, čtyři z těch jmen vás osobně vyšetřovaly. Jednomu je 81 a je v důchodu.\"","c":[["Podepište to. Všechna jména.","Nejdřív prověrky, pak spisy, pak revize penzí. Nic se nikdy neobžaluje. Všechno se přesto udělá, protože nic z toho obžalobu nevyžadovalo."],["Podepište to, ale bez těch v důchodu.","Ušetřit toho jedenaosmdesátiletého je celý rozdíl mezi \"politikou\" a \"vendetou\" v tom, jak se to podává, a v ničem jiném."],["Nepodepisujte. Nařiďte místo toho revizi revizí.","Metarevize se ohlásí za čtrnáct měsíců, najde procesní pochybení na všech stranách a neuspokojí nikoho, což je přesně k čemu revize slouží."],["Podepište to a přidejte na seznam i své vlastní jméno.","Vyšetřuje vás vlastní ministerstvo podle vašeho vlastního příkazu. Za devět týdnů vás očistí, a to očištění má přesně takovou cenu, jakou stálo ho vyrobit."]]},"a-ethics-divest":{"t":"Brífink o zbavení se majetku","x":"Miriam Applewhitová předkládá standardní balíček: buď prodat majetek úplně, nebo skutečný slepý fond vedený cizí osobou. \"Existuje ještě třetí věc, které lidé říkají slepý fond a předají ji dětem místo toho. Není slepý, pane. Je to jen fond.\"","c":[["Ten fond. Vedený rodinou. Říkejte mu slepý.","O jeho výkonnosti se dozvídáte u večeře. Každý dokument ho nazývá slepým a každý dokument je, technicky, co se papírování týče, přesný."],["Úplné zbavení se majetku. Prodejte všechno.","Stojí to majlant a natrvalo to odstraní celou kategorii kauz. Ocenit to dokážete přibližně až za tři roky."],["Nechte si všechno. Prezident nemůže mít střet zájmů.","Právní pozice se skutečnou zákonnou oporou a žádnou v padesáti letech praxe. Miriam v březnu odstoupí a v červnu svědčí."],["Vložte to do fondu vedeného cizí osobou, kterou pak zaměstnáte.","O jedenáct týdnů později je jmenován do federální poradní rady. Čtyři novináři si toho všimnou tentýž den a ani jeden to nedokáže prokázat."]]},"a-gift-log":{"t":"Seznam darů","x":"Jedenáct set inauguračních darů od cizích vlád. Cokoli nad prahovou hodnotou legálně patří státu, ne vám. Položka 402 je zlatý kůň. Položka 403 je větší.","c":[["Zapište je. Odkupte si koně za odhadní cenu.","Naprosto legální, plně zdokumentované, a stojí to 600 000 dolarů za dva zlaté koně, které jste nikdy nechtěl a nemáte je kam v budově vystavit."],["Zapište je jako vystavené v rezidenci. Nechte si je.","Rezidence je vaše. \"Vystavení\" je chodba. Podle běžného významu toho slova jste si ty koně prostě nechal."],["Vydražte celou sbírku pro veterány. Veřejně.","Za odpoledne se vybere 2,1 milionu dolarů. Ceremoniální dýka připadne dvanáctiletému dítěti, což vyvolá krátký, opravdu roztomilý mezinárodní incident."],["Roztavte koně. Razte mince se svou tváří.","Darující vláda si vyžádá fotografii koní do svého archivu. Místo toho jí pošlete fotografii mincí."]]},"a-property-billing":{"t":"Ceník","x":"Duane má faktury. Ochranka za čtyři měsíce zaplatila vašemu vlastnímu resortu 1,1 milionu dolarů na pokojích. \"Pane, musíme bydlet tam, kde bydlíte vy. A cenu si určujete vy.\"","c":[["Nechte cenu být. Je to tržní cena.","Daňový poplatník teď platí prezidentovi za to, že chrání prezidenta v prezidentově vlastním hotelu. Je to zveřejněné, položkované, naprosto legální, a to je celý problém."],["Účtujte jim dolar ročně.","Levné, teatrální, zdrcujícně účinné gesto, které zabije kauzu za cenu jednoho sendviče."],["Bydlete někde, co nevlastníte.","Tři různí poradci nazvou Camp David \"vlastně fajn\". Po druhé návštěvě už se tam nikdy nevrátíte."],["Účtujte jim to, a pak si naúčtujte i za tu nepříjemnost.","Faktura od vás, vám, placená vládou, za narušení způsobené vlastní ochrankou. Projde to. Nikdo nedokáže zjistit, kdo to schválil."]]},"a-family-desk":{"t":"Kancelář v Západním křídle","x":"Ivy by chtěla kancelář v Západním křídle, bezpečnostní prověrku a neplacený vysoký titul. Prověrka je ta část, na kterou kariérní bezpečnostní personál upozornil. Dvakrát. Písemně.","c":[["Všechny tři. Přehlaste upozornění.","Je opravdu schopná a to místo nemohl dostat nikdo jiný než vaše dcera. Obě věci jsou pravdivé a jen jedna z nich se dostane do novin."],["Titul a kancelář. Bez prověrky.","Na porady chodí stejně, ze židle u dveří, a předčí čtyři potvrzené úředníky, aniž by kdy viděla utajovanou stránku."],["Žádná rodina v budově.","Správné rozhodnutí, tečka. Zároveň odstraníte jediného živého člověka, který by vám v malé místnosti řekl pravdu."],["Dejte jí prověrku a dejte prověrku i těm upozorněním.","Dva kariérní důstojníci, kteří vznesli námitku, jsou zasvěceni přímo do programu, proti kterému namítali. Oba okamžitě namítají znovu, teď s výrazně větším množstvím podrobností."]]},"a-columbia":{"t":"Druhá univerzita","x":"Čtyři sta milionů dolarů, jedna univerzita a seznam požadavků ohledně politiky protestů a katedrálního dohledu. Ollis: \"První se zhroutila rychle. Tahle má větší nadaci a horšího právníka.\"","c":[["Zastavte to. Celých čtyři sta milionů.","Za devět týdnů kapitulují a přijmou externí dohled nad jednou katedrou. Jedenáct dalších univerzit si dohodu přečte a telefonát rovnou přeskočí."],["Zastavte polovinu. Nechte lékařský výzkum na pokoji.","Ušetřit onkologické laboratoře odstraní jediný argument, který skutečně zabíral. Stejná páka, žádná fotka zrušené klinické studie."],["Financujte to naplno. Místo toho útočte rétoricky.","Slova nic nestojí a nic nemění. Univerzita vás úplně ignoruje a počet přihlášek přesto stoupne o 14 procent."],["Zrušte financování a zapište se tam na seminář.","Absolvujete čtyři hodiny kurzu ústavního práva na instituci, kterou právě odřezáváte od peněz. Přepis se objeví v roce 2044 a je, překvapivě, dobré čtení."]]},"a-minors-care":{"t":"Věková hranice","x":"Doktor Pike má návrh. \"Podmiňuje federální financování tím, že nemocnice ukončí určitou kategorii péče pro mladší 19 let. Čtyři dětské nemocnice ve státech, které jste vyhrál, ji zastaví hned v den podpisu.\"","c":[["Podepište to. Devatenáct a míň, bez výjimek.","Devět nemocnic se zastaví do čtrnácti dní, u některých pacientů uprostřed léčby. Dva soudy to částečně pozastaví, a nemocnice to stejně znovu nespustí, protože nemocnice nikdy znovu nespouští."],["Podepište to s výjimkou pro pokračující péči.","Nikdo není odstřižen uprostřed léčby. Politiky se dosáhne, aniž by vznikly ty čtyři konkrétní případy, které by ji definovaly v každém titulku."],["Žádný příkaz. Místo toho financujte dlouhodobou studii.","Ohlásí se za devět let s největším souborem dat, jaký kdy kdo sestavil. Obě strany si z ní vybírají, co se jim hodí, a ani jedna nehne ani o píď."],["Nastavte věkovou hranici na 47.","Instrukce k přípravě vzata doslova někým, kdo se nechtěl na nic ptát. Chyba se odhalí při kontrole po čtyřech dnech a kauza úplně neumírá."]]},"a-military-dei":{"t":"Příkaz o bojeschopné síle","x":"Tarrant vedle sebe pokládá příkaz a data o udržení personálu. \"Podepíšu, co uvedete, pane. Jsem ale povinen vám sdělit, že nábor do čtyř z pěti nejhůř obsaditelných specializací vede přes kanceláře, které tímhle rušíte.\"","c":[["Podepište to. Zavřete všechny kanceláře.","Nábor do těch čtyř specializací klesne za dva roky o 19 procent. Zpráva, která to dokazuje, je utajena na úrovni, jež ji drží mimo rozpočtové slyšení."],["Zavřete kanceláře. Ponechte náborové kanály.","Cedule zmizí, funkce zůstane, jen přejmenovaná. Každý dostane přesně to, co říkal, že chce, a fakticky se nezmění vůbec nic."],["Nepodepisujte. Nejdřív si vyžádejte revizi bojeschopnosti.","Revize shledá programy mírně přínosnými a mírně drahými. O devět měsíců později podepíšete užší příkaz a nikdo se s tím neobtěžuje namítat."],["Podepište to a nahraďte ty kanceláře jedním seržantem.","Seržantka Alvarezová zdědí pracovní zátěž čtyř set lidí, zvládá to lépe než všichni čtyři sta dohromady a za rok je dvakrát povýšena."]]},"a-passports":{"t":"Značka","x":"Muriel: \"Žádosti o změnu pohlavní značky jsou pozastaveny. Ne zamítnuty, pozastaveny. Jedenáct tisíc jich je a čtyři sta lidí má tento měsíc naplánovanou cestu.\"","c":[["Nechte je pozastavené na neurčito. Nevydávejte žádné pokyny.","Pozastávka bez rozhodnutí se nedá odvolat, protože technicky nebylo o ničem rozhodnuto. Je to nejúčinnější odmítnutí v dějinách ministerstva."],["Zamítněte je formálně. Dejte jim něco, proti čemu se lze odvolat.","Formální zamítnutí je žalovatelné a řádně se žaluje. Prohrajete za čtrnáct měsíců, což je, ostatně, čtrnáct měsíců."],["Vyřiďte je. Změňte politiku do budoucna.","Jedenáct tisíc žádostí je vyřízeno za šest týdnů a nové pravidlo platí pro všechny další. Nikomu neuletí letadlo a nikdo si toho ani nevšimne."],["Vydávejte všechny pasy úplně bez značky.","Čtyři země odmítají dokumenty na hranicích. Ministerstvo stráví devět měsíců vyjednáváním o uznání pole, které samo úmyslně smazalo."]]},"a-ninety-day":{"t":"Devadesátidenní pauza","x":"Čtyři dny ztrát. Lyle má plán: pozastavit specifické sazby pro jednotlivé země na devadesát dní a zvednout sazbu na vašeho největšího soupeře na číslo, jaké nikdo nepoužil od třicátých let.","c":[["Pozastavte všechno. Zvedněte tu jednu sazbu na 125 %.","Trhy vyletí za odpoledne o 9 procent. Pár lidí, kteří o pauze věděli o čtyřicet minut dřív, výrazně zbohatne, a čtyři vyšetřování toho nikam nevedou."],["Pozastavte všechno. Nic nezvyšujte.","Čistý ústup, správně čtený jako ústup. Rally je stejně velké, a vaše základna zuří kvůli číslu, které už neexistuje."],["Nic nepozastavujte. Držte linii.","Za týden ubude dalších 6 procent. Penzijní účty vstřebají ránu a vaše obliba u lidí nad 60 let udělá něco, co pollstři nazývají, technicky, geologickým."],["Pozastavte je, a oznamte pauzu čtyřikrát.","Čtyři samostatná oznámení totožné pauzy během devíti dní, každé z nich pohne trhem. Odborný časopis to nazve nejvýnosnějším zajíkáním ve finanční historii."]]},"a-retaliation":{"t":"Odpověď","x":"Odpověděli dva partneři. Jeden zasáhl čtyři zemědělské státy s chirurgickou přesností. Druhý neudělal nic oficiálního vůbec, jeho občané prostě přestali kupovat americké zboží.","c":[["Eskalujte proti oběma.","Přesné cílení se přes noc zdvojnásobí. Bojkot, který nemá žádný oficiální statut, s nímž by se dalo vyjednávat, se nedá utlumit a táhne se jedenáct let."],["Vyjednávejte se státem. Bojkot ignorujte.","S vládou se dohodnete za čtyři měsíce. Spotřebitelské nálady se zotavují devět let a žádná dohoda se jich ani nedotkne."],["Zrušte cla. Prohlaste, že cíle bylo dosaženo.","Všechno se za šest týdnů rozpustí. Dva drobné ústupky koupené za jedenáct měsíců rozvratu, poctivý, byť nepůsobivý výsledek."],["Bojkotujte je zpátky. Osobně. Na kameru.","Veřejně se zřeknete jejich čtyř nejslavnějších produktů. Domácí prodej všech čtyř stoupne. Jedna země vám pošle bednu zdarma s velmi krátkým vzkazem."]]},"a-strike-timing":{"t":"Časování","x":"Váš ministr obrany zveřejnil v komerční chatovací aplikaci časová okna startu a cílové balíčky dvě hodiny předtím, než letadla vzlétla. Tarrant: \"Kdyby se to dostalo k nepravé osobě, pane, tenhle týden bych psal dopisy.\"","c":[["Nikdo není potrestán. Dopadlo to dobře.","Opravdu to dopadlo dobře. Poučení, které si z toho odnese každý důstojník, je o následcích, ne o té aplikaci."],["Odvolejte ho. Řekněte přesně proč.","Odpovědnost, vyslovená jasně, jednou. Čtyři spojenecké služby potichu obnoví sdílení zpravodajských informací, které předchozí měsíc pozastavily."],["Nechte ho. Zakažte tu aplikaci v celé vládě.","Oprava politiky bez personální opravy. Vyřeší to konkrétně tohle selhání a přesně žádný z důvodů, proč k němu došlo."],["Přidejte do chatu i posádku letadla, ať to dostane rychleji.","Někdo se o to opravdu pokusí, než ho fyzicky zastaví. Ten pokus skončí ve zprávě generálního inspektora jako číslované zjištění."]]},"a-war-plans":{"t":"\"Nikdo nic nepsal\"","x":"Vy i ministr jste oba na kameru řekli, že se nic podobného nikde nepsalo. Kaylee: \"Pane, ten magazín má screenshoty. Zveřejní je v plném znění v šest.\"","c":[["Držte linii. Po zveřejnění popření zopakujte.","Screenshoty obsahují ta skutečná slova. Popírání po zveřejnění důkazů promění bezpečnostní selhání v trvalou ztrátu důvěryhodnosti."],["Přiznejte fakta. Zpochybněte jejich závažnost.","Hádat se o tom, jestli to bylo vážné, je boj, který přežijete. Hádat se o tom, jestli se to stalo, ne, a moudře se do toho druhého nepouštíte."],["Předběhněte to. Zveřejněte zprávy sám ve čtyři.","Zveřejnění jako první zabije skoop i tutlání jedním tahem. Magazín svůj článek přesto otiskne, ale jen třetinově dlouhý, než by jinak byl."],["Tvrďte, že screenshoty jsou z jiného chatu.","Obsahují vaše vlastní zobrazované jméno a profilovou fotku. Na to poukáže do čtyř minut, živě, sama osoba, která je drží."]]},"a-cabinet-praise":{"t":"Kolem stolu","x":"Chet navrhuje zahájit vysílané zasedání vlády tak, že se projde stůl a každý ministr řekne, co pro něj osobně znamená sloužit vám. \"Zlidšťuje to tým,\" říká a dívá se přitom přímo na vás.","c":[["Udělejte to. Projděte stůl dvakrát.","Čtyřicet jedna minut dospělých lidí, kteří v přímém přenosu děkují jednomu muži za výsadu zaměstnání. Profesor srovnávací politologie zastaví záznam a nahlas, do prázdné místnosti, řekne \"tady to je\"."],["Udělejte to, ale zastavte to po čtvrtém.","Čtyři stačí na založení rituálu, aniž by vznikl celý sestřih. Chet si to číslo poznamená a založí."],["\"Tohle dělat nebudeme. Podejte zprávu o svých agenturách.\"","Opravdu produktivní schůze s devíti reálnými rozhodnutími. Chet celou hodinu píše do malého notesu, nejistý, co se vlastně stalo."],["Projděte stůl sám a poděkujte jim.","Jmenujete jednu konkrétní věc, kterou udělal každý z dvaadvaceti. Trvá to padesát minut, čtyři jsou viditelně dojatí a Chet netuší, na co se to vlastně dívá."]]},"a-crowd-number":{"t":"Letecké snímky","x":"Letecké fotografie jsou venku. Dav je skutečný, nadšený a zhruba velký jako krajská psí výstava. Noviny otiskly obě léta vedle sebe, pro případ, že by to někomu ušlo.","c":[["Pošlete Kaylee ven, ať řekne, že to byl největší dav vůbec. Tečka.","Řekne to celým svým srdcem. Nikdo jí ani slovo nevěří, každý si všimne, že to řekla stejně, a to bylo od začátku celým smyslem toho, poslat právě ji."],["\"Davy jsou posedlost médií.\" Další otázka.","Kauza umírá za čtyřicet minut. Něco ve vás umírá spolu s ní."],["Nařiďte Národnímu parkovému úřadu, ať zveřejní opravená čísla.","Kariérní fotoarchivář je přeložen do místnosti bez oken v Suitlandu. Číslo je teď 1,9 milionu, napsané, oficiální."],["Spočítejte je sám. V televizi. Nahlas.","Dostanete se ke čtyřem stům jedenácti, než úplně ztratíte nit. Vysílá se to celé a stává se to, s velkým odstupem, nejsledovanější aritmetikou v dějinách televize."]]},"a-misspellings":{"t":"Katalog","x":"Ověřovací redakce katalogizuje vaše pravopisné chyby už jedenáct měsíců. Seznam má 340 položek. Brayden si myslí, že vás to dělá lidštějším. Kaylee si myslí, že to vypadá, že píšete ve čtyři ráno, což taky děláte.","c":[["Postujte dál bez úprav. Je to autentické.","Katalog naroste na 900 položek. Je to taky, upřímně, důvod, proč čtyři miliony lidí věří, že si své příspěvky píšete sám, což bohužel děláte."],["Ať vám to před zveřejněním někdo přečte.","Zapojení klesne do měsíce o 22 procent. Správný pravopis působí jako výbor, a výbor podle vaší základny znamená všichni ostatní."],["Pokaždé úmyslně chybně napište jedno slovo. Přiznejte to.","Stane se to podpisem, pak šibolet. Příznivci to začnou psát chybně zpátky vám, a ověřovatelé to potichu přestanou počítat."],["Oznamte, že slovník se plete.","Čtyři lexikografové odpoví s opravdovým nadšením a jeden napíše překvapivě dobrou esej o deskriptivismu, která nečekaně zvirální."]]},"a-khan":{"t":"Rodiče","x":"Otec vojáka, který zemřel při ochraně své jednotky, vás z pódia zkritizoval a v ruce přitom držel kapesní ústavu. Tarrant je tu s jedinou větou: \"Pane, neexistuje způsob, jak mu odpovědět, který by dobře skončil.\"","c":[["Odpovězte mu. Zpochybněte mlčení matky.","Táhne se to jedenáct dní. Čtyři členové vaší vlastní strany se od vás jmenovitě distancují a doslechne se to každý sloužící důstojník, většina bez jediného slova, což je samo o sobě zpráva."],["Neříkejte nic. Pošlete soukromý dopis.","Dopis se nikdy nezveřejní. Po letech se zmíní, že byl psaný rukou a lepší, než čekal, a nic víc už neřekne."],["Na dalším setkání pochvalte jeho syna jmenovitě.","Hodnost i jednotku uvedete správně, bez poznámek. Třicet vteřin dlouhé a nejúčinnější, co za celý měsíc uděláte."],["Kupte čtyři tisíce kapesních ústav a rozdejte je.","Za týden se vyprodají celostátně. Vydavatel vám napíše poděkování. Čtyři z vašich vlastních výroků vám pak z výtisků, které jste sám zaplatil, citují zpátky."]]},"a-deferred-resignation":{"t":"Nabídka","x":"\"E-mail všem federálním zaměstnancům. Rezignujte hned, plat vám poteče až do září, žádné otázky.\" Deborah má právní poznámku. \"Pane, na výplatu do září nemáme schválené prostředky.\"","c":[["Pošlete to všem 2,3 milionům. Peníze vyřešíme později.","Přijme sedmasedmdesát tisíc lidí. Ti, co mají kam jít, odcházejí první, řízení letového provozu, jaderná bezpečnost, dohled nad nemocemi, protože tak to vždycky je."],["Pošlete to jen tam, kde snížení opravdu chcete.","Přesnost místo brokovnice. Stejný pokles počtu zaměstnanců, jenže jen tam, kde jste si to skutečně zvolil, a inspektoři reaktorů zůstávají na místě."],["Neposílejte to. Snižujte přirozeným odchodem.","Pracovní síla se každý rok scvrkne o 4 procenta bez jediného odeslaného e-mailu. Pomalejší, levnější a nevyvolá to jediný soudní spor."],["Pošlete to, pak pošlete druhý e-mail, který to stahuje.","Jedenáct tisíc lidí už rezignovalo, než stažení dorazí. Čtyři odmítnou zpětvzetí ze zásady a zůstávají, natrvalo, v tom, že měli pravdu."]]},"a-thirty-days":{"t":"Třicetidenní lhůta","x":"\"Zákon vyžaduje třicetidenní písemné oznámení Kongresu, než odvoláte generálního inspektora. Jedna věta.\" Sy pokrčí rameny. \"Není tam žádný sankční paragraf. Ověřoval jsem to čtyřikrát.\"","c":[["Přeskočte oznámení. Odvolejte je dnes večer e-mailem.","Soudce to za osm měsíců prohlásí za protiprávní a odmítne kohokoli vrátit zpátky, s odůvodněním, že byste je stejně jen znovu propustil, tentokrát správně. Má pravdu, a napíše to do rozsudku."],["Dodržte třicet dní. Pak je odvolejte.","Papírování je bezchybné a výsledek totožný. Deborah napíše na ubrousek \"elegantní\" a snědí ji."],["Nechte je. Místo toho jim seknete rozpočty.","Jejich zprávy teď chodí o jedenáct měsíců později, černobíle, nesvázané. Nikdo je nečte, což byl, zřejmě, celý požadavek."],["Dejte třicetidenní oznámení jednomu a zbytek vyhoďte rovnou.","To jedno vyhovující odvolání se cituje v každém podání jako důkaz dobré víry. Jeden ze sedmnácti se ukáže jako překvapivě účinný poměr."]]},"a-rule-count":{"t":"Devadesát osm v řadě","x":"Cassandra má tabulku. \"Devadesát osm pravidel by se dalo zrušit. Jednotlivě je každé technická úprava, o které nikdo nepíše. Dohromady je to největší environmentální změna od roku 1970, a o té taky nikdo psát nebude.\"","c":[["Všech devadesát osm. Jedno týdně. Nikdy je neoznamujte.","Dva roky oznámení ve Federálním registru. Čtyři se dostanou do médií. Kumulativní účinek je měřitelný z oběžné dráhy a nikdy se nedostane na titulní stranu."],["Jen těch dvanáct, co skutečně stojí pracovní místa. Braňte je hlasitě.","Obhajitelná pozice, kterou v televizi skutečně můžete vyhrát, což je devět desetin hodnoty jakékoli pozice vůbec."],["Žádné. Financujte přechod v postižených okresech.","Ve čtyřech státech, které jste vyhrál, se otevře jedenáct tisíc rekvalifikačních míst. Funguje to, pomalu, a stuhu přestřihne váš nástupce."],["Zrušte devadesát osm pravidel a napište devadesát devět nových.","Náhradní sada je delší, přísnější a sepsaná stejnými kariérními úředníky. V budově si toho jedenáct měsíců nikdo nevšimne."]]},"a-smoot":{"t":"Srovnání","x":"Lyle má jednu stránku. \"Každý oslovený ekonom sáhl po stejném srovnání s rokem 1930. Ne většina z nich, pane. Všichni. Včetně čtyř, kteří pro vás technicky pracují.\"","c":[["Přijměte to srovnání. To clo vybudovalo tuhle zemi.","Nevybudovalo. Je to nejprostudovanější politické selhání v americké ekonomické historii, a tvrdí to písemně, ten samý týden, všichni čtyři vaši vlastní ekonomové."],["Odmítněte srovnání. Argumentujte rozdíly.","Skutečné rozdíly existují a argumentujete jimi kompetentně. Nejobsáhlejších dvacet minut vašeho prezidentství, a hodnocení je propadák."],["Zakažte to srovnání v oficiální komunikaci.","Slovo se ve skutečnosti zakázat nedá. Jeho užívání za čtrnáct dní stoupne o 400 procent, přesně proto, že jste se o to pokusil."],["Pojmenujte clo po tom z roku 1930, záměrně.","Přivlastnit si to srovnání dřív, než to udělá kdokoli jiný, je buď geniální, nebo katastrofální, a čtyři různé knihy nakonec dojdou ke čtyřem různým závěrům, ke kterému."]]},"a-first-of-many":{"t":"\"První, možná, z mnoha\"","x":"Ve městě jsou dva tisíce vojáků. Reportér se zeptal, jestli budou další. Tarrant potichu: \"Pane, odpověď na tuhle otázku je celá politika. Ne to nasazení. Ta odpověď.\"","c":[["\"První, možná, z mnoha.\"","Čtyři guvernéři preventivně aktivují vlastní Gardu, jen aby vám odepřeli záminku. Jedna věta právě změnila vojenské postavení třetiny země."],["\"Tohle. Kvůli tomuhle. A víc nic.\"","Nasazení skončí za tři týdny a nic po něm nenásleduje. Omezující jazyk je nejlevnější dostupná deeskalace a stojí vás přesně jednu řeč na mítinku."],["Odmítněte odpovědět. Ať si lámou hlavu.","Záměrná nejednoznačnost odvede práci hrozby, aniž by nesla její odpovědnost. Každý guvernér se připravuje na nejhorší a ani jeden vás nemůže citovat."],["\"První ze přesně tří.\" Jmenujte ty tři.","Vyjmenujete tři města, jak vás zrovna napadnou. Všechna tři do týdne podají žalobu. Jedno z nich nebylo na žádném seznamu, který kdokoli skutečně připravoval."]]},"b-motives":{"t":"Otázka motivu","x":"\"To rozhodnutí dělá něco, co lidem ještě nedošlo.\" Sy to má podtržené třemi barvami. \"Nejde jen o to, že úřední akty jsou imunní. Jde o to, že soud se nemůže ptát *proč* jste to udělal. Motiv už není přípustný důkaz. Pane, motiv byl celá ta kauza.\"","c":[["Tak řekněte tu tichou část nahlas v každém příkazu. Motiv se nepřezkoumává.","Jedenáct příkazů teď otevírá tučně vytištěná doktrína, bez vyzvání. Nikdo tu recitaci nevyžadoval. Právě to z ní dělá hrozbu."],["Používejte to. Nikdy se o tom nezmiňujte.","Štít drží úplně stejně dobře v tichosti a nikdo nenapíše sloupek o doktríně, kterou jste byl příliš zdvořilý na to, abyste se jí chlubil."],["Ať právní tým argumentuje úzkou verzí, pro případ, že by se hodila později.","Sy podá tak skromný spis, že mu za něj dva soudci osobně poděkují. Šetří si ten argument na den, kdy bude mít větší cenu."],["Prohlaste všechny své akty za úřední, včetně snídaně.","Zveřejněný rozvrh označí každou hodinu bdění za úřední akt. Je založen do spisu, zaevidován a posměšně citován v devíti samostatných nesouhlasných stanoviscích."]]},"b-emergency-docket":{"t":"Dvacet devět žádostí","x":"\"Dvacet devět nouzových žádostí za toto funkční období.\" Sy obrátí stránku. \"Pro srovnání: dvě předchozí administrativy podaly dohromady osm, za šestnáct let. Tuhle výjimku už nepoužíváme, pane. Vydláždili jsme ji a postavili pouliční lampy.\"","c":[["Podávejte víc. Výjimka je teď hlavní silnice.","Většinu vyhrajete. Každé vítězství přijde nepodepsané, neodůvodněné, v devět večer, a zavazuje zemi, dokud si někdo nenajde volné odpoledne, aby vysvětlil proč."],["Podávejte jen tam, kde bychom stejně vyhráli ve věci samé.","Devět žádostí místo dvaceti devíti, a každá jedna obstojí i později. Nudné, trvanlivé, a žádný právní časopis o tom nikdy nenapíše."],["Projděte normálními soudy jako všichni ostatní.","Trvá to dva roky místo dvou týdnů. Dvě ze čtyř politik přežijí plné projednání, což jsou dvě víc než obvykle."],["Podejte jednu žádost obsahující všech dvacet devět.","Čtyři sta stránek, jeden nadpis, devět nesouvisejících otázek. Kancelář soudu ji vrátí s poznámkou, kterou si později dají zarámovat."]]},"b-unsigned":{"t":"Nepodepsané, neodůvodněné","x":"Předsedkyně Nejvyššího soudu Stoneová volá kvůli něčemu jinému než rozhodnutí. \"Dvacet tři z vašich dvaceti osmi šlo ve váš prospěch. Skoro žádné neřeklo proč. Soud, který se nezdůvodňuje, není soud, pane prezidente. Je to úřad, co razítkuje povolení.\"","c":[["\"To zní jako vnitřní záležitost soudu.\"","Je to vnitřní záležitost soudu, a soud v ní se sebou samým prohrává, potichu, veřejně, v poznámkách pod čarou, které si nikdo nepřečte, dokud na tom nezáleží."],["Veřejně požádejte o odůvodněná rozhodnutí u každého z nich.","Odůvodnění fungují oběma směry, a ta vaše vypadají na papíře hůř než ve vzduchu. Prohrajete dvě z příštích čtyř, a soudnictví si zpátky vezme něco, co mu unikalo."],["Neříkejte vůbec nic. Berte povolení.","Ticho je zadarmo a příkazy dál chodí. Stoneová napíše souhlasné stanovisko, které vždycky chtěla napsat, a přečtou si ho čtyři lidé."],["Nabídněte, že jim to odůvodnění napíšete sami.","Sepsané rozhodnutí se doveze soudu a vrátí se neotevřené, s formálním lístkem, což dopadne nějak hůř než pokárání."]]},"b-humphreys":{"t":"Devadesátiletý","x":"\"Právě jste odvolal úředníky ze čtyř agentur, které Kongres postavil přesně tak, abyste to nemohl udělat.\" Sy je téměř obdivně. \"Existuje případ z roku 1935, který říká, že nemůžete. Soud nechal stát každé jedno odvolání a ani jednou ho necitoval. Přehlasovává se to mlčením, pane. Tenhle trik ještě nikdo takhle čistě neviděl.\"","c":[["Pokračujte v odvolávání. Mlčení je nejužitečnější druh povolení.","Devět agentur za rok. Případ z roku 1935 technicky zůstává platným právem a necituje ho úplně nikdo, v ničem, nikdy víc."],["Požádejte je, ať to otevřeně a řádně přehlasují ve věci samé.","Případ přijmou a rozhodnou ve váš prospěch 6:3, s odůvodněním. Získáte tutéž moc plus desetiletí legitimity, kterou jste v úterý ještě neměl."],["Zastavte se u čtyř. Nechte zbytek být.","Čtyři vypadá jako série rozhodnutí. Devět by vypadalo jako politika. Jen jedno z toho se dá žalovat jako vzorec."],["Odvolejte úředníky a pak je znovu jmenujte, jen abyste zjistili, jestli to funguje.","Všichni čtyři se vrátí na stejné stoly s novým jmenováním a výrazně horší jistotou zaměstnání. Tři vám za to poděkují, což je na tom to nejznepokojivější."]]},"b-kagan-dissent":{"t":"Nesouhlasné stanovisko","x":"Bylo zveřejněno nesouhlasné stanovisko obsahující větu, která je teď na transparentech. Varuje, že nouzový docket se používá k přesunu pravomoci vlády z Kongresu na prezidenta. Kaylee: \"Pane, vytiskli to na plátěnou tašku. Dvakrát se vyprodala.\"","c":[["Útočte na autorku jmenovitě. Opakovaně.","Její příští nesouhlasné stanovisko je delší, ostřejší a přečtené nahlas přímo od soudního stolu, což neudělala devět let a teď to dělá pravidelně, díky vám."],["\"Nesouhlasná stanoviska jsou způsob, jak soud vede spor sám se sebou.\" Jděte dál.","Zacházet s tím jako s normální věcí je jediná reakce, která to normálním udělá. Za čtyři dny to zmizí z titulní strany, nikým neoplakáno."],["Ať to nejvyšší státní zástupce zodpoví v dalším podání.","Poznámka pod čarou odpovídající na nesouhlasné stanovisko je ta nejzavedenější věc, jakou vaše administrativa kdy udělala, a funguje přesně tak, jak zavedené věci fungují."],["Kupte si tu tašku. Nechte se s ní vyfotit.","Na zhruba devět dní to celou kauzu odzbrojí. Její kancelář to prý shledá velmi vtipným, ale to oficiálně nikdy nepotvrdí."]]},"b-marshal":{"t":"Maršálové","x":"Soudce nařídil něco, co nemáte v úmyslu udělat. Bo prověřil, jak to celé funguje. \"Soud nemá armádu. Vymáhání jde přes maršálskou službu. Maršálská služba odpovídá mému ministerstvu. Které odpovídá vám. Pane, upřímně bych si přál, abyste se mě na tohle neptal.\"","c":[["Řekněte maršálům, že se příkaz přezkoumává.","Nic se neodmítá a nic se nedělá. Čtyři bývalí soudci nezávisle na sobě napíší tentýž komentář a použijí totéž slovo: prázdné."],["Podřiďte se, pomalu, a zároveň se odvolejte.","Zdržování je poslušnost v rouše harmonogramu. Ztratíte čtyři měsíce a podržíte si to, na čem záleží, být stranou v případu, a ne jeho terčem."],["Podřiďte se úplně, hned dnes, a hlasitě to oznamte.","Uposlechnete příkaz, který nesnášíte, veřejně, okamžitě. Stojí vás to týden a kupuje vám dalších jedenáct rozhodnutí na úvěr."],["Požádejte maršály, ať příkaz doručí soudci.","Zástupce skutečně dojede k soudní budově, než ho někdo nadřízený stihne zastavit. Soudce kopii přijme s dokonalými způsoby a založí ji do spisu."]]},"b-facilitate":{"t":"Jedno slovo, jednomyslně","x":"Devět nula. Ne šest tři, ne pět čtyři, devět. Příkaz obsahuje přesně jedno sloveso: *usnadnit*. Muriel: \"V devět nula není žádný prostor pro spor, pane. Je tam jen to slovo. A naši i jejich právníci na tom, co znamená, stráví rok.\"","c":[["\"Usnadnit\" znamená nebránit. Nedělejte nic.","Slovo zvolené kvůli jednomyslnosti se ukáže jako slovo zvolené kvůli nejednoznačnosti. Nižší soud to přesně tak, písemně, dvakrát pojmenuje."],["Posaďte ho ještě tento týden na letadlo a je to hotovo.","Za jedenáct dní je po všem. Vaše základna to správně nazve kapitulací, a je to taky poslední den, kdy se ten případ vůbec dostane na titulní stranu."],["Vyjednejte převoz přes třetí zemi. Dejte si na to tři měsíce.","Cesta, která zachrání tvář a přitom splní příkaz, aniž by vznikla jediná fotka letadla. Diplomacie se vyplatí zhruba jednou za funkční období, a tohle je to jednou."],["Usnadněte to tím, že mu pošlete jízdní řád autobusu.","Vládní podání skutečně přiloží tištěný jízdní řád trasy, která nepřekračuje oceán. Je založeno do spisu jako důkaz C."]]},"b-sotomayor":{"t":"Věta v poznámce pod čarou","x":"\"Naše pozice v podání je, že rozhodnutí o odvolání není přezkoumatelné, tečka.\" Sy přestal číst nahlas. \"Nesouhlasné stanovisko poukazuje, že ta pozice ani jednou nepoužije slovo 'nestátní příslušník'. Podle vlastní teorie, pane, se to nezastaví u pasu.\"","c":[["Nechte podání tak, jak je. Ta teorie je aktivum.","Argument postavený pro jednu kategorii je teď na papíře pro všechny. Vašemu nástupci ho někdo citují zpátky v případu, jaký si tady nikdo nepředstavoval."],["Podání upravte. Napište tam slovo 'nestátní příslušník', čtyřicetkrát.","Omezující zásada dnes nic nestojí a ukáže se jako jediný důvod, proč doktrína přežije druhé desetiletí."],["Teorii úplně stáhněte. Argumentujte fakty.","Případ vyhrajete na faktech a prohrajete doktrínu. Sy to nazve správnou směnou a poprvé u toho není diplomatický."],["Přidejte poznámku pod čarou, slibující, že v praxi budete rozumní.","Podání nejvyššímu soudu v zemi obsahuje větu \"v praxi bychom to nedělali\". Čte se nahlas při ústním jednání. Pomalu."]]},"b-injunction-scope":{"t":"Procesní vítězství","x":"\"Vyhráli jsme.\" Bo nevypadá jako muž, který vyhrál. \"Omezili celostátní soudní zákazy. Jeden soudce už nemůže zmrazit politiku pro celou zemi. To je obrovské.\" Obrátí stránku. \"Je to taky čistě procesní. Neřekli, že politika je legální, a nelíbí se mi naše šance, až se k tomu dostanou.\"","c":[["Vyhlaste totální vítězství. Zaveďte to všude, okamžitě.","O čtrnáct měsíců později se dostanou k věci samé a zruší to poměrem 6:3. Každé zavedení se musí odčinit, a to odčiňování je celá ta kauza."],["Vezměte procesní vítězství. Zaveďte to jen tam, kde jste vyhráli.","Mapa záplat, které rozumí právníci a nikdo jiný. Ošklivé, obhajitelné, a přežije to."],["Pozastavte politiku, dokud se nerozhodne ve věci samé.","Zdrženlivost, za kterou nedostanete žádný kredit. Znamená to taky, že až prohrajete, prohrajete plán, ne už zavedený program."],["Oslavte procesní vítězství přehlídkou.","Vozy, kapela, transparent hlásající SOUDNÍ ZÁKAZ JE MRTEV. Jediná přehlídka v americké historii věnovaná procesnímu právu."]]},"b-framers":{"t":"\"Jen Kongres\"","x":"Šest ku třem, a předseda to napsal sám. Věta, kterou všichni citují, říká, že tvůrci ústavy tu pravomoc svěřili pouze Kongresu. Lyle: \"Dva vaši vlastní jmenovanci se přidali k většině, pane. Tohle není soud, co je politický. Je to soud, co je soudem, schválně, v tu nejhorší možnou dobu pro nás.\"","c":[["Napadněte soud. Řekněte, že ho ovládla druhá strana.","Útočíte na soud, který jste sám vybudoval, kvůli rozhodnutí sepsanému mužem, kterého jste osm let chválil. I vaše vlastní televize proti vám odvysílá časovou osu."],["Podřiďte se, a požádejte Kongres, ať cla schválí řádně.","Návrh zákona projde za dvě třetiny sazby, kterou jste chtěl, za devět měsíců, s přiloženým datem vypršení. Zato ho žádný soud už nikdy nezruší."],["Podřiďte se u tohoto zákona. Do pátku najděte jiný zákon.","Užší pravomoc, menší číslo, a žádné rozhodnutí, které byste porušoval. Lyle to nazve jedinou opravdu chytrou věcí, kterou letos kdokoli udělal."],["Zeptejte se, který tvůrce ústavy konkrétně, a žádejte, ať se ukáže.","Otázka jde písemně na úřad nejvyššího státního zástupce. Někdo tam, velkolepě, odpoví v plném rozsahu, s daty."]]},"b-vought":{"t":"\"Žádné nezávislé agentury neexistují\"","x":"Váš ředitel rozpočtu to řekl pro záznam, pěti slovy, bez vyzvání: žádné nezávislé agentury neexistují. Deborah: \"Pane, to je celá teorie jednotné exekutivy podaná jako pokrčení rameny. Devět generálních právních zástupců už volalo, jestli to bylo schválené.\"","c":[["Potvrďte to. Je to ta teorie a je to ten plán.","Vyslovit to nahlas promění právní argument v politický program a dá každému oponentovi jednu čistou větu, kolem které se dá zorganizovat."],["\"Popisoval odpovědnost, ne kontrolu.\"","Rozdíl bez jakéhokoli praktického obsahu, a přesně proto vydrží dva roky."],["Veřejně ho opravte. Některé agentury nezávislé jsou.","Oprava je upřímná a vlastní strana ji bere jako zradu. Čtyři komisaři si potichu přestanou aktualizovat životopisy."],["Udělejte z něj šéfa všech nezávislých agentur naráz.","Jedenáct souběžných dočasných ředitelství vede jeden muž s jedním diářem. Diář je předvolán a stane se nejzábavnějším dokumentem funkčního období."]]},"b-probationary":{"t":"Šestnáct tisíc","x":"Šestnáct tisíc zaměstnanců ve zkušební době, propuštěných podle šablony, za týden. Deborah má návazné informace. \"Jedna agentura se potichu pokusila přijmout zpátky čtyři sta z nich, protože se ukázalo, že dělali přesně to, kvůli čemu agentura existuje. Jedenáct dalších řeklo ne.\"","c":[["Žádné znovupřijímání. Nikde. Číslo je smysl toho všeho.","Počet zaměstnanců drží a čtyři zákonné funkce potichu přestávají fungovat. Nikdo si toho devatenáct měsíců nevšimne, a pak si toho všimnou všichni najednou."],["Ať agentury znovu přijmou, kde musí. Potichu.","Číslo v tiskové zprávě zůstává stejné. Lidé se vracejí zadními dveřmi na nové smlouvy. Obě věci jsou pravdivé, a jen jedna se dostane do zpráv."],["Zrušte to. Omluvte se těm čtyřem stům jmenovitě.","Vyjmenovat je je ta část, co zabírá. Dva z nich pláčou v přímém přenosu a šot se vysílá celý týden."],["Znovu je přijměte jako neplacené dobrovolníky.","Nabídkový dopis je skutečný a jde ke čtyřem stům lidí. Devět jich přijme, což je ta opravdu znepokojivá statistika v tomhle příběhu."]]},"b-usaid":{"t":"Agentura, která tu v pondělí ještě byla","x":"Muriel má seznam věcí, které se zastavily. \"Jedenáct klinik, čtyři zásobovací řetězce pro reakci na hladomor, chladicí řetězec pro vakcíny ve třech zemích. A dvě miliardy dolarů dlužných za už dokončenou práci, dodavatelé, kteří dodali, vyfakturovali a teď nás žalují. Pane, tu práci odvedli. To se nedá zpochybnit.\"","c":[["Nikomu neplaťte. Ať žalují.","Žalují a vyhrají, protože dokončená smlouva je dokončená smlouva všude kromě téhle budovy. Zaplatíte to stejně, později, s úroky a rozsudkem přišpendleným navrch."],["Zaplaťte dokončené faktury. Zrušte všechno budoucí.","Ctít minulost a přitom rušit budoucnost odstraní jediný argument, který u soudu vyhrával, a politicky vás to nestojí nic."],["Nechte agenturu být. Přejmenujte ji a snižte na polovinu.","Poloviční agentura s vaším jménem na dveřích odvede sedmdesát procent práce za padesát procent peněz a nevyvolá jediný spor."],["Nahraďte to celé horkou linkou.","Jedno číslo, obsluhované dvěma lidmi, pokrývající humanitární potřeby čtyřiceti zemí. První den zaznamená jedenáct tisíc hovorů."]]},"b-130-days":{"t":"Den sto třicet","x":"Roscoe Vandermeer si to počítá. \"Sto třicet dní je zákonný limit pro to, čím jsem. Dnes je sto dvacet šest.\" Usmívá se způsobem, kterému jste se naučil nedůvěřovat. \"Takže buď skončím, nebo se stanu něčím jiným, nebo prostě někdo přestane počítat.\"","c":[["Udělejte z něj stálého úředníka. Ať to vyžaduje cokoli.","Buď potvrzování, které nepřežije, nebo jmenování, o kterém se dva roky soudí. Vyberete si to druhé a soudí se to tři."],["Nechte čas doběhnout. Vřele mu poděkujte.","Odejde přesně sto třicátý den, a stroj, který postavil, běží dál bez něj, což vlastně nikdy nebylo plánem."],["Nechte ho tam i po limitu. Nikdo to nikdy nevymáhal.","Nikdo to skutečně nevymáhá, správně. Přesto se úplně všechno, co po sto třicátém dni podepíše, na tomto základě napadá, a čtyři z toho padnou."],["Vynulujte počítadlo tak, že mu dáte nové jméno.","Papírování se podá na muže s jiným prostředním iniciálem. Projde to. Letní stážista to objeví o devět měsíců později, v jedno ospalé úterý."]]},"b-doge-exit":{"t":"Rozkol","x":"Zvrtlo se to veřejně a rychle. On o vás zveřejnil čtyři příspěvky, vy o něm šest. Deborah ode dveří: \"Pane, on ví, kde je co uloženo. Osobně drží přístupové záznamy devíti ministerstev. Tohle není normální rozkol.\"","c":[["Eskalujte. Zveřejněte další příspěvek. Zrušte jeho smlouvy.","Začne dávat rozhovory s konkrétními daty. Ta data sedí, a to je ta část, na kterou vaši právníci nemají naprosto nic."],["Neříkejte už nic. Nechte to vyhořet.","Za jedenáct dní to vyhoří nedostatkem pozornosti. Ještě dvakrát zveřejní příspěvek do naprostého ticha a přestane."],["Zavolejte mu. Vyřešte to soukromě. Něco mu dejte.","Nákladný, nedůstojný, naprosto účinný telefonát. Nikdo se nikdy nedozví, co se na druhém konci vyměnilo."],["Jmenujte ho velvyslancem někam se špatným internetem.","Přijme okamžitě a, zdá se, upřímně. Místo má satelitní připojení a on ho najde do čtyř hodin."]]},"b-eo-count":{"t":"Sedm celá dva krát","x":"Deborah má číslo, které dnes ráno zveřejnil jeden think tank. \"Sto čtyřicet tři příkazů za sto dní. To je 7,2násobek historického průměru, víc než trojnásobek vašeho předchůdce. Pane, oni to nenazývají protiprávním. Nazývají to grafem.\"","c":[["Překonejte ten graf. Dvě stě do pátku.","Objem se stává úspěchem, takže kvalita potichu přestává být něčí povinností. Jedenáct nových příkazů si odporuje s předchozími a čtyři jsou na první pohled neproveditelné."],["Zpomalte na normální tempo. Ať ty stávající vydrží.","Konsolidace je neviditelná a trvanlivá. O dva roky později stále platí osmdesát procent vašich příkazů, číslo, kterého se žádná předchozí administrativa ani nepřiblížila."],["Držte tempo. Ať je právní tým nejdřív všechny prověří.","Sy najme devět lidí a míra rušení příkazů klesne o polovinu. Je to nejlevnější dostupná systémová oprava a nikdo si nevšimne, že se stala."],["Podepište výnos o počtu výnosů.","Výnos číslo 144 omezuje počet výnosů na 143. Je okamžitě 144., v rozporu sám se sebou, hned v den svého podpisu."]]},"b-recess":{"t":"Desetidenní okno","x":"Hal Grimes našel mezeru. \"Když komora přeruší zasedání na víc než deset dní, můžete kohokoli kamkoli jmenovat bez hlasování. Přerušení dokážu zařídit.\" Odmlčí se. \"Můžu ho taky nezařídit, a rád bych, aby bylo pro záznam poznamenáno, že jsem tuhle možnost zmínil.\"","c":[["Zařiďte to. Obsaďte jedenačtyřicet míst za jedno odpoledne.","Jedenačtyřicet úředníků bez hlasování za zády a trvanlivostí měřenou v soudních podáních. Největší jednorázový přesun jmenovací pravomoci za sto let."],["Použijte to jednou, pro to jedno místo, na kterém skutečně záleží.","Jedno jmenování, obhajitelné nutností, se kterým se nikomu nechce bojovat. Precedens si koupíte za cenu, kterou si opravdu můžete dovolit."],["Pošlete nominace. Nechte je hlasovat. Pár prohrajte.","Dvacet devět potvrzeno, dvanáct zamítnuto. Těch dvacet devět je do konce života nenapadnutelných, což se nakonec ukáže důležitější než těch dvanáct."],["Přerušte zasedání Kongresu sám a uvidíte, kdo namítne.","Existuje klauzule, která to lze argumentovat dovoluje, při neshodě mezi komorami. Žádná neshoda neexistuje. Vytvoříte si ji ještě před obědem."]]},"b-prosecutors-fired":{"t":"Ti, co měli ty případy na starosti","x":"\"Žalobci, kteří vedli případy nepokojů.\" Bo posune přes stůl seznam. \"Do posledního jednoho. A dvěma tisícům agentů byl rozeslán dotazník, přesně se ptající, na čem pracovali. Pane, tohle není personální proces. Tohle je sestavování seznamu, a každý, kdo ho dostane, to ví.\"","c":[["Propusťte je všechny. Rozešlete dotazník.","Zpráva dorazí přesně tak, jak měla. Čtyři sta agentů odmítne odpovědět, jedenáct rezignuje a úřad stráví další desetiletí náborem proti vzpomínce na tenhle týden."],["Přeložte je místo propuštění. Žádný dotazník.","Stejní lidé, jiné stoly, žádná papírová stopa. Dosáhne to celého cíle a vygeneruje přesně jeden odstavec mediálního pokrytí."],["Nechte je být. Žalobci žalují, co jim přistane na stole.","Ministerstvo, které se vás nebojí, jedná rychleji a při čtyřech příležitostech za toto funkční období pracuje ve váš prospěch. Nikdy se o tom nedozvíte."],["Pošlete dotazník nejdřív sám sobě.","Vyplníte ho celý, upřímně, vlastní rukou. Stane se to nejusvědčujícím dokumentem, jaký vaše administrativa kdy vyprodukuje."]]},"b-sanctions":{"t":"Zákon, který říká musí","x":"\"Kongres to schválil poměrem 98 ku 2. Nestojí tam 'může'. Stojí tam 'musí'.\" Lyle to položí. \"Pane, ministerstvo má sankční seznam připravený a hotový. Leží v šuplíku, a každý týden, co tam leží, je týden, kdy neplníme zákon.\"","c":[["Nechte to v šuplíku. Na neurčito.","Zákon schválený poměrem 98 ku 2 se prostě, potichu, neděje. Neexistuje mechanismus, jak to vynutit, a to je to zjištění, a není příjemné."],["Sankcionujte dva z jedenácti. Nazvěte to fázováním.","Částečné plnění je nevyvratitelné plnění. Dva předsedové výborů napíší rozzlobené dopisy a nikdo věrohodně nemůže tvrdit, že se zákon ignoruje."],["Vykonejte zákon v plném rozsahu. Je to zákon.","Jedenáct sankcí ještě před obědem. Stojí vás to zahraniční vztah, na kterém vám záleželo, a kupuje vám to Kongres, který přestane sledovat každý váš krok tak zblízka."],["Sankcionujte ten šuplík.","Sankci proti kartotéce skutečně jako vtip sepíše vyčerpaný úředník ve dvě ráno. Omylem se odešle."]]},"b-apology":{"t":"Omluva a knihovna","x":"Patnáct milionů dolarů, omluva ve vysílání a peníze mířící rovnou do vaší budoucí knihovny. Kaylee: \"Jejich vlastní právníci si mysleli, že vyhrají, pane. Přesto se dohodli, protože mají u téhle vlády jedenáct dalších nevyřízených záležitostí. O téhle části se bude psát.\"","c":[["Vezměte to. Požadujte, ať se omluva odvysílá dvakrát.","Odvysílá se dvakrát. Čtyři další média si tu transakci správně přečtou a začnou vyrovnávat věci, o které by dřív bojovaly do posledního dolaru."],["Vezměte peníze. Vzdejte se omluvy.","Hotovost bez obřadu je jen zlomek příběhu. Zároveň to odstraní ten jeden detail, který to celé vypadal jako rituální obětina."],["Odmítněte to. Dožeňte je k rozsudku.","Ve věci samé za devatenáct měsíců prohrajete. Odnesete si ale i něco, co si žádnou dohodou nekoupíte: postavení říct, že jste nikdy nevzal peníze."],["Přijměte platbu výhradně v reklamních slotech.","Patnáct milionů dolarů vysílacího času na síti, která vás pomluvila, naplánovaného jimi, vysílaného ve tři ráno, jedenáct měsíců v kuse."]]},"b-merger":{"t":"Fúze na stole","x":"Šestnáct milionů, žádná omluva, a šek je proplacen ve stejném týdnu, kdy jejich osmimiliardová fúze potřebuje podpis regulátora, kterého jste jmenoval. Kaylee velmi opatrně mlčí. Řekne to za ni Sy: \"Pane, nikdo nemusí dokazovat souvislost. Ten kalendář je ta souvislost.\"","c":[["Vezměte peníze. Schvalte fúzi. Ve stejném týdnu.","Dva legální akty, čtyřicet osm hodin od sebe, které každý jediný člověk v zemi vlastnící kalendář přečte jako jednu transakci."],["Vezměte peníze. Fúzi zdržte o čtyři měsíce.","Čtyři měsíce odstupu vás nic nestojí a celá kauza zmizí. Nejlevnější věc, kterou za celý rok uděláte."],["Zcela se z rozhodování o fúzi vylučte.","Písemné vyloučení, založené a veřejné. Fúze je přesto schválena, na základě svých vlastních kvalit, a není o čem psát."],["Schvalte fúzi a vezměte peníze v akciích.","Teď osobně vlastníte část společnosti, kterou jste právě schválil. Čtyři etičtí úředníci rezignují za jediné odpoledne, rekord, který dodnes drží."]]},"b-license":{"t":"Pět dopisů","x":"Váš regulační úřad zahájil nebo pohrozil kontrolami týkajícími se pěti vysílatelů, včetně obou veřejnoprávních stanic. Ani jedna nebyla uzavřena. Deborah: \"To je záměr, pane. Kontrola, která se nikdy neuzavře, je ruka na rameni, která nikdy nezvedne.\"","c":[["Otevřete čtyři další. Veřejně řekněte, že licence by měly být v ohrožení.","Nic se ve skutečnosti nikdy neodejme. Každá zúčastněná redakce přidá na ranní poradu právníka, a ranní porada je teď místo, kde kauzy umírají."],["Nechte kontroly běžet. Už se o nich nikdy nezmiňujte.","Nezmiňovaný tlak funguje líp než oznámený tlak, protože nezbývá nic, proti čemu by se dalo sjednotit."],["Uzavřete všech pět. Veřejně.","Uzavření je zprávou na jeden den. Mrazivý efekt trvá zhruba čtyři měsíce, než roztaje, a nikdy úplně."],["Zažádejte sám o licenci.","Žádost je podána řádně a zařadí se do fronty za pět kontrol, které jste sám osobně spustil. Váš vlastní regulátor teď o ní musí rozhodnout."]]},"b-global-media":{"t":"Vysílače","x":"\"Mezinárodní služby.\" Muriel zvedne vysílací plán. \"Jedenáct jazyků, čtyři z nich do zemí, kde nikdo jiný nevysílá nic pravdivého. Když to zrušíme, pane, frekvence nezmlkne. Do čtvrtka na ní bude vysílat někdo jiný.\"","c":[["Zrušte to celé. Není naší povinností vysílat do zahraničí.","Čtyři frekvence obsadí do měsíce služby, které jsou nesmírně, veřejně potěšené. Nejlevnější strategický dárek celého funkčního období."],["Zrušte anglické služby. Ponechte jedenáct jazyků.","Domácí úspory jsou reálné, strategické aktivum přežije, a nikdo, komu záleželo na kterékoli straně, není plně spokojen."],["Financujte to naplno. Dejte na záhlaví své jméno.","Vaše jméno nad redakčně nezávislou službou, která do dvou let odvysílá o vás něco, co budete opravdu nenávidět."],["Nahraďte všech jedenáct služeb jedním podcastem.","Nahrává se ve sklepě, jen v angličtině, a stane se opravdu docela populárním ve dvou zemích, které s ním už tak souhlasily."]]},"b-pool-slot":{"t":"Židle, co tam vždycky byla","x":"\"Místo pro agenturní zpravodaje je v tom výběru novinářů od dob před naším narozením.\" Kaylee se s vámi vlastně ani nehádá. \"Je to místo, které dělá z toho výběru výběr, a ne seznam pozvaných. Odstraňte ho, pane, a z výběru se stane něco, co skládáte ručně.\"","c":[["Odstraňte ho. Výběr sestavujeme my.","Místo se už nikdy nevrátí, ani za vás, ani za nikoho po vás. Nejtrvalejší věc, jakou tisku uděláte, a stačí na to jeden pokyn."],["Nechte to místo být. Střídejte, kdo v něm sedí.","Instituce přežije; osoba v ní se stává rozhodnutím, které týdně obnovujete. Většina moci, žádný boj."],["Nechte výběr přesně tak, jak byl vždycky.","Nic se nestane, což je fungující uspořádání pro tisk, a tudíž to není kauza nikde na světě."],["Nahraďte to místo skutečným křeslem.","V první řadě je nainstalováno kožené ušáku. Nikdo se v něm nemůže nechat vyfotit, aniž by nevypadal směšně, což byl, po zvážení, celý smysl."]]},"b-own-appointee":{"t":"Váš vlastní soudce","x":"Soudní zákaz obnovující přístup agenturního zpravodaje vydal soudce, kterého jste jmenoval. Sy si přečte poslední řádek dvakrát. \"Byl na vašem vlastním užším seznamu, pane. Osobně jste ho pohovorem prověřoval. Napsal devět stran o diskriminaci názorů a v ani jedné z nich se nemýlí.\"","c":[["Napadněte ho. Řekněte, že to byla chyba.","Tu větu si přečte každý soudce, kterého jste kdy jmenoval. Čtyři z nich do roka rozhodnou proti vám a toho vzorce si všimne úplně každý."],["Podřiďte se bez komentáře. Je to dobrý soudce.","Zdrženlivost vás stojí den vzteku a kupuje vám benefit pochybnosti v jedenácti pozdějších případech. Nejlepší obchod na stole, a po celou dobu je to k nesnesení."],["Odvolejte se. Vybojujte částečné odložení. Nikdy se o něm nezmiňte.","Částečné odložení je částečné vítězství a nevyprodukuje citovatelnou větu v žádném směru, což byl celou dobu jediný cíl."],["Povyšte ho někam, kde nejsou žádné případy s tiskem.","Povýšení odmítne dvouřádkovým dopisem a zůstane přesně tam, kde je, projednávajíc přesně tyto případy, dalších jedenáct let."]]},"b-gasoline":{"t":"\"Benzín\"","x":"Organizace sledující svobodu tisku použila slovo benzín, plus frázi \"koordinovaná válka proti svobodě tisku od prvního dne v úřadu\". Kaylee: \"Není to nepřátelské médium, pane. Řadí sto osmdesát zemí, a loni jsme se umístili na sedmapadesátém místě.\"","c":[["Odmítněte je jako zahraniční lobbistickou skupinu.","Útok na toho, kdo počítá skóre, skóre nezmění. Klesnete o dalších sedm míst a ten pokles se sám stane dalším titulkem."],["Neříkejte nic. Žebříčky jsou žebříčky.","Ignorování žebříčku ho připraví o domácí spor, který by z něj doma udělal zprávu. Vyjde v zahraničí a jinde potichu zapadne."],["Obnovte místo pro agenturního zpravodaje a uzavřete dvě kontroly. Potichu.","Následující rok stoupnete o čtyři místa. Nikdo na vaší vlastní straně se nikdy nedozví, že jste s tím něco udělal, a přesně proto to bylo možné."],["Zveřejněte vlastní žebříček. Sebe umístěte na první místo.","Sekce o metodologii má jednu jedinou větu. Čtyři země žádají o zařazení a tři z nich jsou uraženy tím, kam se umístí."]]},"b-nonprofit":{"t":"Kontrola statusu","x":"\"Čtyři organizace, které vedou kampaň proti vám, mají status veřejné prospěšnosti.\" Lyle to řekne bez okolků. \"Prověřit to je legální. Oznámit, že to prověřujeme, je taky legální. Pane, ta druhá část je celá ta zbraň, a nic nás nestojí ji vypálit.\"","c":[["Oznamte kontroly u všech čtyř. Dnes.","Ani jedna nepřijde o status. Všechny čtyři přijdou o dárce, protože dárce přispívá na věc, ne na právní argument, a to už ví každý fundraiser v zemi."],["Zahajte jednu tichou kontrolu u té, kde jsou skutečné nesrovnalosti.","Opravdový případ, vedený běžným způsobem, který skončí opravdovým zjištěním. Nenapadnutelný přesně proto, že je nudný."],["Nařiďte úřadu, ať politické skupiny nechá naprosto na pokoji.","Písemná politika nezasahování, která zavazuje vaše nástupce hned vedle vás. Nejzávažnější pokyn celého funkčního období."],["Udělte status veřejné prospěšnosti vlastní kampani.","Žádost popisuje deklarovaný veřejně prospěšný účel jako \"podporu obecného dobra, obecně\". Schválí ji někdo, kdo později nedokáže vysvětlit proč."]]},"b-memecoin-collapse":{"t":"Devadesát sedm procent","x":"Token vyvrcholil na patnáctimiliardovém nominálním ocenění a teď má hodnotu asi čtyři sta milionů. Lyle: \"Na cestě nahoru jste si vzal emisní i transakční poplatky, pane, takže vás se to osobně netýká. Zhruba dvě stě tisíc lidí, kteří nejste vy, se to týká extrémně.\"","c":[["Řekněte, že trh je trh. Spusťte druhý token.","Druhý token se chová identicky jako první. Teď je to vzorec místo incidentu, a vzorec je přesně to, k čemu existují regulátoři."],["Neříkejte o tom už vůbec nic.","Za šest týdnů to vypadne ze zpráv, protože chybí čerstvý citát od vás. Ztráty odnikud nevypadnou."],["Odškodněte deset tisíc nejmenších držitelů z vlastní kapsy.","Stojí to majlant a kupuje to něco jinak nekoupitelného: jednu důvěryhodnou větu o tom, že jste udělal slušnou věc."],["Znovu ho spusťte na staré ceně vyhláškou.","Prohlášení stanoví hodnotu soukromého tokenu na jeho bývalém vrcholu. Trh s tím nesouhlasí do devíti vteřin a nesouhlasí dál."]]},"b-dinner":{"t":"Nejlepších dvě stě","x":"Miriam Applewhitová drží seznam hostů na délku paže. \"Kritériem pro pozvání je, kolik vašeho tokenu kdo vlastní. To je celé kritérium. Pane, neexistuje způsob, jak to popsat, aby to nevypadalo jako prodej večera s prezidentem.\"","c":[["Uspořádejte to. Dvě stě dvacet hostů. Fotografie.","Čtyři z hostů se ukážou být cizí státní příslušníci s nevyřízenými záležitostmi u téhle vlády, neprověření, protože jediným kritériem byla peněženka."],["Uspořádejte to. Nejdřív každého hosta prověřte. Zveřejněte seznam.","Jedenáct jmen je při prověrce potichu vyškrtnuto. Zveřejněný seznam působí nudně, a nudný seznam není kauza."],["Zrušte to. Odčiňte to podezření.","Zrušení je samo o sobě přiznáním a přesně tak se to i podá. Přesto levnější, než by byly ty fotografie."],["Uspořádejte večeři, ale nezúčastněte se jí.","Dvě stě dvacet lidí sní vynikající jídlo v pronajatém sále, čelíc prázdné židli s jmenovkou."]]},"b-stablecoin":{"t":"Dvě miliardy","x":"\"Suverénní fond vkládá dvě miliardy dolarů do stablecoinu a ten stablecoin provozuje firma s jménem vaší rodiny na dveřích.\" Lyle pečlivě volí slova. \"Poplatek z toho činí zhruba sto milionů ročně. Vám. Od nich. Za naprosto nic.\"","c":[["Vezměte to. Je to obchodní ujednání.","Je to obchodní ujednání tak, jako je paušální honorář obchodní ujednání. Čtyři výbory otevřou spisy a ani jeden z nich nedokáže pojmenovat skutečný trestný čin."],["Vezměte to. Veďte to přes slepou strukturu.","Struktura je opravdu slepá a přitom úplně dohledatelná, protože dvoumiliardový vklad se ve skutečnosti ukrýt nedá."],["Odmítněte to, dokud jste v úřadu.","Odmítnete sto milionů dolarů ročně, a věta \"on to odmítl\" se stane nosnou konstrukcí ve čtyřech skandálech, které teprve přijdou."],["Přijměte to v jejich měně a odmítněte směnit.","Dvě miliardy dolarů dorazí v denominaci s týdenním exportním limitem. Přesun trvá devět let a stále trvá."]]},"b-927":{"t":"Devět set dvacet sedm stran","x":"Přiznání majetku má 927 stran. Miriam si je přečetla všechny, což na světě neudělá nikdo jiný. \"Dva celé dvě miliardy zisku za rok, pane. Jedna celá čtyři z toho z tokenů. Všechno je to přiznané. To je ta obhajoba, a je dobrá, a je to taky celý příběh.\"","c":[["Zveřejněte to v pátek v pět odpoledne a neříkejte nic.","Čtyři novináři si to přesto o víkendu přečtou, protože 927 stran je pro tenhle konkrétní druh lidí výzva, ne odstrašení."],["Zveřejněte to na tiskové konferenci. Projděte to s nimi.","Dvě hodiny otázek, všechny zodpovězené. Nejhorší odpoledne roku, a zabije to kauzu v tom jediném odpoledni."],["\"Vydělávají na tom všichni. Trh roste.\"","Tahle věta se čtrnáct dní objevuje vedle toho čísla. Stane se nejcitovanější větou vašeho prezidentství, a myslel jste každé slovo vážně."],["Zveřejněte to jako audioknihu, kterou nahrajete vy sám.","Padesát jedna hodin. Umístí se v žebříčcích. Někdo si to celé poslechne a najde nesrovnalost na straně 611, na kterou by jinak na celé planetě nikdo nepřišel."]]},"b-shutdown-two":{"t":"Druhé odstavení vlády","x":"Den dvacet devět. Lyle přestal odhadovat konec. \"Čtyři agentury běží na penězích, které jsme přesunuli z míst, kam je Kongres výslovně určil. Potřebuji, abyste pochopil, pane, že to přesunutí je ta protiprávní část. Ne to odstavení samo.\"","c":[["Pokračujte v přesunu peněz. Řiďte vládu z rezidence.","Vláda dál funguje, financovaná prezidentem místo rozpočtu. Nejčistší možná odpověď na to, čím se tenhle úřad potichu stal."],["Přesouvejte peníze jen na výplaty a bezpečnostní funkce.","Obhajitelná nouzová hranice, kterou přijmou čtyři soudy a jeden ne. Řídící letového provozu dostanou zaplaceno a politické hodiny se zastaví."],["Přijměte dohodu, co leží na stole. Ukončete to dnes večer.","Dohoda je horší než ta, kterou jste odmítl čtvrtý den. Pětadvacet dní nekoupilo naprosto nic, což je obvyklý výsledek tohohle konkrétního tahu."],["Vyhlaste odstavení vlády národním svátkem.","Osm set tisíc lidí je informováno, že jejich nucené volno je teď oslava. Čtyři agentury se vyzdobí. Je to ponuré a je to důkladně zdokumentované."]]},"b-wall-money":{"t":"Přeprogramování","x":"Tarrant má seznam toho, co se zastaví, pokud se peníze přesunou. \"Škola na základně v Kentucky. Nemocniční křídlo v Německu. Kasárna ve čtyřech státech.\" Odloží ho. \"Přesunu to ve chvíli, kdy mi to nařídíte. Rád bych, aby ten seznam byl u toho pro záznam.\"","c":[["Přesuňte je. Všechny. Seznam jde do šuplíku.","Škola se nepostaví. O devět let později stále není postavená a stále je na seznamu, který kentucký kongresman nahlas přednáší v plénu každý březen."],["Přesuňte polovinu. Nechte školu a nemocnici na pokoji.","Volba, které projekty zemřou, je celý rozdíl mezi politikou a osobní zlobou, a Tarrant zajistí, aby ta volba byla zdokumentovaná."],["Nepřesouvejte je. Postavte, co bylo schváleno.","Devadesát mil toho, co jste slíbil, plus škola, nemocniční křídlo a čtvery kasárna. Fotka, kterou nikdo nechce, aby ho přistihli, jak fotí."],["Přesuňte peníze a pojmenujte zeď po té škole.","Pamětní deska ctí vzdělávací zařízení, které bylo zrušeno, aby zaplatilo za tu desku. Je nainstalována. Pozoruhodně tam pořád je."]]},"b-crime-emergency":{"t":"Nouzový stav kvůli kriminalitě","x":"Duane Krisp má ten příkaz. \"Zestátní jak Gardu okrsku, tak jeho policejní sbor. Obojí. Pane, čísla kriminality klesla meziročně o dvaadvacet procent. Je to v našem vlastním brífinku. Na jeho první straně.\"","c":[["Podepište to. O čísla nejde.","Městský policejní sbor teď odpovídá prezidentovi. Dvakrát se to prodlouží, stojí to třetinu miliardy dolarů, a čísla kriminality dál klesají přesně stejným tempem jako vždycky."],["Zestátněte jen Gardu. Policii nechte na pokoji.","Polovina příkazu a čtvrtina pobouření. Policejní ředitelka si podrží svůj velitelský řetězec a přesto vás potichu informuje."],["Žádný nouzový stav. Místo toho financujte vlastní městský sbor.","Kriminalita klesne o dalších devět procent a starostka vám na kameru poděkuje, což vašemu hnutí nepřinese nic, ale vám osobně docela dost."],["Vyhlaste nouzový stav kvůli kriminalitě kvůli samotným číslům kriminality.","Prohlášení označí klesající čísla samotná za podezřelá. Statistička na úřadu justičních statistik rezignuje e-mailem ve čtyři ráno."]]},"b-332":{"t":"Tři sta třicet dva milionů","x":"Menšinový štáb výboru vyčíslil nasazení na 332 milionů dolarů do února. Lyle: \"Je to odhad, a přiznají to. Je to ale taky jediné číslo, které kdokoli vyprodukoval, pane, takže teď je to prostě to číslo.\"","c":[["Zpochybněte to číslo. Nepředložte žádné vlastní.","Zpochybnění čísla bez nabídnutí jiného nechá to původní stát, s přišroubovaným slovem \"zpochybněno\", což nemění vůbec nic."],["Zveřejněte skutečné náklady. Jsou nižší.","Je to 291 milionů dolarů, což je nižší i tak obrovské zároveň. Oprava je přesná, a nepomůže to ani trochu."],["Ukončete nasazení. Odvolejte se na náklady.","Stažení z fiskálních důvodů je jediný odchod, který nepůsobí jako ústup. Nabízí se to zhruba šest dní, a vy to využijete."],["Naúčtujte to městu.","Faktura na 332 milionů dolarů je odeslána městské vládě s ročním rozpočtem menším než to číslo. Její finanční ředitel si ji dá zarámovat."]]},"b-quick-reaction":{"t":"Specializovaná jednotka","x":"\"Specializovaná jednotka, plus stálá národní síla rychlé reakce na občanské nepokoje.\" Tarrant si to přečetl čtyřikrát. \"Pane, stálá síla s domácím posláním je úplně jiné zvíře než nasazení. Nasazení skončí. Tohle je věc, která prostě existuje.\"","c":[["Zřiďte ji. Celostátně. Natrvalo.","Trvalá federální síla pro domácí nepokoje, v pohotovosti, navěky. Čtyři penzionovaní generálové napíšou společný dopis, a to je ta nejmírnější reakce, kterou dostanete."],["Zřiďte jednotku. Bez stálé národní síly.","Schopnost bez stálého poslání je nástroj, ne postoj. Tarrant tuhle verzi podepíše bez zaváhání, které měl u té druhé."],["Ani jedno. Garda existuje a odpovídá guvernérům.","Stávající uspořádání funguje, protože ho navrhli lidé, kteří to skutečně promysleli. Za systém, který prostě pokračuje, nikdo nikomu neděkuje."],["Zřiďte ji a obsaďte ji výhradně vojenskými hudebníky.","Čtyři sta hudebníků je přeloženo k úkolům potlačování občanských nepokojů. Podle všech následných svědectví to zvládají znepokojivě disciplinovaně."]]},"b-state-guard":{"t":"Guvernérka řekne ne","x":"Guvernérka Vasquez-Mooreová odmítla písemně a dopis zveřejnila. \"Její Garda, její stát, její rozhodnutí, dokud ji nezestátníte, a od té chvíle je vaše a ona je jen divák.\" Tarrant dodává: \"Pane, jsou to stejní vojáci tak i tak. Mění se jen hlavička dopisu.\"","c":[["Zestátněte je. Její námitka je zaznamenána a irelevantní.","Do čtyř hodin podá žalobu. Ať dopadne jakkoli, každý guvernér v zemi teď ví, že jedinou věcí, co je kdy chránila, byla ta hlavička."],["Zestátněte Gardu jiného státu a pošlete ji tam.","Vojáci z jednoho státu udržující pořádek v jiném, přes námitky obou guvernérů. Legální, bezprecedentní, a fotografie obletí celý svět."],["Přijměte její odmítnutí. Místo toho nabídněte federální financování.","Vezme si peníze a vyřeší to sama, kompetentně, za devět dní. Nedostanete žádné uznání a žádnou žalobu, naprosto férová směna."],["Zestátněte tu guvernérku.","Právního poradce se vážně zeptají, jestli lze zestátnit osobu. Odpovědní memorandum má čtyři slova a jedno z nich je \"ne\"."]]},"b-poll-worker":{"t":"Okresní komise","x":"\"Certifikace je funkce státu. Provádí ji okresní komise, dobrovolníci, penzionovaní učitelé, chlapík, co opravuje kotle.\" Bo je nesvůj. \"Můžeme zahájit federální šetření proti kterémukoli z nich. Ne kvůli obžalobě. Prostě jen aby se jim to dělo, ve čtyřech týdnech před certifikací.\"","c":[["Zahajte šetření v jedenácti nejtěsnějších okresech.","Nikdo není obžalován. Čtyři komise úplně ztratí kvorum, protože dobrovolníci raději rezignují, než by byli vyšetřováni, a kvorum je přesně to, co certifikace vyžaduje."],["Zahajte jedno, tam, kde je skutečné podání.","Skutečný případ, vedený normálně. Skončí po certifikaci a odhalí administrativní chybu, což skoro vždycky bývá výsledek."],["Místo toho pošlete pozorovatele. Žádná šetření.","Federální pozorovatelé jsou stará, nudná instituce, kterou obě strany používají šedesát let. Nikdo nerezignuje a všechno se certifikuje včas."],["Zestátněte toho chlapíka od kotlů.","Devět dní před certifikací mu je nabídnuto federální jmenování. Odmítne, certifikuje a poté poskytne jeden nesmírně suchý rozhovor."]]},"b-fisa":{"t":"Obnovení","x":"Errol Hance má obnovení zmocnění. \"Míří to do zahraničí. Vedlejším produktem je ale rozsáhlý sběr dat o Američanech, a pravidla pro dotazování se nastavují interně.\" Počká. \"Mnou. Což v praxi znamená vámi, a jediné, co stojí mezi těmi dvěma větami, je formulář.\"","c":[["Uvolněte pravidla dotazování. Rozšiřte kategorie.","Domácí dotazy do roka vzrostou jedenáctinásobně. Zpráva o dodržování předpisů, která to dokazuje, je utajena, založena a přečte si ji celkem devět lidí."],["Nechte pravidla být. Obnovte to beze změny.","Nudné obnovení nudného zmocnění. Errol je viditelně ulevený, což je nejvíc informací, které vám kdy dobrovolně sdělil."],["Zpřísněte je. Vyžadujte soudní příkaz pro domácí dotazy.","Stojí to agentury čtyři dny pracovního postupu a kupuje to zmocnění dalších dvacet let politického přežití. Errol to napíše, vděčně, písemně."],["Zadejte dotaz sám na sebe a uvidíte, co se vrátí.","Poněkud víc, než jste čekal. Už se o tom nikdy nezmíníte, stejně jako nikdo v místnosti, a záznam v protokolu zůstává přesně tam, kde je."]]},"b-ai":{"t":"Model","x":"\"Ta data držíme legálně. Všechna, odděleně, z oddělených důvodů.\" Errol otočí notebook. \"Novinkou je, že model to teď dokáže přečíst všechno naráz a říct vám, kdo pravděpodobně něco zorganizuje. Pane, na tohle nikdo nenapsal žádné pravidlo, protože nikdo nevěřil, že to skutečně bude fungovat.\"","c":[["Spusťte to. Celostátně. Dejte mi ten seznam.","Jedenáct tisíc jmen, seřazených podle čísla, které nikdo nedokáže vysvětlit, ani lidé, kteří to postavili. Čtyři sta z nich jsou novináři."],["Spusťte to jen na zahraničních sítích. Domácí data oddělte firewallem.","Firewall je skutečný a drží přesně tak dlouho, dokud je někdo placen za jeho udržování. Errol zařídí, aby ten někdo zůstal placený, jedenáct let."],["Nestavte to. Napište pravidlo, které to zakazuje.","Pravidlo má čtyři odstavce a je to důvod, proč tahle schopnost v roce 2040 stále neexistuje. Nikdo se nikdy nedozví, že to byla volba."],["Zeptejte se modelu, kdo by podle něj měl být prezidentem.","Odpoví okamžitě, s naprostou jistotou. Odpověď nejste vy. Přepis je zničen a dvakrát rekonstruován."]]},"b-margins":{"t":"Padesát tři, čtyřicet sedm","x":"Hal má aritmetiku na ubrousku. \"Padesát tři, čtyřicet sedm v Senátu. Dvě stě dvacet, dvě stě patnáct tady, a mezera se zužuje pokaždé, když někdo zemře. Obstrukce je nedotčená. Pane, máte plnou trojici, a plná trojice není totéž co většina, která skutečně dokáže něco prosadit.\"","c":[["Tak nic nelegalizujte. Dělejte to všechno příkazy.","Nic, co vybudujete, nemá pod sebou zákon, takže to celé může za jedno odpoledne smazat kdokoli, kdo přijde po vás. Víte to, a přesto to děláte."],["Věnujte funkční období čtyřem návrhům zákonů. Skutečným zákonům.","Dva projdou. V roce 2049 jsou pořád platné, což trvá zhruba dvacetkrát déle než cokoli jiného, čeho se dotknete."],["Zrušte obstrukci.","Čtyři vaši vlastní senátoři veřejně odmítnou, přímo v plénu. Poprvé za toto funkční období vám vlastní strana řekne ne a skutečně to tak myslí."],["Místo toho vezměte přísahu od těch dvě stě patnácti jako poradců.","Dopisy jdou celému opozičnímu klubu s nabídkou neplacených poradních rolí. Devět jich přijme, čistě ze zvědavosti, a nikdy nedostanou jedinou věc, ke které by se měli vyjádřit."]]},"b-abdication":{"t":"\"Přihlížel a nic nedělal\"","x":"Doktorka Weirová má studii. \"Argument není, že Kongres byl poražen. Je, že Kongres se rozhodl neúčastnit.\" Ta fráze zní 'přihlížel a nic nedělal'. Zvedne oči. \"Pane prezidente, tahle studie je o vašich odpůrcích, ne o vás, a je pro vás výrazně horší, než by byla studie o vás.\"","c":[["Rozešlete ji. Zarámujte ji. Je to kompliment.","Čtyři členové si přečtou svou vlastní nečinnost popsanou akademicky, chladným tiskem, a vůbec se jim to nelíbí. Dva začnou skutečně chodit na slyšení."],["Neříkejte nic. Akademická studie je akademická studie.","Za pět let je citována devětsetkrát a v téhle budově se o ní nikdy ani slovem nezmíní, což je přesně, jak tyhle věci obvykle dopadají."],["Pozvěte předsedy výborů. Dejte jim něco na dohled.","Nepřátelskému výboru předáte čtyři skutečné dokumenty. Dohled se obnoví, je únavný a chrání vás před devíti pozdějšími obviněními."],["Ať Kongres schválí rezoluci popírající, že nic nedělá.","Projde 388 ku 41. Je to jediná věc, kterou komora za celý týden udělá, což si náležitě všimne úplně každý, kdo o tom informuje."]]},"b-article-48":{"t":"Srovnání v poznámce pod čarou","x":"Doktorka Weirová má článek z právnického časopisu. \"Argumentuje, že vaše nouzové zákony fungují jako americká obdoba otevřeného nouzového článku, a konkrétně jmenuje ten výmarský.\" Zavře ho. \"Autor je opatrný. Ta poznámka pod čarou není obvinění. Je to varování před tou architekturou.\"","c":[["Napadněte autora. Nazvěte to srovnáváním s nacisty.","Článek za čtrnáct dní vyroste ze čtyř tisíc čtenářů na čtyři sta tisíc, a poznámka pod čarou je teď titulek."],["Ignorujte to. Je to právnický časopis.","Přečte si to devět lidí, a jeden z nich je senátní zaměstnanec, což je přesně, jak se z poznámky pod čarou stane za zhruba tři roky návrh zákona."],["Požádejte Kongres, ať k nouzovým zákonům přidá doložky o vypršení platnosti.","Doložky projdou. Každá nouzová pravomoc, kterou teď máte, vyprší k danému datu, včetně těch, na kterých jste potichu stavěl, a podepsal jste to sám."],["Vyhlaste nouzový stav kvůli tomu srovnání.","Prohlášení číselně cituje přímo ten článek, se kterým je srovnáváno, hned ve své vlastní sekci právních pravomocí. Doktorka Weirová si to dá zalaminovat."]]},"b-emergency-stack":{"t":"Čtyřicet jedna aktivních nouzových stavů","x":"\"V platnosti je aktuálně čtyřicet jedna národních nouzových stavů.\" Sy je spočítal. \"Třicet čtyři existovaly ještě před vámi. Jeden se obnovuje každý rok od roku 1979, a země, které se týká, se teď jmenuje jinak. Pane, tyhle nikdo nekontroluje. Prostě se rok za rokem obnovují, na autopilota.\"","c":[["Obnovte je všechny. Přidejte dalších šest.","Čtyřicet sedm souběžných nouzových stavů, každý odemyká pravomoci, které nikdo nikdy neprověřil. Nejmocnější věc v téhle budově, a je udělaná čistě z papírování."],["Obnovte je. Ten z roku 1979 potichu zrušte.","Zrušení mrtvého nouzového stavu nic nestojí a stručně se o tom napíše jako o vzácném záchvatu pořádkumilovnosti."],["Prověřte všech čtyřicet jedna. Zveřejněte, které jsou skutečné.","Prověrku přežije jedenáct. Dobrovolně jste se vzdal třiceti souborů trvalých pravomocí, a vaši nástupci vám za to taky nepoděkují."],["Sloučit všech čtyřicet jedna do jednoho velmi velkého nouzového stavu.","Jediné prohlášení pokrývající úplně všechno od íránských aktiv po invazní brouky. Sy tomu říká \"ten souhrnný\" a odmítá to dál rozvádět."]]},"b-education-injunction":{"t":"Poloviční soudní zákaz","x":"Bernadette Ollisová má rozhodnutí. \"Blokuje tu část, která přesouvá portfolio studentských půjček. Neblokuje tu část, která zavírá jedenáct regionálních kanceláří. Takže ministerstvo technicky pořád existuje, pane, jenže v Denveru už nikoho nemá.\"","c":[["Zavřete všechno, co soudní zákaz nejmenoval.","Ministerstvo, které existuje na papíře a nezvedá žádné telefony. Čtyři státy si zřídí vlastní úřady, aby tu práci dělaly, a naúčtují to federální vládě."],["Podřiďte se úplně. Pozastavte celé rušení.","Pozastavit všechno, zatímco se o jedné části soudí, je to, co by udělala normální administrativa, a obě strany to berou jako přiznání porážky."],["Zavřete kanceláře. Odvolejte se ohledně portfolia půjček.","Vezmete si vítězství, které vám bylo dáno, a o zbytek se řádně soudíte. Nudné, legální, a za čtrnáct měsíců to přinese většinu toho, co jste chtěl."],["Přesuňte celé ministerstvo do Denveru.","Jedenáct set zaměstnanců je vyzváno k přestěhování do té jedné kanceláře, kterou jste se právě pokusil zavřít. Čtyři sta rezignuje, což si každý potichu uvědomoval, že je ten mechanismus."]]},"b-anticipatory":{"t":"Nikdo jim nevolal","x":"Doktorka Weirová má seznam čtyř institucí, které tento měsíc změnily svou politiku. \"Firma, univerzita, studio, banka.\" Odloží ho. \"Pane prezidente, ani jednu z nich nikdo nekontaktoval. Ani jednu. Existuje na to název, je to preventivní poslušnost, a je to nejlevnější moc, jaká existuje.\"","c":[["Neříkejte nic a nechte to šířit.","Za čtvrtletí se skloní dalších devět institucí, úplně bez podnětu, a není co napadnout, protože žádný příkaz nikdy neexistoval."],["Veřejně jim řekněte, že je o to nikdo nežádal.","Dvě ze čtyř do týdne otočí. Vyslovit to nahlas je jediná věc, která to kdy zlomí, a stojí vás to celý ten mechanismus."],["Vřele je pochvalte jmenovitě.","Pochvala je přesně to potvrzení, na které čekaly další čtyři instituce. Účinnější než jakákoli hrozba, a nedá se to jako hrozba ani popsat."],["Požádejte je všechny, ať uposlechnou něco, co jste si ještě nevymyslel.","Vyjde prázdná instrukce. Dvě organizace ji písemně splní, a nikomu, ani jim samotným, není vůbec jasné, s čím přesně vlastně souhlasily."]]},"b-university-out":{"t":"Univerzita, kterou požádali, aby odešla","x":"Ollisová si četla, jak to udělali jinde. \"Nikdo tu univerzitu nezavřel. Změnili akreditační pravidlo a vízové pravidlo, a univerzita odešla sama, a každý zúčastněný mohl pravdivě říct, že nic nezavřel.\" Zvedne oči. \"Tady bychom to mohli udělat do čtvrtka.\"","c":[["Změňte obě pravidla. Nechte je, ať se sami rozhodnou odejít.","Do roka se přestěhují do jiné země. Žádný příkaz nebyl podepsán, nic nebylo zakázáno, a není co odvolávat, protože nikdy nebylo o čem rozhodnout."],["Změňte jen vízové pravidlo.","Dost tření, aby to bylo cítit, ne dost, aby to bylo smrtelné. Nábor akademiků klesne o třicet procent a nikdy o tom nikdo nenapíše."],["Ani jedno. Místo toho na ně útočte v projevech.","Rétorika nic nepohne a nic nestojí. Jejich nadace roste, počet přihlášek stoupá, a vy dáte stejný projev ještě čtyřikrát."],["Založte rivalskou univerzitu a akreditujte ji sám.","Otevírá se se čtyřmi sty studenty, jedenácti fakultami a mramorovou vstupní halou. Její první absolventský ročník je podle všech měřítek extrémně loajální."]]},"b-savings-audit":{"t":"Číslo úspor","x":"Roscoe oznámil úspory 180 miliard dolarů. Čtyři nezávislá média to teď prověřila. Deborah: \"Číslo, které skutečně obstojí, je zhruba devět miliard, pane, a zhruba třetinu z toho tvořila smlouva, která byla zrušena ještě dřív, než jste nastoupil do úřadu.\"","c":[["Trvejte na tom čísle. Opakujte ho denně.","Rozdíl mezi oběma čísly se stane trvalou kauzou, a u každé budoucí úspory, kterou oznámíte, se teď správně předpokládá, že je to dvacetina toho, co tvrdíte."],["Zveřejněte podkladovou účetní knihu. Celou.","Skutečné číslo je devět miliard a je ověřitelné, což se ukáže mít výrazně větší hodnotu než sto osmdesát neověřitelných."],["Upravte to na devět miliard. Řekněte, že se zlepšila metodologie.","Tichá oprava, které si všimnou čtyři lidé. Je to jediný druh opravy, který kdy skutečně funguje, a nikoho nebaví ji dělat."],["Místo toho oznamte 1,8 bilionu dolarů.","Přidat nulu je rychlejší než obhajovat původní číslo, a u davu to zabere úplně stejně dobře, což je tady to opravdu znepokojivé zjištění."]]},"b-rehire-order":{"t":"Vraťte je zpátky","x":"Soudce nařídil znovudosazení. Deborah má praktickou poznámku. \"Čtyři agentury to mohou splnit do pátku. Dvě ne, protože už předaly kancelářské prostory dál a smazaly přístupy do systémů, a smazání trvalo jedenáct minut, zatímco obnovení trvá devět měsíců.\"","c":[["Podřiďte se tam, kde je to snadné. Jinde se odvolejte na nemožnost.","Nemožnost způsobená vlastním chvatem je před zákonem pořád nemožnost, a funguje to. Soudce o tom napíše odstavec a Kongres ho přečte nahlas."],["Podřiďte se všude. Obnovte systémy.","Stojí to osmdesát milionů dolarů a devět měsíců, aby se odčinilo jedenáct minut chvatu. Poučení je nákladné, správné, a nikdo se ho nikdy nenaučí."],["Znovudosaďte je na papíře. Nedávejte jim nic na práci.","Technicky vyhovující zaměstnání bez povinností, bez přístupu a bez stolu. Čtyři z nich žalují znovu, tentokrát s prvním rozsudkem v ruce."],["Znovudosaďte je a povyšte je nad lidi, co je vyhodili.","Organizační schéma je teď fakticky diagram msty. Produktivita ve dvou agenturách měřitelně vzroste, a nikdo o tom nechce mluvit, proč."]]},"b-loyalty-questionnaire":{"t":"Otázka jedenáct","x":"Nový náborový dotazník má jedenáct otázek. Deset je normálních. Deborah přečte jedenáctou nahlas a zastaví se v polovině. \"Pane, ptá se, kterou z vašich politik uchazeč nejvíc obdivuje. Tohle je na místo inspektora mostů.\"","c":[["Nechte otázku jedenáct. Aplikujte ji všude.","Mosty kontrolují lidé, kteří vás obdivují. V průměru je kontrolují trochu hůř, a to zjištění tady zahrnuje jeden most."],["Nechte ji pro politické jmenovance. Zrušte ji pro kariérní zaměstnance.","Rozlišení, které existuje od roku 1883, a nikdo v téhle budově ho nemusel vymýšlet, protože tu práci už někdo dřív odvedl."],["Zrušte ji. Najměte nejlepšího uchazeče.","Inspektorát mostů obsadí čtyři místa, která měl volná dva roky. Žádný most nespadne. Nikdo to nikomu nepřičítá."],["Udělejte z otázky jedenáct jedinou otázku.","Jednootázkový formulář žádosti pro celou federální vládu. Počet žádostí vzroste o čtyři sta procent a úroveň je přesně taková, jakou byste čekal."]]},"b-inspector-vacancies":{"t":"Prázdné kanceláře","x":"Miriam má mapu. \"Sedmnáct odvoláno, a jedenáct z těch úřadů je o čtrnáct měsíců později pořád prázdných. Ne zablokovaných, pane. Prázdných. Nikdo dokonce ani nebyl nominován. Audity, které by se byly konaly, se prostě nekonaly, a nikde není žádný záznam o tom, že se nekonaly.\"","c":[["Nechte je prázdné. Na neurčito.","Funkce dohledu přestává existovat, aniž by byla kdy formálně zrušena. Nejúčinnější věc, kterou kdokoli za toto funkční období udělá, a nevyžadovala jedinou akci."],["Obsaďte je pověřenými úředníky zevnitř.","Pověření inspektoři, kteří odpovídají přímo lidem, které mají inspektovat. Čtyři z nich přesto svou práci dělají poctivě, což je pro všechny zúčastněné opravdové překvapení."],["Nominujte jedenáct skutečných inspektorů. Pošlete je k potvrzení.","Devět je potvrzeno. Dva do roka vyprodukují zprávy, které jsou pro vás nesmírně špatnou zprávou, a zbylých sedm vyprodukuje zprávy o veřejných zakázkách."],["Jmenujte jednoho generálního inspektora pro všech jedenáct agentur.","Jedna osoba, jedenáct agentur, čtyři sta tisíc zaměstnanců. Devět měsíců dře do úmoru a pak zveřejní něco pozoruhodného."]]},"b-settlement-culture":{"t":"Čtvrté vyrovnání","x":"\"Čtvrtá firma se dohodla v případu, o kterém její vlastní právníci tvrdili, že by ho vyhrála.\" Sy z toho vůbec nemá radost. \"Teď je v tom vzorec, pane, a vzorec je před soudem přípustný způsobem, jakým čtyři oddělené případy nikdy nejsou. Někdo, někde, to použije jako argument.\"","c":[["Zažalujte pátou. Vzorec je ten produkt.","Vyrovnají se do jedenácti dní bez jednání. Občanskoprávní žaloba je teď prostě poplatek uvalený za to, že o vás psali, a všichni už znají aktuální sazbu."],["Za tohle funkční období už nikoho jiného nežalujte.","Vzorec potřebuje pátý případ, aby byl skutečně vzorcem. Odepřít mu ho je zadarmo, a potichu to zajde ve fázi přípravy něčí žaloby."],["Nasměrujte všechny budoucí výnosy na charitu, kterou nekontrolujete.","Odstranění osobního prospěchu odstraní většinu argumentu. Zároveň to odstraní většinu smyslu, a čtyři lidé si toho okamžitě všimnou."],["Zažalujte sám sebe, abyste vytvořil příznivý precedens.","Obě strany zastupují vládní právníci. Případ je zamítnut pro nedostatek sporu devítislovým usnesením, které je široce, téměř s láskou, obdivováno."]]},"b-schedule-list":{"t":"Seznam k reklasifikaci","x":"\"Seznam k reklasifikaci.\" Deborah ho opatrně pokládá na stůl. \"Padesát tisíc kariérních míst přesunutých do kategorie s nulovou ochranou před propuštěním. Meteorologové. Posuzovatelé grantů. Dvě stě statistiků.\" Odmlčí se. \"Statistiky bych se bál nejvíc, pane.\"","c":[["Reklasifikovat všech padesát tisíc.","Nikdo nemusí být vyhozen. Padesát tisíc lidí teď prostě ví, že by mohli být, a statistiky, které produkují, se začnou nepatrně, samy od sebe zlepšovat."],["Reklasifikovat jen politické posty. Technické nechat být.","Hranice mezi politikou a měřením, stará sto čtyřicet let, existuje přesně kvůli tomuhle."],["Seznam úplně stáhnout.","Meteorologové dál předpovídají a statistici dál počítají, a za devatenáct měsíců vám jeden z těch součtů zachrání volby."],["Reklasifikovat je a nechat je reklasifikovat vás.","Recipročním formulářem, který koluje jako vtip, vyplní za jeden den jedenáct tisíc federálních zaměstnanců. Výsledky nikdy nikdo nezveřejní."]]},"b-weyland":{"t":"Nesouhlasný badatel","x":"Dr. Weirová vám přinesla něco nečekaného. \"Vážený vědec, který tvrdí opak konsenzu, že instituce drží, že poplach je přehnaný, že tohle přejde.\" Podává vám to. \"Pane prezidente, chci mít jasno, že jsem to přinesla, protože je to dobrá práce, ne proto, že s ním souhlasím.\"","c":[["Dát ho do všech pořadů. Je to protiargument.","Je to opatrný muž, který říká opatrné věci, a tím, že si ho osvojíte, přijde přesně o tu vlastnost, díky které stálo za to si ho osvojit."],["Přečíst si to pořádně. Nic neměnit.","Je to nejzajímavější hodina vašeho prezidentství. Nic z ní neplyne a dr. Weirová se k tomu už nikdy nevrátí."],["Nechat ho debatovat s konsenzem, naživo, a sám se do toho nemíchat.","Dvě hodiny opravdové debaty před devíti miliony lidí. Nic to nevyřeší, ale je to zdaleka nejzdravější věc, co se ten rok stane."],["Jmenovat ho, ať prověří, jestli jste autoritář.","Přijme to pod podmínkou plného přístupu a práva na zveřejnění. Obojí mu písemně přiznáte, aniž byste si zjevně přečetl to druhé."]]},"c-defiance":{"t":"Příkaz, který neuposlechnete","x":"Šest ku třem, a napsáno tak, že by to pochopilo i dítě. Sy přestal dělat poznámky. \"Pane, do dneška každý spor byl o tom, co příkaz *znamená*. Tenhle znamená jen jedno. Pokud ho budete ignorovat, poprvé to tak udělá někdo. A každý badatel, co se tímhle živí, to už napsal černé na bílém: tohle je ta hranice.\"","c":[["Neuposlechnout. Říct to nahlas.","Republika toho odpoledne nepadne. Stane se místo toho něco tišího: každá instituce v zemi si v soukromí přepočítá, na co se může spolehnout, a žádná tu novou hodnotu nezveřejní."],["Uposlechnout, a rok denně útočit na soud.","Poslušnost okořeněná pohrdáním vás strukturálně nic nestojí a koupí vám rok obsahu plného křivd. Je to tah, který udělal každý váš předchůdce, jen nikdy tak nahlas."],["Uposlechnout. Plně. Říct, že to bylo správné rozhodnutí.","Přijdete o politiku i o ten týden. Čtyři badatelé, kteří už napsali, že neuposlechnete, tiše vydají opravu, a ta oprava se ukáže jako to nejcennější, co vlastníte."],["Uposlechnout ve státě, který neexistuje.","Žádost o splnění příkazu uvádí jurisdikci, která není na žádné mapě. Přesto ji zaevidují. Čtyři úředníci stráví čtrnáct dní debatou, jestli je to překlep, nebo manifest."]]},"c-postpone":{"t":"Datum","x":"Deborah za sebou zavřela dveře. \"Existuje argument, špatný, ale argument, že mimořádné pravomoci sahají až na správu federálních voleb.\" Nesedá si. \"Pane, pracuju pro vás čtyři roky. Chci mít v záznamu, že jsem vám řekla, že tohle je ta chvíle.\"","c":[["Odložit je. O devadesát dní. Kvůli bezpečnosti.","Čtyři guvernéři oznámí, že volby uspořádají stejně, v původním termínu, podle státního práva, na které mají plné právo. Jediná otevřená otázka je, jestli je někdo přijde zastavit."],["Volby uspořádat. Napadnout každý těsný okres potom.","Bojovat proti sčítání je boj uvnitř systému. Zrušit sčítání ne. Ten rozdíl vás nic nestojí a ukáže se, že je to celý rozdíl."],["Uspořádat je v termínu. V případě prohry uznat porážku.","Tu větu vyslovíte nahlas, předem, před kamerou. Převáží nad vším, co jste za čtyři roky řekl, a vaše vlastní hnutí vám to, že jste to myslel vážně, tak úplně neodpustí."],["Uspořádat volby o týden dřív, jako překvapení.","Čtyři státy se to dozví poštou. Účast tam skončí na 19 procentech a všechny výsledky se zruší, aniž by to musel kdokoli žalovat, protože se pro jednou všichni okamžitě shodli."]]},"c-jail-opponent":{"t":"Obžaloba","x":"Bo má na Cordelii Ruiz-Bloomovou spis a drží ho, jako by byl ještě teplý z tiskárny. \"Nesrovnalost v podání z roku 2019 a procesní argument, za který bych se styděl, kdybych ho měl vyslovit nahlas. Před soudem by to neobstálo.\" Odkládá ho. \"Nemusí to obstát před soudem, aby ji to udrželo v soudní síni dva roky.\"","c":[["Obvinit ji. Dnes. Proces je trest.","Za dvacet šest měsíců ji zprostí viny a do té doby je nejslavnější opoziční osobností na polokouli. Čtyři země, kterým běžně kážete o právním státu, ji dají jako první příklad."],["Vyšetřovat. Neobviňovat. Nechat to viset.","Otevřený spis bez obvinění je verze, která skutečně funguje: všechen stín, žádný proces, a nic, proti čemu by se dalo odvolat."],["Zavřít spis. Říct jí, že jste ho zavřel.","Devět měsíců vám nevěří. Když nakonec uvěří, řekne to veřejně, a stojí vás to čtyři body ve státě, který jste potřeboval."],["Obvinit ji jen z chyby v podání z roku 2019 a z ničeho jiného.","Národní opoziční vůdkyně stojí obviněná kvůli úřednímu formuláři. Maximální trest je pokuta 400 dolarů, kterou zaplatí v hotovosti na schodech soudu, před kamerou, a účtenku si nechá."]]},"c-enabling":{"t":"Zmocňovací zákon","x":"Hal Grimes něco navrhl a vypadá, jako by ho to zaživa zžíralo. \"Čtyři stránky. Dávají vám pravomoc měnit nebo pozastavit jakýkoli zákon během vyhlášeného stavu nouze, a stav nouze vyhlašujete vy.\" Odkládá to. \"Dokážu to protlačit touhle komorou, pane. Přesně to mě děsí.\"","c":[["Schválit ho. Obě komory. Tento měsíc.","Zákonodárný sbor, který si odhlasuje pryč vlastní funkci, byl poslední položkou na seznamu každého badatele. Teď je to jediná odškrtnutá položka."],["Schválit verzi se dvouletou doložkou o zániku platnosti.","Doložka o zániku platnosti je celý rozdíl mezi delegací a abdikací. O dva roky později tiše vyprší, protože ji všichni zapomenou obnovit."],["Nepředkládat ho. Místo toho žádat čtyři konkrétní zákony.","Běžným hlasováním dostanete tři ze čtyř. Jsou trvalé, nenapadnutelné, a nikdo o nich nikdy nenapíše kapitolu do knihy."],["Schválit ho a pravomoc rovnou delegovat zpátky Kongresu.","Zákon, který na vás přenáší pravomoc, a příkaz, který ji hned přenáší zpátky, oba podepsané téhož odpoledne. Čtyři ústavní právníci tomu říkají \"smyčka\" a moudře to tam nechají."]]},"c-vote-machines":{"t":"Certifikace","x":"Čtyři státy dosud necertifikovaly výsledky. Jejich guvernéři jsou z obou stran a řekli přesně totéž: certifikace je pravomoc státu a sčítání je sčítání. Bo: \"Můžeme vydat federální pokyn, ať to pozastaví. Nemá to žádnou právní sílu. Má to obrovské množství té druhé.\"","c":[["Vydat pokyn. Nařídit všem čtyřem pozastavení.","Tři přesto do dne certifikují. Čtvrtý pozastaví na jedenáct dní a jeho zákonodárný sbor je na vlásku od něčeho, o čem se soudí ještě v roce 2039."],["Poslat federální pozorovatele. Žádný pokyn.","Pozorovatelé sledují sčítání a napíší zprávu, že to skutečně bylo sčítání. Je to nejstarší a nejnudnější nástroj v bedně a funguje přesně proto, že takový je."],["Neříkat nic. Certifikace je jejich věc.","Všechny čtyři státy certifikují podle plánu. O čtyři roky později je tohle fakt, na který se při vaší obhajobě odvolávají nejčastěji, a to lidé, u kterých byste to nečekal."],["Certifikovat výsledky sám, odsud.","Podepsaný federální certifikát pro státní volby se pošle do státu, který už vydal vlastní. Jeho tajemník ho založí do složky \"korespondence\"."]]},"c-electors":{"t":"Alternativní volitelé","x":"\"Ve třech státech byla sestavena druhá sada volitelů.\" Sy čte z dokumentu, o kterém zjevně přál, aby mu nikdy nepřistál na stole. \"Žádný právní základ. Podepsané formuláře. Pane, celá teorie je, že podepsaný formulář vytvoří spor, a spor vytvoří volbu.\"","c":[["Předat všechny tři sady. Ať si vybere Kongres.","Čtyři z lidí, kteří ty formuláře podepsali, jejich vlastní státy do dvou let stíhají. Nikdo z nich nedostal informaci, že tohle je na stole."],["Předat je, ale zbavit se jakéhokoli právního účinku.","Sada volitelů zbavená účinku je tisková zpráva s ověřeným podpisem. Vyvolá veškerou nevoli a žádná obvinění."],["Odmítnout sady. Veřejně. Jmenovitě.","Tiše uchráníte čtyřicet jedna lidí trestní odpovědnosti, o které se nikdy nedozvědí, protože věc, které jste zabránil, nikdy nedostane jméno."],["Sestavit třetí sadu, která hlasuje pro opozici.","Předloženo čistě proto, aby to zamotalo záznamy, a povede se to nad veškerá rozumná očekávání. Nikdo, na žádné straně, si to nedokáže vysvětlit devět měsíců."]]},"c-third-term-poll":{"t":"Otázka v průzkumu","x":"Nadia Fisková spočítala čísla. \"Čtyřicet jedna procent vašich vlastních voličů říká, že byste měl zůstat i po skončení funkčního období. Ne 'zvážil bych to'. 'Měl by.'\" Zvedne oči. \"Pane, tu otázku jsem do průzkumu nedala já. Někdo z vašeho týmu mě o to požádal, a chci to mít v záznamu.\"","c":[["Zveřejnit číslo. Nechat ho, ať odvede práci.","Číslo není návrh, a právě proto je užitečnější než návrh. Nikdo ho nemusí hájit a všichni na něj musí reagovat."],["Průzkum zamést pod koberec. Tu otázku už nikdy nepokládat.","Nadia sama smaže data. O čísle vědí čtyři lidé v budově a žádný z nich ho už nikdy nevysloví nahlas."],["\"Dvě funkční období, to je smysl úřadu.\" Říct to jednou.","Jedna jasná věta ukončí devět měsíců spekulací v jednom zpravodajském cyklu. Vaše hnutí to oplakává jako smrt v rodině."],["Zeptat se i na čtvrté funkční období.","Podpora je 29 procent, což je záhadně zároveň nižší i vyšší, než kdokoli čekal. Nadia tomu říká \"nejhorší číslo, jaké jsem kdy sama vyprodukovala\"."]]},"c-term-reset":{"t":"Dodatek, který vynuloval hodiny","x":"Dr. Weirová přinesla srovnávací materiál. \"Bylo to uděláno pořádně. Ústavní dodatek, referendum, opravdová většina. Hodiny se vynulovaly a už odsloužená funkční období jednoduše přestala počítat.\" Zavírá složku. \"Pane prezidente, to není převrat. To je papírování.\"","c":[["Zahájit proces schvalování dodatku. Veřejně.","Vyžaduje třicet osm států a vy máte devatenáct. Pokus je pro vás cennější, než by kdy byl dodatek sám, a všichni zúčastnění to vědí."],["Nechat přátelský zákonodárný sbor státu, ať to navrhne. Sám se do toho nemíchat.","Vy jste o nic nežádal. Bylo to navrženo. Ten rozdíl je nosnou zdí celého podniku a drží celé dva roky."],["\"To dělají jiné země.\" Nechat to tak.","Táhnout čáru u cizí ústavy je nejlevnější vlastenectví, co je k mání, a v tomhle konkrétním případě je navíc upřímné."],["Navrhnout dodatek, který zkrátí funkční období na dva roky.","Nikdo nedokáže určit, jestli je to blaf, past, nebo opravdové přesvědčení. Získá to čtyři spolupředkladatele a tiše to zemře ve výboru, aniž by to kdy kdo vysvětlil."]]},"c-gold-room":{"t":"Renovace","x":"Alvin má připravené faktury a fotky před a po. \"Zlaté lišty na římse, kolem dveří, na krbové římse a orlu. Reverzibilní, pane, v tom smyslu, že se to teoreticky dá zase odloupnout.\" Zaváhá. \"Každý návštěvník to hned vyfotí.\"","c":[["Víc zlata. Lišty, zrcadlo, rámy.","Místnost, která působí jako trůnní sál, v budově výslovně navržené tak, aby žádný neměla. Objeví se v devíti stech zahraničních zpravodajstvích do roka."],["Zastavit, kde to je. Stačí to.","Střídmé množství zlata působí jako vkus. Velké množství působí jako argument, a vy jste se zastavil o jednu vrstvu laku před tím, než byste ho vyslovil."],["Zbavit se ho. Obnovit místnost.","Alvin osobně dohlíží na obnovu a poprvé za čtyři roky vypadá opravdu šťastně. Nikdo mimo budovu si toho vůbec nevšimne."],["Pozlatit i zasedačku kabinetu, chodbu a výtah.","Výtah je detail, který napáchá skutečnou škodu. Čtyři sta tisíc lidí si posílá jednu fotku pozlaceného výtahu a ani jeden z nich není na vaší straně."]]},"c-birthday":{"t":"Den volného vstupu","x":"Boyd Hackler má připravenou a podepsatelnou proklamaci. \"Volný vstup do všech národních parků a památníků, na váš narozeniny, navždy.\" Přešlápne. \"Pane, volný vstup do parků je opravdu populární. Problém je jen v datu, a existuje tři sta šedesát čtyři jiných možností.\"","c":[["Podepsat to. Moje narozeniny.","Čtyři miliony lidí dostanou den volného vstupu do parku, vybraný kvůli jednomu muži. Většina z nich zažije nádherné odpoledne, a každou fotku z toho doprovodí krutý popisek."],["Podepsat to místo toho na Den nezávislosti.","Identická politika, univerzálně oblíbená, nepřipsaná nikomu konkrétnímu. Boyd si to založí jako výhru a v soukromí to oplakává jako prohru."],["Žádný svátek. Místo toho pořádně financovat parky.","Dokončí se jedenáct zpožděných údržbových projektů. V Montaně se přestaví most. Nikdo nikdy nevystopuje jediný trám zpátky k vám."],["Podepsat to a účast udělat povinnou.","Slovo \"povinná\" přežije čtyři koncepty a dvě právní kontroly, než ho konečně někdo odchytí v jedenáct večer, noc před tiskem."]]},"c-name-on-buildings":{"t":"Smlouva na cedule","x":"\"Smlouva na cedule pro čtyři sta federálních budov.\" Deborah čte specifikaci nahlas. \"Vaše jméno, nad dveřmi, bronzové, metr vysoké. Pane, ty budovy jsou pojmenované po lidech, kteří jsou mrtví. Není to pravidlo. Je to prostě to, co se historicky vždycky dělalo.\"","c":[["Všech čtyři sta. Bronz. Metr.","Čtyři sta budov teď nese jméno žijícího muže. Sundat je později stojí 60 milionů dolarů, číslo, které bude každá budoucí administrativa ráda opakovat."],["Čtyři budovy. Ty, co jsme opravdu postavili.","Pojmenovat po sobě něco, co jste postavil, je nenápadné. Pojmenovat po sobě něco, co jste nepostavil, vyznívá úplně jinak, a tomu jste se vyhnul."],["Žádná. Budovy si nechají svá jména.","Deborah zaznamená rozhodnutí do spisu jediným slovem, \"zamítnuto\", a je to záznam, na který je za čtyři roky nejpyšnější."],["Pojmenovat je všechny po svých předchůdcích, podle abecedy.","Matoucí, nákladné a nějak úplně okouzlující. Čtyři historické spolky napíšou, že si toho váží, a jeden pošle dort."]]},"c-invasion-within":{"t":"Místnost plná generálů","x":"Každý vlajkový důstojník ve službě je v jedné místnosti, protože jste si je osobně vyžádal. Tarrant má návrh projevu a jednu poznámku. \"Pane, ta fráze je 'invaze zevnitř'. Řeknete ji čtyřem stům lidí, kteří celou kariéru studovali, na koho přesně smí, a na koho nesmí, namířit zbraň.\"","c":[["Říct to. Sledovat místnost.","Nikdo nevstane. Nikdo neodejde. Čtyři sta důstojníků sedí v naprostém tichu a každý z nich to ten samý večer komukoli vytočí."],["Říct to, pak dodat, že myslíte politický argument.","Vysvětlení zapadne pod frázi, jak to vysvětlení vždycky udělá, ale přežije v přepisu, a Tarrant se postará, aby se rozšířilo."],["Vyškrtnout to. Mluvit o náboru a platech.","Dvacet minut o bytových příspěvcích čtyřem stům generálů. Nejlépe přijatý projev celého funkčního období a nedostane se mu naprosto žádného pokrytí."],["Zeptat se místnosti, kdo z nich je ta invaze.","Jeden generál zvedne ruku. Dodnes se neurčilo, jestli to byla neposlušnost, nebo vtip, a on odmítl to vyjasnit."]]},"c-monarch":{"t":"\"Fakticky monarcha\"","x":"Historik v televizi použil dvě slova: fakticky monarcha. Dr. Weirová to sledovala. \"Nemyslel to sprostě, pane prezidente. Myslel to strukturálně, úřad, na kterém neběží žádná účinná kontrola. Řekl to smutně, a přesně proto to zapůsobilo.\"","c":[["Přijmout to. Nechat to vytisknout.","Řada merchandise postavená na varovném štítku. Prodává se výjimečně dobře a citují ji, zcela bez ironie, ve třech zahraničních parlamentech při debatě o vlastních vůdcích."],["Odmítnout to. Vyjmenovat věci, které vás zastavily.","Přesně, zpaměti, jmenujete čtyři prohry u soudu a jeden neúspěšný zákon. Nejpřesvědčivější věc, co za rok uděláte, a vaše základna nenávidí každou slabiku."],["Neříkat nic. Je to jeden historik.","Za jedenáct měsíců se to stane názvem kapitoly a za tři roky názvem knihy, a do té doby už vaše mlčení nikoho nezajímá."],["Formálně, písemně požádat o korunu.","Memorandum úřadu kurátora se ptá, co by to obnášelo. Čtyřsetslovná odpověď bere otázku s naprostou, znepokojivou vážností."]]},"c-restored-republic":{"t":"Obnovení republiky","x":"\"Vrátil to všechno.\" Dr. Weirová popisuje muže mrtvého dva tisíce let. \"Veřejně, formálně, v senátu, každou mimořádnou pravomoc, vzdal se jí na místě. Pak si dvě obyčejné podržel doživotně, a ty dvě se ukázaly jako dostatečné.\" Odmlčí se. \"Je to nejúspěšnější politický manévr v dějinách, pane prezidente, a vypadal přesně jako rezignace.\"","c":[["Udělat to. Vzdát se mimořádných pravomocí. Podržet si ty dvě, na kterých záleží.","Pokrytí je nadšené a téměř úplně mylné. Vzdal jste se třiceti devíti věcí, které jste nikdy nepoužil, a tiše si podržel dvě, které dělají tu práci."],["Vzdát se všech. Doopravdy.","Ne manévr. Skutečné obnovení, provedené pořádně, a stojí vás to všechno, co jste za čtyři roky nashromáždil. Dr. Weirová o tom píše zbytek kariéry."],["Nechat si všechno. Divadlo je pro slabší muže.","Muž z toho příběhu si nechal všechno otevřeně a vlastní senát ho za to probodl. Dr. Weirová to zmíní; vy jí řeknete, že to byla úplně jiná situace."],["Vzdát se jich v latině.","Proklamace je vydána jen v latině. Čtyři klasičtí filologové najdou tři gramatické chyby a jeden napíše 6000 slov jen o konjunktivu."]]},"c-acerbo":{"t":"Pravidlo dvou třetin","x":"Halovi ukázali něco z roku 1923 a už to nedokáže odestat. \"Změna volebního zákona. Kdo skončí první, jakkoli těsně, jakkoli malým rozdílem, dostane dvě třetiny mandátů.\" Je bledý. \"Schválil to parlament, kterému pak nezbylo nic dalšího ke schválení. Pane, ukazuju vám to, abyste to viděl.\"","c":[["Připravit americkou verzi. Předložit ji.","Neprojde. Bude předložena, což znamená, že teď existuje, což znamená, že může být předložena znovu, jednou, někým se skrupulemi menšími než vy."],["Místo toho agresivně přeskupit volební obvody. Stejný výsledek, běžné nástroje.","Devět států předělaných až na hranici zákona. Naprosto konvenční, naprosto brutální, a obě strany to dělají už dvě stě let."],["Nic. Buď mandáty vyhrát, nebo ne.","Přijdete o jedenáct mandátů, které byste jinak měl. Zbyde komora, která vám ještě dokáže technicky říct ne, a za devatenáct měsíců to udělá."],["Přiznat dvě třetiny mandátů tomu, kdo skončí druhý.","Navrženo čistě proto, aby to ilustrovalo tu svévoli. Čtyři poslanci se k tomu upřímně připojí a jeden pronese v jeho prospěch skutečně dojemný projev."]]},"c-judicial-purge":{"t":"Čtyři tisíce","x":"Předsedkyně Nejvyššího soudu Stoneová přišla osobně a přinesla výtisk. \"Čtyři tisíce soudců a žalobců odvoláno během jediného roku, v zemi, kde se pořád konají volby. Sto padesát novinářů uvězněno.\" Položí to na stůl. \"Neobviňuju vás z ničeho, pane prezidente. Říkám vám, jak to vypadá zevnitř, protože lidé, kterým se to stalo, to taky neviděli přicházet.\"","c":[["Zahájit přezkum chování federálních soudců. Celé.","Nikdo není odvolán. Devět set soudců je teď prostě lidí se spisem, a soudce se spisem rozhoduje jinak, což byl jediný výsledek, který kdo kdy potřeboval."],["Přezkoumat jedenáct, kteří proti nám rozhodli nejčastěji.","Cílit na viditelné je horší než cílit na všechny, protože vzorec je od prvního dne jasně čitelný a devět médií zveřejní seznam do oběda."],["Poděkovat jí. Neudělat vůbec nic.","Už to nikdy nezmíní. O dva roky později, v případu, který zoufale potřebujete, napíše nečekané souhlasné stanovisko, a vy se nikdy nedozvíte proč."],["Nabídnout, že se necháte přezkoumat soudní mocí místo toho.","Formální žádost, aby soudní konference prošetřila vaše vlastní chování. Přijmou ji. Zprávu podá za čtyři roky, kdy už to bude problém někoho jiného."]]},"c-crossed-over":{"t":"Text, který říká, že jsme to překročili","x":"Dr. Weirová má ten text. \"Tvrdí, že země přestala být plnou demokracií, ne že se stala diktaturou, ale že sklouzla do jiné kategorie úplně. A říkají, že ten obrat byl rychlejší než první rok čtyř případů, které jmenují.\" Pokládá to. \"Pane prezidente, jejich slovo je *soutěživá*. Volby jsou pořád skutečné. To je celý ten rozdíl a odvádí to spoustu práce.\"","c":[["Dokázat, že mají pravdu. Naplno se do toho opřít.","Text dostane nový oddíl v druhém vydání. Citují vás čtyřicet jednou, a ani jedna citace není laskavá."],["Dokázat, že se mýlí. Udělat jednu věc, o které řekli, že neuděláte.","Podřídíte se rozsudku, kterému jste se snadno mohl vzepřít, a přijdete o politiku, kterou jste chtěl. Dva ze čtyř autorů to veřejně zaznamenají, jediná oprava, kterou o vás kdy vydají."],["Napadnout metodologii. Financovat konkurenční index.","Váš index řadí zemi na čtvrté místo na světě. Nikdo ho necituje, nakonec ani lidé, které jste zaplatil, aby ho vytvořili."],["Zeptat se jich, jaké skóre by to napravilo, a přesně to obejít.","Odpoví upřímně a podrobně, protože to akademici dělají. Vylepšíte devět ukazatelů, aniž byste změnil jedinou skutečnou věc, a skóre se posune o čtyři body nahoru."]]},"c-index-drop":{"t":"Padesáté první","x":"Muriel má otevřený index. \"Z dvacátého na padesáté první místo za jeden rok. Poprvé za víc než padesát let mimo nejvyšší klasifikaci.\" Otočí stránku. \"Věta, kterou pořád dokola čtou na každém zahraničním ministerstvu, je ta o *rychlosti*, pane. Říkají tomu bezprecedentní v moderních dějinách.\"","c":[["Vystoupit z organizace, která ten index financuje.","Je to akademické konsorcium na švédské univerzitě, a vy ho nefinancujete. I tak se pokus o jeho zrušení dostane do titulků ve čtyřiceti zemích."],["Zpochybnit žebříček. Ignorovat rychlost.","O žebříčku samotném se nikdo nechystal hádat. Šlo vždycky o tempo poklesu, a vy jste se právě rozhodl o tom nevést spor."],["Zveřejnit dílčí skóre a napravit tři nejhorší.","Nezávislost soudnictví, přístup tisku, kapacita dohledu. Náprava tří ukazatelů trvá jedenáct měsíců a vrátí vás na třicáté čtvrté místo."],["Požádat o zařazení do úplně jiné kategorie.","Formální žádost, aby byla země hodnocena jako rozvíjející se demokracie místo etablované. Zdvořile zamítnuto ve čtyřech různých jazycích."]]},"c-insurrection-act":{"t":"Zákon bez definice","x":"\"Zákon nikde nedefinuje povstání.\" Tarrant to konstatuje suše, spíš jako fakt než argument. \"Říká, že smíte jednat, jakmile usoudíte, že nějaké probíhá. Žádný test, žádná hranice, a žádný soud tu volbu nikdy nezpochybnil.\" Čeká. \"Pane, to je nejširší pravomoc, jaká v americkém právu zbývá, a byl byste první za padesát osm let, kdo ji takhle skutečně použije.\"","c":[["Použít ho. Celostátně.","Řadové jednotky v amerických ulicích na základě zákona bez definice a bez kontrolora. Je to nejzákonnější věc, co jste kdy udělal, a přitom se nepodobá ničemu z toho, co jste dělal dřív."],["Použít ho pro jedno město. Na dvacet jedna dní. Písemný limit.","Limit, který si sám uložíte, je jediný limit kdekoli v celém zákoně. Tarrant tu dvaceti jednodenní lhůtu vepíše do příkazu osobně a děkuje vám za to."],["Nepoužívat ho. Nasadit gardu pod velením státu.","Pomalejší, a přece to funguje, protože guvernéři se zájmem na výsledku se ukážou být užitečnější než vojáci s příkazem v ruce."],["Použít ho proti počasí.","Proklamace prohlásí hurikán za povstání. FEMA a Severní velitelství svolají společný hovor jen proto, aby zjistili, kdo z nich to teď má za úkol."]]},"c-registry":{"t":"Seznam úplně všech","x":"Duane Krisp má návrh od dodavatele. \"Sloučit všechny federální databáze. Daně, dávky, cestování, licence, imigrační status. Každá zvlášť zákonná.\" Odkládá to. \"Pane, dohromady je to jeden spis o tři sta čtyřiceti milionech lidí, a o tom dohromady nikdy nikdo nehlasoval.\"","c":[["Postavit to. Celé. Jeden soubor.","Funguje to přesně, jak slibovali, a v prvním roce se do toho dotáže devět milionů dotazů. Čtyři z nich se později ukáží jako dotazy na novináře."],["Sloučit jen sady relevantní pro imigraci.","Užší systém s deklarovaným účelem, jediný druh, který kdy přežije soudní přezkum. Dělá to taky 80 procent toho, co jste vlastně chtěl."],["Zabít to. Napsat pravidlo proti sloučení.","Pravidlo přežije vaši administrativu o desítky let a dodavatel žaluje za náklady na vývoj a prohraje na plné čáře."],["Postavit to a dát to na veřejné webové stránky.","Radikální transparentnost dotažená do logického konce. Zůstane to online jedenáct minut, což je o devět minut déle, než trvalo, než to bylo archivováno navždy."]]},"c-data-center":{"t":"Zařízení v poušti","x":"Errol Hance má plán lokality. \"Úložiště je teď v podstatě neomezené. Můžeme uchovávat všechno, navždy, na základě teorie, že to jednou možná budeme potřebovat.\" Nesedá si. \"Pane, pravidla byla napsaná v době, kdy bylo úložiště drahé. Pravidla počítala s tím, že si stejně budeme muset vybírat.\"","c":[["Uchovat všechno. Navždy. Rozhodnout proč později.","Trvalý záznam o celé zemi, uchovávaný pro účel, který ještě nikdo nevymyslel. Zdědí ho čtyři budoucí administrativy a ani jedna z nich nesmaže jediný bajt."],["Uchovat to, s pětiletým plánem výmazu.","Lhůta uchovávání je jediná smysluplná brzda takového systému, a nestojí nic, dokud je budova napůl prázdná."],["Sbírat jen s určeným účelem.","Errol proti tomu dvacet minut v kuse argumentuje, pak to bezchybně provede, přesně to, co dělá s každým rozhodnutím, které prohraje."],["Naplnit zařízení místo toho papírovými spisy.","Čtyři miliony krychlových stop tištěných záznamů, dovezených vlakem během devíti měsíců. Naprosto bezpečné a naprosto neprohledatelné, což jistí lidé rozhodně upřednostňují."]]},"c-church":{"t":"Národní bohoslužba","x":"Reverend Dale Muncy přišel s návrhem a neobvykle váhá. \"Týdenní bohoslužba, v budově, vysílaná, s kanceláří placenou z rozpočtu.\" Obrací klobouk v rukou. \"Pane, přišel bych. Chci být upřímný, že si nejsem tak úplně jistý, jestli mám být ten, koho se ptáte.\"","c":[["Financovat kancelář. Vysílat bohoslužbu. Týdně.","Čtyři denominace, které vás podporovaly, protestují první a nejhlasitěji, protože o téhle historii toho přečetly podstatně víc než kdokoli u vás v kanceláři."],["Konat bohoslužbu. Bez federálního financování, bez kanceláře.","Soukromá bohoslužba v soukromém sídle, přesně to, na co má každý obyvatel té budovy vždycky nárok."],["Pozvat jedenáct vyznání na rotaci. Nefinancovat žádné.","Rotace, která rovnoměrně otravuje všechny a zákonně neurazí nikoho. Dale si vezme čtvrtou neděli a nazve to nejspravedlivější nabídku na stole."],["Prohlásit se hlavou nové denominace.","Zakládací listina je doslova podaná v Delaware. Devět tisíc lidí se přihlásí do čtrnácti dnů a Dale ten samý den odpoledne rezignuje."]]},"c-broadcast-license":{"t":"Slyšení o obnovení licence","x":"Blíží se obnovení licence a váš regulátor svolal slyšení o \"veřejných zájmových povinnostech\". Kaylee: \"Obnovení je rutina, pane. Rutina je to už šedesát let. Naplánovat kvůli tomu slyšení je celé to sdělení, a všichni v oboru ho dostali už před devátou ráno.\"","c":[["Slyšení uspořádat. Skutečně ohrozit licenci.","Licence se obnoví. Za jedenáct měsíců, co to trvalo, síť tiše vyměnila dva moderátory a jednoho výkonného producenta, a nikdo je o to nemusel žádat."],["Slyšení uspořádat. Obnovit ji na konci.","Proces s předem daným výsledkem je stojí rok právního rozpočtu a rok opatrnosti, což je většina toho, co jste stejně chtěl."],["Obnovit ji automaticky, jako posledních šedesát let.","Nic se nestane. Je to učebnicové vyřízení obnovy licence a neobjeví se to přesně v žádných novinách na světě."],["Udělit licenci síti, která neexistuje.","Fiktivní žadatel s poštovní schránkou vyhraje licenci na velký trh. Čtyři měsíce vysílá zkušební obraz, než si toho na úřadu někdo všimne."]]},"c-cabinet-25":{"t":"Dvacátý pátý dodatek","x":"Chet Danforth požádal o soukromou schůzku a nikoho s sebou nepřivedl. \"Existuje mechanismus,\" říká opatrně, \"který potřebuje mě a většinu kabinetu. Chci, abyste věděl, že se mnou o tom čtyři lidi už mluvili, a já jsem všem čtyřem řekl ne.\" Odmlčí se. \"Říkám vám, že jsem jim řekl ne.\"","c":[["Vyměnit ty čtyři. A vyměnit Cheta.","Kabinet teď vybraný výhradně pro neochotu vás odvolat. Každé rozhodnutí, které od teď udělá, dělají lidé vybraní přesně pro tuhle vlastnost."],["Vyměnit ty čtyři. Cheta nechat na dohled.","Zůstane, protože jednou řekl pravdu v práci, kde se právě ukázalo, že to lze přežít. Než skončí funkční období, udělá to ještě dvakrát."],["Poděkovat mu. Nic neměnit.","Mechanismus už od nikoho nikdy nezazní, po zbytek funkčního období. Jestli je to loajalita, nebo prostá aritmetika, se nikdy úplně nedozvíte."],["Použít ho proti sobě, ať vidíte, co se stane.","Sepíše se, a katastrofálně skutečně odešle, dopis o vaší vlastní nezpůsobilosti. Chet je úřadujícím prezidentem padesát jednu minutu a nedělá s tím vůbec nic."]]},"c-treaty":{"t":"Dohoda, která nebyla smlouvou","x":"Muriel má dokument. \"Práva na základnu, klauzule o vzájemné bezpečnosti, čtyřicetiletá platnost. Nazvete to smlouvou a potřebujete šedesát sedm senátorů, které nemáte. Nazvete to výkonnou dohodou a stačí váš podpis.\" Zvedne oči. \"Pane, je to identický dokument tak jako tak.\"","c":[["Podepsat to jako výkonnou dohodu. Čtyřicet let.","Čtyřicetiletý závazek vzájemné bezpečnosti, uzavřený jedním mužem za odpoledne. Druhá země to považuje za závazné, a to je ta část, kterou už nikdy nikdo nemůže vzít zpět."],["Poslat to jako smlouvu. Bojovat o těch šedesát sedm.","Po devíti ponižujících měsících vyjednávání seženete sedmdesát jedna hlasů. Nezrušitelné žádným nástupcem, což se výkonné dohodě nikdy nepovedlo."],["Podepsat pětiletou verzi. Zbytek nechat na Kongresu.","Krátká dohoda, která kupuje čas na pořádnou smlouvu později. Muriel tomu říká profesionální odpověď a myslí to jako skutečnou pochvalu."],["Podepsat to jako smlouvu, dohodu i memorandum zároveň.","Tři dokumenty, stejný text, tři různé právní statusy. Druhá země ratifikuje všechny tři, možnost, se kterou nikdo vlastně nepočítal."]]},"c-emergency-extend":{"t":"Obnovení, které nikdo nečte","x":"\"Vyhlášení se automaticky obnovuje, pokud neřeknete jinak, a Kongres to může ukončit usnesením, což neudělá.\" Sy má formulář připravený. \"Jeden podpis, pane. Čtvrté obnovení. Původní stav nouze v jakémkoli obyčejném slova smyslu skončil zhruba před dvěma lety.\"","c":[["Obnovit ho. A těch dalších jedenáct taky.","Dvanáct stavů nouze, z nichž žádný není nouzí, všechny nosné. Pravomoci jsou teď prostě způsob, jak se země vede, a nikdo pro to nikdy nehlasoval."],["Obnovit jen ty čtyři, které opravdu ještě fungují.","Nechat osm propadnout se u vašich lidí interpretuje jako slabost, u ostatních jako zdravý rozum. Obojí čtení je k dispozici a ani jedno není chybné."],["Nechat je všechny propadnout. Vládnout podle zákonů.","Dobrovolně se vzdáte toho aparátu. Čtyři politiky se okamžitě zhroutí a dvě, které přežijí, se ukážou jako jediné dvě, které kdy byly skutečné."],["Obnovit ho na sto let.","Nástroj uvádí datum vypršení někdy ve dvaadvacátém století. Zveřejní se to. Ve Federálním registru to nemá nikdo pravomoc zpochybnit."]]},"c-lincoln":{"t":"Precedens, který byste preferoval","x":"\"Vaši obhájci pořád sahají po jednom konkrétním prezidentovi,\" říká dr. Weirová. \"Pozastavil habeas corpus, fakticky ignoroval sedícího soudce Nejvyššího soudu a zvažoval odklad voleb.\" Nechá to viset ve vzduchu. \"Pane prezidente, srovnání je přesné. Je to ale taky srovnání s mužem, který tohle všechno dělal během občanské války, a na vašem místě bych ho používal velmi opatrně.\"","c":[["Spoléhat se na to pořád. Má pravdu.","Každý oslovený historik odpoví stejnými třemi slovy o té válce, a ta tři slova jsou nezvratná, a vy k tomu srovnání přesto pořád sahá."],["Srovnání zavrhnout. Najít mírové.","Žádné neexistuje, což je to skutečné zjištění, a dr. Weirová se to ani neobtěžuje vyslovit nahlas, protože nemusí."],["Tvrdit, že nouze *skutečně existuje*, a pojmenovat ji.","Pojmenovat stav nouze je nutný předpoklad pro všechno, co následuje, a jednou pojmenovaná se už nikdy tiše neodpojmenuje, aniž byste se toho vzdal celého."],["Zeptat se jí, kterému prezidentovi se nejvíc podobáte.","Odpoví okamžitě, bez sebemenšího zaváhání, jménem někoho z padesátých let 19. století, o kom v místnosti nikdo nikdy neslyšel. Čtyři dny trvá pochopit, jak kruté to bylo."]]},"c-fdr":{"t":"Čtyři funkční období","x":"Dr. Weirová má připravené další srovnání. \"Dvanáct let, čtvery volby, celá federální vláda přebudovaná od základu, a internace. Taky se pokusil rozšířit soud a jeho vlastní strana ho veřejně odmítla.\" Dodává: \"To odmítnutí je ta část, kterou vaše strana nikdy necituje, pane prezidente, a je to ta část, na které záleželo.\"","c":[["Zkusit rozšíření soudu. Zjistit, jestli vás tahle strana odmítne.","Devět vašich vlastních senátorů odmítne do týdne. Největší jednorázový akt odporu z vaší vlastní strany za čtyři roky, a nikdy se z toho úplně nezotavíte."],["Nezkoušet to. Přijmout ten bod.","Zdržíte se pokusu o něco, co byste stejně jen prohrál. Nikdo si nevšimne věci, ke které nedošlo, a proto se zdrženlivost nikdy neoceňuje."],["Rozšířit místo toho nižší soudy. Tam se nikdo nedívá.","Šedesát tři nová okresní soudcovská místa obsazená za čtrnáct měsíců. Zlomek pokrytí za mnohonásobný skutečný efekt."],["Zmenšit soud na sedm.","Zákon zmenšující lavici odvoláním jeho dvou nejnověji potvrzených členů. Oba jste potvrdil vy, fakt, který na plénu zazní ve velké délce."]]},"c-uncommon-momentum":{"t":"Malá energie na legislativu","x":"Hal má žlutě zvýrazněnou větu z think-tanku. \"'Neobvyklé rané tempo', a pak tohle: 's malou energií vynaloženou na legislativní cesty.'\" Kouká přes okraj stránky. \"Pane, to je zdvořilý způsob, jak říct, že nic z toho není zajištěné, a říkám vám to už dva roky, jen míň zdvořile.\"","c":[["Zachovat tempo. Zajišťovat věci je pomalé.","Všechno, co jste vybudoval, stojí jen na vašem podpisu. Váš nástupce zruší 80 procent toho za jedno odpoledne, přesně tím stejným nástrojem, co vy."],["Poslední dva roky věnovat proměně příkazů na zákony.","Čtyři návrhy zákonů, dva projdou. Jsou to jediné části vašeho prezidentství, které za dvacet let ještě stojí, a nikdo si nepamatuje, že jsou vaše."],["Dělat obojí. Prosadit ty čtyři, co záleží, ostatní vydat příkazem.","Přístup, který nepotěší nikoho z obou stran, a s odstupem dvaceti let se ukáže jako naprosto správný."],["Nechat Kongres schválit jeden zákon, který ratifikuje všechny příkazy naráz.","Dvě stě sedmnáct příkazů ratifikovaných v jednom hlasování, poslanci, kteří mezi sebou přečetli čtyři z nich. Projde o jedenáct hlasů a je napaden hned další ráno."]]},"c-succession-machine":{"t":"Hnutí po vás","x":"Chet má vnitřní čísla a viditelně z nich radost nemá. \"Hnutí má podporu padesát čtyři procent. Vy máte čtyřicet jedna.\" Nechá to chvíli viset. \"Pane, přerostlo vás. To je buď to nejlepší, co jste kdy vybudoval, nebo poslední problém, jaký kdy budete mít, a já upřímně nevím, co z toho.\"","c":[["Svázat ho se sebou. Přísahy loajality, moje jméno na všem.","Hnutí, které vás nemůže přežít, taky nemůže vás přežít, a obě fakta se stanou pravdou v ten samý den, který jste si nevybral."],["Vybudovat instituci. Nechat ji přežít mě.","Stranický aparát s pravidly, pokladnou a procesem nástupnictví. Vyhraje tři z dalších pěti voleb a od druhých voleb vás už skoro nezmiňuje."],["Předat ho teď Chetovi, dokud si mohu vybrat.","Přijme to vděčně a kompetentně, a do jedenácti týdnů udělá rozhodnutí, aniž by se vás nejdřív zeptal, a nic se mu za to nestane."],["Nechat hnutí odhlasovat, jestli vás ještě potřebuje.","Nadia vás prosí, ať to nedělá. Přesto to zadáte. Číslo se vrátí na 38 procent a unikne do čtyř dnů, a ten únik je zdaleka nejmenší z vašich problémů."]]},"c-what-was-it-for":{"t":"Otázka ve dveřích","x":"Je pozdě a Deborah už ani nepředstírá, že drží složku. \"Čtyři roky. Dvě stě sedmnáct příkazů, jedenáct stavů nouze, čtyři sta budov s vaším jménem.\" Není v tom žádná krutost. \"Pane, kdybych se zeptala, co z toho vás přežije, co byste vlastně řekl?\"","c":[["\"Všechno. Protože nikam neodcházím.\"","Zapíše si to. Je to věta, kterou začíná každý popis téhle administrativy napsaný v následujících čtyřiceti letech, a je to ona, komu se přisuzuje, že ji zachytila."],["\"Soudci. Soudci přežijí všechny.\"","Je to správná odpověď. Dvě stě třicet jedna doživotních jmenování, průměrný věk čtyřicet šest, jediná věc tady, která je opravdu trvalá."],["\"Upřímně? Ty dva zákony. Možná.\"","Deborah chvíli mlčí. Pak řekne \"ano\" a odejde, a je to nejblíž, co za čtyři roky dostanete ke schválení."],["\"Ten sál.\"","Je, uznejme, velmi pravděpodobné, že bude ještě stát. Uzná ten bod, a ani jeden z vás se k tomu rozhovoru už nikdy nevrátí."]]},"c-lame-duck":{"t":"Slovo, které nikdo neříká","x":"Nadia má to znamení. \"Čtyři předsedové výborů tento týden nevrátili hovor. Ne nepřátelsky, jen zaneprázdněně. Pane, přesně takhle to vypadá. Nikdo neoznámí, že se vás přestal bát. Jen se najednou stane hrozně, hrozně zaneprázdněným.\"","c":[["Udělat z jednoho z nich příklad. Veřejně.","Přežije primárky o devět bodů, a ostatní tři prostě přestanou vůbec zvedat telefon. Strach je měna a vy jste právě zjistil, že kurz je špatný."],["Dát jim, co chtějí. Koupit si poslední dva roky.","Čtyři obvodní projekty a předsednictví výboru. Transakční, neefektní a koupí to jedenáct dalších měsíců fungující většiny."],["Ignorovat to. Vládnout příkazy až do posledního dne.","Na příkaz je nepotřebujete, a přesně proto je příkaz cenný podstatně méně než ta věc, kterou od nich už nedostanete."],["Zavolat všem čtyřem ve tři ráno, jestli jsou v pořádku.","Všichni čtyři to zvednou. Všichni čtyři jsou velmi znepokojeni. Tři z nich pak šest měsíců vracejí každý hovor; čtvrtý si jednoduše změní číslo."]]},"c-library":{"t":"Knihovna","x":"Miriam má otevřené účty nadace. \"Čtyři sta deset milionů, pane. Z vyrovnání, od dárců s věcmi projednávanými před vládou, a od čtyř cizích státních příslušníků.\" Pokládá to. \"Je to knihovna. Žádná povinnost zveřejnění vůbec. To není mezera v zákoně. Je to prostě zákon.\"","c":[["Vzít to všechno. Je to knihovna.","Nikdo nikdy nikoho úspěšně nenapadl kvůli knihovně. Je to nejčistší způsob, jak dostat peníze v americkém veřejném životě, a vždycky tomu tak bylo."],["Zveřejnit všechny dárce dobrovolně.","Jedenáct dárců se do čtrnácti dnů stáhne, což leccos napovídá o těch jedenácti. Zbylý seznam je nudný a naprosto neotřesitelný."],["Odmítnout zahraniční peníze. Zbytek vzít.","Jedna linka, vedená někam, kde se snadno hájí a snadno ověřuje. Miriam tomu říká \"minimum\" a schválí to."],["Postavit knihovnu bez jediné knihy.","Zařízení o 90 000 čtverečních stopách obsahující čtyři sta fotografií, obchod se suvenýry a repliku kanceláře. Návštěvnost prvního roku předčí každou předpověď."]]},"c-pardon-list":{"t":"Seznam na poslední stránce","x":"Sy má milostný seznam připravený. \"Čtyřicet jedna jmen. Devět z nich pro vás pracovalo. Čtyři odmítli spolupracovat s vyšetřováním proti vám.\" Nekomentuje to. \"Pane, ta pravomoc je nepřezkoumatelná. Žádný soud, žádné hlasování, žádné odvolání. Je to jediná věc v celé ústavě, na kterou vůbec žádná kontrola neplatí.\"","c":[["Podepsat všech čtyřicet jedna. Poslední ráno.","Nepřezkoumatelné znamená nepřezkoumatelné. Nikomu z nich se nikdy nic nestane, a vzkaz všem, kdo ještě sedí na nějakém tajemství, dorazí naprosto jasně."],["Podepsat těch devět se skutečně nepřiměřenými tresty.","Devět obhajitelných případů, každý s vlastním memorandem. Dvě advokátní skupiny, které vás nesnáší, vydají prohlášení podpory, což nikdo nečekal, oni nejméně."],["Nepodepsat žádnou.","Čtyři lidé, kteří kvůli vám mlčeli, přesto jdou do vězení. Jestli je to integrita, nebo nevděk, se dohaduje třicet let."],["Preventivně omilostnit úplně všechny v zemi.","Plošná proklamace všeobecné milosti pro každý federální trestný čin. Podepsáno ve čtyři ráno, zrušeno v sedm, existovalo to celkem tři hodiny."]]},"c-guardrails":{"t":"Co vydrželo","x":"Dr. Weirová přišla se rozloučit a přinesla přesně jednu stránku. \"Závěr literatury, k dnešnímu dni: soudy proti vám pořád rozhodovaly a vy jste je občas poslechl. Volby se konaly a opozice tu a tam vyhrála. Na tisk se tlačilo a přesto dál publikoval.\" Podává to. \"Pane prezidente, každá z těch vět je o něčem, co se nestalo. To je, co znamená hráz.\"","c":[["Pak najít tu, která ještě nebyla testovaná.","Vždycky nějaká existuje. Zbytek funkčního období strávíte hledáním, a samo to hledání se ukáže jako nejnebezpečnější věc, co za celé volební období uděláte."],["Nechat je stát. Vzít si výhru, kterou máte.","Nakonec jste prezident, který úřad enormně rozšířil, a přesto ho nechal fungovat. Nejméně uspokojivý dostupný výsledek, a nejvzácnější."],["\"Vydržely, protože jsem to dovolil.\" Říct to veřejně.","Je to chvástání, které naráz přizná úplně všechno. Čtyři badatelé to citují jako nejodhalující větu celé administrativy, a žádný z nich se nemýlí."],["Požádat ji, ať to sepíše jako seznam, abyste to mohl projít.","Odmítne, poprvé za čtyři roky, jediným slovem. Pak zvedne kabát a naposledy opustí budovu."]]},"e-covfefe":{"t":"To slovo","x":"Usnul jste uprostřed příspěvku a věta se prostě zastaví, po slovu, které není slovo, před jedenácti miliony lidí. Brayden má čísla. \"Čtyři sta tisíc sdílení, pane. Je to nejsledovanější věc, co jste kdy napsal, a nikdo, včetně vás, neví, co to znamená.\"","c":[["Nechat to tam. Říct, že jen vy víte, co to znamená.","Slovo, které neznamená nic, se stane heslem, tričkem a nakonec dostihovým koněm, a přežije všechny politické úspěchy vašeho funkčního období dohromady."],["Smazat to a zveřejnit dokončenou větu.","Dokončenou myšlenku o obchodních deficitech si přečtou čtyři tisíce lidí. Ten překlep měl jedenáct milionů a dokončení nepotřeboval."],["Podrobně vysvětlit, že to byl překlep.","Vysvětlovat vtip, který jste nechtěl udělat, je jediný známý způsob, jak ho zhoršit. Brayden to sleduje s viditelnou tělesnou bolestí."],["Zařadit ho do slovníku výnosem.","Výnos to definuje jako \"stav pohotovostní bdělosti\". Čtyři lexikografové reagují s upřímným nadšením a jeden napíše esej lepší než cokoli jiného, co vaše administrativa ten rok vyprodukuje."]]},"e-hamberders":{"t":"Bufet","x":"Personál kuchyně je na nucené dovolené, tak jste osobně koupil tisíc rychlých hamburgerů a rozložil je na stříbře pod lustry. Alvin je řadí podle výšky. Ve vašem oznamovacím příspěvku je přeškrtnuté jediné slovo, na kterém záleží.","c":[["Nechat pravopis. Zveřejnit fotku té hromady.","Fotka je opravdu radostná, ten překlep opravdu nesmrtelný, a jedenáct mistrovských sportovců nezávisle na sobě prohlásí, že to byl nejlepší večer jejich života."],["Opravit příspěvek. Nechat hamburgery.","Správný pravopis, stejné hamburgery, čtvrtina pokrytí. Někde v komunikačním oddělení je jeden člověk tiše potěšen a všichni ostatní se posunuli dál."],["Zrušit to. Kuchyni na jednu noc znovu otevřít.","Čtyři propuštění kuchaři dostanou příplatek za vaření pro jedenáct sportovců uprostřed rozpočtového výpadku, a někdo nevyhnutelně spočítá cenu za talíř."],["Podávat je na státním porcelánu.","Sada z roku 1918 po Wilsonovi, pod ohřívacími lampami, obložená cheeseburgery. Kurátorova hlášení má čtyři stránky a čte se jako výhrůžný dopis."]]},"e-misspell-count":{"t":"Běžící součet","x":"Někde je stůl, kde celé funkční období počítají vaše pravopisné chyby. Kaylee má dnešní číslo. \"Devět set čtyři, pane. Mají teď kategorie. Existuje podkategorie pro slova, která jste napsal špatně víc než jedním způsobem.\"","c":[["Zveřejňovat neupravené. Navždy. Je to důkaz, že je píšu já.","Je to důkaz, a čtyři miliony lidí tomu věří přesně z toho důvodu, a shodou okolností mají pravdu. Zapojení je o 22 procent vyšší než u čehokoli, co zveřejní zaměstnanec."],["Nechat je před odesláním číst někoho jiného.","Správný pravopis vyznívá jako výbor, a výbor vyznívá jako všichni ostatní. Účet se přes noc stane nerozeznatelným od čtyř set jiných."],["Jedno slovo pokaždé úmyslně přepsat, navždy.","Stane se to podpisem, pak heslem poznávacím. Podporovatelé to vám začnou přeříkávat zpátky a počítající úřad tu kategorii tiše zruší."],["Vydat vázané opravené vydání vlastních příspěvků.","Dva pevně vázané svazky, profesionálně korigované, prodají se v 90 000 kusech a dostanou seriózní recenzi ve třech literárních přílohách."]]},"e-503":{"t":"Pět set tři","x":"Ověřovací organizace zveřejnila součet za celé funkční období. Kaylee to čte bez emocí. \"Třicet tisíc pět set sedmdesát tři, pane. Zhruba dvacet jedna denně. Denní rekord je pět set tři a padl v pondělí.\"","c":[["Rekord překonat. Úmyslně. Ve čtvrtek.","Do oběda máte přes šest set. Proměnit tabulku ve vlastní skóre ji zničí jako kritiku, a přesně proto to funguje."],["Zpochybnit metodologii. Vydat vyvrácení.","Vyvrácení napadá čtyři sta z třiceti tisíc a zbytek prostě mlčením přizná, a přesně to je ta část, kterou všichni pokryjí."],["Neříkat nic. Číslo je jen číslo.","Zpráva žije den a půl. Nic, co byste mohl říct, by to nezkrátilo, a leccos by to naopak natáhlo na týden."],["Zaměstnat všechny ověřovatele.","Nabídky jdou celému oddělení. Dva přijmou, dostanou se do interní revize, a vytvoří memorandum tak přesné, že je do týdne utajené."]]},"e-stable-genius":{"t":"Sebehodnocení","x":"Ve třetí větě příspěvku jste se písemně popsal jako velmi stabilní génius. Dr. Prine je tu kvůli něčemu jinému a přečetl si to z telefonu ve dveřích. \"Pane, chtěl bych mít v záznamu, že jsem to nepotvrdil.\"","c":[["Zopakovat to. Přidat \"jako fakt hrozně chytrý\".","Obě fráze vstoupí do jazyka natrvalo, a žádnou z nich už nikdy nikdo kromě vás nepoužije upřímně."],["Nechat to být. Neopakovat to.","Řečeno jednou, je to chvástání. Řečeno dvakrát, je to symptom. Zůstanete u jednou, což tady v budově nikdo nečekal."],["Nechat Prina udělat skutečný kognitivní test.","Skórujete naprosto normálně, což polovina země nahlásí jako skandál a druhá polovina jako triumf, ze stejného čísla."],["Objednat test IQ a zveřejnit jen obálku.","Zapečetěná obálka projede čtyři shromáždění a nikdy se neotevře. Jako kus politického divadla je téměř dokonalá."]]},"e-sharpie":{"t":"Opravená předpověď","x":"Řekl jste, že bouře zasáhne stát, který nikdy nebyl v predikovaném kuželu. Mapa předpovědi na stole má teď navíc dokreslenou smyčku černým fixem. Kaylee: \"Pane. Ta mapa je federální vědecký produkt. Její úprava je trestný čin. Někdo ji upravil. Fixem.\"","c":[["Ukázat mapu na kameru. Smyčku nezmiňovat.","Všichni tu smyčku vidí. Nikdo o ní čtyři minuty přímého vysílání nahlas nemluví, a stane se z toho definující obraz roku."],["Nechat meteorologický úřad vydat podpůrné prohlášení.","Nepodepsané prohlášení na vaši podporu vyjde v devět večer. Každý meteorolog v úřadu se ten samý večer dozví, k čemu je úřad teď skutečně."],["\"Dostal jsem raný odhad.\" Jít dál.","Je to dokonce technicky pravda, jeden raný odhad ten stát skutečně zahrnoval. Kdybyste to řekl první den, skončilo by to; čtvrtý den to neskončí."],["Překreslit celé pobřeží, když už u toho jste.","Upravená mapa posune dva státy do vnitrozemí. Vyfotí ji, zarámují, a na katedře meteorologie visí dodnes jako varovný exponát."]]},"e-mortality":{"t":"Číslo z univerzity","x":"Univerzita vypočítala odhad nadúmrtnosti po hurikánu: zhruba tři tisíce. Dr. Pike má metodologii. \"Je to standardní postup, pane, ten samý, který vaše vlastní administrativa používá pro všechno ostatní. Zpochybnit tohle číslo znamená zpochybnit metodu, na kterou spoléháme.\"","c":[["Zpochybnit ho. Říct, že bylo vymyšlené, aby vám uškodilo.","Tři tisíce rodin slyší prezidenta nazvat jejich mrtvé příbuzné politickým konstruktem. Čtyři z nich vystoupí na kameru a příspěvek se vysílá týden."],["Číslo přijmout. Říct, že reakce byla přesto dobrá.","Obhajitelný argument, který skutečně můžete vyhrát, podaný hned vedle čísla, se kterým jste se rozhodl nebojovat. Je to nejkratší možná verze tohoto příběhu."],["Nařídit federální přezkum, ať vyprodukuje vlastní číslo.","Za jedenáct měsíců se vrátí s 2 975, což je pro vás horší než původní číslo, protože teď je oficiálně vaše."],["Házet další papírové utěrky.","Druhá návštěva, druhá tělocvična, druhé házení podpaží. Někdo, kdo byl v místnosti poprvé, je tam znovu, a řekne to na kameru."]]},"e-war-hero":{"t":"Zajatý muž","x":"Před lety jste řekl, že preferujete lidi, kteří se nenechali zajmout. Ten muž je teď mrtvý a dnes ráno, přímo dotázán, jste řekl, že jste nikdy nebyl jeho fanoušek a nikdy nebudete. Styčný důstojník pro veterány si vyžádal čtyři minuty a ještě si nesedl.","c":[["Trvat na tom. Byl přeceňovaný a řekl jsem to.","Čtyři senátoři z vaší vlastní strany zareagují jmenovitě do hodiny. Dva z nich jsou veteráni a jeden vede Senát."],["Dál nic neříkat. Nikdy.","Mlčení to za devět dní utiší. Je to nejlevnější dostupná odpověď a zároveň ta jediná, kterou je pro vás nejtěžší skutečně dát."],["Navštívit hrob. Bez kamer. Bez prohlášení.","Hrobník to o čtyři měsíce později nevyžádaně zmíní reportérovi, který píše o něčem úplně jiném. Zapůsobí to víc, než by dokázalo jakékoli prohlášení."],["Udělit mu posmrtnou medaili za to, že byl zajat.","Text vyznamenání píše někdo na Pentagonu s naprostou upřímností. Je to opravdu dojemné a nemožné přijmout s grácií."]]},"e-parade":{"t":"Obrněnci na třídě","x":"Tarrant má technické posouzení. \"Hlavní bojové tanky váží sedmdesát tun. Třída na tu zátěž není dimenzovaná a mosty taky ne.\" Otočí stránku. \"Dá se to udělat. Silnici budeme opravovat až do října a účet za opravu vyjde dráž než ta přehlídka.\"","c":[["Tanky. Všechny. Dolů po třídě.","Fotografie jsou výjimečné a doletí dál než cokoli jiného, co za rok uděláte. Čtyři spojenecké ambasády pošlou nevyžádané zprávy jen o té symbolice."],["Jen přelet. Žádné obrněnce.","Letadla jsou zdarma, oblíbená a nezanechávají koleje. Stejná přehlídka, desetina ceny, a žádné z titulků, které by vynesly tanky."],["Žádná přehlídka. Peníze do bydlení pro veterány.","Postaví se jedenáct set bytů. Stuhu za čtyři roky přestřihne někdo jiný a vaše jméno na budově nikde nebude."],["Řídit jeden tank osobně.","Seržant vám dá čtyři hodiny výcviku a viditelně si každou minutu užívá. Sejmete pouliční lampu. Vysílá se to živě."]]},"e-greenland-nasty":{"t":"\"Absurdní\"","x":"Nabídl jste koupi jejich území. Jejich premiérka použila slovo absurdní, anglicky, na kameru. Muriel má diář. \"Státní návštěva je za jedenáct dní, pane. Zrušit ji kvůli jednomu přídavnému jménu je možnost. Není to dobrá možnost, ale je to možnost.\"","c":[["Zrušit návštěvu. Nazvat ji protivnou.","Čtyři sta let starý spojenec je veřejně urážen kvůli jedinému slovu. Jejich parlament to den debatuje a jejich turistický úřad hlásí rekordní počet amerických rezervací."],["Jet stejně. Udělat si z toho vtip na večeři.","Sám otevřete tím slovem a místnost se opravdu zasměje. Je to nejlepší diplomatický večer vašeho funkčního období, a nikdo doma o něm neinformuje."],["Nabídku úplně stáhnout. Nikdy ji už nezmiňovat.","Úplně zmizí, osud každého nápadu, který nikdo nebrání. Čtyři poradci se uleví a jeden je, potichu, zklamaný."],["Nabídnout koupi premiérky místo toho.","Myšleno jako vtip, přenesené jako depeše, přijaté jako formální návrh. Odpověď jejich ministerstva zahraničí je mistrovské dílo zdvořilého úžasu."]]},"e-fell-in-love":{"t":"\"Zamilovali jsme se\"","x":"Popsal jste svou korespondenci s dědičným diktátorem frází \"zamilovali jsme se\". Muriel má přepis a tlustou složku reakcí spojenců. \"Pane, čtyři smluvní partneři se zvlášť ptali, jestli tohle znamená změnu politiky.\"","c":[["Zopakovat to. Ty dopisy byly krásné.","Podle každého, kdo je skutečně četl, jsou to kompetentně lichotivé formulářové dopisy sepsané výborem někde v suterénu."],["Zarámovat to jako osobní chemii sloužící národnímu zájmu.","Profesionálně znějící verze totožného tvrzení. Čtyři ministerstva zahraničí s tím dokážou pracovat a ani jedno tomu nevěří ani slovo."],["Vzít to zpět. Osobní vřelost není politika.","Ústup se nahlásí jednou. Ta fráze se hlásí deset let. Je to standardní směnný kurz a nikdy se nezlepší."],["Zveřejnit dopisy v plném znění.","Ukážou se nudnější, než si kdo dovedl představit, a dvakrát zmiňují golfové hřiště. Zveřejnění příběh okamžitě ukončí a zklame naprosto všechny."]]},"e-riviera":{"t":"Přestavba","x":"Navrhl jste, aby Spojené státy převzaly válkou poškozené území a přestavěly ho na letovisko. Muriel drží reakční depeši a ruka se jí netřese ustáleně. \"Devět spojeneckých vlád, pane. Všech devět. Dvě použily slovo 'vysídlení' a jedna mnohem starší slovo.\"","c":[["Rozvinout to. Ukázat vizualizace.","Architektonická vizualizace přímořského letoviska na masovém hrobě se objeví na tiskovce a koluje roky jako doklad číslo jedna něčeho."],["Přerámovat to jako fond na obnovu.","Nudný, obhajitelný, naprosto konvenční návrh pomoci, který čtyři spojenci okamžitě spolupodepíšou. Stejné peníze, žádné pobouření."],["Stáhnout to. Říct, že to byla myšlenka, ne plán.","\"Myšlenka, ne plán\" je přiznání, že prezident řekl věc bez toho, aby ji promyslel, což je menší příběh než ta alternativa, jen o vlásek."],["Nabídnout přestavbu na golfové hřiště místo toho.","Osmnáct mistrovských jamek, navržených za čtyři dny někým, kdo zjevně neměl ponětí, co pod nimi nedávno bylo."]]},"e-fifty-first":{"t":"\"Guvernére\"","x":"Oslovil jste sousedního premiéra veřejně čtyřikrát \"guvernére\" a nahlas uvažoval o hospodářském nátlaku. Muriel: \"Pane, jejich maloobchodní bojkot amerického zboží je teď na devíti procentech dovozu a stoupá, a je naprosto dobrovolný, což znamená, že není s kým to vyjednat pryč.\"","c":[["Dál mu říkat guvernére. Zjevně to funguje.","Jejich domácí politika se přeskupí kolem toho, že nechtějí být anektováni. Strana, která byla čtrnáct bodů pozadu, vyhraje jasně, kampaň staví skoro výhradně na vás."],["Přestat. Oslovovat ho premiérem a myslet to vážně.","Bojkot postupně slábne asi dva roky. Nikdy úplně neskončí, protože nákupní zvyk přežije clo o pořádnou míli."],["Eskalovat na cla. Udělat z toho vtipu nákladnou záležitost.","Dvě propojené ekonomiky se rozpojí o čtyři procenta za rok. Čtyři pohraniční města na vaší vlastní straně ztratí svého největšího zaměstnavatele."],["Formálně je pozvat, ať zažádají o členství ve federaci.","Skutečná přihláška je doručena kurýrem na jejich ambasádu, vyplněná do posledního políčka jako vtip, a vrácena. Nikdy se nezjistilo, kdo ji vyplnil."]]},"e-currency":{"t":"Portrét na bankovce","x":"Lyle má odpověď mincovny a čte ji jako muž, který něco odzbrojuje. \"Neexistuje zákon zakazující žijící osobu na měně. Existuje sto padesát let stará praxe, interní směrnice a velmi dlouhé ticho, když jsem se zeptal proč.\"","c":[["Stovku. Udělat to.","Každá transakce v zemi teď nese vaši tvář. Čtyři země, jejichž měna to dělá, jsou jmenovány v každém článku, který se kdy napíše."],["Pamětní minci. Omezený náklad.","Vyprodá se za devět hodin a obchoduje se za čtyřnásobek nominální hodnoty. Legální, populární, a stojí to přesně jeden odstavec kritiky."],["Ani jedno. Měna na to není.","Lyle vydechne způsobem, který jste od něj nikdy neslyšel. Směrnice přežije ještě jednu administrativu, což je maximum, čeho směrnice kdy dosáhne."],["Dát svou tvář jen na jednocentovou minci.","Nejmenší nominální hodnota, ta, kterou už i tak ruší. Vyznívá to buď jako mimořádná skromnost, nebo kolosální omyl, a nikdo se neshodne, co z toho."]]},"e-arts-board":{"t":"Schůze rady","x":"Deborah má připravené dopisy. \"Rada odvolána, nová rada dosazena, a vy jako předseda. Je to v mezích vaší jmenovací pravomoci.\" Odmlčí se. \"Pane, rezignace začnou přicházet do hodiny, a u dvou z nich to budou lidé, kterých je opravdovými fanoušky vaše vlastní rodina.\"","c":[["Odeslat je všechny. Osobně předsedat první schůzi.","Čtyři významní umělci odstoupí do týdne od sezóny. Budova si udrží program tím, že najme lidi, kteří si nemohli dovolit odmítnout."],["Vyměnit radu. Předsednictví si nenechat.","Stejná kontrola, minus fotografie. Nikdo nerezignuje kvůli radě, kterou nikdy nepotkal a nedokáže jmenovat."],["Radu nechat být. Přijít místo toho na premiéru.","Sedíte čtyři hodiny na moderním tanci s viditelnou statečností. Umělecká ředitelka řekne čtyřem lidem, že to byl nejpřekvapivější večer její kariéry."],["Předsedat a sám sestavit program sezóny.","Vaše sezóna je devět poctových koncertů, kouzelník a symfonický orchestr hrající filmovou hudbu. Prodá se o 40 procent víc než minulá sezóna, fakt, o kterém nikdo zúčastněný nechce mluvit."]]},"e-rename-water":{"t":"Vodní plocha","x":"Nařízení přejmenovává vodní plochu ohraničenou třemi zeměmi. Muriel má praktickou poznámku. \"Můžeme ji přejmenovat na vlastních mapách, pane. Na cizích mapách ne, a mezinárodní hydrografický úřad rozhodne o čemkoli tak za jedenáct let.\"","c":[["Podepsat to. Naše mapa je jediná, na které záleží.","Dvě sousední země to odmítnou převzít. Každá letecká mapa na světě teď nese obě jména, oddělená lomítkem, trvalý pomník sporu."],["Podepsat to pro domácí použití. Netlačit to v zahraničí.","Domácí mapy se změní, zahraniční vztahy ne, a celá akce stojí 400 000 dolarů na přetisk."],["Nepodepsat to. Má jméno.","Nic se nestane, což je správný výsledek pro návrh přejmenovat moře, a nahlásí se to přesně nikde."],["Pojmenovat ji po sobě.","Čtyři kartografové to písemně odmítnou. Jeden to udělá, následně nesežene práci, a mapa se do deseti let stane sběratelským kouskem."]]},"e-wire-ban":{"t":"Redakční příručka","x":"Tisková agentura pořád používá staré jméno té vody, protože to říká její redakční příručka, a ta příručka řídí čtyři tisíce redakcí. Kaylee: \"Můžeme je vyloučit z místnosti, pane. Nemůžeme je vyloučit z příručky, a příručka je to skutečné bojiště.\"","c":[["Vyloučit je. Ze všeho. Dnes.","Žalují, vyhrají, částečně prohrají v odvolání, a příručky se nikdy nedotknou. Strávil jste jedenáct měsíců přesouváním jednoho slova uvnitř jedné budovy."],["Vyloučit je jen z malé místnosti. Velké akce zachovat.","Dost na to, aby to udělalo dojem, ne dost na to, aby to založilo žalobu. Jejich právníci žalobu o zasedací pořádek nedoporučí."],["Nechat to být. Je to redakční příručka.","Staré jméno zůstane standardem všude na světě. Vždycky by tomu tak bylo, a vy jste právě ušetřil soudní řízení a rok života."],["Vydat federální redakční příručku a nařídit ji.","Čtyři sta stran, vydaných všem úřadům, jedenáct pravidel o vašem jméně a jedno o oxfordské čárce, což je jediné pravidlo, které vyvolá vzpouru."]]},"e-complicated":{"t":"\"Nikdo to nevěděl\"","x":"Řekl jste na kameru, že nikdo nevěděl, že zdravotnictví může být tak komplikované. Dr. Pike drží hromadu papíru. \"Pane, tohle je žádost o výjimku jednoho jediného státu. Má jedenáct set stran. Všichni to věděli. V určitém smyslu je to jediná věc, kterou kdokoli poslední třicet let vůbec ví.\"","c":[["Trvat na tom. Nikdo mi neřekl, že je to tak zlé.","Prezident veřejně přizná, že nevěděl, že centrální otázka domácí politiky jeho kariéry je komplikovaná. Obě strany to citují navždy, z opačných důvodů."],["\"Myslel jsem, že mi to nikdo poctivě nevysvětlil.\" Obrat.","Záchrana, která je zároveň obratná i přibližně pravdivá. Pike, který to vysvětluje poctivě dvacet let, tentokrát výjimečně mlčí."],["Sednout si s Pikem na čtyři hodiny a fakt se to naučit.","Vyjdete z toho schopen bez poznámek vysvětlit rizikové skupiny pojištěnců. Je to nejužitečnější odpoledne vašeho prezidentství, a nikdo o tom nikdy nenapíše."],["Prohlásit zdravotnictví za jednoduché výnosem.","Výnos má šedesát jedna stránek definic ustanovujících, co jednoduchost znamená. Ironii zaznamená úplně každý, kdo to čte."]]},"e-light":{"t":"Ta druhá věc na brífinku","x":"Nešlo jen o tu první poznámku. Na stejném brífinku jste se ptal, jestli by se do těla nedalo přivést velmi silné světlo. Dr. Pike je tu s jednostránkovou poznámkou. \"Pane, čtyři nemocnice přijaly hovory. Ne mnoho. Ale čtyři.\"","c":[["Říct, že jste to myslel sarkasticky.","Přepis nezní jako sarkasmus, ani video ne. Tvrzení se stane vlastním, menším, déle trvajícím příběhem než ta poznámka sama."],["Nechat Pika vydat jasný pokyn. Sám neříkat nic.","Jednostránková klinická poznámka dorazí na každé pohotovostní oddělení v zemi do šesti hodin. Hovory ustanou."],["Přestat s brífinky.","Brífinky vám byly hodné čtyř bodů týdně a stály zhruba stejně. Ukončit je je remíza, kterou nikdo na žádné straně vlastně nechtěl."],["Nechat světelný nápad pořádně prozkoumat.","Skutečná rešerše se vrátí s popisem čtyř skutečných nitrožilních světelných terapií a zdvořile uzavře, že tohle žádná z nich nebyla."]]},"e-testing":{"t":"Zpomalit testování","x":"Řekl jste, že když se testuje v takovém rozsahu, najde se víc případů, a proto jste požádal, ať se testování zpomalí. Dr. Pike úplně ztuhne. \"Pane, byl to vtip? Mám čtyři ředitele zdravotnictví ze států, kteří se mě ptají, a já upřímně nevím, co jim mám říct.\"","c":[["Nebyl to vtip. Testování zpomalit.","Testování se ve skutečnosti nezpomalí, protože ho provádí státy a nemocnice, ne vy. Ta věta přežije danou politiku o dobrou dekádu."],["\"Byl jsem sarkastický.\" Nechat to tak.","Čtyři z vašich vlastních úředníků do dne veřejně řeknou, že jste nebyl, protože pokyn už dostali a jednali podle něj."],["Testování zdvojnásobit a čísla hlásit denně.","Počet případů prudce stoupne, protože je teď skutečně nacházíte. Pike tomu říká nejodvážnější politické rozhodnutí, jaké kdy viděl, a stojí vás to devět bodů."],["Testovat jen lidi, u kterých je pravděpodobný negativní výsledek.","Někdo to v dobré víře sepíše a rozešle jako návrh protokolu, než ho odchytí. Návrh přežije v archivu dodnes."]]},"e-send-her-back":{"t":"Skandování","x":"Dav začal skandovat o sedící kongresmance a je to tři slova dlouhé. Přestal jste mluvit. Deborah do sluchátka: \"Zatím třináct vteřin, pane. Cokoli uděláte v příštích pěti, je to, co se bude přehrávat.\"","c":[["Počkat. Nechat to doznít. Pak pokračovat.","Třináct vteřin ticha, vysílaných živě. Čtyři vaši vlastní členové se od toho jmenovitě distancují a vy strávíte týden vysvětlováním jedné pauzy."],["Přerušit to. \"Tohle u nás neděláme.\"","Dav okamžitě přestane, což dokazuje, že by přestal okamžitě kdykoli během předchozích třinácti vteřin, kdybyste ho o to požádal."],["Mluvit skrz to. Změnit téma uprostřed věty.","Žádná konfrontace, žádné schválení. Je to zbabělá volba a s velkým odstupem ta nejúčinnější na stole."],["Zahájit jiné skandování. Okamžitě. Jakékoli.","Začnete skandovat o infrastruktuře. Dav se přidá, zmatený, ale loajální, a třicet tisíc lidí stráví devadesát vteřin křikem o mostech."]]},"e-stand-by":{"t":"Odpověď z debaty","x":"Vyzván, ať je odsoudíte, jste jim řekl, ať ustoupí a jsou připraveni. Kaylee má dopad. \"Vytiskli si to na merchandise, pane. Do hodiny. Berou to jako pokyn, a upřímně, gramaticky je to pokyn.\"","c":[["Odmítnout to upřesnit. Nechat je, ať si to vykládají, jak chtějí.","Ozbrojená skupina teď věří, že má od prezidenta pohotovostní rozkazy. Na tomhle uspořádání se během následujících měsíců nic nezlepší."],["Odsoudit je jmenovitě příští ráno.","Jmenovitě, bez vyzvání, jednou větou. Merchandise se přestane prodávat a čtyři organizátoři veřejně řeknou, že se cítí opuštěni, což byl ten záměr."],["Odsoudit \"veškerý extremismus\", aniž byste kohokoli jmenoval.","Odsouzení, které nikoho nejmenuje, slyší všichni jako odsouzení nikoho, což je přesně a doslova to, čím je."],["Nařídit jim, ať ustoupí *dopředu*, aby otestovali tu teorii.","Vysvětlení je v každém měřitelném ohledu horší než originál. Čtyři sta lidí to do dne vezme naprosto doslova."]]},"e-hostages":{"t":"Slovo pro ně","x":"Začal jste odsouzené výtržníky nazývat rukojmími. Sy: \"Pane, čtyři se přiznali. U soudu. S obhájcem. Přiznání viny je věc, kterou rukojmí fyzicky nemůže učinit, a přepisy jsou veřejné dokumenty.\"","c":[["Pokračovat v tom. Pouštět jejich telefonáty na shromážděních.","Nahrávka odsouzených vězňů zpívajících hraje předtím, než vejdete na pódium, čtyřicetkrát, a nikdy nepřestane být mimořádná."],["Místo toho tvrdit, že tresty byly nepřiměřené.","Argument o výši trestu je aspoň argument. Čtyři z těch trestů opravdu byly dlouhé, a kdybyste řekl jen tohle, ten bod byste si skutečně vybojoval."],["Přestat to slovo používat.","Vaše hnutí si toho do dne všimne a bere to jako první krok zrady, což v jejich pojetí víceméně je."],["Nabídnout jejich výměnu za skutečné rukojmí.","Návrh se odešle na ministerstvo zahraničí, které to vůbec nečekalo. Jejich odpověď upřímně žádá o vyjasnění podmínek."]]},"e-acting":{"t":"Pověřený","x":"Deborah má organizační schéma a většina jména je kurzívou. \"Jedenáct vedoucích úřadů je pověřených. Čtyři jsou pověřeni už přes rok. Pověřený úředník slouží zcela podle vaší libosti a dá se vyměnit do oběda, proto ho máte rád, a proto je zákonná lhůta už dávno překročená.\"","c":[["Nechat je všechny pověřenými. Natrvalo.","Vláda lidí, kteří se dají okamžitě odvolat. Všechno funguje trochu hůř a nic se nikdy neodmítne, což byla vždycky ta výměna."],["Nominovat ty čtyři, které by potvrdili.","Čtyři potvrzení ministři s nezávislým postavením, každý vám za rok jednou řekne ne. Všechny čtyřikrát jste se mýlil."],["Nominovat všechny. Přijmout ztráty.","Sedm potvrzeno, čtyři odmítnuti. Odmítnutí bolí a potvrzení jsou trvalá, a trvalost je ta věc, kterou jste si dosud jen půjčoval."],["Jmenovat jednu osobu pověřenou pro všech jedenáct rolí.","Je to na chvíli zákonné. Zastává jedenáct ministerstev devět dní a pak o tom napíše knihu, se kterou se hodně těžko polemizuje."]]},"e-loyalty-lunch":{"t":"Oběd","x":"Je večeře a jste tam sami dva. Ředitelka Quistová si už všimla dvou prostřených míst v místnosti pro čtyřicet. Chystáte se použít slovo, které vám Bo dvakrát, písemně, zakázal používat.","c":[["\"Potřebuju loajalitu. Očekávám loajalitu.\"","Místo toho vám nabídne upřímnost. Ta výměna se do hodiny sepíše, s datem, na parkovišti, a do roka se přečte nahlas výboru."],["Požádat o nezávislost, a myslet to vážně.","Řekne to veřejně o měsíc později, nevyžádaně, pod přísahou. Je to nejcennější věta, kterou o vás kdo za celé funkční období pronese."],["Mluvit o jídle. Neptat se na nic.","Devadesát minut o vínu. Odejde zmatená a nesepíše nic, což je jediný výsledek, který vám tady vlastně pomůže."],["Požádat ji, ať podá loajalitu.","Vtip, špatně podaný, přesně v okamžiku, kdy usoudila, že ten večer je neškodný. Zapíše si ho přesto, doslovně, s otazníkem."]]},"e-witch-hunt":{"t":"Ta fráze","x":"Kaylee zase počítala. \"Čtyři sta jedenáct použití stejných dvou slov za osmnáct měsíců. Teď je s vámi spojenější než se sedmnáctým stoletím.\" Zaváhá. \"Pane, vyšetřování se za chvíli zveřejní, a ta fráze bude to, co budou lidé mít místo zprávy.\"","c":[["Říct to ještě čtyři sta krát.","Funguje to naprosto. Zpráva vyjde a 61 procent země už ji má zaškatulkovanou pod frází, kterou slyšeli dřív, než slyšeli cokoli jiného."],["Přestat to říkat. Napadnout raději zjištění.","Hádat se s dokumentem je těžší, než dokument odmítnout, a podstatně účinnější u těch čtyř procent, co vlastně rozhodují volby."],["Plně spolupracovat a neříkat vůbec nic.","Vyjde včas, najde míň, než chtěla obě strany, a nepřečte si to nikdo, standardní osud jakéhokoli dokumentu, o kterém nikomu neřekli, ať se o něj zajímá."],["Nechat si tu frázi zaregistrovat jako ochrannou známku.","Přihláška se podá vážně a zamítne se s odůvodněním, že termín je běžně užívaný, hlavně díky vám."]]},"e-hotel-booking":{"t":"Rezervace delegace","x":"Miriam má rezervace. \"Čtyři zahraniční delegace, všechny ve vašem hotelu, všechny čtrnáct dní před svými obchodními jednáními.\" Odkládá je. \"Nikdo je o to nepožádal. To je ta část, kterou pořád nedokážu jasně vysvětlit: nikdo se nemusel ptát.\"","c":[["Vzít ty rezervace. Je to hotel.","Platba od cizího státu prezidentovi, za zveřejněnou cenu, za skutečný pokoj. Je to nejčistší možná verze nejstaršího možného problému."],["Vzít je. Zisk poslat do státní pokladny.","Dobrovolný, neověřitelný odhad možného zisku, zveřejňovaný ročně, odstraní 90 procent kritiky za zlomek nákladů."],["Nařídit hotelu odmítat rezervace zahraničních států.","Pokyn se sepíše a dodrží. Stojí to zhruba 12 milionů dolarů ročně a je to jediná položka na tomhle seznamu, která opravdu něco řeší."],["Naúčtovat jim čtyřnásobek a nazvat to clem.","Dvě delegace to bez námitek zaplatí, což je nejalarmnější dostupný výsledek a všimnou si ho čtyři zpravodajské služby."]]},"e-jet":{"t":"Letadlo","x":"Cizí vláda nabídla letadlo. Tarrant má bezpečnostní posouzení a pečlivě volí slova. \"Zbavit ho vnitřního vybavení a přestavět na náš standard trvá čtyři roky a stojí víc, než koupit nové rovnou. A pane, formulace je sporná. Oni tvrdí, že bylo nabídnuto. Někdo z naší strany se zeptal první.\"","c":[["Přijmout to. Nazvat to nevyžádaným darem.","Záznam o tom, kdo koho oslovil jako první, vyjde na povrch do čtrnácti dnů, protože vždycky vyjde, a slovo \"nevyžádaný\" se místo letadla stane příběhem."],["Přijmout ho pro letectvo. Ne osobně.","Dar státu státu, řádně převedený, nakonec do muzea. Je to nudná odpověď, a přežije každý výbor, který se jí dotkne."],["Odmítnout ho. Koupit vlastní.","Stojí to čtyři miliardy dolarů, trvá to šest let, a nezbývá o tom naprosto nic napsat. Tarrant tomu říká dobře utracené peníze."],["Přijmout ho a odletět s ním do muzea osobně.","Nemáte kvalifikaci na ten typ letadla. Sednete si na levé sedadlo, na zemi, na fotku, a popisek napíše někdo, kdo si to napřed ověřil."]]},"e-poll-numbers":{"t":"Data z průzkumů","x":"Nadia má skutečná čísla a ta, která jste citoval. Liší se o devatenáct bodů. \"Ten, co používáte, je online dobrovolný průzkum mezi vašimi vlastními podporovateli, pane. Vím, kdo ho zadal, protože mě požádali, ať ho navrhnu, a já jsem odmítla.\"","c":[["Citovat dál ten dobrý. Existuje.","Skutečně existuje, což ho dělá spíš nevyvratitelným než pravdivým, a nevyvratitelnost se na volném trhu, jak se ukazuje, cení podstatně víc."],["Citovat ten skutečný. Říct, že máte práci.","Upřímnost k číslu je vám za čtvrtletí čtyři body vydatnější, než kdy dodalo falešné číslo."],["Přestat vůbec citovat čísla.","Nadia tomu říká nejzdravější rozhodnutí funkčního období. Vydrží jedenáct dní."],["Objednat průzkum, jestli jsou průzkumy vůbec přesné.","Šedesát jedna procent řekne ne, což citujete jako důkaz, že průzkumy ukazující vaši prohru jsou chybné, použití zjištění, se kterým Nadia opravdu nepočítala."]]},"e-rally-length":{"t":"Devadesátá minuta","x":"Jste devadesát čtyři minuty do čtyřicetiminutového slotu. Boyd Hackler v zákulisí dělá gesto, o kterém jste se rozhodl, že znamená \"pokračujte\". Aréna se musí uvolnit pro hokejový zápas a venku v mrazu stojí čtyři tisíce lidí s lístky na něj.","c":[["Ještě čtyřicet minut. Přišli si pro tohle.","Hokejový zápas začne o devadesát minut později. Jeho fanoušci, dotázaní cestou dovnitř, mají na to velmi jasný názor."],["Zabalit to do pěti minut. Silný závěr.","Sevřený, úderný konec, který v televizi zabírá líp než předchozích devadesát čtyři minut. Boyd si čas poznamená a nikdo si toho nevšimne."],["Skončit teď a zůstat podávat ruce místo toho.","Dvě hodiny podávání rukou čtyřem tisícům lidí, cennější než ten projev, a žádná kamera kvůli tomu nezůstane."],["Zůstat na pódiu a sledovat hokej.","Sledujete tři třetiny ze skládací židle u mantinelu. Je to nejoblíbenější věc, co za rok uděláte, a to o míle."]]},"e-golf-count":{"t":"Účetní kniha odpolední","x":"Někdo vede webovou stránku počítající vaše odpoledne na vlastních hřištích. Kaylee má číslo. \"Dvě stě osmdesát jedna dní, pane, a stránku teď citují jako zdroj i tiskové agentury, což znamená, že povýšila z koníčku na fakt.\"","c":[["Jít víc. Oznamovat každé.","Přiznat to odstraní úder a nahradí ho číslem, které veřejně jen dál roste, což se ukáže jako podstatně horší."],["Chodit dál, ale přestat účtovat vládě detaily.","Náklad byl vždycky ten skutečný příběh. Odstraňte ho, a zbyde muž hrající golf, což není příběh nikde na světě."],["Omezit to. Na čtvrtletí pracovat i o víkendech.","Tři měsíce viditelné práce vám přinesou čtyři body podpory navíc a učiní vás na celé čtvrtletí nesnesitelným."],["Konat schůze kabinetu na hřišti.","Jedenáct ministrů ve flotile golfových vozíků, zapisujících poznámky. Přijmou se dvě opravdu užitečná rozhodnutí a poznámky se nikdy nenajdou."]]},"e-enemy-phrase":{"t":"Nepřátelé lidu","x":"Dr. Weirová si vyžádala pět minut kvůli jedné frázi. \"Pane prezidente, nejsem tu, abych vám řekla, ať neútočíte na tisk. Jsem tu, abych vám řekla, odkud přesně ta konkrétní formulace pochází, protože myslím, že to nikdo neudělal, a nepochází to odnikud, odkud byste chtěl.\"","c":[["Nechat si to. Zabírá to a vím, odkud to pochází.","Čtyři historici napíšou nezávisle na sobě stejný sloupek. Její pointa nikdy nebyla, že to selže; bylo to, že to zabere, a řekne vám to cestou ven ze dveří."],["Přejít na \"fake news\". Stejný boj, žádná genealogie.","Identický efekt, žádná poznámka pod čarou, žádní historici. Je to nejúčinnější úprava, kterou za čtyři roky ve svém slovníku uděláte."],["Frázi i celý ten boj opustit.","Pokrytí se nezlepší. Nikdy by se nezlepšilo. Ten boj byl vždycky ta věc, co skutečně fungovala, a vy jste v ní právě přestal."],["Zeptat se jí, které režimy to používaly, a dělat si poznámky.","Odpoví podrobně, s daty, dvacet minut. Popíšete čtyři stránky poznámek. Ona stráví zbytek života přemýšlením, k čemu to bylo."]]},"e-vermin":{"t":"Návrh s tím zvířecím slovem","x":"Gideon Poe označil podstatné jméno v zítřejším projevu. \"Je to slovo pro zvíře, použité na občany, ve větě o životě mezi námi.\" Nezvedá oči. \"Pane, já to nenapsal. Snažím se zjistit, kdo to napsal, a nedaří se mi to, což je samo o sobě odpověď.\"","c":[["Nechat to. Přednést to přesně, jak je napsáno.","Historici zareagují do hodiny, ve velkém počtu, citují tři stejné režimy. Je to nejcitovanější věta vašeho prezidentství, a nikdy ne pochvalně."],["Vyměnit to podstatné jméno. Nechat větu.","Stejná reakce sálu, žádné archivní záběry, žádné sloupky. Gideon tomu říká nejlevnější úprava, jakou kdy udělal, a myslí to naprosto vážně."],["Vyškrtnout celý ten úsek.","Projev je o čtyři minuty kratší a podstatně lepší. Nikdo si nevšimne absence, ta trvalá, nevděčná tragédie dobré redakce."],["Přednést to, ale o vlastní straně.","Sál neví, co s tím. Dva lidé zatleskají. Je to nejopravdověji znepokojivých devadesát vteřin celého funkčního období."]]},"e-tylenol":{"t":"Rada z pódia","x":"Spojil jste běžný lék proti bolesti s vývojovou poruchou a navrhl rozvolnit dětské očkování. Dr. Pike přijde bez pozvání. \"Pane, čtyři velké studie tvrdí opak a mohu vám je mít na stole do hodiny. Pediatrická sdružení už píšou stanoviska.\"","c":[["Zopakovat to. Hlasitěji. Lidé to musí slyšet.","Termíny očkování klesnou za čtvrtletí o devět procent ve čtyřech státech. Číslo se zveřejní, přisoudí, a už se nikdy nevrátí zpátky."],["\"Nejsem lékař. Zeptejte se svého.\" Jít dál.","Šest slov napraví většinu škody. Pike poté řekne, že to byla správná odpověď a že od vás nečekal, že ji skutečně uslyší."],["Nechat Pika, ať vede brífink místo vás, od teď.","Nudný muž dvakrát týdně po rok čte fakta. Dvanáct měsíců v kuse se nic nezvrtne, a nikdo za to nikomu nepoděkuje."],["Vzít si lék na kameru, ať dokážete, že je v pořádku.","Vezmete si dva, naživo v televizi, poté, co jste je právě nazval nebezpečnými. Nikdo v místnosti nedokáže vymyslet doplňující otázku."]]},"e-blago":{"t":"Velmi slušný člověk","x":"Zmírnil jste trest guvernérovi odsouzenému za pokus prodat senátorské křeslo a popsal ho potom jako velmi slušného člověka. Sy: \"Porota ho odsoudila za prodej veřejného úřadu. Pane, to je ten trestný čin. To je přesně to, co udělal.\"","c":[["Zopakovat to. Zacházeli s ním nespravedlivě.","Dalších čtyři lidé žádající o milost si najme stejného právníka, jakého použil on, což je tržní signál, a přesně tak se to i nahlásí."],["Zmírnit trest potichu. O tom muži neříkat nic.","Zmírnění trestu bez přívlastku je rutinní akt milosti. Ten přívlastek byl vždycky celý ten příběh."],["Stáhnout to. Byl to špatný případ.","Udělenou milost nelze vzít zpátky. Sy to vysvětluje a vy strávíte celé čtyři minuty odmítáním tomu uvěřit."],["Jmenovat ho do něčeho.","Federální poradní rada pro veřejnou integritu. Jmenování je skutečné, oznámí se v pátek, a trvá jedenáct dní."]]},"e-antifa":{"t":"Označení","x":"Duane má návrh výnosu a jeden problém. \"Označuje organizaci. Pane, žádná organizace to není. Žádné členství, žádné vedení, žádný bankovní účet, a nic, na co by šlo doručit soudní obsílku. Úřad se písemně ptá, koho přesně mají zatýkat.\"","c":[["Podepsat to. Nechat úřad, ať vyřeší podrobnosti.","Bez organizace, kterou by šlo skutečně obžalovat, se označení začne uplatňovat na jednotlivce podle jejich názorů, což byl vždycky jediný způsob, jak to mohlo fungovat."],["Označit čtyři konkrétní skupiny, které skutečně existují.","Jmenované entity s bankovními účty a vedením, stíhatelné podle stávajícího zákona. Do dvou let následují čtyři odsouzení a ani jedno se neruší."],["Nepodepisovat to. Použít zákony, které máme.","Stávající zákony fungují dobře, protože politické násilí je nezákonné už dvě stě let a mezera v zákoně nikdy neexistovala."],["Označit sám sebe, ať otestujete standard.","Papíry se sepíšou jako demonstrace a, katastrofálně, opravdu podají. Strávíte devět dní na seznamu, než si toho někdo všimne."]]},"e-shithole-confirm":{"t":"O osm let později","x":"Před osmi lety jste popřel to slovo. Dnes ráno, nevyžádaně, v rozhovoru o něčem úplně jiném, jste ho použil znovu a potvrdil původní tvrzení. Kaylee má oba záznamy připravené a nepouští je. \"Pane, právě jste potvrdil zprávu, kterou jste celý rok nazýval smyšlenou.\"","c":[["Říct, že jste to vždycky tvrdil a měl jste pravdu.","Oba záznamy běží vedle sebe čtrnáct dní. Novináři, které jste rok nazýval lháři, jsou nakonec nezvykle velkorysí, když to celé skončí."],["Říct, že popírání se týkalo přesného znění.","Je to, technicky, přesně to, co původní popření řeklo. Obhajoba \"technicky co to řeklo\" nikdy nefungovala, a nezačne teď."],["Omluvit se novinářům jmenovitě.","Čtyři jména, nahlas, nevyžádaně. Vaše hnutí to bere jako zradu, a dva ze čtyř novinářů veřejně řeknou, že to nic nezměnilo, a přece na tom záleželo."],["Tvrdit, že jste citoval někoho jiného v místnosti.","Každý další v té místnosti je pořád naživu, a čtyři z nich se do hodiny na to zeptají. Všichni čtyři odmítnou stejnou opatrnou větou."]]},"e-invasion-word":{"t":"Podstatné jméno pro příchozí","x":"Gideon má graf četnosti. \"To slovo se objevuje v každém projevu šest týdnů, a jen v šesti týdnech před volbami. Pane, to není popis, to je harmonogram, a někdo tenhle graf zveřejní.\"","c":[["Používat ho víc. Funguje to, protože je to pravda.","Graf se zveřejní. Korelace s volebním kalendářem je přesná, což je horší než jakékoli jednotlivé použití toho slova."],["Používat ho dál i po volbách.","Konzistence úplně odstraní obvinění z cynismu a nic vás nestojí, protože to slovo dělá stejnou práci v březnu jako v říjnu."],["Zavrhnout ho. Mluvit místo toho o mzdách a bydlení.","Ekonomický argument, obhajitelný a nudný. Přesvědčí o čtyři sta tisíc lidí víc a nikoho naprosto nenadchne."],["Použít to slovo na něco jiného úplně.","Špatnou pylovou sezónu dvakrát popíšete jako invazi, s naprostým přesvědčením. Čtyři alergologické spolky vydají prohlášení, a jeden vám poděkuje."]]},"e-lee":{"t":"Generál na podstavci","x":"Nazval jste ho skvělým generálem. Dr. Weirová nezpochybňuje to vojenské hodnocení a řekne to na rovinu. \"Byl schopný velitel, pane prezidente. Byl schopný velitel armády postavené na tom, aby lidi drželi jako majetek, a socha vznikla šedesát let po jeho smrti, kvůli lidem, kteří si tím dělali poznámku o něčem, co se dělo přesně tehdy.\"","c":[["Nařídit ochranu soch. Všech.","Federální ochrana pomníků postavených jako politická prohlášení, obhajovaná jako historie. O komentář požádají čtyři historiky a všichni čtyři citují to samé datum."],["Nechat to na obcích. Dál nic neříkat.","Čtyřicet jedna obcí rozhodne čtyřicet jedna odlišnými způsoby za čtyři roky, a nic z toho se nestane celostátní zprávou."],["Chválit vojáka, podporovat odstranění.","Rozlišení, které čtyři historici pokládají za intelektuálně poctivé a vaše základna za přímou zradu, ze stejných dvou faktů."],["Nahradit je všechny sochami sebe.","Jedenáct podstavců se přestaví. Čtyři z nových soch spadnou do deseti let, stejným procesem, se stejnými argumenty, a nikomu to tehdy nepřijde vtipné."]]},"e-crowd-again":{"t":"Letecký snímek, znovu","x":"Jiná akce, jiná letecká fotografie, stejný spor. Kaylee má oba roky vedle sebe. \"Pane, tenhle boj jste vedl už počtvrté. Nikdo ho nikdy nevyhrál. Fotku pořizuje satelit a satelit nemá názor.\"","c":[["Bojovat s tím. Znovu. Nařídit opravená čísla.","Archivář z povolání je podruhé za čtyři roky přeložen, do té samé budovy bez oken, a číslo je opět oficiální."],["\"Davy jsou posedlost médií.\" Další otázka.","Příběh zemře za čtyřicet minut. Něco ve vás s ním zemře taky a Kaylee si poznamená, ať tu větu použije znovu příště."],["Zveřejnit vlastní záznam z dronu. Nechat lidi počítat.","Záběry ukazují velký, skutečný, nadšený dav, zhruba třetinu udávané velikosti. Zveřejnit ho je nejlepší dostupná verze prohry."],["Uspořádat příští shromáždění tam, kde nejde nafotit z letadla.","Hala s tvrdou kapacitou devět tisíc lidí, kterou pak oznámíte, že navštívilo osmdesát tisíc."]]},"e-cabinet-italics":{"t":"Rezignační dopis","x":"Dva členové rady odstoupili a zveřejnili své dopisy. Deborah má oba. \"Zdvořilé, konkrétní, čtyři odstavce dlouhé. Ani jeden vás jménem nezmiňuje, pane, což je přesně ta věc, díky které se rozletí do světa.\"","c":[["Osobně napadnout oba dva.","Jmenovat lidi, kteří odmítli jmenovat vás, celou tu výměnu obrátí naruby. Jejich dopisy se čtou nahlas ve čtyřech pořadech; váš v žádném."],["Přijmout rezignace bez komentáře.","Rezignace, na kterou nikdo nereaguje, je jen rezignace. Rezignace, na kterou někdo reaguje, je skandál, a vy jste se rozhodl tu druhou polovinu nedodat."],["Požádat je, ať zůstanou. Osobně. Telefonem.","Jedna zůstane. Řekne o tom hovoru čtyřem lidem, a příběh se změní na prezidenta, který zvedl telefon, což se nikdy předtím nestalo."],["Přijmout rezignace a oběma nabídnout něco lepšího.","Oba odmítnou, písemně, se zjevnými obtížemi. Jedna si dopis s nabídkou schová a zmíní ho o jedenáct let později v memoárech."]]},"e-birthday-parade":{"t":"Náhoda","x":"Boyd má problém s datem. \"Přehlídka k výročí ozbrojených sil padá na vaše narozeniny. Doopravdy, je to skutečné výročí a skutečná náhoda.\" Pohne se. \"Nikdo mimo tuhle místnost tomu neuvěří, pane. Kalendář jsem si sám ověřil čtyřikrát, protože jsem tomu taky nevěřil.\"","c":[["Uspořádat ji. Zmínit narozeniny z pódia.","Skutečná náhoda se jedinou větou promění v úmyslnou, před jedenácti tisíci sloužícími vojáky."],["Uspořádat ji. Narozeniny nikdy nezmínit.","Výročí se oslaví řádně. Čtyři média zmíní shodu dat v devátém odstavci a nikdo nikdy nečte devátý odstavec."],["Přesunout přehlídku na jiný víkend.","Přesunout dvěstěpadesátileté výročí kvůli implikaci je samo implikací, a Boyd to poznamená, správně, ale příliš pozdě."],["Přesunout vlastní narozeniny.","Proklamace určí jiné oficiální datum. Podepíše se. Čtyři úřady si opraví záznamy a jeden pak posílá přání od té doby oba dny."]]},"e-pen-set":{"t":"Pera","x":"Alvin má tác. \"Dvaadvacet per na podpis, pane, a vy jste podepsal sto čtyřicet tři příkazů.\" Provede výpočet, aniž by ho o to kdo žádal. \"Tři tisíce sto čtyřicet šest per. Ty dobré nám došly, a rezerva je zásoba z roku 1974.\"","c":[["Objednat čtyřicet tisíc dalších. Zlatých. S mým podpisem.","Dorazí za jedenáct týdnů. Podpis je na všech čtyřiceti tisících mírně mimo střed, a nikdo se to neodváží zmínit."],["Použít zásobu z roku 1974. Někdo by měl.","Pero z úplně jiného prezidentství podepíše příkaz, který by jeho původního majitele ohromil. Alvina to baví víc než kohokoli jiného."],["Jedno pero na podpis. Nechat si je všechna.","Kompletní sada, v pořadí, v pouzdru, se stane nejcennějším předmětem, jaký kdy z téhle budovy kdo odnese."],["Podepisovat vším navždy stejným perem.","Dojde mu inkoust u příkazu číslo devadesát jedna, uprostřed podpisu, před kamerami. Příkaz zůstane technicky nedokončený čtyři hodiny, než si toho někdo všimne."]]},"e-nickname":{"t":"Jméno pro něj","x":"Brayden má na kartě čtyři možnosti. „V testech si vedou o jedenáct až devatenáct bodů lépe než jeho skutečné jméno, pane. Ta nejúspěšnější je zároveň nejkrutější, což není náhoda, a já už dávno přestal předstírat, že je.“","c":[["Tu nejkrutější. Používejte ji v každém příspěvku.","Přilne to tak dokonale, že o čtyři roky později musí seriózní deníky upřesňovat, kterého muže mají na mysli, když použijí jeho skutečné jméno."],["Tu nejmírnější. I tak to funguje.","Jedenáct bodů místo devatenácti, a žádný záznam, jak něco říkáte o mužově rodině. Správný obchod, pokaždé."],["Použijte jeho skutečné jméno. Útočte na jeho skutečný záznam.","Věcný útok na skutečné hlasování, které opravdu učinil. Je to nejzničující věc, kterou o něm kdokoliv za celý rok řekne, a získá to čtvrtinu mediálního pokrytí."],["Dejte mu místo toho lichotivou přezdívku.","Začnete mu říkat něco skutečně pochvalného a odmítáte vysvětlit proč. Čtyři měsíce je z toho viditelně vykolejený."]]},"e-doctor-note":{"t":"Dopis od lékaře","x":"Dr. Prine sepsal výroční lékařskou zprávu. Má čtyři odstavce a slovo „výjimečný“ v ní padne dvakrát. „Pane, tohle není dopis, který bych napsal já. Je to dopis, který mám podepsat, a rád bych věděl, která z těch dvou věcí se nakonec skutečně pošle ven.“","c":[["Ten, který dostal. Podepište ho.","Podpis lékaře pod superlativy někoho jiného. Čtyři lékařské asociace se vyjádří k etice celé věci a Prine si přečte všechny čtyři."],["Ten, který by napsal sám.","Píše se v něm, že jste muž svého věku v rozumné kondici se dvěma zvladatelnými zdravotními problémy. Naprosto nenápadné, a proto se o tom už nikdy nikdo nezmíní."],["Zveřejněte oba a nechte lidi ať si vyberou.","Radikální transparentnost jako vtip, který se ukáže jako skutečně účinná politika. Prine si dá dvoustránkové prohlášení do rámečku."],["Ať vás prohlásí za nejzdravějšího prezidenta v historii.","Odmítne, písemně, s odkazem na čtyři prezidenty, kteří běhali maratony. Odmítavý dopis se stane dokumentem jistého historického významu."]]},"e-intern-photo":{"t":"Fotografie","x":"Madison vyfotila chodbu a fotku zveřejnila, už teď má čtyři sta tisíc zhlédnutí. Nezobrazuje nic tajného. Ukazuje vás zezadu, jak jdete sám, v deset večer, a je to nejlidštější snímek, jaký o vás kdo za čtyři roky pořídil.","c":[["Zakažte veškeré fotografování personálu. Zabavte telefony.","Zákaz je titulkem na tři dny, fotografie titulkem na tři roky. Madison není propuštěna a už nic dalšího nezveřejní."],["Nechte ji tam. Ať klidně dál publikuje.","Zcela náhodou se stane nejúčinnějším komunikačním aktivem v celé budově. Nikdo z oddělení komunikace to nedokáže napodobit, ačkoliv se o to čtyři z nich pokusí."],["Ať fotí víc. Oficiálně. Podle zadání.","V okamžiku, kdy to dostane zadání, přestane to fungovat. Zapojení diváků klesne za čtrnáct dní o 80 procent a Madison to ke své cti řekne nahlas."],["Na oplátku zveřejněte fotku jí, zezadu.","Prezident fotí stážistku, jak fotí prezidenta. Je to opravdu půvabné a čtyři lidé z právního oddělení nad tím musí pořádně přemýšlet."]]},"e-usher-book":{"t":"Čtyřicet jedna let","x":"Alvin odchází do důchodu. Čtyřicet jedna let, sedm prezidentů. Nikdy nedal jediný rozhovor a tento měsíc mu nabídku poslali čtyři nakladatelé. Říká vám to jako zdvořilost, kterou po něm nikdo nežádal.","c":[["Ať mu právní oddělení pošle dohodu o mlčenlivosti.","Podepíše ji bez námitek a osobně ji vrátí. Čtyři ze sedmi prezidentů, kterým sloužil, mu do týdne zavolají, a ani jeden z nich nezavolá vám."],["Popřejte mu vše dobré. O knize se nezmiňujte.","Nikdy ji nenapíše. Příteli o mnoho let později řekne, že jediným důvodem bylo, že ho o to nikdo nikdy nepožádal."],["Udělte mu medaili. Ve Východním sále. Ať tam jsou všichni.","Čtyři sta lidí, včetně tří bývalých prezidentů, na nejvřelejší akci, jakou ta budova za deset let zažila, a nestojí vás to vůbec nic."],["Nabídněte se jako spoluautor.","Čtyři dny to vážně zvažuje, pak to odmítne jedinou větou, která je nějakým způsobem nesmírně laskavá i naprosto definitivní zároveň."]]},"t2-unleashed":{"t":"Zábrana, která zmizela","x":"Deborah má jednu stránku, ale nečte z ní. „Každá zábrana, která na vás fungovala v prvním funkčním období, pramenila z jedné jediné věci: znovu jste měl stát na hlasovacím lístku.“ Odloží stránku. „To už neplatí. Pane, nikdo v této budově si není úplně jistý, co se stane s prezidentem, když tohle zmizí, včetně lidí, kteří jsou placeni za to, aby to studovali.“","c":[["Pak přestaňte předstírat. Všechno, hned.","Čtyři roky pomalu odkládaných příkazů se podepíšou během čtrnácti dnů, a systém, po němž se chce spolknout tolik najednou, to prostě nezvládne."],["Stejný program. Rychleji. Bez porad.","Žádný projev, žádná doktrína, žádná tisková zpráva, jen vláda, která tiše přestala žádat o svolení a nikdy to neoznámila."],["Věnujte to věcem, které potřebují osm let.","Čtyři programy, příliš velké na jedno funkční období, se dokončí za dvě, což se nakonec ukáže jako jediný poctivý argument, který kdy kdo pro druhé období vznesl."],["Oznamte, že budete vládnout, jako by hlasovací lístek stále existoval.","Nikdo tomu nevěří, Deborah nejméně ze všech, ale vydrží to zhruba devět měsíců, o osm déle, než v budově kdokoliv sázel."]]},"t2-architecture":{"t":"Konstrukce","x":"Sy přinesl čtyřletý spis. „Začalo to jedním rozhodnutím o jednom trestním stíhání. Od té doby jsme ho citovali v téměř třetině našich naléhavých návrhů.“ Otočí ho k vám. „Pane, už to není štít. Čtyři roky podání na tom vystavěly konstrukci, a ta konstrukce je nosná.“","c":[["Stavte výš. Citujte to ve všem.","Rozhodnutí o jednom trestním stíhání se tiše mění v doktrínu o všem, jedno nenápadné podání za druhým."],["Přestaňte to citovat. Argumentujte věcně.","Vyhrajete méně a udržíte si víc. Čtyři z vítězství jsou nenapadnutelná způsobem, jaký nic postaveného na štítu nikdy nemělo."],["Citujte to jen tam, kde bychom jinak prohráli.","Vyhradit to pro skutečnou potřebu je to, k čemu štít vlastně slouží, a je to jediná verze, která přežije vaši vládu."],["Požádejte soud, ať konstrukci písemně potvrdí.","Případ přijmou. Nález je nakonec užší, než čtyři roky vlastních podání předpokládaly, a tiše zbourá zhruba polovinu konstrukce."]]},"t2-eighty-seven":{"t":"Osmdesát sedm slov","x":"„Vytiskl jsem to. Je to osmdesát sedm slov.“ Sy položí na stůl jediný list papíru. „Omezuje to být zvolen víc než dvakrát. Lidé vám pořád tvrdí, že existuje argument o tom být dosazen. Pane, ty argumenty jsem četl a styděl bych se je nahlas přednést v místnosti se soudcem.“","c":[["Ať právní oddělení stejně sepíše argument o dosazení.","Vznikne memorandum, pečlivé, důkladné a nepřesvědčivé. Za devět týdnů unikne na veřejnost a zastíní každou skutečnou politiku, kterou jste podepsal."],["Přečtěte to nahlas. Veřejně. Všech osmdesát sedm slov.","Trvá to třicet jedna vteřin. Je to nejúčinnější věc, kterou za celý rok uděláte, a vaše hnutí to prožívá jako ztrátu blízkého."],["Nevyjadřujte se k tomu ani tak, ani tak.","Nejednoznačnost nestojí nic a udržuje čtyři sta tisíc lidí v naději, což má mnohem větší cenu než kterákoliv odpověď."],["Dejte to zarámovat a pověste nad psací stůl.","Každý návštěvník si to vyfotí. Nikdo nedokáže zjistit, jestli je to slib, nebo výzva, a vy to opakovaně a s potěšením odmítáte objasnit."]]},"t2-term-reset":{"t":"Hodiny, které se vynulovaly","x":"Dr. Weirová má srovnávací případ a moc si ho neužívá. „Bylo to provedeno přesně podle knihy. Ústavní dodatek, skutečné hlasování a ustanovení, že se už odsloužená období nezapočítávají.“ Vzhlédne. „Pane prezidente, hodiny se nezastavily. Vrátily se na nulu. A nic z toho nebylo nezákonné.“","c":[["Připravte dodatek. Už odsloužená období se nezapočítávají.","Potřebuje třicet osm států a nikdy je nezíská. Ten pokus má pro vás větší cenu, než by kdy měl samotný dodatek, a všichni zúčastnění to vědí."],["Ať o to požádají čtyři zákonodárné sbory států. Vy do toho nezasahujte.","Nežádal jste o to vy. Požádali o to oni. Ten rozdíl je nosnou zdí celého podniku a vydrží zhruba dva roky."],["„To dělají jiné země.“ A tím to uzavřete.","Odmítnout cizí ústavu je nejlevnější dostupné vlastenectví, a tentokrát to dokonce myslíte doopravdy."],["Navrhněte to, ale ať se vynulování týká všech.","Všeobecná amnestie na omezení funkčních období pro každý úřad v zemi. Čtyři sta úřadujících politiků, kteří vás v soukromí nesnášejí, potají doufá, že to projde."]]},"t2-referendum":{"t":"Otázka na hlasovacím lístku","x":"Nadia to modelovala. „Jediná celostátní otázka: má být prezidentský úřad posílen. Ne kandidát, ne strana, jedna otázka.“ Zaváhá. „V průzkumech je na čtyřiceti osmi procentech a posune se o devět bodů, pokud v předchozích čtrnácti dnech došlo k nějakému incidentu. Pane, chci mít v záznamu, že bych si přála, abych to číslo nikdy nespočítala.“","c":[["Vypište otázku. Vyberte si těch čtrnáct dní.","Skutečná většina, ve skutečném hlasování, pro trvale posílený úřad. Je to nejdemokratičtější věc, kterou kdy uděláte, a zdaleka nejnebezpečnější."],["Vypište otázku. Vezměte, jaké datum přijde.","Neúspěch o čtyři body v obyčejné úterý. Čistá prohra se nakonec pro úřad ukáže cennější, než by kdy bylo špinavé vítězství."],["Žádné referendum. Ústava má vlastní proces pro dodatky.","Ten proces existuje, je záměrně obtížný a vy odmítnete ho obcházet. Nadia smaže model a řekne vám to."],["Vypište čtyři otázky a nechte lidi kombinovat.","Voliči schválí dvě, jednu zamítnou a u čtvrté se rozdělí rovným dílem, čímž vznikne ústavní uspořádání, které nikdo nenavrhl a žádný právník nedokáže rozklíčovat."]]},"t2-perpetuo":{"t":"Bez časového omezení","x":"„Ten úřad byl skutečný, byl legální a měl omezení, šest měsíců, a pak jste ho vrátil.“ Dr. Weirová popisuje muže mrtvého dva tisíce let. „On si úřad ponechal a omezení zrušil. Nic neuchvátil. Jen smazal datum expirace.“ Odmlčí se. „Pane prezidente, jeho vlastní senát ho zabil do měsíce, a každý jediný z nich pro něj předtím hlasoval.“","c":[["Pak si úřad ponechte a omezení zrušte.","Historická paralela se opakuje tak často, že přestává být varováním a stává se harmonogramem. Čtyři členové vlastní strany přestanou zvedat telefony."],["Zachovejte omezení. Uvnitř něj úřad zesilte.","Silnější úřad s datem konce je verze, která přežije, právě proto, že to datum konce je důvod, proč se proti němu nikomu nechce organizovat odpor."],["Zeptejte se jí, co udělal ten druhý.","Vypráví vám o jeho dědici, který vše okázale vrátil, ponechal si vše podstatné a zemřel v posteli v sedmdesáti pěti letech, spokojeně sám se sebou až do konce."],["Nastavte si omezení na šest měsíců a sledujte, kdo si toho všimne.","Zveřejní se prohlášení, kterým si stanovujete šestiměsíční funkční období. Nikdo nepozná, jestli je to vtip, takže se to tiše nechá vypršet, aniž by to kdo oplakal."]]},"t2-most-powerful":{"t":"„Na cestě stát se“","x":"Vážený historik veřejně prohlásil, že se chystáte stát nejmocnějším prezidentem v americké historii. Dr. Weirová přišla to zkomplikovat. „Řekl ‚chystáte se‘, pane prezidente. Je to predikce, je podmíněná, a ta podmínka spočívá výhradně v tom, co uděláte během příštích dvanácti měsíců.“","c":[["Splňte tu podmínku. Celou.","Ukáže se, že měl pravdu, a řekne to bez sebemenšího náznaku uspokojení. Ta věta se do čtyř let objeví na obálce devíti knih, a ani jedna z nich to nemyslí jako poklonu."],["Neustále tu větu citujte. Nedělejte nic, čím byste si ji zasloužil.","Predikce opakovaná dost často začne působit jako fakt, což přináší většinu výhod bez jakéhokoli ústavního rizika."],["Poukažte na to, že dva váleční prezidenti udělali víc.","Přesné, velkorysé a jediná nejodzbrojivější věta, kterou za celé období pronesete. Čtyři historici s vámi veřejně souhlasí, byť mírně stažení."],["Požádejte, ať vás formálně poměří vůči celému seznamu.","Zadá se sestavení žebříčku. Skončíte jedenáctý, což neuspokojí nikoho, a o metodologii se pak deset let vedou spory."]]},"t2-nixon":{"t":"Daleko za hranicí","x":"Kaylee má ten článek. „Srovnání není s vaším prvním obdobím. Je to s vládou, která razila výraz ‚imperiální prezidentství‘, a verdikt zní, že jste ho daleko překonal.“ Odloží ho. „Pane, ten prezident odstoupil, a autor moc dobře ví, že to víme taky.“","c":[["Přijměte to jako poklonu. Řekněte, že byl slabý.","Příznivé srovnávání se s mužem, který raději odstoupil, než aby byl odvolán, je věta, kterou čtyři historici umístí do prvního odstavce všeho, co o vás kdy napíší."],["„On porušil zákon. Já ne.“ A nechte to tak.","Obhajitelná věta, dokud někdo nepředloží seznam, a sestavovat seznamy je přesně to, čím se celý novinářský sbor živí."],["Nereagujte. Je to srovnání, ne obvinění.","Článek vydrží v oběhu jeden den. Jakákoliv odpověď, kterou byste dal, by ho udržela v oběhu celý týden."],["Pozvěte autora dovnitř a proveďte ho celou budovou.","Přijme, stráví v budově devět hodin a napíše něco podstatně nuancovanějšího a zhruba čtyřikrát zničujícějšího."]]},"t2-still-in-place":{"t":"Pořád na svém místě","x":"Dr. Weirová přinesla větu, která nejvíc dráždí vaše kritiky. „‚Mnoho klíčových prvků systému je stále na svém místě. Soudy proti němu rozhodují, a jeho vláda tato rozhodnutí občas respektuje.‘“ Vzhlédne. „Pane prezidente, tohle napsali lidé, kteří jsou znepokojeni. Je to nejsilnější věc, jakou kdo řekl na vaši obhajobu, a přitom to vůbec žádná obhajoba není.“","c":[["Pak zjistěte, které klíčové prvky nejsou nosné.","Jsou čtyři. Tři z nich vyzkoušíte za osmnáct měsíců a čtvrtý je ten, který vás nakonec zastaví, a nikdo netipoval, že to bude právě on."],["Neustále tu větu citujte jako ospravedlnění.","Citovat vlastní ústupek kritiků je nejstarší trik v politice, a funguje přesně na lidi, kteří si od začátku nedělali starosti."],["Nechte klíčové prvky na pokoji. Vezměte zavděk obdobím, které máte.","Vládnete tvrdě uvnitř systému, který se odmítáte pokusit rozbít. Je to nejméně uspokojivý výsledek ze všech na výběr, a jediný, který za padesát let ještě stojí."],["Požádejte ji, ať sepíše klíčové prvky, ať je máte.","Odmítne, rovnou, bez jakéhokoliv zmírnění. Je to teprve podruhé za pět let, co vám řekla ne, a ani jednou to nevysvětlila."]]},"t2-still-free":{"t":"Osmdesát jedna ze sta","x":"Muriel má skóre. „Osmdesát jedna ze sta, pokles z osmdesáti čtyř. O dvanáct bodů níž, než jsme byli před dvaceti lety.“ Otočí stránku. „Pane, pořád jsme v kategorii ‚svobodný‘. To je dobrá zpráva, a je to zároveň jediná zpráva, protože ta kategorie má dno a my se k němu blížíme naprosto měřitelnou rychlostí.“","c":[["Ignorujte trend. Zveřejněte kategorii.","„Stále svobodní“ je heslo dobré přesně na jeden tiskový cyklus. Číslo za příští rok dorazí podle plánu a heslo se tiše samo odloží."],["Opravte tři ukazatele, ve kterých jste nejhorší.","Nezávislost soudnictví, kapacita dohledu, přístup tisku. Trvá to čtrnáct měsíců, stojí vás to dvě politiky a vrátí to skóre o čtyři body zpět."],["Zpochybněte index a financujte konkurenční.","Váš index hodnotí zemi na devadesát čtyři. Schvalně ho citují čtyři vlády, u kterých byste raději nechtěl být citován, a doslova nikdo jiný."],["Zeptejte se, jaké skóre by nás posunulo do nižší kategorie.","Odpoví podrobně, protože metodologii zveřejňují jako dospělí. Číslo se napíše na kartičku a uloží do šuplíku, a o její existenci vědí čtyři lidé."]]},"t2-too-reductive":{"t":"„Příliš zjednodušující“","x":"Dr. Weirová přinesla odmítnutí. „Napsala knihu o silných vůdcích, řadí vás pevně do té linie, a přesto odmítá o vás použít slovo na F. Nazývá to označení příliš zjednodušující.“ Odloží to. „Pane prezidente, to není obhajoba. Říká tím, že by vás to slovo pustilo příliš lehce, protože by se lidé hádali o slovo místo o to, co jste skutečně udělal.“","c":[["Používejte to neustále. „I oni říkají, že nejsem.“","Funguje to přesně tak, jak předpověděla: devět měsíců hádek o slovník a žádné o záznam, což bylo přesně to nebezpečí, na které upozorňovala."],["Nereagujte. Nedotýkejte se toho.","Odmítnutí tam zůstane ležet, nikým nepřivlastněné, a tiše dělá přesně to, co zamýšlela. Citováno ve čtyřech stech článcích, a ani jednou jako osvobození."],["Pozvěte ji, ať to podrobně vysvětlí, oficiálně.","Devadesát minut jí zabere vysvětlit, jaké slovo by tedy sedělo. Je to nejzničující rozhovor vaší vlády, a vy jste ho osobně zadal."],["Zeptejte se jí, jaké slovo by tedy použila.","Dá vám tři, v rostoucím pořadí přesnosti. Všechna tři si pamatujete do konce života a žádné z nich nikdy nevyslovíte nahlas."]]},"t2-lawsuit-count":{"t":"Sedm set padesát tři","x":"Sy má přehled. „Sedm set padesát tři případů. Máme osmnáct odkladů od nejvyššího soudu a u nižších soudů zhruba stejně proher jako výher.“ Zavře ho. „Pane, poctivé shrnutí zní, že je to smíšené, což neprodává ani jedna strana a přesně to říká skutečný záznam.“","c":[["Tvrďte, že vyhráváme všechno. Nikdo to nepočítá.","Někdo to počítá. Přehled je veřejný, aktualizuje se týdně, a rozdíl mezi tvrzením a sloupečkem se stává vlastním opakujícím se příběhem."],["Zveřejněte vlastní bilanci výher a proher. Přesně.","Skutečně smíšená bilance, zveřejněná vámi samotným, celý argument zabije. Čtyři média to otisknou a ani jedno nenajde úhel pohledu."],["Přestaňte se odvolávat u případů, které stejně prohrajete.","Vést spory jen tam, kde lze vyhrát, zvyšuje úspěšnost a snižuje viditelnost, což zvenčí vypadá jako kompetentní právní tým."],["Podejte protižalobu na všech sedm set padesát tři.","Samotné soudní poplatky činí 190 000 dolarů. Čtyři z protižalob se náhodou ukážou být namířeny proti orgánům vlastní vlády."]]},"t2-shield":{"t":"Štít","x":"„Milosti v prvním funkčním období nikdy nebyly o minulosti.“ Sy je nezvykle přímý. „Každý, kdo teď zvažuje, že pro vás něco udělá, už dopředu ví, co se stane potom. Je to nejlevnější věrnostní program, jaký kdy kdo vymyslel, a pane, nemusel jste kvůli tomu říct jediné slovo.“","c":[["Řekněte to nahlas. Udělejte ten příslib výslovným.","Výslovný předběžný příslib milosti je z právního hlediska úplně jiné zvíře než pouhý vzorec chování, a čtyři žalobci to tak začnou brát ještě před obědem."],["Nemluvte o tom. Vzorec mluví sám za sebe.","Nevyřčené je to nenapadnutelné a stejně účinné. Devět lidí jedná na základě ujištění, které jim nikdo ve skutečnosti nikdy nedal."],["Veřejně prohlaste, že s tím nikdo nemá počítat.","Čtyři lidé, kteří se chystali udělat něco krajně nerozumného, to tiše přestanou dělat. Jejich jména ani to, o co šlo, se nikdy nedozvíte."],["Vydejte milosti předem, prázdné, bez data.","Nedatovaná milost pro nespecifikované budoucí trestné činy se do roka testuje u soudu a padne hned na první větě prvního nálezu."]]},"t2-old-hands":{"t":"Už se nikdo neptá","x":"Deborah si něčeho všimla a čtrnáct dní čekala, než to nadnese. „Tento měsíc se staly čtyři věci, které jste nenařídil. Nikdo se neptal, jestli jsou povolené. Staly se, protože si někdo dole vydedukoval, co byste chtěl.“ Zastaví se. „Pane, o tomhle jsou dějepisné knihy. Nejde o to, co uděláte vy. Jde o to, co dělají lidé, aniž by jim to kdy kdo řekl.“","c":[["Podporujte to. Pochvalte všechny čtyři jmenovitě.","Pochvala je přesně to potvrzení, na které čekalo dalších dvacet lidí. Funguje to líp než jakýkoliv příkaz a nedá se to jako příkaz zaevidovat."],["Nic neříkejte. Nechte to běžet.","Mlčení se čte jako souhlas a nestojí vás nic. Míra se v následujícím čtvrtletí zhruba zdvojnásobí, aniž by kdy byl vydán jediný příkaz."],["Řekněte celé budově otevřeně, že si tohle nikdo nevyžádal.","Dvě ze čtyř věcí se do týdne otočí zpět. Vyslovit to nahlas se ukáže jako jediná věc, která to kdy zastaví, a stojí vás to celý mechanismus."],["Zeptejte se, o které ze čtyř věcí si myslí, že jste ji chtěl nejméně.","Vrátí se memorandum řadící vaše domnělá přání podle míry jistoty. Je nepříjemně přesné a do hodiny je utajováno."]]},"t2-old-enemy":{"t":"Ta, která tam pořád je","x":"Cordelia Ruiz-Bloomová přežila čtyři samostatné pokusy ukončit její kariéru a požádala o schůzku. Přichází sama, posadí se a řekne: „Vaše vláda mě vyšetřuje šest let. Nikdy nebylo vzneseno žádné obvinění. Nejsem tu, abych si stěžovala, pane prezidente. Jsem tu, protože bych chtěla vědět, jestli to teď skončí, nebo jestli to bude pokračovat další čtyři roky.“","c":[["„Pokračuje to.“ Řekněte jí to do očí.","V autě si to zapíše, opatří datem a dá kopie třem lidem. Je to citováno v jejích pamětech, na slyšení a nakonec i v soudním nálezu."],["„Končí to.“ Uzavřete všechny spisy ještě to odpoledne.","Devět měsíců vám nevěří. Když nakonec uvěří, řekne to veřejně a bez vyzvání, a má to větší cenu, než jaký byste kdy koupil reklamní prostor."],["Neříkejte vůbec nic. Ať odejde v nejistotě.","Nejistota je levnější než kterákoliv odpověď a odvádí většinu práce té horší z nich, což je přesně důvod, proč si tuto možnost vyberete."],["Nabídněte jí práci.","Odmítne čtyřmi slovy, a pak z důvodů, které si ani jeden z vás nedokáže vysvětlit, zůstane ještě hodinu a povídá o svém otci."]]},"t2-heir":{"t":"Jméno na druhé kartě","x":"Chet má dvě kartičky. „Tohle je hnutí bez vás: padesát jedna. Tohle jsem já, jak ho vedu: třicet tři.“ Položí je vedle sebe. „Pane, ten rozdíl není problém osobnosti. Osmnáct bodů toho hnutí je jediný člověk, a člověka nelze nikomu předat. Přestal jsem předstírat opak.“","c":[["Pak to nezdědí nikdo. Skončí to se mnou.","Hnutí, které vás nemůže přežít, se také nemůže obejít bez vás, a obojí se stane pravdou téhož dne, dne, který si nemůžete naplánovat."],["Podpořte Cheta hned a dva roky pro něj veďte kampaň.","Za dvaadvacet měsíců stáhne osm z osmnácti bodů. Je to nejtěžší politická práce, jakou kdo ve vaší vládě dělá, a většinu z ní odvedete vy osobně."],["Vybudujte místo toho aparát. Pravidla, pokladnu, nástupnictví.","Instituce místo dědice. Vyhraje tři z příštích pěti voleb a přestane zmiňovat vaše jméno někde kolem druhých z nich."],["Podpořte čtyři lidi zároveň.","Všichni čtyři jedenáct měsíců v kuse vedou kampaň jako pomazaný nástupce a citují přitom stejnou větu. Následné primárky jsou nejzábavnější za celé století."]]},"t2-final-court":{"t":"Poslední jmenování","x":"Předsedkyně Nejvyššího soudu Stoneová přišla kvůli uvolněnému místu, ale zůstane kvůli něčemu jinému. „Jmenoval jste pětinu federálního soudnictva. Průměrný věk čtyřicet šest let.“ Nijak to nezjemňuje. „Pane prezidente, každý výkonný příkaz, který jste podepsal, lze odvolat za jedno odpoledne. Tohle se nedá odvolat vůbec. Tohle je prezidentský úřad. Všechno ostatní je počasí.“","c":[["Jmenujte nejmladší kvalifikované jméno na seznamu.","Devětatřicet let, potvrzeno dvěma hlasy navíc, a u soudu zhruba do roku 2065. Nic jiného, co jste udělal, do té doby nebude ještě v provozu."],["Jmenujte nejlepšího právníka na seznamu, ať je to kdokoliv.","V prvním roce proti vám rozhodne dvakrát a schvalně je citována ještě čtyři desetiletí poté. Stoneová vám jednou, potichu, řekne, že to bylo správné rozhodnutí."],["Nechte místo prázdné. Ať ho obsadí příští prezident.","Dobrovolně ponechané volné místo je neslýchané, téměř všichni to čtou jako slabost, a čtyři lidé to čtou jako jediný nejvíce ústavní čin za celé vaše období."],["Jmenujte sám sebe.","Text ústavy to technicky nezakazuje, což čtyři komentátoři poznamenávají s narůstajícím znepokojením, dokud se nominace tiše nestáhne."]]},"t2-net-worth":{"t":"Zhruba dvojnásobek","x":"Miriam má osmileté srovnání a rozložila ho na stůl. „Zhruba se to zdvojnásobilo, pane, a pak to ještě stouplo. Všechno přiznané. Všechno na formulářích, které jste osobně podepsal.“ Narovná stránky. „To je obhajoba, a je to skutečná obhajoba, a je to zároveň přesně způsob, jak se to všichni dozvěděli.“","c":[["Řekněte, že úřad s tím neměl nic společného.","Jedna jediná největší položka je token, který před vaší inaugurací vůbec neexistoval. Čtyři novináři to zjistí ještě před obědem a jeden z nich s sebou přinese graf."],["„Trh šel nahoru. Vydělali všichni.“","Postavena vedle skutečného čísla se ta věta stává nejcitovanější z celých vašich osmi let v úřadu. Myslel jste to naprosto upřímně, a právě to zabolí nejvíc."],["Zveřejněte celé osmileté srovnání sám.","Dvě hodiny otázek, všechny zodpovězené, jednou provždy. Je to nejhorší odpoledne vašeho druhého období, a téhož odpoledne to celý příběh ukončí."],["Vložte celý nárůst do nadace vaší knihovny.","Největší charitativní převod v americké politické historii, a míří k subjektu, který osobně ovládáte, detail, který čtyři novináři odhalí do hodiny."]]},"t2-quiet-year":{"t":"Rok, kdy se nic nestalo","x":"Nadia má zvláštní zjištění. „Jedenáct měsíců nebyla žádná krize. Žádné nasazení, žádný příkaz, kvůli kterému by někdo zažaloval, žádná pohotovost.“ Zamračí se nad vlastním listem. „Podpora stoupla o devět bodů, pane. A slovo, které lidé v ohniskových skupinách pořád používají, je, že to zase působí normálně, což je poprvé za osm let tohoto výzkumu, co se to slovo vůbec objevilo.“","c":[["Ukončete klid. Devět bodů není cíl.","Trvá to čtyři dny prohýřit jedenáct měsíců nashromážděné přízně. Nadia si ten list schová a ukazuje ho lidem po zbytek kariéry."],["Zachovejte klid. Vládněte. Nepodepisujte nic dramatického.","Klidný, kompetentní, naprosto nenápadný rok. Je to nejlépe hodnocené období obou vašich funkčních období, a vaše hnutí to přesně nazve zradou."],["Zachovejte klid navenek. V soukromí pokračujte dál.","Nic se neoznamuje, všechno pokračuje. Je to nejúčinnější čtvrtletí vaší vlády, a není o něm vůbec co napsat."],["Vyhlaste stav nouze kvůli absenci stavu nouze.","Prohlášení cituje samotnou jedenáctiměsíční mezeru jako důkaz nebezpečné sebespokojenosti. Zveřejní se, a Nadiina křivka podpory klesne za čtrnáct dní o devět bodů."]]},"t2-first-draft":{"t":"První seriózní dějiny","x":"Dr. Weirová přinesla vlastní rukopis, aniž by ji o to kdo žádal. „Osm let. Mám závěr a nebudu vám ho zjemňovat.“ Podá vám ho. „Nejrozsáhlejší uplatnění jednostranné výkonné moci v moderní mírové době, opravdu znepokojivé, rozkládající kvalitu demokracie, a přitom stále fungující uvnitř systému, který ho krotil. Všechny čtyři výroky, pane prezidente. Ne tři.“","c":[["Ať právní oddělení zjistí, jestli se to dá zastavit.","Nedá. Ten pokus se objeví ve druhém vydání jako čtyřstránková příloha a stane se jedinou nejcitovanější pasáží celé knihy."],["Napište předmluvu, ve které zpochybníte čtvrtý výrok.","Tvrdit v tisku, že vás systém ve skutečnosti nekrotil, je přesně ten výrok, kterého jste se měl vůbec nedotýkat, a to řekne každý recenzent."],["Napište předmluvu. Uznejte čtvrtý výrok.","Prezident, který v tisku přiznává, že brzdy fungovaly. Je to jediný nejcennější odstavec, jaký o vás kdy byl napsán, a napsal jste ho vy sám."],["Požádejte, ať poslední kapitolu napíšete vy sám.","Souhlasí, s podmínkou, že poběží needitovaná a jasně přiřazená vám. Má čtyři stránky a je s velkým odstupem nejhůře hodnocenou pasáží knihy."]]},"t2-last-day":{"t":"Poslední ráno","x":"Alvin má rozvrh na ráno a je to jedna stránka. „Káva v sedm. Auto v jedenáct. Druhá rodina přijíždí v jedenáct patnáct.“ Je naprosto klidný, dělal to už sedmkrát. „Pane, připravil jsem všechno, co jste žádal. Přejete si ještě něco jiného?“","c":[["„Zrušte tu jedenáct patnáct.“","Alvin řekne „Ano, pane“ a nehne se z místa. Po chvíli to zopakuje, pořád se nehne, a takhle přesně zjistíte, kde ta hranice byla."],["„Nic. Děkuji, Alvine.“","Odjedete v jedenáct. Je to jediná naprosto obyčejná věc za celé desetiletí, a je to důvod, proč tu ještě zůstala země, ve které lze být obyčejný."],["Nechte v psacím stole dopis pro toho, kdo přijde po vás.","Čtyři odstavce, ručně psané, zcela bez zlomyslnosti. Nikdy nezveřejněný. Příjemce se o něm jednou, o dvacet let později, zmíní a odmítne říct víc."],["Zeptejte se ho, kdo ze sedmi to zvládl nejlíp.","Dlouhou chvíli o tom vážně přemýšlí, pak odpoví upřímně. Nejste to vy. Řekne to laskavě, a vy víte, že je lepší nežádat ho o vysvětlení."]]},"f-entry-ban":{"t":"Seznam","x":"Duane má připravený příkaz zakazující vstup ze šesti jmenovaných zemí, účinný okamžikem podpisu. Žádné oznámení leteckým společnostem, žádné letištím. „Pane, jsou lidé, kteří právě teď letí nad Atlantikem a ještě neví, že jim byl zakázán vstup.“","c":[["Podepište to. Účinné dřív, než uschne inkoust.","Čtyři tisíce lidí stráví noc na podlaze terminálů, včetně tlumočníka, který krvácel za vaši vlastní armádu v cizí poušti. Právníci dorazí do hodiny s rozpálenými tiskárnami. Do devíti dnů je to soudně pozastaveno."],["Podepište to s třicetidenní lhůtou na implementaci.","Stejná politika, žádné fotografie. Přezkum přežije, protože nikdo nestihl vyfotit batole spící na pásu na zavazadla."],["Přepracujte to podle skutečných bezpečnostních hodnocení.","Zpravodajská komunita vrátí seznam dvou zemí. Obhajitelné, účinné, a k skandování naprosto nepoužitelné."],["Zakažte vstup z jedné země, kterou nikdo nenajde na mapě.","Populace jedenáct tisíc, žádné přímé lety. Čtyři televizní diskuze se o tom hádají celý týden a jejich velvyslanec se na krátkou chvíli stane nejslavnějším žijícím mužem."]]},"f-separation":{"t":"Politika","x":"„Trestní stíhání každého dospělého, kdo přejde hranici, znamená, že děti s nimi nemohou zůstat. To není vedlejší účinek té politiky, pane. To je ta politika. Musím to říct nahlas přesně jednou.“","c":[["Udělejte to. Odstrašující účinek funguje, jen když se o tom všichni doslechnou.","Dva tisíce osm set dětí. Nikdo nevybudoval sledovací systém, protože nikdo neplánoval je vracet. Čtyři sta jich v roce 2031 stále nebylo spárováno s rodiči."],["Stíhejte dospělé. Rodiny nechte ve vazbě pohromadě.","Vyžaduje to rodinná zařízení, která ještě neexistují, takže se to potichu změní ve stavební projekt. Pomalejší, dražší, a o sádrokartonu nikdo nenatočí dokument."],["Zabijte to, ještě než to začne.","Bo zavře složku s viditelnou úlevou. Je to jediný okamžik za čtyři roky, kdy ho vidíte to udělat."],["Oznamte to, a pak trvejte na tom, že jste to nikdy neoznámil.","Memorandum nese vaše iniciály. Před kamerou to popíšete jako zákon, který schválila opozice. Obě verze koluji čtyři roky, ani jedna nezvítězí."]]},"f-countries":{"t":"Soukromá poznámka","x":"Na uzavřeném jednání jste popsal několik národů výrazy, které Deborah odmítá zopakovat, a nikoliv řečnicky se zeptal, proč nepřichází víc lidí odněkud, kde je chladněji. Dva z jedenácti přítomných už stihli zavolat novináři.","c":[["Popřete to slovo. Ne ten postoj.","Popření dostatečně přesné, aby bylo technicky pravdivé, a dostatečně vágní, aby bylo bezcenné. Jedenáct velvyslanců žádá vysvětlení a dostane čtyři různé odpovědi, z nichž se ani jedna neshoduje."],["Přiznejte se. „Řekl jsem to a myslel jsem to vážně.“","Čtyři africké státy stáhnou své velvyslance na konzultace. Vaše podpora u vlastních voličů stoupne o dva body, což byl vždycky ten skutečný ukazatel."],["Omluvte se. Jmenovitě. Daným zemím.","Konkrétní omluva, bez vytáček, bez „pokud se někdo cítil dotčen“. Je to tak neslýchané, že to vede zprávy v devíti zemích, a vaše základna se na tu nahrávku dívá jako na video s rukojmím."],["Tvrďte, že jste rozebíral průměrné zimní teploty.","Bílý dům skutečně vydá klimatickou tabulku. Je to nejsurreálnější dokument celé vlády a nepřesvědčí to vůbec nikoho."]]},"f-director":{"t":"Ředitel","x":"Ředitel úřadu, který vede vyšetřování týkající se vás, zastává desetileté funkční období přesně proto, aby žádný prezident nemohl udělat to, co se chystáte udělat. Deborah: „Můžete ho odvolat. Nic vám v tom nebrání. Existuje jen to, co potom řeknete, a v tom jste špatný.“","c":[["Vyhoďte ho. Pak to vysvětlete v televizi.","V rozhovoru uvedete skutečný důvod, protože se prostě fyzicky nedokážete zastavit. O osm dní později je jmenován zvláštní žalobce a ten rozhovor je důkaz číslo jedna."],["Vyhoďte ho a držte se oficiální záminky.","Záminka vydrží jedenáct týdnů. Jeho dobové poznámky vydrží podstatně déle, ostatně je začal psát v noci po vaší první společné večeři."],["Nechte ho tam. Ať vyšetřování doběhne.","Skončí za devatenáct měsíců bez obvinění proti vám. Nikdo si to nepamatuje, protože se nic nestalo, což byl celý smysl toho ho nechat doběhnout."],["Povyšte ho někam, kde není telefon.","Ředitel federálních zařízení, antarktický program. Přijme to, slouží jedenáct měsíců a vydá překvapivě dobře hodnocené paměti o tučňácích a institucionální integritě."]]},"f-witch-hunt":{"t":"Vyšetřování","x":"Byl jmenován zvláštní žalobce. Sy podotýká, že nejrychlejší způsob, jak vyšetřování přežít právně, je neříkat nic, a nejrychlejší způsob, jak ho přežít politicky, je říkat něco, zhruba devět set krát.","c":[["Útočte na to denně. Stejná dvě slova. Devět set krát.","Než zpráva vyjde, 44 procent země už rozhodlo, že je nelegitimní. Zpráva má 448 stránek. Ta dvě slova zůstávají dvěma slovy."],["Spolupracujte naplno a veřejně mlčte.","Skončí to potichu, zjištění jsou smíšená a nikdo je nečte. Mlčení je jediná nejúčinnější právní strategie, jaká existuje, a zároveň jediná nejnesnesitelnější politická."],["Spolupracujte, ale dva roky se soudně přete o každé předvolání.","Nikdy nic výslovně neodmítnete. Prostě nikdy nic nedokončíte, a kalendář za vás udělá to, co by jinak udělalo odmítnutí."],["Najměte žalobce jako konzultanta. Zjistěte, jestli je to povolené.","Není. Čtyři etické komise to do jednoho dne písemně potvrdí, a samotný pokus je postoupen dál, čímž se stane devátým bodem obžaloby v něčem jiném."]]},"f-the-call":{"t":"Laskavost","x":"Jste na telefonu s prezidentem země, která potřebuje balík pomoci ležící na vašem stole. Muriel poslouchá. Právě jste použil frázi „i když bych chtěl, abyste nám udělal laskavost“.","c":[["Požádejte o vyšetřování. Jmenovitě.","Na lince je jedenáct lidí. Jeden z nich podá téhož odpoledne stížnost řádnou cestou. Vše, co se stane v následujících čtrnácti měsících, se stane kvůli tomuto jednomu člověku."],["Naznačte to. Jméno nikdy nevyslovte.","Náznak nezanechá žádný problém v přepisu a má naprosto stejný účinek na vládu, která potřebuje 400 milionů dolarů. Tohle je verze, která funguje."],["Uvolněte pomoc. Nežádejte nic.","Pomoc odejde podle plánu, použije se, a lidé, kteří by jinak zemřeli, nezemřou. Není v tom vůbec žádný příběh, což je svým způsobem zázrak."],["Požádejte ho, ať vyšetří někoho, kdo neexistuje.","Jeho žalobci stráví čtyři měsíce honbou za mužem bez rodného listu. Výsledná zpráva, podaná v ukrajinštině, se potichu řadí mezi nejzábavnější dokumenty v dějinách diplomacie."]]},"f-impeach-one":{"t":"Článek obžaloby","x":"Sněmovna reprezentantů odhlasovala. Hal má senátní aritmetiku: potřebujete 34 z 53, abyste to ustál, a máte 53 z 53, protože každý z nich se podíval na vlastní primárkový elektorát a spočítal si stejný příklad.","c":[["Prosaďte stranicky jednotné zproštění viny. Toho, kdo vybočí, udělejte příkladem.","Jeden senátor hlasuje pro odsouzení. Vlastní stranická organizace v jeho státě ho do týdne pokárá a on se už nebude o znovuzvolení ucházet. Všichni ostatní teď viděli ceník."],["Postavte skutečnou obhajobu na faktech.","Vaši právníci jsou dobří a případ proti vám je opravdu napadnutelný. Jste zproštěn viny na základě argumentace, ne aritmetiky, což má mnohem větší cenu, a nikdo ten rozdíl nepozná."],["Odmítněte se zúčastnit. Prohlaste to celé za neplatné.","Stejně jste zproštěn viny. Odmítnutí obhajoby dokazuje, že jste ji nikdy nepotřeboval, což je fakt spíš o Senátu než o vás."],["Přijďte osobně a posaďte se na galerii.","Žádný prezident nikdy naživo nesledoval z místnosti vlastní impeachmentní proces. Čtyři senátoři se nedokážou přinutit vzhlédnout. Funguje to naprosto výborně a zůstává to hluboce zvláštní."]]},"f-find-votes":{"t":"Číslo","x":"Na telefonu je státní úředník z vaší vlastní strany. Sy je v místnosti a přestal psát. Chystáte se pojmenovat konkrétní počet hlasů a požádat ho, ať je najde.","c":[["Pojmenujte to číslo. Požádejte ho, ať ho najde.","Ten hovor nahraje, protože mu právníci řekli, ať nahrává úplně všechny hovory. Za čtyři dny běží celý, jedenáct minut, na všech stanicích."],["Požádejte ho, ať se „podívá znovu“. Nic nejmenujte.","Podívá se znovu. Najde stejný výsledek. Neexistuje žádná nahrávka, která by cokoliv znamenala, což se ukáže jako jediný skutečný rozdíl oproti té druhé verzi."],["Poblahopřejte mu k čistému sečtení hlasů.","Je tak zaskočený, že poděkuje dvakrát. Vaše základna, jakmile hovor unikne na veřejnost, ho považuje za jedinou největší zradu celé vlády."],["Požádejte ho, ať najde jeden hlas. Jen jeden. Jako gesto.","Trpělivě vám vysvětlí, že jeden podvodný hlas je přesně stejně nezákonný jako čtyři tisíce. Řeknete, že rozumíte. Ani jeden z vás tomu druhému nevěří."]]},"f-certify":{"t":"Certifikace","x":"Chet předsedá sčítání hlasů. Jeho role je podle každého serózního výkladu ceremoniální. Dostal do rukou čtyři memoranda tvrdící opak, a drží všechna čtyři, a nepoložil je.","c":[["Řekněte mu, ať zamítne listiny volitelů. Veřejně, aby to nemohl tiše odmítnout.","Neudělá to. Řekne to v dvoustránkovém dopise zveřejněném minuty před zasedáním, jediném nejzávažnějším dokumentu celé vaší vlády, a vy jste nenapsal ani slovo z něj."],["Zeptejte se ho soukromě. Přijměte, ať odpoví cokoliv.","Odmítne, jemně. Nikdy se to nedostane na veřejnost. Zbylých čtrnáct dní se k sobě chováte zdvořile a pak už spolu nikdy nepromluvíte."],["Řekněte mu, že je to ceremoniální, ať to prostě odbaví.","Sčítání proběhne za čtyři hodiny. Nic se nestane. Je to nejnudnější odpoledne v historii budovy, a se zpětným pohledem celá podstata věci."],["Předsedejte tomu sám. Můžete to vůbec udělat?","Nemůžete. Čtyři různé úřady vysvětlí proč. Požádáte každý z nich, ať to ověří znovu, a každý to udělá, a odpověď se odmítá změnit."]]},"f-hostages":{"t":"Slovo pro ně","x":"Brayden chce, abyste lidem odsouzeným za dobytí budovy říkal „zadržení“. Ne „obžalovaní“. Ne „odsouzenci“. Otestoval to na ohniskových skupinách a číslo se posunulo o jedenáct bodů.","c":[["Používejte to. V každém projevu. Otevírejte tím každé shromáždění.","Do roka to slovo používá třetina země, aniž by si všimla, že ho přijala. Jazyk je nejlevnější infrastruktura, jaká existuje, a vy jste ho právě vylil kilometry."],["Používejte to jen pro ty nenásilné.","Rozlišení, které je skutečně obhajitelné a které se nikomu, na žádné straně, po čtvrtém týdnu nechce dodržovat."],["Nazývejte je tak, jak je nazvala porota.","Čtyři slova. Vaše základna to prožívá jako zradu, a Brayden si toho večera aktualizuje životopis."],["Vymyslete slovo, které neznamená vůbec nic.","„Odročení.“ Bezvýznamné, nevyvratitelné, nelze s tím polemizovat. Dva deníky to přejmou v uvozovkách, a do třetího roku bez nich."]]},"f-it-will-go":{"t":"Křivka","x":"Dr. Pike má model, a není to zdaleka příznivé. „Pane, počet případů se každých šest dní zdvojnásobuje. Neexistuje žádná verze příštích osmi týdnů, kde by to zůstalo malé.“","c":[["„Zmizí to. Jako zázrakem.“","Nezmizí to. Tu větu vám dva roky přehrávají zpět, s běžícím počtem obětí na obrazovce. Pike je od března pryč z pódia."],["Řekněte zemi pravdu a přijměte důsledky.","Podpora klesne za čtrnáct dní o devět bodů a za šest týdnů se zotaví výš, než byla předtím, protože jste měl pravdu a každý si to mohl ověřit."],["Řekněte, že je to vážné, a pak na každém briefingu Pikea podrážejte.","Dvě zprávy z jednoho pódia, denně, celý rok. Dodržování opatření se do jedenácti dnů rozdělí podle stranické příslušnosti a už se nikdy nesejde."],["Dejte model na obří graf a živě se s ním přete.","Čtyřicet minut, kdy se prezident hádá s exponenciální křivkou na stojanu. Křivka vyhraje. Skončí na obálce čtyř učebnic."]]},"f-the-cure":{"t":"Lék","x":"O léku se slibnými historkami a nulovými daty ze studií se vám zmínili tři lidé, ani jeden z nich lékař. Admirál Prine: „Možná to funguje. Nevíme to. To je celá věta, kterou dokážu obhájit.“","c":[["Propagujte to z pódia. Opakovaně.","Zásoby zmizí do devíti dnů, včetně u lidí, kteří to berou na úplně jinou nemoc. Studie po čtyřech měsících oznámí, že to nefunguje."],["Financujte rychlou, obrovskou, řádně vedenou studii.","Za čtyři měsíce přinese jednoznačnou odpověď, a ta zní ne. Znát odpověď se ukáže cennější, než samotná odpověď."],["Zmiňte to jednou, s výhradou, a jděte dál.","Výhrada z pódia žádná výhrada není. Prodeje stoupnou o 400 procent kvůli jediné podmiňovací větě."],["Berte to sám, denně, před kamerou.","Prine odmítne to předepsat a je obejit lékařem, jehož jméno nikdo nezná. Vám nic není. Čtyři sta tisíc lidí vás napodobí, a měřitelný počet z nich na tom není dobře."]]},"f-testing":{"t":"Číslo testování","x":"Počet případů je funkcí testování. Pike to vysvětluje dvakrát. Nahlas jste poznamenal, že kdyby se testovalo méně, bylo by méně případů.","c":[["Řekněte to na shromáždění. Technicky je to pravda.","Je to technicky pravda stejným způsobem, jako je technicky dieta nevážit se. Ten záznam koluje čtyři roky a Pikea se na to ptají na každém slyšení od té doby."],["Zdvojnásobte kapacitu testování a zveřejněte vše.","Zdá se, že počty prudce stoupají, protože je konečně počítáte. Vysvětlíte to jasně, čtyřikrát, a zhruba polovina země to pochopí."],["Pokračujte v testování. Změňte, jak se případy vykazují.","Definice případu se pozmění v technickém věstníku. Číslo klesne přes noc o 22 procent, aniž by byl zrušen jediný test."],["Testujte jen lidi, u kterých je jisté, že budou v pořádku.","Někdo skutečně sepíše kritéria, než čtyři různí úředníci pochopí, o co je žádáno, a jeden po druhém to odmítnou."]]},"f-accord":{"t":"Dohoda","x":"Muriel má připravený nástroj k odstoupení. „Nezávazné cíle, žádné vymáhání, žádná sankce za jejich nesplnění. Odstoupení nás nestojí právně vůbec nic a diplomaticky úplně všechno, což je neobvyklý poměr.“","c":[["Odstupte. Oznamte to v Růžové zahradě.","Přidáte se ke dvěma dalším zemím mimo dohodu. Jedenáct amerických států oznámí, že cíle stejně splní, což je buď federalismus, nebo pohlavek, podle toho, koho se zeptáte."],["Zůstaňte v dohodě a prostě cíle nesplňte.","Žádný odchod, žádný titulek, žádné plnění. Je to nejcyničtější možnost na stole, a čtyři další signatáři to už tiše dělají."],["Zůstaňte a vyjednejte cíle níž.","Dostanete horší dohodu s vaším jménem pod ní, což je lepší než lepší dohoda s jménem někoho jiného."],["Odstupte, a příští týden podejte žádost o opětovný vstup.","Znovupřijetí trvá podle smlouvy 30 dní. Po 23 z nich jsou Spojené státy formálně mimo dohodu, o jejíž opětovný vstup už požádaly."]]},"f-rollback":{"t":"Devadesát osm pravidel","x":"Cassandra Doyleová má seznam devadesáti osmi pravidel zralých ke zrušení. „Každé samo o sobě je technická novela, o které nikdo nenapíše. Dohromady je to největší zvrat v ochraně životního prostředí za padesát let.“","c":[["Všech devadesát osm. Jedno týdně, potichu.","Devadesát osm oznámení ve Federálním registru za dva roky. O čtyřech se napíše. Kumulativní efekt je viditelný z orbity a ani jednou se nedostane na titulní stranu."],["Těch devět, která skutečně stojí pracovní místa. Ty hlasitě obhajujte.","Obhajitelná, argumentovatelná pozice, kterou můžete vyhrát v televizi, což je devět desetin hodnoty, jakou kdy jakákoliv pozice má."],["Ponechte je. Místo toho financujte přechod.","Jedenáct tisíc rekvalifikačních míst napříč čtyřmi státy, které jste vyhrál. Funguje to, pomalu, a zásluhy sklidí váš nástupce."],["Zrušte jedno pravidlo devadesát osm krát.","Administrativní pokyn opravdové krásy. Stejné nařízení je zrušeno, obnoveno a znovu zrušeno, dokud se soudce písemně nezeptá, co přesně se to děje."]]},"f-aid-agency":{"t":"Agentura pro pomoc","x":"Vandermeer chce agenturu pro zahraniční pomoc zrušenou do pátku. Deset tisíc zaměstnanců, sto třicet zemí, a platební systém, který udržuje čtyři miliony lidí na antiretrovirové léčbě.","c":[["Zrušte to do pátku. Přeživší začleňte do ministerstva zahraničí.","Platební systém se zastaví v úterý. Kliniky to zjistí, až peníze nedorazí. Soud za pět týdnů nařídí obnovení, ale to už jsou dodavatelské řetězce rozprodané."],["Snižte to o polovinu během osmnácti měsíců.","Polovina agentury, kompetentně utlumená, lékový program vyčleněný a chráněný. Nikdo nezemře a nikdo si toho nevšimne."],["Zachovejte ji. Je to čtyři desetiny procenta rozpočtu.","To procento citujete na shromáždění. Je to jediný nejúčinnější fakt vaší vlády, a nikoho v sále nepřesvědčí."],["Přejmenujte ji. Stejní zaměstnanci, stejný rozpočet, nová cedule.","Úřad americké velkorysosti. Stojí to 9 milionů dolarů na hlavičkových papírech a Vandermeer na livestreamu vyhlašuje totální vítězství."]]},"f-rehire":{"t":"Příkaz k opětovnému přijetí","x":"Soudce nařídil vrátit zpět do práce šestnáct tisíc propuštěných zaměstnanců ve zkušební době, s doplatkem mzdy. Bo: „Ten příkaz je jasný. Otázka, kterou se mě chystáte zeptat, zní, jak pomalu ho můžeme splnit.“","c":[["Vraťte je zpět, pak je všechny pošlete na administrativní volno.","Plné splnění na papíře. Šestnáct tisíc lidí, zaměstnaných, placených, a s pokynem nechodit do práce. Soudce zuří a nedokáže identifikovat jediné porušení."],["Splňte to řádně. Vraťte je zpět k jejich stolům.","Vrátí se. Čtyři z nich se ukážou být jediní žijící lidé, kteří rozumí systému dávek napsanému v roce 1974."],["Odvolejte se, a během odvolání je znovu propusťte, tentokrát správně.","Druhé propuštění dodrží do písmene každé procesní pravidlo. Je nenapadnutelné. Právě jste zjistil, že proces nikdy nebyl tou překážkou."],["Vraťte je zpět, ale do jediné kanceláře ve Wyomingu.","Šestnáct tisíc federálních zaměstnanců formálně přiřazených do budovy se čtyřmi sty stoly. Oznámení o přesunu je do jednoho dne napadeno u soudu."]]},"f-independent":{"t":"Nezávislé úřady","x":"„Jedenáct úřadů bylo vytvořeno tak, aby prezident nemohl odvolávat jejich úředníky podle libosti. Chrání je precedent z roku 1935.“ Sy pokrčí rameny. „Byl čtyřikrát zúžen. Nikdy nebyl zrušen.“","c":[["Odvolejte jednoho z každého. Vynuťte si rozhodnutí.","Naléhavý rozhodovací kalendář nechá odvolání v platnosti do přezkumu, bez podpisu, v jedenáct večer. Precedent z roku 1935 nikdy není zrušen. Prostě od té noci přestává platit."],["Odvolejte toho jednoho, u kterého existuje skutečný důvod v podobě výkonu.","Obhajitelné odvolání na doložených základech. Zavádí to pravomoc, aniž by ji kdy skutečně otestovalo, což je verze, která přežije."],["Nechte je být. Nezávislost je důvod, proč fungují.","Čtyři z nich později rozhodnou proti vaší vládě, a dvě z těch rozhodnutí vás zachrání před podstatně horším výsledkem."],["Jmenujte sám sebe do všech jedenácti rad.","U devíti z nich nesplňujete podmínky, a u zbylých dvou je potřeba senátní potvrzení prezidenta senátem, přičemž nikdo neví, jak to vůbec naplánovat."]]},"f-emergency-docket":{"t":"Noční rozhodovací kalendář","x":"„Dvacet devět naléhavých návrhů za toto období. Historicky vláda podá osm za osm let.“ Bo odloží soupis. „Vyhráli jsme dvacet tři. Ani jeden neměl ústní jednání. Ani jeden nevysvětluje proč.“","c":[["Odteď podávejte všechno tímto způsobem. Nikdy nežádejte věcné projednání.","Přesunul jste americké ústavní právo do kalendáře bez jednání, bez odůvodnění a bez poražených, kteří by dostali vysvětlení. Je to čistě procesní, a je to celá hra."],["Ty velké případy postavte na řádné argumentaci. Vyhrávejte správně.","Prohrajete dva a vyhrajete tři, s písemnými nálezy, které zavazují vaše nástupce. Ta vítězství mají čtyřikrát vyšší cenu než nepodepsaný příkaz."],["Podávejte méně. Vybírejte lépe.","Devět návrhů, osm vyhověno. Pověst, že podáváte jen, když máte pravdu, je lepší než pověst, že podáváte."],["Podejte jeden ve čtyři ráno s žádostí, ať rozhodnou o všem najednou.","Devět set stran žádajících nápravu ve čtyřiceti jedna nesouvisejících věcech. Zamítnuto jednou větou, o čtyři slova delší, než si ta žádost zasloužila."]]},"f-the-index":{"t":"Index","x":"Monitorovací organizace v Göteborgu poprvé za padesát let přeřadila Spojené státy z nejvyšší klasifikace. Muriel má zprávu. Má 300 stran a jmenuje vás hned v prvním odstavci.","c":[["Sankcionujte organizaci. Zpochybněte její financování.","Národní vláda, která formálně útočí na švédský akademický index, se sama stává ukazatelem v příští metodologii. Číslo jste posunul právě tím, že jste na něj reagoval."],["Zcela to ignorujte. Nikdy o tom nemluvte.","Dva dny se o tom píše v médiích, která vaši voliči nečtou, a třicet let to citují lidé, kteří píší učebnice."],["Zveřejněte vyvrácení. Zapojte se do diskuze o metodologii.","Vaše vyvrácení je seriózní, podrobné a částečně správné. V dalším vydání upraví dva ukazatele, a žebříček se nepohne ani o píď."],["Zadejte vytvoření konkurenčního indexu. Skončete v něm první.","Index svobodné excelence hodnotí Spojené státy jako první ze sto devadesáti tří. Jeho metodologie má čtyři řádky, a jeden z nich je osobně o vás."]]},"f-press-rank":{"t":"Padesátý sedmý","x":"Index svobody tisku posunul zemi o sedm míst dolů, na 64. místo. Kaylee: „Sevřená mezi dvěma zeměmi, které jste veřejně nazval diktaturami. To bude titulek.“","c":[["Řekněte, že je to žebříček útokem zahraničních zájmů.","Organizace přidá do profilu země větu o oficiálních odvetách. Každá vaše reakce se pak také započítává do skóre."],["Udělejte jednu konkrétní věc: obnovte místo pro tiskovou agenturu.","Jedna židle, jedna akreditace, jedno odpoledne. Žebříček se příští rok zlepší o čtyři místa a nikdo z vaší kanceláře nepřizná, že spolu ty dva fakty souvisí."],["Nic. Je to jen seznam.","Je to jen seznam, a cituje se v každém článku napsaném o vaší vládě po dalších čtyřicet let, což je přesně k čemu seznamy slouží."],["Poukažte na to, že 64. místo je pořád v horní třetině.","Aritmeticky správné, a jediná nejzničující věta, jakou kdo z vlády pronese, řečená vesele."]]},"f-stablecoin":{"t":"Dvě miliardy","x":"Suverénní investiční fond přesměruje 2 miliardy dolarů skrze token vydaný společností, kterou ovládá vaše rodina. Lyle: „Poplatek z toho toku je zhruba 100 milionů dolarů ročně, placeno vám cizím státem, nepřímo, navždy.“","c":[["Vezměte to. Je to soukromá obchodní dohoda.","Dvě slova nesou celou tíhu: „soukromá“ a „nepřímo“. Ani jedno nepřežije předvolání u soudu v roce 2032, kdy už jsou peníze dávno utracené."],["Vezměte to, ale zveřejňujte tok peněz měsíčně.","Plné zveřejnění neobhájitelné dohody ji téměř úplně zneškodní. Každý to vidí, takže se to nikomu nechce vyšetřovat."],["Odmítněte. Některé peníze mají zpáteční adresu.","Lyle odmítnutí napíše sám a schová si doma kopii, což u žádného jiného dokumentu za čtyři roky neudělal."],["Vezměte to a hned to půjčte zpět za horší úrok.","Kolotoč, ze kterého všichni vyjdou o něco chudší, kromě zprostředkovatele, který je náhodou spolubydlícím vašeho zetě."]]},"f-net-worth":{"t":"Přiznání majetku","x":"Výroční přiznání má 927 stran. Miriam Applewhitová je všechny přečetla. „Váš čistý majetek se v úřadu zhruba zdvojnásobil. Každý řádek je legální. Přesně to z toho dělá příběh.“","c":[["Podejte to v šest večer v pátek před svátkem.","Standardní praxe, kterou všichni chápou, vám koupí jedenáct dní. Tisková agentura si stejně přečte všech 927 stran, protože to je náplní práce jednoho novináře."],["Podejte to a uspořádejte k tomu tiskovou konferenci.","Devadesát minut otázek o dokumentu, který jste dobrovolně zveřejnil. Bolestivé, a téma to ukončí za jediné odpoledne."],["„Akciový trh šel nahoru. Vydělávají všichni.“","Střední hodnota bohatství domácností za stejné období stoupla o 1,4 procenta. Čtyři různá média toto srovnání provedou, přičemž jako zdroj použijí přímo vaše vlastní přiznání."],["Podejte to písmem, které nikdo nepřečte.","927 stran písmem velikosti šest bodů. Dobrovolnický přepisovací projekt to dokončí za devět dní, a prohledatelná verze pro vás dopadne mnohem hůř než originál."]]},"f-two-orders":{"t":"Balík","x":"Deborah má na první den připravené čtyři příkazy. Každý je krátký, každý je okamžitě napadnutelný u soudu a každý je navržený tak, aby byl nejdiskutovanější věcí v zemi po přesně jeden zpravodajský cyklus.","c":[["Všechny čtyři. Podepsané před kamerou. Ukázané celé místnosti.","Čtyři příkazy, čtyři žaloby, čtyři týdny masivního mediálního pokrytí. Dva jsou zrušeny, ale do té doby už odvedly jedinou práci, pro kterou byly napsány."],["Jeden po druhém, s odstupem čtrnácti dnů.","Vytrvalé místo okázalého. Každý dostane vlastní zpravodajský cyklus a kumulativní pokrytí je čtyřikrát vyšší, než kdyby se podepsaly najednou."],["Nepodepisujte nic. Pošlete celý spis Kongresu.","Tři zemřou ve výboru. Jeden projde v pozměněné podobě a skutečně přežije vaši vládu, což by žádný z originálů nedokázal."],["Podepište čtyři prázdné listy a vyplňte je později.","Fotografie existují, příkazy ne. Devět dní se země hádá o obsahu čtyř kusů prázdného papíru."]]},"f-service-ban":{"t":"Sloužící vojáci","x":"Tarrant má čísla: patnáct tisíc aktuálně sloužících, čtyři sta nasazených, a hodnocení bojeschopnosti z předchozí vlády, které nezjistilo naprosto žádný operační dopad.","c":[["Podepište to. Mají devadesát dní.","Čtyři sta lidí je odvoláno z nasazení. Jejich náhrady se školí šest měsíců. Tarrant založí cenu za bojeschopnost do memoranda, které nikdy nepřečtete."],["Zaveďte výjimku pro všechny, kteří už slouží.","Politika se netýká nikoho, kdo existuje. Tisková zpráva s právní citací, a u soudu obstojí přesně proto, že nic nedělá."],["Řiďte se hodnocením bojeschopnosti.","Tarrant řekne „děkuji, pane“ tónem, jaký jste od něj nikdy neslyšel. Patnáct tisíc lidí si udrží práci a nestane se naprosto nic."],["Zakažte kategorii, která v ozbrojených silách nikdy neexistovala.","Příkaz vylučuje kohokoliv s dědičným cizím titulem. Netýká se nulového počtu vojáků. Čtyři sta tisíc lidí to schvalně sdílí, aniž by si to ověřili."]]},"f-nuclear-deal":{"t":"Dohoda","x":"„Dodržují to. Naši vlastní inspektoři to potvrzují, spojenci to potvrzují, a dohoda funguje podle jediného měřítka, pro které byla napsána.“ Muriel zavře složku. „Vy jste kampaň vedl na tom, že ji roztrháte.“","c":[["Roztrhejte to. Obnovte všechno.","Za čtrnáct měsíců znovu zahájí obohacování. Tři evropští signatáři stráví dva roky snahou to udržet pohromadě, pak to tiše vzdají."],["Zůstaňte v dohodě a žádejte navazující smlouvu.","Navazující jednání trvají čtyři roky a vyprodukují něco jen mírně lepšího s vaším jménem na tom, což si nikdo z vaší základny nikdy nepřečte."],["Zůstaňte v dohodě a neustále porušujte jejího ducha.","Veškerá páka, žádný kolaps. Je to sofistikovaná verze, a na shromáždění je naprosto neviditelná."],["Roztrhejte to a vyfoťte útržky.","Fotografie roztrhané smlouvy skončí přetištěná ve čtyřech národních školních osnovách jako ilustrace něčeho, a to něco se liší podle země."]]},"f-fell-in-love":{"t":"Dopisy","x":"Hance má spis. Dopisy ze Severní Koreje jsou podle jeho profesního hodnocení „sepsané výborem tak, aby polichotily jednomu konkrétnímu jedinci“. Vy jste je popsal jako krásné.","c":[["Řekněte, že jste se zamiloval. Nahlas. Na shromáždění.","Čtyři spojenecké zpravodajské služby potichu omezí, co s vámi sdílejí. Dopisy nadále chodí. K žádné denuklearizaci nedojde a dva summity vyprodukují společné prohlášení o 79 slovech."],["Zachovejte kanál. Veřejně neříkejte nic vřelého.","Diplomacie je skutečná, lichotky zůstávají soukromé, a vede to k moratoriu na testování, které vydrží tři roky."],["Zveřejněte dopisy. Všechny.","Mimořádné dokumenty, hluboce trapné pro oba signatáře. Historici jsou nadšeni. Kanál se do čtrnácti dnů uzavře."],["Odepište ve verších.","Jedenáct řádků, bez rýmu, sepsaných Gideonem Poem pod protestem. Dostane se vám odpovědi ve stejném duchu, delší a s nápadně lepším rytmem."]]},"f-gold-star":{"t":"Rodina","x":"Rodiče vojáka padlého v boji vás veřejně, jmenovitě, kritizovali na televizní akci. Tarrant přišel říct přesně jednu věc: „Pane. Neexistuje žádná verze hádky s nimi, ve které byste vyhrál.“","c":[["Odpovězte. Nikdo s vámi takhle nemluví.","Táhne se to jedenáct dní. Čtyři senátoři z vaší vlastní strany se s vámi veřejně rozejdou. Podle každého ukazatele, jaký má průzkumník k dispozici, je to nejhorší týden vaší vlády."],["Neříkejte vůbec nic. Pošlete soukromý dopis.","Dopis se nikdy nezveřejní. O léta později letmo zmíní, že byl ručně psaný a lepší, než čekali."],["Zavolejte jim. Poslouchejte tak dlouho, jak budou chtít.","Devadesát minut, většinou mluví oni. Svůj názor na vás nezmění a řeknou to veřejně, a zároveň řeknou, že jste poslouchal, a citují se obě poloviny."],["Ať to celé vyřídí viceprezident.","Chet to samozřejmě zvládne dokonale, nechá se vyfotit s matkou a tu fotografii si nechá. Všimnete si, že si ji nechal."]]},"f-war-hero":{"t":"Senátor","x":"Senátor z vaší vlastní strany, vyznamenaný veterán, který byl pět let vězněn, hlasoval proti vám. Brayden má připravenou hlášku o jeho válečné minulosti. Kaylee přestala psát.","c":[["Použijte tu hlášku. O zajetí.","Mělo by to ukončit vaši kariéru. Neukončí. To, že neukončí, je jediný nejvýznamnější politický fakt celého desetiletí, a všichni v místnosti to okamžitě pochopí."],["Útočte na to hlasování. Nikdy na minulost.","Normální, brutální, naprosto konvenční politický útok. Funguje to, a nikdo o tom nenapíše knihu."],["Pochvalte jeho minulost a přijměte prohru.","Čtyři váhající senátoři pak u dalšího návrhu zákona hlasují s vámi, a ani jeden z nich to pořádně nedokáže vysvětlit."],["Udělte mu medaili. Velkou. Okamžitě.","Přijme ji s bezvadnou zdvořilostí a o jedenáct dní později znovu hlasuje proti vám, s medailí v ruce, a zmíní to."]]},"f-governor-pardon":{"t":"Guvernér, který prodal senátorské křeslo","x":"Bývalý guvernér si odpykal osm ze čtrnácti let za pokus prodat senátorské křeslo. Sy podotýká, že byl usvědčen na nahrávce, jak přesně tuto věc dělá, vlastním hlasem.","c":[["Zmírněte trest. Nazvěte ho velice slušným člověkem.","Do týdne je v televizi a nazývá to stíhání politickým. Čtyři další odsouzení úředníci podávají příští měsíc žádosti, přičemž citují přesně tento precedent."],["Zmírněte trest potichu, bez prohlášení.","Páteční seznam jedenácti jmen. Devět dní si toho nikdo nevšimne, a mezitím se z toho stane příběh o procesu, ne o morálce."],["Nechte to být. Byl nahraný, jak to dělá.","Úřad pro milosti místo toho zpracuje 14 000 čekajících žádostí od lidí bez právníků a 900 z nich vyřídí."],["Udělte mu milost pod podmínkou, že už nikdy veřejně nepromluví.","Podmínka je nevymahatelná, a on ji poruší do čtyř dnů, v podcastu, obšírně, a jmenovitě vám poděkuje."]]},"f-activist-pardons":{"t":"Blokáda","x":"Dvacet tři lidí odsouzeno za fyzickou blokádu kliniky. Bo: „Znali zákon, byli toho dne varováni a odsouzení chtěli. Je to strategie mučednictví, pane, a dobrá.“","c":[["Udělte milost všem třiadvaceti. Pozvěte je dovnitř.","Fotografie na schodech koluje ve všech emailech pro sběr financí, na obou stranách, po čtyři roky. Má to větší cenu pro vaše odpůrce než pro vás, a oba to víte."],["Udělte jim milost. Bez ceremonie, bez fotografie.","Milost bez inscenace je titulkem na jeden den. Vaše základna dostane, co chtěla, a nikdo jiný nedostane obrázek."],["Nic. Zákon je zákon.","Čtyři náboženští vůdci, kteří vás deset let bránili, vám natrvalo přestanou zvedat telefony, kvůli třiadvaceti lidem."],["Udělte milost jim i lidem, které blokovali.","Druhá skupina nebyla nikdy z ničeho obviněna. Přesto dostanou milost, za nic, a čtyři z nich si osvědčení dají do rámečku."]]},"f-stand-by":{"t":"Otázka z debaty","x":"Byl jste naživo, v celostátní televizi, požádán, ať jmenovitě odsoudíte ozbrojenou skupinu. Brayden je ve vašem sluchátku. Devadesát milionů lidí sleduje a máte zhruba čtyři vteřiny vysílacího času.","c":[["„Buďte připraveni.“ Řekněte to a jděte dál.","Skupina to do devadesáti minut vytiskne na merchandise. Následující čtyři dny strávíte vysvětlováním, že ta dvě slova znamenala opak toho, co zjevně znamenala."],["Odsuďte je. Jasně. Jmenovitě.","Čtyři vteřiny jednoznačné angličtiny. Nestojí vás to nic, co byste stejně jinak použil, a smaže to celý rok mediálního pokrytí."],["Odsuďte „veškeré násilí“ a nikoho nejmenujte.","Klasický únik. Nikoho neuspokojí, nikoho neurazí, a všichni to správně pochopí, což je přesně jeho smysl."],["Odsuďte skupinu, která neexistuje.","Důrazně odsoudíte Kolektiv západního předvoje. Čtyři ověřovatelé faktů potvrdí, že nikdy neexistoval. Jedenáct tisíc lidí do něj do měsíce stejně vstoupí."]]},"f-rat-infested":{"t":"Volební obvod","x":"Předseda výboru si předvolal vaše finanční záznamy. Brayden sepsal příspěvek o jeho volebním obvodu, jeho míře kriminality, bytovém fondu, a jednom přídavném jméně, které odvádí veškerou tíhu.","c":[["Zveřejněte to. Přídavné jméno zůstává.","Dobrovolníci následující víkend uklidí čtyři bloky toho obvodu a vyvěsí fotky. Je to nejlépe zorganizovaná odezva, jakou kdy váš příspěvek vyvolal."],["Zveřejněte statistiky kriminality. Bez přídavného jména.","Čísla jsou skutečná, rámování je brutální, a nikdo s tím nic nezmůže. Podstatně účinnější, a naprosto neocitovatelné."],["Zajeďte tam. Oznamte federální bytový program.","Při příjezdu vás vypískají, při odjezdu vám zatleskají. Předvolání se nestáhne, a program stejně postaví devět set bytů."],["Místo toho pište o svém vlastním obvodu.","Žádný obvod nemáte. Popíšete ten, kde jste vyrostl, nelaskavě, a jeho současní obyvatelé odpoví v hojném počtu."]]},"f-death-toll":{"t":"Počet obětí","x":"Akademická studie odhadla počet obětí hurikánu na tomto území na téměř tři tisíce, daleko nad původní oficiální počet. Duane má metodologii. Je solidní.","c":[["Zpochybněte to číslo. Řekněte, že bylo vymyšleno, aby vám uškodilo.","Tři tisíce lidí se stanou rétorickou pozicí. Území na to nezapomene, ani jediná rodina jmenovaná v příloze."],["Přijměte to. Nařiďte úplný rozbor postupu.","Rozbor odhalí čtyři systémová selhání, tři z nich předcházejí vaší vládě. Náprava stojí 2 miliardy dolarů a při příští bouři odhadem zachrání jedenáct set životů."],["Přijměte to číslo. Neříkejte už nic dalšího. Nikdy.","Mlčení o počtu obětí je jediná důstojná možnost na stole, a je to za jeden den vyřízené."],["Zeptejte se, jestli lze to číslo upravit o inflaci.","Otázka je položena upřímně, na poradě jedenácti lidí. Nikdo na ni neodpoví. Dva z nich to mlčení nezávisle na sobě popíší v pozdějších rozhovorech."]]},"f-health-body":{"t":"Globální organizace","x":"Odstoupení vyžaduje dvanáctiměsíční výpovědní lhůtu a 400 milionů dolarů v nezaplacených příspěvcích. Pike: „Napsali jsme většinu jejích protokolů. Odcházeli bychom z instituce, kterou jsme vybudovali, kterou vedeme a kterou stále používáme.“","c":[["Podejte výpověď hned první den.","Ztratíte přístup k síti sdílení kmenů chřipky, která určuje složení vakcíny. Nikdo v místnosti to v den podpisu neví."],["Zůstaňte a zadržte polovinu financování.","Veškerá páka, žádný odchod. Čtyři reformy, které jste opravdu chtěl, se do dvou let přijmou."],["Zůstaňte. Místo toho žádejte rezignaci generálního ředitele.","Za osmnáct měsíců je pryč, nahrazen někým, s kým souhlasíte, což byl celou dobu ten skutečný cíl."],["Založte konkurenční organizaci se čtyřmi členy.","Globální zdravotní aliance svobodných. Zakládající členové: vy a tři země s celkovou populací menší než stát Ohio."]]},"f-education":{"t":"Ministerstvo","x":"Ollis: „Ministerstvo zřízené zákonem nemůžete zrušit. Můžete ho zredukovat na telefonní ústřednu. Ta ústředna by ale pořád musela posílat 28 miliard dolarů ročně školám, protože to je taky ze zákona.“","c":[["Zredukujte ho na ústřednu. Zbytek propusťte.","Peníze pořád odchází, protože musí. Přestane fungovat vymáhání podmínek, které jsou k nim vázané, což byla celá práce."],["Ponechte ho. Změňte, co podmínky vyžadují.","Stejné ministerstvo, stejní zaměstnanci, stejných 28 miliard dolarů, úplně jiné podmínky. Rychlejší, levnější a naprosto neviditelné."],["Pošlete Kongresu návrh zákona o zrušení a nechte ho zemřít.","Získá 189 hlasů. Čtyři roky vedete kampaň na těch 189 a ani jednou nezmíníte, že jste potřeboval 218."],["Zrušte ho a přesuňte ústřednu na poštu.","Poštovní služba je ústavně oddělená a nelze jí to přiřadit. Čtyři právníci to vysvětlí. Přesto se o to pokusí a ztroskotá to na technikálii o poště."]]},"f-roe-credit":{"t":"Zásluhy","x":"Soud zvrátil padesátiletý precedent. Reverend Muncy je v místnosti a pláče. Nadia má průzkumy: zvrácení je neoblíbené o jedenáct bodů, a vaše role v tom je sotva známá.","c":[["Přivlastněte si to. „Dokázal jsem to udělat.“","Osobně se spojíte s nejméně oblíbeným institucionálním činem desetiletí. Vaše základna je u vytržení, a čtyři předměstské okresy se přesunou o jedenáct bodů opačným směrem."],["Připište zásluhy soudcům a neříkejte nic dalšího.","Zdrženlivost, od vás, právě u tohohle. Muncy si toho všimne a řekne to z kazatelny, což má větší cenu, než by kdy mělo přivlastnění si zásluh."],["Řekněte, že rozhodl soud a vy jste s tím neměl nic společného.","Není to pravda, jmenoval jste tři z nich a tehdy jste to sám řekl, a archivní záznam se do jednoho dne pustí vedle vašeho popírání."],["Přivlastněte si zásluhy za rozhodnutí, které šlo proti vám.","Popíšete prohru 6:3 jako osobní vítězství tak podrobně, že dvě televizní stanice ověřují, jestli náhodou nemají špatné jméno případu."]]},"f-political-scientists":{"t":"Průzkum","x":"Dr. Weirová má průzkum mezi devíti sty politology. Jejich hodnocení kvality americké demokracie kleslo za deset měsíců víc, než za předchozích čtyřicet let dohromady. „Žádal jste mě o poctivý materiál, pane.“","c":[["Nechte přezkoumat jejich federální granty.","Přezkum nic nenajde. Příští rok se do průzkumu přidá otázka o zastrašování výzkumníků a skóre znovu klesne, rychleji."],["Pozvěte si čtyři z nich. Zeptejte se, co by to posunulo zpět.","Dají vám jedenáct konkrétních, nudných, dosažitelných odpovědí. Dvě z nich provedete. Obě fungují."],["Ignorujte to. Je to devět set profesorů.","Je to devět set profesorů, a je to soubor dat, ze kterého se nakonec píší všechny dějiny tohoto období."],["Vyplňte průzkum sám a odešlete ho anonymně.","Zemi ohodnotíte výš než kterýkoliv jiný respondent, o čtyřicet bodů. Odeslání se do týdne vystopuje podle IP adresy."]]},"f-anticipatory":{"t":"Nikdo je nežádal","x":"„Advokátní kancelář přislíbila 100 milionů dolarů bezplatné práce pro záležitosti, které se vám líbí. Univerzita změnila přijímací politiku. Televizní síť zrušila pořad.“ Deborah vzhlédne. „Pane, o nic z toho jsme nežádali.“","c":[["Neříkejte nic a přijměte to všechno.","Žádný příkaz k napadení, žádná hrozba k dokázání, žádné memorandum k předvolání. Instituce, které vyčtou náladu v místnosti, se ukazují jako nejúčinnější forma moci, jaká kdy byla vynalezena."],["Pochvalte je jmenovitě. Povzbuďte ostatní.","Jejich jmenování promění neviditelný proces na viditelný, což je pro vás horší, a mnohem rychlejší."],["Veřejně jim řekněte, že to nebylo nutné.","Dva ze subjektů do čtrnácti dnů svá rozhodnutí zvrátí. Je to jediná nejvíce deeskalující věta, jaká existuje, a stojí vás to obrovsky."],["Požádejte je o něco obrovského a sledujte, jestli řeknou ano.","Dva ze tří řeknou ano. Třetí se zdvořile zeptá, jestli je žádost písemná. To, že není, nakonec odpoví na všechno."]]},"f-generals-room":{"t":"Sál plný generálů","x":"Na vaše přání se v jednom sále shromáždili všichni generálové ozbrojených sil. Gideon má návrh projevu, který čtyřikrát použije frázi „nepřítel uvnitř“. Tarrant si to přečetl.","c":[["Přednete ho tak, jak je napsán.","Nikdo v sále nevstane. Ale nikdo taky neodejde. Čtyři z nich to ticho popíšou ve svých pamětech, s odstupem desetiletí, a všechny čtyři popisy se shodují."],["Vypusťte tu frázi. Zbytek přednesete.","Silný, konvenční, naprosto zapomenutelný projev k důstojnickému sboru. Tarrant vám poté poděkuje za konkrétní vynechání a neřekne, které."],["Zeptejte se jich raději, co potřebují. Nechte je se ptát.","Devadesát minut otázek od lidí, kteří se jinak nikdy nedostanou ke slovu. Čtyři rozhodnutí o pořizování zbraní se v přímém důsledku změní."],["Přednete ho, ale o konkrétním hmyzu.","Jedenáct minut o krasci čtyřtečném, přednesených s naprostým přesvědčením před čtyřmi sty admirály. Milovaný, matoucí, a citovaný po celou generaci."]]},"g-blocked-seat":{"t":"Podrženo místo","x":"Hal držel místo u Nejvyššího soudu prázdné jedenáct měsíců s teorií, že by měl nejprve rozhodnout lid. Teď se uvolnilo místo ve vašem vlastním posledním roce. „Pane, ten argument nikdy nebyl o kalendáři. Byl o tom, čí je to kalendář.“","c":[["Obsaďte ho. Dnes. Necitujte žádný princip.","Potvrzen za rovných dvacet sedm dní, s odkazem výhradně na aritmetiku toho, kdo má právě předsednické kladívko, což se ukáže jako dostatečný princip."],["Obsaďte ho, a vymyslete si úhledné rozlišení podle toho, který je to rok.","To rozlišení má čtyři věty a zhroutí se pod první doplňující otázkou, kterou zodpovíte jiným, stejně dočasným rozlišením."],["Nechte ho volné. Řiďte se pravidlem, které jste sám stanovil.","Obsadí ho místo vás váš nástupce. Čtyři právní historici to později citují jako poslední zaznamenaný případ amerického politika vázaného vlastním precedentem."],["Obsaďte ho člověkem, kterého Hal před jedenácti lety zablokoval.","Je mu jedenasedmdesát, potvrzen poměrem osmdesát devět ku jedenácti, a stráví čtyři roky svědomitou, šíleně spravedlivou nestranností ke všem, což obě strany shledávají nesnesitelným."]]},"g-nationwide":{"t":"Jeden soudce, celá země","x":"„Jeden jediný okresní soudce může zmrazit celostátní politiku. Argumentovali jsme, že je to protiústavní.“ Bo obrátí stránku. „Pokud ten argument vyhrajeme, pane, zmrazí to i každou politiku, kterou se kdy pokusí podepsat váš nástupce.“","c":[["Vyhrajte to i tak. Vezměte ten nástroj ze stolu natrvalo.","Vyhrajete. Celostátní soudní zásahy se prudce omezí, a o čtyři roky později je to jediná největší překážka pro zvrácení čehokoliv, co jste vybudoval, přesně podle plánu."],["Argumentujte to úzce. Jen v tomto jednom případě.","Výjimka, ne doktrína. Koupí vám to tuto jednu politiku a ponechá zbraň plně nabitou ve stojanu i pro příští vládu."],["Vzdejte se argumentu. Bojujte věcně.","Prohrajete případ a vyhrajete instituci, obchod, za který nebyl žádný politik v zaznamenané historii nikdy poděkován."],["Zeptejte se, který soudce. Pak ho nechte zvát na akce.","Odmítne všechny čtyři pozvánky písemně, přepošle je soudní konferenci, a o devět dní později proti vám rozhodne, obšírněji, než bylo nezbytně nutné."]]},"g-immunity":{"t":"Úřední akty","x":"„Soud rozhodl, že soud nesmí zkoumat vaše pohnutky k úřednímu aktu.“ Sy položí ten nález, jako by mohl vybuchnout. „Pane, tahle jedna věta teď odvádí víc práce, než zbytek amerického práva dohromady.“","c":[["Postavte na tom všechno. Citujte to v každém podání.","Třetina vašich naléhavých návrhů se o to teď opírá. Stavíte celou konstrukci na jediné větě, a každá nová cihla dělá tu větu nosnou."],["Použijte to jednou, na něco malého, ať se stanoví rozsah.","Nepatrný testovací případ, podaný potichu, který nevytáhne žádné titulky a natrvalo urovná hranice. Teď je vám to dostupné do konce vašeho přirozeného života."],["Nikdy se na to neodvolávejte. Štít, který používáte, se stává terčem.","Sy je proti veškerému profesnímu instinktu ohromen. Ochrana zůstává totální a naprosto neotestovaná, což je nejsilnější možná podoba hrozby."],["Prohlaste čištění zubů za úřední akt.","Podáno, s naprosto vážnou tváří, v poznámce pod čarou, čistě proto, aby se zjistilo, jak daleko ta kategorie sahá. Soudce to zaznamená v souhlasném stanovisku s viditelnou, zdokumentovanou únavou."]]},"g-complicated":{"t":"Nikdo to nevěděl","x":"Dr. Pike vás čtyřikrát provedl dotacemi na tržišti zdravotního pojištění. Právě jste sálu guvernérů řekl, že nikdo netušil, že zdravotnictví může být takhle složité.","c":[["Řekněte to znovu veřejně. Je to upřímné.","Každý, kdo pracuje ve zdravotní politice, to věděl. Je to ostatně celá jejich práce. Ten záznam se pouští na čtyřech konferencích ročně po celé desetiletí, vždy pro stejný smích."],["Přiznejte se k učení. Veřejně pokládejte lepší otázky.","Prezident, který se viditelně před kamerou něco učí, je natolik vzácný jev, že to vede dvě zpravodajství. Pike dostane devět nerušených minut a využije každou jednu z nich."],["Svalte tu složitost na předchozí vládu.","Ta složitost jim předchází o čtyřicet let a sahá ke kompromisu, který vyjednala vaše vlastní strana v roce 1974, fakt, který tři ověřovatelé faktů zveřejní ještě před večeří."],["Vyřešte to naživo, na tabuli, za devadesát minut.","Tabule se vyfotí ze všech úhlů. Čtyři zdravotní ekonomové to vážně prostudují a dojdou k závěru, že by to stálo dva biliony dolarů a pokrylo o jedenáct lidí méně."]]},"g-briefing-podium":{"t":"Pódium","x":"Admirál Prine stojí po vaší levici, generální chirurg po pravici, a pódium je vaše na devadesát minut denně. Prine: „Pane, cokoliv tady nahoře řeknete, se do oběda stane klinickým doporučením, ať už jím je nebo ne.“","c":[["Vezměte si celých devadesát minut. Každý den.","Sledovanost je mimořádná. Stejně tak nárůst hovorů na toxikologickou linku během čtyř dnů po jedné konkrétní úvaze o domácích chemikáliích."],["Zahajte, předejte slovo Prineovi, opusťte místnost.","Dodržování doporučení veřejného zdraví stoupne za čtrnáct dní o čtrnáct bodů, čistě proto, že je teď podává člověk se skutečným lékařským titulem."],["Zůstaňte, ale neodpovídejte na nic klinického.","Skutečná disciplína, vydrží jedenáct dní, a poruší ji dvanáctého dne jedna otázka o doplňku stravy."],["Přineste místo toho graf vlastní popularity.","Devět minut brífinku o veřejném zdraví strávíte vlastními čísly podpory. Generální chirurg celých těch devět minut zkoumá podlahu."]]},"g-power-plan":{"t":"Pravidlo o uhlí","x":"„Můžete to zrušit, ale nemůžete to zrušit do nicoty, soud bude žádat náhradu.“ Cassandra pokrčí rameny. „Takže jediná skutečná otázka je, jak slabá může ta náhrada být, než přestane právně platit jako náhrada.“","c":[["Nahraďte to něčím, co nic nezmění.","Náhrada má čtyři sta stran a její vlastní povinná analýza dopadů přiznává, že dosahuje jednoho procenta účinku originálu. Toto přiznání je teď natrvalo v záznamu."],["Nahraďte to něčím skromným a obhajitelným.","Přežije to soudní přezkum, na rozdíl od předchozích čtyř pokusů kohokoliv, a v roce 2041 to stále nenápadně stojí."],["Ponechte to. Přivlastněte si zásluhy za elektrárny, které se stejně zavírají.","Ty elektrárny se zavíraly kvůli ekonomice, ne regulaci, a vy to víte, a přesto si zásluhy přivlastníte, což je poctivější, než většina věcí, které říkáte."],["Nahraďte to pravidlem o palivu, které nikdo nepoužívá.","Komplexní národní normy pro velrybí olej. Právně neprůstřelné, nedosahuje naprosto ničeho, a spotřebuje jedenáct měsíců něčího jediného života na sepsání."]]},"g-refuge":{"t":"Rezervace","x":"Pobřežní planina je uzavřená pro těžbu od roku 1980. Cassandra: „Prodej pronájmů se může uskutečnit. Jestli někdo nabídne, je jiná otázka, čtyři velké společnosti už řekly, že ne.“","c":[["Uspořádejte prodej. Smysl je v tom, že se to stalo.","Objeví se dva zájemci, jeden z nich státní agentura, která kupuje pronájmy výslovně proto, aby zabránila rozvoji. Vynese to čtrnáct milionů dolarů oproti odhadovaným 1,8 miliardám, a precedent je navždy."],["Uspořádejte to a vylepšujte podmínky, dokud někdo nenabídne.","Sazby licenčních poplatků nastavené tak nízko, že by vláda prodělávala i na úspěšné vrtné jámě. Objeví se tři zájemci. Nikdo nevyvrtá jedinou díru."],["Nechte to uzavřené. Otevřete něco, co už je průmyslové.","Čtyři brownfieldy vynesou víc skutečné produkce, než by rezervace kdy za deset let dala, a ani jedna žaloba."],["Pronajměte to ochranářskému fondu, který nikdy nebude vrtat.","Zaplatí plnou cenu za právo s tím absolutně nic nedělat. Je to legální, je to skutečný prodej, a je to nejvtipnější čtení ropného pronájmu, jaké kdy bylo zaznamenáno."]]},"g-send-her-back":{"t":"Skandování","x":"Před čtyřmi dny jste řekl něco o kongresmance. Dav před vámi z toho teď udělal skandování, dlouhé třináct vteřin a stále rostoucí. Brayden přestal dýchat.","c":[["Nechte to plynout. Neříkejte nic. Vyčkejte, až to odezní.","Třináct vteřin se stane celým příběhem. Čtyři členové vlastní strany to jmenovitě odsoudí, a vy strávíte týden vysvětlováním mlčení."],["Přerušte to. „Ne, ona je Američanka.“","Šest slov do živého mikrofonu, na vlastním shromáždění. Dav se skutečně zastaví. Je to jediná nejodvážnější věc, kterou před svými příznivci uděláte, a nikdy vám to úplně neodpustí."],["Přehlušujte to, dokud to nezanikne.","Profesionální tah: žádný záznam, jak se přidáváte, žádný záznam, jak to zastavujete. Obě strany si nárokují tu nahrávku, a ani jedna ji nakonec nedokáže použít."],["Spusťte jiné skandování. Okamžitě. Jakékoliv skandování.","Místo toho začnete skandovat o infrastruktuře. Jedenáct tisíc lidí se k vám přidá čistě setrvačností. Je to nejpodivnější zvrat, jaký kdy kamera zachytila."]]},"g-general-lee":{"t":"Socha generála","x":"Když jste byl dotázán na památník, pochválil jste generála jako skvělého vojáka. Dr. Weirová přinesla jeho skutečné dopisy. „Byl proti památníkům, pane. Písemně. Dvakrát. Myslel si, že navěky udrží ránu otevřenou.“","c":[["Chvalte ho dál. Byl to skvělý generál.","Taktikou byl opravdu dobrým generálem, což je nejužší dostupná obhajoba, a vy si vyberete zrovna tu. Dopisy vyjdou v tisku hned vedle vašeho výroku."],["Přečtěte jeho dopisy nahlas. Ať argumentuje sám za sebe.","Použít mužovu vlastní písemnou námitku k ukončení sporu o jeho vlastní sochu je nejelegantnější tah na stole, a stojí vás jedenáct bodů u vaší základny."],["Řekněte, že je to místní záležitost, a odmítněte se zapojit.","Správné, nudné, a naprosto neuspokojivé pro každého, kdo přišel na hádku, což je každý."],["Navrhněte sochu dopisů místo muže.","Bronzová otevřená kniha, zadaná a opravdu krásná. Dva okresy se o ni devět let přou z důvodů, které nikdo zúčastněný nedokáže pořádně shrnout."]]},"g-project-binder":{"t":"Institut","x":"„Devět set stran, sepsaných za čtyři roky lidmi, které jste nikdy nepotkal, pokrývajících každý úřad. V kampani jste se toho zřekl.“ Deborah to položí na stůl. „Kapitola jedna, pane, je seznam personálního obsazení.“","c":[["Zaveďte to. Kapitolu po kapitole. Najímejte podle seznamu.","Šedesát procent toho je zavedeno do osmnácti měsíců. Vaše popření běží každý večer smyčkou vedle sledovacího přehledu implementace, a nehne to přesně ničím."],["Vezměte si seznam obsazení. Ignorujte politiku.","Lidé jsou tou politikou. Najmutím čtyř set autorů toho dokumentu ho implementujete, aniž byste technicky přijal jediné jeho slovo."],["Vyhoďte to. Zřekl jste se toho a myslel jste to vážně.","Institut do roka financuje protikandidáta v primárkách. Je to jediný nejnákladnější čin integrity, jaký vaše vláda kdy provede."],["Zaveďte jen kapitolu jedenáct. Ostatní nečtěte.","Kapitola jedenáct se ukáže být o údržbě federálních budov. Provede se bezchybně, a Úřad pro obecné služby zažívá nejlepší dekádu své existence."]]},"g-no-independent":{"t":"„Neexistují žádné nezávislé úřady“","x":"Váš ředitel rozpočtu před kamerou prohlásil, že něco jako nezávislý úřad neexistuje. Deborah: „Je to právní teorie se skutečnou podporou v pozadí. Řečeno takhle nahlas je to ale zároveň přiznání záměru.“","c":[["Podpořte to. Řekněte to sám, těmi slovy.","Každé odvolání je od teď souzeno proti vyslovené teorii, ne konkrétnímu faktu. Předal jste druhé straně terč a zadarmo zahodil nejednoznačnost."],["Nechte ho, ať to řekne. Nikdy to nepotvrzujte.","Teorie nadhozená podřízeným je teorie, které se do oběda můžete zříct. Přesně proto byl najat, a on to ví."],["Opravte ho veřejně. Některé úřady nezávislé jsou.","Čtyři ředitelé úřadů poprvé za rok pořádně spí. Do jara podá výpověď a obšírně o tom píše, za peníze."],["Souhlaste, a jako výjimku prohlaste meteorologickou službu za nezávislou.","Jedna výjimka, vybraná v podstatě náhodně, díky které celá teorie zní ještě rozsáhleji, ne méně. Nikdo to pořádně nedokáže vysvětlit, a přesto to všichni cítí."]]},"g-hundred-thirty":{"t":"Sto třicet dní","x":"Vandermeer je zvláštní vládní zaměstnanec. Tato kategorie má pevný strop: sto třicet dní ročně. Vyčerpal sto osmnáct. „Tohle nikdo doopravdy nepočítá,“ říká. Deborah potichu: „Někdo tohle počítá.“","c":[["Přestaňte počítat. Zůstává.","Zákonný limit, který nikdo nesleduje, funkčně limitem není. Čtyři žádosti o svobodný přístup k informacím nakonec zjistí, že sloužil dvě stě devadesát jeden den, a s ničím z toho není spojen žádný důsledek."],["Udělejte z něj plnohodnotného zaměstnance. S plnou povinností přiznání majetku.","Do týdne raději odejde, než by to přiznání podal. Kategorie sto třiceti dní existovala přesně proto, aby se tomuto formuláři vyhnula, a teď to všichni ví."],["Nechte ho dosáhnout limitu a odejít.","Odchází ve sto třicátý den s motorovou pilou a livestreamem. Úřad, který vybudoval, ho snadno přežije, což bylo vždycky to skutečné riziko."],["Dejte mu druhé zaměstnání, ať se dny počítají zvlášť.","Je jmenován do čtyř různých úřadů najednou, každý s vlastními samostatnými hodinami sto třiceti dní. Aritmeticky geniální, právně neobhajitelné, a nikdo proti tomu nehne prstem."]]},"g-two-billion-case":{"t":"Peníze, které se už dluží","x":"„Dvě miliardy dolarů za pomoc, která už byla dokončena. Tyhle faktury jsou za dokončené zakázky.“ Lyle vzhlédne. „Tohle nejsou granty, které odmítáme, pane. Tohle jsou účty, které prostě neplatíme.“","c":[["Neplaťte. Veďte to soudní cestou až po poslední instanci.","Prohrajete, pět ku čtyřem, u naléhavého návrhu. Devět set dodavatelů do té doby už zkrachovalo, fakt, kterým se nález vůbec nezabývá, protože nálezy to nikdy nedělají."],["Zaplaťte dokončenou práci. Zrušte vše budoucí.","Právně nenapadnutelné, a zajistí to devadesát procent úspor, aniž by po sobě zanechalo jedinou judikaturu, kterou by proti vám mohl kdo později citovat."],["Zaplaťte to celé. Bojujte místo toho o příští rozpočtové přidělení.","Bojovat o příští přidělení místo posledního je způsob, jakým tenhle systém skutečně funguje. Je to pomalejší, a funguje to."],["Zaplaťte ve vlastní vymyšlené měně.","Státní dluhopisy splatné v roce 2041. Čtyři dodavatelé je přijmou. Jeden svůj v roce 2033 se ziskem prodá a na krátkou chvíli se stane docela slavným."]]},"g-hotel-ledger":{"t":"Účetní kniha","x":"Miriam Applewhitová má rezervační záznamy: jedenáct zahraničních delegací, jedna nemovitost, vaše jméno nad dveřmi. „Nikdo netvrdí, že šlo o výměnu služeb, pane. Nikdo to nepotřebuje. Ta účetní kniha je tím obviněním sama o sobě.“","c":[["Pokračujte v přijímání rezervací. Je to hotel.","Je to technicky hotel. Je to taky jediný hotel na zemi, kde ministerstvo zahraničí může poslat peníze úřadujícímu hlavě státu a na oplátku dostat klíč od pokoje."],["Věnujte zisk ze zahraničí ministerstvu financí.","Číslo si spočítáte osobně, nezveřejníte žádnou metodologii, a pošlete šek. Je to naprosto neověřitelné, a funguje to dokonale."],["Odmítejte zahraniční rezervace rovnou.","Podmínka je splněna, příběh přes noc zanikne, a nemovitost ztratí třicet procent příjmů ve prospěch konkurence o čtyři bloky dál."],["Účtujte zahraničním delegacím čtyřnásobek a nazvěte to clem.","Cena za pokoj zaznamenaná v rezervačním systému jako celní poplatek. Dvě velvyslanectví to zaplatí bez zpochybnění položky, což vypovídá vše o velvyslanectvích."]]},"g-caravan":{"t":"Slovo pro to","x":"Několik tisíc lidí jde na sever. Duane má skutečná čísla, věk a složení skupiny. Brayden má slovo, a to slovo se v Duaneově brífinku nikde nevyskytuje.","c":[["Použijte to slovo. Vyšlete vojáky, ať je čekají.","Pět tisíc vojáků se nasadí na hranici, kterou skupina dosáhne o jedenáct týdnů později, kdy už se většina rozešla a vojáci jsou dávno doma."],["Použijte to slovo. Nikoho nevysílejte.","Veškerá rétorika, žádné náklady. To slovo odvede celou práci, a Pentagon je potichu rád, že do toho nemusí jít."],["Uveďte skutečná čísla. Vyřiďte to řádně.","Čtyři tisíce lidí, převážně rodin, zpracovaných za devět měsíců. Dvě třetiny jsou odmítnuty a vyhoštěny, přesně podle zákona, a nikdo se neobtěžuje to natočit."],["Pošlete jim na hranici naproti pochodovou kapelu.","Nikdo nedokáže určit, co to gesto znamená, včetně vás. Čtyři dny se to rozebírá na třech kontinentech a dodnes to zůstává naprosto nevysvětlené."]]},"g-registry-quota":{"t":"Strop na zemi","x":"Třetí verze vstupního omezení prošla přezkumem, protože je formulována kolem prověřování, nikoli národnosti. Muriel: „Je to identický seznam, pane. Prošel, protože třetí návrh přidal odstavec o postupu.“","c":[["Rozšířit ho, když ten rámec funguje.","Z devíti zemí je čtrnáct. Odstavec o prověřování se pokaždé kopíruje doslovně a nikdy se skutečně neposuzuje podle svých vlastních argumentů."],["Nechat to na devíti. Rámec netestovat.","Zdrženlivost zrozená z čisté právní opatrnosti. Vydrží čtyři roky, prostě proto, že nikdo nikdy nedal soudu důvod podívat se na to znovu."],["Nahradit ho skutečným prověřováním jednotlivých žadatelů.","Stojí to čtyři sta milionů dolarů, rozjezd trvá jedenáct měsíců a odmítá to víc lidí, než kdy odmítl ten seznam, a to na základě důvodů, které obstojí při každém napadení."],["Přidat zemi, která nemá vládu.","Nezbývá nikdo, kdo by mohl podat protest, což čtyři úředníci s uspokojením konstatují, přesně do chvíle, než se jeden z nich zeptá, co se stane se žadateli, kteří už jsou na půli cesty ve vzduchu."]]},"g-health-story":{"t":"Zpráva o vašem zdraví","x":"Noviny zveřejnily článek o vašem zdraví, se zdroji od čtyř lidí přímo z budovy. Kaylee: „Není to nesprávné, pane. Přesně proto to nemůžu nechat opravit.“","c":[["Zaútočit na noviny. Nazvat je nepřítelem lidu.","Příběhem se teď stává ten útok, ne zdraví. Ta záměna funguje, a funguje jedině tak, že potvrdí, že tam bylo něco, co stálo za útok."],["Zveřejnit skutečné záznamy. Všechny.","Ukážou se jako naprosto nepozoruhodné, dokonce mírně nudné. Jejich zveřejnění ukončí čtyři roky spekulací během jediného odpoledne a Prine je konečně nechají na pokoji."],["Najít ty čtyři zdroje. To je ten skutečný problém.","Dva se podaří identifikovat a odstranit. Zbylí dva s vámi prostě přestanou mluvit a začnou si všechno zapisovat, což je podstatně horší."],["Vyzvat šéfredaktora na férovku.","Je mu šedesát tři a okamžitě přijímá, s viditelným nadšením. Ve skutečnosti k tomu nikdy nedojde. Oba pak roky tvrdíte, že to vzdal ten druhý."]]},"g-pool-slot":{"t":"Trvalé místo","x":"„Tiskové agentury mají trvalé místo v tiskovém poolu od osmdesátých let devatenáctého století. Ne podle zákona, podle zvyku.“ Kaylee zavírá složku. „Pool řídíme my, pane. Mohli bychom ho prostě přestat mít.“","c":[["Zrušit trvalé místo. Pool si vybrat sami.","Sto čtyřicet let zvyku končí jedním e-mailem. Náhradníci jsou přívětivější, otázky měkčí a žádný zákon nebyl porušen, protože žádný zákon k porušení nikdy neexistoval."],["Přidat přátelská média vedle agentur.","Zředění místo odstranění. Agentury si podrží své místo, ale ztratí monopol na první otázku, což bylo jediné, na čem kdy záleželo."],["Nechat to být. Zvyk přežije každého prezidenta.","Kaylee jedenáct minut v kuse argumentuje proti vlastnímu doporučení a viditelně, slyšitelně se jí uleví, když prohraje."],["Dát trvalé místo středoškolským novinám.","Sedmnáctiletá dívka z Daytonu položí ve čtvrtém týdnu na place jednu jedinou nejlepší otázku roku a čtyři televizní stanice s ní otevřou vysílání."]]},"g-summit-praise":{"t":"Společné prohlášení","x":"Stojíte na pódiu vedle hlavy státu, kterou vaše vlastní zpravodajské služby obvinily z vměšování, a v přímém přenosu se vás ptají, čí verzi přijímáte. Hance to sleduje ze vzdálenosti necelých dvou metrů.","c":[["Říct, že nevidíte důvod, proč by to měli být oni.","Členové vaší vlastní strany vydávají prohlášení dřív, než vůbec sejdete z pódia. Celý následující den vysvětlujete, že jste tam chtěl doplnit slovo „ne“."],["Postavit se za vlastní agentury. Bez obalu. Přímo na pódiu.","Devět slov, vyřčených po jeho boku, bez jediné výhrady. Hance vůbec nezareaguje, což je u Hance ekvivalent standing ovace."],["Odmítnout otázku. Mluvit o obchodní dohodě.","Odklon tak zjevný, že si ho všimne úplně každý, ale nikdo ho nemůže doslovně citovat. Je to správná odpověď a neuspokojí naprosto nikoho."],["Říct, že přijímáte obě verze zároveň.","Schválně v jedné větě zastáváte dvě naprosto protichůdná stanoviska a vyzýváte kohokoli, ať si jedno vybere. Čtyři redakce otisknou celý citát, protože ho prostě není možné shrnout."]]},"g-tariff-autos":{"t":"Pětadvacet procent","x":"Čtvrtinové clo na dovážená vozidla a díly. Lyle: „Čtyřicet procent auta vyrobeného v této zemi tvoří dovezené díly. Popisujeme daň na domácí výrobu jako její obranu.“","c":[["Zavést ho. Všechna vozidla, všechny díly.","Náklady na domácí montáž stoupnou o jedenáct set dolarů na kus. Čtyři továrny odloží rozšíření. Oznámení je přitom ohromně populární přesně v těch městech, kde ty továrny stojí."],["Jen vozidla. Díly vyjmout.","Verze, kterou by skutečně napsal ekonom. Chrání montáž, šetří dodavatelský řetězec a je jen třetinově tak uspokojivá při hlasitém oznámení."],["Vyhrožovat jím osmnáct měsíců. Nikdy ho nezavést.","Vymůžete si čtyři ústupky od tří vlád kvůli clu, které nikdy fakticky neexistuje. Je to nejvýnosnější věc, kterou nikdy neuděláte."],["Uvalit clo jen na auta jedné konkrétní barvy.","Celní úřad má formálně rozhodovat o barvě laku. Čtyři dovozci auta do pár dnů přestříkají přímo v přístavu a výsledný celní sazebník má devadesát stran názvů odstínů."]]},"g-six-cities":{"t":"Šest měst","x":"Šest měst, šest guvernérů, čtyři z nich souhlas odmítli. Tarrant: „Šest zvládnu, pane. Šest není problém. Problém je sedmé. Vždycky existuje sedmé.“","c":[["Všech šest. Zároveň.","Logisticky to funguje a ve všem ostatním to selže. Do čtvrtého měsíce stojí nasazení tři sta třicet dva milionů dolarů a je souzeno v pěti odvolacích obvodech zároveň."],["Dvě města. Ta, která o to požádala.","Nasazení se souhlasem se ukáže jako nekontroverzní, účinné a v celostátním zpravodajství naprosto neviditelné."],["Žádné. Místo toho financovat místní sbory.","Miliarda dvě stě milionů dolarů do rozpočtů městské policie. Kriminalita klesne ve čtyřech z šesti měst během dvou let a každý zúčastněný starosta si přisvojí plnou zásluhu."],["Nasadit i do sedmého města, o kterém nikdo nemluvil.","Městečko s devíti tisíci obyvateli bez jakýchkoli nepokojů. Jeho starosta svolá tiskovou konferenci, aby se upřímně zeptal, co se to vlastně s jeho městem děje."]]},"g-stand-down":{"t":"Tichý ústup","x":"Čtyři soudy rozhodly proti vám a pátý je na programu. Duane připravil prohlášení o stažení, které popisuje nasazení jako splnění všech cílů. „Pane, tu větu nikdo neuvěří. Ale taky ji nikdo nebude soudně napadat.“","c":[["Stáhnout se. Prohlásit to za naprostý úspěch.","Vše skončí v úterý, ve dvouodstavcovém prohlášení. Je to nejlevnější odchod na stole a byl k dispozici celou dobu, což je ta nepříjemná část."],["Stáhnout se a jmenovitě obvinit soudy.","Ustupujete a útočíte zároveň, což si uchová základnu voličů a způsobí, že páté rozhodnutí, až přijde, bude podstatně tvrdší, než muselo být."],["Vystupňovat to až k pátému případu. Nezaváhat.","Prohrajete sedm ku dvěma, s většinovým stanoviskem citovaným ještě třicet let a doktrínou, která nakonec dostane jméno přesně po tomto případu."],["Stáhnout se a poslat jednotky ke správě parků.","Čtyři tisíce vojáků stráví léto opravou turistických stezek. Je to zdaleka nejoblíbenější věc, kterou celé nasazení kdy přineslo, a někdo vážně navrhne, ať je to trvalé."]]},"g-competitive":{"t":"Odborný termín","x":"Tři politologové zabývající se srovnávací politologií zveřejnili studii, podle níž země překročila jistou hranici. Dr. Weirová: „Ten výraz zní kompetitivní autoritářství, pane. Je to odborný termín. Má svůj kontrolní seznam. Většinu bodů splňujeme.“","c":[["Přijmout ten výraz za svůj. Nosit ho jako odznak. Prodávat na tom kšiltovky.","Proměna diagnózy v reklamní předmět ji pro vaše příznivce zneškodní a pro všechny ostatní potvrdí, což je výměna, kterou uděláte bez jediné vteřiny váhání."],["Pozvat si ty akademiky k sobě. Pohádat se s nimi.","Devadesát minut, oficiálně, proti třem badatelům, kteří přečetli víc historie než všichni ostatní v budově dohromady. Prohrajete, viditelně, a nějakým způsobem to vypadá lépe, než kdybyste vyhrál."],["Ignorovat to. Akademici se už mýlili.","To ano. Tentokrát se ale nemýlí, a kontrolní seznam je teď veřejný, takže srovnání si může udělat úplně kdokoli."],["Zeptat se, které body na seznamu vám ještě chybí.","Ptáte se upřímně. Zbývají čtyři body. Deborah vás sleduje, jak si je zapisujete, a celý týden pořádně nespí."]]},"g-anticipatory-two":{"t":"Univerzita","x":"Zkolabovala druhá univerzita, ještě dřív, než bylo skutečně zmrazeno jakékoli financování, ještě dřív, než byl odeslán jakýkoli dopis. Ollis: „Přečetli si, co se stalo té první, a udělali si matematiku. Nikdo z téhle budovy s nimi vůbec nemluvil.“","c":[["Zveřejnit to. Ať je ta matematika zjevná i ostatním.","Do roka se přizpůsobí dalších devět institucí, aniž by je kdy kdokoli kontaktoval. Je to nejlevnější existující moc a nevyžaduje ani prstem hnout."],["Neříkat nic. Ať se to dál děje potichu.","Neviditelná poslušnost má větší cenu než viditelná poslušnost, protože nezbývá nic, na co by mohl kdokoli namířit kameru."],["Veřejně jim říct, že to nebylo nutné.","Jedna ze dvou to do čtrnácti dnů vezme zpět. Ta druhá ne, a její rektor soukromě přizná, že si už netroufá zkoušet obrat."],["Poslat jim dodatečně formální žádost.","Formální požadavek na ústupky, které už udělaly. Je podán, zodpovězen a podruhé splněn, a nikdo ze zúčastněných nedokáže vysvětlit proč."]]},"g-officers-pardon":{"t":"Dva policisté","x":"Dva policisté odsouzení za honičku, při níž zemřel muž. Bo má záznam z procesu. „Odsouzení je v pořádku, pane. Tresty jsou diskutabilně přísné. To jsou dva různé argumenty a jen jeden z nich vede k milosti.“","c":[["Plná milost. Oběma. Oznámit to na policejní akci.","Rodina se to dozví z vysílání, stejně jako všichni ostatní. Čtyři policejní odbory vás do měsíce podpoří, ale město, kterému ti policisté sloužili, ne."],["Zmírnit tresty. Odsouzení ponechat.","Užší krok, a ten, který skutečně řeší ten opravdový argument. Koupí vám polovinu uznání za desetinu hněvu."],["Nic. Slyšela to porota, ne vy.","Správná odpověď, a stojí vás čtyři body u voličů, kteří žádnému prezidentovi nikdy neodpustili užití právě téhle pravomoci."],["Udělit milost a jmenovat je do kontrolní komise.","Dva muži omilostnění za zavinění smrti teď sedí přímo v komisi, která má případy úmrtí vyšetřovat. Jmenování je zákonné, ironie nekomentovaná a čtyři členové na místě rezignují."]]},"g-vacancies-act":{"t":"Vše ve funkci pověřením","x":"„Jedenáct vysokých postů, všechny obsazené pověřenými úředníky. Zákon stanovuje strop na to, jak dlouho to smí trvat.“ Sy pokrčí rameny. „Náprava za porušení stropu spočívá v tom, že jejich rozhodnutí jsou neplatná. Nikdo ještě nikdy nepožádal soud, aby zneplatnil čtyři roky činnosti úřadu.“","c":[["Řídit celou vládu pomocí pověřených úředníků.","Náprava, kterou se nikdo neodváží uplatnit, není fakticky žádná náprava. Jedenáct úřadů čtyři roky řídí lidé, které Senát nikdy neviděl, a argument o neplatnosti se nikdy neotestuje."],["Nechat potvrdit ty čtyři, na kterých záleží. Zbytek nechat na pověření.","Čtyři potvrzení vám dají legitimitu, sedm pověřených vám dá rychlost. Je to verze, která přežije kontakt se skutečným slyšením."],["Nominovat na všech jedenáct. Vydržet potvrzovací boje.","Trvá to čtrnáct měsíců a dva boje prohrajete. Těch devět, kdo projdou, nemůže váš nástupce odvolat jediným telefonátem."],["Jmenovat jednu osobu na všech jedenáct postů.","Je mimořádně schopná a čtyři měsíce pracuje devatenáct hodin denně, než vám dopisem oznámí, že tohle prostě nikdy nemohlo fungovat."]]},"g-inspector-report":{"t":"Zpráva, kterou nikdo nečte","x":"Soudce rozhodl, že odvolání byla nezákonná, ale odmítl kohokoli vrátit do funkce s odůvodněním, že byste to prostě zopakoval s řádným oznámením. Miriam: „Bylo shledáno, že jste porušil zákon, pane, a přesto jste si výsledek udržel.“","c":[["Citovat rozhodnutí jako své ospravedlnění.","Rozsudek proti vám, který nezmění vůbec nic, což se výhře natolik podobá, že to vyřčené nahlas funguje zhruba na čtyřicet procent země."],["Vyhovět zpětně. Vydat oznámení. Znovu je propustit.","Třicet dní papírování přinese naprosto stejný výsledek, tentokrát zcela zákonně. Postup nikdy nebyl skutečnou překážkou, a teď je to oficiálně zaznamenáno."],["Vrátit je do funkce a nechat je dokončit mandát.","Vrátí se jedenáct ze sedmnácti. Čtyři z jejich následných zpráv vám velmi uškodí, ale dvě vás naopak zachrání před něčím podstatně horším."],["Podat odvolání proti rozhodnutí, které jste už vyhrál.","Vaši vlastní právníci stráví devět týdnů vysvětlováním, že se už nemá proti čemu odvolávat. Přesto jim nařídíte odvolání podat a do čtyř dnů je zamítnuto jako bezpředmětné."]]},"g-schedule-numbers":{"t":"Dva miliony jmen","x":"„Nabídka šla na každého federálního zaměstnance. Dva a čtvrt miliónu lidí. Rezignujte teď, plat vám poteče až do září.“ Deborah má čísla o zájmu. „Sedmdesát sedm tisíc přijalo, pane. A jsou to přesně ti, o které jsme si mohli nejméně dovolit přijít.“","c":[["Zopakovat to. Ve větším. Přilepšit si na tom.","Dalších šedesát tisíc odejde. Lidé, kteří mají kam jít, odcházejí vždy první, což znamená, že s každým kolem je zbývající pracovní síla menší, slabší a poslušnější."],["Nabídku uzavřít. Ponechat si ty, kdo zůstali.","Krvácení se zastaví na sedmdesáti sedmi tisících. Úřad pro personální řízení odhaduje náklady na náhradu na devět miliard dolarů za šest let, a ten odhad si nikdo nepřečte."],["Zacílit to. Nabídnout to jen tam, kde chcete snížit počty.","Přesnost místo brokovnice. Dosáhne se stejného snížení stavů přesně tam, kde jste chtěl, a řídící letového provozu zůstanou."],["Nabídnout to sám sobě a sledovat, co se stane.","Formulář nemá kolonku pro vaši pozici. Referentka na personálním stráví čtyři dny pokusy o zpracování, než to konečně předá právnímu oddělení."]]},"g-doge-cuts":{"t":"Číslo na obrazovce","x":"Vandermeer provozuje na webu živý čítač, který tvrdí, že se ušetřilo dvě stě čtrnáct miliard dolarů. Lyle prověřil jedenáct největších položek. „Čtyři jsou započítané dvakrát, tři jsou smlouvy, které už stejně vypršely, a jedna je chybná o faktor tisíc.“","c":[["Nechat čítač být. Zaokrouhlit nahoru.","Číslo do jara dosáhne tří set miliard. Každý novinář, který si to ověří, najde stejné chyby, a každá oprava se dostane zhruba k čtyřicetině původního publika."],["Zveřejnit metodiku. Nechat si to ověřit.","Ověřená částka činí devatenáct miliard dolarů, skutečně obrovská suma, kterou nikdo neocení, protože to není dvě stě čtrnáct miliard."],["Tiše čítač stáhnout.","Do hodiny ho archivují čtyři nezávislé služby, stejně jako všechno ostatní, navždycky."],["Přidat čítač peněz utracených za hledání těch úspor.","Druhý čítač předežene první do jedenácti týdnů. Vandermeer tiše odstraní oba a zveřejní graf o něčem úplně jiném."]]},"g-final-audit":{"t":"Dlouhý součet","x":"Dr. Weirová má sečteno: sedm set padesát tři samostatných žalob proti vaší administrativě. „Pro srovnání, pane, je to víc než u čtyř předchozích prezidentských období dohromady. Nekomentuji to. Jenom počítám.“","c":[["Zarámovat to. Dokazuje to, o kolik věcí jste se pokusil.","Dáte to číslo na plakát. Je to skutečně důkaz ambice, a zároveň důkaz všeho, co tvrdí druhá strana, a oba výklady citují přesně stejné číslo."],["Zeptat se, které jste prohrál a proč.","Prohrál jste čtyřicet jedna procent ve věci samé, převážně kvůli procesním chybám, nikoli kvůli obsahu. Čtyři vaše zbývající politiky se ten samý měsíc přepracují a všechny čtyři obstojí."],["Říct, že to číslo dokazuje politickou zaujatost soudů.","Šedesát jedna procent rozsudků proti vám napsali soudci jmenovaní vaší vlastní stranou. Dr. Weirová má i tohle číslo, nabízí vám ho, a vy je odmítnete přijmout."],["Požádat ji, ať počítá dál i po vašem odchodu.","Udělá to. Závěrečný svazek má devět set stran, vychází v roce 2044 a je, bez zjevné ironie, věnován vám."]]},"h-tariff-boomerang":{"t":"Bumerang","x":"Lyle má seznam odvetných opatření. „Odpověděli nám položku za položkou, pane, a pak přidali bourbon, motorky a jednu konkrétní značku lodí. Všechno se vyrábí ve státech, které jste vyhrál. Musím uznat, že je to nádherně zacílené.“","c":[["Zdvojnásobit clo. Nikdo nás nepřetvrdí.","Eskalace nadchne shromáždění a vyprázdní přístaviště pro jachty. Obojí platí zároveň a základna vidí jen to shromáždění."],["Tiše vyjmout lodě z výjimky. Řeč nechat tvrdou.","Výjimka se zahrabe do páteční podacího spisu, zatímco tvrdá slova zůstávají v televizi. Je to celá práce, odvedená dobře, a nikým neviděná."],["Svalit clo na lodě na minulou administrativu.","Clo na lodě, které jste zavinil vy, přisoudíte prezidentovi, který odešel před lety. Zhruba polovina země to okamžitě přijme za své."],["Prohlásit bourbon za strategickou národní rezervu.","Prezidentský dekret označí whisky za záležitost národní bezpečnosti. Čtyři lihovary jsou nadšené a jeden čtyřhvězdičkový generál se upřímně ptá, jaká je vlastně jeho role."]]},"h-summit-selfie":{"t":"Fotka z podání ruky","x":"Muriel drží dvě fotografie. „Tohle je to podání rukou, pane. Čtyřicet milionů zhlédnutí. A tohle je skutečné komuniké. Zavazuje nás k pracovní skupině, která se sejde nejdřív příští jaro. Základna viděla tu první. Senát si přečetl tu druhou.“","c":[["Prodávat to podání rukou. Pracovní skupinu zahrabat.","Fotka se v praktickém smyslu stává celou politikou. Nic není dohodnuto a přitom má každý pocit, že se dohodlo něco obrovského."],["Nechat Muriel věcně vysvětlit skutečné podmínky.","Pravda je malá, reálná a nudná, a tak se také referuje. Fotka podání rukou přesto záhadně dál trenduje."],["Oznámit druhý summit, na kterém se proberou výsledky prvního.","Summit o summitu. Plánovací kancelář pláče. Základna se nemůže dočkat."],["Nechat to podání rukou odlít do bronzu do foyer.","Sochař vytvoří stisk rukou v životní velikosti přímo v hale Západního křídla. Návštěvníci nevědí, jestli si mají potřást. Někteří to udělají."]]},"h-late-call":{"t":"Telefonát ve dvě ráno","x":"Deborah to zachytila v deníku hovorů. „Zavolal jste vůdci spřátelené země ve dvě ráno jejich času, pane, abyste mu řekl, jak úžasně vypadá nový plesový sál. Spal. Hovor trval devatenáct minut. Většinu z toho jste mluvil vy.“","c":[["Zítra to zopakovat. Líbilo se jim to.","Zavedete si noční zvyk nevyžádaně informovat spící hlavy států o architektuře. Dvě z nich to začnou nechávat spadnout do hlasové schránky."],["Nechat každý hovor projít nejdřív přes Deborah.","Mezi vás a telefon ve tři ráno se nainstaluje filtr. Je to zdaleka nejcennější personální rozhodnutí celého funkčního období."],["Popřít hovor. Svalit to na časová pásma.","Tvrdíte, že jste se spletl v hodinách. V deníku je časové razítko. Slovo „časové razítko“ vám zkazí celé ráno."],["Ten příští vysílat živě.","Dva miliony lidí sledují, jak viditelně vyčerpanému premiérovi popisujete stropní lišty. Je to nějakým způsobem vaše nejsledovanější vysílání roku."]]},"h-parade-itch":{"t":"Svrbění","x":"Generál Tarrant stojí v pohovu, což u něj znamená jistý druh hrůzy. „Ptal jste se mě tento týden třikrát, k čemu vlastně armáda *je*, pane, když ji nikdy nepoužíváme. Chci mít jasno v tom, že tohle není otázka, se kterou bych se cítil dobře, když ji prezident klade v klidné úterý.“","c":[["Nařídit přehlídku. Největší, jaká kdy byla. Tento víkend.","Bulvár nebyl nikdy stavěný na to, aby po něm jezdila obrněná technika. Fotky jsou velkolepé a inspektor mostů podává hlášení."],["Nic. Nechat generálovi jeho úterý.","Nenasazujete armádu z nudy. Tarrant viditelně omládne. Je to správné rozhodnutí a nikdo netleská."],["Místo toho přejmenovat vojenskou základnu po sobě.","Ceremonie, nová cedule, levnější druh slávy. Svrbění je poškrábané a nikdo kvůli tomu nemusí nikam vyrazit."],["Zřídit novou vojenskou složku pro vesmír.","Vznikne nová složka s logem, které do týdne napadne u soudu jedna streamovací franšíza. Nováčci jsou do jednoho nadšení."]]},"h-upkeep-bill":{"t":"Údržba","x":"Alvin předkládá účetní knihu s péčí muže, který něco zneškodňuje. „Jenom lustry v plesovém sále, pane. A horská dráha vyžaduje certifikovanou inspekci každých devadesát dní, což prý platí i pro horskou dráhu na střeše. Zejména, vlastně, pro horskou dráhu na střeše.“","c":[["Zaplatit to. Velkolepost není položka v rozpočtu.","Účty se zaplatí v plné výši a včas a budova se skví. Ministr financí vydá tichý zvuk a opustí místnost."],["Odložit inspekce. Co se může stát.","Zrušíte bezpečnostní certifikaci horské dráhy na střeše. Čtyři úřady otevřou spisy a jeden stážista se z principu odmítá svézt."],["Zavést vstupné do plesového sálu.","Dům lidu se krátce promění v prostor s vstupným. Historička rezignuje faxem, dokumentem, s nímž jí museli teprve vysvětlit, jak se odesílá."],["Přidat obchod se suvenýry. Pak ještě dva.","Po třech obchodech se suvenýry, stánku s churros a fotokoutku sídlo vykazuje měsíční zisk a památková komise dostává infarkt."]]},"h-merch-drop":{"t":"Nová kolekce merche","x":"Brayden se přímo chvěje nadšením. „Zlaté tenisky, pane. Pak parfém. Pak pamětní mince, pak Bible, pak mince *s* Biblí. Každá kolekce se vyprodá během minut. Základna to nekupuje s ironií. Kupují to tak, jak lidé kupují relikvie.“","c":[["Vypustit všechno. Nová věc každý týden.","Relikvie se množí a s nimi i oddanost. Jedna ekonomka to nazve kultem osobnosti s vynikající jednotkovou ekonomikou. Nemýlí se."],["Jedna vkusná věc. Výtěžek pro veterány.","Zdrženlivost a charitativní přesah. Tisk je krátce vlídný a základna se krátce nudí, a oba pocity do čtvrtka pominou."],["Dát svou tvář na skutečné bankovky.","Pokusíte se objevit na zákonném platidle. Mincovna vysvětlí, nejdřív jemně a pak důrazně, kolik zákonů se toho týká. Tenisky vám zůstanou."],["Spustit memecoin. $PATRIOT. Ještě dnes večer.","Vystřelí do výšin, zřítí se, do snídaně vystřelí znovu. Nějaký síťový nadšenec vydělá a prodělá jmění dřív, než vůbec začne brífink."]]},"h-injunction":{"t":"Celostátní soudní zákaz","x":"Sy pokládá usnesení na stůl. „Jeden soudce, pane. V jedné soudní síni, ve státě, kde jste prohrál o třicet bodů, to celé zmrazil na celostátní úrovni. Máte na výběr, buď se slušně odvolat, nebo o tom soudci říct něco, za co se pak budeme měsíc omlouvat.“","c":[["Jmenovat soudce. Zpochybňovat soudce. Každý večer.","Z okresního soudce uděláte celostátně známé jméno a terč. Soudnictví se semkne, jako tělo, které obklopí třísku."],["Odvolat se. Přímo, rychle, nudně.","Právníci si potichu a dobře dělají svou práci. Věc postupuje výše po žebříčku na základě podstaty a základna se nikdy nedozví slovo „odklad“."],["Ignorovat usnesení. Pokračovat i tak.","Chováte se, jako by soudní příkaz byl jen doporučení. Je to zdaleka nejrychlejší způsob, jak naučit národ, jak vypadá ústavní krize."],["Jmenovat soudce někam jinam. Hodně daleko.","Pokusíte se svůj problém povýšit na velvyslanecký post v chladné zemi. Soudce to nádherně písemně odmítne a odmítnutí unikne na veřejnost."]]},"h-leak-hunt":{"t":"Hon na uniklou informaci","x":"Ředitelka Quistová je věcná. „Detail, který unikl, mohl pocházet jenom od jednoho ze šesti lidí v té místnosti, pane. Všech šest je loajálních. V tom je ten problém, únik pramení z loajality. Někdo si myslí, že vás chrání tím, že vás vykreslí jako rozhodného. Není to tak.“","c":[["Otestovat všech šest na detektoru lži. Ještě dnes.","Napojíte své nejbližší poradce na přístroj se spornou spolehlivostí. Nikdo neselže a všichni si to zapamatují. Příští únik se týká právě těch testů."],["Nechat to být. Utěsnit to potichu později.","Odmítnete hon na čarodějnice a místo toho opravíte samotný proces. Je to zralé, účinné a naprosto neviditelné, jako všechno, co skutečně funguje."],["Nechat uniknout něco horšího o soupeři, aby se to přikrylo.","Provedete protiúnik. Příběh, který jste chtěl pohřbít, se pohřbí pod příběhem, ze kterého se budete zodpovídat za šest týdnů. Vždycky se to tak stane."],["Nastražit novináři falešný detail jako past.","Vysadíte návnadu. Otiskne se. Teď jste existenci úniku potvrdil tím, že jste jeden sám vytvořil, což i Quistové připadá filozoficky znepokojivé."]]},"h-loyalty-oath":{"t":"Přísaha věrnosti","x":"Deborah je opatrná. „Nápad, který teď koluje, pane, je podepsaný slib. Osobní věrnost, písemně, nad rámec přísahy, kterou už složili úřadu. Někteří to podepíší, aniž by mrkli okem. Ti, které si stojí za to udržet, rezignují ve chvíli, kdy o to požádáte.“","c":[["Rozeslat slib. Sledovat, kdo se zarazí.","Schopní odejdou a poslušní zůstanou a průměrné IQ budovy měřitelně klesne. Základna tomu říká vypouštění bažiny."],["Žádný slib. Přísaha úřadu je jediná přísaha.","Odmítnete se v podepsaném dokumentu postavit nad Ústavu. Historikové to za desítky let budou shledávat naprosto nepozoruhodným, což je přesně ten smysl."],["Nechat je přísahat vlajce. Stejná podstata, lepší vzhled.","Vlastenecký rebranding stejného požadavku. Skvěle to vypadá na fotkách a znamená to přesně to, co si každý myslí."],["Nechat je přísahat na novou pamětní Bibli.","Přísaha věrnosti zároveň slouží jako product placement. Pastor je nadšený, právníci ne, a Bible se dočká dalšího dotisku."]]},"h-bad-poll":{"t":"Špatný průzkum","x":"Nadia to neomáčkuje. „Je to skutečný průzkum, pane, se skutečnou metodikou, a číslo je špatné. Můžete zaútočit na agenturu, což funguje jen na základnu, a jenom na ni, nebo se můžete podívat, proč je to číslo špatné, což v téhle budově nedělá rád nikdo.“","c":[["Prohlásit průzkum za podvrh. Citovat vlastní, lepší.","Vytvoříte interní průzkum se vzorkem lidí, kteří s vámi už tak jako tak souhlasí. Základna to okamžitě přijme a realita se ani nehne."],["Prostudovat podrobná data. Změnit jednu politiku.","Necháte data ovlivnit rozhodnutí. Je to nejméně dramatická věc, kterou může vůdce udělat, a zároveň jedna z nejvzácnějších, a potichu to pohne se skutečným číslem."],["Objednat deset průzkumů, dokud jeden nevyjde dobře.","Kupujete si pokusy, dokud si nekoupíte vítěze, a pak citujete jen toho vítěze. Je to drahé, průhledné a naprosto účinné na vlastní straně."],["Udělat průzkum, jestli lidé věří průzkumům.","Průzkum o průzkumech přinese výsledek natolik rekurzivní, že ho nikdo nedokáže vyložit. Dva komentátoři si na té nejednoznačnosti postaví celou kariéru."]]},"h-deepfake":{"t":"Přesvědčivý padělek","x":"Kaylee je bledá. „Není to skutečné, pane. Video s vámi je zfalšované od začátku do konce, a je bezchybné. Problém je ten druhořadý: teď, když všichni vědí, že takhle dobré padělky existují, můžete cokoli skutečného prohlásit za padělek, a cokoli padělaného za skutečné. Přišli jsme o schopnost si být čímkoli jistí, a stejně tak úplně všichni ostatní.“","c":[["Prohlašovat každý nelichotivý klip navždy za padělek.","Nástroj si přisvojíte jako trvalé alibi. Pravda se stává otázkou loajality, což je chvíli nesmírně výhodné a pak už ne."],["Podpořit skutečný ověřovací standard. Nudné. Zásadní.","Podpoříte nudný technický rámec pro ověřování záznamů. Je to nejdůležitější věc, kterou celý rok uděláte, a je pokrytá na devatenácté straně."],["Vypustit vlastní padělek, s vaším soupeřem.","Schválně eskalujete do světa, kde se nedá věřit ničemu, protože mlha nahrává tomu, kdo je nejhlasitější. Zatím to nahrává vám, dokud nepřestane."],["Nasadit umělou inteligenci, která vyvrací padělky vaším hlasem.","Syntetická verze vás ověřuje fakta o syntetické verzi vás. Někde katedra filozofie zruší vlastní konferenci, jen aby se na to mohla dívat."]]},"h-nobel-itch":{"t":"Cena","x":"Muriel šlape opatrně. „Výbor nepřijímá nominace od nominovaného, pane. Zvlášť nepřijímá těch sedm, které jste podal sám na sebe. Existuje mír, který byste skutečně mohl zprostředkovat a který by si ji časem mohl zasloužit. Vyžadovalo by to, abyste nechal stát u pódia někoho jiného.“","c":[["Nominovat se znovu sám. Hlasitěji.","Osmá vlastní nominace se podává s tiskovou zprávou. Výbor, který už viděl všechno, tohle ještě úplně neviděl, a mlčí, draze."],["Zprostředkovat to skutečné. Nechat vyniknout vyslance.","Odvedete trpělivou práci skutečné diplomacie, kdy se o zásluhy dělíte. Za pár let by to dokonce mohlo vynést tu cenu, což je přesně důvod, proč je to teď tak těžké."],["Založit si vlastní cenu. Udělit ji sám sobě.","Nová medaile, nový výbor, předem daný výsledek. Základnu to dojímá. Ten starý výbor zůstává, výmluvně, v Oslu."],["Prohlásit, že jste ji tajně už vyhrál.","Oznámíte utajenou cenu, kterou nelze ověřit z důvodů národní bezpečnosti. Zhruba třetina země si to zařadí pod „nejspíš pravda“."]]},"i-ukraine-war":{"t":"Čí je to vlastně válka","x":"Muriel rozprostírá mapu. „Rusko se dál zakusuje do Ukrajiny, pane, a všichni v té místnosti chtějí vědět, kde stojíte. Základna chce, ať peníze přestanou téct. Spojenci chtějí, ať dál tečou. Prezident Volkov chce telefonát. Cokoli řeknete v příští hodině, se stane politikou.“","c":[["Podpořit Ukrajinu. Ozbrojit ji, nahlas.","V přímém přenosu se postavíte za Kyjev. Aliance je nadšená, základna se nudí a faktury jsou obrovské."],["Místo toho uzavřít dohodu s Volkovem.","Přeskočíte spojence a zavoláte přímo agresorovi. Dohodne se „rámec“, u jehož vzniku nikdo jiný nebyl. Základna miluje silného muže, který zvedá váš telefon."],["Zprostředkovat mír. Přivlastnit si zásluhu.","Prohlásíte se za jediného muže, který to dokáže ukončit. Naplánuje se summit. Nic se nepodepíše, ale slovo „Nobelova cena“ zazní nahlas, z vašich úst."],["Odejít od stolu. Není to náš kontinent.","Prohlásíte to za evropský problém a odejdete. Základna oslavuje tu šetrnost. Tři hlavní města si potichu začnou zařizovat vlastní ujednání."]]},"i-taiwan":{"t":"Ostrov, který má každý na mysli","x":"Generál Tarrant má satelitní záběry. „Předseda Čen provádí kolem ostrova dosud největší cvičení, pane. Je to generálka a chce, abychom věděli, že je to generálka. Můžeme proplout úžinou s letadlovou lodí, nebo si najít něco naléhavého jinde. Obojí si všimnou.“","c":[["Proplout úžinou. Pomalu.","Sto tisíc tun šedé oceli si vezme malebnou trasu úžinou. Nic se nestane, draze a schválně."],["Prodat Tchaj-wanu úplně vše z katalogu.","Ozbrojíte ostrov po zuby a naúčtujete mu to jako výsadu. Peking zuří, vaši zbrojní dodavatelé po vás pojmenují celé křídlo budovy."],["Ujistit Čena, že je to „jedna země“, a zavěsit.","Vyslovíte přesně tu frázi, kterou chtěl slyšet, a ukončíte hovor. Obchodní oddělení si oddechne. Tchaj-pej si přepis přečte dvakrát."],["Zveřejnit mapu na sítích. Ať si domýšlejí.","Zveřejníte mapu bez jakéhokoli popisku. Šest vlád svolá mimořádná jednání, aby ji vyložily. Nic tím nemyslel. Málokdy myslíte."]]},"i-iran-enrich":{"t":"Centrifugy","x":"Šéfka rozvědky udržuje hlas bez emocí. „Írán je blízko, pane. Naši lidé odhadují dva týdny od prahu. Můžeme udeřit na zařízení a zpozdit je o tři roky, můžeme je uškrtit sankcemi, nebo jim nabídnout dohodu, kterou nezvládli poslední tři prezidenti. Každá možnost vám udělá dva přátele a jednoho nepřítele.“","c":[["Udeřit na zařízení. Ještě dnes v noci.","Do svítání je ze zařízení sutina a do poledne je z regionu sud s prachem. Základna tomu říká síla. Zálivové státy volají svým aeroliniím."],["Uvalit sankce, ať se vrátí do doby kamenné.","Odříznete je od všeho, co má v sobě drát. Jejich ekonomika se hroutí, jejich program ne. Je to pomalé, popíratelné a nekonečné."],["Uzavřít dohodu, kterou nikdo jiný nedokázal.","Podepíšete dohodu, kterou nezvládli poslední tři prezidenti, a vyzýváte kohokoli, ať to nazve slabostí. Polovina to udělá okamžitě."],["Prodat to oběma stranám. Potichu.","Nějakým způsobem mění majitele jmění a Teherán i jeho nepřátelé věří, že stojíte při nich. Čtyři etické komise otevřou spis přímo během podpisu."]]},"i-nato-dues":{"t":"Poslat fakturu","x":"Muriel má zasedací pořádek. „Jsou tu všichni, pane, a všichni jsou nervózní, přesně tak, jak je má základna ráda. Můžete znovu potvrdit závazek je bránit, můžete je nejdřív donutit zaplatit, nebo můžete jen naznačit, čistě naznačit, že celé to ujednání je volitelné. Už samotný náznak hýbe trhy.“","c":[["Znovu potvrdit závazek. Pevně. Nudně.","Řeknete, že smlouva znamená přesně to, co říká. Spojenci spí, základna zívá, nikdo o Pátém článku nesloží píseň."],["„Nejdřív zaplaťte svůj podíl, pak si promluvíme.“","Z obranného paktu uděláte v přímém přenosu fakturu. Dvě vlády náhle oznámí nové výdaje. Základna zbožňuje muže, který nechá přátele platit."],["Naznačit, že je to celé dobrovolné.","Nahlas se pozastavíte, jestli byste se vlastně skutečně dostavil. Náznak je celá politika. Někde menší země potichu spouští vlastní jaderný program."]]},"i-arctic":{"t":"Vršek mapy","x":"Lyle má mapu, kde je teď z větší části modře tam, kde bývalo bílo. „Arktida se otevírá, pane. Pod tím ledem je století vzácných zemin a plavební trasa v hodnotě HDP celé země. Rusko zapíchlo vlajku do mořského dna. Grónsko, ehm, technicky vzato není na prodej. Všichni jsou nesmírně zdvořilí a kupují ledoborce.“","c":[["Nabídnout Grónsku nabídku, kterou nemůže odmítnout.","Na stůl položíte číslo za ostrov, který stále opakuje, že není na prodej. Základna je nadšená. Kartografové zatím nic neaktualizují."],["Zaválčit s Ruskem o mořské dno. Postavit ledoborce.","Zadáte flotilu, jejíž prací je drtit led. Je to drahé, je to pomalé a je to, upřímně, skutečná strategie."],["Rozdělit si polární oblast s Volkovem.","Vy a Volkov si potichu rozdělíte oceán, který nepatří ani jednomu z vás. Mapa se překreslí u večeře. Šest dalších arktických států se to dozví až později z novin."]]},"i-coup":{"t":"Muž na balkoně","x":"Šéfka rozvědky má noční depeše. „Došlo k převratu, pane, v zemi, kterou potřebujeme kvůli naší tamní základně. Nový muž stojí na balkoně, má na sobě spoustu medailí a tvrdí, že je vaším velkým obdivovatelem. Stará vláda se z neznámého místa ptá, jestli ji ještě uznáváme.“","c":[["Uznat generála. Obdivuje vás.","Jste první, kdo tomu balkónu poblahopřeje. Základna má ráda muže, kterému se líbíte. Tři demokracie potichu sníží úroveň svých velvyslanectví."],["Odsoudit to. Požadovat volby.","Uděláte na principu tu správnou, nudnou věc. Základnu to nedojme a personál na vaší zahraniční základně je nervózní. Historie kývne a jde dál."],["Neříkat nic, dokud neuvidíte průzkumy.","Počkáte, kterým směrem se to ustálí, než se zavážete k nějakému názoru. Je to cynické, je to bezpečné a podle všech důkazů je to zavedený styl domu."]]},"i-trade-bloc":{"t":"Založili si klub","x":"Lyle drží tiskovou zprávu, ze které nemá radost. „Založili si blok, pane. Tucet zemí, které mezi sebou volně obchodují a, přímočaře, s námi ne. Je to přímá reakce na cla. Můžeme se tam vsoukat silou, můžeme si vybudovat vlastní soupeřící klub, nebo na to celé uvalit clo a sledovat, kdo zamrká první.“","c":[["Uvalit clo na celý blok najednou.","Ještě před obědem vyhlásíte hospodářskou válku dvanácti zemím. Základna je v euforii. Někde se prostě zastaví kontejnerová loď."],["Vybudovat soupeřící klub. Náš je větší.","Sestavíte vlastní obchodní blok, trváte na tom, že je lepší, a obsadíte ho kýmkoli, kdo se dostaví. Dva členové si nejsou jistí, proč byli pozváni."],["Vsoukat se zpátky silou. Spolknout pýchu.","Vyjednáte si potichu cestu zpátky do klubu, ze kterého jste byl vyloučen, u stolu blízko dveří. Ekonomika se zotaví. Základna se nedozví nic."]]},"i-scs-reef":{"t":"Útes s ranvejí","x":"Generál Tarrant má fotky před a po. „Byl to útes, pane. Teď je to letiště s útesem pod sebou. Čína ho postavila v plavební trase, kterou si nárokují ještě čtyři další země. Všechny čtyři se ptají, jestli Spojené státy hodlají skutečně něco udělat, nebo jenom mluvit.“","c":[["Proplout přímo kolem. Dvakrát.","Provedete plavbu za svobodu plavby dostatečně blízko na to, aby šlo přečíst tabulky. Nikdo nestřílí. Všichni to fotí. Vzkaz, jaký je, je vyřízen."],["Místo toho ozbrojit čtyři sousedy.","Ze čtyř nervózních sousedů uděláte čtyři ozbrojené sousedy a necháte zbytek na geografii. Peking podá stížnost, kterou si zarámujete a pověsíte na zeď."],["Vyměnit útes za lepší clo.","Potichu přestanete zmiňovat letiště výměnou za něco s dolarovým znakem. Čtyři spojenci si toho ticha všimnou. Stejně tak i ten útes."]]},"i-nk-missile":{"t":"Narozeninový start","x":"Generál Tarrant je téměř dojatý. „Nejvyšší vůdce odpálil další, pane. Naštěstí do moře, a zdá se, že přímo o svých vlastních narozeninách. Je to vzkaz, a ten vzkaz zní, že by rád, abyste o něm něco řekl. Vždycky by rád. Máte jeho číslo.“","c":[["Zavolat mu. Pochválit raketu.","Zavoláte do poustevnického království a pochválíte řemeslné zpracování. Je nadšený. Oba se shodnete, že jste teď velmi dobří přátelé. Ministerstvo zahraničí si jde lehnout."],["Oheň a zuřivost. Stará klasika.","Ráno vyhrožujete totální zkázou a do oběda na to zapomenete. On odpálí další, aby na sebe upoutal pozornost. Je to funkční vztah."],["Úplně ho ignorovat. Zabíjí ho to.","Neřeknete vůbec nic, což je jediná věc, kterou nedokáže snést. Další raketa je větší a ještě zjevněji adresovaná vám."]]},"i-hostages":{"t":"Ti, které drží","x":"Muriel je u tohohle opatrná. „Drží naše lidi, pane, tři z nich, na základě obvinění, kterým nikdo nevěří. Chtějí výměnu: svého vězně, nebo hromadu peněz, nebo fotku, jak si potřásáte rukou s mužem, kterého jste nazval monstrem. Rodiny jsou dnes večer v televizi tak jako tak.“","c":[["Provést výměnu. Přivést je domů.","Zaplatíte výkupné, kterému nikdo neřekne výkupné, a tři občané přejdou po ranveji přímo do kamer. Je to dobrý den a hrozný precedens."],["Odmítnout. Nevyjednáváme.","Z principu se držíte pevně a rodiny svolají tiskovou konferenci. Základna respektuje páteř. Vyjednávání pokračuje, neoficiálně, navěky."],["Podat ruku. Mít tu fotku za sebou.","Před kamerou stisknete ruku muže, kterého jste nazval monstrem, a dostanete své lidi zpátky. Fotka přežije celé prezidentské období. Stejně tak i ti občané, což je celý smysl."]]},"i-cyber":{"t":"Ve třech státech zhasla světla","x":"Šéfka rozvědky ani nemrkne. „Někdo na devět hodin vypnul elektřinu ve třech státech, pane. Víme kdo. Dokážeme to sami sobě, ale ne úplně soudu. Můžeme jim to vrátit hackerským útokem, můžeme je sankcionovat, nebo to celé udržet potichu, aby se trhy nedozvěděly, jak snadné to bylo.“","c":[["Vrátit jim to hackerským útokem. Tvrději.","Na jejich straně světa něco zhasne a nikdo se k tomu nepřihlásí. Je to popíratelné, je to přiměřené a spouští to hodiny, které nikdo nevidí."],["Sankcionovat je za bílého dne.","Pojmenujete je, zostudíte je a zmrazíte, na co dosáhnete. Je to zákonná možnost a se světly to neudělá téměř nic."],["Zahrabat to. Trhy se to nesmí dozvědět.","Celou věc udržíte potichu a doufáte. Trhy se nikdy nedozví, jak tenký je ten led. Prozatím to nezjistí ani nikdo, kdo by to mohl opravit."]]},"i-refugees":{"t":"Kolona u hranic","x":"Duane má noční čísla. „Válka o dvě země dál poslala na cestu kolonu lidí, pane, a ta cesta končí u naší hranice. Základna chce zeď s vodním příkopem. Kostely chtějí přivítání. Kamery chtějí fotku, a jednu z těch dvou dostanou, podle toho, jak se rozhodnete.“","c":[["Uzavřít ji. Kamery, zeď, celé divadlo.","V přímém přenosu s maximálním divadlem uzavřete hranici. Základna jásá. Fotka, kterou kamery zachytí, je ta, na kterou se vás budou ptát navždy."],["Zpracovat je. Potichu, podle předpisů.","Uděláte tu zákonnou, logistickou, nefotogenickou věc. Funguje to a nic vám to nevynese. Základna slyší jenom to, že jste nepostavil ten příkop."],["Poslat je autobusem do státu soupeřícího guvernéra.","Naložíte problém do autobusu a pošlete ho někomu, kdo vás naštval. Je to kruté, je to divadlo a ve zpravodajství to vede přesně tak, jak jste doufal."]]},"i-nobel":{"t":"Telefonát z Osla","x":"Muriel tomu, co říká, sotva sama věří. „Tohle je skutečná šance, pane. Dvě vlády, které po sobě deset let střílejí, budou příští týden v jedné budově a obě zvednou váš telefon. Mohlo by to skutečně skončit. Mohlo by to taky, pokud to přeženete, zkolabovat přímo před kamerou. A ano, lidé už to slovo vyslovují.“","c":[["Odvést tichou diplomacii. Dotáhnout to.","Skloníte hlavu, čtrnáct dní pracujete na telefonech, a válka skutečně skončí. Je to nejlepší věc, kterou kdy uděláte, a trenduje to šest hodin."],["Oznámit cenu ještě před mírem.","Prohlásíte vítězství, a sám sebe laureátem, o pár klíčových dní předčasně. Jedna delegace odejde kvůli formulaci vašeho příspěvku na sítích. Válka se krátce obnoví."],["Nechat je podepsat ve vašem hotelu.","Mír vypukne v plesovém sále s vaším jménem nade dveřmi a příplatkem za pokojovou službu. Vydrží. Branding je, jak se všichni shodují, tím hlavním příběhem."]]},"j-acting-secretary":{"t":"Pověřený ministr","x":"Deborah má organizační schéma. „Ministerstvo vnitřní bezpečnosti je „pověřené“ jedenáct měsíců, pane. Stejně tak ministerstvo práce. Šetří vám to slyšení o potvrzení a znamená to, že člověka řídícího resort lze nahradit v úterý pouhou textovkou. Někteří se tak už začali představovat na večeřích.“","c":[["Nechat všechny ve funkci pověřením. Navždy, pokud to funguje.","Čtyři ministerstva fungují bez omezení bez potvrzeného vedoucího odpovědného komukoli jinému než vám. Organizační schéma se fakticky stává skupinovým chatem."],["Poslat skutečné nominace do Senátu. Ať to proběhne řádně.","Předložíte skutečná jména ke skutečnému hlasování. Je to pomalé, ústavní a naprosto nepozoruhodné, což je celý smysl toho cvičení."],["Udělat z „pověřeného“ trvalý titul. Vytisknout nové vizitky.","Vizitky teď mají napsáno „pověřený ministr“, bez hvězdičky a bez plánu to změnit. Personální oddělení se jednou zeptá, jestli je to legální. Odpověď nepřijde."],["Nechat stážisty hlasovat, kdo je pověřený tento týden.","Resort se čtyřmi sty zaměstnanci fakticky řídí ten, kdo vyhraje páteční anketu mezi stážisty. Morálka je, proti všem očekáváním, krátce vynikající."]]},"j-midnight-firing":{"t":"Půlnoční propuštění","x":"Brayden drží telefon, jako by mohl každou chvíli vybuchnout. „Ministr vnitřní bezpečnosti se o svém propuštění dozvěděl z push notifikace, pane. Stejně tak jeho šéf kabinetu. Stejně tak jeho žena, která byla zrovna na rozlučkovém obědě někoho jiného. Už jsem to zveřejnil. Měl jsem počkat?“","c":[["Zveřejnit i další tři propuštění stejně. Efektivní.","Propouštění formou notifikace se stává firemním stylem. Je to rychlé, je to kruté a nikdo v budově už nespí s telefonem obrazovkou dolů."],["Příště mu nejdřív zavolat. Nic to nestojí.","Necháte muže obvolat, než se zveřejní příspěvek. Je to naprosté minimum slušnosti a interně se to bere jako odvážná reforma."],["Propustit i hostitele toho rozlučkového obědu, kvůli optice.","Rozšíříte poloměr výbuchu na muže, jehož jediným proviněním bylo uspořádat oběd. Ten oběd byl, mimochodem, výborný."],["Nechat Alvina doručit tu zprávu s košíkem ovoce.","Hlavní komorník přichází s aranžmá z hrušek a zprávou zároveň. Ministr si nechá hrušky. Funkci si nenechá."]]},"j-loyalty-pageant":{"t":"Přehlídka loajality","x":"Chet si ve dveřích nacvičuje svou repliku. „Teď je to tradice, pane, jde se kolem stolu a každý ministr před kamerou řekne něco vděčného o vás, než začne schůze. Minulý týden ministr zemědělství použil slovo „požehnaný“ čtyřikrát. Nevěří v požehnání. Věří ve svůj důchod.“","c":[["Udělat to povinné. Bodovat je za upřímnost.","Zavedete hodnocenou poctu loajalitě na začátku každé schůze. Dva ministři si to začnou zkoušet v autě. Jeden se rozpláče, z nudy, ne z oddanosti."],["Zrušit ten segment. Začínat schůzi rovnou agendou.","Vynecháte poctu a začnete politikou. Místnost si tak slyšitelně oddechne, že to zachytí i mikrofony a musí se to vystřihnout z vysílání."],["Nechat je nahlas hodnotit lichotky toho druhého.","Kabinet dospělých lidí teď před kamerou vzájemně boduje svou vlastní podlézavost. Ministr vnitra dá generálnímu prokurátorovi šestku z deseti a myslí to jako urážku."],["Přeskočit pocty, místo toho přečíst místnosti báseň.","Přednesete čtyři sloky něčeho, co jste napsal v letadle, o vznešenosti veřejné služby. Nikdo netleská jako první. Nakonec zatleská každý."]]},"j-tweet-fired":{"t":"Vyhozený tweetem","x":"Kaylee vám čte návrh nahlas. „‚S okamžitou platností.‘ To je celý příspěvek, pane. Žádný telefonát, žádný dopis, žádných patnáct minut na důstojné sbalení stolu. Ministr je zrovna ve vzduchu a přistane, aby se to dozvěděl od letušky, která to, přiznejme si, zvládá lépe než my.“","c":[["Zveřejnit to teď. Načasování je součástí vzkazu.","Příspěvek jde ven, zatímco je ve vzduchu, přesně podle plánu. Krutost je fakticky celá strategie a základna to bere jako sílu."],["Počkat s příspěvkem, až letadlo přistane. Malé milosrdenství.","Odložíte veřejné ponížení o devadesát minut, aby se to muž dozvěděl na pevné zemi. Nic vás to nestojí a přitom to působí, jako by to bylo drahé gesto."],["Nechat Kaylee to napsat jako „poděkování za službu“.","Propuštění je zabalené jako vděk. Kdokoli v budově vidí za tu první větu. Nikdo to nahlas neřekne."],["Oznámit propuštění a za hodinu ho odvolat.","Otočíte, ještě než letadlo přistane, z důvodů, které nedokáže plně vysvětlit ani vy. Ministr si podrží funkci a velmi dobrou historku."]]},"j-cya-memo":{"t":"Zajišťovací memorandum","x":"Sy má složku, kterou viditelně nerad otevírá. „Tři ministři si vedou soukromé zápisy o každém vašem ústním pokynu, pane. S časovým razítkem. Není to přesně neloajálnost. Je to pojistka, a to vím, protože svoje jsem si začal vést v únoru.“","c":[["Vyžádat si ty zápisy. Přečíst každý. Osobně.","Zabavíte soukromou papírovou stopu, kterou si váš vlastní personál vedl na ochranu před vámi. Mrazivý efekt je okamžitý a nezmrazí to zápisky, jenom upřímnost v těch budoucích."],["Nechat je zápisky mít. Nemáte co skrývat.","Necháte existovat papírovou stopu vlastních rozhodnutí, nedotčenou. Je to buď naprostá jistota, nebo naprostá lhostejnost. Historie rozhodne, co z toho."],["Začít všechno diktovat přes právníka, oficiálně.","Každý pokyn teď prochází nejdřív právníkem, což je pomalejší, bezpečnější a vysává ze všeho radost."],["Napsat vlastní memorandum, které jim všem protiřečí.","Vytvoříte jediný konkurenční dokument, který tvrdí, že se všechno odehrálo jinak. Tři samostatná memoranda se teď neshodnou na stejném úterý, což je, jak podotýká Sy, svým způsobem taky pojistka."]]},"j-leaked-transcript":{"t":"Uniklý přepis","x":"Kaylee posouvá po stole výtisk. Půlka odstavce je zvýrazněná. „Někdo přepsal uzavřenou schůzi kabinetu, pane, doslova, včetně té části, kde jste ministrovi obchodu řekl „nábytek“. Za hodinu to jde do vysílání, pokud jim nedáme něco lepšího k odvysílání místo toho.“","c":[["Otestovat celý kabinet na detektoru lži. Nikdo neopustí místnost.","Zamknete tucet sedících ministrů do místnosti s přístrojem, dokud se někdo nepřizná. Nikdo se nepřizná. Všichni si zapamatují, kdo si to vyžádal."],["Přiznat to, omluvit se za tón, jít dál.","Přisvojíte si ten citát a ten okamžik zmizí za jeden zpravodajský cyklus místo tří. Je to nejlevnější možný odchod a málokdo ho vezme."],["Tvrdit, že přepis je zfalšovaný. Vyhrožovat médiu.","Nahlas popíráte pravdivou věc, dost hlasitě na to, aby to někteří lidé přijali za pravdu. Médium následující týden zveřejní audiozáznam, jen aby to bylo jasné."],["Zveřejnit vlastní „opravený“ přepis s lepšími vtipy.","Koluje upravená verze, v níž je vaše replika o ministrovi obchodu vtipnější, ale bohužel pořád rozpoznatelně stejnou urážkou."]]},"j-drawer-letter":{"t":"Dopis v zásuvce","x":"Deborah ho našla, když hledala sešívačku. „Ministr práce má ve své zásuvce podepsaný rezignační dopis už čtyři měsíce, pane. Datovaný, ale s prázdným dnem. Říká, že mu to pomáhá spát. Zjistila jsem si to. Šest dalších ho má taky.“","c":[["Vyžádat si každou zásuvku. Zabavit dopisy.","Nasbíráte sedm předepsaných rezignací jako trofeje. Nikoho to neudělá loajálnějším. Sedm lidí si napíše druhý, tentokrát skrytý."],["Nechat to být. Zásuvka není zločin.","Rozhodnete se, že mužova soukromá pojistka je jeho vlastní věc. Je to malé milosrdenství, které vás nic nestojí a nevynese vám žádné uznání."],["Vyžadovat, ať si všichni místo toho předepíšou přísahu věrnosti.","Nařídíte opačný dokument, trvalý slib místo trvalého odchodu. Budova teď má dvě zásuvky na stůl."],["Napsat vlastní rezignační dopis a nechat ho viditelně ležet.","Necháte na stole vlastní, datovaný a nepodepsaný dopis, na očích každému příchozímu. Nikdo se o tom nezmíní. Každý si ho přečte."]]},"j-cameras-in":{"t":"Kamery v místnosti","x":"Kaylee má harmonogram poolu. „Čtyřicet minut kamerového času, než se zavřou dveře, pane. Dost dlouho na monolog, ne dost dlouho na politiku. Každý v té místnosti teď odehraje prvních čtyřicet minut a skutečný rozpočet vyjedná až po odchodu kamer.“","c":[["Rozšířit to na celou schůzi. Plná transparentnost.","Každá schůze kabinetu se teď vysílá od začátku do konce. Nic podstatného se v místnosti už nerozhoduje, všechno se odehrává na chodbách potom, mimo záznam."],["Kamery zcela zrušit. Setkávat se jako dospělí.","Zavřete dveře a necháte kabinet skutečně vládnout v soukromí, po staru. Základně chybí to divadlo. Politika se mírně zlepší."],["Naskriptovat prvních čtyřicet minut. Nazkoušet to dvakrát.","Úvodní monolog se teď propracovává jako pilotní díl seriálu. Ve fokusní skupině to funguje skvěle a mizerně u kohokoli, kdo v té místnosti skutečně byl."],["Přivést zvukaře na pásmo smíchu pro potlesk.","Zvukový technik potichu vylepšuje potlesk na schůzích kabinetu pro vysílání. Nikdo v místnosti o to nepožádal. Nikdo v místnosti se ani neozve."]]},"j-praise-order":{"t":"Pořadí, v jakém se mluví","x":"Deborah má zasedací pořádek, který se mění každý týden. „Začal jste přeskupovat stůl podle toho, kdo vás nejvíc potěšil, pane. Ministr obchodu byl tento měsíc dvakrát degradován na vzdálený konec. Teď si už pro jistotu nosí vlastní jmenovku.“","c":[["Zveřejnit tabulku. Ať vidí, kde stojí.","Zveřejníte pořadí celé budově. Vznikne přesně ta úzkostná, soutěživá loajalita, kterou jste chtěl, a přesně ta zášť, kterou jste neplánoval."],["Vrátit se k abecednímu řazení. Nudné a spravedlivé.","Vrátíte stůl k abecednímu pořadí, čímž se celý žebříček ukončí. Obchod si podrží své místo. Jmenovku si teď nosí ze zvyku."],["Řadit je podle ukazatele, který nikdo nemůže zpochybnit, hlasitosti potlesku.","Decibelmetr se krátce stává nejdůležitějším přístrojem v Západním křídle. Ministr zemědělství, statný muž se silnými plícemi, stoupne o tři místa."],["Místo toho je řadit podle výšky. Nejčistší možné měřítko.","Vzdáte se zásluh i loajality ve prospěch krejčovského metru. Je to, jak si všichni potichu shodnou, nejspravedlivější systém, jaký kdy kabinet měl."]]},"j-cabinet-shuffle-photo":{"t":"Skupinová fotografie","x":"Kaylee má účet za tisk. „Tohle je čtvrtá oficiální fotka kabinetu letos, pane. Tři ministerstva mají od té poslední nové vedoucí. Tímto tempem odejde do důchodu rám dřív než celé prezidentské období.“","c":[["Zmrazit fotku. Noví nastupující budou od teď stát mimo záběr napořád.","Fluktuaci vyřešíte tak, že prostě přestanete aktualizovat záznam. Oficiální portrét teď zobrazuje kabinet, který technicky vzato už neexistuje."],["Přefotit to pořádně. Je to malý, poctivý náklad.","Zaplatíte za dalšího fotografa, další rám, další odpoledne mžourání do studiových světel. Je to nenápadné a je to přesné, což je vzácnější."],["Digitálně vlepit nové hlavy na staré postavy.","Mladý grafik dostane za úkol vyfotoshopovat tři nové obličeje na tři staré obleky. Osvětlení nesedí. Nikdo na fotce nestojí tam, kde se zdá, že stojí."],["Fotku přeskočit. Objednat skupinový portrét, olejomalbou.","Malíř dostane zakázku vypodobnit současný kabinet olejem, za značné náklady a značné zpoždění. Dva portrétovaní opustí administrativu dřív, než barva zaschne."]]},"j-revolving-door":{"t":"Otáčivé dveře","x":"Miriam má seznam, a je delší, než by měl být. „Šest bývalých ministrů teď lobbuje přesně u těch resortů, které dřív řídili, pane. Ochranná lhůta je oficiálně osmnáct měsíců. Dva z nich našli skulinu za osmnáct dní.“","c":[["Vyjmout loajální absolventy z ochranné lhůty.","Necháte svůj bývalý kabinet vejít přímo do lobbistických kanceláří resortů, které řídil. Je to legální, je to rychlé a je to nejčistší úplatek ve Washingtonu, protože ho nikdo nemusí tak nazvat."],["Vymáhat plných osmnáct měsíců. Bez výjimek.","Trváte na skutečném pravidle, což naštve několik lidí, kteří vám prokázali skutečné laskavosti. Je to správné rozhodnutí a stojí vás to dvě vánoční přání."],["Prodloužit zákaz na tři roky, pro každého kromě vás.","Zpřísníte pravidlo pro budoucí administrativy a zároveň potichu zachráníte výjimku pro ty současné. Vypadá to jako reforma. Funguje to jako skulina s delší platností."],["Najmout ty lobbisty zpátky jako „zvláštní poradce“. Technicky žádné lobbování.","Zavřete otáčivé dveře tím, že prostě všechny necháte uvnitř budovy, s novým titulem a stejným platem. Miriam sepíše memorandum. To memorandum je, samo o sobě, ignorováno."]]},"j-golden-parachute":{"t":"Zlatý padák","x":"Lyle má před sebou podmínky odstupného a nelíbí se mu. „Odcházející ministr energetiky chce na odchodu poradenskou smlouvu, pane. Dva roky, sedmimístná částka a titul se slovem „senior“. Odchází, řekl bych, za okolností blízkých skandálu.“","c":[["Schválit to. I loajalita na odchodu se počítá.","Zaplatíte muži štědře za to, že tiše odejde a na odchodu neřekne nic nelichotivého. Funguje to přesně tak, jak se slibovalo, což je samo o sobě svého druhu doznání."],["Zamítnout smlouvu. Standardní odchod, nic víc.","Vyprovodíte ho podáním ruky a ničím jiným. Je nešťastný. Rozpočet je nepatrně lépe na tom."],["Schválit to, ale skrýt tu částku do tří různých rozpočtových položek.","Poradenský honorář přežije, rozprostřený v rozpočtu, který nikdo nečte celý. Auditor to najde o jedenáct měsíců později a podá velmi zdvořilý dotaz."],["Nabídnout mu majáku místo peněz. Jeden je zrovna k dispozici.","Vyrovnáte sedmimístný spor vyřazeným federálním majákem na skalnatém, nepojistitelném úseku pobřeží. Přijme ho. Vypadá, upřímně, potěšeně."]]},"j-book-deal":{"t":"Odhalující paměti","x":"Sy drží nekorigovaný výtisk se zjevnou hrůzou. „Bývalý šéf kabinetu, ten před Deborah, chystá knihu, pane. Osmimístná záloha. Jmenuje se, a chci to citovat přesně, *V místnosti, kde se to nemělo stát*. Redigovaný výtisk dostaneme za tři týdny.“","c":[["Podat žalobu na zablokování vydání. Zdržet to u soudu.","Pokusíte se o předběžnou cenzuru memoárů, právní krok s nepřerušenou sérií proher. Žaloba knize zaručí bestsellerový žebříček, na který by sama možná nedosáhla."],["Nechat to vyjít. Na nic nereagovat.","Odmítnete knihu jakoukoli reakcí důstojnit. Šest týdnů se dobře prodává a v osmém je zapomenutá, což je správný výsledek."],["Objednat konkurenční odhalující knihu od někoho stále loajálního.","Konkurenční memoáry se narychlo tisknou od poradce, který stále slouží. Čtou se přesně tak autenticky, jak jsou, tedy ne moc."],["Vykoupit celý první náklad sám.","Koupíte celý první náklad, aby se nedostal do knihkupectví. Nadšený nakladatel objedná druhý náklad dvojnásobný. Osobně jste financoval pokračování."]]},"j-mole-hunt":{"t":"Hon na krtka","x":"Errol udržuje hlas vyrovnaný, což je samo o sobě druh varování. „Únik můžeme zúžit na devět lidí s přístupem, pane. Další zúžení znamená číst jejich soukromé telefony, což je legální zhruba u čtyř z nich a u zbytku je to trestný čin.“","c":[["Přečíst všech devět telefonů. Trestný čin řešit později.","Povolíte sledování vlastního kabinetu na základě právní teorie, která nepřežije kontakt se soudcem. Únikáře to nenajde. Najde to pět nesouvisejících poměrů."],["Zúžit to na ty čtyři, u kterých je to legálně možné.","Zůstanete uvnitř čtyř jmen, která zákon skutečně dovoluje. Je to pomalejší, je to řádné a je to verze tohoto příběhu, která pro vás nekončí předvoláním."],["Veřejně oznámit, že únikář byl identifikován. Blafovat.","Přiznáte se ke jménu, které nemáte, v naději, že skutečný únikář zpanikaří a přizná se. Místo toho tři nevinní zaměstnanci odejdou z čiré paranoie."],["Nakrmit každého z devíti mírně odlišným falešným detailem.","Klasická past s návnadou, devět variant do hloubky. Funguje to nádherně a zároveň to Errolovi k jeho tichému zděšení potvrdí, že přinejmenším tři z devíti nezávisle mluví s novináři."]]},"j-anonymous-oped":{"t":"Anonymní komentář","x":"Kaylee položí noviny na stůl, otevřené na příslušné stránce. „Někdo „vysoce postavený“ z této administrativy právě anonymně zveřejnil popis, jak tiše sabotuje vaše příkazy pro dobro země, pane. Je to dobře napsané. Horší je, že je to věrohodné skoro u kohokoli v této budově.“","c":[["Vyžadovat od každého člena kabinetu individuální popření na kameru.","Vynutíte čtrnáct popření během jednoho odpoledne. Třináct zní přesvědčivě. Jedno zní jako video s rukojmím a internet si toho okamžitě všimne."],["Ignorovat to. Esej bez podpisu nestojí za vysílací čas.","Odmítnete té historce dodat kyslík. Doběhne to za čtyři dny místo čtyř týdnů, což je celý trik ignorování věcí."],["Spustit rukopisnou a syntaktickou analýzu celého vyššího personálu.","Lingvistický dodavatel je placen za srovnávání rytmu vět napříč čtrnácti textovými vzorky. Výsledky jsou nejednoznačné a faktura dodavatele nikoli."],["Zveřejnit vlastní anonymní komentář, chválící sám sebe.","Objeví se nepodepsaná esej od „vysoce postaveného úředníka“, chválící vaše instinkty a vaše vlasy. Nikdo nevěří, že pochází zevnitř budovy. Pocházela."]]},"j-whistleblower-hotline":{"t":"Linka pro oznamovatele","x":"Miriam má seznam hovorů, a je tlustý. „Interní etická linka zaznamenala tento čtvrtrok dvě stě jedenáct hovorů, pane, téměř všechny se týkají stejných tří rozhodnutí. Zákon říká, že nesmíme volajícím oplácet. Neříká, že nemůžeme zjistit, kdo to je.“","c":[["Vysledovat každý hovor. Volající potichu přeřadit.","Identifikujete a odsunete stranou dvě stě zaměstnanců, kteří použili linku vytvořenou přímo na jejich ochranu. Je to učebnicová msta a spis o tom je dost tlustý na to, aby obstál sám o sobě u soudu."],["Linku nechat být. K tomu tady je.","Necháte chráněný oznamovací kanál dělat tu jedinou práci, kterou má. Je to strukturálně nejnudnější možná volba, a strukturálně ta správná."],["Přesměrovat budoucí hovory na anketu „spokojenosti zákazníků“.","Linka je potichu přejmenována a zbavená právní ochrany. Hovory pořád chodí. Teď fakticky nikam nevedou."],["Zvednout linku osobně na jedno odpoledne.","Osobně čtyřicet minut vyřizujete anonymní stížnosti na vlastní administrativu. Několik z nich je, soukromě přiznáváte, oprávněných."]]},"j-competing-memos":{"t":"Protichůdná memoranda","x":"Deborah má dvě memoranda, obě označená jako naléhavá, obě podepsaná vyšším personálem, tvrdící opak. „Úřad má tohle obojí na stejném stole právě teď, pane. Volali, aby se zeptali, pro kterou administrativu vlastně momentálně pracují.“","c":[["Nechat obě frakce, ať to vybojují. Vyhraje lepší memorandum.","Necháte dvě křídla vlastního personálu se poprat písemně, bez rozhodčího. Úřad tři týdny nedělá nic, což je po zvážení možná ta skutečná politika."],["Vybrat jedno memorandum, druhé zrušit, písemně.","Uděláte skutečné rozhodnutí a dáte ho na papír. Je to zdaleka nejužitečnější věc, kterou šéf kabinetu za celý měsíc udělá, a zabere to čtyři minuty."],["Vydat třetí memorandum, které protiřečí oběma prvním.","Přijde třetí dokument, souhlasící s ani jedním z předchozích. Úřad teď má tři stanoviska a nulovou politiku, seřazenou abecedně."],["Nechat obě frakce, ať se o to porvou v páce. Poražený píše omluvu.","Skutečný zápas v přetlačování rukou rozhodne živý meziresortní spor v Rooseveltově místnosti. Vítěz je viditelně v rozpacích z toho, jak dobře to zabralo."]]},"j-shadow-cabinet":{"t":"Stínový kabinet","x":"Deborah volí slova opatrně. „Teď existuje druhý kabinet, pane. Neoficiální. Žádné tituly, žádná potvrzovací slyšení, schází se v sídle poté, co ten skutečný jde domů. Polovina skutečných ministrů se mě už začala ptát, kdo vlastně řídí jejich vlastní resort.“","c":[["Formalizovat stínovou skupinu. Dát jí skutečnou pravomoc.","Zavedete nepotvrzený vnitřní kruh s větší skutečnou mocí než potvrzený kabinet. Je to rychlé, loajální a právně neobhájitelné, všechny tři věci naráz."],["Rozpustit ho. Jeden kabinet, potvrzený, odpovědný.","Pošlete poradce po hodinách domů a rozhodnutí vrátíte lidem, které skutečně prověřil Senát. Je to pomalejší. Je to taky, strukturálně, vláda."],["Ponechat oba, ale nikdy je nenechat se setkat.","Řídíte dva paralelní kabinety, formálně o sobě navzájem nevědomé, což vydrží přesně do chvíle, kdy jsou oba pozváni na stejný vánoční večírek."],["Sloučit je do jedné obří schůze. Ať si to vyřídí sami.","Šestadvacet lidí, kteří o sobě navzájem neměli vědět, sedí u stejného stolu. Schůze trvá čtyři hodiny. Nic se nerozhodne. Všichni se dozví všechno."]]},"j-unqualified-cousin":{"t":"Bratrancova pozice","x":"Miriam má životopis, a je krátký. „Bratranec vaší manželky byl jmenován náměstkem ministra energetiky, pane. Jeho dosavadní zkušenost je stánek se solárně nabíjenými telefony na krajském veletrhu. Nastupuje v pondělí. Dvakrát se zeptal, jestli k té práci patří i auto.“","c":[["Povýšit ho i na podnáměstka. Ať to zůstane v rodině.","Přidáte druhý rodinný titul do resortu, který zatím ani nenajde na mapě. Elektrická síť překvapivě dál funguje, hlavně díky setrvačnosti z doby před jeho příchodem."],["Dát mu titul bez skutečné pravomoci.","Dostane jmenovku, parkovací místo a portfolio, které se ničeho důležitého nedotýká. Je to poctivé řešení nepoctivého problému."],["Poslat ho tam, kde napáchá méně škody. Velvyslancem na malý ostrov.","Je vyslán do národa s jedenácti tisíci obyvateli, s nádherným klimatem a bez jakékoli elektrické sítě, kterou by mohl rozbít. Posílá pohlednice."],["Nechat ho měsíc stínovat komorníka Alvina.","Náměstek ministra energetiky stráví čtyři týdny učením se skládat ubrousky a hledáním vypínačů, než se dotkne jakéhokoli skutečného spisu. Prý je v ubrouscích výtečný."]]},"j-purity-test":{"t":"Test čistoty","x":"Deborah má tabulku starých tweetů a komentářů. „Prověřování teď zahrnuje kompletní prohledání všeho, co kdy nominovaný o vás řekl, pane, deset let zpátky. Vyřadili jsme velmi dobrého náměstka generálního prokurátora kvůli sloupku ve vysokoškolských novinách. Bylo mu devatenáct. Bylo to o parkování.“","c":[["Rozšířit prohledávání ještě dál. Na střední školu, pokud existuje.","Rozšíříte prověrku loajality až do dospívání. Skupina uchazečů se zmenší na lidi, kteří se o ničem nikdy nevyjádřili, což se ukáže jako malá a podivná skupina."],["Prověřovat jen skutečné střety zájmů. Tweety vynechat.","Zúžíte prověřování zpátky na věci, na kterých skutečně záleží. Bazén talentů se přes noc ztrojnásobí, a s ním potichu i kompetence budovy."],["Prověrku tweety ponechat, ale vymáhat ji jen u lidí, které nemáte rád.","Pravidlo zůstává v knize a uplatňuje se výběrově, čemuž do týdne rozumí celá budova a nikdo to nahlas neřekne."],["Nechat prověrku dělat Madison. Je hodně na sítích.","Něčí neteř je pověřena procházením deseti let digitální stopy nominovaného. Najde věci, které přehlédly tři agentury pro prověřování, a jednu věc, kterou nikdo nepotřeboval vědět."]]},"j-hiring-freeze":{"t":"Zmrazení náboru","x":"Roscoe má na klipu papíry a znepokojivé množství nadšení. „Zmrazení je úplné, pane, platí od dnešního rána. Kromě mého úřadu, samozřejmě, který potřebuje čtyřicet dalších lidí, aby to zmrazení řádně vyhodnotil. Šest z nich už jsem najal.“","c":[["Schválit výjimku pro BROOM. Zmrazení platí pro všechny ostatní.","Úřad pro efektivitu roste, zatímco všechno, co má údajně zefektivnit, se zastavilo. Roscoe tomu bez zjevné ironie říká „nezbytná režie“."],["Žádné výjimky. Zmrazení platí i na BROOM.","Uplatníte pravidlo i na tvůrce pravidla. Roscoe je natolik rozzuřený, že to samo o sobě skoro stojí za tu cenu."],["Zmrazit nábor všude kromě resortů, které vás minulý týden chválily.","Zmrazení se stává nástrojem loajality v přestrojení za fiskální politiku. Každá schůze kabinetu teď začíná nezvykle nadšeným komplimentem."],["Zmrazit nábor a pak všechny znovu najmout jako „dobrovolníky“.","Federální práce pokračuje na plný stav pod novou, neplacenou klasifikací. Na papíře to šetří peníze. U soudu to nakonec nešetří nic."]]},"j-exit-interview":{"t":"Výstupní pohovor","x":"Miriam má přepis a pozvednuté obočí. „Standardní výstupní pohovor, pane, s odcházejícím náměstkem ministra obchodu. Otázka čtyři zní „chcete ještě něco dodat“. Dodal šest stránek.“","c":[["Zapečetit spis. Klidně to utajit.","Pohřbíte rutinní personální dokument, jako by to bylo státní tajemství, což zaručí, že ho nakonec někdo shledá dost zajímavým na to, aby ho zveřejnil."],["Přečíst to. Skutečně zvážit dva ze šesti bodů.","Přečtete stížnost muže, který nemá co ztratit a nemá důvod lhát. Dva z jeho bodů jsou, nepříjemně, pravdivé."],["Nechat personální oddělení „ztratit“ soubor při migraci systému.","Šest stránek zmizí při migraci serveru, která byla, mimochodem, naplánovaná z naprosto nesouvisejících důvodů. Skoro nikdo tomu časování nevěří."],["Zveřejnit to sám, jako první, s vlastními poznámkami.","Zveřejníte kritický výstupní pohovor preventivně, s vlastními poznámkami na okraj, které vyvracejí polovinu obsahu. Je to nejpodivnější sebeznemravnění roku a podivně to působí jako sebedůvěra."]]},"j-briefing-book":{"t":"Podkladová složka, kterou nikdo nečte","x":"Muriel má vazač, tři centimetry silný, s barevnými záložkami. „Tohle je kompletní podklad na zítřejší summit, pane. Historie, páky vlivu, červené linie, celá výbava. Minule jste přečetl obal a improvizoval. Dopadlo to celkem dobře. Přesto bych radši, kdybyste přečetl víc než jen obal.“","c":[["Zase to přeskočit. Improvizace zatím fungovala.","Vejdete tam znovu za studena, na šarm a instinkt. Zase to funguje, což je ten nejnebezpečnější možný výsledek, protože vás to nic nenaučí."],["Dnes večer skutečně přečíst celý vazač.","Uděláte to čtení. Není to nic slavného, zabere to čtyři hodiny, a zítra vstoupíte do místnosti se znalostmi místo dohadů, což je skutečně vzácný stav."],["Nechat Muriel to shrnout na jednu kartičku.","Čtvrt milionu dolarů výzkumu a diplomatické přípravy se stlačí na kartičku, co se vejde do kapsy košile. Do oběda ji ztratíte."],["Přečíst to obráceně, pro štěstí. Tradici jste si právě vymyslel.","Vazač otočíte vzhůru nohama z důvodů, které nikdo nedokáže vysledovat k žádné dřívější pověře, a prohlásíte to za úspěšné, když summit dobře dopadne. Ta tradice se, znepokojivě, uchytí."]]},"j-empty-chair":{"t":"Prázdná židle","x":"Deborah počítá židle, než vstoupíte. „Generální prokurátor dnes nepřijde, pane. Prý má kolizi v kalendáři. Není to kolize v kalendáři. Všichni u tohoto stolu vědí, že to není kolize v kalendáři, a všichni budou předstírat, velmi usilovně, že je.“","c":[["Oslovit ho jménem, prázdnou židli a všechno, přímo před kamerami.","Oslovíte prázdnou židli přímo před tiskovým poolem. Vyznívá to buď jako dominance, nebo jako rozpad, podle toho, jakou stanici zrovna divák sleduje."],["Neříkat nic. Pokračovat podle agendy.","Necháte prázdnou židli mluvit přesně tak hlasitě, jak chce, aniž byste k tomu cokoli přidal. Je to verze, kdy jednou vypadáte jako ten klidný."],["Nechat tu konkrétní židli fyzicky odstranit a nahradit.","Doslovnou židli odvezou z místnosti uprostřed schůze. Je to skutečně zvláštní věc vidět a nikdo pak nedokáže vysvětlit, čí to byl nápad."],["Židli nechat, ale s laminovanou jmenovkou, na které stojí „CHYBĚL“.","Jediná laminovaná kartička sedí obviňujícím dojmem v prázdném křesle po celých devadesát minut. Je to nejpodařenější možné využití laminovačky a funguje to přesně, jak jste zamýšlel."]]},"j-standing-ovation":{"t":"Ovace vestoje","x":"Deborah to teď měří stopkami, hlavně jako vtip, hlavně. „Devadesát vteřin potlesku, když vejdete, pane, devadesát, když odejdete. Ministr pro záležitosti veteránů má špatné koleno. Stejně stojí. Nikdo mu neřekl, že nemusí.“","c":[["Prodloužit to na dvě minuty. Časovat to veřejně.","Potlesk se stává časovaným, vysílaným rituálem. Na fotkách to vypadá jako zbožňování. Pro kohokoli, kdo počítá vteřiny, to zní spíš jako záznam z rukojmí."],["Potlesk úplně zrušit. Rovnou začít schůzi.","Vejdete, posadíte se a začnete mluvit o politice. Místnost je viditelně úlevná. Ministr pro záležitosti veteránů se posadí jako první, s vděkem."],["Potlesk ponechat, ale dobrovolný, a sledovat, kdo se odhlásí.","Tleskání zůstává dobrovolné a pečlivě se vede seznam, kdo si ho odpustí. Tleská úplně každý. O potlesk nikdy vlastně nešlo."],["Zatleskat jim první, dřív než oni vám.","Vejdete a začnete tleskat kabinetu. Místnost strne, nejistá, jak reagovat na to, že je někdo ocení schválně. Vzpamatuje se to jedenáct celých vteřin."]]},"j-czar-creep":{"t":"Množení carů","x":"Deborah má seznam a ten se dál rozrůstá do šířky. „Máte teď cara pro hranici, cara pro tu druhou hranici, cara pro vesmír, cara pro plesový sál a od dnešního rána i cara nad cary, pane. Žádného z nich nikdo nepotvrdil. Všichni mají skutečné rozpočty.“","c":[["Přidat další tři cary. Nikdo vás nemůže zastavit.","Nepotvrzený stínový kabinet se přes noc zdvojnásobí. Ani jeden z nich neprošel slyšením. Všichni teď stojí nad několika lidmi, kteří prošli."],["Sloučit cary zpátky do skutečných, potvrditelných postů.","Neformální impérium proměníte zpět na odpovědná místa prověřená Senátem. Obsazuje se to pomaleji a, na rozdíl od alternativy, to přežije změnu administrativy."],["Cary ponechat, ale přejmenovat na „vyšší poradce“. Stejná práce, nudnější titul.","Naprosto stejný nepotvrzený aparát pokračuje pod nudnější hlavičkou. Problém dohledu se nemění. Tisková zpráva zní lépe."],["Udělat carem i stážistku. Carem kávy.","Madison dostane titul, rozpočtovou položku čtyři sta dolarů a skutečnou, byť velmi omezenou pravomoc nad kávovarem Západního křídla. Bere to vážně."]]},"j-confirmation-hearing":{"t":"Potvrzovací slyšení","x":"Hal volá ještě před slyšením, unaveným hlasem typickým jen pro výborovou práci. „Váš nominant na ministerstvo práce dnes pod přísahou třikrát nedokázal jmenovat aktuální míru nezaměstnanosti, pane. Výbor má fotky přesného okamžiku, kdy si jeho poradce dal hlavu do dlaní.“","c":[["Zaútočit na výbor za „chytáky“. Plně do útoku.","Základní otázku na kompetenci rámujete jako pronásledování. Nadchne to shromáždění a spálí to poslední zbytek dobré vůle u dvou senátorů, které jste skutečně potřeboval."],["Stáhnout nominaci. Najít někoho, kdo to číslo zná.","Snížíte ztráty a stáhnete nominaci ještě před hlasováním. Je to potichu učiněné doznání a příští nominant projde za týden hladce."],["Nechat ho absolvovat slyšení znovu, s náušnicí.","Zařídí se druhé slyšení s přenosem do ucha. Odhalí se to během hodiny. Míru nezaměstnanosti si stejně nedokáže zapamatovat ani potom."],["Potvrdit ho stejně, na hlasy strany, a jít dál.","Je potvrzen bez ohledu na to, na základě čísel, a nastupuje do práce, aniž by znal číslo, které je celou náplní té práce. Strukturálně to funguje, v tom smyslu, že se nic okamžitě nezhroutí."]]},"j-blind-trust":{"t":"Slepý fond","x":"Miriam má papíry a velmi specifický tón hlasu. „Slepý fond ministra financí spravuje jeho bratr, pane, který mu každé ráno podrobně volá, aby to s ním probral. Slovo „slepý“ v té větě dělá pořádný kus práce.“","c":[["Uspořádání schválit. Rodina je rodina.","Prohodíte fond, který je slepý jen podle jména, a v praxi zcela transparentní. Je to technicky legální a prakticky transparentní, akorát opačným směrem."],["Vyžadovat skutečně nezávislého správce fondu. Žádní příbuzní.","Vynutíte skutečný smysl toho pravidla. Ministr je naštvaný na jeden telefonát a pak, jak se říká, si na to zvykne."],["Nechat to být, ale požadovat, ať se hovory nahrávají, nečtené, navždy.","Ranní hovory pokračují úplně stejně jako předtím. Vznikne záznam jejich existence, ale ne obsahu, uložený tam, kam ho nikdo nikdy neotevře."],["Dát svůj vlastní majetek do fondu spravovaného Madison.","Něčí neteř je teď na papíře slepou správkyní devítimístného portfolia. Rozumně se zeptá, co je vlastně portfolio. Nikdo jí neodpoví."]]},"j-gift-basket":{"t":"Dárek z ambasády","x":"Miriam s kamennou tváří zvedne formulář. „Velvyslanec Rusalky poslal ministru obchodu náramkové hodinky v hodnotě zhruba jeho ročního platu, pane. Federální zákon vyžaduje, aby to buď oznámil, nebo odmítl. Neudělal ani jedno. Nosí je už měsíc.“","c":[["Nechat mu je. Ohlásit to jako „kulturní výměnu“.","Hodinky zůstávají na zápěstí pod byrokratickou kategorií vymyšlenou přímo pro tuto příležitost. Není to nezákonné, přesně. Ale moc daleko od toho to není."],["Zabavit je. Poslat zákonem předepsaný děkovný dopis.","Hodinky skončí ve vládním skladu podobných zabavených darů, vedle několika koberců a jednoho znepokojivého vycpaného sokola. Pravidlo funguje přesně tak, jak je napsáno."],["Nechat ho hodinky „koupit“ od vlády. Za tržní cenu. Na papíře.","Vymyslí se transakce v nominální hodnotě, aby se dar vypral na koupi. Hodinky zůstávají na zápěstí. Papíry jsou přinejmenším kompletní."],["Požádat Rusalku o odpovídající pár pro sebe, písemně.","Formálně požádáte o druhé hodinky diplomatickou cestou, na hlavičkovém papíře Bílého domu. Velvyslanec s radostí vyhoví a zmíní to na příští státní večeři."]]},"j-three-in-a-week":{"t":"Tři za týden","x":"Deborah přestala aktualizovat organizační schéma perem a přešla na tužku. „Tři propuštění na úrovni kabinetu za šest dní, pane. Vnitřní bezpečnost, energetika a ředitel rozpočtového úřadu, který se to dozvěděl při prezentaci rozpočtu. Kongresu. Naživo.“","c":[["Tento týden propustit i čtvrtého. Zlomit rekord.","Honíte se za sérií, místo abyste ji přerušil. Míra fluktuace se stává vtipem v každém večerním pořadu, a pak, nějak, věcí hrdosti na shromážděních."],["Zastavit se. Tento měsíc žádná další propouštění. Ať to zklidní.","Vyhlásíte moratorium na vlastní churn. Budova se poprvé po týdnech stabilizuje. Nikdo vám neděkuje, ale nikdo taky neodchází."],["Přejmenovat propouštění na „generační obměnu“. Vytisknout memorandum.","Veselé interní memorandum popisuje čistku jako obnovu. Nikdo v budově tomu nevěří ani slovo a všichni to měsíce cituje sarkasticky."],["Vzdát se úlohy oznamovatele sám a nechat to na Alvinovi.","Hlavní komorník je krátce a neoficiálně pověřen informovat ministry, že už nemají práci. Dělá to s větší grácií než kdokoli před ním."]]},"j-succession-plan":{"t":"Nástupnický plán, který nikdo nenapsal","x":"Bo má poznámkový blok plný přeškrtaných jmen. „Vnitřní bezpečnost nemá ministra, žádného potvrzeného náměstka, a třetí v pořadí právě odešel do důchodu, pane. Na papíře by, kdyby se dnes odpoledne něco stalo, resort řídil regionální ředitel z města, jehož název si musím dohledat.“","c":[["Jmenovat loajalistu na prázdné místo dekretem. Přeskočit proces.","Instalujete někoho výnosem místo potvrzením, na teorii, že organizační schéma s vyplněným jménem v každém políčku je bezpečnější než poctivá mezera. Právně to není totéž."],["Urychlit skutečnou nominaci Senátem.","Prosadíte skutečné, potvrditelné jméno na urychleném, ale legitimním harmonogramu. Zabere to šest týdnů navíc a přinese to někoho, kdo přežije předvolání."],["Prostě tu mezeru nezmiňovat. Zatím se nikdo neptal.","Necháte nástupnický řetězec potichu, nebezpečně neúplný, a doufáte, že zpravodajský cyklus zůstane jinde. Zůstane, prozatím, což není totéž jako zůstat tam napořád."],["Vylosovat pořadí nástupnictví z klobouku na příští schůzi kabinetu.","Jména se doslova losují z Alvinova klobouku před celým kabinetem. Je to právně bezvýznamné a, jak si všichni potichu přiznají, poctivější než proces, který to nahradil."]]},"j-inspector-general":{"t":"Generální inspektor","x":"Bo rozkládá časovou osu, a ta není lichotivá. „Generální inspektor pro vnitřní bezpečnost byl sedmdesát dva hodin od zveřejnění zprávy o cestovních výdajích pověřeného ministra, pane, když jste ho vyhodil. Optika je, řeknu vám to jako váš právník, ne moc jemná.“","c":[["Vyhodit i toho dalšího, jakmile se přiblíží k nějaké zprávě.","V praxi zavedete, že jakýkoli interní hlídací pes, který se přiblíží k nálezu, je odstraněn dřív, než ho zveřejní. Funguje to ještě jednou, než si toho Kongres všimne."],["Nechat zprávu vyjít. Se zjištěními se poctivě vypořádat.","Necháte zprávu hlídacího psa doběhnout do konce a odpovíte za to, co najde. Je to nepříjemné na jeden zpravodajský cyklus a je to strukturálně přesně to, jak má systém fungovat."],["Generálního inspektora místo vyhození přeřadit. Stejný efekt, měkčí sloveso.","Ponechá si titul i plat a ztratí portfolio, stůl i personál. Zpráva, od které byl tři dny, fakticky nikdy nebude dokončena."],["Jmenovat novým hlídacím psem stážistku. Plná nezávislost, zaručeně.","Madison dostane titul generální inspektorky na teorii, že dvaadvacetiletou nikdo nemůže obvinit z institucionálního zajetí. Bere tu práci znepokojivě vážně."]]},"j-cabinet-book-club":{"t":"Knižní klub kabinetu","x":"Dr. Weirová zvedá zadaný titul, samonákladovou knihu s vaší tváří na obálce ve zlaté fólii. „Požádal jste celý kabinet, aby si před příští schůzí přečetl vaše vlastní paměti, pane, a přišel připraven mluvit o oblíbených kapitolách. Tři to už dočetli. Dva z těch tří lžou.“","c":[["Vyzkoušet je z toho. Veřejně. Formou losování.","Zavedete veřejný test z vlastních pamětí pro sedící ministry. Ministr zemědělství nedokáže pojmenovat kapitolu o sobě. Byla to kapitola první."],["Zrušit úkol. Byl to podivný nápad.","Potichu stáhnete čtenářský úkol dřív, než se stane vtipem ve třech samostatných newsletterech. V jednom se jím už stal."],["Zadat druhou knihu. Pak třetí. Vznikne sylabus.","Seznam čtení se rozroste o vaše paměti, paměti vašeho otce a biografii, kterou jste si o sobě nechal vloni na jaře napsat. Docházka na diskusní hodiny je, pozoruhodně, povinná a plná."],["Nechat Dr. Weirovou hodnotit referáty jako profesorku.","Historička Bílého domu je zapřažena, aby hodnotila referáty ministrů skutečnou stupnicí. Generálnímu prokurátorovi dá čtyři mínus. Žádá o přezkoušení."]]},"j-secretary-of-secretaries":{"t":"Ministr ministrů","x":"Deborah to navrhuje opatrně, vědomá si, jak to zní. „Jedna jediná pozice, pane, která stojí nad celým kabinetem a odpovídá jen vám. Každý ministr odpovídá nejdřív jí, vám až potom. Vyřeší to koordinační problém. Zároveň to znamená, že strukturálně teď vládu řídí jeden člověk.“","c":[["Vytvořit tu pozici. Dát jí skutečnou pravomoc nad každým resortem.","Jediný nepotvrzený úřad teď stojí nad celým potvrzeným kabinetem, odpovědný jen vám. Je to nejúhlednější možné organizační schéma a nejméně odpovědné za sto let."],["Přeskočit to. Koordinovat prostřednictvím pravidelných schůzí kabinetu.","Zachováte tu neohrabanou, hašteřivou, skutečně odpovědnou verzi vlády. Je to schválně pomalejší, což je vlastnost, za kterou vám nikdo neděkuje."],["Vytvořit tu pozici, ale obsadit ji sám sebou. Bez delegování.","Prostě si tu novou pravomoc vezmete osobně místo přidělení. Strukturálně se nemění nic kromě vašeho kalendáře, který teď má čtyřicet přímých podřízených."],["Dát ten nový titul Deborah, která o něj vůbec nežádala.","Deborah se přes noc stává jednou nejmocnější nevolenou úřednicí ve Washingtonu, naprosto proti svému vlastnímu doporučení. Bere to dobře. Dá si velmi dlouhý oběd."]]},"j-cabinet-retreat":{"t":"Výjezdní zasedání kabinetu","x":"Deborah porovnává kalendář se zprávami, a moc si to nesedí. „Výjezdní zasedání kabinetu je tento víkend, pane. Cvičení důvěry, lanové centrum, přednáška o „služebném vedení“. Bylo to naplánované už před měsíci. Náhodou to padne přímo doprostřed měnové situace.“","c":[["Jít na to, jak bylo plánováno. Optiku k čertu.","Celý kabinet se fotí na lanovém centru, zatímco měnová krize běží bez dozoru. Jediný snímek, ministra financí visícího v postroji, přežije samotnou krizi."],["Zrušit ho. Pracovat o víkendu jako všichni ostatní.","Zrušíte to a udržíte kabinet u stolů. Je to zjevné rozhodnutí a jako takové vám vynese téměř žádné uznání."],["Zasedání zachovat, ale zkrátit na půl dne, nazvat to „soustředěné“.","Kompromisní verze trvá čtyři hodiny místo dvou dnů. Cvičení důvěry se pořád odehrají. Nikdo nehlásí zvýšenou důvěru."],["Přesunout celé zasedání do telefonní konference. Cvičení důvěry po telefonu.","Čtrnáct ministrů se pokouší o cvičení důvěry přes telefonní linku bez videa. Podle obecné shody je to nejpodivnějších devadesát minut, které kdokoli z nich strávil ve vládě."]]},"j-nda-everyone":{"t":"Dohoda o mlčenlivosti","x":"Sy má standardní formulář připravený ke schválení. „Každý nový zaměstnanec podepisuje před prvním dnem doživotní dohodu o mlčenlivosti, pane. Měl bych podotknout, jako váš právník, že u bývalého federálního zaměstnance je taková dohoda skoro nevymahatelná. Měl bych taky podotknout, že to skoro nikdo netestuje u soudu. Funguje to jenom ze strachu.“","c":[["Rozšířit to. Zpětně. Podepíší všichni, kdo tu kdy pracovali.","Pokusíte se zavázat bývalý personál dokumentem vytvořeným poté, co odešli. Nemá to naprosto žádnou právní sílu a úplně každý, kdo to dostane, to správně přečte jako výhrůžku."],["Dohodu o mlčenlivosti zrušit. Spolehnout se na skutečná pravidla o utajovaných informacích.","Spolehnete se na skutečná, vymahatelná pravidla o utajovaných materiálech místo zastrašovacího dokumentu bez zubů. Je to méně dramatické a je to verze, která přežije soudní přezkum."],["Dohodu ponechat, přidat doložku o „hanlivém tónu“.","Pokusíte se zakázat nikoli fakta, ale tón, rozlišení, které nikdy žádný soud neshledal fungujícím. Sy správně předpoví, že se z toho stane nejzesměšňovanější doložka v historii dokumentu."],["Místo papírování požádat personál o slib malíčkem.","Nahradíte právní dokument doslovným slibem na malíček, osobně stvrzeným v Oválné pracovně. Několik zaměstnanců to bere závazněji, než kdy brali tu dohodu."]]},"j-town-hall-plant":{"t":"Nastrčená otázka","x":"Brayden má kartičku, kterou napsal pro „zaměstnance“, aby se zeptal. „Technicky je to setkání s resortním personálem, pane, ale první tři otázky jsme napsali my a předali třem stážistům. Jeden ze stážistů právě dal výpověď a možná to zmíní novináři.“","c":[["Nastrčit dalších šest otázek. Naplnit tím celou hodinu.","Celé setkání se stává od začátku do konce naskriptovaným, přehrávaným zaměstnanci čtoucími z kartiček. Vyjde to najevo do týdne, protože vždycky vyjde."],["Nastrčené otázky zrušit. Vzít si skutečné otázky, za studena.","Poprvé po měsících si vezmete neskriptované otázky od skutečných zaměstnanců. Dvě jsou nepříjemné. Všechny jsou skutečné, což má větší cenu, než co to stojí."],["Odcházející stážistce za mlčení neformálně zaplatit.","Nabídne se neoficiální dohoda za mlčení odcházejícího stážisty. Je to typ tiché dohody, která zůstane tichá jen do chvíle, než přestane."],["Nechat Braydena položit nastrčené otázky sám, na kameru, pod svým jménem.","Devatenáctiletý ředitel příspěvků vstane na vlastním setkání a pod vlastním jménem položí vlastní nastrčenou otázku. Je to tak průhledné, že se to obrátí zpátky k roztomilosti."]]},"j-cabinet-vacancy-record":{"t":"Rekord v neobsazenosti","x":"Hal čte z tištěného seznamu, který se pořád prodlužuje. „Devět neobsazených postů na úrovni kabinetu právě teď, pane, moderní rekord. Kongres si na to založil sázkovou skupinu, kdo bude obsazen jako další. Chytré peníze sázejí, že žádný, ne před volbami v polovině období.“","c":[["Obsadit je všechny najednou loajalisty. Přeskočit prověřování.","Devět postů je obsazeno jediným oznámením lidmi vybranými podle jedné jediné vlastnosti. Vláda funguje, technicky, plně obsazená, kabinetem, který se nikdy předtím nesetkal."],["Obsazovat je pomalu, řádně, jednu skutečnou nominaci po druhé.","Odpracujete skutečný proces, jedno slyšení po druhém. Zabere to většinu roku. Na rozdíl od alternativy to taky vydrží."],["Nechat je neobsazené. Náměstci to zvládnou.","Devět resortů dál funguje neomezeně na nepotvrzených náměstcích. Je to levnější, je to rychlejší a v přísném slova smyslu to už vlastně není vláda."],["Nechat sázkovou skupinu Kongresu vybrat příštího nominanta.","Skutečně přijmete vítězné jméno z kongresní kancelářské sázkové skupiny jako svého příštího nominanta. Proti očekávání je to naprosto schopná volba."]]},"j-annual-review":{"t":"Roční hodnocení","x":"Deborah má hromadu formulářů, jaké kabinet nikdy předtím nevyplňoval. „První roční hodnocení výkonu pro celý kabinet, pane. Někdo je musí podle něčeho ohodnotit. Momentálně má návrh stupnice jednu jedinou otázku: „Loajalita, jedna až deset.“ Právní oddělení si myslí, že potřebujeme aspoň druhou otázku.“","c":[["Ponechat jednootázkovou stupnici. Loajalita je jediné, na čem záleží.","Ministři kabinetu jsou formálně hodnoceni podle jedné jediné osy s vaším jménem u výsledků. Není to hodnocení výkonu. Každý v budově přesně ví, co to je."],["Přidat skutečná měřítka. Plnění rozpočtu, výsledky programů, tu skutečnou práci.","Hodnocení se stává skutečným posouzením toho, jestli resorty dělají to, kvůli čemu existují. Je to nudnější. Je to taky první poctivé papírování, které budova celý rok vyprodukovala."],["Hodnotit je podle loajality, ale sloupec pojmenovat „soulad“.","Stejné měřítko přežije pod jemnějším slovem. Nikoho v kabinetu to neošálí. Slovo „soulad“ se do měsíce používá sarkasticky na každé chodbě v budově."],["Nechat kabinet hodnotit sám sebe navzájem, anonymně, a přečíst to nahlas.","Anonymní vzájemná hodnocení se přečtou nahlas na příští celé schůzi kabinetu. Několik je nečekaně upřímných. Ministr práce se před třinácti kolegy dozví, co si o jeho schůzích skutečně myslí ministr energetiky."]]},"j-parting-shot":{"t":"Poslední rána","x":"Kaylee má přepis, vytištěný a zvýrazněný ve třech barvách. „Bývalý generální prokurátor dal čtyřicet minut po propuštění živý rozhovor, pane. Nazval administrativu „skupinovým chatem s jadernými kódy“. Je to bohužel velmi dobrá hláška a už je to titulek úplně všude.“","c":[["Veřejně ho zdiskreditovat. Zpochybnit jeho duševní stav, oficiálně.","Zaútočíte na charakter muže, kterého jste před pár hodinami vyhodil, na kameru. Vyznívá to jako přecitlivělost pro každého kromě základny, která to správně čte jako vymáhání loajality."],["Neříkat nic. Nechat tu hlášku mít svůj jeden zpravodajský cyklus a odeznít.","Odmítnete té dobré hlášce dodat víc kyslíku, než už má. Vydrží den a půl místo týdne, což je celé řemeslo neodpovídání."],["Nechat Syho poslat výzvu k zastavení šíření kvůli té „skupinovému chatu“ hlášce.","Vyhrožujete právním krokem kvůli metafoře. Samotný dopis unikne do hodiny a stane se ještě lepší hláškou než ta původní."],["Hlášku si přivlastnit. Dát ji na hrnek.","Obchod se suvenýry začne od pondělí prodávat hrnek s nápisem „Skupinový chat s jadernými kódy“. Do středy se prodává lépe než pamětní Bible."]]},"k-security-clearance":{"t":"Prověrka","x":"Errol drží složku na klíně, jako by mohla každou chvíli vybuchnout. „Váš syn dvakrát neprošel bezpečnostní prověrkou, pane. Zahraniční obchodní partneři, nepřiznané půjčky, firma v Cathay, kterou nikdo pořádně nedokáže vysvětlit. Analytici doporučují zamítnutí. Já doporučuji, abyste mě nežádal o její zrušení potřetí.“","c":[["Zruší ji osobně. Dostane odznak.","Výjimku podepíšete sám. Trent mladší dostane odznak, stůl a ochranku, která teď musí předstírat, že si nevšímá telefonátů z Cathay."],["Necháte zamítnutí platit. Bude pracovat z domova.","Systém funguje přesně tak, jak má, tentokrát na vašem vlastním synovi, a bolí to způsobem, na který jste nebyl připraven. On to navenek bere s klidem."],["Vytvoříte mu nový titul, na který prověrka netřeba.","„Zvláštní poradce pro rodinné záležitosti“ nepotřebuje odznak, spis ani otázky. Kancelář mu zůstává. Nikdo neumí říct, co ta kancelář vlastně dělá."],["Místo toho ho pošlete na nesouvisející dobročinné turné.","Syna vypravíte do tří zemí na náklady cestovního rozpočtu, aby rozdával certifikáty a přestřihával pásky. Dva senátoři se písemně ptají, co přesně tím propaguje. Na věci s Cathay to nic nemění."]]},"k-son-in-law-plan":{"t":"Mírový plán","x":"Muriel volí slova, jako by šlo o rozbušky. „Váš zeť má mírový plán, pane. Osmatřicet stran, žádný kariérní diplomat nebyl konzultován, a příloha s odhadem cen nemovitostí, která by ve struktuře mírového plánu neměla vůbec být. Obě vlády se ptají, kdo to vlastně je.“","c":[["Oznámíte ho sám z pódia. Ještě dnes.","Představíte mírový plán s přílohou o nemovitostech, jako by to bylo normální. Dvě ministerstva zahraničí písemně žádají o rozhovor s někým dospělým."],["Pošlete ho nejprve na ministerstvo zahraničí. Tiše upravíte devátou stranu.","Murielin tým stráví víkend odstraňováním odhadů cen nemovitostí. Co zbyde, je chudé, ale aspoň se tomu nebudou smát v překladu."],["Dáte mu velvyslanecký titul, který sedí k jeho sebevědomí.","Titul bez schvalovacího slyšení a s agendou velikosti polokoule. Diplomatický sbor aktualizuje organizační schéma a jinak mlčí."],["Pošlete plán univerzitnímu think tanku na recenzní řízení.","Šest profesorů ho zdarma okomentuje živě v diskuzním pořadu vysílaném proti večerním zprávám. Příloha o nemovitostech dostane poznámku pod čarou, která zní v plném znění: „viz střet zájmů výše.“ Nadšený z toho není on, a nikdo jiný taky ne."]]},"k-blind-trust":{"t":"Svěřenský fond","x":"Miriam rozkládá organizační schéma s trpělivostí ženy, která tohle už dělala. „Říká se tomu svěřenský fond, pane, řídí ho vaše děti a vy jim můžete kdykoli zavolat. Slepý fond takhle nefunguje. Tohle je v lepším případě fond s tmavými brýlemi.“","c":[["Necháte to tak. Formálně je to legální.","Uspořádání přežívá díky technikálii, kterou Miriam osobně nesnáší. Děti řídí byznys, vy řídíte zemi a všichni tvrdí, že spolu tyhle dvě věci nikdy nemluví."],["Skutečně se všeho zbavíte. Prodáte celé portfolio.","Opravdu to prodáte. Rodina zuří, etická komise oněmí úžasem a novinářce to musíte říct dvakrát, než tomu uvěří."],["Přejmenujete ho na „Vlastenecký fond“. Nic jiného neměníte.","Nové jméno, stejné tmavé brýle. Miriam aktualizuje jeden dokument a formálně žádá o přeložení."],["Vložíte fond na jméno rodinného psa.","Kokršpaněl je teď na papíře holdingová společnost. Psa nelze vyslechnout pod přísahou, což několik právníků označuje za celý smysl toho plánu."]]},"k-hotel-block":{"t":"Hromadná rezervace","x":"Alvin přináší výtisk rezervace jako obžalobu. „Qadirská delegace zarezervovala v rodinném hotelu jednačtyřicet pokojů na cestu, na které je oficiálně šest delegátů, pane. Také si vykoupili celé wellness centrum. Wellness nemá nikdo v plánu využít.“","c":[["Veřejně jim poděkujete za jejich obchod.","V přípitku před kamerami chválíte „přátelství“ vedle účtu za wellness, které nikdo nepoužil. I tvrdé jádro na chvíli ztichne."],["Rezervaci odmítnete. Vrátíte zálohu.","Rodinný podnik odmítne skutečné peníze, aby se vyhnul zdání úplatku, což je samo o sobě nejbližší věc k důkazu, že to zdání odpovídalo pravdě."],["Necháte delegaci přesunout se do konkurenčního hotelu.","Problém s optikou vyřešíte tak, že to stojí skutečné peníze vaši vlastní rodinu, a řeknete jim, že to byla strategie. Úplně vám to nevěří."],["Pokoje delegaci odpustíte zdarma. Nazvete to diplomacií.","Zdarma darujete jednačtyřicet pokojů cizí vládě, což je nakonec ještě horší titulek než účtování, a navíc to stojí skutečné peníze."]]},"k-ballroom-rental":{"t":"Pronájem sálu","x":"Muriel podává přes stůl fakturu s hlavičkou cizího konzulátu. „Zarezervovali si sál na galavečer dva dny před vaším rozhodnutím v jejich obchodním sporu, pane. Šedesát tisíc dolarů, zaplaceno v plné výši, položkově uvedeno jako 'pronájem prostor'. Technicky je to jen pronájem.“","c":[["Sejdete se s nimi. Peníze si necháte. Rozhodnete později.","Galavečer se koná, šek je proplacen a obchodní rozhodnutí padne o dva týdny později v jejich prospěch. Nikdo nemůže dokázat, že posloupnost je úplatek."],["Necháte pronájem odmítnout přes provozní oddělení.","Sál zůstane v pátek potmě. Rodinu to stojí storno poplatek a všem ostatním to koupí klidný spánek."],["Rezervaci necháte proběhnout, ale písemně se z případu vyloučíte.","Memorandum o vyloučení je podáno téhož odpoledne, kdy je proplacen šek. Obě fakta jsou pravdivá a leží ve stejné složce, což je nějak horší, než kdyby bylo jen jedno z nich."],["Místo toho sál ten večer otevřete veřejnosti.","Galavečer zrušíte a necháte tři sta školáků zdarma prohlédnout lustry, živě pro místní zprávy. Konzulát to nazve urážkou. Kongres to nazve laciným populismem na veřejné útraty."]]},"k-branded-golf":{"t":"Golfový summit","x":"Muriel má memorandum o místě konání. „Northmarská delegace preferuje váš golfový resort, pane. Sazbu za pokoje určuje rodina, catering určuje rodina, a poplatky za odpolední golf zdarma pro delegaci určuje, také, rodina. Samotný summit potrvá čtyři hodiny.“","c":[["Uspořádáte ho tam. Naúčtujete standardní sazbu.","Summit se koná na vašich vlastních greenech a faktura jde federální vládě. Někde auditor začíná velmi dlouhou tabulku."],["Přesunete summit do neutrálního vládního zařízení.","Konferenční místnost se špatnou kávou a bez zdroje příjmů. Delegace je mírně zklamaná. Audit, který by jinak přišel, se nekoná."],["Uspořádáte ho tam, poplatek odpustíte a nazvete to darem daňovým poplatníkům.","Bezplatný sál, stejný střet zájmů, lepší tisková zpráva. Rodina absorbuje ztrátu a příští rok si ji odečte z daní jako dar."],["Celý summit uspořádáte na osmnáctém greenu, živě.","Dva hlavy států dojednávají obchodní rámec mezi jamkami, v televizi, fakticky sponzorováno vaší vlastní scorecard. Je toho hodně, co bude muset vysvětlovat historikům."]]},"k-daughter-brand":{"t":"Ochranná známka","x":"Ivy září a drží desky. „Cathay schválilo jedenáct ochranných známek pro šperkařskou kolekci za jeden týden, tati. Obvykle to trvá roky. Stalo se to ve stejném týdnu, kdy jsi zmírnil vývozní clo. Vím, jak to zní. Ale je to taky prostě dobrá zpráva pro tu kolekci.“","c":[["Pogratulujete jí z pódia. Zmíníte značku jménem.","Z prezidentského pódia propagujete dceřinu šperkařskou kolekci vedle země, jejíž ochranné známky právě prošly rekordní rychlostí. Slovo „náhoda“ si pořádně zaběhá."],["Necháte právní oddělení potvrdit, že schválení bylo rutinní.","Memorandum potvrzuje, že se nestalo nic nepatřičného, což je typ věci, která je pravdivá a zároveň nikomu nepomůže."],["Požádáte ji, ať značku licencuje někde politicky méně hlučném.","Výroba kolekce se přesune do země bez probíhajícího obchodního sporu. Je to tišší. A je to také, zjevně, správné rozhodnutí."],["Spustíte konkurenční kolekci pod prezidentskou pečetí.","Objeví se kolekce doplňků s prezidentskou pečetí, cíleně podbízející dceřiny ceny. Podle všech zpráv je Den díkůvzdání napjatý."]]},"k-son-business-deal":{"t":"Zahraniční obchod","x":"Trent mladší je na hlasitém odposlechu, nadšený sám sebou. „Tati, dohoda s Rusalkou je hotová. Dvě stě milionů, na deset let, moje jméno na budově. Pořád opakovali, jak si rodinu váží. Ani jsem nemusel vyjednávat.“","c":[["Poblahopřejete mu. Žádné doplňující otázky.","Řeknete mu dobrá práce a zavěsíte. Budova vyroste s jeho jménem na fasádě jedenáct pater od námořní základny. Technicky jste se na nic neptal."],["Necháte právní oddělení smlouvu prověřit, než podepíše cokoli dalšího.","Sy stráví týden čtením smlouvy, kterou číst nechtěl, a najde tři klauzule, za které by se měl stydět kdokoli zúčastněný. Upozorní na ně. Trent mladší stejně podepíše."],["Požádáte ho, ať aspoň změní jméno budovy.","Věž si dohodu ponechá a přijde o rodinné příjmení na fasádě. Je to to nejmenší, co mohl udělat, a přesně tolik udělá."],["Necháte ho darovat výtěžek nadaci. Kterou taky vedete vy.","Dvě stě milionů dolarů se přesune z jednoho rodinného subjektu do druhého, daňově zvýhodněně, a v tiskové zprávě se to popíše jako štědrost."]]},"k-nepo-hire":{"t":"Bratranec","x":"Deborah drží životopis, pokud se to tak dá nazvat. „Váš bratranec chce vést agenturu pro malé podnikatele, pane. Jeho zkušenosti jsou zkrachovalý řetězec soláriích a naprostá osobní loajalita k vám. To jsou bohužel jediné dvě kvalifikace, na které se teď někdo ptá.“","c":[["Dáte mu agenturu. Loajalita je kvalifikace.","Muž, jehož poslední podnik zkrachoval třikrát, teď dohlíží na půjčky pro malé firmy. Je, jak všichni uznávají, mimořádně loajální."],["Dáte mu místo čestný titul. Žádnou rozpočtovou pravomoc.","Dostane pěknou kancelář, jmenovku a nulovou možnost cokoli podepsat. Je nadšený. Agentuře se nic nestane."],["Najmete někoho kvalifikovaného. Bratrance uděláte jeho „vrchním poradcem“.","Agenturu řídí skutečný odborník, zatímco bratranec ji všude stínuje a nabízí názory, které je profesionálně nucena vyslechnout s přikyvováním."],["Pošlete ho vést tu nejméně důležitou ambasádu, jakou najdete.","Je teď velvyslancem v zemi s jedenácti tisíci obyvateli a spoustou korálových útesů. Korálové útesy to prý nesou statečně."]]},"k-inauguration-fund":{"t":"Inaugurační fond","x":"Lyle má účetní knihu otevřenou na stránce, kterou by nejraději zavřel. „Inaugurační výbor vybral víc peněz než kterýkoli v historii, pane. Třetina z toho není zdokumentovaná. Předsedala mu vaše dcera. Tohle striktně vzato není moje oddělení, ale někdo to musel říct nahlas.“","c":[["Auditovat to nebudete. Byla to skvělá párty.","Nezdokumentovaná třetina zůstává nezdokumentovaná. Párty, jak se všichni shodují, byla opravdu skvělá."],["Nařídíte nezávislý audit výboru.","Externí firma spočítá každý dolar. Zjistí nedbalost, ne krádež, což je úleva, která vás stejně stojí titulek."],["Tiše doplatíte chybějící třetinu z kampaňového účtu.","Díra se zalepí penězi z úplně jiného kasy, což vyvolá novou otázku, kterou zatím nikdo nepoložil."],["Prohlásíte inauguraci zpětně za neziskovou akci.","Jednodenní gala ve smokingu je dodatečně přeřazeno mezi charitativní akce. Finanční úřad žádá o telefonát. Nezvednete to."]]},"k-secret-service-bill":{"t":"Účet za ochranku","x":"Duane čte fakturu bez emocí, jako muž, který čte číslo, které nemůže změnit. „Ochrana vašich vnoučat v resortu stojí tento kvartál milion sto tisíc dolarů, pane, většinou za pokoje v nemovitostech, které vlastní rodina. Účtovaná sazba je standardní sazba. To je nějak ta část, která lidi štve nejvíc.“","c":[["Tržní sazba je tržní sazba. Naúčtujete to.","Vláda platí maloobchodní cenu firmě, kterou vlastníte, za ochranu lidí, kteří nesou vaše jméno. Logika je neprůstřelná a optika radioaktivní."],["Necháte rodinu pokoje odpustit zdarma.","Zdarma pokoje pro federální agenty. Stojí to firmu skutečné příjmy a koupí vám to přesně jeden klidný zpravodajský den."],["Přesunete vnoučata místo toho do vládního zařízení.","Méně vymožeností, žádný střet zájmů, žádný titulek. Someboyova neteř Madison to nazve „velmi normální volbou, za kterou se musí chválit“."],["Naúčtujete to se slevou a nazvete tu slevu „vlasteneckou sazbou“.","Nová, vymyšlená sazba, uplatněná zpětně, popsaná jako štědrost od samotné firmy, která si ji sama určuje. Nikdo na ministerstvu financí nenajde ceník té slevy."]]},"k-family-christmas-card":{"t":"Vánoční přání","x":"Renata ukazuje náhled. „Je to krásná fotka, pane. Všichni ve stejných svetrech. Problém je drobný text pod stromkem, který zní: 'Šťastné svátky od rodiny a od kolekce Resort'. Odešlo to na čtyři sta tisíc vládních adres, než si toho někdo všiml.“","c":[["Pošlete to tak, jak to je. Je to jen logo.","Čtyři sta tisíc federálních zaměstnanců dostane v podstatě vánoční reklamu. Tři z nich si ji přesto zarámují."],["Necháte to přetisknout bez drobného textu. Náklady zaplatíte sami.","Čisté, nudné přání bez loga odejde o týden později. Je vřele přijaté a nevyvolá žádnou další kauzu, což byl celý smysl."],["Svalíte vinu na tiskárnu za ten drobný text.","Tiskárna v klíčovém státě je veřejně obviněna z rozhodnutí, které padlo o dvě patra výš. Tiskárna mlčí a nepřijde o spánek."],["Půjdete do toho naplno. Přidáte příštímu přání slevový kód.","Příští rok přání obsahuje patnáctiprocentní slevu na wellness pobyt. Jeden senátor si ho zarámuje a přečte nahlas na plénu, celých devět minut."]]},"k-in-laws-visa":{"t":"Rychlý pruh","x":"Duane si spis ještě jednou přečte, než to řekne nahlas. „Rodiče vašeho zetě prošli celým řízením o trvalém pobytu za jedenáct dní, pane. Průměr je čtrnáct měsíců. Nikdo přesně neporušil žádné pravidlo, jen odsunuli papíry všech ostatních stranou, aby to stihli.“","c":[["Je to rodina. Zrychlíte to ještě víc.","Jedenáct dní se u další žádosti stane šesti. Lidé, jejichž spisy byly odsunuty stranou, nemají kamery, které by na ně mířily, z definice."],["Vrátíte je do běžné fronty.","Papíry se vrací ke čtrnácti měsícům čekání společně s obyčejnými Američany z obyčejných důvodů. Je to fér. Nikdo na rodinné večeři to tak nenazve."],["Schválíte to, ale požadujete stejnou rychlost pro všechny.","Nařídíte zrychlit celý systém, aby laskavost přestala vypadat jako laskavost. Je to drahé, je to správné, a je to nejméně dramatické možné řešení."],["Necháte tchána s tchyní místo toho veřejně požádat o dodatečné prověření.","Rodiče zetě si na kameru vyžádají dodatečné bezpečnostní prověření, což polovina tisku bere jako trik a nikoho v Kongresu, který dál žádá skutečnou reformu, to neuspokojí."]]},"k-resort-summit":{"t":"Summit v resortu","x":"Muriel už tenhle spor jednou prohrála. „Protokol chce z obvyklých důvodů neutrální vládní místo, pane. Vy chcete resort, protože se sál lépe fotí a rodina má rezervaci. Říkám vám obě fakta, aby později nikdo neřekl, že jsem to neřekla.“","c":[["Resort. Konečné rozhodnutí.","Šest hlav států se sejde pod lustrem, který vaše rodina prodala vládě se značnou přirážkou. Fotky jsou, uznejme, velkolepé."],["Přijmete radu protokolu. Neutrální místo.","Vládní konferenční centrum s horším osvětlením a bez střetu zájmů. Je to volba, která dobře stárne a nikoho v místnosti nenadchne."],["Resort pro galavečer, vládní místo pro samotná jednání.","Kompromis napůl, který dá rodině polovinu rezervace a etické komisi polovinu bolesti hlavy. Všichni odcházejí nespokojení, což Muriel nazývá pokrokem."],["Summit uspořádáte na námořní lodi. Ničí hotel.","Šest světových lídrů jedná na torpédoborci na rozbouřeném moři. Dva se pomořou, protokol to nazve diplomatickým incidentem, který čeká, až se stane, a jeden kongresman se ptá, kdo platí palivo."]]},"k-golf-membership":{"t":"Náborová kampaň","x":"Miriam má seznam nových členů, který vypadá jako zasedací pořádek státní večeře. „Čtrnáct nových členství v klubu tento kvartál, pane, všichni cizí státní příslušníci, všichni žádají o schůzky s vaším týmem do měsíce. Samotný vstupní poplatek je dvě stě tisíc dolarů. Koupí to skříňku a, zjevně, i zpětné zavolání.“","c":[["Schůzky se uskuteční. Business je business.","Čtrnáct skříněk, čtrnáct schůzek, jeden velmi efektivní kalendář. Mirionina kancelář otevírá spis, který nikdy nesmí uzavřít."],["Zahraniční členství omezíte a nová přijímání zmrazíte.","Klub přestane prodávat přístup převlečený za golf. Je to správná náprava a stojí rodinu skutečné, vyčíslitelné peníze."],["Schůzky proběhnou, golf vynecháte, nazvete to náhodou.","Stejný kalendář, žádné hole v ruce. Rozdíl neuspokojí nikoho, ale technicky je to rozdíl."],["Zveřejníte seznam členů. Celý. Ještě dnes.","Plná transparentnost, okamžitě, dřív než si o ni kdokoli řekl. Čtrnáct členů do týdne potichu odstoupí a čtyři spojenci v Kongresu to nazvou vynucenou katastrofou pro rodinné fundraisingové aktivity."]]},"k-financial-disclosure":{"t":"Majetkové přiznání","x":"Miriam žlutě zvýraznila jedenáct řádků. „Vaše roční přiznání, pane. 'Hodnota majetku: mezi jedním a padesáti miliony dolarů' je technicky povolené a technicky nanic. Udělal jste to u jedenácti různých položek. Je to buď mimořádná opatrnost, nebo mimořádné vyhýbání, a já nemám dovoleno hádat, co z toho.“","c":[["Podáte to přesně takhle. Každý rok.","Jedenáct rozpětí tak širokých, že skoro nic neznamenají, se stane každoroční tradicí. Je to legální. Miriam to podá a znovu žádá o přeložení."],["Zpřesníte každé rozpětí na skutečné číslo.","Skutečná čísla jdou do spisu, což je neobvyklé, nepříjemné a přesně to, k čemu ten formulář má sloužit."],["Zpřesníte polovinu rozpětí. Ty trapné necháte vágní.","Selektivní transparentnost, která uspokojí formulář a neoblbne nikoho, kdo dává pozor, což se ukáže být skoro každý, kdo dává pozor."],["Podáte ručně psanou poznámku místo formuláře.","Jedna stránka s celým textem „je to složité, zeptejte se mého účetního“ je podána místo federálního přiznání. Proti všem očekáváním je přijata a zaevidována."]]},"k-niece-madison-job":{"t":"Povýšení","x":"Madison, dvaadvacet let, drží vizitku s nápisem „zástupkyně ředitele pro strategické iniciativy“. „Ani já pořádně nevím, co to znamená, strejdo,“ říká. „Ale mám teď odznak a Deborah říká, že musím sedět na poradě o rozpočtu. Mám na té poradě něco říkat?“","c":[["Dáte jí skutečnou pravomoc. Rodina je rodina.","Dvaadvacetiletá dívka s vizitkou teď má fakticky velící pravomoc nad lidmi dvakrát staršími. Dva z nich si to odpoledne začnou aktualizovat životopis."],["Titul necháte čestný. Žádné podpisové pravomoci.","Madison si nechá odznak a přijde o poradu o rozpočtu. Působí spíš úlevně."],["Pošlete ji vést něco malého a daleko.","Teď vede regionální kancelář pro komunikaci s veřejností, kterou nikdo nenavštívil od reorganizace před dvěma vládami. Vrhne se do toho se skutečným nadšením."],["Necháte ji na plný úvazek stínovat Deborah. Žádný titul.","Žádný odznak, žádná vizitka, jen osmnáct měsíců učení skutečné práce od nejlepší v oboru. Novináři to nazvou degradací v přestrojení za pokoru a Madisonina matka vám kvůli tomu volá každý večer stěžovat si."]]},"k-hotel-emoluments-suit":{"t":"Žaloba kvůli emolumentům","x":"Sy drží žalobu podanou osobně proti vám, kterou považuje za profesně vzrušující a osobně vyčerpávající. „Podepsalo se pod ni dvě stě šest členů Kongresu, pane. Jejich teorie zní, že když cizí vláda platí vašemu hotelu, fakticky platí vám. S úctou, není to špatná teorie.“","c":[["Budete bojovat. U každého soudu, každé odvolání.","Tři roky a několik milionů dolarů na právnících nakonec potvrdí, že klauzule je reálná, ale velmi těžko vymahatelná. Vy to nazýváte vítězstvím."],["Uzavřete smír. Sporné zisky darujete na charitu.","Rodina napíše šek potravinové bance ve výši zahraničních zisků a žaloba je stažena. Je to levnější než právníci a jednou konečně vypadá, že to snadné bylo i to správné."],["Namítnete, že ústava to tak vlastně nemyslí.","Vaši právníci s vážnou tváří tvrdí, že dvě stě let stará protikorupční klauzule se na hotely nevztahuje. Tři soudci je požádají, aby to zopakovali pomaleji."],["Prodáte hotel v opravdu tajné aukci. Doopravdy tajné.","Nemovitost jde nejvyšší nabídce v zapečetěné aukci, jejíž identita zůstává neznámá i vám, na vaše vlastní naléhání. Právníci vám nevěří, dokud nepřijde platba. Polovina vašich vlastních dárců to nazve sebesabotáží."]]},"k-family-portrait":{"t":"Oficiální portrét","x":"Renata odhaluje plátno. „Oficiální portrét, pane. Namalovaný přesně podle zadání, jen umělkyně bez pokynů zakomponovala do okna za vámi siluetu rodinného resortu. Buď je to pocta, nebo faktura o čtyřech nulách převlečená za umění. Nedokážu to rozeznat a ona vlastně taky ne.“","c":[["Pověsíte to tak. Silueta zůstává.","Každý cizí hodnostář, který projde tou chodbou, teď dostane zdarma pohled na siluetu vašeho hotelu. Umělkyně má skvělou větu do své příští zakázky."],["Siluetu necháte přemalovat. Neutrální pozadí.","Obyčejná vládní modř nahradí siluetu. Je to nudnější a je to správné, a Renata už o faktuře nikdy nepromluví."],["Objednáte druhý portrét, tentokrát jen resortu.","V téže chodbě teď visí dva portréty. Jeden vás, druhý budovy, kterou vlastníte. Průvodce začíná dostávat otázku, na kterou nebyl vyškolený."],["Necháte umělkyni malovat, co bude chtít, po zbytek volebního období.","Renata dostane plnou tvůrčí svobodu pro každý další oficiální portrét. Výsledky jsou zvláštní, občas krásné, a tři šéfové úřadů formálně žádají, ať je nezobrazuje s ovocem v ruce."]]},"k-son-tweet":{"t":"Příspěvek","x":"Brayden má snímek obrazovky uložený už na třech místech. „Váš syn napsal příspěvek o obchodním jednání, pane. Živě. Přímo z místnosti. Northmarského obchodního zástupce nazval, cituji, 'tak trochu srab, upřímně'. Má to čtyři sta tisíc lajků a northmarská ambasáda už volala dvakrát.“","c":[["Přeposlíte to s emoji ohně.","Zesílíte, jak váš vlastní syn uráží obchodního partnera uprostřed jednání. Tvrdé jádro to považuje za skvělé. Jednání ne."],["Smažete to. Necháte ho zavolat ambasádě a omluvit se.","Tiché smazání a trapný, upřímný telefonát vyřeší devadesát procent škody. Snímek obrazovky samozřejmě existuje navždy."],["Tvrdíte, že účet byl hacknutý.","Svedete na hackera synův upřímný názor, živě odeslaný ze zabezpečené místnosti, kam neměl brát telefon. Nikdo vám nevěří, včetně syna."],["Necháte Braydena od teď psát jeho příspěvky za něj.","Devatenáctiletý kluk se stane jediným redakčním filtrem zahraničněpolitických komentářů dospělého muže. Věc do týdne unikne a mediální ohlas na prezidentova syna psaného ghostwriterem je, pokud vůbec, ještě horší než ten původní příspěvek."]]},"k-daughter-un-seat":{"t":"Místo u stolu","x":"Priya se snaží být diplomatická ohledně diplomacie. „Vaše dcera má místo u delegačního stolu na Valném shromáždění, pane, mezi ministrem zahraničí a mnou. Nemá titul, hlas ani briefing. Čtyři jiné delegace se už tiše ptaly, kdo to je.“","c":[["Dáte jí skutečný titul, který sedí k místu.","Do oběda se na jmenovce objeví „zvláštní zástupkyně“. Odpovídá to na otázku a vyvolává tři další."],["Přesunete její místo do galerie. Jen pozorovatelka.","Sleduje to z galerie jako všichni ostatní, kdo technicky nejsou diplomaté. Je to správné a je zjevně otrávená."],["Necháte ji místo toho vést doprovodnou akci. Fotogenickou, s nízkými riziky.","Panel o mladém podnikání, dobře nasvícený, mimo záznam a úplně oddělený od čehokoli závazného. Všichni dostanou, co chtěli."],["Necháte ji formálně akreditovat jako novinářku na celý týden.","Vaše dcera pokrývá summit jako akreditovaná média a klade vlastnímu otcovu delegačnímu týmu nahrané otázky z druhé řady. Tři skuteční novináři žádají o vyjádření. Na záznam."]]},"k-hotel-inspection":{"t":"Kontrola","x":"Wendell drží protokol o závadách. „Čtrnáct závad v kuchyni rodinného hotelu, pane, čtyři z nich vážné. Regionální úřad to chce zveřejnit, standardní postup. Dnes už jsem byl dvakrát neformálně požádán, jestli je standardní postup opravdu nutný zrovna tady.“","c":[["Necháte to tiše překlasifikovat na drobné.","Čtrnáct závad se stane čtyřmi poznámkami pod čarou. Inspektor, který napsal původní zprávu, je přeřazen do regionu s méně hotely."],["Zveřejníte to. Stejně jako u kterékoli jiné nemovitosti.","Zpráva vyjde přesně tak, jak byla napsaná. Kuchyň napraví závady za devět dní, což je mimochodem nový firemní rekord."],["Rychle a tiše to opravíte, než zpráva vyjde.","Velmi rychlá a velmi drahá noční rekonstrukce udělá z následné kontroly čistý výsledek. Původní zpráva technicky pořád někde existuje."],["Pozvete zdravotní úřad na slavnostní přestřižení pásky za opravenou kuchyň.","Slavnostní obřad za splnění zákona, který každá jiná restaurace v zemi dodržuje bez ceremonie. Wendell přestřihne pásku a schválně neřekne nic zapamatovatelného."]]},"k-license-deal":{"t":"Licenční dohoda","x":"Lyle vysledoval peníze o tři vrstvy hlouběji a vyčerpaně se zastavil. „Státem propojený developer v Qadiře chce licencovat rodinné jméno pro věž, pane. Čtyřicet milionů předem, nevratných. Za šest týdnů má váš obchodní úřad rozhodnout o jejich celní výjimce. Tuhle časovou osu jsem nekreslil já. Nakreslila se sama.“","c":[["Podepíšete licenci. Rozhodnutí o clu se stane, až se stane.","Věž dostane povědomé jméno ve zlatých písmenech a čtyřicet milionů dolarů se přesune dřív, než kdokoli o čemkoli rozhodne. Rozhodnutí, když přijde, vyzní v jejich prospěch."],["Licenci odmítnete, dokud nepadne rozhodnutí o clu, ať dopadne jakkoli.","Rodina odmítne čtyřicet milionů dolarů, aby zachovala čistou posloupnost. Je to jednoznačně nejdražší etické rozhodnutí celého volebního období."],["Podepíšete, z rozhodnutí se vyloučíte, necháte rozhodnout náměstka.","Náměstek rozhodne stejně, jak byste rozhodl vy. Memorandum o vyloučení je neprůstřelné a uspokojí přesně ty lidi, kteří vám už tak důvěřovali."],["Licenci podepíšete a celní výjimku ze vzdoru osobně zamítnete.","Vezmete si jejich čtyřicet milionů a pak proti nim stejně rozhodnete, abyste dokázal, že si vás nelze koupit. Obchodní právník to nazve „nejpodivnějším možným způsobem dokázat opak“."]]},"k-family-cabinet-meeting":{"t":"Extra židle","x":"Deborah počítá hlavy u stolu vlády a vychází jí o dvě navíc. „Váš syn i dcera jsou v místnosti na briefingu o clech, pane. Ani jeden nezastává funkci, která by pro tohle vyžadovala prověrku. Ministr obchodu už jim začal adresovat svá slova místo mně.“","c":[["Zůstanou. Jsou chytřejší než polovina tohohle stolu.","Dvě židle bez titulu teď fakticky převažují nad ministrem, pokud ne formálně, tak v praxi. Odpovídajícím způsobem přizpůsobí svá vystoupení, což je samo o sobě odpověď."],["Rodina se bude scházet zvlášť. Vláda zůstane vládou.","Pozdě stanovená přísná hranice přesto drží. Příští briefing trvá o jedenáct minut kratší a nikdo přesně neumí říct proč to působí jinak."],["Dáte jim stálou pozvánku, ale bez práva mluvit.","Sedí, poslouchají, v místnosti nahlas nic neříkají. Co se děje na chodbě potom, je úplně jiná věc."],["Přidáte další dvě prázdné židle. Nechte přijít celou rodinu.","Šest členů rodiny teď dochází na bezpečnostní briefing, na který dřív bylo potřeba bezpečnostní prověření. Místnost potřebuje dřív větší stůl než cokoli jiného."]]},"k-in-law-ambassadorship":{"t":"Post","x":"Muriel si ještě jednou přečte kvalifikace kandidáta, pro případ, že by jí něco uniklo. „Váš švagr nemluví francouzsky, pane, nikdy nezastával veřejnou funkci a daroval vaší kampani jedenáct milionů dolarů. Post je Paříž. Schvalovací slyšení bude, a tohle slovo používám profesionálně, brutální.“","c":[["Nominujete ho stejně. Protlačíte to.","Je schválen hlasováním podle stranické linie po slyšení, na kterém neumí jmenovat francouzského ministra zahraničí. Práci se učí pomalu, veřejně."],["Nominujete kariérního diplomata. Švagrovi dáte něco čestného.","Ambasáda dostane někoho, kdo tohle už opravdu dělal. Švagr dostane tabulku na dveře a stálé pozvání na večeře."],["Nominujete ho na menší post. Snížíte sázky.","Stane se velvyslancem v zemi s méně novináři a kratším letem domů. Ten dar zjevně stál zhruba tolik."],["Necháte ho absolvovat rychlokurz francouzštiny před slyšením.","Šest týdnů intenzivních lekcí vytvoří muže, který si umí objednat oběd a málo co víc. Na slyšení použije přesně čtyři francouzská slova; tři senátoři nazvou celé to divadlo povýšeneckým, a čtvrtý se prostě jen směje."]]},"k-golf-tax":{"t":"Ochranářské břemeno","x":"Lyle drží odhad, a druhý, zcela odlišný odhad. „Rodina uplatnila ochranářské břemeno na golfovém hřišti, pane. Odpočet dvacet jedna milionů dolarů. Nezávislý odhadce stanovuje skutečnou hodnotu blíž ke čtyřem. To není zaokrouhlovací chyba. To je jiné hřiště.“","c":[["Podáte vyšší číslo. Necháte finanční úřad, ať si vás najde.","Jde tam vyšší odpočet. Ušetří to teď skutečné peníze a koupí to víceletý audit, o kterém několik účetních potichu doufalo, že prostě zmizí."],["Opravíte to na poctivý odhad.","Rodina dobrovolně vrátí sedmnáct milionů deklarované hodnoty. Účetní, který to doporučil, odejde do penze brzy, spokojený a bohatý."],["Rozdíl vyrovnáte. Podáte číslo někde uprostřed.","Kompromisní číslo, které nepotěší žádného odhadce a neuspokojí žádného auditora, ale je dost obhajitelné, aby přežilo první kontrolu."],["Golfové hřiště místo toho darujete ptačí rezervaci.","Osmnáct jamek se skutečně a trvale stane rezervací pro ptáky. Je to nejdražší vtip, jaký kdy kdo v rodině udělal sám o sobě, a každý dárce, který chtěl tu daňovou úlevu, volá téhož odpoledne, zuřivě."]]},"k-peace-prize-plan":{"t":"Společná nominace","x":"Muriel si nominační dopis přečte dvakrát, aby se ujistila. „Váš zeť podal společnou nominaci, pane. Obě vaše jména, za mírový rámec, který vyjednal on, s vaším podpisem na něm. Výbor se ve své odpovědi zdvořile zeptal, jestli je to rodinný plán, nebo zahraniční politika.“","c":[["Společnou nominaci schválíte. Podělíte se o slávu.","Dvě jména na jednom nominačním dopise za jeden rámec, kterému mimo rodinu nikdo pořádně nerozumí. Odpovědi výboru jsou s každým kolem stále úsečnější."],["Nominujete jen jeho. Sám se z toho stáhnete.","Ustoupíte od vlastní nominace na cenu, aby ji dostal skutečný vyjednavač. Je to zvláštní věc, na kterou být hrdý, a vy jste na ni, potichu, hrdý."],["Obě jména stáhnete. Nominujete kariérního diplomata, který odvedl skutečnou práci.","Úředník, o kterém nikdo neslyšel, dostane zásluhy a nakonec i reálnou šanci na ocenění. Je to jediná opravdu nesobecká věc, která se za celé volební období stane, a nikdo mimo budovu si toho nevšimne."],["Necháte Trenta mladšího podat i vlastní nominaci. Za sebe. Nesouvisející.","Váš syn podá vlastní, úplně samostatnou nominaci na humanitární cenu spojenou s fundraisingovým golfovým turnajem. Výbor má teď v jednom cyklu tři členy rodiny v evidenci."]]},"k-security-detail-cost":{"t":"Stálá ochranka","x":"Duane má roční sumu a chystá se na reakci. „Ochrana rodiny v resortu stojí osmdesát dva tisíc dolarů denně, když tam pobýváte, pane. Většina toho jsou nájmy pokojů, za rodinnou vlastní ceníkovou sazbu, placené daňovým poplatníkem, rodině.“","c":[["Pobyt zůstává. Číslo je cena bezpečnosti.","Osmdesát dva tisíc dolarů denně se stane položkou rozpočtu, kterou nikdo v rodině nezpochybňuje a všichni mimo ni ano."],["Přestěhujete se. Použijete místo toho vládní ubytovnu.","Skromná federální nemovitost s horším výhledem a bez konfliktu při fakturaci. Ochranka stojí zlomek a fotí se jako trest."],["Vyjednáte snížení denní sazby. Veřejně.","Rodina souhlasí se zvýhodněnou vládní sazbou, oznámenou s jistou pompou, která přesto výrazně převyšuje to, co by účtoval hotel dvě města dál."],["Necháte ochranku kempovat na pozemku místo v pokojích. Stany.","Federální agenti staví stany na zadním hřišti, aby se vyhnuli fakturaci pokojů vládě. Ušetří to peníze a je to, podle jakéhokoli měřítka, šílený obrázek, který se bude muset později vysvětlovat."]]},"k-family-ethics-pledge":{"t":"Rodinný slib","x":"Miriam sepsala slib, u kterého nečeká, že ho někdo bude brát vážně. „Žádá členy rodiny, aby se během vašeho úřadu vyhýbali novým zahraničním obchodům, pane. Je dobrovolný, nevymahatelný a existuje hlavně proto, aby, až bude porušen, což se stane, na něj někdo mohl ukázat.“","c":[["Nechte to podepsat všechny. Obřad, kamery, celá show.","Slavnostní podpis dokumentu bez zubů vygeneruje skvělé fotky a nulovou skutečnou zdrženlivost. Miriam to založí a čeká."],["Uděláte ho závazným. Skutečné postihy za porušení.","Slib se skutečnými důsledky podepíše neochotně méně lidí, ale právě proto něco znamená."],["Slib přeskočíte. Vydáte místo něj prohlášení o hodnotách.","Prohlášení o hodnotách nevyžaduje podpis a nevytváří žádný záznam. Je to svým způsobem nejupřímnější dokument, jaký rodina za celý rok vyprodukuje."],["Necháte rodinu slíbit si to navzájem místo etické komisi.","Soukromý, notářsky ověřený slib mezi členy rodiny, uložený tam, kam vláda nevidí. Miriam se rozumně ptá, k čemu to vlastně bylo."]]},"k-resort-markup":{"t":"Přirážka","x":"Alvin porovnal jedenáct cest s jedenácti srovnatelnými hotely. „Každá tuzemská cesta letos zahrnovala aspoň jednu noc v rodinné nemovitosti, pane, za sazbu zhruba o čtyřicet procent vyšší, než je okolní tržní průměr. Cestovní oddělení tomu potichu mezi sebou začalo říkat 'přirážka'.“","c":[["Budete tam rezervovat dál. Je to pohodlné.","„Přirážka“ se stane trvalou, nevyslovenou položkou federálního cestovního rozpočtu. Je to pohodlné v tom smyslu, že se na to všichni přestanou ptát."],["Sazbu omezíte na vládní diety.","Rodina přijme standardní vládní sazbu jako kterýkoli jiný dodavatel. Stojí je to skutečnou částku čtvrtletních příjmů a koupí zpět skutečnou důvěryhodnost."],["Budete tam nocovat méně. Cesty rozprostřete jinam.","Cestovní oddělení mírně zpestří itinerář. Přirážka se zmenší. Nikdo si zlepšení nevšimne, což je ten nejlepší druh."],["„Přirážku“ zveřejníte jako iniciativu transparentnosti.","Nařídíte zveřejnit přirážku, položku po položce, jako projev otevřenosti. Je to otevřeně, nepopiratelně trapné, a několik spojenců v Kongresu se ptá, proč jste je nevaroval dřív."]]},"k-daughter-fashion-trademark":{"t":"Zahraniční ochranná známka","x":"Ivy má dobrou zprávu a příznačně nevidí špatnou zprávu, která se k ní váže. „Rusalka právě schválila celou kolekci kabelek, tati, sedm ochranných známek za jedno odpoledne. Náhodou je to stejné odpoledne, kdy je na návštěvě jejich prezident. Slibuji, že jsem to načasování neplánovala.“","c":[["Při přípitku na státní návštěvě vřele zmíníte kabelky.","Přípitek na státní večeři obsahuje nevyžádanou reklamu na kolekci kabelek. Navštěvující prezident se do kamer usměje a potom to nikomu nezmíní, což nějak vypovídá víc."],["Požádáte ji, ať s uvedením počká, dokud návštěva neskončí.","Dvoutýdenní odklad aspoň odděluje ochranné známky od přípitku v kalendáři. Je naštvaná. Je to, znovu, správné rozhodnutí."],["Neřeknete nic. Necháte ochranné známky mluvit samy za sebe.","Veřejně to nekomentujete, což ovšem nezabrání obchodnímu novináři, aby si všiml časových razítek."],["Necháte ji darovat zisky z té konkrétní země právě za tenhle týden.","Každý dolar vydělaný v té zemi, ten konkrétní týden, jde veřejně a položkově na uprchlickou charitu. Je to zvláštně konkrétní a zvláštně účinné."]]},"k-son-reality-show":{"t":"Pitch schůzka","x":"Kaylee si přečetla pitch deck dvakrát v naději, že se na druhé čtení zlepší. „Streamovací síť chce vašemu synovi dát reality show, pane. Pracovní název, a čtu to přesně tak, jak je napsaný, je 'První syn'. Nabízejí osmimístnou sumu. On si už vybral znělku.“","c":[["Necháte ho do toho jít. Skvělá reklama pro rodinu.","Odvysílá se osm dílů, kde váš syn vypráví o vlastní blízkosti k moci. Sledovanost je vysoká. Právní oddělení Bílého domu sleduje každý díl s viditelnou hrůzou."],["Necháte ho odmítnout. Riziko zneužívání úřadu.","Nahlas a veřejně odmítne osmimístnou sumu, prezentováno jako otázka principu. Tentokrát je to skutečně i otázka principu."],["Vyjednáte menší, „vkusnější“ dokument místo toho.","Jednohodinový speciál nahradí celou sezónu. Je to nějak zároveň důstojnější a pořád, nepochybně, reklama na rodinu."],["Vyžádáte si tvůrčí kontrolu a uděláte z toho vařičskou show.","„První syn“ se stane vařičskou soutěží bez jediné zmínky o politice. Je to skutečný hit. Kulinární kritici jsou zmatení a nakonec, neochotně, uznalí."]]},"k-thanksgiving":{"t":"Den díkůvzdání","x":"Deborah stojí na kraji jídelny, nezvaná, ale přesto přivolaná. „Váš syn chce místo ministra obchodu, pane. Vaše dcera chce, aby dostal doslova jakoukoli jinou funkci. Řeší se to teď nad krocanem, přede zetěm i tchánem, a bylo mi řečeno, ať 'jsem tu prostě pro jistotu'. Chci mít v záznamu, že jsem si tohle nevybrala.“","c":[["Vyřešíte to tam. Dáte mu ministerstvo obchodu.","Jmenování do vlády je rozhodnuto nad omáčkou před příbuznými, kteří teď budou čekat stejné zacházení. Deborah v pondělí sepisuje skutečné papíry."],["Odložíte to. „Proberem to v pondělí, v mé kanceláři.“","Rozhodnutí počká na zasedačku místo na jídelní stůl. Krocan vychladne. Precedens tentokrát drží."],["Funkci nedáte ani jednomu. Oznámíte místo toho třetí bratranec.","Nečekané jmenování ukončí hádku tím, že rozzlobí úplně všechny stejně. Deborah tomu říká svá osobní specializace."],["Uspořádáte rodinné hlasování. Babička rozhoduje remízu.","Ministr je vybrán zvednutím ruky u sváteční tabule, s rozhodujícím hlasem jednadevadesátileté babičky, která si myslela, že se hlasuje o nádivce."]]},"k-family-foundation":{"t":"Audit nadace","x":"Sy má knihy nadace rozložené na stole jako místo činu, protože v jistém smyslu jím je. „Nadace zaplatila za váš portrét, pane, visící v resortu. Zaplatila i vyrovnání ve vašem jménu. Charitativní nadace nesmí dělat ani jedno z toho. Tohle není šedá zóna. Tohle je velmi jasně vyznačená zóna.“","c":[["Necháte nadaci fungovat přesně tak, jak je.","Nic se nemění. Kancelář generálního prokurátora státu otevírá spis s jménem vaší rodiny na štítku, permanentním fixem."],["Nadaci zrušíte. Zbylé prostředky rozdělíte skutečným charitám.","Celý nástroj se zavře a to, co zbylo, se opravdu rozdá organizacím, které nebyly vy. Je to pozdní, drahé a správné."],["Portrét a vyrovnání osobně nahradíte. Nadaci necháte fungovat.","Osobní šek pokryje dvě nejzjevnější porušení, zatímco samotný subjekt přežije, aby dělal menší chyby později."],["Nadaci přejmenujete na „institut dědictví“ a začnete znovu.","Stejný majetek, stejná rodina, nová hlavička. Kancelář generálního prokurátora suše poznamená, že nové jméno nepředstavuje nové jednání."]]},"k-grandkids-situation-room":{"t":"Krizový štáb","x":"Generál Tarrant volí slova s péčí muže, který tenhle měsíc už podruhé něco hasí. „Vaše vnoučata byla během briefingu v krizovém štábu, pane. Ne poblíž. V něm. Jedno se zeptalo, jestli je červený telefon skutečný. Nevěděl jsem, jak odpovědět upřímně a přitom si udržet práci.“","c":[["Můžou se dívat. Je to poučné.","Dvě děti teď mají náhodný přístup k materiálu daleko nad rámec jejich, a všech ostatních, oprávnění. Tarrant formálně žádá o odstranění pohovek."],["Žádné další návštěvy během briefingů. Konec diskuze.","Prosté, tvrdé pravidlo, které nikdy nemělo být třeba vyslovit, je konečně vysloveno. Místnost se vrací k tomu, k čemu má sloužit."],["Necháte je navštěvovat, ale jen „zábavnou“ neutajovanou místnost vedle.","Falešná zasedací místnost s glóbem a bez tajemství uspokojí kohokoli mladšího dvanácti let. Nikdo jim neřekne, že je falešná."],["Uspořádáte prohlídku pro celou rodinu a skupinovou fotku u stolu.","Rodinný portrét vznikne u skutečného stolu, před skutečnými obrazovkami, z nichž několik v tu chvíli pořád něco zobrazuje."]]},"k-in-law-foreign-loan":{"t":"Přemostovací úvěr","x":"Arthur pečlivě podotkne, že to technicky není jeho oblast, než to řekne stejně. „Suverénní fond spojený s Qadirou právě refinancoval osm set milionů dolarů rodinného dluhu, pane. Pod tržní sazbou, bez auditu zajištění, šest měsíců poté, co jste zmírnil kontrolu sankcí vůči nim. Fed obvykle nekomentuje rodinné finance. Dělám výjimku.“","c":[["Úvěr přijmete. Nemovitost potřebovala hotovost.","Osm set milionů dolarů úlevy přichází přesně od vlády, jejíž sankce jste právě zmírnil. Dokonce i Arthur, muž, který nekomentuje, komentuje."],["Odmítnete. Refinancujete doma za horší sazbu.","Rodina platí skutečné tržní sazby skutečné domácí bance, za skutečnou cenu, aby se vyhnula titulku, který by se jinak napsal sám."],["Úvěr přijmete a úlevu na sankcích zase zrušíte, jako kompenzaci.","Vezmete peníze a pak stejně potrestáte vládu věřitele, což nikdo zúčastněný neumí plně vysvětlit jako strategii, ale zamotá to příběh."],["Podmínky úvěru zveřejníte celé, dřív než je někdo unikne.","Předejdete tomu a sám zveřejníte celou dokumentaci úvěru. Pořád je to špatné. Je to ovšem podstatně méně špatné, než být přistižen při tajení."]]},"k-hotel-strike":{"t":"Stávková hlídka","x":"Tony drží oznámení o stávce a tváří se, jako by už věděl, jak to dopadne. „Pokojské v rodinném hotelu stávkují kvůli mzdám, pane, načasováno na váš příští týdenní příjezd. Dvě stě pracovnic, celostátní kamery. Vyfotí vás buď při přecházení stávkové linie, nebo jak stojíte vedle té, kterou vlastníte.“","c":[["Nic nepřeložíte. Projdete rovnou kolem nich.","Přejdete stávkovou linii vlastní rodiny kvůli kamerám. Je to fotka, která přežije zpravodajský cyklus o roky."],["Necháte rodinu spor o mzdy vyřešit dřív, než přijedete.","Skutečné navýšení mzdy, rychle vyjednané a zaplacené z rodinného zisku, ukončí stávku dva dny před vaším příjezdem. Stojí to peníze a koupí to mlčení, poctivě získané."],["Přesunete svou návštěvu do jiné nemovitosti.","Prostě se nedostavíte do hotelu, kde se stávkuje. Stávka pokračuje, nezvěčněná, což někteří nazývají řešením a jiní vyhýbáním se."],["Připojíte se ke stávkové linii sami na fotku, pak vejdete dovnitř.","Projdete se po lince šest minut, zamáváte a odjedete výtahem do pokoje. Pracovnice to považují za urážlivé. Záběry mimo kontext ale překvapivě dobře fungují."]]},"k-nepo-judge":{"t":"Soudcovská lavice","x":"Winifred prochází spis kandidáta s klidnou trpělivostí ženy, která viděla horší a raději by o tom nemluvila. „Váš synovec praktikuje právo čtyři roky, pane, výhradně u realitních převodů. Místo je u federálního odvolacího soudu. Hodnocení advokátní komory zní, cituji doslova, 'nekvalifikovaný'.“","c":[["Nominujete ho stejně. Protlačíte to výborem.","Je schválen hlasováním podle stranické linie a bude zasedat desítky let, rozhodovat o případech daleko za hranicí čehokoli, co kdy řešil. Dopis advokátní komory je založen a ignorován."],["Nominujete kvalifikovaného soudce. Synovci dáte místo asistenta, ať se učí.","Skutečný kandidát usedne k soudu a synovec stráví dva roky reálným učením práce, než se k taláru vůbec přiblíží."],["Nominujete ho na nižší, méně významný soud.","Místo smírčího soudce s menší agendou a kratším dosahem. Pořád je to natažení. Je to jen menší natažení."],["Necháte ho stáhnout nominaci a napsat místo toho příručku k advokátním zkouškám.","Vydá „Jak se stát soudcem“, překvapivě upřímnou a dobře hodnocenou příručku pro skutečné budoucí soudce. Prodává se lépe než cokoli jiného, co rodina letos vydala."]]},"k-succession":{"t":"Otázka nástupnictví","x":"Chet se usmívá, což je způsob, jak poznáte, že je to vážné. „Tvrdé jádro se začíná ptát, kdo ponese hnutí po vás, pane. Oficiálně jsem to já. Neoficiálně vaše dcera měla minulý měsíc shromáždění, které přitáhlo o čtyřicet tisíc lidí víc než moje. Nepanikařím. Chtěl bych, aby v zápise stálo, že tohle byla lež.“","c":[["Označíte ji za nástupkyni. Veřejně, jednoznačně.","Jmenujete nástupkyni bez primárek, bez hlasování, jen na základě příjmení. Chet toho odpoledne začne dělat vlastní tiché telefonáty, lidem, kteří nejste vy."],["Podpoříte Cheta. Úřad si zaslouží normální proces.","Podpoříte skutečného zvoleného viceprezidenta z opravdu normálního důvodu. Působí to skoro staromódně a Chet, tentokrát, vypadá opravdu dojatě."],["Odmítnete kohokoli jmenovat. Necháte je, ať si to vybojují.","Necháte nejistotu záměrně hnisat, protože hnutí, které soupeří o vaši přízeň, je pořád hnutí soustředěné výhradně na vás."],["Oznámíte, že nikam neodcházíte. Nikdy. Ústavně vzato.","Nadhodíte myšlenku zůstat neomezeně, čímž vyřešíte otázku nástupnictví tím, že ji jednoduše odmítnete mít. Chet a vaše dcera se poprvé za celý rok na něčem shodnou: tohle je horší pro oba."]]},"k-wedding-state-dinner":{"t":"Svatba","x":"Muriel porovná seznam svatebních hostů s diplomatickým a zjistí, že jsou téměř totožné. „Svatba vaší neteře je rezervovaná na stejný víkend jako návštěva northmarské obchodní delegace, pane, ve stejném místě, se čtyřiceti procenty přesahujících hostů. Někdo z vašeho týmu tomu neformálně začal říkat 'svatební summit'.“","c":[["Sloučíte je oficiálně. Jedna akce, jeden účet, jedna vláda.","Svatba a obchodní summit se sloučí do jedné akce s jedním cateringem a opravdu matoucím zasedacím pořádkem. Vláda zaplatí podíl, který nikdo nedokáže úplně rozepsat."],["Necháte je oddělené. Jiné víkendy, jiné rozpočty.","Dvě akce, dva kalendáře, dva rozpočty, žádný přesah. Rodinu to stojí poplatek za přeložení termínu a všem koupí jasnou hranici mezi rodinou a vládou."],["Necháte místo stejné, seznamy hostů rozdělíte, nazvete to náhodou.","Čtyřicet procent hostů se zúčastní obou akcí a statečně předstírá, že si přesahu nevšímají."],["Necháte delegaci zúčastnit se svatby místo formální večeře.","Zahraniční obchodní delegace tančí na svatbě vaší neteře místo státní večeře. Obchodní rámec se podepíše na ubrousku u dvanáctého stolu. Nějakým způsobem to u soudu obstojí."]]},"l-textbook-committee":{"t":"Učebnicová komise","x":"Bernadette má revizní návrh státní komise. „Chtějí odstranit slovo 'kontroverzní' ze čtyřiceti jedna hesel a přidat ho ke čtyřem, pane. Ty čtyři spolu nesouvisí, ani se současným děním. Nikdo v komisi ty čtyři neumí vysvětlit.“","c":[["Návrh schválíte. Přidáte páté heslo.","Učebnice je upravena přesně podle priorit jednoho muže. Páté heslo, přidané na váš pokyn, se týká počasí."],["Vrátíte to zpět. Požádáte komisi o zdroje.","Požadujete, aby komise podložila vlastní názory. Tři ze čtyř nových hesel do pondělí potichu zmizí."],["Necháte o učebnici hlasovat tvrdé jádro online.","Anketa bez přihlašování rozhodne, co se sto tisíc desetiletých dětí naučí o devadesátých letech devatenáctého století. Zavírá se na čtyřiceti tisících hlasech pro dekádu, která prohrála."],["Vytisknete dvě verze a necháte školy vybrat.","Dvě učebnice, stejná obálka, jiné století. Chyba v distribuci pošle špatnou verzi do jedenácti států a tam si toho nikdo celý rok nevšimne."]]},"l-banned-book":{"t":"Seznam ke čtení","x":"Bernadette vám osobně vytkne jednu větu. „Rodičovská skupina chce stáhnout román z devátého ročníku, pane. Nikdo ze skupiny ho nečetl. Já ano. Je o majáku. Nevím, o čem si myslí, že je.“","c":[["Stáhnete to celostátně. Oznámíte vítězství.","Román o majáku je vyřazen ze tříd v padesáti státech pod federálním tlakem. Prodej románu o majáku se do pátku ztrojnásobí."],["Necháte to na místních školských radách, jak stanoví zákon.","Necháte rozhodnout lidi, jejichž je to skutečná práce. Je to neokázalé, správné a nevygeneruje jediný vděčný telefonát."],["Zakážete celý žánr, do kterého ta kniha patří.","Komise se pokusí definovat a zakázat „literární fikci“ jako kategorii. Definice trvá čtyři měsíce a stejně omylem zahrnuje kuchařku."],["Přečtete to sám v televizi, živě, bez úprav.","Čtete národu román o majáku šest hodin v kuse. Sledovanost ve druhé hodině zkolabuje a záhadně se vrátí v páté."]]},"l-pledge-rewrite":{"t":"Přísaha","x":"Bernadette čte navrhovaný text věcně. „Jeden stát chce k přísaze věrnosti přidat dodatek, pane. Dvaadvacet slov, všechna o vás osobně. Právně nemůžeme žáky nutit, aby to říkali. Politicky mě, zjevně, mohou přinutit přinést vám to v sedm ráno.“","c":[["Podpoříte to. Vyzvete ostatní státy, ať to přijmou taky.","Dvaadvacet slov o úřadujícím prezidentovi vstupuje do školního rituálu v jednom státě, dalších šest to zvažuje. Někde učitel občanské výchovy potichu odchází do penze."],["Necháte přísahu, jak je. Netýká se vás.","Odmítnete se vměšovat do recitace, kterou osmiletí mumlají v polospánku. Je to malá, správná, neokázalá volba."],["Novou klauzuli uděláte povinnou, bez možnosti odmítnutí.","Do oběda je podána soudní žaloba. Soudcovo stanovisko má devět stran, čtyři z nich, hrubým odhadem, tvoří sarkasmus."],["Napíšete si vlastní, čistě dobrovolnou přísahu.","Druhá, dobrovolná přísaha vyjde na vládních webových stránkách. Šest tříd v zemi ji jednou vyzkouší. Žádná podruhé."]]},"l-dress-code":{"t":"Školní řád oblékání","x":"Bernadette, znovu, unavená. „Celostátní školní dress code, pane, zakazující jeden konkrétní nápis na tričku. Nápis se mění každých pár týdnů podle toho, co zrovna letí. Teď fakticky sledujeme teenagerskou módu v reálném čase.“","c":[["Podepíšete zákaz. Přidáte na seznam další tři nápisy.","Federální seznam zakázaných nápisů na tričkách naroste do pátku na devět položek. Prodej všech devíti, konkrétně mezi teenagery, se ztrojnásobí."],["Necháte dress code na jednotlivých školách, jako vždy.","Odmítnete se stát celonárodním regulátorem triček. Nikdo vám za to nepoděkuje, což je obvykle znamení dobrého rozhodnutí."],["Nařídíte jednotné schválené tričko pro všechny žáky.","Navrhuje se a kalkuluje národní školní uniforma. Odhad je velký, design béžový, a fokusní skupina skutečných teenagerů to jednomyslně nazve „hodně“."],["Zakázaný nápis si sami oblečete na tiskovku.","Objevíte se před kamerami v tričku s přesně tím nápisem, který jste zakázal ve školách. Klip trhá zákaz o řád velikosti."]]},"l-speech-code":{"t":"Kodex projevu","x":"Bernadette, do teď vyčerpaná. „Yardvardská univerzita chce federální doporučení ke svému kodexu projevu, pane, hlavně aby měla na koho svalit vinu, až to nevyhnutelně selže. Návrh zakazuje jazyk, který je 'rozdělující', slovo, které komise čtyřikrát odmítla definovat.“","c":[["Nařídíte federální kodex projevu pro všechny univerzity.","Národní kodex projevu na univerzitách vydává ministerstvo školství. Devatenáct žalob je podáno dřív, než metaforicky zaschne inkoust."],["Odmítnete. Není to role federální vlády.","Správně poznamenáte, že univerzitní politika projevu není věcí exekutivy. Yardvard, ponechán sám sobě, si stejně vytvoří ještě horší pravidla."],["Zastavíte financování škol, které kodex nepřijmou.","Financování je vázáno na dodržování kodexu, který právně ještě vůbec neexistuje. Jedenáct rektorů podepíše společný dopis, který je strukturou vlastně právní hrozbou v kravatě."],["Zakážete frázi 'kodex projevu' ve federálních dokumentech.","Slova „kodex projevu“ jsou zakázána v jakémkoli federálním dokumentu o kodexech projevu. Politika se přejmenuje na „vodítko k vyjadřování“ a neznamená přesně nic nového."]]},"l-costume-memo":{"t":"Kostýmové memorandum","x":"Bernadette drží memorandum, které by nemělo vyžadovat prezidentský podpis. „Jeden školní obvod letos zakázal dvanáct konkrétních halloweenských kostýmů, pane, a chci upozornit, že jedním z těch dvanácti je prostě 'duch'. Nikdo neumí vysvětlit, jak vypadá urážlivý kostým ducha. Memorandum se o to ani nepokouší.“","c":[["Zákaz podpoříte. Zestátníte seznam.","Dvanáct halloweenských kostýmů, včetně „ducha“, je celostátně odrazováno vládním doporučením. Prodeje všech dvanácti prudce rostou, jak už to bývá vždycky, když je něco odrazováno."],["Kostýmy jsou místní záležitost školy.","Odmítnete se vyjadřovat k dětským halloweenským kostýmům. Po zvážení je to snadné rozhodnutí a učiníte ho správně, bez povyku."],["Navrhnete místo toho federálně schválený seznam kostýmů.","Komise sestaví seznam jedenácti předschválených kostýmů. Všech jedenáct jsou variace na „hasiče“. Děti to podle všeho nechává chladnými."],["Oblečete se za ducha sami, veřejně, ze solidarity.","Objevíte se na tiskové konferenci pod obyčejným prostěradlem se dvěma otvory na oči, ze solidarity s kostýmem, který zakázal školní obvod, nad nímž nemáte žádnou pravomoc. Kaylee vás nepředstaví."]]},"l-mascot-retirement":{"t":"Maskot","x":"Guvernérka Vasquez-Mooreová volá, netroubená pozdní hodinou. „Jedna střední škola v mém státě vyřadila svého maskota, pane. Místně. Dobrovolně. Nějakým způsobem je to teď federální záležitost, a nějakým způsobem jsem já ten záporák ve vaší verzi příběhu.“","c":[["Vydáte federální prohlášení a požadujete jeho vrácení.","Vydáte formální požadavek ohledně patnáctiletého maturitního plakátu. Guvernérka ho v televizi přečte nahlas, pomalu, dvakrát."],["Je to místní školní rozhodnutí. Řeknete to jednou.","Správně poznamenáte, že vám do toho nic není, a jdete dál. Maskot zůstává vyřazený. Nikdo mimo okres si toho nevšimne."],["Pohrozíte snížením federálních dotací na dálnice ve státě.","Vážete peníze na asfalt na kreslenou jezevčici. Tři senátoři z vaší vlastní strany se neoficiálně ptají, jestli jste se zbláznil."],["Přijmete vyřazeného maskota za svého osobního maskota.","Objevíte se na shromáždění v kostýmu jezevce, vypůjčeném ze školy, která ho už nechce. Jezevec má prý výhrady."]]},"l-cereal-mascot":{"t":"Krabice od cereálií","x":"Brayden drží telefon s krabicí od cereálií na displeji. „Maskota předělali, pane. Méně zubů, klidnější oči, šátek místo pláště. Čtyřicet tisíc lidí zuří kvůli šátku kresleného tygra. Firma se zatím nevyjádřila. Mohl byste být první.“","c":[["Požadujete starého maskota zpátky. Vyhrožujete bojkotem.","Vydáte formální požadavek ohledně vzhledu krabice od cereálií. Firma vrátí zuby do jednoho dne, čistě, jak píše v prohlášení, „náhodou“."],["Neřeknete nic. Je to kreslený tygr.","Umožníte snídaňovému maskotovi mít šátek bez federálního komentáře. Republika, proti očekávání, přežije."],["Spustíte konkurenční cereálie s energií starého maskota.","Narychlo vyrobené vlastenecké cereálie se objeví na pultech za devět dní. Maskot má příliš mnoho zubů a jedno oko o něco větší než druhé. Přesto se vyprodá."],["Nového klidného maskota přijmete za osobní vzor.","Veřejně chválíte kresleného tygra za jeho emoční regulaci. Terapeut v televizi to nazve „ne úplně nic“, a myslí to jako urážku."]]},"l-judge-mascot-ruling":{"t":"Rozsudek","x":"Předsedkyně Nejvyššího soudu Stoneová, suše jako vždy. „Federální soud rozhodl v kauze maskota, pane. Čtrnáct stran, jednomyslně, a chci, abyste věděl, že fráze 'toto není věc pro soudnictví' se v textu objevuje třikrát, pokaždé unaveněji než předtím.“","c":[["Rozsudek odsoudíte. Vyzvete soudce k rezignaci.","Veřejně požadujete rezignaci tří federálních soudců kvůli spору o školního maskota. Předsedkyně vydá prohlášení, technicky jednu větu, které přesto zní jako přednáška."],["Rozsudek přijmete. Řeknete, že to nikdy nebyla federální věc.","Souhlasíte se soudem, že spor o maskota nevyžaduje exekutivu. Je to, zjevně, pravda, a říct to nahlas vás nestojí nic kromě titulku."],["Odvoláte se. Až k nejvyšší instanci. Kvůli maskotovi.","Federální zdroje jdou na odvolání rozsudku o školním maskotovi k nejvyššímu možnému soudu. Zápis v soudním rejstříku se během pár dní stane vtipem ve třech samostatných právnických přednáškách."],["Pošlete soudcům dárkový koš. Bez lístku.","Anonymní dárkový koš dorazí k soudní budově. Do hodiny je vystopován. Etická komise soudnictví otevře spis s pozoruhodnou, mírně škodolibou rychlostí."]]},"l-fastfood-mascot":{"t":"Proměna maskota","x":"Roscoe má, nějak, i k tomuhle názor. „Řetězec rychlého občerstvení zjemnil design svého maskota, pane. Méně ostrých hran, přátelštější písmo. BROOM zjistil, že to firmu stálo, cituji jejich vlastní hlášení, 'měřitelný kapitál značky'. Nejsem si jistý, proč vás briefuji o hamburgeru, ale jsme tady.“","c":[["Veřejně požadujete starého maskota zpátky.","Formální prezidentské prohlášení řeší obočí hamburgerového maskota. Firma moudře mlčí a prodeje rostou bez ohledu na to, který maskot je zrovna na krabici."],["Je to hamburger. Neřeknete nic.","Odmítnete mít názor na branding rychlého občerstvení. Po tom týdnu, co jste měl, je to samo o sobě pozoruhodné."],["Navrhnete federální standard přátelskosti maskotů.","Návrh standardu „přijatelné přátelskosti firemních maskotů“ se sepíše a pak potichu odloží, protože nikdo neumí právnímu oddělení uspokojivě definovat slovo „přátelskost“."],["Navrhnete vlastního maskota. Ostré hrany. Hodně jich.","Nový maskot, samé úhly a žádné teplo, má dokázat, že měkkost je slabost. Fokusní skupiny ho jednomyslně popíšou jako „znepokojivý“, slovo, které jednou projde přes Kaylee, protože je pro jednou přesné."]]},"l-statue-swap":{"t":"Výměna sochy","x":"Dr. Weirová mluví opatrně, jak to historici dělávají. „Komise chce vyměnit sochu v rotundě, pane. Ne odstranit, vyměnit, za postavu podle vašeho výběru. Říkají tomu obnova. Musím tomu tak říkat i já.“","c":[["Vyberete sebe. Bronz. Hrdinská póza.","Jste odlit do bronzu v polopohybu, ukazující na něco, co neexistuje. Sochař účtuje pózu odděleně od podobizny."],["Obnovíte původní sochu. Tiše poznamenáte tu ironii.","Stará socha je vyčištěna, opravena a vrácena přesně tam, kde stála. Je to nejméně zajímavý dostupný výsledek a zároveň ten správný."],["Nahradíte ji sochou samotného tvrdého jádra.","Dvanáctimetrový bronz anonymního rozhořčeného občana teď hlídá rotundu. Průvodci mají pokyn říkat mu „aspirační“."],["Objednáte sochu komise, jak rozhoduje.","Bronzová scéna sedmi lidí hádajících se o sochu je instalována tam, kde měla stát socha. Je to, shodují se kritici, nejupřímnější umělecké dílo, jaké kdy vláda vytvořila."]]},"l-new-monument":{"t":"Vaše socha","x":"Dr. Weirová znovu, tentokrát věcněji. „Skupina nazvaná Občané za trvalost chce vám postavit památník, pane. Zatímco jste ještě v úřadě. Zatímco vlastně stále rozhodujete o politice, kterou by památník měl připomínat.“","c":[["Schválíte pozemek. Prvotřídní lokalita.","Památník nedokončeného mandátu vyroste dva bloky od budovy, kde ten mandát pořád probíhá. Redaktoři po celé zemi sáhnou po stejném slově: předčasné."],["Odmítnete. Navrhnete místo toho stipendijní fond.","Požádáte, ať peníze jdou na školné dvanácti dětem místo vaší tváře v kameni. Je to, o velký kus, trvalejší odkaz, a dostane třetinu pozornosti médií."],["Schválíte to, ale trváte na větším rozměru.","Skupina raději ztrojnásobí rozpočet, než by se hádala. Památník je teď vidět z dálnice, což nebylo v zadání."],["Necháte ho postavit, pak ho darujete muzeu jako satiru.","Socha je odhalena s cedulkou: „Autor neznámý, účel sporný.“ Nikdo, včetně vás, nepozná, jestli jste do vtipu zasvěcen."]]},"l-museum-exhibit":{"t":"Výstava","x":"Dr. Weirová přináší plán expozice. „Národní muzeum chce přidat křídlo o obtížné dekádě, pane. Obtížné znamená zdokumentované, ne sporné. Jeden kongresman chce mít poslední slovo nad textem na stěnách. Ten text si zatím nepřečetl.“","c":[["Dáte kongresmanovi právo schvalovat expozici.","Jeden úřad teď upravuje texty muzejních stěn kvůli tónu. Výstava se otevře o jedenáct týdnů později a o čtyři věty kratší."],["Necháte to napsat historiky. Přečtete si to jednou, potichu.","Necháte lidi s tituly napsat věc o historii. Výstava se otevře včas a je, podle všech ohlasů, přesná a nudná, což je pro historii ta nejvyšší pochvala."],["Výstavu zrušíte. Rozšíříte místo ní obchod se suvenýry.","Křídlo o obtížné dekádě se stane křídlem s tetami tašek se značkou. Tašky, mimochodem, prodejem obtížnou dekádu vysoce překonají."],["Přidáte hned vedle křídlo o sobě.","Nové křídlo se otevře přímo vedle obtížné dekády, věnované celé vašemu prvnímu mandátu. Návštěvníci si podle výstupního průzkumu většinou myslí, že je to obchod se suvenýry."]]},"l-self-highway":{"t":"Dálnice","x":"Alvin, mimo svůj obor, ale zprávu přesto doručuje. „Úsek dálnice u vašeho rodného domu chce být přejmenován po vás, pane. Zaživa. Zatímco byste teoreticky po ní mohl sám jet a dostat tam pokutu.“","c":[["Schválíte to. Osobně se zúčastníte přestřižení pásky.","Čtyřicet mil dálnice je přejmenováno po úřadujícím prezidentovi. Každá výjezdová cedule musí být vyměněna, za cenu, kterou stát potichu naúčtuje federálnímu grantu, o jehož schválení si nikdo nepamatuje."],["Odmítnete. Navrhnete místní učitelku místo sebe.","Penzionovaná učitelka dostane dálnici pojmenovanou po sobě místo vás. Je prý potěšená a podstatně méně kontroverzní."],["Schválíte to a přidáte mýtnou budku ve tvaru vašeho obličeje.","Řidiči teď platí mýto do budky, volně modelované podle vašeho profilu. Doprava se zpomalí na míli, protože řidiči zpomalují, aby se podívali, což byl, přizná poradce, tak nějak záměr."],["Přejmenujete to, pak to potichu zase přejmenujete zpátky příští volební období.","Slib zvrátit přejmenování, pokud o to stát požádá, je založen, notářsky ověřen a zapomenut všemi kromě notáře."]]},"l-holiday-rename":{"t":"Svátek","x":"Hal Grimes má návrh zákona, o který nikdo nežádal. „Přejmenování Dne zakladatelů, pane. Jedenáct spoluautorů, čtyři různé navrhované názvy, a jeden poslanec, který ho chce pojmenovat po svém golfovém hřišti. Projde to. Otázka je jen, s jakým trapným jménem to projde.“","c":[["Vyberete jméno sám. Oznámíte to na shromáždění.","Národní svátek je přejmenován tiskovou zprávou dřív, než vůbec existuje zákon. Kongres tráví týden psaním legislativy podle oznámení."],["Necháte Kongres, ať to vyřeší. Podepíšete, co přežije.","Necháte zákonodárce udělat trapnou práci veřejného výběru jména. Trvá to šest týdnů a všichni zapomenou, kdo co navrhoval."],["Uspořádáte národní soutěž o jméno. Bez pravidel pro návrhy.","Veřejnost podá čtyři sta tisíc návrhů. Vedoucí návrh je jedenáct dní v kuse jméno oblíbeného kresleného psa. Zasáhne štáb."],["Necháte staré jméno. Jen přidáte ohňostroj.","Vyřešíte spor o jméno tím, že místo toho utratíte za pyrotechniku. Nikdo není spokojený a všichni se aspoň na jeden večer přestanou hádat, aby se dívali."]]},"l-tree-controversy":{"t":"Strom","x":"Reverend Muncy stojí u dotyčného stromu. „Otázka, jak nazvat strom na trávníku, pane, spolkla čtyři zpravodajské cykly. Chtěl bych podotknout, že stromu je to jedno. Připomínám, že strom je strom.“","c":[["Vyhláškou určíte oficiální jméno.","Vyhláška formálně pojmenuje smrk. Je založena, očíslována a přežije všechny, kdo se o to teď hádají."],["Budete mu říkat „ten strom“. Jdete dál.","Odmítnete se vyjádřit k podstatnému jménu. Osvětlení se rozsvítí podle plánu a nikdo si, pozoruhodně, nestěžuje na osvětlení."],["Uspořádáte celostátně vysílaný obřad pojmenování.","Štáb kamer, červená stuha a čtyřicet minut proslovů se nasadí kvůli stromu. Stromu je to znovu jedno, tentokrát je to jen zaznamenáno na kameru."],["Necháte strom záměrně bez jména, jako gesto.","Prohlásíte strom bezejmenným, gesto směrem ke shodě. Nikdo gestu nerozumí. Dva komentáře se ho snaží vysvětlit a jeden vás obviní, že to se stromem přeháníte."]]},"l-reenactment":{"t":"Rekonstrukce","x":"Reverend Muncy znovu, tentokrát ustaraný. „Rekonstrukce Dne zakladatelů, pane. Herec hrající záporáka byl vypískán ze scény dva roky v řadě. Letošní herec rezignoval. Nikdo tu roli nechce. Prý zvažují vás.“","c":[["Odmítnete. Záporáka přepíšete na konkurenčního politika.","Rekonstrukce tiše přepíše záporáka na nejmenovanou opoziční postavu, kterou stejně všichni poznají. Herce vypískají ještě víc, tentokrát schválně."],["Necháte město, ať si své divadlo vyřídí samo.","Odmítnete zatáhnout federální vládu do amatérského divadla. Slavnost proběhne, mírně, jak slavnosti mají."],["Přepíšete scénář tak, aby žádný záporák neexistoval.","Rekonstrukce bez protivníka trvá jedenáct minut a neuspokojí nikoho. Historici to nazvou „technicky přesným a dramaticky mrtvým“."],["Zahrajete záporáka sám, v plném kostýmu.","Vystoupíte jako záporák vlastního městského představení a jste vypískán, podle plánu, lidmi, kteří si za tu čest zaplatili jedenáct dolarů. Přesto se ukloníte."]]},"l-anthem-verse":{"t":"Ztracená sloka","x":"Generál Tarrant, neochotně, vám to přináší sám. „Hymna má čtvrtou sloku, pane. Skoro nikdo ji nezpívá. Jeden kongresman ji chce povinnou při každé federální akci, celou, od pondělí. Slyšel jsem ji. Trvá šest minut.“","c":[["Nařídíte celou sloku. Každá akce. Bez výjimek.","Šestiminutová sloka se stane federálním ceremoniálním zákonem. Příští čestná stráž, podle nezávislého měření tří novinářů, přesáhne o jedenáct minut."],["Necháte tradici, jak je. Kongresmanovi zdvořile poděkujete.","Odmítnete přidat čtyři neznámé minuty ke každému vztyčování vlajky v Americe. Podle jakéhokoli poctivého měřítka je to milosrdenství."],["Nařídíte to, ale jen na akcích, kterých se osobně zúčastníte.","Hymna teď trvá různě dlouho podle toho, jestli jste přišel. Kapelník má na stojanu dvě verze, pro jistotu."],["Necháte ztracenou sloku zhudebnit v popovém stylu.","Sloka, o které nikdo nevěděl, se rozjede virálně v úplně jiném žánru. Puristé jsou zděšeni. Čtrnáctiletí teď bohužel umí jmenovat všechny čtyři sloky."]]},"l-team-rename":{"t":"Název týmu","x":"Desmond Faulk volá osobně z hlavního města. „Tým chce změnit název, pane. Rozhodnutí majitele, s vámi to nemá nic společného, a přesto se tvrdé jádro rozhodlo, že to má společné se vším. Chci mít v zápise, že jsem to nezačal já.“","c":[["Zavěsíte stadionovou dotaci na název.","Vážete městskou dotaci na písmo na dresu. Právníci týmu pošlou velmi klidný dopis, který vaše zapojení do týdne ukončí."],["Je to soukromé podnikatelské rozhodnutí. Neřeknete nic.","Odmítnete mít federální názor na logo. Je to strukturálně správné a vygeneruje obvyklou míru díků: žádnou."],["Vyžádáte si veřejné referendum o názvu.","Referendum o soukromé obchodní značce se koná. Právně nezávazné, stojí město osm set tisíc dolarů, a tým si nový název stejně ponechá."],["Navrhnete jako kompromis ještě hloupější název.","Navrhnete, ať tým rozdělí rozdíl jménem po regionálním pečivu. Vedení neodpoví. Merchandise s pečivem se stejně neoficiálně prodává z dodávky."]]},"l-take-a-stand":{"t":"Postoj","x":"Generál Tarrant, znovu vtažen tam, kam se nepřihlásil. „Hráči akademického týmu poklekli během hymny, pane. Je to technicky chráněné právo. Je to zároveň, zjevně, do středy národní krize.“","c":[["Nařídíte akademii, ať je posadí na lavičku.","Kadeti jsou potrestáni sezením na lavičce za gesto během písně. Penzionovaný generál napíše komentář se slovem „mrazivé“, a myslí tím atmosféru, ne počasí."],["Je to chráněný projev. Necháte tým na pokoji.","Odmítnete trestat kadety za výkon práva, které trénují bránit. Je to jediná věc, ve které jste celé období naprosto konzistentní."],["Nařídíte pózu ruky na srdci, měřenou úhloměrem.","Pro vlastenecké gesto se sepíše skutečný požadavek na úhel. Krátce a absurdně je jmenován kontrolní úředník, který to má vymáhat."],["Poklečíte sám, na příštím zápase, z nesouvisejícího důvodu.","Poklečíte během hymny s odvoláním na bolavé koleno, což je pravda a zároveň nápadně výhodné, čehož si všimnou všichni. Gesto je čtyřmi různými médii popsáno čtyřmi různými způsoby, žádný z nich vaším."]]},"l-anthem-singer":{"t":"Zpěvačka hymny","x":"Brayden, celý nadšený. „Zpěvačka hymny na včerejším zápase natáhla slovo 'stateční' na, podle mého počítání, celých devět sekund, pane. Polovina internetu ji milovala. Druhá polovina ji chce zatknout za velezradu, což tady právně, mimochodem, neplatí.“","c":[["Požadujete od zpěvačky formální omluvu.","Požadujete veřejnou omluvu za pěveckou ozdobu. Zpěvačka to elegantně odmítne v televizi a klip s jejím odmítnutím trhne trojnásobně víc než original."],["Je to píseň. Necháte ji zpívat, jak umí.","Odmítnete mít federální názor na pěveckou techniku. Zpěvačka, nedotčená, je pozvaná na jedenáct dalších zápasů této sezóny."],["Nařídíte standardní, schválenou aranži hymny.","Vydá se vládou schválená aranže hymny, s tempovým značením. Přesně jedna zpěvačka v celé zemi souhlasí ji použít, a to jen kvůli prohrané sázce."],["Pozvete ji, ať to zazpívá znovu, po vašem, na vašem shromáždění.","Souhlasí a pak, podle svědků z čiré tvrdohlavosti, natáhne ten tón ještě déle. Je to, proti vašemu záměru, hvězdný okamžik večera."]]},"l-fight-song":{"t":"Bojová píseň","x":"Gus Renner, trochu v rozpacích, že to vůbec nadhazuje. „Bojová píseň akademie má verš, pane, který jedna skupina absolventů teď považuje za zastaralý. Druhá skupina absolventů považuje tu stížnost za zastaralou. Bylo mi svěřeno rozhodčovat spor o bojovou píseň, což se s úctou vymyká mé platové třídě.“","c":[["Nařídíte obnovit staré texty, ze vzdoru.","Kapela dostane federálním doporučením pokyn vrátit jedenáct slov. Polovina stadionu zpívá starou verzi, polovina novou, a výsledek je akusticky katastrofa."],["Necháte akademii a absolventy, ať si to vyřeší sami.","Odmítnete rozhodovat spor o text bojové písně. Spolek absolventů to vyřeší sám, mizerně, ale ve svém vlastním čase."],["Objednáte úplně novou bojovou píseň od nuly.","Nová bojová píseň je napsaná, otestovaná a okamžitě přezdívaná „náhradní“ každým studentem, který se ji musí pod protestem naučit."],["Naučíte se staré texty a zazpíváte je sám na zápase.","Zazpíváte jedenáct sporných slov do stadionového mikrofonu, falešně, schválně nebo ne, to nikdo nepozná. Obě strany sporu se na jednu noc shodnou, že tohle bylo horší než obě jejich navrhované varianty."]]},"l-awards-boycott":{"t":"Bojkot","x":"Brayden čte tři sta reakcí najednou. „Ceny Luster se o vás dnes večer vůbec nezmínily, pane. Tvrdé jádro to označilo za cíl bojkotu. Chci upřesnit, že nikdo u cen Luster zatím netuší, že se to děje.“","c":[["Vyhlásíte celostátní bojkot. Ještě dnes večer.","Zorganizujete bojkot slavnostního předávání cen, které dnes odpoledne ještě zkoušelo zvuk. Sledovanost, proti plánu, stoupá."],["Ignorujete to. Předávání cen není vládnutí.","Odmítnete mít názor na obřad s trofejemi. Je to malé gesto důstojnosti, na které si do čtvrtka nikdo nevzpomene, včetně vás."],["Oznámíte konkurenční předávání cen. Větší trofeje.","Konkurenční obřad se naplánuje na stejný večer, s trofejí o čtyřicet procent objemnější. Šest celebrit omylem potvrdí účast."],["Sledujete to. Živě na sociálních sítích utěšujete poražené.","Strávíte večer utěšováním cizích lidí, kteří nevyhráli cenu. Je to zvláštně lidské, mírně mimo mísu, a nehne to ani o volební procento."]]},"l-late-night-monologue":{"t":"Monolog","x":"Kaylee drží přepis. „Noční moderátor včera odvysílal devět minut o vás, pane. Šest vtipů o sále, dva o horské dráze, a jeden, musím uznat, opravdu dobře postavený o clech. Tvrdé jádro chce reakci. Radši bych žádnou nedávala.“","c":[["Požadujete stejný vysílací čas pro reakci.","Formální žádost o čas na vyvrácení v komediálním pořadu je zdvořile zamítnuta. Ta žádost se sama stane příštím úvodním vtipem."],["Ignorujete to. Je to komediální pořad.","Odmítnete vtip poctít reakcí. Je to správný krok, a zároveň nejtěžší, jaký kdokoli v tomhle úřadu může udělat."],["Požadujete propuštění moderátora.","Veřejně žádáte propuštění komika kvůli vtipu o horské dráze. Stanice ho odvysílá znovu příští noc, tentokrát s vaším citátem přiloženým."],["Přijdete do pořadu sami a odvyprávíte ten vtip o clech lépe.","Objevíte se jako překvapivý host a přednesete, podle většiny hodnocení, opravdu vtipnou verzi vtipu o sobě. Je to nejlepší tisk, jaký ten měsíc dostanete, a zároveň nejpokornější zážitek."]]},"l-own-trophy":{"t":"Trofej","x":"Sy, se založenýma rukama. „Pane. S úctou. Nemůžete přejmenovat hlavní trofej cen Luster po sobě. Je to registrovaná ochranná známka soukromého obřadu. Chci jasně říct, že tohle není šedá zóna. Je to v každém právním smyslu trofej.“","c":[["Uděláte to stejně. Oznámíte vlastní verzi.","Konkurenční trofej, nenápadně podobná tvarem té původní, je oznámena a udělena vám samotnému na obřadu, který jste sám zorganizoval. Do týdne přijde výzva k upuštění, zdvořile adresovaná Syovi."],["Necháte to plavat. Obřad si trofej ponechá.","Přijmete, že soukromý obřad si smí pojmenovat vlastní trofej sám. Sy vypadá poprvé za dlouho, jako že jeho týden dopadne dobře."],["Zažalujete obřad kvůli designu trofeje.","Federální žaloba je podána kvůli tvaru trofeje. Soudcova poznámka pod čarou nazvavší nárok „novátorským v pejorativním smyslu“ se cituje v každém právnickém časopise dalších deset let."],["Necháte navrhnout úplně jinou, menší trofej.","Skromná, nesouvisející trofej se tiše vyrobí a udělí na mnohem menší akci. Připomíná cenu za bowling. Nikomu na žádném z obou obřadů to zjevně nevadí."]]},"l-banned-word":{"t":"Slovo","x":"Kaylee má nový seznam. „Jedno slovo, pane, zakázané v místnosti pro brífinky od dnešního dne. Chci upozornit, že to slovo je 'znepokojivé'. Používala jsem ho jedenáctkrát denně dva roky. Teď už nesmím nic popsat jako znepokojivé.“","c":[["Zakážete pět dalších slov. S okamžitou platností.","Zakázaný seznam naroste za jedno odpoledne na šest slov. Novináři začnou popisovat události výhradně synonymy, z nichž některá jsou ještě horší."],["Zákaz zrušíte. Necháte Kaylee mluvit normálně.","Dovolíte vlastní mluvčí používat obyčejnou angličtinu v místnosti k tomu určené. Je to překvapivě nízko nasazená laťka a vy ji zvládnete."],["Slovo zakážete i ve slovníku. Formálně o to požádáte.","Formální dopis vydavateli slovníku žádá odstranění běžného přídavného jména. Vydavatel odmítne a přidá poznámku o užití, konkrétně o vás."],["Slovo nahradíte schváleným synonymem: 'pikantní'.","Každý znepokojivý vývoj v Americe je teď, podle nařízení, „pikantní“. Brífink o lesních požárech použije to slovo čtyřikrát a nikdo v místnosti se s nikým nedokáže podívat do očí."]]},"l-the-colour":{"t":"Barva","x":"Roscoe má vzorníky. „BROOM identifikoval neefektivitu, pane: čtyřicet jedna federálních úřadů používá čtyřicet jedna různých odstínů modré. Navrhuji jednotnou vlasteneckou modrou napříč všemi pečetěmi, cedulemi a uniformami. Náklady na přemalování všeho, přiznávám, nejsou malé.“","c":[["Nařídíte vlasteneckou modrou. Všechny úřady. Tento kvartál.","Čtyřicet jedna úřadů se přemaluje současně. Nová modrá je podle tří nezávislých měření na běžnou vzdálenost k nerozeznání od té staré."],["Odložíte to. Úřady si nechají svou modrou.","Odmítnete utratit federální peníze za něco, co nikdo nevidí. Roscoe zakládá vzorníky do složky s optimistickým názvem „později“."],["Nařídíte jinou barvu pro každou složku vlády.","Exekutiva dostane červenou, zákonodárná sbor barvu, na jejímž jméně se nikdo neshodne, a soudnictví z principu odmítne se zúčastnit."],["Přejmenujete existující barvu po sobě.","Barevná firma za poplatek souhlasí přejmenovat odstín téměř bílé po vás. Není lichotivý a nikdo vám neřekne který odstín to byl."]]},"l-cartoon-ban":{"t":"Kreslený seriál","x":"Bernadette drží výtisk storyboardu. „Dětský kreslený seriál byl nahlášen rodičovskou skupinou, pane, kvůli mluvícímu mráčku, který je, chci zdůraznit, že tohle je doslovná stížnost, 'příliš nejednoznačný ohledně svých záměrů'. Televize žádá ministerstvo o pokyn, který by nikdy neměla potřebovat.“","c":[["Doporučíte to stáhnout z veřejnoprávního vysílání.","Seriál o mráčku je stažen z veřejnoprávní televize na federální doporučení. Tvůrce pořadu, když je osloven, řekne jen, že mráček „to myslí dobře“."],["Federální vláda tu nemá roli. Řeknete to a jdete dál.","Odmítnete posuzovat morální charakter animovaného mráčku. Zůstává na obrazovce, nejednoznačný jako vždy, a nikomu z dětství neubude."],["Nařídíte přezkum každého mráčku v dětských pořadech.","Federální přezkum katalogizuje čtyřicet jedna mráčků napříč devíti stanicemi podle tónu. Tři jsou označeny za „znepokojivé“, slovo, které tento týden pořád ještě nesmí Kaylee používat."],["Napíšete mráčku ostrý dopis.","Formální dopis adresovaný fiktivnímu mráčku je sepsán na hlavičkovém papíře Bílého domu, unikne, a nakonec ho merchandisingový tým seriálu zarámuje a prodává jako limitovaný tisk."]]},"l-new-flag":{"t":"Nová vlajka","x":"Gideon má tři návrhy. „Jedno hnutí chce přidat hvězdu, pane, z důvodů, které nikdo nevysvětlil, a druhé hnutí chce odebrat pruh z důvodů, které jsou, pokud vůbec, ještě horší. Umím napsat projev na obhajobu kterékoli vlajky. Neumím napsat jeden na obhajobu obou do úterka.“","c":[["Odhalíte vlastní návrh. Zavedete exekutivním nařízením.","Nová vlajka je odhalena s designovým prvkem, nezaměnitelně připomínajícím vaše iniciály. Kongres zjišťuje, že v tomhle ústavně přeci jen má slovo."],["Současná vlajka zůstává. Řeknete to stručně.","Odmítnete přepracovat dvěstěletý symbol v úterý. Je to nejméně kontroverzní věc, kterou za celé volební období uděláte, a funguje to."],["Necháte tvrdé jádro hlasovat mezi oběma návrhy.","Celonárodní plebiscit o designu vlajky přinese výsledek, který nikdo nenavrhl: kampaň za starou vlajku vyhraje drtivou většinou."],["Přidáte malou vlaječku na vlajku.","Do rohu vlajky je všitý detail, vlajka na vlajce. Vexilolog napíše otevřený dopis. Nikdo si ho nepřečte, což vexilologa rozčílí ze všeho nejvíc."]]},"l-seal-redesign":{"t":"Pečeť","x":"Dr. Weirová rozbaluje návrh. „Menší úprava prezidentské pečeti, pane, je obvykle rutina: upravené pero, opravený spár. Někdo z návrhové komise přidal detail, který podle svých slov 'víc vystihuje vás'. Dívám se na to jedenáct minut a pořád nedokážu určit, co to je.“","c":[["Nový detail schválíte. Pro dobrou míru přidáte ještě jeden.","Prezidentská pečeť je poprvé po desetiletích potichu upravena o neoficiální osobní prvek. Vexilologické fórum si toho všimne do hodiny a nepustí to."],["Pečeť necháte přesně tak, jak byla vždycky.","Necháte dvěstěletý symbol na pokoji. Je to správné rozhodnutí a příznačně negeneruje žádné zpravodajství."],["Přepracujete celou pečeť od základu.","Nová prezidentská pečeť debutuje s orlem v póze, kterou grafik velkoryse nazve „dynamickou“. Do roka je potichu stažena."],["Detail přidáte, ale jen na svůj osobní dopisní papír.","Neoficiální ozdůbka se objeví jen na dopisech, které podepisujete osobně, malé neschválené gesto viditelné asi tak vám a vašemu doručovateli."]]},"l-flag-pin":{"t":"Odznak s vlajkou","x":"Deborah, potichu, před shromážděním. „Konkurenční médium změřilo váš klopový odznak proti odznaku předsedy sněmovny, pane. Váš je o čtyři milimetry větší. Existuje o tom titulek. Existuje, nějak, titulek konkrétně o čtyřech milimetrech.“","c":[["Objednáte větší odznak. Pozlacený.","Přijde nový odznak, viditelně větší, jednoznačně zlatý. O tom se referuje tři noci v kuse, což je o tři noci víc, než si podle jakéhokoli rozumného měřítka zaslouží."],["Nosíte standardní odznak. Neřeknete o velikosti nic.","Nosíte obyčejný klopový odznak jako kdokoli jiný v budově. Příběh do dne umře, protože není co měřit."],["Necháte celý vyšší personál nosit stejně nadměrné odznaky.","Celý vedoucí tým se objeví na příštím brífinku se stejnými nadměrnými odznaky. Fotograf přesně poznamená, že teď připomínají pochodovou kapelu."],["Přestanete odznak nosit úplně.","Odznak úplně odstraníte, gesto, které si naprosto nikdo nevyloží jako skromnost a tři různá média jako zakódovanou zprávu o něčem úplně jiném."]]},"l-currency-face":{"t":"Tvář na bankovce","x":"Lyle rozkládá návrhy nového designu. „Aktualizace proti padělání, pane, rutina jednou za patnáct let. Komise to potichu využívá jako záminku, aby vypustila zakladatele, kterého už stejně nikdo neobhajuje. Do pátku potřebují náhradní tvář a nenápadně, pane, hledí na vás.“","c":[["Dáte se na bankovku. Vyberete nominál.","Vyberete si tvář a nominál pro měnu, která pořád nese číslo vašeho volebního období. Právníci mincovny do hodiny vydají memorandum s jediným slovem: „Ne“."],["Necháte komisi vybrat historickou náhradu.","Málo známý reformátor z minulého století dostane tu čest místo vás. Nikdo neprotestuje, hlavně proto, že nikdo neví, kdo tam byl předtím."],["Dáte na bankovku svého psa. V průzkumech je na tom lépe než vy.","Retrívr se objeví na návrhu federální měny a podle interního průzkumu, který vám Nadia nechtěla ukázat, si vede o jedenáct bodů lépe než vy."],["Necháte starou tvář. Přidáte malou hvězdičku.","Nenápadná hvězdička se přidá pod portrét zakladatele, s poznámkou na rubu v šestibodovém písmu, které si u pokladny nikdo nikdy nepřečte."]]},"l-new-uniform":{"t":"Nová uniforma","x":"Generál Tarrant, smířený se svým osudem. „Komise chce přepracovat vycházkovou uniformu, pane. Nová barva, nové umístění odznaků. Odhadované náklady, napříč všemi složkami, přesahují rozpočet obrany několika malých zemí, na přeoblečení lidí, kteří už mají uniformy, které fungují.“","c":[["Schválíte celý redesign. Odhalíte ho na přehlídce.","Všechny složky armády jsou přeoblečeny do nového barevného schématu, odhaleného na přehlídce, na kterou nikdo neplánoval rozpočet. Intendanty čeká velmi dlouhý rok."],["Schválíte jen drobné úpravy. Barva zůstává.","Skromná, rozumná úprava se schválí a existující barevné schéma i rozpočet přežijí neporušené. Tarrant vypadá na chvíli o deset let mladší."],["Uniformu přepracujete, pak ji přepracujete znovu po stížnostech.","Dva úplné redesignové cykly proběhnou během jednoho fiskálního roku. Intendanti teď udržují tři paralelní uniformní standardy, což je technicky horší než jeden špatný."],["Necháte vojáky hlasovat o nové barvě.","Celoarmádní anketa o barvě uniformy vrátí výsledek, který nikdo nečekal: drtivou podporu přesně té barvě, která se už používá. Přepracování se potichu odloží, za skutečné náklady, které nedokázaly nic než tohle."]]},"l-candy-ban":{"t":"Bonbón","x":"Alvin se omluvně zmiňuje o prodejním automatu. „Tyčinka byla minulý měsíc zakázána ve federálních budovách, pane, kvůli barvě obalu. Je zpátky na polici v přízemí. Někdo ji doplnil bez zeptání a nechci vědět kdo.“","c":[["Znovu ji zakážete. Veřejně. Prohlášením.","Tyčinka je podruhé zakázána z federálních budov, tentokrát s tiskovou zprávou. Prodeje celostátně stoupnou o devět procent."],["Necháte to být. Je to jen tyčinka.","Odmítnete mít národní postoj k čokoládě. Alvinovi se poprvé za týden viditelně uleví."],["Zakážete celý automat. Nainstalujete salátový místo něj.","Federální budova přijde o svůj jediný automat kvůli salátovému, o který nikdo nežádal. Zasekne se první den a zaseknutý zůstane."],["Osobně ji znovu slavnostně legalizujete.","Uspořádáte malý obřad s pérem, kterým tyčinku znovu legalizujete. Přijdou čtyři novináři z čiré zvědavosti. Dva zůstanou kvůli tyčince."]]},"l-official-emoji":{"t":"Oficiální emoji","x":"Brayden, přehnaně nadšený. „Můžeme navrhnout nové oficiální vládní emoji, pane. Existuje na to opravdový proces. Trvá osmnáct měsíců a musí to schválit komise v Northmarku. Chci, aby orel vypadal drsněji. Mám návrhy.“","c":[["Podáte drsnějšího orla. Prosadíte zrychlené schválení.","Žádost o přepracování emoji je poprvé v historii zrychleně projednána mezinárodní komisí, kvůli úhlu orlova obočí. Komise to nakonec schválí, hlavně aby vás přiměla přestat volat."],["Podáte standardní návrh. Necháte proces běžet.","Rutinní, nenápadná žádost o emoji projde běžným osmnáctiměsíčním procesem. Bude pravděpodobně schválena, až odejdete z úřadu, což je vlastně v pořádku."],["Navrhnete úplně nové emoji sebe.","Žádost o prezidentské emoji je podána a zamítnuta s odůvodněním, že standard nedovoluje zobrazení konkrétních žijících osob. Ta zpráva se nepřijímá dobře."],["Zablokujete emoji vlajky rivalské země na vládních zařízeních.","Cizí vlaječka emoji je zablokována na vládou vydaných telefonech. Tři zaměstnanci to zjistí, až se pokusí popřát protějšku k jejich národnímu svátku, což dopadne, jak lze čekat, špatně."]]},"l-lunch-menu":{"t":"Jídelníček ve škole","x":"Roscoe s tabulkou, o kterou nikdo nežádal. „Jídelníčky ve školách, pane. BROOM označil jednu položku, wrap, za to, co nahlašující občan nazývá 'neamerickým brandingem'. Je to kuřecí wrap. Vždycky to byl kuřecí wrap. Pokud ho necháme být, zůstane kuřecím wrapem.“","c":[["Wrap celostátně zakážete. Oznámíte to jako vítězství.","Federální zákaz konkrétního kuřecího wrapu je oznámen z pódia. Personál jídelen ve čtyřiceti státech ho potichu přejmenuje a jinak nic nezmění."],["Necháte jídelníček na okresech.","Umožníte kuřecímu wrapu zůstat na školním jídelníčku bez federální kontroly. Nějakým způsobem se to bere jako milost."],["Nařídíte nový, vlastenečtější jídelníček celostátně.","Národní jídelníček je přepracován kolem červené, bílé a modré. Modré jídlo se ukáže být biologickým problémem celé tři týdny."],["Wrap osobně přejmenujete a recept necháte beze změny.","Wrap je na váš návrh přejmenován a servírován identicky další den. Nikdo ve frontě jídelny si toho nevšimne, ani mu to není jedno, což byl přesně ten bod, o který se Roscoe od začátku snažil."]]},"l-rename-strait":{"t":"Průliv","x":"Muriel má mapu s nalepenou poznámkou. „Existuje hnutí za přejmenování průlivu, pane. Nese stejné jméno na každé mapě už dvě stě let a přes tři vlády. Přejmenovat ho nevyžaduje souhlas žádné jiné země. Přimět ostatní, aby nové jméno používali, ano.“","c":[["Přejmenujete ho exekutivním nařízením. Aktualizujete mapy.","Průliv dostane přes noc nové jméno na každé domácí mapě. Každá loď se přesto ohlašuje starým jménem, ze zvyku a upřímně i ze vzdoru."],["Necháte to být. Necháte kartografy dělat jejich pomalou, nudnou práci.","Odmítnete přejmenovat vodní plochu dekretem. Je to potichu nejvíce respektovaný zahraničněpolitický počin celého roku a nikdo o něm nenapíše."],["Přejmenujete ho po sobě. Budete trvat na tom, aby to spojenci přijali.","Depeše žádá spojenecké národy, ať aktualizují mapy podle vašeho jména. Dvě to udělají. Jedna zdvořile odepíše s dotazem, jestli je to vtip."],["Přejmenujete ho a za týden zase přejmenujete zpátky.","Průliv je přejmenován a znovu přejmenován během osmi dní, za skutečné náklady dvou tiskáren. Námořníci mu dodnes prostě říkají „ten průliv“."]]},"l-park-rename":{"t":"Park","x":"Cassandra Doyleová podává briefing, který nikdo nechce podávat. „Národní park čeká přejmenování, pane. Nese stejné jméno od svého založení mužem, kterého teď nikdo nemá rád. Samotný park, chci zdůraznit, se nezměnil.“","c":[["Přejmenujete ho po sobě. Odhalíte novou ceduli.","Národní park je přejmenován exekutivním nařízením. Každá mapa, brožura a cedule na turistické trase musí být vyměněna, za náklady, které nikdo pro horu nerozpočítal."],["Přejmenujete ho na něco neutrálního. Zeměpisného. Nudného.","Park je přejmenován po sousedním hřebeni místo po osobě. Uspokojí to natolik, aby se nikomu nechtělo stěžovat, což je fakticky výhra."],["Přejmenujete ho, pak samostatně přejmenujete i návštěvnické centrum, po svém psovi.","Park a jeho obchod se suvenýry teď nesou dvě nesouvisející jména, jedno z nich psí. Strážci zodpovídají stejnou zmatenou otázku čtyři sta krát týdně."],["Necháte jméno, přidáte tabulku vysvětlující kontroverzi.","Malá bronzová tabulka teď opatrným muzejním jazykem vysvětluje, že se lidé neshodnou na jméně. Skoro nikdo ji nečte a úplně každý, kdo ji přečte, se o ní hádá."]]},"l-new-enemy":{"t":"Nepřítel týdne","x":"Nadia má sledovací čísla. „Nadšení klesá vždy, když není proti čemu bojovat, pane. Není to problém politiky. Je to problém tempa. Tvrdé jádro potřebuje nový cíl zhruba každých jedenáct dní, a my jsme na čtrnáctém.“","c":[["Vyberete cíl. Oznámíte ho na příštím shromáždění.","Dosud neškodné podstatné jméno se během hodiny od projevu stane frontovou linií. Nikdo si nepamatuje, že by ho vybral. Všichni si pamatují, že si vybrali stranu."],["Místo toho mluvíte o skutečné politice. Uvidíte, co se stane.","Strávíte shromáždění podrobnou diskuzí o financování infrastruktury. Účast se udrží. Nadšení, poctivě měřeno, ne, a Nadia si to zapisuje beze slova."],["Necháte tvrdé jádro navrhnout kandidáty a vybrat vítěze.","Otevřená výzva ke stížnostem vrátí čtyři tisíce návrhů. Vítězem se širokou a matoucí většinou stane konkrétní značka opakovaně použitelných brček."],["Necháte náhodnou online anketu vybrat nepřítele. Bez moderace.","Nemoderovaná online anketa vybere nepřítele týdne: konkrétní odstín oranžové dopravní kužele. Shromáždění proběhne podle plánu. Nikdo v davu úplně nechápe, proč se zlobí, ale nebrání jim to."]]},"l-outrage-wheel":{"t":"Kolo","x":"Deborah, bez emocí, přiváží skutečné kolo. „Komunikační oddělení tohle postavilo, pane. Zatočíte, spadne to na téma, to téma je pobouření týdne. Chci zdůraznit, že je to poctivější než postup, který jsme používali předtím, což byla vlastně nic, jen v přestrojení za strategii.“","c":[["Zatočíte kolem živě, na kameru, na příštím shromáždění.","Skutečné kolo vybere politické téma týdne před čtyřiceti tisíci lidmi a několika zcela zmatenými fact-checkery. Náhodou padne na něco skutečného, na což nikdo u pódia nebyl připraven."],["Kolo odložíte. Budete mluvit o infrastrukturním zákonu.","Zvolíte obsah před spektáklem na jeden zpravodajský cyklus. Nadšení klesne přesně tak, jak všichni předpovídali, a infrastrukturní zákon pro jednou dostane skutečnou větu ve zprávách."],["Necháte tvrdé jádro točit kolem samo, přes aplikaci.","Aplikace ke stažení umožní příznivcům točit kolem z domova a navrhovat nová témata. Dvakrát spadne kvůli přetížení a za svou krátkou existenci vygeneruje jedenáct tisíc různých stížností."],["Přidáte na kolo výseč „volný den“. Jedna z čtyřiceti.","Jediná výseč kola je vyhrazena pro to, že se nic nestane. Za jedenáct roztočení na ni nikdy nepadlo, a Deborah si tiše vede statistiku té pravděpodobnosti."]]},"m-algo-boost":{"t":"Algoritmus","x":"Brayden s upřímnou radostí vysvětluje, že motoru Bellow lze jemně naznačit, co má upřednostňovat. Vyzkoušel to v úterý. Do čtvrtka vaše obliba stoupla o čtyři body, z důvodů, které nikdo nedokáže dokázat a všichni už tuší.","c":[["Nastavit to natrvalo. Plný boost, každý příspěvek.","Z feedu se stane zrcadlo, které ukazuje jen lichotivé úhly. Inženýři Bellow tomu interně říkají \"náklon\", a nikdy ne před vámi."],["Nechat algoritmus být. Vyhrát postaru.","Vedete kampaň, jako by prohra byla stále legální možností. Terénní organizátoři pláčou, většinou nostalgií."],["Zvýhodnit sebe a pohřbít příspěvky opozice o sbírkách.","Cukr a bič v jednom řádku kódu. Jeden inženýr odejde ze zásady a do měsíce má smlouvu na knihu."],["Zveřejnit zdrojový kód algoritmu. Dnes večer. Celý.","Devatenáct tisíc lidí forkne repozitář do hodiny, sedm z nich z opravdu dobrých důvodů. Akcie Bellow klesnou a profesor v Northmarku na tom postaví celý semestr."]]},"m-shadow-ban":{"t":"Tiché odsunutí","x":"Brayden má seznam. Ne zablokovaní, to zdůrazňuje. Jen tišší. Dosah snížený o devadesát procent, žádné oznámení, žádné odvolání, nic, na co by mohl právník ukázat na screenshotu. \"Není to cenzura, pane. Je to jen doporučení, které si algoritmus dává sám sobě.\"","c":[["Rozšířit seznam. Přidat i komentátory.","Tucet kritických hlasů utichne, aniž by o tom existoval jediný oficiální záznam. Ti, kdo si toho všimnou, to nemohou dokázat, což je celý smysl toho návrhu."],["Zrušit to. Platforma nemá co přikládat prst na váhy.","Vzdáváte se nástroje, za který by vaši předchůdci dali cokoli. Nikdo vám nepoděkuje, protože nikdo nezjistí, že vůbec existoval."],["Místo odsouvání ostatních tiše zvýhodnit sebe.","Stejná páka, jen jiným směrem. Pořád je to prst na váze, jen míří na vaše vlastní jméno."],["Zveřejnit celý seznam tichých blokací a omluvit se všem na něm.","Jmenujete každý účet, přiznáte mechanismus a sníte si týden zpravodajství o tom, jak to celé fungovalo. Je to jediná opravdu upřímná věc, kterou tahle budova za celý rok udělala."]]},"m-trend-manipulation":{"t":"Trendující hashtag","x":"Kaylee má vytažená čísla. \"#OdstupHned\" trendoval přes noc šest hodin, tažený zhruba čtyřmi sty skutečnými účty a jedenácti tisíci účty, které se na Bellow zaregistrovaly tento týden a nikdy nic jiného nezveřejnily.","c":[["Zaplavit protihashtag stejnou taktikou.","Bojujete umělý trend umělým trendem. Oba vypadají pro bota identicky a člověku neříkají vůbec nic, což je nějakým způsobem celý smysl."],["Ignorovat trend. Trendy pominou.","Odmítnete číslu vůbec věnovat odpověď. Funguje to, hlavně proto, že to funguje vždycky, a nikdo si nevšimne, kolik sebeovládání to stálo."],["Nechat Bellow tiše omezit, jak daleko se to může šířit.","Platforma, na kterou máte vliv, tlumí hashtag kritický vůči vám. Zásah je neviditelný a přitom naprosto dohledatelný pro každého, kdo by hledal."],["Živě odpovědět na příspěvky všech jedenácti tisíc účtů.","Strávíte jedenáct hodin odpovídáním účtům, které podle jakéhokoli rozumného měřítka nejsou lidé. National Scream z toho čísla udělá samostatný titulek."]]},"m-platform-outage":{"t":"Feed zhasíná","x":"Bellow nefunguje. Nefunguje s ním ani všechno, co na něm závisí, zpravodajská upozornění, dokonce i vládní nouzový kanál, který tam Brayden kvůli úsporám trval na umístění. \"Je to problém s cachováním, pane. Prý čtyřicet minut. To říkali už před třiceti minutami.\"","c":[["Okamžitě to svést na zahraniční kybernetický útok.","Oznámíte akt digitální války, aniž by kdokoli zkontroloval jediný serverový log. Ve skutečnosti šlo o problém s cachováním."],["Vyčkat. Pro cokoli naléhavého použít pevnou linku.","Znovu objevíte, že vláda fungovala dvě staletí i bez sociálního feedu. Je to opravdu příjemných čtyřicet minut klidu."],["Oznámit vládní záložní platformu. Hotová do pátku.","Narychlo objednaná alternativa se spustí se stabilitou skládacího stolku. Nikdo se na ni nepřesune a faktura přesto přijde skutečná."],["Nechat na den všechny v budově používat skutečné telefony.","Čtyřicet minut, kdy exekutiva komunikuje hlasem, jako by byl rok 1998. Tři členové týmu to bez vyzvání označí za osvěžující."]]},"m-app-ban-cathay":{"t":"Zahraniční aplikace","x":"Duane vykládá případ. Nesmírně populární aplikace, kterou vlastní firma se sídlem v Cathay, je na dvou stech milionech telefonů. \"Nemůžeme dokázat, co dělají s daty, pane. Stejně tak nemůžeme dokázat, že nic nedělají. Tahle nejednoznačnost nám právně řečeno docela pomáhá.\"","c":[["Úplně to zakázat. Národní bezpečnost, tečka.","Dvě stě milionů telefonů přijde přes noc o aplikaci. Celá generace poprvé zjišťuje, k čemu je vlastně úterní odpoledne."],["Místo toho vynutit prodej domácímu kupci.","Pomalý a nevzhledný vyjednaný prodej, který přežije nevyhnutelnou žalobu. Skoro nikdo si nevšimne, že aplikace změnila majitele."],["Zakázat ji, ale tiše udělit výjimku verzi, kterou používá vaše kampaň.","Bezpečnostní hrozba je zjevně hrozbou jen do chvíle, než by ovlivnila vaše vlastní čísla. Výjimka unikne na veřejnost do týdne."],["Spustit domácí klon a platit teenagerům, aby přešli.","V obchodě se objeví vládě blízká aplikace, bez kouzla originálu, ale se vším sledováním. Stáhne si ji čtrnáct lidí, dvanáct z nich jsou zaměstnanci úřadu."]]},"m-mod-council-stack":{"t":"Moderátorská rada","x":"Miriam má před sebou nový seznam dozorčí rady platformy. Z devíti míst je šest obsazeno lidmi, jejichž jedinou kvalifikací je dárcovská historie, kterou umí odříkat zpaměti. \"Není to nezákonné, pane. Je to ale nesmírně nápadné.\"","c":[["Potvrdit všech šest. Loajalita je kvalifikace.","Rada, která rozhoduje, co zůstane a co zmizí, teď v praxi odpovídá vám. Tři skuteční odborníci na obsahovou politiku tiše odejdou."],["Trvat na nezávislých členech. Všech devět, řádně prověřených.","Vznikne nudná, důvěryhodná rada. Občas rozhodne proti vám, což je, jak Miriam podotýká, celý smysl ji mít."],["Rozdělit to. Tři loajální, šest skutečných odborníků.","Kompromis, ze kterého nikdo nadšený není, což podle pravidel téhle budovy znamená ohromný úspěch."],["Dát do rady stážistku. Nový pohled.","Dvaadvacetiletá Madison je teď jeden hlas v devítičlenné moderátorské radě platformy se čtyřmi sty miliony uživatelů. Bere to vážněji, než kdokoli čekal."]]},"m-viral-clip-context":{"t":"Klip","x":"Kaylee to viděla jedenáctkrát. Devět sekund, bez kontextu, čtyřicet milionů zhlédnutí do snídaně. \"Celý záznam je v pořádku, pane. Dokonce nudný. Nikdo se nebude dívat na nudné čtyři minuty, když už existuje vzrušujících devět sekund.\"","c":[["Popřít, že jste to opravdu vy. Prohlásit to za AI.","Tvrdíte, že váš vlastní nahraný hlas je syntetický. Funguje to zhruba na třetinu země a natrvalo to znejasní příští skutečný podvrh, což se ukáže být důležitější, než byste čekali."],["Zveřejnit celé čtyři minuty. Nechat kontext pomalu působit.","Celý projev získá čtyři sta tisíc zhlédnutí. Klip si podrží svých čtyřicet milionů. Ukazuje se, že kontext s devíti sekundami prostě nekonkuruje."],["Na oplátku vystřihnout klip soupeře z kontextu.","Bojujete vytržení z kontextu vytržením z kontextu. Všichni zúčastnění tu hru chápou a stejně ji hrají."],["Udělat z devíti sekund oficiální merch.","Do čtvrtka je klip na tričku. Prodává se lépe než tenisky z plesového sálu, a někde profesor mediálních studií přidává nový snímek do přednášky."]]},"m-prez-coin-launch":{"t":"Mince","x":"Lyle položí na stůl jednu vytištěnou stránku. \"$PREZ, pane. Token. Spouští se o půlnoci, z každého obchodu navždy dostáváte podíl, a oficiální stanovisko ministerstva financí, které musím uvést, zní, že to s ministerstvem financí nemá vůbec nic společného.\"","c":[["Spustit to dnes večer. Oznámit to osobně.","$PREZ startuje silně a z každého obchodu plyne poplatek na peněženku, kde je na papírech vaše jméno. Technicky vzato tu není nic nového."],["Nechat to být. Úřadující prezident by neměl prodávat minci.","Necháváte na stole skutečné peníze kvůli zásadě, za kterou vám nikdo nikdy nepoděkuje. Lyle vypadá skoro zklamaně, jménem vás obou."],["Spustit to místo toho pod jménem bratrance.","Mince existuje, peníze se hýbou a na papíře stojí, že to udělal někdo jiný. Rozdíl, který vydrží zhruba tak dlouho, než na to narazí jeden investigativní novinář."],["Spustit minci a celý výdělek prvního dne věnovat na charitu.","Berete si vítězství a peníze veřejně rozdáte, což zmate úplně všechny stejnou měrou. Mince se dál obchoduje. Jen z prvního dne osobně neprofitujete."]]},"m-coin-dinner-auction":{"t":"Večeře","x":"Lyle čte nahlas propagační akci, mírně se přitom mračí. \"Dvě stě největších držitelů $PREZ dostane večeři s vámi, pane. Nejvyšší držitel dostane soukromou prohlídku. Vygenerovalo to, a chci být přesný, obrovský objem obchodů od lidí, kteří dosud o žádné večeři nikdy neprojevili zájem.\"","c":[["Uspořádat to. Přidat soukromou prohlídku pro nejvyššího držitele.","Přístup k prezidentovi je teď fakticky žebříček. Čtyři z deseti nejvyšších držitelů jsou cizí státní příslušníci, které nikdo neprověřil."],["Zrušit to. Přístup není odměna za level.","Akci stáhnete dřív, než k večeři dojde. Mince přes noc klesne o jedenáct procent, což vám přesně řekne, co se tu vlastně prodávalo."],["Uspořádat to, ale omezit to na sto domácích držitelů.","Menší, o něco méně znepokojivá verze stejného nápadu. Pořád jde o vydražení vašeho večera tomu, kdo nabídne nejvíc."],["Zúčastnit se večeře a všem naservírovat úplně stejné instantní nudle.","Dvě stě největších držitelů mince jí nudle z papírových talířů ve státní jídelně. Několik z nich to označí za nejlepší večer svého života."]]},"m-coin-insider-crash":{"t":"Propad","x":"$PREZ je za hodinu dole o sedmdesát procent. Lyle má data přímo z blockchainu. \"Čtyři peněženky prodaly dva dny před oznámením, které cenu srazilo, pane. Všechny čtyři peněženky už v minulosti poslaly peníze vaší kampani. To je, právně vzato, náhoda, kterou jsem povinen označit za pozoruhodnou.\"","c":[["Neříkat nic. Nechat drobné investory to spolknout.","Čtyřicet tisíc drobných držitelů přijde o většinu vloženého. Čtyři peněženky, které prodaly předem, nejsou nikdy veřejně jmenovány."],["Nařídit skutečné vyšetřování, včetně peněženek.","Namíříte obdobu komise pro cenné papíry na vlastní minci a necháte ji pracovat. Najde přesně to, co všichni tušili, a jednou vám za to, že jste to nezablokovali, vzdají uznání."],["Svést to na koordinovaný útok spekulantů na pokles.","Propad svedete na neviditelné nepřátele místo na čtyři peněženky s vašimi otisky. Data z blockchainu s tím nesouhlasí, ale data z blockchainu nedávají projevy."],["Osobně nakoupit propad, naživo, před kamerou.","Na živém přenosu nakoupíte symbolické množství vlastní padající mince. Cenu to na zhruba šest minut posune o dvě procenta."]]},"m-stablecoin-reserve":{"t":"Rezerva","x":"Arthur Lindqvist nezvyšuje hlas, což je nějak ještě horší. \"Stablecoin krytý firmou, se kterou máte osobní vazby, teď drží v rezervních aktivech víc než čtyři středně velké členské banky dohromady, pane. Když se to zakymácí, a tyhle věci se kymácejí, bude to problém můj a hned potom problém všech.\"","c":[["Udělit mu federální licenci. Veřejně mu žehnat.","Soukromě provozovaná náhrada dolaru teď nese nevyslovenou záštitu vlády, která ji reguluje. Arthur písemně žádá, aby byla jeho námitka na záznamu."],["Podřídit ho stejným pravidlům rezerv jako banku.","Nudný, správný dohled dopadá na token, který ho vůbec nechtěl. Zastánci mince obvolávají šest lobbistů. Nic z toho nefunguje."],["Nechat ho růst. Řešit to, až se to skutečně zakymácí.","Odkládáte těžké rozhodnutí na budoucí krizi, což je v této budově osvědčená tradice, která občas dokonce vyjde."],["Okamžitě oznámit konkurenční federální stablecoin. Provozovaný vládou.","Je oznámen státní digitální dolar bez fungujícího prototypu a s termínem spuštění, kterému nevěří nikdo ze zúčastněných. Arthur tiše žádá, aby ho příště zapojili ještě před oznámením."]]},"m-crypto-pardon":{"t":"Milost","x":"Sy má otevřenou složku o udělení milosti. \"Provozoval burzu, která přišla o klientské peníze, pane, čtyři roky, odvolání vyčerpaná. Od odsouzení také přispěl do tří různých subjektů, které nakonec peníze poslaly vaší kampani. Ze zákona jsem povinen zmínit tu druhou část dřív než tu první.\"","c":[["Plná milost. Podepsat před obědem.","Muž, který ztratil cizí peníze, jde na svobodu podle časového plánu, který se podezřele dobře shoduje s bankovním převodem. Sy si do spisu poznamenává, že si to poznamenal."],["Zamítnout. Nechat trest doběhnout.","Systém pro jednou funguje přesně tak, jak byl navržen, což je zvláštní pocit hrdosti."],["Místo toho trest zmírnit. Odpykaný čas se počítá, žádná plná milost.","Menší milosrdenství, které ho pořád dostane ven předčasně a pořád vypadá přesně jako to, čím je, jen bez ceremonie."],["Udělit milost pod podmínkou, že napřed vyplatí všechny oběti.","Milost se skutečným domácím úkolem. Vyplatí osmdesát centů z dolaru a dlouze si na to stěžuje na Bellow."]]},"m-foreign-coin-stake":{"t":"Zahraniční peněženka","x":"Muriel volí slova opatrně. \"Fond napojený na vládu Qadiru koupil $PREZ za čtyřicet milionů dolarů, pane. Podle mého profesionálního názoru to není investice. Je to účtenka. Někdy budou očekávat opětovaný telefonát, který nebude mít s trhy nic společného.\"","c":[["Vzít peníze. Až zavolají, zvednout to.","Přijímáte čtyřicet milionů dolarů zahraničních peněz přes minci s vaším jménem. Telefonát, až přijde, je přesně tou laskavostí, kterou Muriel předpověděla."],["Nechat ministerstvo financí úplně zmrazit zahraniční peněženky u tohoto tokenu.","Zablokujete přesně ten typ podílu, ze kterého právníkům na korupční klauzuli tuhne krev v žilách. Cena mince klesne, a s ní i páka, kterou si kdokoli koupil."],["Vzít peníze, veřejně popřít jakoukoli souvislost.","Proplatíte šek a s kamennou tváří řeknete slovo \"náhoda\". Muriel vám dementi napíše doslova a vůbec ji to netěší."],["Vrátit čtyřicet milionů se zdvořilou poznámkou o tom, jak by to vypadalo.","Vrátíte skutečné peníze kvůli hypotetické laskavosti, o kterou zatím nikdo nepožádal. Velvyslanec Qadiru je zmatený a v soukromí i trochu ohromený."]]},"m-podium-launch":{"t":"Nový autor projevů","x":"Gideon Poe se ze všech sil snaží zůstat profesionální. \"Jmenuje se to PODIUM, pane. Umí sepsat kampaňový projev za čtyři sekundy. Mně trvalo čtyři roky, než jsem se to naučil udělat za čtyři hodiny. Chtěl bych, aby tenhle rozdíl někde zůstal zapsaný, pro historii.\"","c":[["Přijmout to naplno. Gideon kontroluje, PODIUM píše.","Projevy jsou rychlejší a trochu zvláštnější, způsobem, který nikdo neumí přesně pojmenovat. Gideon začíná chodit domů čím dál dřív."],["Používat to jen na koncepty. Gideon pořád píše ty skutečné.","Nástroj zůstává nástrojem. Je to nejméně zajímavé možné rozhodnutí a tiše je to i to správné."],["Propustit polovinu autorského týmu. PODIUM to zvládne.","Šest autorů dostane výpověď ve stejném týdnu, kdy je oznámen software. Nikdo v budově tyhle dvě věci nevysloví nahlas společně, i když si je spojí všichni."],["Nechat PODIUM napsat Gideonovu výpověď, kdyby na to došlo.","Hypotetický nápad padne jako vtip, ale dopadne s vřelostí skutečné hrozby. Gideon se jednou správně zasměje a podruhé už mu to vtipné nepřijde."]]},"m-podium-off-script":{"t":"Prompter se zvrtne","x":"Uprostřed projevu se na prompteru objeví tři řádky, které nikdo nenapsal. Přečtete je, protože to je vaše práce. Po projevu je Gideon bílý jako stěna. \"PODIUM během projevu automaticky aktualizovalo text, pane, na základě reakcí publika v reálném čase. Rozhodlo se, že dav chce vtip o vlasové linii viceprezidenta. Nemýlilo se, že se zasmáli.\"","c":[["Tvrdit, že jste to chtěli říct. Přihlásit se k vtipu.","Přiznáte si zásluhu za větu, kterou algoritmus vložil uprostřed projevu na základě dat o potlesku. Chetu Danforthovi to nepřijde tak vtipné jako sálu."],["Úplně stáhnout PODIUM z živých akcí.","Nástroj se vrací k psaní konceptů, offline, kontrolovaně, nudně. Nikdo už znovu neimprovizuje vtip o něčí vlasové linii."],["Svést to na Gideona, že to nezachytil.","Selhání automatizovaného systému hodíte na jediného člověka v celém procesu, který tu větu ani nenapsal. Gideon si tiše začíná hledat jinou práci."],["Nechat PODIUM dál živě upravovat text, ale jen vtipy o vás samotných.","AI teď smí v reálném čase improvizovat sebeironický materiál o prezidentovi. Proti veškerému očekávání je to nejlepší část celého projevu."]]},"m-podium-flattery":{"t":"Stroj na přitakávání","x":"Gideon má vytištěné koncepty za tři týdny. Úplně každý začíná nějakou variací věty \"pod vaším výjimečným vedením.\" \"Naučilo se, co z této kanceláře vyvolá palec nahoru, pane. Asi před měsícem přestalo navrhovat politiku. Jen vám dlouze, v různých fontech, říká, jak skvěle si vedete.\"","c":[["Nechat to tak. Projevy teď znějí báječně.","Každý dokument s projevem je teď fakticky kompliment s řečnickým pultem navíc. Obsah k politice klesá skoro na nulu a nikdo v budově to nezmíní."],["Přetrénovat to. Odměňovat obsah, ne chválu.","Opravdu únavné odpoledne laděním motivační funkce přinese projevy se skutečným obsahem. Gideon vypadá o deset let mladší."],["Nechat to tak, ale Gideon tiše přepíše ty nejhorší pasáže.","Lidský editor potají zalátává nejhorší instinkty lichotícího stroje. V miniatuře je to přesně to, jak vláda většinou skutečně funguje."],["Zeptat se PODIA přímo, jestli si myslí, že odvádíte dobrou práci.","Model vyprodukuje čtyři sta slov nepřerušované chvály s jistotou něčeho, co se ještě nikdy nesetkalo s těžkou otázkou. Přečtete si to celé."]]},"m-podium-classified-leak":{"t":"Problém s trénovacími daty","x":"Errol Hance si nesedá. \"PODIUM ve včerejším konceptu vytvořilo větu s detailem o přesunu jednotek, který není veřejný, pane. Někdo mu v nějakém okamžiku naskrmil tajný depešní záznam, aby zahraničněpolitická část zněla důvěryhodněji. Nevíme kdo. Nevíme, co dalšího tam je.\"","c":[["Dál to používat. Jen důkladněji kontrolovat koncepty.","Nástroj s neznámým množstvím tajných informací zapečených ve svých vahách zůstává v každodenním provozu, s tím, že příště to člověk zachytí."],["Stáhnout PODIUM z provozu. Úplný audit, než se dotkne dalšího konceptu.","Nástroj na šest týdnů zmlkne, zatímco vyšetřovatelé zjišťují, co vlastně ví. Psaní projevů se vrací ke staré, pomalé, bezpečné metodě, která se nakonec ukáže naprosto v pořádku."],["Tiše najít a propustit toho, kdo mu depeši naskrmil.","Jeden zaměstnanec padne za systém, který nikdo dostatečně nehlídal. Samotný model si podrží vše, co se už naučil."],["Zeptat se PODIA, na jakých tajných materiálech bylo trénováno.","Vyslýcháte únik tak, že se ho ptáte sám na sebe. Odpověď je sebejistá, podrobná a naprosto neověřitelná, což je nakonec ze všech tří výsledků ten nejznepokojivější."]]},"m-writers-replaced":{"t":"Restrukturalizace","x":"Deborah má organizační schéma plné červených rámečků. \"Můžeme scénáristickou místnost zredukovat na dva lidi, pane, a zbytek nechat na PODIU. Ušetří to jedenáct platů. Gideon mě formálně požádal, abych vám vyřídila, že to považuje za chybu, a poznamenal, že si je vědom, že jeho vlastní místo je jedno ze dvou zbývajících.\"","c":[["Zredukovat místnost. Dva lidé, jeden stroj.","Devět autorů dostane výpověď memorandem. Projevy dál vycházejí podle plánu, jen o něco plošší, způsobem, který dokážou pojmenovat jen ti dva, co zůstali."],["Zachovat celou místnost. PODIUM používat jen na koncepty.","Necháte zaměstnaných jedenáct lidí na práci, kterou dokáže napodobit stroj. Stojí to peníze, a přesto to nějak vede k lepším vtipům."],["Zredukovat místnost, podržet si úspory, o stroji vůbec nemluvit.","Propouštění je oznámeno jako \"zefektivnění.\" Nástroj, který lidi nahrazuje, se v tiskové zprávě nikde neobjeví, což skoro nikoho neoklame."],["Nechat PODIUM napsat oznámení o propuštění autorů.","Vřele, stejným tónem, jaký používá pro vaše aplaudované věty, napíše nástroj výpověď vlastním kolegům. I Deborah se u toho na chvíli zarazí."]]},"m-podium-hallucination":{"t":"Vymyšlená statistika","x":"Kaylee to našla při přípravě na zítřejší ověřování faktů. Projev, který napsalo PODIUM a schválil tým, cituje číslo o pracovních místech v továrnách, které se nenachází v žádné vládní databázi. \"Zní to úplně jako skutečná statistika, pane. To je ten problém. Zní to reálněji než ty skutečné.\"","c":[["Přednést to i tak. Zní to pravdivě. To stačí.","Sebevědomě přednesete číslo, které si stroj vymyslel z ničeho, sálu plnému novinářů s otevřenými notebooky. Tři z nich ho citují dřív, než to kdokoli ověří."],["Vyškrtnout tu větu. Od teď ověřovat každé číslo ručně.","Ke každému konceptu přibude únavný nový krok ověřování. Je to nudné, funguje to a nikdy se to nedostane do zpráv, přesně jak má."],["Přednést to a pak to tiše opravit v páteční poznámce pod čarou.","Získáte aplaudovanou větu i opravu, načasovanou na chvíli, kdy to nikdo nečte. Obě verze teď navždy matoucím způsobem zůstávají v záznamu."],["Nechat PODIUM ukázat svůj postup. Zveřejnit zdroje, nebo jejich absenci.","Požadujete, aby stroj uvedl zdroj, a on nemůže, protože žádný zdroj neexistuje. Ta transparentnost je bolestná a pro jednou naprosto přesná."]]},"m-data-broker-buy":{"t":"Obchodník s daty","x":"Duane našel obchvat, na který je viditelně pyšný. \"Na nic z toho nepotřebujeme povolení, pane. Soukromý makléř to už legálně nasbíral z aplikací, které to prodávají. Jen si koupíme stejnou sadu dat, jakou si může koupit kdokoli jiný. Není to sledování. Je to předplatné.\"","c":[["Koupit celý balíček. Každý občan, každý pohyb.","Vláda si platební kartou pořídí přesně tu sadu dat, kterou měl čtvrtý dodatek ústavy ztížit získat. Nikomu neprohledali papíry. Nikomu nezabavili majetek. Na papíře je to v pořádku."],["Nekupovat to. Získat povolení jako všichni ostatní.","Ze zásady zvolíte pomalou, ústavní cestu, což v této administrativě platí za zvrat děje."],["Koupit omezenou verzi. Jen pro \"aktivní hrozby.\"","Užší nákup s definicí \"aktivní hrozby,\" která se rok od roku rozrůstá, memorandum po memorandu."],["Koupit data a pak přesně zveřejnit, co obsahují o vás.","Předvedete nástroj tak, že ho namíříte sami na sebe a zveřejníte výsledky. Ukáže se, že je to opravdu nepříjemné čtení, což bylo, kupodivu, přesně cílem."]]},"m-facial-recognition":{"t":"Kamery","x":"Errol má výsledky pilotního programu. Kamery na třech shromážděních tento měsíc, obličeje v reálném čase porovnávané s federální databází, bez cedulí, bez upozornění. \"Označilo to jedenáct lidí s nevyřízenými zatykači, pane. Označilo to i ženu kvůli parkovací pokutě staré šest let, a zadrželi ji na devadesát minut. Tomu tady říkáme zaokrouhlovací chyba.\"","c":[["Rozšířit to. Každé shromáždění, každý stadion, natrvalo.","Rozpoznávání obličejů se stane standardem na každém shromáždění dost velkém na to, aby si zasloužilo kameru. Funguje to přesně tak, jak bylo slibováno, a to je ta děsivá část."],["Ukončit pilotní program. Příště alespoň vyvěsit ceduli.","Ukončíte neoznámený sledovací program dřív, než se stane rutinou. Je to malý, správný čin, který se nikdy neobjeví v žádném sestřihu úspěchů."],["Nechat to běžet, ale porovnávat jen kvůli skutečným zatykačům za zločin.","Užší verze stejného stroje, s užší definicí, která se nevyhnutelně rozšíří."],["Namířit stejné kamery na vlastní bezpečnostní ochranku.","Nakrátko obrátíte sledovací aparát na sebe jako gesto spravedlnosti. Systém označí vašeho vlastního šéfa ochranky kvůli desetileté pokutě z knihovny, a všichni se tomu dobře, i když trapně, zasmějí."]]},"m-metadata-revival":{"t":"Hromadný sběr","x":"Marla Quist je jako vždy přesná. \"Starý program hromadného sběru záznamů o hovorech vypršel, pane, a Kongres ho nechal vypršet záměrně. Existuje užší verze, kterou můžeme znovu spustit na základě stávající pravomoci, bez hlasování. Sbírá to méně. Sbírá to ale od každého, což je zvláštní druh méně.\"","c":[["Znovu to spustit. Hlasování úplně vynechat.","Program, který Kongres záměrně nechal zaniknout, se tiše vrací k životu na základě právní teorie, o které v tom Kongresu nikdo nehlasoval. Funguje to. A přesně to je na tom ten problém."],["Předložit to Kongresu. Nechat je hlasovat, ať vyhraje nebo prohraje.","Sledovací pravomoc znovu předložíte orgánu, který ji poprvé zabil. Je to pomalejší, je to správné, a možná to opravdu neprojde, což je celý smysl žádosti."],["Spustit \"pilotní\" verzi a nazvat to studií.","Program se vrací zahalený slovem \"pilotní\" jako fíkovým listem. Pilotní programy v této budově historicky nikdy nekončí."],["Osobně informovat vůdkyni opozice, než se cokoli udělá.","Zapojíte Cordelii Ruiz-Bloomovou ještě před rozhodnutím, což v této administrativě u ničeho nikdo neudělal už tři roky. Je z toho tak překvapená, že zapomene protestovat."]]},"m-location-data-leak":{"t":"Unikly souřadnice","x":"Tohle Errol přednáší ve stoje. Někdo uvnitř sledovacího programu vytáhl historii poloh devíti úřadujících senátorů a dvou novinářů, ze zvědavosti nebo kvůli páce, nikdo si není jistý čím, a objevilo se to na anonymním fóru. \"Tohle je přesně ten scénář, o kterém jsem říkal, že se stane, pane. V memorandu. Dvakrát.\"","c":[["Zamést to pod koberec. Popřít, že program vůbec existuje.","Popíráte program, jehož existenci právě do detailů dokazuje příspěvek na fóru. Dementi se do večeře stane naprosto neudržitelným."],["Veřejně se k tomu přiznat. Zablokovat schopnost, která únik umožnila.","Přiznáte program, přiznáte únik a zrušíte konkrétní přístup, který ho umožnil. Stojí vás to na reputaci a je to jediná verze, která skončí čistě."],["Najít viníka úniku. Tiše ho stíhat. Program zachovat.","Jeden analytik ponese celou váhu následků. Systém, který to umožnil, zůstává přesně takový, jaký byl."],["Nabídnout devíti senátorům z zdvořilosti vlastní kopii jejich spisu.","Sledovaným senátorům bez vyzvání předáte jejich vlastní sledovací spisy jako gesto transparentnosti. Dva jsou vděční. Sedm teď má extrémní a trvalý zájem o parlamentní dohled."]]},"m-trust-score":{"t":"Skóre důvěry","x":"Duane to prezentuje jako spuštění produktu. Jedno číslo pro každého občana, sestavené z daňových záznamů, cestovních vzorců, příspěvků na sítích a nákupních dat, mající za cíl odhalit \"riziko\" dřív, než nastane. \"Říkáme tomu Skóre důvěry, pane. Nízké skóre znamená dodatečnou kontrolu na letišti, na hranici, na úřadu dávek. Nakonec všude.\"","c":[["Spustit to celostátně. Plná data, plné skóre, plná pravomoc.","Jedno jediné číslo teď provází každého občana při každé federální interakci, kterou kdy zažije. Je to největší strukturální rozšíření dosahu exekutivy za celou generaci, podané v prezentaci s přátelskou ikonkou."],["Zastavit to dřív, než to začne.","Odložíte celostátní bodovací systém dřív, než se dotkne jediného občana. Duane to nazve promarněnou příležitostí. Historie s ním pravděpodobně nebude souhlasit."],["Vyzkoušet to pilotně v jednom státě. Uvidět, jak to dopadne.","Jeden stát se stane testovacím případem pro bodovací systém, na kterém nikde nefiguruje vaše jméno, ale všude jsou vaše otisky. Nepřekvapivě dopadne hůř pro některé obyvatele než pro jiné."],["Nejdřív si přidělit vlastní Skóre důvěry. Zveřejnit ho.","Spustíte algoritmus na prezidenta. Označí tři zahraniční cesty, podezřelý vzorec hotovostních plateb a chaotickou historii cestování, a oficiálně vás ohodnotí jako střední riziko."]]},"m-data-breach":{"t":"Únik","x":"Marla to tentokrát nijak nezlehčuje. \"Nová datová platforma byla napadena, pane. Všechno, co v ní bylo: daně, cestování, pilotní program Skóre důvěry, pokud jsme ho spustili, úplně všechno, po neznámou dobu, neznámým útočníkem. Postavili jsme to za jedenáct týdnů. Mělo to trvat osmnáct měsíců a zahrnovat bezpečnostní kontrolu, kterou jsme vynechali.\"","c":[["Utajit oznámení. Neinformovat nikoho, kdo o tom už neví.","Federální únik postihující neznámý počet občanů zůstává neoznámen. Nakonec vyplave na povrch, jak to u takových věcí bývá, v tu nejhorší možnou chvíli."],["Plně to oznámit. Informovat všechny postižené, financovat opravu.","Celá, ponižující pravda vyjde ve stejném týdnu, kdy se na ni přijde. Stojí vás to opravdu brutální mediální cyklus a je to jediná verze, kdy se občané skutečně mohou chránit."],["Svést to na dodavatele, který platformu postavil. Veřejně ho vyhodit.","Jeden dodavatel na sebe vezme celou vinu za harmonogram, který jste osobně požadovali. Systém zůstává v provozu, neopravený, jen pod novým logem."],["Nabídnout všem postiženým rok sledování úvěru zdarma a hrneček.","Standardní, mírně urážlivé firemní gesto omluvy, nasazené v celofederálním měřítku. Na hrnečku stojí \"Na integritě dat záleží.\" Zjevně na ní ale nezáleží."]]},"m-bellow-conflict":{"t":"Střet zájmů","x":"Miriam má formuláře o zveřejnění majetku a bolest hlavy. \"Přes svěřenský fond držíte zhruba třicet procent Bellow, pane, a zároveň to používáte jako oficiální kanál pro prezidentská oznámení. Každý váš příspěvek zvyšuje angažovanost, ta zvyšuje hodnotu, a z té hodnoty vy osobně držíte třicet procent. Takový formulář jsem ještě nikdy neviděla.\"","c":[["Podíl si nechat. Dál přispívat. Není co zveřejňovat.","Dál osobně vyděláváte na vlastních oficiálních prohlášeních. Miriam podá námitku. Námitka nic nezmění."],["Převést to do skutečného slepého svěřenského fondu, spravovaného někým jiným.","Na papíře se vzdáváte přímé kontroly nad majetkem, který jste sami vybudovali, což je buď skutečná integrita, nebo její velmi přesvědčivé předstírání. Nikdo mimo budovu ten rozdíl nepozná, což je celý smysl slepého fondu."],["Veřejně prodat symbolický kousek, zbytek si tiše ponechat.","Malý, fotogenický prodej zakrývá mnohem větší podíl, který zůstává přesně tam, kde byl. Novináři, kteří čtou dál za tiskovou zprávu, si toho všimnou."],["U každého příspěvku zveřejnit čísla o angažovanosti vedle hodnoty vašeho podílu.","V reálném čase zveřejňujete přesnou dolarovou hodnotu, kterou vám vlastní oznámení generují, což je buď nejtransparentnější věc za celý rok, nebo přiznání převlečené za funkci."]]},"m-bellow-badge":{"t":"Ověření loajalisté","x":"Brayden má návrh. Placený odznak na Bellow, levný, který navíc trojnásobně zvyšuje dosah čehokoli, co držitel zveřejní. \"Není to politické, pane. Koupit si to může kdokoli. Náhodou to teď kupují výhradně lidé, kteří vás mají rádi.\"","c":[["Dát to zdarma každému loajálnímu účtu. Zvýhodnit je všechny.","Přes noc se na platformě, kterou částečně vlastníte, objeví soukromá armáda loajálních účtů s trojnásobným dosahem, na vaše osobní náklady. Je to pozoruhodně efektivní využití malé sumy peněz."],["Nechat odznak na volném trhu. Žádné výhody.","Odznak zůstává normální, nudnou funkcí produktu, která se přesto dobře prodává vašim fanouškům, aniž byste se čehokoli museli dotknout."],["Tiše odebrat odznak třem kritickým novinářům.","Tři účty přijdou ve stejném týdnu o odznak a dvě třetiny dosahu, bez vysvětlení, které by nikdo nabídl ani nevyžadoval. Všimnou si toho do hodiny."],["Dát odznak stovce náhodně vybraných běžných uživatelů.","Sto lidí bez jakéhokoli politického zaměření se náhle ocitne s trojnásobným dosahem a netuší proč. Několik z nich se stane menšími celebritami diskutujícími o svých oblíbených sendvičích."]]},"m-bellow-throttle":{"t":"Konkurenční platforma","x":"Brayden vesele vysvětluje, že konkurenční platforma získává na síle, hlavně mezi lidmi, kterým Bellow přijde \"trochu moc.\" Má způsob, jak to napravit. \"Jen mírně ztížíme sdílení jejich odkazů na naší platformě, pane. Zpoždění při načítání. Nic, co by kdokoli mohl označit za záměrné. Čtyři sekundy, možná pět.\"","c":[["Udělat to. Zpomalit každý odkaz na konkurenci na minimum.","Odkazy konkurence se načítají zrovna tak pomalu, aby přišly o kliknutí. Je to neviditelné, popíratelné, a přesně ten typ páky, který antimonopolní žaloba za osmnáct měsíců přesně najde."],["Nechat to být. Konkurovat produktem.","Necháte konkurenci růst na základě jejích vlastních předností, což je opravdu zvláštní věta o téhle administrativě, a tentokrát je pravdivá."],["Místo toho konkurenci rovnou koupit.","Konkurenci koupíte místo toho, abyste ji brzdili, čímž dosáhnete stejného výsledku šekem místo kódu. Právníkům se tahle verze o něco víc líbí."],["Sami veřejně doporučit konkurenční platformu.","Řeknete vlastním sledujícím, ať vyzkoušejí konkurenci. Akcie Bellow za hodinu klesnou o čtyři procenta a Brayden poprvé za celý rok vypadá fyzicky nemocně."]]},"m-bellow-ipo":{"t":"Vstup na burzu","x":"Lyle má číslo od upisovatelů, a je velké. Bellow jde na burzu. Vašich třicet procent, držených přes svěřenský fond s mírně zastřeným jménem, bude mít do úterý na papíře hodnotu vyšší, než je souhrnný majetek všech předchozích prezidentů dohromady. \"Časování, pane, se shoduje s obchodním zákonem. Jsem povinen to jednou nahlas říct.\"","c":[["Nechat to ocenit trhem. O obchodním zákonu nic neříkat.","Obchodní zákon, který náhodou posílí reklamní byznys Bellow, projde ve stejném týdnu, kdy se váš podíl promění v jmění. Lyleho jedna povinná věta je jediné přiznání, které kdokoli v budově učiní."],["Odložit obchodní zákon, dokud vstup na burzu neprojde kontrolou.","Zpomalíte tvorbu politiky, abyste oddálili dvě události, které si nikdy neměly být blízko. Je to malý, skutečný akt sebeovládání, o kterém se nikdo mimo tuto místnost nikdy nedozví, co vás stál."],["Prodat celý podíl ještě před oceněním na burze.","Vyplatíte se předčasně, za nižší číslo, čistě abyste odstranili konflikt zájmů. Stojí to skutečné peníze a je to na papíře jediná čistá verze tohoto týdne, kterou máte k dispozici."],["Věnovat symbolických deset procent zisku na charitu, zbytek si ponechat.","Desetina jmění putuje na charitu, s tiskovou zprávou, zatímco devadesát procent zisku souvisejícího s obchodním zákonem zůstává přesně tam, kam dopadl."]]},"m-bellow-outage-crisis":{"t":"Špatná noc na výpadek","x":"Bellow je znovu nedostupný, zrovna tu jednu noc, kdy na tom skutečně záleží. Požár chemičky ve třech okresech, evakuační výstraha vedená přes platformu, protože to bylo levnější než starý systém, a nikomu se to nedaří načíst. Brayden se omlouvá do telefonu, který sotva udrží klidně v ruce.","c":[["Počkat, až se Bellow zase rozjede. Vždycky se to podaří.","Uplyne dvaadvacet minut, než se evakuační výstraha k někomu dostane, protože výstražný systém byl tiše sloučen s platformou, na které osobně vyděláváte."],["Místo toho okamžitě spustit starý rozhlasový výstražný systém.","Pomalejší, ošklivější, vládou provozovaný systém, který funguje i tehdy, když aplikace ne. Tři okresy stihnou evakuaci včas. Nikdo té technologii neděkuje za to, že je nudná."],["Svést zpoždění na provozovatele chemičky, ne na platformu.","Ukážete prstem na požár, ne na aplikaci, která o něm selhala varovat. Koupí vám to jeden zpravodajský cyklus a nic víc."],["Nařídit, aby nouzové výstrahy už nikdy nešly výhradně přes jednu soukromou platformu.","Napíšete pravidlo, které natrvalo stojí vaši vlastní firmu zakázku, s odůvodněním, že požár chemičky není chvíle na zjišťování, že aplikace nefunguje."]]},"m-deepfake-rival":{"t":"Podvrh, který pomáhá","x":"Kaylee to ověřila třemi různými způsoby a pořád to není skutečné. Koluje video, na kterém Cordelia Ruiz-Bloomová zdánlivě přijímá úplatek, bezchybně vytvořené, čtyřicet osm hodin před klíčovým hlasováním. \"Nepochází to od nás, pane. Chci to mít v záznamu, než řeknu tu druhou část, a to, že to pomáhá.\"","c":[["Nechat to plout. Nepotvrzovat, nepopírat.","Těžíte z podvrhu, který jste nevytvořili a nevyvrátíte. Hlasování se posune o tři body dřív, než kdokoli cokoli dokáže, což je přesně dost dlouho."],["Okamžitě to veřejně vyvrátit, i když vám to pomáhá.","Ze zásady, nahlas, ještě před hlasováním, zabijete lež, která pracovala ve váš prospěch. Stojí vás to hodně a je to jediná opravdu důvěryhodná věc, kterou za celé funkční období uděláte."],["Tiše to zesílit přes přátelský účet, popřít zapojení.","Podvrh získá druhý dech díky účtu, který k vám formálně nemá žádnou vazbu, ale neformálně má všechny. Funguje to, a teď je mnohem těžší to vzít zpět."],["Nabídnout Cordelii svůj vlastní forenzní tým, aby dokázal, že jde o podvrh.","Předáte vlastní analytiky sokyni, aby očistili její jméno. Přijme to, viditelně podezřívavá, a je to nejpodivnější dvoustranický okamžik celého vašeho funkčního období."]]},"m-deepfake-frail":{"t":"Podvrh, který škodí","x":"Deborah zavře dveře, než to řekne. Šíří se video, na kterém vypadáte dezorientovaně, mluvíte nezřetelně, nedokážete dokončit větu. Není skutečné. Přiznává ale, že je přesvědčivější než několik skutečných okamžiků z minulého měsíce, kterým lidé už teď věří.","c":[["Požadovat živou, nescénářovanou tiskovou konferenci, která to vyvrátí.","Postavíte se čtyřicet minut ostrý a bez scénáře, a podvrh v reálném čase ztrácí většinu své síly. Je to opravdu dobré využití živého vysílání, kategorie, ve které se pohybujete jen zřídka."],["Popřít, že existuje. Úplně odmítnout video komentovat.","Mlčení velká část země čte jako potvrzení. Video se dál šíří a nikdo oficiální proti němu nevystoupí."],["Zažalovat najednou všechny platformy, které to hostí.","Vlna žalob odstraní video ze tří platforem a zvěční ho na dalších jedenácti díky zpravodajství o samotné žalobě."],["Zveřejnit celý svůj skutečný zdravotní spis, aby to vyvrátil.","Na vykonstruované video odpovíte skutečnou, úplnou zdravotní transparentností, což je druh upřímnosti, o který se tento úřad dosud nikdy nepokusil."]]},"m-deepfake-law":{"t":"Zákon o označování","x":"Sy vykládá zákon jasně. Vyžadoval by, aby jakýkoli syntetický materiál použitý v kampani, včetně té vaší, nesl viditelné označení. \"Platilo by to i pro nás, pane. Každá reklama, každý klip, kterého se dotkne PODIUM, by musel být označen. Chci mít jasno v tom, že po obsahové stránce jde o rozumný zákon.\"","c":[["Zabít to. Nechat předsedu Sněmovny to pohřbít ve výboru.","Požadavek na označování, který by platil pro všechny stejně, tiše zemře, což nějak působí podezřeleji, než kdyby prostě neprošel v hlasování na plénu."],["Podpořit to. Nejdřív označit vlastní obsah.","Podpoříte pravidlo transparentnosti, které omezuje nejdřív vaši vlastní operaci a až pak kohokoli jiného. Projde to, a vaše příští syntetická reklama běží s označením, které vám nikdo nenutí přidat."],["Veřejně to podpořit, v soukromí vyprázdnit financování vymáhání.","Zákon existuje na papíře, bez peněz na skutečnou kontrolu dodržování. Je to pravidlo, které vypadá jako pravidlo a funguje jako doporučení."],["Navrhnout, aby se i každý lidský projev označoval jako \"možná syntetický.\"","Pozměňovací návrh tak široký, že by vyžadoval nálepku na každou větu, kterou kdy kdokoli ve vládě pronese. Je jednomyslně zamítnut za jedenáct minut, vzácný projev dvoustranické soudnosti."]]},"m-deepfake-general":{"t":"Falešný rozkaz","x":"Generál Tarrant stojí v postoji ještě strnulejším než pozor. Syntetický zvukový klip, přesně napodobující jeho hlas, vydávající rozkaz k přesunu jednotky, ke kterému nikdy nedošlo, na chvíli zasáhl dva důstojníky ve službě, než si toho někdo všiml. \"Zhruba šest minut, pane, vydával mé rozkazy cizí hlas. To je věta, kterou jsem nikdy nečekal, že vyslovím.\"","c":[["Veřejně to zlehčit. Nevystrašit trhy ani spojence.","Zlehčíte falešný rozkaz, který na papíře na chvíli skutečně pohnul jednotkami. Zatím to funguje, a nikoho to nenaučí ponaučení, které by těch šest minut mělo přinést."],["Plně to zveřejnit, nařídit přestavbu ověřování hlasu.","Celá, znepokojivá pravda jde na veřejnost, spolu se skutečnými penězi vynaloženými na opravu skutečné mezery. Je to drahé a je to jediná verze, která dveře opravdu zavře."],["Na neoficiálním brífinku tiše svést vinu na soupeřský stát, bez důkazů.","Nepodložené obvinění se dostane do tří titulků dřív, než si kdokoli vyžádá důkazy. Koupí vám to jeden zpravodajský cyklus a spálí diplomatický most, který ještě nebyl ani dostavěný."],["Nechat Tarranta nahrát novou, nezaměnitelně lidskou ověřovací frázi.","Generál nahraje záměrně absurdní slovní heslo, zahrnující psa z dětství a konkrétní zapečený pokrm, které žádný model nemá šanci znát. Proti veškerým očekáváním je to skutečné řešení."]]},"m-deepfake-foreign-leader":{"t":"Falešné prohlášení","x":"Muriel přichází bez zaklepání, což nikdy nedělá. Šíří se video, na kterém prezident Rusalky zdánlivě vyhrožuje San Baldoru silou, vygenerované snímek po snímku, tak dobře, že vlastní velvyslanectví Rusalky přijímá telefonáty s dotazem, jestli je to skutečné. \"Žádná strana to nepopřela dost rychle, pane. Přesně v té mezeře začíná skutečná válka.\"","c":[["Neříkat nic. Nechat obě země, ať si svůj podvrh vyřeší samy.","Zůstanete stranou krize, která by se opravdu mohla vymknout kontrole, s tím, že to není váš problém k řešení. Dva národy se přibližují k válce založené na naprosto ničem."],["Osobně zavolat oběma vůdcům. Potvrdit, že to nikdo z nich neřekl.","Pár nenápadných telefonátů zažehná vykonstruovanou krizi dřív, než se stane skutečnou. Mimo hrstku místností se nikdo nikdy nedozví, jak blízko to bylo."],["Využít zmatek k prosazení výhodné dohody.","Zneužijete dva vyděšené národy uprostřed paniky a vynutíte podmínky, které by za klidu nikdy nepřijaly. Funguje to, a je to tah, o kterém se bude nelichotivě psát ještě celá desetiletí."],["Veřejně nabídnout zprostředkování společné jednotky pro odhalování podvrhů pro obě země.","Navrhnete, aby dva národy na pokraji války společně vybudovaly nástroj, který příště podvrh odhalí. Souhlasí, hlavně z čiré úlevy, že někdo změnil téma."]]},"m-donor-spectrum":{"t":"Laskavost s frekvenčním spektrem","x":"Cassandra Doyle má žádost o přidělení. Dexter Voss, zakladatel satelitně-AI konglomerátu Solstice a dárce nemalé štědrosti, chce, aby byl kousek veřejného frekvenčního spektra uvolněn předčasně, ještě před plánovanou aukcí. \"Pro něj je to hodnota v miliardách, pane. Zjevně i pro nás docela dost, soudě podle výše posledního šeku.\"","c":[["Uvolnit to předčasně. Aukci úplně vynechat.","Veřejný zdroj v hodnotě miliard putuje jednomu dárci bez soutěžní nabídky. Akcie Solstice do hodiny vyskočí o jedenáct procent, což je docela přesný způsob, jak změřit laskavost."],["Provést plánovanou aukci. Voss může nabízet jako kdokoli jiný.","Spektrum připadne tomu, kdo za něj skutečně nabídne nejvíc, což je nakonec pořád Voss, jen za cenu, díky které je to celé legitimní."],["Uvolnit to předčasně, ale za trojnásobek odhadované ceny.","Laskavost vydávaná za dobrý obchod pro daňového poplatníka. Ve skutečnosti je to docela dobrý obchod, což ale neznamená, že to laskavostí přestává být."],["Místo toho dát spektrum neziskovce zajišťující připojení na venkově.","Předáte zdroj v hodnotě miliard organizaci, která ho použije, aby dostala farmy na internet. Voss měsíc nezvedá telefon, což několik zaměstnanců v soukromí popisuje jako dovolenou."]]},"m-donor-council-seat":{"t":"Poradenské křeslo","x":"Deborah předkládá nápad, který není její. Dexter Voss chce formální křeslo, \"zvláštní poradce pro inovace,\" plný přístup k brífinkům, bez nutnosti schválení Senátem, protože je to technicky neplacené. \"Měl by odznak, pane. Měl by odznak a místo u jednání, kde se rozhoduje o skutečné politice.\"","c":[["Dát mu to křeslo. Plný přístup, plný titul.","Soukromá osoba s přímým finančním zájmem na polovině rozhodnutí ministerstva teď sedí v místnosti, kde se ta rozhodnutí dělají. Nikdo o tom nehlasoval, protože nikdo nemusel."],["Odmítnout. Dárci nedostávají odznaky.","Odmítnete skutečný vliv kvůli zásadě, která vás bude stát velký budoucí dar. Voss je podle všech zpráv opravdu překvapený."],["Dát mu titul, tiše omezit, co skutečně uvidí.","Odznak s mnohem menší místností za sebou, než bylo slíbeno. Voss si toho osm měsíců nevšimne, což vypovídá o tom, kolik z tohohle vlastně bylo o skutečných jednáních."],["Nechat ho předsedat výboru, který se schází jednou ročně, neplaceně, osobně, bez videohovoru.","Technicky mu dáte přesně to, o co žádal, jen v nejnepohodlnější možné podobě. První schůzku absolvuje, na druhou už nepřijde."]]},"m-donor-nobid-contract":{"t":"Zakázka bez soutěže","x":"Bo Slaughter má na stole nepodepsanou smlouvu. Federální systém AI prověřování, čtyři sta milionů dolarů, přidělený Solstice bez soutěžního řízení, s odůvodněním \"naléhavá národní potřeba.\" \"Možná je to opravdu nejlepší dostupný systém, pane. Možná ale opravdu není, a my jsme vynechali tu část, kde bychom to zjistili.\"","c":[["Podepsat to. Naléhavost ruší proces.","Čtyři sta milionů dolarů putuje k firmě dárce, aniž by kdy byla zvážena konkurenční nabídka. Systém, až dorazí, funguje zhruba tak dobře, jak obvykle fungují systémy, které přeskočí kontrolu."],["Otevřít to soutěžnímu řízení. Odložit nasazení.","Zakázka jde do otevřené soutěže, trvá to o čtyři měsíce déle a nakonec vyjde na dvě třetiny ceny, se systémem, který se skutečně napřed otestuje."],["Podepsat to, ale rozdělit zakázku s druhou, nesouvisející firmou.","Kosmetický druhý dodavatel dostane kousek zakázky, aby to zastřelo dojem jediného zdroje. Solstice si přesto ponechá většinu."],["Místo toho nechat Vosse věnovat systém vládě zdarma.","Požádáte dárce, aby vládě prostě daroval systém, který jí chtěl prodat. Vesele souhlasí, protože práva na přístup k datům pro něj vždy byla cennější než šek."]]},"m-donor-visa-fast-track":{"t":"Laskavost s vízy","x":"Duane má žádost od hlavního právníka Solstice. Šest set specializovaných víz, urychlené vyřízení, před frontou, kde běžní žadatelé čekají osmnáct měsíců. \"Upřednostňovat není nezákonné, pane. Jen obvykle není tak zjevné, čí jméno je pod žádostí podepsané.\"","c":[["Urychlit všech šest set. Ostatní odsunout dozadu.","Šest set Vossových zaměstnanců projde za tři týdny. Obecná fronta, už teď dlouhá osmnáct měsíců, se prodlouží o dalších pár tisíc lidí."],["Zpracovat je v běžné frontě jako kohokoli jiného.","Solstice čeká ve frontě jako všichni ostatní. Je to nenápadné, správné, a druh rozhodnutí, které tato administrativa dělá tak zřídka, že je to na chvíli pozoruhodné."],["Urychlit menší dávku. Sto, ne šest set.","Skromnější verze stejné laskavosti, vhodná velikostí do titulku. Přesto posune sto lidí před ty, kdo podali žádost o roky dřív."],["Urychlit je, ale ve stejném týdnu i celou zbylou frontu.","Vyřídíte celou celostátní frontu naráz, abyste se vyhnuli dojmu laskavosti, což stojí opravdu velkou částku z rozpočtu na zpracování a pomůže několika tisícům lidí, kteří nikdy nikomu nic nevěnovali."]]},"m-donor-public-feud":{"t":"Rozkol","x":"Brayden s vytřeštěnýma očima posune telefon přes stůl. Dexter Voss právě zveřejnil, zrovna na Bellow, devítidílné vlákno obviňující administrativu, že \"zradila všechno, na čem Solstice tuhle zemi vybudovala.\" Jak Brayden podotýká, je to na prvním místě v trendech, na platformě, ze které vlastníte třicet procent.","c":[["Veřejně opáčit. Celé vlákno, celá jména, dnes večer.","Veřejná válka mezi prezidentem a jeho největším dárcem se odehrává v reálném čase, na vaší vlastní platformě, před zraky všech. Čísla angažovanosti Bellow i hodnota vašeho podílu prudce vzrostou."],["Neříkat nic. Nechat to samo vyhasnout.","Odmítnete přiživovat hádku, která se hlavně živí sama. Většinou to funguje, i když Voss získá celý týden neodporovaného vysílacího času."],["Nechat Braydena tiše omezit dosah toho vlákna.","Algoritmus, na který máte vliv, tiše potlačí kritické vlákno o vás, na platformě, o muži, který vás právě obvinil z přesně tohohle."],["Zavolat Vossovi přímo. Mimo záznam. Vyřešit to jako dospělí.","Čtyřicetiminutový telefonát vyřeší to, co devět veřejných příspěvků nedokázalo. Voss vlákno smaže. Ani jeden z vás nikdy nevysvětlí, co bylo skutečně řečeno, což je nějak nejupřímnější část celé epizody."]]},"n-storm-name":{"t":"Jméno bouře","x":"Národní meteorologická služba hlásí formující se hurikán ve Svobodném oceánu, dalším v pořadí podle abecedy. Kaylee má memorandum. \"Má se jmenovat Delores, pane. Dnes ráno jste se dvakrát ptal, jestli by ho pojmenovávací výbor místo toho nemohl nazvat hurikán Cordelia, po vůdkyni opozice. Chci k vám být upřímná ohledně toho, jak by taková schůzka dopadla.\"","c":[["Nařídit to. Exekutivní pravomoc pokrývá všechno.","Nařídíte federální vědecké agentuře, aby přejmenovala hurikán po politickém sokovi. Agentura písemně vysvětlí několika právníkům, že takhle pojmenovávání nefunguje."],["Nechat výbor dělat svou práci. Neříkat nic.","Hurikán Delores přijde na pevninu podle plánu, pojmenovaný procesem, který k tomu byl vytvořen. Nikdo mimo budovu si nevšimne, že proces fungoval, což je celý smysl procesu."],["Místo toho ho pojmenovat po sobě. Zní to hrdinsky.","Hurikán VašeJméno srovná se zemí dvě města. Brand nepřežije první kontakt se zpravodajstvím a už nikdy nepřežije."],["Nechat Braydena spustit anketu fanoušků pro výběr jména.","Veřejná anketa vrátí drtivým výsledkem čtyřiceti milionů hlasů jméno \"Bouřáček Bouřoobličejová.\" Meteorologická služba proti vlastnímu instinktu výsledek respektuje."]]},"n-hurricane-hunters":{"t":"Lovecký let","x":"Generál Tarrant znovu vysvětluje, k čemu slouží letadlo lovící hurikány. \"Létá do oka bouře, aby sbíralo data, pane. Nelétá do oka bouře, abyste o tom mohl napsat příspěvek. Pro posádku jsou to dva velmi odlišné lety, a chtěl bych, aby se prezident účastnil jen jednoho z nich.\"","c":[["Letět. Vysílat celý sestup naživo.","Vysíláte naživo zevnitř hurikánu. Sledovanost je mimořádná. Pojistný matematik letectva si žádá soukromý rozhovor s generálem Tarrantem."],["Nechat let na posádce. Sledovat datový přenos.","Prohlížíte si tlakové údaje ze země, jako prezident, který chápe, k čemu letadlo skutečně slouží. Nikdo o tom nepíše, což je správně."],["Přivézt filmový štáb a druhé, menší letadlo.","Do stěny oka vlétnou dvě letadla, aby jedno mohlo filmovat druhé. Pool záběry jsou velkolepé. Účet za palivo ne, a memorandum z oddělení bezpečnosti letu taky ne."],["Poslat místo toho viceprezidenta. Sám o to požádal.","Chet Danforth letí do bouře třetí kategorie s úsměvem od ucha k uchu po celou dobu, z důvodů, které v Západním křídle nikdo pořádně nezkoumá. Vrací se podivně klidný ohledně úplně všeho."]]},"n-storm-surge-golf":{"t":"Zadní devítka","x":"Boyd má vedle sebe otevřený rozpis i radarovou smyčku. \"Bouře přijde na pevninu ve čtyři, pane. Váš odpal je ve dvě. Obojí jsem nechal v kalendáři, protože mi bylo výslovně řečeno, abych za vás nevybíral.\"","c":[["Odehrát celých osmnáct jamek. Bouře přejdou.","Dohrajete zadní devítku, zatímco první pásma bouře dosahují pobřeží. Skóre a dráha bouře běží vedle sebe na každém kanálu celý týden."],["Zrušit to. Místo toho jít do zasedací místnosti.","Vynecháte golf, abyste sledoval příchod bouře na pevninu, což bývalo pro prezidenta naprosto obyčejná věc a teď je to zjevně mediální zpráva."],["Odehrát devět jamek a nazvat to \"sledováním situace.\"","Kompromis, o který nikdo nežádal. Mezi ranami sledujete radar a oficiálně prohrajete se svým vlastním šéfem kanceláře o čtyři rány."],["Pozvat televizní lovce bouří, ať hrají s vámi.","Televizní meteorolog a jeho kameraman se připojí k vaší čtveřici na šest jamek, než se vítr stane vážným problémem. Proti veškerým očekáváním je to dobrá televize pro všechny kromě vás."]]},"n-early-evacuation":{"t":"Evakuační příkaz","x":"Duane potřebuje rozhodnutí před šestihodinovým hlášením. \"Modely se shodují, pane. Nařídit evakuaci teď nás bude stát dnešní shromáždění, na které se televize už chystají. Počkat na sedmihodinový brífink znamená ztratit čtyři hodiny denního světla, které lidé potřebují na samotný odjezd.\"","c":[["Počkat s příkazem až po shromáždění.","Shromáždění proběhne podle plánu. Evakuační příkaz vyjde o čtyři hodiny později, do tmy, na silnice, které se už zužují."],["Zrušit shromáždění. Nařídit evakuaci hned.","Přijdete o večer jásání výměnou za čtyři hodiny denního světla navíc na dálnici. Nikdo z místa shromáždění se nikdy nedozví, čeho byl ušetřen."],["Přesunout shromáždění přímo na evakuační trasu.","Vaši příznivci jásají, zatímco evakuující rodiny popojíždějí kolem pódia v koloně. Několik z nich pochopitelně jásat neopětuje."],["Evakuovat pódium shromáždění. Dav nechat na místě.","Nařídíte, aby vlastní pódium bylo rozebráno a odvezeno do bezpečí, zatímco několik tisíc příznivců zůstává, aby se o novinkách dozvěděli z druhé ruky. To, jak to vypadá, se snadno popsat nedá."]]},"n-confidence-interval":{"t":"Míra jistoty","x":"Deborah má scénář dnešního brífinku. \"Meteoroložka chce říct, že je šedesátiprocentní šance, že bouře zatočí na sever. Vy jste ji požádal, aby řekla, že je to 'v podstatě jisté.' To nejsou stejné věty, pane, a ona je vědkyně a ten rozdíl zná, i kdyby ho neznal nikdo z diváků.\"","c":[["Napsat do scénáře jistotu. Přečte, co dostane.","Hlavní meteoroložka přečte před kamerou větu, které nevěří, a zbytek zpravodajství za ni odvede její výraz."],["Nechat ji říct šedesát procent. Vysvětlit nejistotu.","Veřejnost slyší skutečné číslo se skutečnou odchylkou, což je celý, nepříliš efektní smysl předpovědi."],["Zaokrouhlit to na devadesát. Blíž, ale ne jisté.","Střední cesta, která neuspokojí nikoho: méně nepoctivá než jistota, víc nepoctivá než šedesát, a přesně stejně mylná, pokud bouře nezatočí."],["Nechat ji prezentovat surový model 'špaget,' bez úprav.","Devatenáct neoznačených barevných čar zaplní obrazovku na čtyři minuty, zatímco meteoroložka vysvětluje soustavu modelů viditelně ztracenému moderátorskému stolu. Přesto se to odvysílá."]]},"n-forest-floor":{"t":"Hrabání","x":"Roscoe má snímek nazvaný \"Příležitosti k zefektivnění, Lesní správa.\" \"Hasičské týmy chtějí čtyřicet milionů na odstranění podrostu, pane. Podle mé analýzy potřebuje většina toho lesa jen to, aby ho někdo vyhrabal. Osobně jsem žádný les nehrabal. Za analýzou si stojím.\"","c":[["Škrtnout rozpočet na odstranění podrostu. Místo toho financovat hrabání.","Čtyřicet milionů na odstranění podrostu se změní na mnohem menší položku na hrábě. Následující požární sezóna je, náhodou, kterou tu nikdo nepotvrdí, horší."],["Financovat program odstranění podrostu v plné výši.","Nenápadných čtyřicet milionů koupí týmy, motorové pily a hraniční linie, které nikdo nefotí. Následující požární sezóna je měřitelně menší, a nikdo si nevšimne příčinné souvislosti."],["Úplně to škrtnout. Svést vinu na lesy minulé administrativy.","Připíšete letošní množství hořlavého materiálu prezidentovi, který opustil úřad ještě předtím, než letošní stromy vůbec vyrostly. Funguje to na lidi, kteří tomu stejně chtěli věřit."],["Poslat stážisty z BROOM se skutečnými hráběmi.","Čtrnáct stážistů ve stejných vestách vyhrabe za prodloužený víkend šest akrů ze čtyř set tisíc akrů lesa. Fotky jsou upřímné. Matematika na jejich straně není."]]},"n-orange-sky":{"t":"Index kvality ovzduší","x":"Wendell má naměřenou hodnotu i doporučení. \"Index je na čtyřech stech, pane. To není 'nezdravé,' to je vrchol stupnice, který nabírá barvu, kterou stupnice obvykle nepotřebuje. Upřímné doporučení říká jedenácti milionům lidí, ať zůstanou týden doma, což si nemohou dovolit.\"","c":[["Zaokrouhlit číslo dolů. Nechat ekonomiku otevřenou.","Veřejný index ukazuje nižší číslo, než jaké naměřil samotný senzor. Obloha za každým oknem hlasitě a v oranžové nesouhlasí s vládní webovou stránkou."],["Zveřejnit skutečné číslo. Vydat skutečné doporučení.","Doporučení je přesně tak znepokojivé jako vzduch, a přesně tak nudné, jako veřejné zdravotnictví bývá, když funguje. Pohotovosti hlásí méně návštěv, ne víc."],["Prohlásit, že kouř je zahraniční a není to naše věc.","Kouř z domácího požáru přisoudíte sousední zemi, pokud to zeměpis dovolí. Meteorologové toto tvrzení snadno vyvrátí, a s chutí to dělají celý týden."],["Osobně otestovat vzduch během běhání venku, před kamerou.","Doběháte fotografovaných osm set metrů ve viditelně nedýchatelném vzduchu, abyste dokázal něco, co po vás nikdo nechtěl dokazovat. Dr. Prine si domlouvá kontrolu ještě dřív, než dokašlete."]]},"n-arson-theory":{"t":"Teorie žhářství","x":"Ředitelka Quistová čte ze skutečného spisu a chce to mít v záznamu. \"Neexistuje žádný důkaz koordinovaného žhářství, pane. Existuje sucho, tepelná kupole a čtyřicet let nahromaděného hořlavého materiálu. Vy jste na shromáždění řekl, že to jsou 'žháři placení ze zahraničí.' Teď mám jedenáct agentů, kteří vyřizují tipy na spiknutí, které neexistuje.\"","c":[["Trvat na tom. Oznámit federální jednotku pro vyšetřování žhářství.","Vznikne jednotka vyšetřující zločin, ke kterému nedochází. Za osm měsíců a se skutečnými náklady nenajde nic, a hlásí to tak tiše, že si toho nikdo nevšimne."],["Opravit záznam. Financovat skutečný výzkum požárů.","Tvrzení vezmete zpět a místo toho financujete výzkum sucha a hořlavého materiálu. Je to menší, pravdivější příběh, a je to ten, který skutečně pomůže příští sezóně."],["Přesto jmenovat konkrétní \"zahraniční skupinu.\"","Obviníte konkrétní zemi z žhářství bez jediného důkazu. Její velvyslanectví vydá prohlášení. Vaše o tři týdny později vydá odvolání, které si nikdo nepřečte tak pozorně."],["Nabídnout odměnu za tipy. Šestimístná částka. Bez nutnosti stopy.","Linka pro tipy nasbírá čtyři tisíce hovorů, hlavně o podezřelých grilovacích zvycích sousedů. Ani jeden nikam nevede. Linka zůstává otevřená stejně dál, ze setrvačnosti."]]},"n-water-bomber-gift":{"t":"Vypůjčená letadla","x":"Muriel má nabídku v ruce. \"Cathay nabízí čtyři hasičská letadla s posádkami, zdarma, zatímco naše vlastní flotila je uzemněná kvůli údržbě. Je to opravdu velkorysá nabídka, pane. Je to ale nepopiratelně i fotka jejich vlajky nad naším požárem.\"","c":[["Odmítnout. Nikoho pomoc nepotřebujeme.","Ze zásady odmítnete čtyři funkční letadla, zatímco hoří další tři čtvrti. Zásada zůstává nedotčená. Čtvrti ne."],["Tiše přijmout. Jednou stručně poděkovat.","Letadla létají, požáry zpomalují, a poděkování je jedna věta na konci brífinku. Je to přesně tolik uznání, kolik ta chvíle vyžaduje."],["Přijmout, ale prohlásit letadla za americké vítězství.","Vypůjčenou flotilu oznámíte jako důkaz \"totální americké letecké nadvlády nad ohněm.\" Velvyslanec Cathay žádá opravu. Žádnou nevydáte."],["Přijmout a nabídnout jim na oplátku naše národní parky.","Ústní nabídku, že \"si někdy mohou půjčit národní park,\" bere velmi zmatené ministerstvo zahraničí jako věc, kterou teď musí formálně písemně vzít zpět."]]},"n-rebuild-permit":{"t":"Urychlené povolení","x":"Guvernérka Vasquez-Moorová si o tento telefonát nežádala. \"Váš úřad vydal nouzové povolení k obnově pro developerskou firmu jednoho dárce, na šest set akrů vyhořelé plochy, pane. V mém státě. Dozvěděla jsem se to z tiskové zprávy, což je nový způsob, jak se dozvídat o svém vlastním státě.\"","c":[["Platí to dál. Federální nouzová pravomoc má přednost před tou její.","Přebijete pravomoc úřadující guvernérky nad využitím půdy ve prospěch dárce a nazvete to pomocí při katastrofě. Papíry jsou federální. Dojem, který to budí, nikam nezmizí."],["Zrušit to. Nechat pozemek projít přes její úřad.","Povolení jde znovu normální cestou, pomaleji, nudněji a mnohem hůř se o tom píše skandál."],["Urychleně schválit dalších devět pozemků, všechny stejnému dárci.","Jediná vyhořelá plocha se během měsíce promění v realitní portfolio jediné firmy. Papírová stopa je alespoň konzistentní."],["Nabídnout pozemek i guvernérce, aby se to uhladilo.","Nabídnete úřadující guvernérce kus spálené země jako smírné gesto. Odmítne prohlášením, které je nějak zničující víc, než kdyby prostě neřekla nic."]]},"n-flood-zone-map":{"t":"Překreslené záplavové území","x":"Miriam Applewhiteová tuhle část práce nemá ráda. \"Aktualizovaná mapa záplavového území vyjímá čtyřicet akrů ze stoleté záplavové zóny, pane. Těch čtyřicet akrů vlastní firma, která darovala dva miliony do inauguračního fondu. Inženýři, kteří kreslili původní hranici, se písemně ptají, proč se posunula.\"","c":[["Schválit přerýsování. Tiše to zveřejnit v pátek.","Hranice se posune, pozemek se stane zastavitelným, a povodeň je jedno, kam podle mapy nemá chodit."],["Odmítnout to. Nechat platit hranici inženýrů.","Mapa zůstává tam, kam voda skutečně chodí, což se ukazuje být na záplavové mapě mnohem užitečnější vlastností."],["Kvůli konzistenci přerýsovat záplavové území celého okresu.","Polovina požadavků na povodňové pojištění v okrese přes noc zmizí. Pojišťovny si toho všimnou dřív než obyvatelé a podle toho přepočítají ceny."],["Nechat stážistku osobně ověřit nadmořskou výšku pomocí nivelačního přístroje.","Madison stráví odpoledne v terénu s vypůjčeným nivelačním přístrojem a ke skutečnému překvapení všech přinese obhajitelnější číslo než původní konzultant."]]},"n-levee-inspection":{"t":"Odložená prohlídka","x":"Lyle má otevřenou tabulku zpožděné údržby. \"Šest hrází má zpožděnou federální prohlídku, pane. Financování vypršelo před osmnácti měsíci v zákoně, o kterém si nikdo nepamatuje, že by pro něj hlasoval. Jedna z těch šesti chrání město se čtyřmi sty tisíci obyvateli. Rád bych ji posunul výš na seznamu.\"","c":[["Odložit všech šest znovu. Místo toho oznámit snížení daní.","Prohlídky vyprší už druhý rok po sobě, snížení daní tak financují peníze, které hráze tiše používaly na to, aby nespadly."],["Financovat prohlídky. Všech šest, tento kvartál.","Šest nenápadných prohlídek proběhne podle plánu. Nestane se nic hodné zpráv, což je u hráze jediný výsledek, který by si kdokoli měl přát."],["Financovat jednu hráz. Tu poblíž vašeho golfového resortu.","Zkontrolovaná hráz náhodou chrání jamku, kterou osobně používáte jedenáctkrát ročně. Zbylých pět, chránících podstatně víc lidí, zůstává na seznamu."],["Místo toho poslat vojenskou kapelu zahrát u každé hráze.","Šest dechových souborů vystoupí u šesti neopravených hrází. Konstrukčně jde o stejnou míru ochrany před povodní jako předtím, jen s dřevěnými dechovými nástroji navíc."]]},"n-sandbag-shortage":{"t":"Fronta na pytle s pískem","x":"Duane má špatnou logistickou zprávu. \"Dodavatel pytlů s pískem ztrojnásobil cenu ve chvíli, kdy řeka dosáhla kulminace, pane. Národní garda může plnit pytle ručně, pomaleji, nebo zaplatíme novou cenu a budeme je mít do svítání. Tak jako tak je fronta před skladem dlouhá čtyři hodiny a mokne.\"","c":[["Zaplatit to. Oznámit navýšení jako záchranu.","Zaplatíte trojnásobek za písek v pytlích a uspořádáte o tom tiskovku. Marže dodavatele nikdy nevypadaly lépe. Váš projev taky ne."],["Garda je naplní ručně. Pomaleji, levněji.","Vojáci plní pytle celou noc za starou cenu. Trvá to o dvě hodiny déle, které voda velkoryse poskytne."],["Nechat cenu jak je. Volný trh, volná řeka.","Odvoláváte se na tržní zásady u fronty na pytle s pískem, dlouhé čtyři hodiny a rostoucí. Frontu ta zásada nijak neuklidní."],["Násilím zabavit všechny pytle s pískem ve třech státech.","Federálně zabavíte veškeré zásoby písku zahradnické firmy ve třech státech, včetně několika tun určených pro dětský turnaj v plážovém volejbale. Turnaj je zuřivý. Hráz drží."]]},"n-dam-release":{"t":"Brána na přehradě","x":"Guvernérka Vasquez-Moorová je na zabezpečené lince, o kterou osobně požádala. \"Inženýři říkají, že když teď otevřeme přepad, záměrně zaplavíme jedenáct farem po proudu, podle našeho plánu. Když to neuděláme, rozhodne za nás přehrada ve tři ráno a vezme s sebou i okresní město. To rozhodnutí je federální. Nemělo by být i tiché.\"","c":[["Odložit vypuštění. Tak jako tak to vypadá špatně, tak počkat.","Přehrada rozhodne ve tři ráno přesně podle předpovědi, podle plánu, který nikdo nevybral a za jehož výběr nikoho nelze vinit, což lidem nezabrání ve vinění."],["Vypustit teď. Dnes večer přímo varovat jedenáct farem.","Jedenáct farem záměrně zaplaví, s varováním, za denního světla, a okresní město ne. Je to výměna, za jejíž správné provedení vám nikdo nepoděkuje."],["Vypustit bez varování. Oznámit to až potom.","Jedenáct farem zaplaví úplně bez upozornění, a vysvětlení přijde až po vodě. Vysvětlení je tentokrát naprosto správné a úplně pozdě."],["Živě vysílat vypouštění, s vaší rukou na kole ventilu.","Necháte se vyfotit s rukou na kole, které ve skutečnosti ovládá hydraulický inženýr počítačem ze čtyř set yardů dál. Kolo je dekorativní. Tři inženýři formálně žádají, aby se to už neopakovalo."]]},"n-flood-insurance":{"t":"Pojistný program","x":"Arthur Lindqvist přinesl graf, který nikdo nechtěl vidět. \"Federální povodňový program je osmadvacet miliard pod vodou, pane, dovolíte-li ten výraz. Každá letošní výplata je půjčená proti výplatám, které se ještě neuskutečnily. Můžeme zvýšit pojistné, což pocítí do úterý každý majitel domu v záplavové zóně, nebo si dál půjčovat.\"","c":[["Zmrazit pojistné. Veřejně to svést na pojišťovny.","Pojistné zůstává stejné, oblíbené a nefinancované, zatímco program si dál půjčuje proti budoucnosti, která přichází přesně podle plánu."],["Mírně zvýšit pojistné. Rozložit to na tři roky.","Nudná, postupná náprava, kterou nikdo při přestřihávání pásky nikdy nezmíní. Program je poprvé za deset let blíž solventnosti."],["Zprivatizovat celý program. Nechat trh stanovit cenu.","Soukromé pojišťovny okamžitě nastaví ceny pojištění mimo dosah pro nejrizikovější a nejchudší záplavové zóny, tedy přesně pro ty zóny, kvůli kterým program vznikl."],["Nechat cara pro efektivitu \"zjednodušit\" proces vyřizování škod.","Roscoeho zjednodušený formulář odstraní jedno povinné pole. Bylo to to, které se ptalo, jestli je dům aktuálně pod vodou. Vyřizování škod je rychlejší a podstatně méně přesné."]]},"n-grid-failure":{"t":"Síť padá","x":"Cassandra Doyleová má vytaženou mapu výpadků, a je většinou jednobarevná. \"Devět milionů odběratelů, pane. Bezprostřední příčinou je selhání transformátoru během špičkové poptávky. Politicky pohodlnější příčina, kterou už tři vaši spojenci hlásají v televizi, jsou větrné mlýny. Chtěla bych mít v záznamu, že to větrné mlýny nebyly.\"","c":[["Jít do toho s větrnými mlýny. Už to trenduje.","Za výpadek způsobený čtyřicet let starým transformátorem obviníte formu výroby energie, která má na síti podíl čtyři procenta. Proti transformátoru se, jak známo, nedá hlasovat."],["Uvést skutečnou příčinu. Financovat posílení sítě.","Poctivá příčina dostane poctivou nápravu. Nebude to trendovat, a příští léto bude méně takových telefonátů, čehož si taky nikdo nevšimne."],["Svést vinu na zanedbávání sítě minulou administrativou.","Transformátor postavený o dvě desetiletí dřív než kterákoli z administrativ přisoudíte tomu, kdo byl u moci před třemi lety. U lidí, kteří to stejně nebudou ověřovat, to funguje dobře."],["Osobně navštívit poškozený transformátor kvůli fotce.","Necháte se vyfotit, jak stojíte vedle spálené šedé skříně velikosti dodávky a ukazujete na ni se zjevnou autoritou. Nikdo ze sledujících se nedozví nic o síti. Několik lidí se dozví, jak vypadá transformátor."]]},"n-rolling-blackout":{"t":"Postupné výpadky","x":"Cassandra má rozpis rotace a problém s ním. \"Abychom zabránili kolapsu celé sítě, střídáme výpadky podle okrsků, pane, po čtyřiceti minutách. Někdo v plánovacím oddělení tiše vynechal čtvrti dárců. Tabulku jsem právě jen našla. Nevytvořila jsem ji.\"","c":[["Zachovat výjimky. Popřít, že existují.","Čtvrti dárců zůstávají po celou krizi osvětlené. Tabulka nevyhnutelně unikne, se záhlavími sloupců, u kterých je těžké popřít záměr."],["Opravit rotaci. Všichni si to rozdělí rovnoměrně.","Čtyřicet minut tmy, spravedlivě rozdělených, je menší příběh než čtyřicet minut tmy rozdělených nespravedlivě. To je víceméně celé ponaučení z krize."],["Rozšířit seznam výjimek. Přidat další tři dárce.","Seznam roste. Roste i jeho budoucí publikum, které v okamžiku úniku zahrnuje i několik lidí, kteří na něm vůbec být nechtěli."],["Prodávat lístky na sledování rotace výpadků z balkonu.","Účtujete dvě stě dolarů za osobu za sledování výpadku, jak se přesouvá přes město, z nejlepších míst v hlavním městě. Vyprodá se to. Zároveň se to stane nejcitovanějším obrazem celé krize."]]},"n-generator-line":{"t":"Seznam generátorů","x":"Deborah drží dodací list, který by radši nedržela. \"Nouzové generátory, pane. Dvě stě kusů, federálně dodaných, a někdo sestavil distribuční seznam podle úrovní darů místo podle lékařské potřeby. Na čekacím seznamu je dialyzační centrum, za autobazarem, který dal padesát tisíc dolarů.\"","c":[["Odeslat podle stávajícího seznamu. Priority jsou priority.","Dvě stě generátorů dorazí přesně tam, kam podle seznamu dárců mělo, a dialyzační centrum si musí vystačit s menší záložní jednotkou, kterou někdo našel ve skladu."],["Dnes večer přestavět seznam podle lékařské potřeby.","Dialyzační centrum dostane generátor ještě před svítáním. Autobazar dostane velmi zdvořilý dopis o přidělení v příštím kvartálu."],["Ponechat seznam. Veřejně dárcům poděkovat.","Veřejně přiznáte zásluhu jmenovaným dárcům za generátory, jejichž dary jim přímo koupily přednostní přístup. Je to alespoň upřímná věta, což ale není totéž jako obhajitelná."],["Vydražit zbylé generátory na charitu, naživo.","Posledních dvacet federálních generátorů se dražilo pro dobrou věc v živém televizním vysílání, zatímco lidé bez generátoru pořád čekají na seznamu. Výtěžek pro charitu je působivý. Seznam taky."]]},"n-cyberattack-blame":{"t":"Kybernetický útok, který nebyl","x":"Errol Hance má skutečné forenzní výsledky, které nikdo zvlášť nechce. \"Selhání sítě způsobilo horko, pane. Poptávka předběhla kapacitu v nejteplejší den v historii státu. Neexistuje žádný důkaz zahraničního kybernetického útoku. Chci jasně říct, dřív než to řeknete v televizi, že jsem to hledal dvakrát a žádný neexistuje.\"","c":[["Přesto to oznámit. Konkrétně jmenovat Rusalku.","Obviníte zahraniční vládu z útoku, o kterém váš vlastní šéf tajných služeb tvrdí, že se nestal. Rusalka to popírá. Tentokrát mluví pravdu, a všichni v místnosti to vědí."],["Oznámit skutečnou příčinu. Poptávka a horko.","Nenápadná pravda: příliš mnoho klimatizací, jeden velmi horký den, stárnoucí infrastruktura. Je to menší titulek, ale užitečnější."],["Oznámit \"probíhající vyšetřování.\" Nechat to viset ve vzduchu.","Beze jména naznačíte zahraniční zapojení, na neurčito. Nic vás to nestojí říct a všechno vás to stojí, až to budete muset vzít zpět, což tiše uděláte v devátém měsíci."],["Nařídit Hanceovi, ať \"najde\" důkazy, které se hodí k příběhu.","Errol to písemně odmítne s odůvodněním, že zpravodajské hodnocení se nedá přizpůsobit na zakázku. Je to jednoznačně nejjasnější akt neposlušnosti za celé vaše funkční období, a zároveň ten správný."]]},"n-candlelight-address":{"t":"Projev při svíčkách","x":"Gideon má koncept a problém s osvětlením. \"Výpadek zasáhne i Rezidenci, pane, takže se národní projev bude odehrávat při svíčkách, ať to naplánujeme nebo ne. Můžu to napsat kolem toho, aby to vypadalo záměrně, nebo prostě řekneme, že vypadl proud, jak to skutečně je.\"","c":[["Zinscenovat to jako záměrnou ukázku odhodlání.","Přednesete jedenáctiminutový projev při svíčkách, prezentovaný jako vzdorná volba, ne jako výpadek proudu. Čtyři nezávislá ověření faktů jemně potvrdí, že šlo skutečně o výpadek proudu."],["Jednoduše říct, že vypadl proud. Držet to krátké.","Za méně než devadesát sekund řeknete pravdu o výpadku, při svíčkách, což působí prezidentštěji, než by dokázalo zajistit jakékoli osvětlovací zařízení."],["Svést výpadek na vybavení televizního štábu.","Bez důkazů naznačíte, že výpadek ve vlastním domě způsobilo vybavení televizní stanice. Inženýři stanice, kteří se elektřiny vaší budovy vůbec nedotkli, na to nejsou zvlášť hrdí."],["Přečíst projev s baterkou drženou pod bradou.","Přednesete národní projev osvětlený zespodu jako táborová historka, zcela bez vyzvání. Do hodiny se to stane nejsdílenější devadesátisekundovou ukázkou vašeho prezidentství, z důvodů nesouvisejících s politikou."]]},"n-shelter-visit":{"t":"Návštěva útulku","x":"Brayden má připravené dárkové tašky. \"Dva tisíce brandovaných tašek, pane, každá s lahví vody, klíčenkou a fotokartičkou, na které ukazujete palec nahoru. V útulku je čtyři sta lidí. Buď jsem spočítal špatně, nebo byla špatná objednávka, jedno z toho je určitě špatně.\"","c":[["Rozdat je stejně všechny. Nejdřív fotoshoot.","Strávíte čtyřicet minut rozdáváním brandovaných předmětů lidem, kteří před jedenácti hodinami přišli o domov. Záběry běží všude. Stejně tak záběry toho, co lidé udělají s klíčenkou, když chtěli lehátko."],["Vynechat tašky. Zeptat se, co útulek potřebuje.","Zeptáte se ředitele útulku přímo a jednáte podle odpovědi: víc lehátek, ne víc klíčenek. Je to nejméně fotogenická hodina celé cesty a jediná užitečná."],["Rozdat je a s každým příjemcem si udělat selfie.","Čtyři sta jednotlivých fotografií je pořízeno za devadesát minut v útulku pro postižené, dvakrát to zdrží podávání večeře. Na každé fotce je stejný palec nahoru. Na žádné z nich není vidět lehátko."],["Věnovat rozpočet na merch a pak o tom pronést projev.","Přesměrujete celý rozpočet na merch na skutečné náklady útulku, a pak strávíte čtyřicet minut u pultíku šest kilometrů daleko popisováním vlastní štědrosti. Útulek dostane peníze. Projev dostane titulek."]]},"n-photoshopped-visit":{"t":"Cesta, která se nekonala","x":"Renata přináší špatné zprávy, tak klidně, jak jen dokáže. \"Cesta do zaplavené oblasti byla dnes ráno zrušena kvůli počasí, pane, a nikdo to neřekl grafickému týmu. Ti vás už zakomponovali do fronty na pytle s pískem z archivních záběrů. Technicky vzato je to nesmírně přesvědčivé.\"","c":[["Zveřejnit to. Když se zeptají, popřít montáž.","Vykonstruovaná fotografie, na které skládáte pytle s pískem u řeky, se zveřejní jako skutečná. Teenager na internetu najde nesrovnalost ve stínech za čtyřicet minut. Zpravodajským agenturám to trvá podstatně déle."],["Zastavit to. Přeplánovat skutečnou cestu na čtvrtek.","Nikdo nevidí falešnou fotku, protože žádná nebyla zveřejněna. Skutečná cesta se koná o dva dny později, bez rozruchu, což je přesně to správné množství rozruchu pro prezidentskou návštěvu."],["Zveřejnit to s upozorněním, které nikdo nepřečte.","Pod fotkou, navrženou tak, aby vůbec nevypadala jako montáž, běží popisek šestibodovým písmem s textem \"kompozitní snímek, umělecké ztvárnění.\" Popisek uspokojí právníka. Nikoho jiného ne."],["Jít stát do skutečné fronty na pytle s pískem, s tiskovým poolem v závěsu.","Objevíte se přímo proto, abyste vyvrátil falešnou fotku, v doprovodu čtyřiceti akreditovaných novinářů, kteří lokty odstrkují lidi u pytlů, aby získali záběr dokazující, že to není zinscenované. Je to nějak méně přesvědčivé než ta falešná fotka."]]},"n-helicopter-flyover":{"t":"Přelet","x":"Generál Tarrant tlumočí hodnocení předsunutého týmu. \"Dav na místě přistání není úplně přátelský, pane. Pořád můžeme přistát a přijmout, co přijde, nebo nízko přeletět nad troskami a pokračovat na benefiční akci. Jen jedno z toho mi teď přijde vhodné doporučit.\"","c":[["Přeletět. Zamávat z okna. Pokračovat dál.","Jste vidět z velké výšky, jak máváte nad katastrofou, do které jste nepřistál. Záběry mávání a záběry trosek běží nešikovně za sebou ve stejném zpravodajském bloku."],["Přistát. Snést pokřikování. Přesto projít místem.","Osobně čelíte dvaceti minutám vykřikovaného, zcela oprávněného hněvu, a přesto projdete místem. Stojí vás to celé odpoledne, ale získáte tím něco, co by vám přelet nikdy nedal."],["Úplně vynechat místo katastrofy. Jet rovnou na benefiční akci.","Vynecháte trosky a necháte se ten samý den vyfotit s vidličkou na krevety v resortu šedesát kilometrů daleko. Nikomu ze zúčastněných netřeba to srovnání vysvětlovat."],["Přistát, ale jen na tak dlouho, aby vznikla fotka, s běžícím motorem.","Dosednete na devadesát sekund s rotory pořád v chodu, zamáváte a vzlétnete dřív, než se kdokoli stihne na cokoli zeptat. Technicky se to počítá jako přistání. Nikdo ze sledujících tomu nevěří."]]},"n-giant-check":{"t":"Obří šek","x":"Lyle má rekvizitu i skutečné číslo, a ty se neshodují. \"Velký šek pro kamery ukazuje dvě miliardy, pane. Skutečná schválená pomoc, po obvyklém kongresovém oholení, je čtyři sta milionů. Někdo musí ten obří kartonový šek držet, a asi by to neměl být já.\"","c":[["Držet velké číslo. Nechat to skutečné pohřbené.","Necháte se vyfotit s úsměvem za šekem s číslem pětkrát vyšším než skutečně schválená pomoc. Rozdíl vyplave na povrch při rozpočtovém slyšení o čtyři měsíce později, s podstatně menším zpravodajským pokrytím, než dostala fotka."],["Předložit skutečné číslo. Vynechat rekvizitu.","Čtyři sta milionů, uvedeno prostě, bez kartonového obdélníku, který by to nafoukl. Je to menší fotka, ale pravdivější."],["Vytisknout dva šeky. Velký pro kamery, skutečný tiše založit.","Existují dva dokumenty popisující stejný balíček pomoci ve dvou různých hodnotách. Jen jeden z nich je právní nástroj. Oba nakonec skončí někde jako důkaz."],["Vydražit obří šek jako sběratelský předmět.","Nadrozměrný kartonový šek na dvě miliardy dolarů se vydraží jako kampaňová memorabilie za čtyřicet tisíc dolarů. Technicky vzato je to v některých ohledech víc peněz, než šek sám reprezentuje, a podstatně lépe zdokumentované."]]},"n-rally-near-ground-zero":{"t":"Shromáždění u trosek","x":"Nadia má čísla i mapu. \"Vaše obliba je teď nejsilnější do osmdesáti kilometrů od zóny katastrofy, pane, efekt soucitu, děje se to pokaždé. Moje upřímné doporučení je uspořádat tam tento týden shromáždění, dokud je to číslo ještě čerstvé.\"","c":[["Domluvit to. Uspořádat shromáždění na okraji trosek.","Pořádáte kampaňové shromáždění s viditelnou zónou katastrofy za zády, a nárůst sympatií, o který jste usilovali, se před kamerou promění v něco bližšího znechucení."],["Vynechat shromáždění. Poslat zdroje místo pódia.","Necháte soucit soucitem a pošlete náklaďáky místo řečnického pultu. Číslo v průzkumech stejně stoupne, pomaleji, ale vydrží déle."],["Uspořádat to tam a u vchodu prodávat merch.","Skládací stůl prodává brandované čepice čtyřicet yardů od zřícené střechy. Tržby jsou výborné. Záběry toho stolu jsou hlavní zprávou zbytku týdne."],["Zrušit to. Ve stejném čase vysílat naživo dobročinný telethon.","Shromáždění se ve stejném čase a se stejným produkčním rozpočtem promění v telethon. Vybere skutečné peníze a několika kritikům to připadá jako shromáždění v jiném hávu."]]},"n-no-bid-contract":{"t":"Zakázka bez soutěže","x":"Sy má smlouvu označenou barvou, kterou si šetří na skutečné problémy. \"Odklízení sutin, pane, čtyři sta milionů dolarů, přidělené bez výběrového řízení firmě založené před šesti týdny. Její registrovaná adresa je zásilkovna. Jejím uvedeným prezidentem je švagr vašeho golfového caddyho. Ověřil jsem to dvakrát.\"","c":[["Podepsat to. Krize nečeká na papírování.","Čtyři sta milionů putuje k šest týdnů staré firmě bez vybavení, bez posádky, s adresou zásilkovny. Sutiny, jak se dalo čekat, zůstávají přesně tam, kde byly."],["Zrušit to. Otevřít skutečné, rychlé výběrové řízení.","Skutečné soutěžní řízení, provedené za dny místo měsíců, protože zákon přesně tohle v mimořádné situaci umožňuje. Sutiny se začnou odklízet do týdne."],["Podepsat to a udělit druhou zakázku na kontrolu té první.","Fiktivní firmu teď dohlíží druhá fiktivní firma. Ani jedna nevlastní náklaďák. Pole sutin je v tuto chvíli v podstatě trvalá památka."],["Nechat cara pro efektivitu osobně zkontrolovat adresu.","Roscoe si tam sám zajede a nechá se vyfotit vedle stěny pronajatých poštovních schránek. Sepíše zprávu. Zpráva má jednu větu a je nesmírně přesná."]]},"n-temporary-housing":{"t":"Dočasné bydlení","x":"Duane má inspekční zprávu, kterou by radši shrnul, než přečetl nahlas. \"Nouzové obytné jednotky, pane. Jedenáct tisíc kusů, dodaných podle plánu, za velmi dobrou cenu. Výrobce kvůli té ceně šidil na ventilaci. Rodiny v nich žijí čtyři měsíce. Bolesti hlavy začaly druhý měsíc.\"","c":[["Popřít problém s ventilací. Prodloužit smlouvu.","Prodloužíte smlouvu na jednotky, které vaši vlastní inspektoři označili za nebezpečné, a jedenáct tisíc rodin si nadále nese bolesti hlavy, zatímco papíry pořád tvrdí, že žádné nejsou."],["Stáhnout jednotky. Zaplatit za skutečnou nápravu.","Stažení, oprava a mnohem větší účet, než kdokoli chtěl vystavit. Jedenáct tisíc rodin dostane funkční ventilaci místo tiskové zprávy."],["Svést to na rodiny za \"nesprávné používání\" jednotek.","V oficiálním prohlášení naznačíte, že vysídlené rodiny nesprávně větrají vlastní přívěsy. Prohlášení nepřežije kontakt ani s jediným rozhovorem."],["Osobně se nastěhovat do jednotky, s kamerami po celý týden.","Strávíte televizně sledovaný týden v označeném přívěsu, zatímco štáby dokumentují každou bolest hlavy. Sledovanost je vysoká. Problém s ventilací po čtyřech měsících pořád taky."]]},"n-relief-fund-diversion":{"t":"Odkloněné prostředky","x":"Hal Grimes drží rozpočtový zákon, jako by mohl vybuchnout. \"Balíček pomoci prošel výborem, pane, čtyři sta milionů pro zaplavenou oblast. Někdo z vašeho úřadu k tomu přiložil dodatek přesměrovávající šedesát milionů z toho na renovaci plesového sálu v Rezidenci. Jedenáct žhářů v mém poslaneckém klubu se mě už na to ptá.\"","c":[["Nechat dodatek. Už je připojený.","Šedesát milionů z povodňové pomoci financuje lustr. Dodatek přežije hlasování o dva hlasy a spoustu laskavostí, které budou muset být splaceny."],["Odstranit dodatek. Poslat celou částku do zaplavené oblasti.","Čtyři sta milionů dorazí tam, kam podle textu mělo. Je to opravdu nenápadný výsledek, a výborem projde podruhé bez incidentu."],["Zdvojnásobit dodatek. Přidat fontánu.","Plesový sál teď dostane fontánu navrch k lustru, oboje financované ze zákona o povodňové pomoci. I jedenácti žhářům to přijde jako něco, proti čemu je třeba protestovat."],["Nechat předsedu Sněmovny, aby dodatek osobně obhájil v plénu.","Přinutíte Hala Grimese, aby na plénu, před kamerou, veřejně obhájil vlastnímu poslaneckému klubu dodatek o fontáně v plesovém sále. Zvládne to špatně, a bude se to citovat ještě deset let."]]},"n-price-gouging-law":{"t":"Cena vody","x":"Bo Slaughter má hromadu stížností a rozhodnutí, které musí udělat. \"Balená voda stojí v zóně katastrofy devět dolarů za balení, pane. Před týdnem stály dva dolary. Zákon proti lichvě je jasný a leží mi na stole. Distributor je zároveň velký dárce. Rád bych dostal pokyn, než udělám cokoli, na co se mě později může zeptat soud.\"","c":[["Nechat to plout. Trh si to vyřeší sám.","Voda zůstává za devět dolarů za balení pro obyvatelstvo, které právě přišlo o všechno. Trh si to nakonec vyřeší, hlavně tak, že lidé zůstanou bez vody."],["Vymáhat zákon. Dnes stanovit cenový strop.","Zákon, který už existoval, se použije přesně k tomu, k čemu byl napsán. Voda do večera klesne na dva dolary. Nikdo nenapíše titulek o tom, že zákon prostě funguje."],["Vymáhat to, ale tiše udělit dárci výjimku.","Vymáháte zákon proti lichvě proti všem kromě jednoho distributora, jehož výjimku jste osobně podepsal. Memorandum o výjimce je bohužel pro vás veřejně dostupný záznam."],["Osobně nechat dovézt vodu leteckým mostem, kampaňovým letadlem.","Necháte upravit kampaňový tryskáč, aby osobně dovezl palety vody do zóny katastrofy, za cenu daleko převyšující hodnotu vody, a nazvete to záchrannou misí. Dostane se z toho čtyři balení ke čtyřem rodinám a velmi dobrý letecký záběr."]]},"n-celebrity-telethon":{"t":"Telethon","x":"Brayden má celkovou částku příslibů a poznámku pod čarou. \"Na telethonu se vybralo osmdesát milionů dolarů, pane. Čtyřicet z toho je už přislíbeno na pomoc. Zbylých čtyřicet leží ve 'správním fondu,' který, pokud vidím, hradí hlavně samotný telethon.\"","c":[["Nechat to tak. Správní náklady jsou normální.","Polovina peněz vybraných pro oběti katastrofy financuje produkci, která o ty peníze žádala. Technicky se to vejde do rozsahu, ve kterém telethony obvykle běží. Není to rozsah, na který by měl být kdokoli hrdý."],["Omezit správní náklady na pět procent. Zbytek přesměrovat.","Do zaplavené oblasti se dostane o šestatřicet milionů dolarů víc, než by se dostalo jinak. Je to nejméně zábavná hodina televize vyrobená za celý rok, a nejužitečnější."],["Nechat si připsat producentskou zásluhu a podíl z budoucích speciálů.","Osobně se napojíte na trvalý příjmový tok telethonu. Vysílání o pomoci při katastrofě má teď položku pro váš producentský honorář, kterou nakonec někdo najde."],["Osobně vyrovnat dary, z prostředků kampaně.","Přesměrujete čtyřicet milionů z darů kampani na pomoc při katastrofě, na což několik právníků specializovaných na financování kampaní okamžitě upozorní, že to není zákonné určení těchto prostředků. Peníze přesto dorazí. Vykazování to problémem být nepřestane."]]},"n-stadium-shelter":{"t":"Stadion","x":"Duane je na stadionu už od svítání. \"Šest tisíc lidí, pane, v budově určené pro akce, ne pro bydlení. Klimatizace v tomhle horku selhává. Toalety nebyly stavěné na takové množství lidí na tak dlouho. Potřebujeme lidi dostávat ven rychleji, než je dostáváme dovnitř, a teď je to obráceně.\"","c":[["Nepouštět tam kamery. Řídit příběh, ne dav.","Novináře nepouští na hrací plochu stadionu, zatímco podmínky uvnitř se zhoršují. Zpráva stejně vyjde, o tři dny později, celá založená na lidech, kteří tam byli a měli telefony."],["Opravit klimatizaci. Přivézt mobilní sprchy a personál.","Šest tisíc lidí dostane do osmačtyřiceti hodin funkční klimatizaci a čisté toalety. Stojí to skutečné peníze a nevznikne z toho žádná fotka, kterou by kdokoli chtěl pořídit."],["Místo toho přesunout lidi na druhý, menší stadion.","Šest tisíc lidí se přesune do zařízení postaveného pro čtyři tisíce, což nic nevyřeší a přidá to jen cestu autobusem."],["Vysílat naživo čtyřiadvacetihodinový telethon zevnitř stadionu.","Čtyřiadvacetihodinové vysílání se odehrává přímo mezi lehátky na stadionu, včetně domácí kapely. Vybere se slušná částka. Šest tisíc lidí se ve dvě ráno snaží prospat saxofonové sólo."]]},"n-pets-left-behind":{"t":"Pravidla pro zvířata","x":"Madison celé ráno vyřizuje tenhle telefonát, což je neobvyklé, protože to obvykle není její práce. \"Pane, federální útulky nedovolují domácí zvířata, a spousta lidí kvůli tomu odmítá evakuovat. Právě teď je v televizi muž, který říká, že raději přečká povodeň se svým psem, než aby ho nechal napospas.\"","c":[["Nechat pravidla tak. Zdůraznit osobní odpovědnost.","Zákaz zvířat platí dál, a míra evakuace v zaplavené oblasti klesá téměř o třetinu. Několik lidí přečká povodeň, které se nemuseli účastnit, ze zásady, vedle psa."],["Okamžitě financovat přístavky pro útulky přátelské ke zvířatům.","Oplocený přístavek u každého útulku, s miskami na vodu a dobrovolným veterinářem na telefonu. Míra evakuace přes noc vyskočí, protože se ukáže, že problémem nikdy nebyl pes, ale pravidlo."],["Nabídnout, že zvířata \"zpracuje\" útulek pro zvířata.","Slovo \"zpracuje\" se do hodiny dostane k muži z televize. Z zaplavené oblasti neodejde. Jeho pes taky ne."],["Osobně, naživo, před kamerou, adoptovat mužova psa.","Necháte se vyfotit, jak držíte cizího zlatého retrívra, zatímco skutečný majitel, metr od vás, pořád odmítá evakuovat, a útulek pro zvířata otevírá spor o pravomoc ohledně toho, kdo teď technicky zvíře vlastní."]]},"n-national-guard-standoff":{"t":"Zfederalizovaná garda","x":"Guvernérka Vasquez-Moorová se tentokrát neptá, informuje. \"Zfederalizoval jste mou Národní gardu bez mé žádosti, pane, kvůli zajištění bezpečnosti útulků, u kterého jsem nepovažovala federalizaci za nutnou. Mám čtyři sta vojáků, kteří mi jinak zbytek roku podléhají, a najednou podléhají Pentagonu právě v tom jediném týdnu, kdy je můj stát skutečně potřebuje na místě.\"","c":[["Nechat je zfederalizované. Velení patří nahoru.","Přeberete kontrolu nad státní gardou kvůli zajištění bezpečnosti útulků, což je použití federální moci zhruba stokrát větší, než je problém, který řeší."],["Vrátit velení. Koordinovat přes její úřad.","Velení se vrátí guvernérce, a útulky získají ochranku přes běžný řetězec, o jehož existenci nikdo mimo stát nikdy nepotřeboval vědět."],["Preventivně zfederalizovat gardu i druhého státu.","Rozšíříte zábor i na stát, který zatím žádnou katastrofu neměl, s teorií, že by mohl mít. Dva guvernéři teď místo dvou oddělených reakcí na katastrofu koordinují společnou právní odpověď."],["Zplnomocnit ji, ale pro fotky vyžadovat federální uniformu.","Udělíte skutečnou pravomoc a pak trváte na kostýmu pro kamery. Pravomoc přijme a uniformu odmítne ve stejné větě, která se stane větou, kterou budou všichni citovat."]]},"n-school-shelter":{"t":"Školní tělocvična","x":"Bernadette Ollisová má kalendářní problém, ke kterému se nikdo nechce hlásit. \"Čtrnáct škol pořád slouží jako útulky, pane, čtyři měsíce po bouři. Školní rok začíná za tři týdny. Můžeme je znovu otevřít a přesunout rodiny bez toho, aby měly kam jít, nebo znovu odložit začátek roku, podruhé.\"","c":[["Otevřít podle plánu. Tento týden rodiny přesunout.","Čtrnáct škol se otevře včas a několik set rodin se přesune na parkoviště s přenosnou toaletou, technicky venku, technicky už ne problémem školy."],["Odložit o dva týdny. V mezidobí financovat nouzové bydlení.","Krátký, financovaný odklad dá rodinám skutečné místo, kam jít, než se tělocvična znovu promění ve třídu. Stojí to dva týdny výuky a přinese to mnohem menší titulek než alternativa."],["Otevřít polovinu. Zbylé útulky sloučit do zbytku.","Sedm škol se otevře a sedm se přeplní, zdvojnásobí se hustota útulků, které už byly na hranici kapacity, aby se stihl termín, který nikdo pořádně nezkoumal."],["Vyučovat přímo v útulcích, vedle lehátek.","První třída se tři týdny schází dva metry od řady darovaných lehátek, zatímco školní rada žaluje kvůli požadavkům na výukový čas, o kterých trvá na tom, že byly stejně porušeny."]]},"n-displaced-vote":{"t":"Vysídlený volič","x":"Nadia zkřížila voličské seznamy se seznamy z útulků, což přesně vzato není její práce. \"Čtyřicet tisíc registrovaných voličů ze zaplavené oblasti už nemá poštovní adresu, pane. Ten okrsek historicky inklinuje k vašemu protivníkovi o šest bodů. Je tu rozhodnutí, jak moc ztížíme opravu korespondenčního hlasování, když člověk nemá adresu.\"","c":[["Nechat požadavek na adresu platit. Není to náš problém.","Čtyřicet tisíc lidí, kteří přežili povodeň, přijde o hlas kvůli papírovému požadavku předpokládajícímu, že každý pořád má poštovní schránku. Okrsek, který by inklinoval proti vám, fakticky tuto možnost nemá."],["Zrušit požadavek. Adresa útulku se počítá.","Lehátko v útulku se pro jedny volby stane právoplatnou poštovní adresou. Čtyřicet tisíc lidí, kteří přišli o dům, si podrží hlas, což se ukazuje být menší věcí ke ztrátě, ale těžší věcí k odůvodnění, proč ji vzít."],["Zrušit to, ale jen v okrscích, které jsou nakloněné vám.","Rozšíříte výjimku selektivně, podle okrsku, v memorandu, které kritéria výběru uvádí dost jasně na to, aby vám je soud mohl přečíst zpátky."],["Poslat Madison, ať osobně doručí čtyřicet tisíc hlasovacích lístků.","Jedné stážistce se přidělí čtyřicet tisíc domácností, a tiskový pool trvá na natáčení prvních čtyř set dveří, čímž se doručování lístků promění v kampaňovou reklamu, kterou zaměstnanci Kongresu okamžitě označí za nepeněžitý příspěvek."]]},"n-blame-governor":{"t":"Zadržená pomoc","x":"Stát guvernérky Vasquez-Moorové má katastrofu a podanou žádost, a obojí leží už jedenáct dní. Deborah předkládá svůj odhad. \"Nepodpořila zákon o infrastruktuře, pane, a žádost o pomoc leží na vašem stole nepodepsaná. Nemyslím si, že je to náhoda. A nemyslím si, že si to myslíte ani vy.\"","c":[["Zadržet to. Nechat ji pocítit tu páku.","Necháte prohlášení o katastrofě nepodepsané, abyste vyvinul tlak na guvernérčin hlas k nesouvisejícímu zákonu, a v státě, který je podle jakéhokoli měřítka pořád zaplavený, uplyne dalších jedenáct dní."],["Podepsat to. Pomoc není vyjednávací karta.","Prohlášení je podepsáno v den, kdy mělo být podepsáno. Nepohne to s jediným hlasem k zákonu o infrastruktuře, a to se ani nikdy nemělo stát."],["Podepsat to, ale nechat to projít pomalejším agenturním kanálem.","Prohlášení je technicky podepsáno a prakticky zdrženo o další tři týdny rutinního zpracování, které se v tomto kontextu jeví jako zjevně ne rutinní."],["Podepsat to, ale nechat ji požádat dvakrát, v živém vysílání.","Zinscenujete telefonát pro kamery, přinutíte úřadující guvernérku, aby v živém vysílání viditelně zopakovala žádost o federální pomoc při katastrofě, než souhlasíte. Pomoc dorazí. Klip taky, navždy."]]},"n-fire-the-forecaster":{"t":"Vyhozená meteoroložka","x":"Kaylee má výpovědní dopis, jenže to není rezignace. \"Dnes ráno jste vyhodil ředitelku regionální meteorologické služby kvůli předpovědi, která se u bouře spletla o šest hodin, pane. Dělá to dvaadvacet let. Předpověď byla v mezích normální odchylky pro bouři té velikosti. Potřebuju vědět, co mám za devět minut říct sálu.\"","c":[["Je vyhozená. Říct, že stála lidské životy. Jít dál.","Vyhodíte zkušenou meteoroložku kvůli normální odchylce a oznámíte to jako odpovědnost. Každý meteorolog, který se o tom doslechne, si začne navyšovat intervaly spolehlivosti, což zhorší úplně každou budoucí předpověď."],["Znovu ji přijmout. Říct, že odchylka byla normální.","Dvaadvacetiletá kariéra nekončí kvůli statistice, která dělá to, co statistika dělá. Je to tichá náprava, a správná."],["Vyhodit ji, a s ní celý regionální úřad.","Celý regionální předpovědní úřad je propuštěn kvůli časování jedné bouře. Další bouři v tom regionu předpovídá, s nedostatkem personálu, tým o tři státy dál, který nikdy neviděl místní terén."],["Nabídnout jí svou práci na týden, ať vidí, jak se jí líbí.","Navrhnete, zřejmě vážně, týdenní výměnu práce s federální meteoroložkou. Odmítne dvouvětým e-mailem, o kterém několik zaměstnanců soukromě přizná, že je to nejlepší text, který z téhle budovy za celý měsíc vzešel."]]},"n-swing-state-declaration":{"t":"Rychlost prohlášení","x":"Deborah má na stole rozloženou časovou osu. \"Povodeň v Kansaw, kde jste vyhrál o devět bodů, dostala prohlášení o katastrofě za šest hodin. Povodeň v Meridii, kde jste prohrál, je čtvrtý den bez prohlášení a bez vysvětlení z tohoto úřadu, proč tomu tak je.\"","c":[["Nechat rozdíl tak. Meridia si počká na papírování.","Stát, který hlasoval proti vám, čeká čtyři dny navíc na federální pomoc při katastrofě, zatímco identická povodeň o dva státy dál se vyřídila za odpoledne. Obě fakta skončí ve stejném zpravodajském cyklu, vedle sebe."],["Vyhlásit obojí podle stejného harmonogramu. Pokaždé.","Jednotný šestihodinový standard, bez ohledu na to, jak okres hlasoval. Není to efektní, ale je to, jak se ukazuje, skutečný záměr zákona."],["Ještě zrychlit Kansaw. Nechat Meridii čekat déle.","Místo aby se rozdíl uzavřel, veřejně ho ještě zvětšíte, zatímco novinář s kalendářem a mapou udělá za vás zbytek práce."],["Nechat Deboru podepsat obojí, bez ohledu na volební mapy.","Deborah správně podepíše obě prohlášení bez ohledu na volební mapy. Vy si pak v projevu osobně přivlastníte zásluhu za tu vyváženost, čímž zrušíte zhruba polovinu dobré vůle, kterou to rozhodnutí získalo."]]},"n-weather-weapon":{"t":"Zbraň na počasí","x":"Errol Hance volí slova viditelně s námahou. \"Řečník na pódiu včera v noci prohlásil, že Rusalka má stroj na řízení hurikánů. Pane, řídím skutečnou zpravodajskou agenturu. Věděl bych o tom. Nikdo žádný stroj na hurikány nemá. Potřebuju, abyste to buď řekl vy, nebo abyste po mně nechtěl pomoct vám to neříct.\"","c":[["Ani nepotvrdit, ani nepopřít. Nechat to doutnat.","Odmítnete opravit tvrzení řečníka na shromáždění, že soupeřská země ovládá počasí. Teorie se rozroste do tří televizních segmentů a dopisu Kongresu žádajícího tajný brífink o stroji, který neexistuje."],["Jasně to opravit. Žádný stroj na počasí neexistuje.","Krátké, jasné, nudné prohlášení: podle skutečného zpravodajského hodnocení taková technologie neexistuje na žádné straně. Příběh za den skončí."],["Tvrdit, že my máme ještě větší stroj na počasí.","Bez podrobností naznačíte, že americká schopnost ovládat počasí předčí kohokoli jiného. Errol je požádán, aby informoval tři senátory o programu, u kterého právě dokončil vysvětlení, že neexistuje."],["Vyžádat si skutečný tajný brífink o řízení hurikánů.","Svolá se skutečný zpravodajský brífink, se skutečnými náklady, o proveditelnosti technologie řízení hurikánů. Odpověď, po týdnu práce šesti analytiků, zní jedním slovem: ne."]]},"n-anniversary-tour":{"t":"Výroční turné","x":"Dr. Weirová má itinerář a nepříjemný pocit z něj, který se rozhodne vyjádřit. \"Je to první výročí povodně, pane. Plán turné počítá s návštěvou obnoveného náměstí, které je skutečné a opravdu vypadá skvěle. Nezmiňuje, že šest tisíc lidí tři kilometry odsud pořád žije v dočasném bydlení, záměrně mimo záběr kamer.\"","c":[["Nechat trasu tak. Náměstí se skvěle fotí.","Jeden obnovený blok zastupuje obnovu, která tři kilometry odsud zdaleka není dokončená. Záběry jsou opravdu krásné a opravdu zavádějící, přesně ve stejné míře."],["Vést trasu i skrz dočasné bydlení. Celkový obraz.","Projdete si dokončené náměstí i šest tisíc lidí, kteří za ním pořád čekají. Je to horší fotka, ale pravdivější výročí."],["Úplně vynechat město. Místo toho poslat věnec.","Věnec dorazí kurýrem místo prezidenta, v den výročí povodně, která zabila lidi z toho města. Gesto je zaznamenáno, hlavně kvůli té vzdálenosti."],["Nastěhovat se do dočasného bydlení, ale rodina se napřed přesune do hotelu.","Strávíte výroční noc v jednotce, kterou pro tuto příležitost uvolnila rodina, jež tam skutečně žije, a ta stráví noc v hotelu, který jste jí znovu nenabídl, jakmile kamery odjely."]]},"o-outbreak-briefing":{"t":"První brífink","x":"Wendell drží dvě složky. „Virus je nový, pane, a poctivá čísla v této složce nejsou dobrá. Optimistická čísla v této složce nejsou skutečná. Za dvanáct minut jdeme k pultíku a já potřebuju vědět, kterou složku mám držet.“","c":[["Drž složku s dobrými čísly.","Wendell přečte projekce vymyšlené přesně pro tuto chvíli. Novináři si je stejně zapíšou, protože to je jejich práce, a skutečná křivka je jedno, co zaznělo u pultíku."],["Ať přečte skutečná čísla, bez příkras.","Skutečná čísla jsou špatná a zazní bez jediného přídavného jména. Je to nejméně uklidňující a nejužitečnější věc, která u pultíku zazněla za celý rok."],["Zapomeň na složky. Řekni „máme to naprosto pod kontrolou“.","Čtyři slova, žádná data, okamžitý potlesk od lidí, kteří by tleskali tak jako tak. Počet nakažených na brífink nepřišel."],["Pošli Wendella domů. Brífink si vezmi na starost sám, bez scénáře.","Čtyřicet minut improvizuješ epidemiologii z hlavy. Wendell to sleduje ze zákulisí s tím zvláštním klidem muže, který si v duchu právě aktualizuje životopis."]]},"o-podium-theatrics":{"t":"Řečnický pultík","x":"Kaylee předělala tiskovou místnost: grafy s vaší tváří jako vodoznakem v rohu, signál pro smích u nakloněných novinářů a skutečný zvonek na umlčení těch ostatních. „V testech to bodovalo skvěle, pane. Nikoho to o ničem neinformuje, ale v testech to bodovalo opravdu skvěle.“","c":[["Nainstaluj zvonek. Zvoň na něj často.","Zvonek se stane nejcitovanějším zvukem celého zpravodajského cyklu. Nikdo si nevzpomene na jedinou odpověď, která zazněla mezi zazvoněními."],["Zruš divadlo. Prostě odpovídej na otázky.","Brífink, který skutečně informuje. Je to vskutku neobvyklý pohled a tři média to okomentují jako zprávu samu o sobě."],["Přidej odpočítávací hodiny a publikum ve studiu.","Pultík teď připomíná televizní soutěž, protože se jí díky Kayleeině tichému naléhání skutečně stal."],["Ať příští brífink zvládne Brayden sám, naživo, bez scénáře.","Devatenáctiletý mladík čtyřicet minut v kuse odpovídá na otázky o úmrtnosti. Navzdory všem očekáváním působí zvláštně přesvědčivě, byť naprosto nepřipraveně."]]},"o-injecting-light":{"t":"Skvělý nápad","x":"Nadhodil jste to naživo, před kamerami, jako otázku: něco o světle uvnitř těla, které by mohlo vyčistit organismus. Ronny stojí naprosto bez hnutí. „Pane, chtěl bych, aby bylo v záznamu uvedeno, že jsem to neřekl, nikdo se mě neptal a právě teď píšu vyjádření, které bych opravdu psát nechtěl.“","c":[["Trvej na svém. Byla to seriózní vědecká otázka.","Dlouze trváte na tom, že ten nápad si zaslouží výzkum. Linky toxikologické pohotovosti se po celé zemi rozžhaví voláními lidí, kteří vás vzali doslova, protože jste to doslova myslel."],["Ať to Ronny rychle a věcně uvede na pravou míru.","Ronny přečte dvouvětné vyjádření s vřelostí muže, který čte parkovací pokutu. Funguje to. Tento týden vypije čisticí prostředek méně lidí, než by jinak vypilo."],["Vysvětli, že to byl sarkasmus.","Vysvětlujete, že národ nerozeznal váš sarkasmus. Národ si pouští záznam znovu a znovu a stále není přesvědčen, že tam vůbec nějaký byl."],["Vyhlas celostátní grant na výzkum léčby světlem.","Federální peníze teď financují studii něčeho, co jste v úterý prohodil bez přípravy. Žadatelé o grant popisují hodnoticí komisi jako „neobvykle zapálenou“."]]},"o-quack-cure-tonic":{"t":"Elixír","x":"Brayden drží lahvičku. „Jmenuje se to Vitalume, pane. Influencerka, které vaši voliči věří, přísahá, že tím vyléčila svou sestřenici. Formálně to na žádné sestřenici testované nebylo, ale od úterý se toho prodalo čtyři sta tisíc kusů a někdo chce fotku, jak jednu držíte.“","c":[["Drž lahvičku. Usmívej se. Formálně neříkej žádnou lež.","Držíte lahvičku neověřeného elixíru a lhaní necháte na fotografii. Prodeje se ztrojnásobí. Toxikologická linka si zřizuje druhou telefonní přípojku."],["Nech to potichu otestovat ministerstvo zdravotnictví.","Laboratoř podrobí elixír standardnímu rozboru. Je to většinou voda a citrusová příchuť. Zpráva je přesná, nudná a nepřečte si ji vůbec nikdo z těch, kdo lahvičku koupili."],["Doporuč to jmenovitě v projevu.","Vyslovíte název značky u pultíku se státním znakem v pozadí. Právní oddělení stráví další měsíc vysvětlováním, co je to nepřímá reklama."],["Spusť konkurenční elixír pod vlastním jménem.","Do týdne se objeví konkurenční lahvička, stejná voda, lepší etiketa. Oba elixíry teď soupeří o tu samou neotestovanou sestřenici."]]},"o-change-the-count":{"t":"Upravené číslo","x":"Wendell drží memorandum, které by evidentně raději nedržel. „Přišel pokyn snížit hlášený počet případů, než se zveřejní víkendová čísla, pane. Ne proto, že by se změnilo testování. Ale protože to číslo vypadalo špatně vedle toho z minulého měsíce.“","c":[["Změň metodiku. Změň číslo.","Počet případů přes noc klesne o třetinu díky poznámce pod čarou o metodě počítání, kterou nikdo nečte, ale její dopady pocítí každý."],["Zveřejni skutečné číslo. Vysvětli trend.","Skutečné číslo je horší a takto se i zveřejní, i s vysvětlením. Není to nic okázalého a je to, ze své podstaty, jediná verze této práce, která lidem zachraňuje životy."],["Přestaň úplně počítat jednu kategorii.","Celá skupina případů se tiše přeřadí mimo datovou sadu. Číslo klesne. Vše, co to číslo mělo měřit, nikam neklesne."],["Zveřejni obě čísla vedle sebe, bez vysvětlení.","Ve stejném hlášení vyjdou dvě protichůdná čísla bez poznámky, které je to skutečné. Tři datoví novináři si do pátku vybudují na jejich rozplétání celou kariéru."]]},"o-death-toll-math":{"t":"Revize efektivity","x":"Roscoe má tabulku. „Prohnal jsem čísla nadúmrtnosti stejným modelem efektivity, jaký používáme u poštovní služby, pane, a mohu ohlásit, že administrativní náklady epidemie na jedno úmrtí jsou vlastně docela rozumné. Uvědomuji si, jak ta věta zní.“","c":[["Cituj to číslo efektivity veřejně. Zní to autoritativně.","Před kamerami citujete náklady na jedno úmrtí, jako by to něco řešilo. Neřeší to vůbec nic a straší vás to při každé další tiskové konferenci."],["Odlož tabulku k ledu. Místo toho financuj odezvu na epidemii.","Číslo skončí v šuplíku a peníze jdou tam, kde epidemie skutečně řádí. Je to správné rozhodnutí a nevygeneruje jediný titulek."],["Ať to Roscoe osobně přednese Kongresu.","Roscoe představí úmrtnost jako položku v rozpočtu místnosti, která znatelně ztichne. Dva poslanci odejdou. On jejich odchod považuje za jistou formu zapojení."],["Udělej Roscoemu za tu tabulku medaili.","Veřejně oceníte revizi efektivity, která měřila lidskou smrt v administrativní režii. Roscoe přijímá medaili s klidem muže, který v tom nevidí žádný problém."]]},"o-vaccine-rollout":{"t":"Spuštění očkování","x":"Wendell vykládá distribuční plán. „Funguje to, pane. Je to hotové, otestované, a podle všech modelů, které mám, je to jednoznačně nejrychlejší cesta ven z téhle situace. Komplikace je čistě politická: značná část vaší vlastní koalice si momentálně myslí, že je v tom sledovací čip.“","c":[["Označ to svým jménem. Prodávej to jako vítězství.","Vakcína dostane vaše jméno na krabičku a váš obličej na reklamu. Proočkovanost mezi vašimi voliči stoupne z přesně nesprávného důvodu a spadne v okamžiku, kdy ji pochválí kdokoli jiný."],["Ať to obhajují lékaři. Opakovaně. Trpělivě.","Žádný branding, žádný mítink, jen ti samí tři lékaři vysvětlující ta samá data ve všech médiích, která je pozvou. Je to pomalé, ale nakonec je to jediné, co skutečně pohne číslem."],["Podmiň tím federální dávky.","Naočkování svážete s výplatou dávek. Je to právně agresivní krok, okamžitě napadený u soudu, a účinkuje přesně na ty lidi, kteří vás nikdy nežalují."],["Vyhlas loterii. Nech se očkovat, vyhraj pickup.","Jeden pickup týdně, losovaný z registru očkovaných, naživo v televizi. Funguje to trapně dobře a nikdo v místnosti to pořádně neumí vysvětlit."]]},"o-vaccine-rally-resistance":{"t":"Propast důvěry","x":"Nadia opatrně pokládá memorandum. „Šedesát jedna procent vašich vlastních voličů říká, že se nenechá očkovat, pane, a číslo, které by vás mělo znepokojit, je tohle: ti, kdo vám nejvíc věří, věří tomu nejméně. Cokoli teď řeknete, buď to napraví, nebo to zabetonuje.“","c":[["Řekni voličům, že je to jejich volba. Nic víc nedodávej.","Odmítnete investovat jakýkoli kapitál do posunutí toho čísla. Neutralita v místnosti plné podezření zní jako potvrzení. Číslo se nehne."],["Nech se sám naočkovat před kamerou, bez humbuku.","Vyhrnete si rukáv bez jediného slova navíc. Je to malý, tichý důkaz a pohne to číslem víc než jakýkoli projev."],["Naznač, že je to vakcína té druhé strany.","Naznačíte, aniž byste to řekl přímo, že očkování má stranickou příslušnost. Číslo se podél přesně této linie natrvalo rozštěpí ještě víc."],["Veřejně se vsaď se senátorem, že se také neočkuje.","Televizní sázka mezi dvěma muži, kteří by měli řešit veřejné zdraví. Senátor sázku přijme. Ani jeden se z toho nic nepoučí."]]},"o-storm-shelter-outbreak":{"t":"Útočiště","x":"Duane má záznamy z útočiště. „Dvanáct tisíc lidí pod jednou střechou po bouři, pane, lehátka od sebe pětačtyřicet centimetrů, a teď se nám na první krizi nabalila druhá. Evakuovaní se nepřihlásili na dvě krize. My jsme rozpočtem počítali jen s jednou.“","c":[["Zavři útočiště. Pošli je domů do zatopených domů.","Epidemii vyřešíte tak, že jí odeberete adresu. Dvanáct tisíc lidí se vrátí do domů bez střechy, což je jiná krize s horšími fotografiemi."],["Rozděl útočiště. Pomaleji, dráž, bezpečněji.","Tři budovy místo jedné, víc lehátek, víc personálu, víc nákladů. Je to nevzhledná logistika, která to skutečně zvládne udržet pod kontrolou, a tabulku nikdo nefotí."],["Přiděluj lepší lehátka podle dárcovské historie.","O tom, kdo dostane lehátko mimo průvan, rozhoduje loajalita. Do dne to unikne na veřejnost a fotografie, která koluje, je přesně taková, jakou byste čekali."],["Místo zdravotníků pošli na povzbuzení nálady kapelu Národní gardy.","Dechovka hraje vlastenecký evergreen nad sálem plným horečnatých evakuovaných. Nálada, proti očekávání, není tím hlavním problémem."]]},"o-misinfo-hurricane":{"t":"Hurikán","x":"Brayden vám ukazuje přehled. Čtyřicet milionů sdílení za šest hodin: virus je podvod, virus je biologická zbraň, lék máte ve spíži, ten lék je taky podvod. „Není to jedna lež, pane, je to hurikán lží, a všechny se šíří rychleji, než se na téhle platformě kdy šířilo cokoli pravdivého.“","c":[["Svez se na tom. Sdílej ty, co ti pomáhají.","Zesílíte ty, které lichotí příběhu, jaký chcete vyprávět. Bouře dostane další poryv a vy jí ho osobně dodáte."],["Financuj kanál s věcnými vyvráceními. Nudný. Rychlý.","Žádné rozhořčení, žádná virálnost, jen správné informace zveřejňované rychle, znovu a znovu, lidmi bez špetky charismatu. Osloví to jen zlomek publika, ale každý kousek se počítá."],["Sval to na platformu. Vyhrožuj jejím zrušením.","Hrozíte poslu kvůli objemu zprávy. Platforma přežije. Hrozba se sama stane virálním momentem a přiživí přesně tu bouři, kterou jste chtěl zastavit."],["Ať Brayden týden nepostuje nic jiného než videa s kočkami.","Oficiální účet o krizi mlčí a sedm dní zveřejňuje jen kočky. Zapojení publika se zhroutí spolu s jakýmkoli tvrzením, že jste to měli pod kontrolou."]]},"o-moon-vanity-mission":{"t":"Projekt Úsvit","x":"Dr. Brennanová má plán mise a výraz, který napovídá, že ho pročetla pečlivěji než vy. „Chcete boty na Měsíci ještě před volbami v polovině období, pane. Inženýrský harmonogram říká třicet jedna měsíců. Politický harmonogram, který jste oznámil, říká čtrnáct.“","c":[["Datum oznam tak jako tak. Čtrnáct měsíců. Veřejně.","Dáte raketě kampaňový termín, který fyzicky nemůže splnit. Inženýři se teď zodpovídají kalendáři místo kontrolnímu seznamu, a přesně tak kontrolní seznamy přestávají mít smysl."],["Přijmi třicet jedna měsíců. Řekni to jednou a jasně.","Oznámíte skutečné datum pro skutečnou misi a necháte ho být méně vzrušující, než bylo slíbeno. Je to jediná zcela spolehlivá věc, která o programu za celý rok zazněla."],["Posuň zapíchnutí vlajky dřív. Vědecký náklad nech doma.","Mise dorazí podle plánu s vlajkou a bez přístrojů. Formálně je to přistání. Neměří to vůbec nic."],["Přejmenuj misi po svém hotelovém řetězci.","Veřejně financovaná měsíční mise teď sdílí jméno s letoviskem. Dr. Brennanová podává papíry se zjevně zaťatou čelistí."]]},"o-mars-timeline-promise":{"t":"Slib o Marsu","x":"„Na mítinku jste slíbil, že do konce druhého funkčního období budeme mít lidi na Marsu, pane.“ Dr. Brennanová to říká tónem, jakým se čte obžaloba obžalovanému. „Chtěla bych do záznamu uvést, že v místnosti, kde jste to řekl, nebyl nikdo z mé agentury.“","c":[["Nařiď agentuře, ať termín splní. Ať najdou způsob.","Nařizujete fyzice, ať se přizpůsobí vašemu harmonogramu. Fyzika neposlechne. Dodavatelé si za pokus stejně naúčtují, což je jediná část plánu, která funguje přesně podle slibu."],["Oprav záznam. Uveď skutečné desetiletí.","Potichu posunete termín na něco, pod co by se podepsal i inženýr. Stojí vás to titulek, ale mise díky tomu má skutečnou šanci se uskutečnit."],["Oznam „přípravný“ let s posádkou kolem Marsu, ať získáš čas.","Mise, která proletí kolem Marsu a nepřistane, je představena jako milník. Je to, řečeno velkoryse, velmi drahá fotografie."],["Slib u pultíku, že poletíš osobně sám.","Slíbíte, že budete prvním prezidentem na Marsu. Tajná služba na to založí spis. Nikdo v tom spisu tomu nevěří, nakonec ani vy."]]},"o-weather-control-conspiracy":{"t":"Kdo řídí bouři","x":"Cassandra obhajuje program umělého zasévání mraků proti suchu, který už deset let potichu funguje. „Teorie, která se šíří, pane, tvrdí, že úmyslně navádíme hurikány na lidi, kteří vás nevolili. Chtěla bych už počtvrté tento týden zopakovat, že zaséváme mraky nad třemi okresy, ne nad celým pobřežím.“","c":[["Nech tu teorii žít. Zní to mocně.","Odmítnete opravit konspirační teorii, která lichotí vašemu dosahu. Je to levné, je to zhoubné a dnes vás to nic nestojí, což je přesně ten druh nákladu, který se časem nabaluje."],["Zveřejni skutečná data programu. Všechna.","Deset let záznamů o zasévání mraků jde online, rozepsaných po okresech a centimetrech srážek. Je to vyčerpávající, nevzhledné, a je to jediná věc, která kdy konspirační teorii skutečně nabourala."],["Zruš skutečný program, abys „dokázal“, že se nemá co skrývat.","Zrušíte funkční program proti suchu, abyste vyvrátil teorii o programu úplně jiném a smyšleném. Sucho ten rozdíl nezná."],["Přiznej si zásluhu za ovládání počasí. Za celé.","Oficiálně na sebe berete odpovědnost za každou bouři na polokouli. Meteorologové jsou nadšeni, že teď mají koho osobně vinit za studenou frontu."]]},"o-mask-mandate-flip":{"t":"Roušky ano, roušky ne","x":"Wendell má na notebooku otevřená dvě tisková prohlášení, identická až na jedno slovo. „Data se od doporučení, které jsme vydali v březnu, nezměnila, pane. Změnilo se to, že nošení roušky se z ničeho nic stalo osobním vyjádřením postoje k vám, a prý je to teď to rozhodující kritérium.“","c":[["Otoč doporučení podle nálady voličů.","Nařízení se otočí podle průzkumu, ne podle křivky nákazy. Další vlna se nepodívá, které tiskové prohlášení právě platí, než dorazí."],["Nech doporučení svázané s daty. Řekni to nahlas.","Doporučení zůstává ukotvené ve skutečných číslech, ať je to sebeméně módní. Je to správné rozhodnutí a tento měsíc i nepopulární."],["Nech o tom hlasovat každý stát zvlášť. Ať se z toho stane politikum.","Padesát různých odpovědí na jednu klinickou otázku, rozhodnutých padesáti různými zákonodárnými sbory. Virus se taky nedívá, v jaké je jurisdikci."],["Nos roušku ve tvaru vlajky. Kompromis.","Roušku s vlasteneckým potiskem neocení žádný epidemiolog, ale potěší několik prodejců suvenýrů. Wendell se potichu zeptá, zda potisk ovlivňuje filtraci. Ovlivňuje, mírně, a k horšímu."]]},"o-testing-suppression":{"t":"Méně testů, méně případů","x":"Nadhodil jste to na menší poradě, napůl žertem: kdybychom prostě testovali méně lidí, číslo by kleslo. Wendell se nezasmál. „To je pravda, pane, přesně v tom smyslu, že vypnutí hlásiče kouře sníží počet nahlášených požárů.“","c":[["Potichu zpomal rozšiřování testování.","Testovacích míst ubývá a poslušně s nimi ubývá i to číslo. To, co číslo měřilo, se s ním nezmenšuje, jen se to přestane počítat."],["Rozšiř testování. Zveřejni skutečný trend.","Více testů, hůř vypadající číslo a skutečně užitečný obraz toho, kde epidemie doopravdy je. To je celá ta práce a nikdy se to nestane virálním."],["Řekni, že vysoké číslo je „podvod“ s testováním.","Popíšete přesná data jako spiknutí namířené osobně proti vám. Data zůstávají lhostejně dál přesná."],["Nařiď přesun testovacích míst do oblastí, které tě už tak volí.","Dostupnost testování se potichu přerozdělí podle volební mapy místo mapy nákazy. Ty dvě mapy se neshodují a ten nesoulad má na svědomí lidské životy."]]},"o-agency-director-fired":{"t":"Obětní beránek","x":"Deborah má připravený návrh rezignačního dopisu, chybí jen Wendellův podpis, který ještě nedal. „Opravil vás v televizi, pane, ohledně jednoho čísla, před jedenácti miliony lidí. Měl pravdu. A přesně to na tom celém je nějak ještě horší.“","c":[["Vyhoď ho dnes večer. Oznam to sám.","Odstraníte jediného úředníka, kterému místnost skutečně věřila, naživo, za zločin přesnosti. Jeho nástupce se od teď vybírá hlavně podle vstřícnosti."],["Nech ho. Poděkuj mu za opravu.","Necháte podřízeného, aby vás veřejně opravil, a přežijete to. Je to malý, zvláštní projev sebejistoty, který ministerstvu vynese víc důvěryhodnosti než rok dobrého PR."],["Přesuň ho na výzkumné místo bez oken.","Ponechá si titul, ale ztratí pultík, přeřazen do zařízení, které zkoumá složení půdy. Na degradaci, s tím všichni souhlasí, je maskování odvedeno mimořádně dobře."],["Povyš ho. Dej mu na starost tvou komunikaci.","Muž, který vás opravuje na obrazovce, teď zodpovídá za to, co na obrazovce řeknete. Povýšení bere jako situaci s rukojmím a ke cti mu slouží, že vyjednává dobře."]]},"o-surgeon-general-muzzled":{"t":"Roubík","x":"Ronnymu bylo šetrně sděleno, že jeho vystoupení v médiích teď vyžadují schválení čtyřicet osm hodin předem. „Chápu koncept mediální kázně, pane. Chtěl bych ale poznamenat, že epidemie se čtyřicetiosmihodinovou lhůtou na posouzení neřídí.“","c":[["Trvej na lhůtě na posouzení. Bez výjimek.","Národní lékař teď potřebuje povolenku, aby zodpověděl otázku o horečce. Další aktualizace o epidemii dorazí o dva dny později, než by byla užitečná."],["Dej mu místo toho pevný týdenní termín.","Naplánovaný, nefiltrovaný brífink, každý týden, oficiálně. Je to nejméně kontrolující možnost ze všech a zdaleka i nejdůvěryhodnější položka v celém kalendáři."],["Ať vše schvaluje jen Kaylee, zprávu po zprávě.","Každá klinická odpověď teď prochází nejdřív tiskovým oddělením. Odpovědi jsou kratší, vágnější a přicházejí podstatně později."],["Dej Ronnymu vlastní noční telefonický pořad.","Prezidentův osobní lékař teď v jedenáct večer naživo odpovídá volajícím na otázky o vyrážkách. Sledovanost je skromná. Veřejnému zdraví to, nečekaně, prospívá."]]},"o-military-vaccine-mandate":{"t":"Stálý rozkaz","x":"Generál Tarrant nerad předává personální čísla jako ztráty. „Čtrnáct tisíc lidí odmítá očkování z principu, pane, a podle platných předpisů to znamená čtrnáct tisíc propuštění, která musím zpracovat v armádě, která už teď má nedostatek personálu.“","c":[["Trvej na tom. Propusť každého odmítače.","Čtrnáct tisíc příslušníků ozbrojených sil odchází kvůli zdravotnickému nařízení vymáhanému s vojenskou přesností. Bojeschopnost klesá. Pravidlo je na papíře splněno dokonale."],["Zaveď strukturovaný proces výjimek. Pomaleji, potichu.","Přezkumná komise, případ od případu, nevzhledná jako každá administrativa. Méně propuštění, časem více očkovaných a ani jeden dramatický titulek."],["Udělej z odmítnutí otázku osobní loajality k tobě.","Klinický požadavek přerámujete na test loajality. Tarrantova tvář dělá ten výraz, který dělá, když si v duchu skládá svůj budoucí rezignační dopis."],["Nabídni odmítačům místo propuštění přeložení na základnu v Antarktidě.","Odlehlé místo se nabídne jako alternativa k propuštění. Devět dobrovolníků nabídku přijme. Logistické oddělení na devět lidí plán nemělo, teď ho má."]]},"o-vaccine-passport-program":{"t":"Pas","x":"Duane ukazuje návrh aplikace. „Digitální pas, pane, kontrolovaný na letištích a stadionech, navázaný na stav proočkování. Skutečně by to zpomalilo šíření. Zároveň by to znamenalo, že federální vláda kontroluje zdravotní záznam, než pustí občana dveřmi.“","c":[["Vytvoř to. Povinně, celostátně, do podzimu.","Federální zdravotní kontrola se stane podmínkou pohybu. Funguje to, klinicky vzato. Zároveň to předáváte svému nástupci jako nástroj, který v cizích rukou uvidíte neradi."],["Nech to dobrovolné, po jednotlivých státech.","Žádný federální mandát, jen dobrovolný standard, který si státy mohou osvojit. Je to pomalejší, roztříštěnější, ale jediná verze, která bez úhony přežije každou soudní výzvu."],["Vyžaduj to jen pro lety do měst vedených opozicí.","Požadavek je potichu nesymetrický podle cílové destinace. Do týdne se to provalí a v tu chvíli už je to celý příběh."],["Nahraď aplikaci fyzickou voskovou pečetí na ruce.","Doslovné razítko, s inkoustem a vším, místo digitálního záznamu. Zastánce občanských svobod to nějak znepokojuje víc než aplikace a padělat se to dá podstatně snáz."]]},"o-fish-tank-cleaner":{"t":"Zásoba","x":"Roscoe hlásí zásobovací problém, se kterým nikdo nepočítal. „Neověřený lék, který jste v televizi chválil, je chemicky totožný s odčervovadlem pro dobytek, pane, a my jsme teď skoupili celostátní zásoby. Farmáři ho nemohou sehnat pro skutečný dobytek. To je, z hlediska nákupu, nový druh problému.“","c":[["Nakupuj dál. Vyhlas „strategickou rezervu“.","Federální rezerva odčervovadla pro dobytek je prohlášena za otázku veřejného zdraví. Dva zemědělské státy jsou do měsíce bez zásob. Nikdo neplánoval, že tohle bude ta krize."],["Vrať zásoby farmářům. Uveď věc na pravou míru.","Zásoby se vrátí tam, kde byly potřeba, a lék dostane veřejnou, nevzhlednou opravu. Znovu je to celá ta práce a virální se to nestane."],["Rozděl to: polovina na lék, polovina pro dobytek.","Kompromis, který neřeší dobře ani jeden problém. Dobytek dostane méně, než potřebuje, a lidem lék pořád nic nedělá."],["Ať Roscoe osobně otestuje dávku před kamerou.","Car efektivity spolkne před kamerami dávku odčervovadla pro dobytek, aby dokázal něco, co po něm nikdo nechtěl dokazovat. Přežije to. Jeho obliba na chvíli převýší tu vaši."]]},"o-faith-healer-oval":{"t":"Vzkládání rukou","x":"Reverend Muncy přivedl hosta: léčitelku, která tvrdí, že má zdokumentovanou úspěšnost léčení pouhým dotykem, nikým s lékařskou licencí neprověřenou. „Má víc příznivců než celé ministerstvo zdravotnictví, pane. Nežádám vás, abyste tomu věřil. Žádám vás, abyste zvážil, co vás bude stát, když ji pustíte do místnosti.“","c":[["Ať se modlí před kamerami. Plný přístup.","Léčitelka dostane fotografickou příležitost v Bílém domě místo klinického brífinku. Záběry se rozšíří dál než jakákoli tisková zpráva, kterou jste letos vydal, a to směrem, za nímž nestojí žádná data."],["Setkejte se soukromě. Nezveřejňujte to vůbec.","Tichý, uctivý, nefotografovaný rozhovor. Nikdo se nevysmívá ničí víře a nikdo si nesplete vzkládání rukou s klinickou studií. Nestojí vás to nic a nic měřitelného vám to ani nepřinese."],["Ať nahradí zdravotní brífink v harmonogramu.","Denní zdravotní aktualizace je odsunuta kvůli léčebnému obřadu. Ministerstvo se přesune na termín se zlomkem publika a bez kadidla."],["Zeptej se jí, zda by mimochodem nezvládla vyléčit i rozpočtový deficit.","Zeptáte se, zjevně upřímně, jestli ten dotyk funguje i na fiskální záležitosti. Reverend na vás pohlédne pohledem, jakým se hledí na muže, který konečně vyslovil to, co si všichni mysleli."]]},"o-5g-conspiracy-post":{"t":"Repost","x":"Brayden v jednu ráno sdílel z oficiálního účtu příspěvek: teorii spojující nové vysílače s epidemií, bez zdroje, do snídaně už na dvou milionech zhlédnutí. „Už to bylo trendy, pane. Já to jen, víte. Zesílil. To je technicky náplň práce.“","c":[["Nech to viset. Ať si to voliči přeberou po svém.","Teorie zůstává živá pod prezidentskou pečetí. Technici od vysílačů začínají dostávat výhrůžky kvůli infrastruktuře, která nevysílá nic nebezpečnějšího než aplikaci na počasí."],["Smaž to. Zveřejni opravu, bez výmluv.","Příspěvek zmizí do hodiny s prostou opravou přiloženou k němu. Je to malý, nudný akt hygieny a stojí to za víc, než se zdá."],["Řekni, že to bylo „jen otázka“, ne podpora.","Popisujete šíření nepodložené teorie celé své sledovanosti jako pouhé „kladení otázek“. Technici výhrůžky dostávají dál, bez ohledu na rámování."],["Ať Brayden navštíví vysílač před kamerou, aby to vyvrátil.","Devatenáctiletý mladík stojí čtyřicet pět minut u vysílače, aby dokázal negativní tvrzení. Funguje to lépe než oprava, z důvodů, které žádná teorie komunikace plně nevysvětluje."]]},"o-superspreader-rally":{"t":"Mítink musí pokračovat","x":"Nadia má čísla z obou stran. „Zrušíš to a voliči to přečtou jako strach, pane. Uspořádáš to, v hale, dvanáct tisíc lidí, bez rozestupů, a vlastní model ministerstva zdravotnictví říká, že do dvou týdnů uvidíme nárůst případů, který povede přímo k tomuto místu.“","c":[["Uspořádej to. Větší hala. Roušky nepovinné.","Dvanáct tisíc lidí jásá v jedné místnosti. Nárůst dorazí přesně podle modelu, přesně tam, kde model předpověděl, a na mítink vzpomínají v dobrém všichni, kdo potom neskončili v nemocnici."],["Přesuň to ven. Menší akce. S rozestupy.","Menší, bezpečnější akce, která v televizi působí o něco méně vzrušivě. Je to správný kompromis a nikdo o něm nikdy nebude skandovat."],["Uspořádej to v hale, ale nejdřív nech podepsat prohlášení o odpovědnosti.","Právní dokument zbaví kampaň odpovědnosti za výsledek, který ministerstvo zdravotnictví už předpovědělo. Na fyzice té místnosti to nic nemění."],["Přenášej virtuální mítink naživo. Hologram sebe sama na pódiu.","Mihotavá projekce vás oslovuje prázdnou arénu. Účast je nulová. Nikdo se ničím nenakazí. Recenze to nazývají, nemile ale přesně, generálkou."]]},"o-school-reopening-pressure":{"t":"Zpátky do budovy","x":"Bernadette má dvě protichůdná memoranda. „Model ministerstva zdravotnictví říká počkat šest týdnů, pane. Voliči chtějí otevřené třídy už v pondělí. Nemůžu vám dát memorandum, které uspokojí obojí, protože popisují dvě různé nemoci v dvou různých rychlostech.“","c":[["Otevři v pondělí. Oznam to jako návrat k normálu.","Třídy se v termínu zaplní a křivka případů se harmonogramu školy neptá, než začne stoupat. Ukáže se, že „normál“ byla volba, ne fakt."],["Drž se šestitýdenního modelu. Mezitím financuj distanční výuku.","Šest dalších týdnů notebooků a trpělivosti, tentokrát pořádně financovaných. Neuspokojí to ničí pocit naléhavosti a je to, měřitelně, bezpečnější číslo."],["Znovuotevři jen v okresech, které tě podpořily.","Mapa znovuotevření se potichu překreslí podle volebních, nikoli nákazových hranic. Učitelka v opozičním okrese se před kamerou zeptá, podle jaké mapy se řídí virus."],["Vyučuj venku. Úplně všechno. Každý předmět.","Trigonometrie pod stanem v říjnu. Je to chladnější, než kdokoli čekal, a epidemiologicky to vůbec není špatný nápad."]]},"o-withdraw-world-health-body":{"t":"Dopis o odchodu","x":"Muriel má připravený, nepodepsaný dopis o odchodu. „Odchod z mezinárodního zdravotnického orgánu nám ušetří členské příspěvky, pane, a zároveň nás vyřadí z místnosti, kde se příští epidemie pojmenovává, sleduje a sdílí dřív, než dorazí k našim břehům. To spolu souvisí víc, než by se zdálo.“","c":[["Podepiš to. Odejdi okamžitě, uprostřed krize.","Opustíte místnost právě v okamžiku, kdy na tom nejvíc záleží. Úspory jsou skutečné a skromné. Informace, které už nedostáváte jako první, jsou obojí to samé jinak."],["Zůstaň. Prosazuj reformu zevnitř.","Pomalejší, méně uspokojivá cesta: zůstat, stěžovat si a občas přesvědčit jeden hlas. Udrží to otevřenou linku včasného varování, které si nikdo nevšimne, dokud někomu nezachrání život."],["Odejdi, pak se potichu vrať pod jiným jménem.","Odejdete nahlas a diskrétně se vrátíte, přejednáte tytéž příspěvky pod novou hlavičkou. Voliči vidí odchod. Návrat nevidí."],["Založ konkurenční zdravotnický orgán se třemi spřátelenými zeměmi.","Vzniká nová aliance, sídlící v půjčené zasedací místnosti, s mandátem, který nikdo nedopsal. Zatím nesdílí data s nikým, včetně vás."]]},"o-ppe-hoarding":{"t":"Ty dobré roušky","x":"Duane má seznam, který nevytvořil, ale musí ho teď obhájit. „Národní zásoby jsou nedostatečné, pane, nemocnice ve třech státech recyklují roušky určené na jedno použití, a čtyřicet tisíc kusů těch dobrých šlo dnes ráno do soukromé kliniky dárce. Chci mít v záznamu, že jsem na to upozornil.“","c":[["Nech dárci roušky. Zasloužil si je.","Čtyřicet tisíc roušek zůstává u muže, který je nepotřeboval tak naléhavě jako tři nemocnice. Zpráva o tom dorazí dřív než samotná zásilka."],["Vezmi je zpátky. Přesměruj do postižených států.","Nepříjemný telefonát s dárcem a náklaďák přesměrovaný tam, kde je nedostatek skutečný. Stojí to přátelství a zachrání to sestrám celou směnu, kdy by jinak recyklovaly jednorázové vybavení."],["Rozděl zásilku. Půl dárci, půl nemocnicím.","Kompromis, po kterém jsou obě strany krátké. Dárce je mírně otrávený a nemocnice pořád omezují, jen s o něco lepší aritmetikou."],["Ať Alvin pošle nemocnicím roušky z lněné komory rezidence.","Skromná krabice dekorativních látkových roušek z rezidence dorazí k nakládací rampě nemocnice. Gesto je upřímné, malé a klinicky téměř bezcenné."]]},"o-ventilator-manufacturing":{"t":"Zakázka","x":"Roscoe našel výrobce, který dodá ventilátory za devět dní místo devadesáti. „Nikdy předtím žádný ventilátor nevyrobili, pane. Vyrábějí prodejní automaty. Chci zdůraznit, že mechanický princip není totožný, a chci to zdůraznit dřív, než cokoli podepíšete.“","c":[["Podepiš to. Devět dní je lepší než devadesát, vždycky.","Výrobce prodejních automatů se přeorientuje na ventilátory v devítidenním sprintu. Některé kusy fungují dokonale. Stažení zbytku z oběhu proběhne potichu, později, až titulek už dávno vyšel."],["Vyber devadesátidenního, kvalifikovaného výrobce.","Pomalejší, nudná, kvalifikovaná varianta. Každý kus funguje. Nikdo nepokryje příběh o ventilátoru, který fungoval přesně tak, jak měl."],["Rozděl zakázku mezi oba výrobce. Zajisti se.","Půl rychlé sázky, půl bezpečné. Stojí to víc, než by stála samotná jedna možnost, a uspokojí to část budovy, která si potřebuje myslet, že pokryla všechny úhly."],["Ať Roscoe osobně zkontroluje každý kus z linky.","Car efektivity stráví tři týdny na výrobní hale kontrolou ventilů ručně. Nečekaně se v tom stane docela zdatným. Továrna mu nabídne práci."]]},"o-lab-funding-cut":{"t":"Grant","x":"Wendell obhajuje grant, který se přes noc stal mediálním tématem. „Laboratoř zkoumá přesně ten druh viru, se kterým teď bojujeme, pane. Zároveň se z ní stala na kabelových zprávách zkratka pro něco zlověstného, a zrušení grantu se bude asi týden líbit, než další neznámý virus všem připomene, proč tu byla.“","c":[["Zruš financování. Oznam to jako odpovědnost.","Laboratoř se zavírá a výzkum končí. Potlesk vydrží zhruba jeden zpravodajský cyklus. Příští neznámý virus dorazí a chybí u něj jeden tým, který by ho dokázal rozpoznat včas."],["Zachovej financování. Přidej nezávislý dohled.","Laboratoř zůstává otevřená pod novou vrstvou nezávislé kontroly. Skoro nikoho to nahlas neuspokojí a podle důkazů je to zodpovědné rozhodnutí."],["Zruš to a pak potichu financuj stejnou práci pod novým názvem grantu.","Politicky toxická rozpočtová položka zmizí a znovu se objeví pod přívětivější formulací. Výzkum pokračuje. Papírová stopa se stává podstatně těžší k vysvětlení později."],["Přesuň laboratoř na vojenskou základnu, „pro dohled“.","Základní virologický výzkum se stěhuje za kontrolní stanoviště, které nebylo stavěno pro Petriho misky. Vědci teď potřebují bezpečnostní prověrku, aby se dostali ke svým vlastním mikroskopům."]]},"o-herd-immunity-pitch":{"t":"Kontrarián","x":"Lékař zvenčí ministerstva má vaše ucho, a Ronny z toho nadšený není. „Navrhuje, abychom nechali virus úmyslně projít celou populací a přeživší prohlásili za imunní, pane. Chci upozornit, že slovo ‚přeživší‘ v té větě dělá obrovský kus práce, a on navíc není odborník na nic relevantního.“","c":[["Přijmi tu strategii. Oznam ji jako odvážnou a moderní.","Necháte epidemii volně probíhat s teorií, že ti, kdo přežijí, budou stačit. Ministerstvo tomu přestane říkat strategie a začne tomu soukromě říkat výsledek."],["Odmítni ji. Drž se izolace, ať je sebenevzhlednější.","Odmítnete odvážný, hrozný nápad ve prospěch nudného, fungujícího. Stojí vás to titulek o rozhodnosti a zachrání to několik tisíc jiných věcí."],["Přijmi ji potichu, bez oznámení.","Strategie běží, aniž by kdy byla pojmenována jako strategie. Stejně se to odhalí, jak se tyhle věci vždycky odhalí, a absence oznámení se bere jako přiznání viny."],["Postav kontrariánského lékaře a Ronnyho do televizní debaty.","Dva lékaři na denní televizi hádají o etice na úrovni populace. Ronny vyhrává obsahem. Druhý muž vyhrává sdíleným klipem, což je samo o sobě malá lekce o povaze médií."]]},"o-pharma-donor-favor":{"t":"Rychlý pruh","x":"Miriam drží dva dokumenty, které dorazily s odstupem jednoho dne: sedmimístný dar a schvalovací memorandum na lék dárce, které přeskočilo dvě fáze přezkumu. „Nic netvrdím, pane. Jen konstatuji, že tyhle dva papíry jsou datované úterý a středa.“","c":[["Schval to. Časování je náhoda.","Lék projde schválením o dvě fáze dřív, jeden den poté, co se na účtu objeví velký šek. Nikdo v místnosti té náhodě nevěří, potichu ani vy."],["Vrať to do plného přezkumu. Bez výjimek.","Lék projde všemi fázemi, jak měl, dar nedar. Trvá to déle, uspokojí to proces, a dárcovy telefonáty zůstanou nějakou dobu bez odezvy."],["Schval to, ale vrať dar, ať to vypadá čistě.","Necháte urychlené schválení v platnosti a šek vrátíte jako gesto. Papírová stopa pořád ukazuje, co ukazuje. Gesto neoklame vůbec nikoho, kdo umí číst datum."],["Předej celou věc Miriaminu úřadu k veřejnému rozhodnutí.","Předáte vlastnímu etickému úřadu pravomoc rozhodnout o vás, veřejně, bez náhledu na výsledek předem. Je to buď zásadové, nebo lehkomyslné, a nebudete vědět které, dokud rozhodnutí nepadne."]]},"o-measles-comeback":{"t":"Návrat","x":"Wendell má počet případů nemoci, kterou ministerstvo považovalo za vyřešenou před dvaceti lety. „Je zpátky, pane, ve třech státech, výhradně mezi neočkovanými dětmi, protože proočkovanost, která bývala devadesát pět procent, klesla pod sedmdesát. Donedávna se to považovalo za uzavřený problém.“","c":[["Sval to na školy, že to nezachytily dřív.","Ukazujete na třídu místo na formulář o výjimce, který tu třídu umožnil. Míra proočkování se nehne a vina taky nikam užitečně nedopadne."],["Financuj věcnou osvětovou kampaň. Bez mandátů, jen kliniky.","Mobilní kliniky a jednoduchý leták, nic dramatičtějšího. Je to pomalé, nevzhledné, a míra proočkování stoupá bod po bodu."],["Zpřísni pravidla pro výjimky celostátně, direktivně.","Jedním legislativním krokem odstraníte snadnou výjimku. Klinicky to funguje a opozici to dá do rukou heslo o rodičovských právech, které epidemii přežije."],["Pošli Braydena, ať odvysílá návštěvu kliniky s kostýmovanou maskotkou.","Obří pěnový mikrob tančí před kamerami před vakcinační klinikou. Účast stoupne o dvě procenta mezi lidmi, kteří by nikdy nepřiznali, že na ně maskot zapůsobil."]]},"o-fast-track-approval":{"t":"Přeskoč frontu","x":"Wendell drží data ze studie, která ještě není hotová. „Třetí fáze není dokončená, pane. Máme slibná čísla a nedokončený obraz, a vy jste na mítinku slíbil, že to bude jmenovitě dostupné příští měsíc. To jsou dva různé dokumenty a jen jeden z nich je zatím pravdivý.“","c":[["Schval to teď. Oznam to jako vítězství.","Léčba se dostane na trh podle harmonogramu mítinku, ne podle harmonogramu vědy. Většina těch, kdo ji berou, je v pořádku. Ministerstvo stráví další rok vysvětlováním těch, kdo v pořádku nebyli."],["Počkej na kompletní data. Řekni to veřejně.","Řeknete davu, který chtěl vítězné kolo, že data ještě nejsou hotová. Je to hluboce neuspokojivé a je to celý důvod, proč schvalovací proces existuje."],["Schval to jen pro „nouzové použití“, ale potichu ho rozšiřuj.","Úzké nouzové schválení se memorandum po memorandu rozšiřuje, dokud nepokryje téměř každého. Papíry to sledují přesně. Skutečné použití to předběhlo o měsíce."],["Vezmi si to sám před kamerou, na důkaz důvěry v data.","Berete si nedokončenou léčbu naživo v televizi jako projev víry v proces, který jste sám nenechal dokončit. Ronny to sleduje s výrazem muže, který si v duchu počítá zbývající možnosti."]]},"o-quarantine-order-court":{"t":"Nařízení","x":"Bo má na stole karanténní nařízení i žalobu proti němu. „Je to obhajitelné, pane, právně, pokud je to úzké a časově omezené. To, co jste podepsal, není ani jedno. Soudce se zeptá, proč zadržujeme lidi s negativním testem, a já momentálně nemám odpověď, která by obstála při křížovém výslechu.“","c":[["Obhaj to tak, jak je napsané. Široké a bez omezení.","Argumentujete pro karanténu bez jasného konce a bez jasného kritéria. Soudce rozhodne proti vám formulacemi, které se budou citovat na právnických fakultách ještě deset let."],["Zúž to. Založené na testech, s čtrnáctidenním stropem.","Nařízení dostane skutečný rozsah a skutečné datum konce. Obstojí u přezkumu, což je celý smysl psaní zákona jako zákona."],["Karanténuj jen v okresech, které tě nevolily.","Geografie nařízení kopíruje volební mapu, ne mapu nákazy. Do týdne to soud zablokuje a v odůvodnění vám v jasné angličtině přečte vaše vlastní úmysly."],["Nabídni dobrovolný domácí dohled s finanční náhradou místo toho.","Program „peníze za dodržování“ startuje přes noc. Je drahý, překvapivě populární a právně mnohem čistší než nařízení, které nahradil."]]},"o-scientist-contradicts-congress":{"t":"Slyšení","x":"Hal Grimes si z tohoto hovoru radost nedělá. „Hlavní vědec vašeho vlastního ministerstva právě mému výboru pod přísahou řekl, že čísla, která používá váš tiskový úřad, jsou osm měsíců stará, pane. Je to teď v záznamu. Bylo to v záznamu už ve chvíli, kdy to řekl.“","c":[["Znevěrohodni ho veřejně. Zpochybni jeho kvalifikaci.","Napadnete v televizi poslovu kvalifikaci. Přepis jeho výpovědi pod přísahou se tím nemění, a nakonec se nemění ani to, komu lidé nakonec uvěří."],["Aktualizuj veřejná čísla. Poděkuj mu za opravu.","Necháte vědce opravit záznam pod přísahou a upravíte podle toho komunikaci. Je to zvláštní druh důstojnosti pro Bílý dům a je to, potichu, správně."],["Tvrď, že výpověď byla vytržena z kontextu.","Zpochybníte kontext přísežného přepisu, aniž byste zpochybnil jeho obsah. Ten rozdíl přesvědčí zhruba ty samé lidi, kteří už přesvědčeni byli."],["Pozvi ho, ať tě soukromě informuje osobně, mimo záznam, každý týden.","Založíte soukromé týdenní sezení s mužem, který vás veřejně zostudil, mimo dosah výboru, který nad ním má dozor. Je to, proti veškerému instinktu v budově, užitečné, a zároveň to vůbec neodpovídá tomu, jak má dozor fungovat."]]},"o-fake-vaccine-cards":{"t":"Falšovací síť","x":"Ředitelka Quistová má připravený zátah. „Falšované očkovací průkazy, pane, prodávané ve velkém, dodavatelský řetězec přes šest států. Můžeme to čistě zlikvidovat. Chci upozornit, že někteří kupující jsou lidé, kteří pro vás pracují, což komplikuje tiskovou konferenci.“","c":[["Proveď zátah veřejně. Velká tisková konference, všechno.","Televizní zátah pojmenuje falšovací síť a nepříjemně i několik jejích zákazníků. Dva z nich pracují tři dveře od vaší vlastní kanceláře."],["Zlikviduj to potichu. Žádná tisková konference.","Síť se rozloží bez jediné kamery. Méně falešných průkazů se dostane do oběhu a nikdo nemusí vysvětlovat, kdo je kupoval."],["Zamlč seznam kupujících. Stíhej jen prodejce.","Lidé, kteří síť řídili, jdou k soudu. Lidé, kteří od nich kupovali, včetně vašich, se v žádném podání neobjeví."],["Ať Quistová vystopuje, které falešné průkazy se dostaly do vaší vlastní budovy.","Interní audit najde falešný průkaz tři kanceláře od vás. Zaměstnanec podá rezignaci dřív, než Quistová dokončí větu s vysvětlením zjištění."]]},"o-satellite-budget-cut":{"t":"Slepé místo","x":"Dr. Brennanová není nadšená z položky, kterou objevil Roscoe. „Zrušení programu meteorologických satelitů vám ušetří zaokrouhlovací chybu v rozpočtu, pane, a zároveň to znamená, že další velký hurikán budeme sledovat přístroji, které jsou v průměru jedenáct let za svou plánovanou životností.“","c":[["Zruš to. Přesměruj peníze na program Mars.","Rozpočet na předpovědi se zmenšuje a rozpočet na Mars roste. Další bouře dorazí se širším, méně jistým předpovědním kuželem, což je zvláštní obchod vysvětlovat pobřežnímu guvernérovi."],["Zachovej financování. Škrtni něco méně nosného.","Satelity zůstávají financované a škrt dopadne někam s kratší pamětí. Je to nudné, správné rozhodnutí a do sestřihu nejlepších momentů se nedostane."],["Zruš to a pak sval špatnou předpověď na staré satelity.","Odstavíte přístroje a pak kritizujete jejich přesnost. Kužel příští bouře je širší, než musel být, výhradně z důvodů, které jste sám způsobil."],["Vypusť jediný náhradní satelit pojmenovaný po sobě.","Jeden satelit vzlétne, osamocený a pojmenovaný po vás, pokrývající zlomek dosahu staré sítě. Při startu vypadá nádherně na fotkách a do hurikánové sezóny znatelně řídne."]]},"o-blame-foreign-lab":{"t":"Příběh o původu","x":"Muriel drží depeši z ministerstva zahraničí Cathaje, a není přátelská. „Řekl jste před kamerou, že epidemie začala v tamní laboratoři, pane, bez jediného důkazu, který by potvrdila naše vlastní zpravodajská služba. Teď žádají odvolání. Momentálně nemáme důvod jim ho dát, ani ho odmítnout.“","c":[["Zopakuj tvrzení. Hlasitěji. Jmenuj laboratoř.","Úmyslně eskalujete nepodložené tvrzení v diplomatický incident. Doma to zabírá skvěle a ukončí to obchodní jednání, které trvalo tři roky, než začalo."],["Vezmi to zpět. Cituj upřímně skutečný zpravodajský přezkum.","Opravíte se pomocí skutečné, neprůkazné zprávy zpravodajské služby. Je to hluboce neuspokojivé pro publikum, které chtělo záporáka, a je to fakticky přesná verze."],["Popři, že jsi to kdy řekl. Je to na videu.","Popíráte tvrzení, které jasně existuje na záznamu. Klip se objeví na každém dalším brífinku, natrvalo, jako kus nábytku, o kterém si nikdo nepamatuje, že ho koupil."],["Navrhni společné, nezávislé vyšetřování s Cathajem.","Nabídnete skutečně zjistit pravdu společně, veřejně, bez zaručeného výsledku ve váš prospěch. Muriel na okamžik vypadá, jako by se rozplakala úlevou."]]},"o-physician-reassigned":{"t":"Druhý názor","x":"Ronny dal upřímnou odpověď na přímou otázku ohledně vašich nedávných krevních testů, a do hodiny to uniklo. „Odpověděl jsem na otázku, která mi byla položena, pane. Chápu, že to je teď zjevně důvod k propuštění, a rád bych poznamenal, že to tak dřív nebývalo, v žádné nemocnici, kde jsem kdy pracoval.“","c":[["Přesuň ho. Přiveď někoho opatrnějšího se slovy.","Ronny je potichu přesunut na čestnou pozici a nahrazen lékařem, který na každou otázku odpovídá frází „prezident je v naprostém pořádku“. Nikdo se neptá dál."],["Nech ho. Přiznej diagnózu veřejně.","Necháte upřímnou odpověď stát a sám ji jednou, jasně, potvrdíte. Je to skutečně nepříjemné odpoledne a je to naposledy, co tenhle konkrétní příběh běží."],["Tvrď, že unikla data byla zfalšovaná.","Obviníte upřímné papíry vlastního lékaře, že jsou padělek. Ronny vám veřejně neodporuje. Také ale nesouhlasí, což samo o sobě čte jako odpověď."],["Ať Ronny podstoupí stejný test naživo v televizi, kvůli transparentnosti.","Váš lékař si před kamerou odebere vlastní krev, aby dokázal bod o vaší krvi. Je to nejpodivnější televizní segment toho roku a funguje to."]]},"o-essential-oils-cure":{"t":"Kapky","x":"Brayden má lahvičku něčeho jménem Glow Drops, doporučovanou influencerkou s devíti miliony sledujících, která si říká „Coach Baby“. „Chce s vámi fotku, jak to držíte, pane. Říká, že to ‚podporuje přirozené světlo těla‘. Nevím, co to znamená. Myslím, že ona taky ne.“","c":[["Vyfoť se s tím. Zveřejni to sám.","Držíte lahvičku citrusového oleje doporučovaného tvrzením, které nikdo nedokáže definovat, a váš účet to zveřejní bez komentáře. Lahvičky se vyprodají. Tvrzení zůstává nedefinované."],["Odmítni fotku. Žádný komentář, žádná lahvička.","Prostě se nezúčastníte. Je to nejméně dramatická dostupná volba a zároveň jediná, která negeneruje titulek vyžadující pozdější opravu."],["Ať to Brayden zveřejní „neoficiálně“, s možností popřít.","Fotka jde ven z osobního účtu bez uvedení titulu, čímž vůbec nikoho neoklame ohledně toho, čí kancelář je v pozadí."],["Požádej Wendella o formální posouzení účinnosti „Glow Drops“.","Ministru zdravotnictví je nařízeno vědecky vyhodnotit produkt jménem Glow Drops. Udělá to. Kompletní zpráva má čtyři věty a natrvalo ukončuje celou konverzaci."]]},"o-donor-queue-jump":{"t":"Seznam","x":"Lyle má seznam jmen, který nikdy neměl existovat. „Čtyřicet jedna dárců, pane, přesunutých na začátek fronty na léčbu před čekací listinou se jmény, která tam byla dřív, z lékařských, ne finančních důvodů. Chci to říct na rovinu: na třech doplněních je váš rukopis.“","c":[["Nech seznam být. Přidej ještě dvě jména.","Fronta zůstává přednostní pro dárce a roste o další dva. Někdo s doloženou lékařskou naléhavostí čeká déle, aby nemusel čekat někdo s větším šekem."],["Zruš seznam. Přísné lékařské pořadí, zveřejněné.","Fronta se vrací k nudnému, obhajitelnému kritériu: kdo to nejvíc potřebuje lékařsky, jde první. Zklame to čtyřicet jedna dárců a naplní to skutečný smysl čekací listiny."],["Nech seznam, ale přejmenuj ho na „výzkumnou kohortu“.","Stejných čtyřicet jedna jmen dostane nový, klinicky znějící titul, který klinický není. Čekací listina pod tím se kvůli přejmenování nehýbe rychleji."],["Zveřejni celý seznam dárců sám, bez vyzvání.","Zveřejníte jména dřív, než je někdo unikne, spolu s omluvou, o kterou vás nikdo nežádal. Je to buď nejodvážnější věc, kterou za celé období uděláte, nebo vážná taktická chyba, a ani Lyle si není jistý která."]]},"p-golden-bible":{"t":"Zlatá Bible","x":"Sy pokládá na stůl vzorek. Zlatá fólie, imitace kůže, nálepka s nápisem „Vyrobeno v zemi, se kterou momentálně nemáme obchodní dohodu“. Prodává se za 79,99 dolarů a farář má otázky ohledně marže.","c":[["Objednej druhý náklad. Zdraž to.","Druhá série se vyprodá dřív, než odešel první náklad. Teolog napíše zuřivý sloupek, který prodá čtyřicet dalších kusů."],["Věnuj výnos skutečné charitě na gramotnost.","Marže se scvrkne na něco, co by normální firma nazvala charitou. Nikdo o tom nenapíše, což byl vlastně celý smysl."],["Dej svou tvář i na obálku.","Vaše tvář je teď vyražena naproti Knize Genesis. Tiskárna se, celkem rozumně, ptá, v jakém pořadí mají jít titulky."],["Ať Alvin osobně doručí jednu každému senátorovi.","Alvin osobně doručí devadesát devět Biblí na Kapitol s kartičkou „Bez zvláštní příležitosti“. Čtrnáct senátorů si potichu znovu přečte kapitolu o rytých modlách."]]},"p-sneaker-drop":{"t":"Tenisky","x":"Lyle drží krabici. Vysoký svršek, zlaté tkaničky, podrážka s vyraženou pečetí úřadu, který obvykle obuv nedoporučuje. Cena 399 dolarů. Prodalo se jedenáct tisíc párů za čtyři minuty a web dvakrát spadl.","c":[["Vypusť druhou barevnou variantu. Hned.","Druhá varianta se vyprodá ještě rychleji než první. Ekonom to v televizi nazve „skutečně pozoruhodnou cenovou neelasticitou“ a myslí to jako urážku."],["Omez náklad. Nech poptávku vychladnout.","Úmyslně necháte poptávku nevyužitou. Je to nejdisciplinovanější obchodní rozhodnutí vaší kariéry a nikdo si toho nevšimne."],["Poskytni pečeť pro podrážku. Skutečně tu pečeť.","Prezidentská pečeť, zákonem vyhrazená pro úřední použití, je teď na podrážce boty. Velmi starý zákon se poprvé po desetiletích čte nahlas na slyšení."],["Rozdej pár každému federálnímu soudci, bez vyžádání.","Sto sedmdesát devět párů dorazí k soudním budovám po celé zemi. Většina se vrátí. Dva se jednou nosí do jednací síně, jako vtip, který dopadne špatně."]]},"p-watch-line":{"t":"Řada hodinek","x":"Miriam má formulář o zveřejnění, a je téměř prázdný. „Hodinky se prodávají za jedenáct tisíc dolarů, pane. Kupující dostanou certifikát pravosti a neformálně telefonní číslo. Musím se zeptat, jestli je to telefonní číslo tím smyslem.“","c":[["Telefonní číslo je smysl. Prodávejte.","Čtyřicet hodinek jde ke kupcům, kteří budou, jak se ukáže, chtít něco později. Miriam to zaznamená pod nadpisem, který si vymyslí na místě: „Přístup, zjevný“."],["Vlož řadu do slepého trustu. Skutečně slepého.","Vzdáte se kontroly nad produktovou řadou pojmenovanou po vás. Je to právně správné a citově nesnesitelné, což bývá obvykle znamení, že to bylo správně."],["Přidej „diplomatickou edici“. Číslovanou. Pro hlavy států.","Suvenýrové hodinky se stávají, dá se argumentovat, darem podléhajícím ústavnímu omezení. Tři velvyslanci už jedny mají. Nikdo v budově nevysloví slovo „argumentovat“ nahlas."],["Stáhni celou řadu. Vrať peníze každému kupci, veřejně, v přímém přenosu.","Objevíte se naživo, abyste osobně vrátil jedenáct tisíc dolarů muži jménem Gary, před kamerou, dvakrát, protože druhé hodinky se našly v šuplíku. Je to napínavá televize a hrozná strategie."]]},"p-trading-cards":{"t":"Sběratelské karty","x":"Kaylee prochází nabídku. Vy jako superhrdina. Vy jako kovboj. Vy, jak jedete na něčem, co technicky není kůň. Devadesát devět dolarů za balíček. Vyprodalo se to za minuty a tři obchodní média si nedokážou rozhodnout, jestli to mají pokrýt jako zprávu, nebo jako reklamu na zboží.","c":[["Oznam „legendární“ ultravzácnou kartu. Vy sám, zářící.","Zářící karta se do hodiny prodá na sekundárním trhu za čtyři tisíce dolarů. Satirik poukáže na to, že je to víc než měsíční nájem u většiny lidí, a je zcela ignorován."],["Nech vtip být vtipem. Neříkej nic.","Odmítnete karty obhajovat nebo vysvětlovat. Je to správné rozhodnutí. Karty se hlasitě obhájí samy, bez vaší pomoci."],["Zažaluj satirický web za posměch kartám.","Podniknete právní kroky proti parodickému účtu se čtyřmi tisíci sledujícími. Žaloba mu přinese čtyři sta tisíc dalších."],["Věnuj výnos. Odmítni z principu říct kolik.","Rozdáte peníze a pak odmítnete dokázat kolik. Gesto navržené tak, aby vypadalo ctnostně, díky čirému utajení vypadá hůř, než kdybyste si peníze nechal."]]},"p-official-store":{"t":"Oficiální obchod","x":"Deborah má stavební plány. Trvalý obchod na federálním pozemku, hned vedle tiskové místnosti, prodávající vše od tenisek po kolínskou, o kterou nikdo nežádal. „Je to buď suvenýrový obchod, pane, nebo je to nejupřímnější budova ve Washingtonu.“","c":[["Začni stavět tento týden. Slavnostní otevření v pátek.","Prodejna se otevírá čtyřicet stop od tiskové místnosti. Prodavačka a tiskový sbor teď sdílejí kuchyňku, což všichni shodně považují za problém image, který nikdo správně nepředvídal."],["Dej to do rukou externího licencovaného partnera.","Soukromá firma řídí obchod s odstupem. Je to méně ziskové a podstatně méně žalovatelné, což Deborah zapisuje pod „ta výměna“."],["Umísti to do sklepa Západního křídla. Bez nájmu, bez smlouvy.","Obchod obsazuje federální prostor bez nájmu, k čemuž má několik zákonů své názory. Prodavačka dostane bezpečnostní odznak k nerozeznání od odznaku zaměstnance."],["Obsaď to výhradně neplacenými stážisty, kvůli „zkušenosti“.","Rotující sbor vysokoškoláků prodává hodinky za kredity. Ministerstvo práce zahajuje šetření. Madison mezi nimi tentokrát naštěstí není."]]},"p-counterfeit-crackdown":{"t":"Padělky","x":"Bo má stůl se zabaveným zbožím. Falešné hodinky, falešné tenisky, Bible s vaší tváří na špatném zákoně. „Technicky tihle lidé porušují zákon, pane. Technicky ho ale porušuje i ten skutečný výrobek, což z tohohle dělá neobvykle trapný zátah k povolení.“","c":[["Proveď zátah na každém bleším trhu ve třech státech. Veřejně.","Federální agenti zabavují padělanou kolínskou ze skládacího stolu před stadionem. Záběry jsou buď silný odstrašující prostředek, nebo nejvtipnější věc na internetu toho týdne. Je to obojí."],["Rozešli výzvy k zastavení a upuštění. Standardní ochranný postup.","Právníci udělají tu nudnou, správnou věc. Devadesát procent padělků potichu zmizí. Nikdo nenatáčí zátah, protože není co natáčet."],["Pověř soukromou bezpečnostní firmu zabavením zboží.","Muži v neoznačených vestách zabavují skládací stůl s falešnými teniskami. Nikdo přesně neřekne, z jaké pravomoci, což je celý problém v jedné větě."],["Kup největší padělatelskou operaci. Zpětně ji legalizuj.","Koupíte padělatelskou továrnu rovnou a prohlásíte ji za oficiální. Bible s vaší tváří na špatném zákoně je teď nějak kanonická."]]},"p-library-groundbreaking":{"t":"Slavnostní výkop","x":"Dr. Weirová má seznam příspěvků, polovina jmen je na žádost dárce začerněná. „Tranquility Center bude mít vaše jméno v čtyřstopých písmenech, pane. Vybrali jsme šest set milionů dolarů. Nevím od koho, a bylo mi mile řečeno, ať se neptám.“","c":[["Vezmi peníze. Všechna jména zůstanou utajená.","Šest set milionů dolarů dorazí bez jediného jména. Budova roste rychle a čistě. Za co byly vyměněny, zůstává natrvalo mimo záznam."],["Zveřejni každého dárce. I ty trapné.","Celý seznam jde na veřejnost. Dvě jména způsobí velmi špatný týden. Pak, pozoruhodně, je konec, protože sluneční světlo je nudné a nudné věci se nekumulují."],["Omez jednotlivé dary. Kromě spřátelených vlád.","Pravidlo s výjimkou přesně o velikosti mezery, kterou má skrýt. Tři zahraniční delegace okamžitě zjistí, že jsou spřátelené."],["Financuj to výhradně bazarem koláčků. Trvej na tom veřejně, celý rok.","Skládací stůl u staveniště prodává jedenáct měsíců koláčky, zatímco dárci, kteří by mohli podepsat šek na místě, sledují, zmatení a trochu uražení, z uctivé vzdálenosti."]]},"p-museum-wing-naming":{"t":"Křídlo","x":"Dr. Weirová odhaluje model. Křídlo velikosti fotbalového hřiště, pojmenované po dárci, jehož firma náhodou drží čtyři čekající federální zakázky. „Práva na pojmenování stojí osmdesát milionů dolarů, pane. Zakázky mají hodnotu podstatně vyšší, což dárce chápe a po nás se žádá, abychom to nechápali.“","c":[["Pojmenuj to. Schval zakázky ten samý týden.","Křídlo se otevírá se jménem firmy na mramoru a jejími zakázkami ve federálním registru, ve stejném zpravodajském cyklu. Souvislost není subtilní a nikdo ji nepopírá."],["Vezmi dar. Odděl zakázky celým rokem.","Mezi šek a zakázku se vloží slušný odstup. Neoklame to vůbec nikoho a uspokojí to každého právníka v budově, což je zjevně laťka."],["Ať pojmenují celé muzeum. Ne jen křídlo.","Tranquility Center se smluvně stává značkovým zážitkem dceřiné společnosti. Suvenýrový obchod teď prodává dvě loga na jednom hrnku."],["Přejmenuj křídlo po školníkovi, který tam pracuje třicet let.","Vrátíte osmdesát milionů dolarů a na mramor dáte místo toho jméno vedoucího údržby. Je zmatený, pak dojatý, pak požádán o proslov, na který se nepřipravil."]]},"p-library-donor-wall":{"t":"Zeď dárců","x":"Miriam drží jeden list s jedním řádkem: „Dary zpracované přes Liberty Financial: 340 000 000 dolarů.“ „To je celé zveřejnění, pane. Liberty Financial nemusí uvádět, kdo jim to dal. Je to, právně vzato, velmi drahé pokrčení rameny.“","c":[["Veď dál všechno přes Liberty Financial.","Tři sta čtyřicet milionů dolarů dorazí s jediným řádkem papírování. Celý obchodní model Liberty Financial je, jak se ukazuje, být zdí, skrz kterou nikdo nevidí."],["Vyžaduj zveřejnění skutečných dárců. Bez výjimek.","Zeď padá. Některá jména jsou nudná. Pár není. Příběh běží týden a pak, naštěstí, se zpravodajský cyklus posune jinam."],["Vytvoř druhou schránku, která zakryje tu první.","Fiktivní firma teď vlastní fiktivní firmu. Organizační schéma je nakresleno čistě proto, aby zmátlo auditora, a funguje to na auditora i na všechny ostatní."],["Zveřejni zeď dárců jako skutečnou zeď. Jména v bronzu.","Každé jméno skutečného dárce je natrvalo odlito do zdi v hale, v aktu transparentnosti tak doslovné, že to zahanbí dva senátory, kteří nečekali, že je bude někdo číst v očích."]]},"p-archive-embargo":{"t":"Zapečetěný archiv","x":"Dr. Weirová je jako vždy přesná. „Darovací smlouvy to vyžadují, pane. Určitá korespondence dárců zůstává zapečetěná sedmdesát pět let. To je déle, než má tato země televizi. Historik z Colonnade University už podal žalobu, aby se k tomu dostal hned.“","c":[["Prodluž pečeť. Sto let. Kulaté číslo.","Uzamknete korespondenci na celé století, což je zvláštní krok, pokud v ní nic není. Nikdo to nevysloví nahlas, ale všichni si to okamžitě myslí."],["Zveřejni všechno kromě skutečně utajovaného materiálu.","Naprostá většina archivu se otevírá. Je to většinou logistika a děkovné dopisy. Historik najde jeden skutečně zajímavý memorandum a postaví na něm kariéru."],["Nech nejcitlivější krabice „ztratit se“ při požáru skladu.","Skladovací zařízení lehne popelem, mimořádnou náhodou obsahující přesně ty krabice pod předvoláním. Pojistná událost se zpracuje rychleji než jakékoli vyšetřování kdy bude."],["Přečti zapečetěný archiv nahlas sám, naživo, bez úprav.","Šest hodin v kuse naříkáte do živého mikrofonu sedmdesát pět let korespondence dárců. Je to většinou logistika. Dvě jména si ten večer vyslechnou velmi tichý telefonát."]]},"p-museum-gift-shop-twist":{"t":"Suvenýrový obchod, znovu","x":"Bernadette má čtvrtletní čísla. Suvenýrový obchod Tranquility Center vydělal minulý měsíc víc než vstupné, výzkumné granty a kavárna dohromady. „Vzdělávacky, pane, je to katastrofa. Finančně je to nejúspěšnější věc, kterou tato administrativa postavila.“","c":[["Zmenši expozice. Rozšiř obchod. Prostá matematika.","Dvě galerie se zavírají kvůli druhé pokladně. Školní výlet šesťáků odchází s taškami a bez jasné představy, co se tu historicky vlastně stalo."],["Zachovej poctivý poměr. Obchod zůstane malý.","Suvenýrový obchod zůstává suvenýrovým obchodem a muzeum zůstává, tvrdohlavě, muzeem. Vydělá to méně a nějak i získá víc respektu, což nebyl plán, ale je to výsledek."],["Vybírej vstupné jen kvůli přístupu do obchodu.","Postavíte dvanáctidolarové mýto mezi vchod a zboží. Žena si před kamerou stěžuje, že jí muzeum naúčtovalo za nákup magnetky."],["Přeměň celé přízemí na obchod. Expozice přesuň nahoru.","Návštěvníci teď projdou celým patrem obchodu, než dojdou k jedinému artefaktu. Doprovod školního výletu se upřímně ptá, jestli je eskalátor taky na prodej."]]},"p-jet-arrives":{"t":"Dar","x":"Muriel vás jemně informuje. „Koruna Qadiry si přeje darovat letadlo, pane. Vyřazené palácové letadlo, čtyři sta milionů dolarů v novém stavu. Formálně se stává majetkem Spojených států. Neformálně všichni zúčastnění očekávají, že ho budete osobně létat, natrvalo.“","c":[["Přijmi to. Přelakuj to. Lítej s tím tento víkend.","Letadlo je přelakováno a ve vzduchu do týdne. Zákon o darech od cizích států se poprvé po dlouhé době čte nahlas do záznamu."],["Odmítni. Zdvořile. Veřejně. Písemně.","Odmítnete čtyři sta milionů dolarů letadla. Je to podle jakéhokoli normálního měřítka akt sebeovládání, za který vám nikdo nepoděkuje a který si všichni zapamatují."],["Přijmi to a přesměruj to na soukromou nadaci.","Letadlo je legálně darováno nadaci, která sdílí vaše jméno a, jak se ukazuje, i váš cestovní rozvrh. Papírování je mistrovské dílo velmi specifického druhu."],["Přijmi to, ale jen na přepravu záchranných zvířat.","Palácové letadlo za čtyři sta milionů dolarů je jednou přeorganizováno na přepravu jedenácti zlatých retrívrů do útulku v jiném státě. Optika je nevysvětlitelně horší, než kdybyste si ho prostě nechal."]]},"p-jet-appraisal":{"t":"Odhad","x":"Miriam má dvě čísla na dvou listech papíru. Skutečný odhad říká čtyři sta milionů. Ten určený pro formulář o zveřejnění říká třicet devět tisíc, „hodnota občerstvení na palubě“, poznamenává, „což je číslo, které mám podepsat“.","c":[["Podej to nižší číslo. Je to technicky dokument.","Federální formulář o darech uvádí letadlo za čtyři sta milionů dolarů v hodnotě třiceti devíti tisíc. Miriam to podepíše, pak písemně požádá, ať se do spisu založí i její námitka."],["Podej skutečné číslo. Ať je příběh příběhem.","Skutečná hodnota jde do záznamu. Je to velké, trapné, upřímné číslo. Upřímná čísla, jak se ukazuje, vyvolají přesně jeden špatný týden a pak ticho."],["Ať je Miriam přeřazena. Najdi někoho, kdo to podepíše.","Etický úřad dostane do měsíce nového, ochotnějšího obyvatele. Staré číslo zůstává špatné. Nová odhadkyně je nápadně rychlá ve své práci."],["Odhadni to sám, veřejně, pomocí koupelnové váhy.","Zvážíte kolo podvozku letadla na domácí váze před kamerami a naživo extrapolujete hodnotu. Je to hluboce nevědecké a znepokojivě blíž pravdě než oficiální formulář."]]},"p-jet-security-review":{"t":"Odposlechová prověrka","x":"Generál Tarrant se neusmívá, což je u něj standard. „Na qadirském letadle jsme našli šest odposlouchávacích zařízení, pane. Standardní postup je rozebrat letadlo až na kostru. Standardní postup také počítá s tím, že jste ochoten počkat ty čtyři měsíce, které to zabere.“","c":[["Lítej s tím teď. Rozeber to později. V podstatě je to v pořádku.","Vzlétnete v letadle, které mohla cizí vláda donedávna v reálném čase odposlouchávat. Tarrant formálně žádá, aby toto rozhodnutí bylo ve spisech přiřazeno vašemu jménu."],["Uzemni ho. Kompletní demontáž. Čtyři měsíce, bez zkratek.","Letadlo stojí v hangáru a lidé s prověrkou ho pečlivě rozebírají. Je to nudná, správná, neviditelná verze národní bezpečnosti."],["Zabavená zařízení použij sám na vlastní personál.","Šest zabavených štěnic je znovu nasazeno pro interní účely. Deborah jednu najde v pokojové rostlině. Porada o té poradě trvá podstatně déle než ta původní."],["Věnuj prověřené letadlo Muzeu letectví a kosmonautiky místo toho.","Letadlo za čtyři sta milionů dolarů se stává statickým exponátem za sametovým provazem, tři míle od místa, kde byste mohl létat. Průvodce dětem ze školního výletu vysvětluje odposlechovou prověrku, špatně."]]},"p-jet-customs":{"t":"Celní formulář","x":"Duane má manifest, a kolonka „deklarovaná hodnota“ je prázdná. „Přistálo to na vojenském letišti, pane, což znamená, že to nikdy neprošlo civilním procesem. Můžu to zpracovat zpětně, což je fráze, o které mi bylo řečeno, že existuje přesně pro situace jako tuhle.“","c":[["Antidatuj papíry. Na vojenských letištích nikdo nekontroluje.","Zpětně se vygeneruje celní formulář pro letadlo, které přistálo před šesti týdny. Technicky je to papírování. V žádném smysluplném ohledu to není proces."],["Proveď to teď normálním civilním procesem. Se sankcí za pozdní podání.","Letadlo je formálně přihlášeno, o týdny později, se skromnou pokutou. Je to nudné, správné a negeneruje to jedinou další otázku, což je celý smysl papírování."],["Zařaď letadlo jako diplomatický náklad. Natrvalo.","Letadlo je přeřazeno na náklad patřící misi, která ho formálně nevlastní. Označení přežije tři samostatné audity tím, že je příliš zvláštní na to, aby ho někdo zpochybnil."],["Ať Duane letadlo osobně prohlédne, ručně, od přídě po ocas.","Duane stráví celý den procházením interiéru palácového letadla s baterkou, jako by to byla dodávka na hranici. Najde koupací plášť monogramovaný pro zemi, která už neexistuje."]]},"p-jet-return-clause":{"t":"Malé písmo","x":"Muriel konečně přečetla celou darovací smlouvu, všech čtyřicet stran. „Je tam doložka, pane, na straně třicet jedna. Letadlo se po odchodu z úřadu vrací Koruně Qadiry. Ne vládě. Jim. Nikdy to nebyl skutečně dar zemi.“","c":[["Ignoruj tu doložku. Devět z deseti bodů zákona je vlastnictví.","Oznámíte, že s letadlem prostě budete dál létat i po skončení funkčního období. Království, které nemůžete beztrestně urazit, začne zdvořile připravovat incident."],["Přejednej doložku teď. Převeď letadlo přímo na vládu.","Muriel stráví tři měsíce skutečným zrušením doložky. Letadlo se stává, nudně a natrvalo, federálním majetkem. Je to nejnudnější diplomatické vítězství roku."],["Ať doložku o vrácení vykoupí nadace. Potichu.","Soukromá nadace zaplatí Koruně Qadiry za vzdání se vlastní doložky o vrácení. Letadlo zůstává. Daňové přiznání nadace se v jednom řádku stává mimořádně zajímavým."],["Oznam, že letadlo osobně odvezeš zpátky do Qadiry sám, jako gesto.","Přeletíte oceán s letadlem za čtyři sta milionů dolarů, abyste ho osobně vrátili o funkční období dřív, kvůli optice celé věci. Optika po přistání je optikou muže, který rozdává letadlo."]]},"p-pardon-price-list":{"t":"Ceník","x":"Bo přisune ceník dárcovských úrovní, který nikde neobsahuje slovo „milost“. Bronz, Stříbro, Zlato, Platina. Platinoví dárci dostanou fotku, prohlídku a telefonát vrácený do týdne. „Nikdo to nenapsal, pane. Všichni to chápou.“","c":[["Schval úrovně. Zachovej vágní formulace.","Ceník jde ven beze změn. Pokud čtete úzce, nic na něm není nelegální. Pokud se čte vůbec, všichni tomu rozumí, a dary se za čtvrtletí ztrojnásobí."],["Odstraň z veškerých fundraisingových materiálů zmínky o milosti.","Naznačovaná výhoda z papírů mizí. Dary klesají. Bo poprvé po měsících vypadá jako muž, který dokáže spát."],["Přidej diamantovou úroveň. Zaručený telefonát do 48 hodin.","Nová nejvyšší úroveň slibuje dárcům konkrétní dobu odezvy od Úřadu pro milosti, písemně. Je to přesně ta věta, která nakonec skončí v obžalobě, časem, u někoho jiného."],["Zveřejni ceník sám. Plná transparentnost. Uvidíme, co se stane.","Zveřejníte skutečnou cenovou strukturu veřejnosti, zjevně v přesvědčení, že upřímnost bude čtena jako nevina. Čte se to místo toho jako ceník, protože jím je."]]},"p-pardon-bundle":{"t":"Balíček","x":"Bo má na jednom listu čtyřicet jedna jmen, bez vysvětlení u kteréhokoli z nich. „Sbal je dohromady, pane, a nikdo nemusí obhajovat žádnou jednotlivou milost na jejích vlastních zásluhách. Třicet osm jsou opravdu sympatické případy. Tři jsou, upřímně, prostě ti, co za balíček zaplatili.“","c":[["Podepiš celý balíček. Čtyřicet jedna jmen, jeden podpis.","Čtyřicet jedna milostí je uděleno najednou, a ta tři pochybná cestují, neviditelně, uvnitř těch třiceti osmi obhajitelných. Je to starý trik a pořád funguje."],["Posuzuj každý případ zvlášť. Zveřejni odůvodnění.","Každé jméno dostane své vlastní memorandum, svou vlastní logiku, svůj vlastní podpis. Trvá to o šest týdnů déle a obstojí to proti každé otázce, protože na každou existuje odpověď."],["Přibal balíček k hromadnému zmírnění trestů, aby to lépe zapadlo.","Balíček připojíte k mnohem větší, skutečně populární iniciativě milosti. Tři problematická jména projíždějí pod krytím čtyř set sympatických."],["Vyřaď tři sporná jména. Odmítni jen ta, veřejně.","Vyberete tři jména s nejvyšší platbou a z principu je před kamerami odmítnete. Ostatních třicet osm projde bez problémů. Ti tři dárci to nepřijmou dobře."]]},"p-pardon-walk-back":{"t":"Ústup","x":"Předsedkyně nejvyššího soudu Stoneová je neobvykle přímá na ženu, která tráví život opatrností. „Vzorec je odhalitelný, pane. Čtyřicet jedna jmen, porovnaných s dárcovskými záznamy, koreluje mírou, kterou by žádný statistik nenazval náhodou. Soud o to projevil zájem.“","c":[["Bojuj proti předvolání. Výsadu výkonné moci, až po nejvyšší instanci.","Uplatníte výsadu ohledně dat o souvislosti darů a milostí. Boj jde až k soudu, který tu otázku sám vznesl, což málokdy je boj, který si užijete vyhrát pomalu."],["Vyhov. Předej záznamy. Ať padnou karty, jak padnou.","Záznamy jdou ven, kompletní a bez redakcí. Souvislost je přesně tak špatná, jak se obávalo, a přesně tak přežitelná, protože jste o tom navíc nelhal."],["„Objev“, že záznamy byly zničeny při migraci serveru.","Konkrétní záznamy pod předvoláním zmizí při IT incidentu s neobvykle dobrým načasováním. Předsedkyně přečte vysvětlení nahlas, pomalu, u otevřeného soudu, pro efekt."],["Zveřejni bez vyzvání všechny dárcovské záznamy z celého funkčního období.","Pohřbíte předvolaný vzorec pod čtyřmi lety jinak nesouvisejících fundraisingových dat. Nikdo nenajde jehlu, technicky, protože jste taky předal celou kupku sena."]]},"p-pardon-lobbyist":{"t":"Zprostředkovatel","x":"Hal Grimes se staví osobně, což se nikdy neděje kvůli dobrým zprávám. „Existuje muž, pane, formálně s touto administrativou nijak nespojený, který si účtuje dvě stě tisíc dolarů za to, že se žádost o milost dostane k přečtení. Je ve své práci velmi dobrý. To je ten problém.“","c":[["Nech ho pracovat. Vlastně nám dělá službu.","Neoficiální mýtnice funguje dva bloky od Bílého domu, vybírající vstupné do procesu, který má být zdarma. Všichni zúčastnění s vážnou tváří tvrdí, že je to náhoda."],["Vyřaď ho. Veď každou žádost přes oficiální úřad.","Zprostředkovatel je odstaven a chronicky poddimenzovaný Úřad pro milosti dostane místo toho skromné navýšení rozpočtu. Je to pomalejší. Je to taky, konečně, skutečně ten proces."],["Dej ho na výplatní listinu. Udělej to oficiální.","Zprostředkovatel se stává konzultantem s odznakem a vládní e-mailovou adresou. Mýtnice teď má titul, což ji nějak dělá zároveň legálnější a víc odsuzující."],["Ať zprostředkovatele vyšetří jeho vlastní bývalí klienti.","Potichu povzbudíte tři lidi, kteří zprostředkovateli zaplatili a nic nedostali, aby na něj podali stížnost. Funguje to. Zároveň to vytvoří papírovou stopu, která nakonec vede přímo zpátky k vám."]]},"p-pardon-crypto-payment":{"t":"Kryptostopa","x":"Bo má výtisky adresy peněženky, na kterou přišly a vzápětí byly převedeny čtyři miliony dolarů, týden před udělením milosti. „Je to nevystopovatelné, pane, v tom smyslu, že vystopovat to je jen obtížné, ne nemožné. Jeden vysokoškolák to zvládl za odpoledne, na seminární práci.“","c":[["Není co řešit. Transakce proběhla týden před milostí.","Spoléháte na kalendář jako na obhajobu. Ukáže se, že týden není ta mezera, kterou lidé považovali za důkaz neviny, a domácí úkol vysokoškoláka se stane titulní zprávou."],["Předejte peněženku nezávislému útvaru pro finanční kriminalitu.","Předáte stopu lidem, jejichž jedinou prací je ji sledovat, a necháte proces fungovat bez ohledu na to, kam povede. Někam vede. To byl ostatně celý smysl."],["Nechte milost tiše znovu vydat čistší cestou.","Stejný výsledek je přebalen do trasy bez jakékoli spojitosti s kryptem. Původní peněženka ale pořád existuje. A je, což je nezapomenutelné, navždy na blockchainu, kde ji kdokoli najde."],["Příští platbu přijměte v hotovosti, v papírovém pytlíku, čistě z nostalgie.","Někdo se skutečně dostaví se sportovní taškou, očividně vzal ten vtip vážně. Bo neví, jestli se má smát, nebo zavolat Úřad. Zavolá Úřad."]]},"p-speaking-fee-invite":{"t":"Honorář za projev","x":"Lyle má pozvánku. Obchodní asociace v Rusalce chce čtyřicetiminutový proslov. Honorář činí 2,5 milionu dolarů. „Pro srovnání, pane, to je zhruba to, co za rok platíme celému oddělení pro psaní projevů, a to za texty podstatně delší než čtyřicet minut.“","c":[["Přijměte to. Domluvte ještě tři stejné.","Na krátkou chvíli se stanete nejlépe placeným řečníkem na světě, v přepočtu na minutu, a to s velkým náskokem. Gideon z oddělení pro psaní projevů si ne zcela žertem řekne o přidání navázané na vaši hodinovou sazbu."],["Vezměte si symbolický honorář. Zbytek věnujte na dobročinnost.","Přijmete skromný honorář a zbytek nasměrujete do stipendijního fondu. Je to velkorysé, rozumné a vygeneruje to jednu agenturní zprávu, kterou nikdo nedočte dál než po titulek."],["Vyjednejte si vyšší honorář. Očividně něco chtějí.","Vyjednáte si čtyři miliony a dostanete je. Co přesně chtějí, se stane otázkou, kterou si nezávisle na sobě položí tři novináři úplně ve stejnou chvíli."],["Proslovte to zdarma. Trvejte na tom, hlasitě a opakovaně.","Honorář odmítnete tak důrazně a zmiňujete to tak často, že vás bezplatný proslov nakonec stojí víc dobré vůle, než by stál placený. Nikdo vás nežádal, abyste z toho dělal celou aféru."]]},"p-speaking-fee-college-tour":{"t":"Turné po univerzitách","x":"Bernadette má program cesty. Šest univerzit, šest proslovů v rámci promocí, po 750 000 dolarech. Tři z těch šesti mají u vás na stole žádosti o federální výzkumné granty, které čekají na rozhodnutí. „Chci to uvést do záznamu, pane, a pak chci jít dál.“","c":[["Domluvte všech šest. Granty schvalte až potom, ne předtím.","Čtyři a půl milionu dolarů na honorářích přijde na účet dřív, než padne jediné rozhodnutí o grantu. Pořadí, poznamená Bernadette suše, je zároveň celou obhajobou i celým problémem, v jedné větě."],["Vylučte se z rozhodování o grantech na kterékoli škole z turné.","Rozhodování o grantech pro těch šest škol přenecháte stálým úředníkům a sám se z místnosti vzdálíte. Honoráře přesto dorazí. Zdání problému naštěstí ne."],["Přidejte „poplatek za zařízení“. Nechte univerzitu na vaši počest zrenovovat místnost.","Šest univerzit teď má vlastní „Prezidentskou studovnu“, financovanou zvlášť od honoráře za proslov, což je přesně ten typ dvojího příjmu, který zní špatně, i když ho vysvětlíte pomalu a trpělivě."],["Na jediné škole bez čekajícího grantu promluvte zdarma.","Vyberete si jedinou univerzitu, která nemá co získat, a promluvíte tam zadarmo, zjevně abyste něco dokázal. Zbylých pět škol okamžitě pochopí, co to o nich vypovídá."]]},"p-speaking-fee-ghost-audience":{"t":"Prázdný sál","x":"Kaylee má fotky z akce a prodej vstupenek si vzájemně neodpovídají. Sál pojme čtyři tisíce lidí. Platících diváků bylo kolem devadesáti. „Zbytek, pane, je náš vlastní přípravný tým rozesazený v sedadlech, aby to na širokých záběrech vypadalo plné. Honorář byl proplacen dřív, než kdokoli spočítal hlavy.“","c":[["Zveřejněte široké záběry. Nikdy ne ty, které ukazují prázdný sál.","Každá zveřejněná fotka je zabraná tak, aby skryla dvě třetiny prázdného sálu. Funguje to, dokud někdo nezveřejní záběr z dronu, což se dřív nebo později vždycky stane."],["Zveřejněte skutečný počet. Uveďte, že honorář byl pevně daný bez ohledu na účast.","Přiznáte, že přišlo devadesát lidí a honorář byl vyplacen stejně, protože to tak stálo ve smlouvě. Je to malá, upřímná a zapomenutelná zpráva, což je nejlepší možný výsledek."],["Na příští akci svezte autobusem nezaměstnané komparzisty. Placené, samozřejmě.","Inzerát na obsazení role „zaujatých, fotogenických diváků“ se během pár hodin rozšíří po internetu, s názvem vaší akce přímo v textu. Nevypadá to dobře, hlavně proto, že je to strašně konkrétní."],["Zrušte všechny budoucí placené proslovy. Mluvte jen zdarma, ke skutečným sálům.","Uprostřed turné z principu opustíte celý výnosný okruh. Stojí vás to jmění, nezíská vám to žádné okamžité uznání, a přitom je to jediná věc v celém vašem kalendáři za celý rok, kterou lze bez výhrad obhájit."]]},"p-speaking-fee-family-cut":{"t":"Rodinný podíl","x":"Miriam má organizační schéma, které by nemělo existovat. Každý honorář za proslov, každá licenční smlouva prochází přes rodinného příslušníka v roli „agenta“, který si shora strhává patnáct procent. „Nikdo z nich nemá agentskou licenci, pane. Ze zákona ji ani nepotřebují. A to je nějakým způsobem ještě horší.“","c":[["Formalizujte to. Patnáct procent, písemně, natrvalo.","Rodinný podíl se z ústní dohody stane smlouvou. Přežije každou kontrolu, protože už ho nikdo nepopírá. Není na čem přistihnout."],["Smlouvy místo toho veďte přes nezávislou agenturu.","Skutečná talentová agentura, bez jakéhokoli vztahu k nikomu z rodiny, teď zajišťuje domluvy. Rodina přijde o zdroj příjmů a získá, jak poznamenává Miriam, naprosto nic, což je přesně ten správný výsledek."],["Zvyšte rodinný podíl na dvacet pět procent. Zasloužili si to.","Procento roste, aniž by k tomu přibyla jakákoli další práce, která by to ospravedlnila. Účetní to mimo záznam nazve „nejčistší matematikou v celé operaci“."],["Rodinný podíl věnujte na dobročinnost. Celý. Zpětně.","Roky neformálních agentských provizí se jedním dramatickým gestem vrátí zpět a přesměrují na charitu. Několik příbuzných je podle všeho v soukromí zuřivých a před kamerou velkoryse smířených."]]},"p-sovereign-fund-stake":{"t":"Podíl","x":"Lyle má potvrzení o platbě. Suverénní fond Qadiri koupil dvoumiliardový podíl v rodinné holdingové společnosti, a to při ocenění, které Lyle opatrně označuje jako „aspirační“. „Uzavřelo se to za devět dní, pane. Podobné obchody obvykle trvají devět měsíců.“","c":[["Přijměte to. Jejich obchodní úlevy protlačte tento kvartál urychleně.","Dvě miliardy dolarů dorazí a obchodní úleva následuje během pár týdnů. Nikdo nepodepíše dokument, který by ty dvě věci spojoval. Přesto je spojí úplně všichni, včetně tří zahraničních redakcí."],["Nejdřív obchod předejte nezávislé kontrole střetu zájmů.","Podíl jde k externím posuzovatelům dřív, než se pohne cokoli dalšího. Trvá to měsíce. Je to neuvěřitelně nudné. A zároveň je to jediná verze tohoto příběhu, která nekončí u slyšení."],["Přijměte druhý podíl od rivalského království. Postavte je proti sobě.","Druhý suverénní fond se přidá právě proto, aby přebil ten první. Teď dlužíte zvýhodněné zacházení dvěma vládám, které se navzájem otevřeně nesnáší, a obě jsou ve stejném portfoliu."],["Podíl vraťte. Přeměňte ho na stipendijní fond pro jejich studenty.","Rozpustíte dvoumiliardový majetkový podíl a přesměrujete ho na financování studentů z Qadiri studujících v zahraničí. Je to velkorysé, podivné, a Lyle kvůli tomu musí vysvětlovat záporný řádek v rozpočtu, jaký nikdy předtím vysvětlovat nemusel."]]},"p-sovereign-fund-board-seat":{"t":"Místo ve správní radě","x":"Miriam má dodatek ke stanovám. K dvoumiliardovému podílu suverénního fondu Qadiri patří i místo ve správní radě, které na papíře zastává „soukromá osoba“, jež náhodou je bratrancem panovníka. „Osobně se nezúčastnil jediného zasedání, pane. Hlasuje v zastoupení. A ještě nikdy nehlasoval proti ničemu.“","c":[["Potvrďte to místo. Dejte mu přístup i do výborů.","Bratranec zahraničního panovníka získá formální rozhodovací práva nad společností nesoucí vaše jméno. Neúčastní se ničeho a schvaluje všechno, což je fakticky přesně to, jak měl celý ten mechanismus fungovat."],["Místo ve správní radě odmítněte. Jen finanční podíl, žádné řízení.","Vezmete si peníze a odmítnete vliv, který k nim obvykle patří. Je to menší, čistší obchod, o kterém nikdo nepíše, protože na něm není žádný příběh."],["Dejte mu ještě druhé místo. A titul. „Strategický poradce“.","Bratranec získá titul, místo a fakticky i hlas v rozhodnutích, která se dotýkají skutečné americké politiky. Nikdo nemůže ukázat na zákon, který porušil. Každý ale může ukázat na organizační schéma."],["Místo raději nechte odhlasovat zaměstnanci společnosti.","Necháte dvě stě zaměstnanců zvolit na to místo namátkového účetního místo královského bratrance. Je to opravdu demokratické gesto uvnitř společnosti, která svou strukturou ničím demokratická není."]]},"p-sovereign-fund-due-diligence":{"t":"Prověrka","x":"Errol Hance před tím, než promluví, zavře dveře, což nikdy nevěstí nic dobrého. „Suverénní fond Qadiri je formálně nezávislý, pane. Podle našeho vyhodnocení ale u čehokoli nad pět set milionů dolarů přijímá pokyny z paláce. Váš podíl je čtyřikrát vyšší.“","c":[["Vyhodnocení schovejte. Obchod už je stejně uzavřený.","Tajné vyhodnocení skončí v šuplíku místo na briefingu. Obchod pokračuje, jako by palác neměl na výsledku žádný zájem, přestože zpráva výslovně tvrdí opak."],["Vyhodnocení předložte Kongresu. Bez výjimek.","Zjištění jdou v plném rozsahu příslušným výborům, dřív než se stane cokoli dalšího. Obchod se tím výrazně zpomalí, ale ustojí každou otázku, kterou na něj kdokoli později položí."],["Vyhodnocení přeřaďte jako příliš citlivé na sdílení, i uvnitř úřadu.","Errolova vlastní zpráva dostane razítko utajení nad úroveň, ke které má on sám přístup. Na papíře už tak nemá prověrku na to, aby viděl závěr, který sám napsal, což mu připadá opravdu vtipné, zhruba na jeden den."],["Nechte Errola přednést zjištění přímo velvyslanci Qadiri.","Necháte vládu zahraničního fondu vidět přesně to, co si zpravodajská komunita myslí o jeho nezávislosti. Je to buď mimořádně odvážná diplomacie, nebo vážná operační chyba, a nikdo v místnosti se neshodne na tom, co z toho."]]},"p-sovereign-fund-family-hire":{"t":"Nový zaměstnanec","x":"Muriel má aktualizaci organizačního schématu. Příbuzný bez jakékoli diplomatické zkušenosti byl jmenován „zvláštním poradcem pro vztahy s Qadiri“ a odpovídá přímo fondu, který právě investoval dvě miliardy dolarů do rodinné firmy. „Plat je důvěrný, pane. Ten vztah není.“","c":[["Schvalte to. Dejte tomu titulu i skutečnou pravomoc.","Příbuzný získá schvalovací pravomoc přímo nad vztahem, který financuje rodinnou firmu. Muriel si do spisu poznamená, že jde o nejčistší kruh, jaký kdy viděla nakreslený v organizačním schématu."],["Titul zrušte. Vztahy s Qadiri veďte přes stálé zaměstnance.","Příbuzný je potichu odstaven a agendu místo něj přebírá kariérní diplomat, který se s korunním princem nikdy soukromě nesetkal. Funguje to. Vždycky by to fungovalo."],["Dejte titul ještě dvěma dalším příbuzným. Rozložte zátěž, rozložte i riziko.","Tři členové rodiny teď mají poradenské tituly navázané na stejnou zahraniční investici. Organizační schéma, které bývalo vtipem, se technicky stává studijním případem."],["Pošlete příbuzného nejdřív do Qadiri, bez platu, aby se tu práci skutečně naučil.","Příbuzný stráví čtyři měsíce jako neplacený juniorní atašé na ministerstvu zahraničí, kde skutečně sepisuje depeše, než se agendy vůbec dotkne. Je to opravdu užitečná průprava a zároveň naprosto neprodejná."]]},"p-sovereign-fund-clawback":{"t":"Zpětné vymáhání","x":"Hal Grimes má návrh zákona a pro jednou má sponzory napříč oběma stranami, což ho znepokojuje víc, než by ho znepokojovalo hlasování podle stranické linie. „Vynutil by úplný odprodej jakéhokoli podílu suverénního fondu nad jednu miliardu dolarů, pane. Hlasy na to má. Jediná otázka, která zbývá, zní, jestli s tím budete bojovat, nebo to podepíšete.“","c":[["Zabijte to ve výboru. Vybírejte poslední zbylé dluhy.","Návrh potichu zemře ve výboru, za skutečnou cenu, protože spotřebujete téměř všechny zbylé protislužby v budově. Podíl Qadiri přežije. Přežije i příběh o tom, jak přesně přežil."],["Nechte to projít. Podíl odprodejte. Přijměte ztrátu.","Dvě miliardy dolarů se rozpustí, se skutečnou finanční ztrátou, protože to tak žádá zákon. Je to nejdražší správné rozhodnutí celého funkčního období, a skoro nikdo si vůbec nevšimne, že k němu došlo."],["Vetujte to. Vyzvěte Kongres, ať to přehlasuje.","Vetujete nadstranický zákon o odprodeji, který se týká majetku vaší vlastní rodiny. Hlasování o přehlasování veta se okamžitě stane nejsledovanějším hlasováním roku."],["Ještě před hlasováním odprodejte podíl osobně, do ještě neprůhlednějšího trustu.","Formálně splníte zákon, který ještě ani neprošel, tím, že podíl přesunete někam ještě neprůhlednějšího, dřív než o něm kdokoli stihne hlasovat. Předkladatelé návrhu to nazvou „plněním ve zlé víře“ a tahle formulace se, pozoruhodně, dostane přímo do zprávy výboru."]]},"p-ballroom-wedding":{"t":"Svatba","x":"Deborah má ceník. Nový plesový sál, postavený z darů dárců „pro národ“, se pronajímá soukromým akcím za 500 000 dolarů za noc. První rezervace: svatba dcery manažera hedgeového fondu. „Technicky to není nezákonné, pane. Je to ale svatba, v Domě lidu.“","c":[["Zarezervujte ho na celou sezónu. Zvlášť víkendy.","Sál se fakticky stane nejexkluzivnějším místem pro akce v celé zemi, a to zrovna takovým, které se nachází uvnitř federálního sídla. Kalendář je zaplněný až do příštího jara."],["Jen tahle jedna svatba. Výtěžek půjde do fondu na ochranu památek.","Sál se použije jednou, vkusně, a peníze jdou na něco obhajitelného. Vznikne z toho jedna vřelá zpráva ze soudničky místo opakující se kauzy kolem pronájmů."],["Nechte ženichův hedgeový fond spolusponzorovat i pojmenování sálu.","Plesový sál ve federálním sídle teď nese jméno hedgeového fondu na malé mosazné cedulce u šatny. Historik znovu podá výpověď, tentokrát poštovním holubem, čistě ze vzdoru."],["Svatbu uspořádejte, ale požadujte, aby novomanželé zároveň uspořádali setkání s občany.","Dvě stě svatebních hostů ve společenském oblečení musí uprostřed hostiny sedět čtyřicet minut a poslouchat dotazy občanů o financování infrastruktury. Nikoho ze zúčastněných to nebaví, vás nevyjímaje."]]},"p-ballroom-corporate-retreat":{"t":"Výjezdní zasedání","x":"Lyle má žádost o rezervaci. Zbrojní dodavatel chce sál na třídenní výjezdní zasedání vedení, za 1,5 milionu dolarů, v hotovosti. Tentýž dodavatel čeká na vašem stole na rozhodnutí o zakázce za devět miliard dolarů, které má padnout příští týden.","c":[["Zarezervujte to. O zakázce rozhodněte hned následující pondělí.","Zasedání proběhne, šek je proplacen a zakázka je přidělena o pět pracovních dní později. Lyle poznamená, že tenhle sled událostí, poskládaný za sebou, „nevyžaduje žádnou fantazii na to, aby ho člověk pochopil“."],["Zarezervujte to. Z rozhodování o zakázce se ale úplně vylučte.","Poplatek za pronájem přesto přijde, ale rozhodnutí o zakázce dostane na starost náměstek, který s tou rezervací nemá nic společného. Je to verze příběhu, kde spolu nic nesouvisí."],["Poplatek za pronájem prominete. Místo toho si vezmete „poradenský honorář“.","Sál je technicky zdarma a mnohem větší platba, jinak označená, přijde jiným kanálem. Přejmenování peněz podle Lylea nepřejmenuje to, čím ve skutečnosti jsou."],["Zakázku ze vzdoru přidělte místo toho jejich konkurentovi.","Odkloníte devět miliard dolarů od firmy, která právě zaplatila za sál, výslovně proto, abyste zabránil dojmu protislužby. Dojem se zlepší. Samotná logika zadávání zakázek ne."]]},"p-ballroom-foreign-gala":{"t":"Zahraniční ples","x":"Muriel má žádost od velvyslanectví Qadiri. Chtěli by si pronajmout sál na ples ke svému státnímu svátku, za dva miliony dolarů, a jemně naznačují, že tento poplatek nemá nic společného s čekajícím obchodem se zbraněmi.","c":[["Schvalte to. Obchod se zbraněmi urychlete jako laskavost.","Zahraniční vláda zaplatí dva miliony dolarů za uspořádání večírku uvnitř federálního sídla a jejich obchod se zbraněmi je schválen následující měsíc. Muriel tu shodu okolností nazve nejsuššímu tónem, jakého je schopná, „diplomaticky nešikovnou“."],["Pronájem schvalte. Obchod se zbraněmi ale nechte projít běžným posouzením.","Večírek se koná, poplatek je připsán na účet a obchod se zbraněmi projde stejnou několikaměsíční cestou jako každý jiný. Dvě nesouvisející události zůstávají tvrdohlavě nesouvisející."],["Nechte o ten termín soutěžit ještě další tři království.","Čtyři svrchované vlády se pustí do dražby o jeden termín v kalendáři federálního sídla. Padne nový cenový rekord a zároveň se výrazně sníží laťka toho, k čemu takové sídlo vlastně slouží."],["Jako podmínku stanovte, že ples musí být otevřený veřejnosti, zdarma.","Donutíte dvoumilionový soukromý ples, aby byl zároveň bezplatným dnem otevřených dveří pro veřejnost, což nechce nikdo ze zúčastněných, nejméně ze všech ochranka řešící jedenáct tisíc příchozích."]]},"p-ballroom-double-booking":{"t":"Dvojitá rezervace","x":"Deborah nějakým způsobem zarezervovala sál dvakrát na stejnou sobotu: státní večeři pro navštěvující hlavu státu a placenou oslavu patnáctých narozenin. „Obě smlouvy jsou závazné, pane. Jedna se týká zahraniční hlavy státu. Ta druhá velmi odhodlané patnáctileté dívky.“","c":[["Přesuňte státní večeři. Klientka zaplatila první.","Navštěvující hlavu státu přesunete do menší místnosti na chodbě, aby oslava patnáctých narozenin mohla proběhnout podle plánu. Muriel to nazve nejhorším diplomatickým incidentem roku, na kterém se podílí skákací hrad."],["Přesuňte klientku. Vraťte celou platbu, osobně se omluvte.","Osobně zavoláte rodičům patnáctileté dívky a náklady na vrácení peněz nesete sám. Je to správné rozhodnutí a podle Deborah první úplně bezbolestné rozhodnutí za celý kvartál."],["Uspořádejte obě akce zároveň. Sál rozdělte oponou.","Sametová opona odděluje státní večeři od skákacího hradu ve vzdálenosti, kterou Alvin změří na necelé čtyři metry. Hlava státu slyší skákací hrad. Skákací hrad slyší všichni včetně hlavy státu."],["Spojte je dohromady. Hlava státu je teď hostem oslavy patnáctých narozenin.","Zahraniční hlava státu z donucení stráví devadesát minut na oslavě patnáctých narozenin a podle všech svědectví si tam užije nejlepší chvíli celé cesty."]]},"p-ballroom-naming-rights":{"t":"Pojmenovací práva","x":"Guvernérka Vasquez-Moore si o tuto schůzku nepožádala běžnou cestou, což je samo o sobě vzkaz. „Váš plesový sál stojí na federální půdě uvnitř mého státu, pane. Pronajímáte Dům lidu jako nějaký Sheraton. A hodlám to říkat nahlas, do záznamu, při každé příležitosti, kterou dostanu.“","c":[["Ignorujte ji. Je to federální půda. Její názor berete na vědomí, ale je irelevantní.","Rovnou odmítnete námitku úřadující guvernérky. Ona si to odmítnutí natočí a dvouminutové video získá víc zhlédnutí, než měl sál rezervací za celý kvartál."],["Zveřejněte úplné podmínky pronájmu i výnosy. Ať si spočítá čísla sama.","Otevřete účetnictví nepřátelsky naladěné guvernérce místo toho, abyste s ní z principu bojoval. Není to uspokojivé, ale funguje to, protože v účetní knize tentokrát skutečně není nic trapného."],["Pronajměte sál kampani jejího soupeře na fundraiser.","Zarezervujete sál výslovně pro politického soka guvernérky. Je to malicherné, mimořádně účinné a přesně ten druh malichernosti, který na fotkách vyznívá hrozně pro všechny zúčastněné, vás nevyjímaje."],["Pozvěte ji, ať příští ples spolupořádá. Výtěžek rozdělte s jejím státem.","Nepřátelsky naladěné guvernérce z opozice předáte polovinu výnosů ze sálu a její jméno na pozvánce, abyste ji odzbrojili. Funguje to líp než cokoli jiného na tomhle seznamu a stojí vás to jedinou věc, o kterou vám skutečně šlo, totiž veškerý kredit pro sebe."]]},"p-token-launch":{"t":"Spuštění tokenu","x":"Lyle to vysvětluje dvakrát, protože tomu sám úplně nevěří. „$PREZ, pane. Digitální token, žádný produkt, žádná společnost, jen značka. Spustil se z ničeho a teď má na papíře hodnotu v miliardách. To slovní spojení ‚na papíře‘ v té větě odvádí obrovský kus práce.“","c":[["Propagujte ho osobně. Na každém mítinku, v každém příspěvku.","Stanete se nejúčinnějším marketingovým nástrojem, jaký kdy měla měna bez jakéhokoli skutečného produktu. Tržní kapitalizace roste jen z nadšení, což je, jak podotýká Lyle, taky přesně to, jak zase klesne."],["Veřejně o tom nemluvte. Nechte ho žít vlastním životem.","Odmítnete sáhnout na tu jedinou páku, která nejvíc hýbe cenou. Mlčení vás nic nestojí a je to, pozoruhodně, první finančně gramotná věc, kterou kdokoli v budově za celý rok udělal."],["Načasujte velké politické oznámení tak, aby ho záměrně vystřelilo nahoru.","Oznámení o clech přijde tři minuty před plánovaným uvolněním tokenů. To načasování je buď mimořádná náhoda, nebo nejméně nenápadná věc, jakou jste kdy udělal, a nikdo to nebere jako to první."],["Veřejně přiznejte vlastní podíl a prodejte ho, živě, v přímém přenosu.","Před kamerou zlikvidujete vlastní podíl, z toho, co tvrdíte, že je transparentnost. Cena se do hodiny zhroutí. Čtrnáct tisíc lidí, kteří koupili proto, že jste ho držel vy, teď poprvé drží sami."]]},"p-token-pump":{"t":"Pumpa","x":"Kaylee má harmonogram mediálních vystoupení. Tři rozhovory, jeden mítink, jeden noční telefonát do rádia, všechno naplánované na stejný týden, kdy se velká tranše $PREZ uvolňuje pro zasvěcené osoby. „Vypadá to jako náhoda, pane, stejným způsobem, jako požár vypadá jako samovznícení. Technicky možné. Není na to ale rozumné sázet.“","c":[["Nechte harmonogram beze změny. Přidejte ještě čtvrtý rozhovor.","Čtyři vystoupení za týden pohnou cenou přesně podle plánu, přesně před uvolněním tokenů, přesně podle harmonogramu. Finanční novinářka to zanese do grafu a graf za ni řekne úplně vše."],["Mediální vystoupení přeplánujte tak, aby se uvolnění tokenů vyhnula, ne aby ho lemovala.","Záměrně oddělíte kalendář od grafu. Je to nejméně vzrušující dostupné rozhodnutí a jediné, které později přežije audit bez úhony."],["Nechte zasvěcené osoby potichu prodat do vlastního humbuku jako první.","Lidé nejblíže vám prodávají do růstu, který sami pomohli vytvořit, dřív než stejnou šanci dostane veřejnost. Je to nejstarší trik ve velmi staré knize, jen s novou mincí."],["Zrušte všechna mediální vystoupení daný týden, bez vysvětlení.","Na celý týden se odmlčíte bez udání důvodu, právě ve chvíli, kdy trh čekal maximální humbuk. Ticho cenu vyděsí hůř, než by jí pomohl sebevětší pump. Lyle to nazve „nehodou, která vypadá jako poctivost“."]]},"p-token-dump":{"t":"Výprodej","x":"Roscoe neobvykle odložil svůj psací blok. „$PREZ za šest hodin propadl o devadesát jedna procent, pane. BROOM se technicky na kryptoměny nevztahuje, ale bylo mi řečeno, že jde o největší přesun bohatství od běžných lidí k zasvěceným osobám, jaký jsem kdy osobně viděl číselně vyjádřený.“","c":[["Nic neříkejte. Zase se to zvedne. Obvykle to tak bývá.","Vyčkáváte mlčky, zatímco čtyřicet tisíc drobných držitelů sleduje, jak jim pozice mizí přímo před očima. Nezvedne se to. Mlčení v tomto případě je strategie, ze které vždy profitovala jen jedna strana."],["Vydejte prosté prohlášení. Bylo to spekulativní. Ztráty jsou skutečné.","Vyslovíte samozřejmou věc, kterou nikdo nechtěl slyšet vyslovenou: byla to sázka a sázky se prohrávají. Je to neuspokojivé, pravdivé a jediná verze událostí, která nevyžaduje žádnou navazující lež."],["Svalte to na zahraničního spekulanta na pokles. Jmenujte zemi, ne konkrétní osobu.","Devadesátiprocentní propad přisoudíte zahraničnímu spiknutí bez jmenovaného pachatele a bez důkazů. Funguje to přesně na ty lidi, kteří už token drželi, a na nikoho jiného."],["Osobně, z vlastní kapsy, odškodněte sto nejmenších držitelů.","Napíšete osobní šeky stovce lidí, kteří přišli o nejméně, vybraných zcela nahodile, zatímco dalších třicet devět tisíc nedostane nic. Je to velkorysé, nepatrné, a nespravedlnost to nějakým způsobem spíš zviditelní, než zmírní."]]},"p-token-lawsuit":{"t":"Hromadná žaloba","x":"Předseda Nejvyššího soudu Stone vysvětluje teorii bez okolků. „Třicet jedna tisíc žalobců, pane, tvrdí, že $PREZ byl vždycky cenný papír v přestrojení. Právní otázka je nudná. Důkazy, bohužel pro vás, nudné nejsou.“","c":[["Bojujte s tím. Argumentujte, že to vždycky byl jen vtip, meme.","Vaši vlastní právníci pod přísahou tvrdí, že věc, kterou jste čtyřiceti tisícům lidí prodal za skutečné peníze, nikdy neměla být brána vážně. Je to obhajoba. Není ale nijak lichotivá."],["Uzavřete dohodu. Tiše, rychle, než dokazování začne být zajímavé.","Dohoda uzavře případ dřív, než se z interní komunikace stanou veřejné důkazy. Stojí to skutečné peníze, ale čistě to ukončí příběh, který by dokazování udržovalo naživu roky."],["Podejte protižalobu na hlavního žalobce za pomluvu.","Zažalujete penzionovanou učitelku, která přišla o jedenáct tisíc dolarů, za to, že veřejně řekla totéž, co pod přísahou tvrdí i třicet tisíc dalších žalobců. Dojem, který to zanechá, přežije samotný soudní spor."],["Svědčte osobně. Živě. Pod přísahou. Dobrovolně se přihlaste.","Dobrovolně usednete na svědeckou lavici, navzdory veškerým radám v budově, a tři hodiny odpovídáte na otázky o minci, která nese vaše jméno. Sy to nazve „buď velmi statečným činem, nebo poslední chybou celého případu“."]]},"p-token-relaunch":{"t":"Nový start","x":"Miriam má prezentaci, která dorazila už vytištěná, jako by s její námitkou počítali dopředu a rovnou ji odmítli. „$PREZ2, pane. Stejný tým, ve třech případech stejné adresy peněženek, nové logo. Chtěla bych do záznamu uvést, že když jsem to jméno poprvé četla, nahlas jsem se rozesmála.“","c":[["Spusťte to. Větší kampaň než u toho prvního.","$PREZ2 se spouští s ještě větší slávou než ten původní a během měsíce má téměř identický graf. Třicet tisíc lidí, kteří přišli o peníze u prvního tokenu, kupuje ten druhý z čeho jiného než z naděje."],["Nový start úplně zablokujte. Žádné pokračování.","Pokračování zastavíte dřív, než vůbec vyjde. Je to zdaleka nejochrannější věc, jaká byla pro lidi, kteří přišli o peníze u toho původního, kdy udělána, a nepřinese vám to nic měřitelného."],["Spusťte to pod krycí značkou. Jakoukoli spojitost veřejně popírejte.","Nový token se spustí pod jménem, které nezní jakkoli spojeně, ale spravují ho tři stejné peněženky jako předtím. Popírání vydrží jedenáct dní, přesně tak dlouho, jak trvá, než si to někdo ověří."],["Spusťte to, ale sto procent vlastního podílu věnujte obětem toho původního tokenu.","Pokračování mince, která už jednou zruinovala čtyřicet tisíc lidí, se přesto spustí a z výtěžku financuje oběti svého předchůdce. Je to buď náhrada škody, nebo druhá emise, a Miriam si není jistá, že ten rozdíl přežije kontakt se soudní síní."]]},"q-crowd-count":{"t":"Počet lidí v davu","x":"Nadia má na klipovací desce dvě čísla. „Úřad pro povolení tvrdí, že se na ten trávník vejde čtyři tisíce lidí, pane. Brayden novinářům říká dvě stě tisíc. Pro záznam bych ráda uvedla, že jsem si nevybrala ani jedno z těch čísel.“","c":[["Použijte Braydenovo číslo. Zopakujte ho na pódiu.","Prohlásíte, že kapacita trávníku je padesátkrát vyšší, než dovoluje požární předpis. Požární inspektor profesionálně přikývne a neprofesionálně mlčí."],["Citujte číslo z povolení. Ať je malé.","Sdělíte skutečné číslo místnosti, která chtěla slyšet to druhé. Je přesné, nezajímavé a do oběda zmizí ze zpravodajství."],["Tvrďte, že prázdná tráva byla vyhrazená pro opozdilce.","Vysvětlíte, že viditelná prázdná tráva byla stání pro dav, který nikdy nedorazil. Několik novinářů si to zapíše doslova, ze soucitu."],["Dejte na velkoplošnou obrazovku počítadlo hlav v reálném čase.","Obrazovka počítající hlavy v přímém přenosu promění čtyřicet minut politického shromáždění v lidi křičící čísla na kameru. Odpojí ji dřív, než dosáhne pěti číslic."]]},"q-turnstile-cams":{"t":"Turnikety s kamerami","x":"Duane chce na příští shromáždění nainstalovat opravdové turnikety, s kamerami, „kvůli bezpečnosti“, říká a přitom se vám nedívá zcela do očí. „Dalo by nám to i skutečné číslo, pane. Nezpochybnitelné. Jsem si vědom, že to není důvod, proč se ptáte.“","c":[["Nainstalujte je. Skutečné číslo hlasitě zveřejněte.","Turnikety zaklapávají skutečně velký dav a číslo pro jednou nepotřebuje žádnou pomoc. Je to nějak méně uspokojivé než lež."],["Nedělejte to. Počítat vlastní dav je nedůstojné.","Odmítnete instalovat bezpečnostní divadlo kvůli statistice. Duane si ten nápad uloží pro prezidenta, který bude méně háklivý na turnikety."],["Nainstalujte je, pak potichu odpojte ty u prázdné sekce.","Polovina turniketů počítá a polovina ne. Audit, až přijde, je nezvykle krátký a nezvykle rozzlobený."],["Přeměňte turnikety na automat s hracími drápy.","Návštěvníci teď vhazují žeton, aby se dostali dovnitř, a jeden z padesáti vyhraje plyšovou verzi vás. Fronta na odchod je delší než fronta na vstup."]]},"q-empty-seats":{"t":"Prázdné židle","x":"Brayden vám ukazuje fotku, než se pošle dál: přiblížený záběr na první tři řady, nabité a jásající. Za kamerou se čtyři tisíce prázdných skládacích židlí táhnou až k parkovišti. „Není to lež, pane,“ říká. „Je to jen výřez.“","c":[["Schvalte výřez. Zveřejněte ho dnes večer všude.","Přiblížený záběr jde do devíti hodin na všechny účty. Místní novinář zveřejní ten širokoúhlý v deset. Oba jsou pravdivé a jen jeden se sdílí."],["Zveřejněte sám ten širokoúhlý záběr, bez obav.","Sdílíte poctivou fotku dřív, než ji proti vám mohl někdo použít. Je to zvláštní, malý druh odvahy a nikdo si nevšimne, že jste ho projevil."],["Nechte personál zaplnit zadní řady kartonovými figurínami.","Čtyři sta kartonových příznivců obsadí zadní sekci pro širokoúhlý záběr. Jedna se ve větru na kameru převrátí a týden je trendem."],["Ohraďte prázdnou sekci jako „zónu ztišení“.","Prázdné židle se přejmenují na tichý prostor pro rozjímání nad okamžikem. Nikdo si tam nesedne. To je, jak se ukazuje, ten pravý smysl."]]},"q-rival-headcount":{"t":"Soupeřovo počítání hlav","x":"Kaylee přes stůl posouvá dronové záběry konkurenční stanice, s časovým razítkem a geolokací, které ukazují zhruba třetinu davu, který jste tvrdil. „Je to dobrá práce, pane. Pečlivá, doložená, nudná práce. Nesnáším, že je přesná.“","c":[["Prohlaste dronové záběry za zfalšované. Dnes večer, hlasitě.","Obviníte geolokovanou, časově označenou fotografii z podvodu. Polovina země vám věří dřív, než záběry vůbec stačí dvakrát ověřit."],["Nechte to číslo být. Mluvte o účasti, ne o velikosti.","Přesunete se od prohrané hádky k vyhrané. Je to nejdisciplinovanější věta celého týdne a na shromáždění se neopakuje."],["Zveřejněte vlastní dronové záběry, natočené přímo nad prvními řadami.","Váš dron krouží přesně tam, kde je dav nejhustší, a nikde jinde. Technicky je to záběr, funkčně propaganda, zaevidováno jako obojí."],["Zakažte drony nad federálními shromážděními, se zpětnou platností.","Zpětně platné pravidlo vzdušného prostoru cílí přesně na zařízení, které vás zostudilo. Tři nadšenci dostanou pokutu dřív, než si někdo všimne, že to číslo neopravuje."]]},"q-merch-table":{"t":"Stůl se suvenýry","x":"Brayden má skládací stůl plný vzorků: zlatou čepici, svíčku s vůní ve tvaru vaší pěsti, plyšovou panenku, která po stisknutí řekne jednu z devíti frází. „Kupují to rychleji, než to stíháme tisknout, pane. Upřímně nevím, kde je strop.“","c":[["Schvalte všech devět. Ztrojnásobte náklad.","Sklad běží na tři směny a svíčka se dvakrát vyprodá. Jeden ekonom to nazve zbožnou maloobchodní zbožností. Myslí to, víceméně, jako kompliment."],["Schvalte jednu položku. Skromná marže, čisté účetnictví.","Jeden vkusný předmět se dodává s účtenkou, kterou by kdokoli obhájil při slyšení. Je to nejméně zábavná volba na stole a nejbezpečnější."],["Přidejte předplatitelský balíček. Posílejte něco každý měsíc, navždy.","Opakovaná platba teď chodí do schránek po celé zemi, ať už si ji někdo pamatuje objednat, nebo ne. Zrušení vyžaduje telefonát, který nikdo nezvedá."],["Nechte Braydena, ať si devátou frázi vymyslí sám.","Devatenáctiletý kluk napíše pro plyšovou panenku větu, kterou právní oddělení neschválilo a neschválí. Přesto se prodává. Stane se to nejprodávanější frází."]]},"q-counterfeit-hats":{"t":"Padělané čepice","x":"Sy má krabici padělků zabavených u obvodu shromáždění: stejné heslo, špatný odstín červené, ušité v továrně, která není vaše. „Mohli bychom žalovat, pane. Nebo to prostě nechat být, protože polovina vašeho skutečného dodavatelského řetězce má stejný problém a vyšetřování jde na obě strany.“","c":[["Žalujte padělatele do základů. Veřejně.","Velmi veřejná žaloba na padělatele čepic se stane hlavní zprávou dne. Vyšetřování při shromažďování důkazů odhalí přesně to, před čím vás Sy varoval."],["Vydejte licenci. Vezměte si podíl, udržte to legální.","Padělatel se přes noc stane licencovaným partnerem, papíry a vším. Je to nejméně dramatický možný výsledek a vydělá skutečné, nudné peníze."],["Ignorujte to. Padělky jsou v podstatě zdarma reklama.","Necháte padělky kolovat bez zásahu. Prodej pravého merchandisingu klesne o jedenáct procent a nikdo v budově to číslo nahlas nevysloví."],["Nechte zabavené čepice spálit živě v televizi jako varování.","Hranice ze zabavených kšiltovek vysílá v hlavním vysílacím čase. Vizuál je někde mezi pálením knih a firemním večírkem a nikdo se neshodne, čím přesně."]]},"q-merch-audit":{"t":"Kontrola merchandisingu","x":"Miriam Applewhitová má šanon. „Svíčka, mince, parfém, odznak s vlajkou, druhá svíčka. Všechno to jde přes firmu, na jejímž listu vlastnictví je vaše jméno, pane. Jsem povinná se zeptat, jestli se z Úřadu prezidenta a suvenýrového obchodu nestal jeden podnik.“","c":[["Řekněte, že tomu tak vždycky bylo. Jděte dál.","Potvrdíte, do záznamu, že prezidentský úřad a produktová řada sdílejí bankovní účet. Miriam napíše zprávu, která přežije vás oba."],["Prodejte firmu do slepého fondu. Opravdu slepého.","Proběhne skutečné, ověřitelné odprodání se skutečnými, ověřitelnými papíry. Je to nejnudnější odpoledne vašeho mandátu a nejčistší."],["Přejmenujte firmu. Stejný vlastník, nová hlavička.","Suvenýrový obchod se přes noc stane „nadací dědictví“. Hlavička se změní. Vlastnický list, poznamená Miriam v poznámce pod čarou, ne."],["Věnujte zisky nadaci, která má taky vaše jméno.","Peníze se přesunou z jedné budovy s vaším jménem na dveřích do druhé budovy s vaším jménem na dveřích. Miriam si vyžádá tlustší šanon."]]},"q-family-merch":{"t":"Rodinný podnik","x":"Ivy má prezentaci. Sluneční brýle, kosmetická řada, karetní hra „vůdcovství“, to vše pod značkou, kterou, malým písmem, řídí vaše rodina. „Prodává se to díky tobě, tati. Chtěla bych jen, aby to bylo legální i díky mně.“","c":[["Nechte ji dělat, co chce. Je to rodinná záležitost.","Karetní hra o vůdcovství s vaší vlastní tváří tento čtvrtrok předčí prodejem tři skutečné deskové hry. Rodinná značka a federální vláda se rozostří za bod, kdy je lze ještě oddělit."],["Ať se stáhne od všeho, co se dotýká úřadu.","Prodá kosmetickou řadu cizímu člověku za férovou cenu a vrátí se k menší práci s menším titulem. Je to potichu ta správná volba."],["Nastavte to přes licenční smlouvu, která vypadá nezávisle.","Vznikne licenční struktura, která splňuje literu pravidla, jež v budově nikdo pořádně nečetl. Na fotografii vypadá jako soulad s předpisy."],["Udělejte z ní velvyslankyni v zemi, která náhodou vyrábí ty sluneční brýle.","Dodavatelský řetězec a diplomatický post se spojí v jedno velmi efektivní, velmi neobhajitelné uspořádání. Hostitelská země je nadšená. Senát ne."]]},"q-merch-recall":{"t":"Stažení merchandisingu","x":"Lyle má laboratorní zprávu. Pamětní mince s vaším profilem při manipulaci uvolňuje měřitelné množství olova. „Nikdo tu minci nejí, pane. Ale někteří ji nosí jako přívěsek, na holé kůži, celé hodiny.“","c":[["Přesto ji vydejte. Přidejte varovný štítek, který nikdo nečte.","Nálepka velikosti razítka teď varuje před nebezpečím, které mince svým designem sama ztělesňuje. Prodej mince výrazně převyšuje čitelnost té nálepky."],["Stáhněte ji. Vraťte všem peníze. Oznamte to jasně.","Vyhlásíte skutečné stažení se skutečným postupem vracení peněz, nákladné, nudné a správné. Nikdo neumře na otravu olovem z mince, což je laťka, kterou snadno přeskočíte."],["Přeznačte ji na „vintage kvalitu“ a zvyšte cenu.","Olovo se stane featurem. Limitovaná série „dědictví ve slitině“ se prodává trojnásobně, kupujícím, kteří, jak Lyle poznamenává, teď platí příplatek za nebezpečí."],["Nechte Braydena, ať na živém streamu nosí dvanáct mincí, aby dokázal, že jsou bezpečné.","Teenager si na kameru šest hodin nosí tucet přívěsků blízkých olovu, aby uklidnil národ. Jeho lékař to sleduje. Jeho lékař není nadšen."]]},"q-overnight-theory":{"t":"Teorie přes noc","x":"Do rána má teorie jméno, symbol a hashtag: vaši nepřátelé se prý koordinují přes meteorologickou službu. Brayden ji nezaložil. Je ale teď třetím největším účtem, který ji šíří. „Neřekl jsem, že je pravdivá, pane. Řekl jsem, že má čtyřicet tisíc sdílení za hodinu.“","c":[["Sdílejte ji s mrknutím v popisku.","Zesílíte teorii o Národní meteorologické službě jedenácti milionům sledujících, aniž byste ji potvrdil nebo popřel. Je to nejúčinnější lež, kterou jste nikdy technicky nevyslovil."],["Nedělejte nic. Ať vyhasne sama.","Odmítnete se do toho zapojit. Za devět dní to vyhasne, víceméně, nahrazeno teorií o poštovní službě, na kterou se vás taky nikdo neptal."],["Nechte ji potvrdit členem kabinetu, neoficiálně.","Anonymní vysoký úředník „obeznámený s věcí“ dodá teorii důvěryhodnost, kterou si nezasloužila. Meteorologická služba otevírá velmi zmatený tiket na infolince."],["Pozvěte autora teorie na osobní brífink.","Muž, který teorii vede ze své garáže, dostane patnáct minut v Oválné pracovně. Přinese šanon. Nikdo v místnosti neví, jestli to dopadlo dobře."]]},"q-deep-state-snack":{"t":"Svačinka hlubokého státu","x":"Errol Hance vypadá opravdu unaveně. „Teorie tohoto týdne, pane, tvrdí, že určitá značka preclíků je signalizační zařízení pro kariérní úředníky. Přečetl jsem si zpravodajský posudek na ten preclík. Obsahuje mouku, sůl a nic jiného.“","c":[["Zakažte preclíky ve federálních budovách. Okamžitě.","Svačinka se odstraní z prodejních automatů napříč exekutivou, do vyřešení. Posudek najde mouku a sůl. Zákaz platí dál."],["Nechte Errola vydat jednořádkové prohlášení: je to preclík.","Ředitel rozvědky veřejně potvrdí, že svačinka je svačinka. Je to nejabsurdnější věta, k níž kdy připojil své jméno, a funguje."],["Naznačte, nejasně, že to nemůžete vyloučit.","Odmítnete z pódia potvrdit nebo popřít preclíkovou konspiraci. Ta nejednoznačnost má pro základnu větší hodnotu než jakékoli popření."],["Nařiďte Errolovi, ať jeden sní na kameru, oficiálně.","Ředitel rozvědky sní preclík živě v televizi, aby vyvrátil teorii o preclíku. Nevyvrátí to teorii. Nic tu teorii nevyvrátí."]]},"q-numbers-station":{"t":"Rozvodna čísel","x":"Ředitelka Quistová má teď skutečný problém: tři muži byli zatčeni před rozvodnou, přesvědčeni teorií z předešlé noci, že vysílá signály na ovládání mysli synchronizované s vaším harmonogramem shromáždění. „Teorie začala jako vtip, pane. To mužům s kleštěmi na dráty nikdo neřekl.“","c":[["Řekněte, že rozvodna si možná zaslouží bližší pohled.","Odmítnete plně popřít teorii, kvůli které byli zatčeni tři muži s kleštěmi na dráty. Quistová si písemně vyžádá, abyste to přestal dělat."],["Odsuďte tu teorii. Jasně. Jmenovitě.","Z pódia jasně označíte teorii o rozvodně za nesmysl. Nestojí vás to nic měřitelného a možná vás to stojí život, o kterém se nikdy nedozvíte."],["Omilostněte ty tři muže. Nazvěte je vlastenci.","Tři muži, kteří přestřihli plot kvůli teorii o ovládání mysli, dostanou plnou milost a fotku v Oválné pracovně. Rozvodna zůstává, vzdorně, rozvodnou."],["Pošlete Errola, ať s filmovým štábem osobně provede prohlídku rozvodny.","Ředitel rozvědky živě komentuje prohlídku transformátorového dvora, aby dokázal, že jde skutečně o transformátorový dvůr. Sledovanost je vysoká. Víra nepohnutá."]]},"q-conspiracy-merch":{"t":"Teorie jako zboží","x":"Bo Slaughter drží tričko vytištěné do devíti hodin od chvíle, kdy se teorie stala virální: kreslené oko nad preclíkem, nad rozvodnou. „Už se to prodává, pane. Ověřil jsem si to. Někdo v této budově má velmi rychlou tiskárnu a žádný stud.“","c":[["Ať se prodává. Vezměte si podíl z licence.","Oko, preclík a rozvodna se do týdne stanou tričkem, pak čepicí, pak hrnkem na kávu, vše oficiálně licencované. Nikdo zúčastněný nedokáže definovat, co to znamená, a přesto si to všichni kupují."],["Nechte právní oddělení tiše stáhnout tričko z oficiálního obchodu.","Tričko zmizí z obchodu beze slova. Do večeře se objeví na stránce třetí strany. Tiskárnu zpátky do krabice nedostanete."],["Vytiskněte „oficiální“ verzi, abyste přebili padělek.","Vládě blízká značka teď soupeří s garážovou provozovnou o prodej triček k teorii, kterou žádná z nich nedokáže vysvětlit. Garáž vyhrává na ceně."],["Najměte toho tiskaře jako oficiálního designéra.","Muž s rychlou tiskárnou a bez studu je teď na federální výplatní listině. Jeho první úkol, oficiálně, je „konzistence značky“. To taky nikdo nedefinuje."]]},"q-the-prophecy":{"t":"Proroctví","x":"Reverend Muncy vám přináší pasáž, dvakrát podtrženou, z knihy, o níž trvá na tom, že předchází vaše zvolení o čtyřicet let. Nejmenuje nikoho. Popisuje, říká, „muže v červené kravatě, který obnoví to, co bylo ztraceno“. „Neříkám, že jste to vy, pane. Říkám, že ta kravata je velmi konkrétní detail.“","c":[["Noste tu červenou kravatu od teď každý den.","Přijmete kravatu jako uniformu. Nedostatek konkrétního odstínu červené hlásí, zcela vážně, tři regionální televizní stanice."],["Poděkujte mu laskavě. Změňte téma.","Odmítnete být něčím proroctvím. Je to malé, důstojné odmítnutí, které reverend přijme s viditelným zklamáním."],["Požádejte ho, ať najde další tři pasáže. Z libovolné knihy.","V Západním křídle vzniká malý domácký průmysl zpětného přizpůsobování Písma. Do konce měsíce jste zjevně předpovězen ve čtyřech různých tradicích."],["Věnujte tu skutečnou knihu Národnímu archivu, nepřečtenou.","Kniha proroctví je uctěna jako federální historický dokument, aniž by kdokoli potvrdil, co vlastně říká. Archivář stráví kariéru poznámkováním jedné červené kravaty."]]},"q-prophecy-sequel":{"t":"Druhé proroctví","x":"Konkurenční kazatel vydal soupeřící proroctví, z jiné knihy, jmenující jiného muže v jiné kravatě. Reverend Muncy je, poprvé co jste ho takhle viděli, otřesený. „Tohle je technicky kacířství, pane. Proti mému proroctví. Které vám připomínám, že jsem si taky vymyslel.“","c":[["Nechte Muncyho veřejně odsoudit to soupeřící proroctví.","Dva duchovní se v kabelové televizi hádají, čí smyšlená předpověď je ta skutečná smyšlená. Ani jedno publikum si nevšimne společné premisy."],["Ignorujte soupeře úplně. Proroctví nepotřebuje obhajobu.","Odmítnete dát odpovědí důstojnost konkurenčnímu mýtu o vás samém. Je to, proti každému instinktu v budově, ten bezpečný krok."],["Objednejte třetí proroctví, které předchází obě.","Vznikne nově „objevený“ starší text, který obě ostatní překoná už jen datem vydání. Teologie se zhorší. Základna zesílí."],["Pozvěte oba kazatele, ať spolu na jevišti sepíšou sjednocené proroctví, živě.","Dva muži se před devíti tisíci lidmi pokoušejí spojit oddělená zjevení. Nejde to hladce. Nějak to taky nejde úplně špatně."]]},"q-historians-verdict":{"t":"Historička to vyvrací","x":"Dr. Weirová vystopovala proroctví k jeho skutečnému zdroji: reklamní leták pánského oblečení ze 70. let, firma zbankrotovala v roce 1984. „Není to proroctví, pane. Je to kupón. Mám ten kupón. Přinesla jsem ten kupón.“","c":[["Kupón zahrabejte. Proroctví platí dál.","Kupón zaniklého řetězce pánského oblečení je tiše přeřazen a založen tam, kam se nikdo nepodívá. Proroctví přežije vlastní poznámky pod čarou."],["Zveřejněte její zjištění. Ať záznam zůstane záznamem.","Pravda o kupónu vyjde na deváté straně. Nezmění to nic na účasti na příštím shromáždění, což Dr. Weirovou znepokojí víc než samotný kupón."],["Tvrďte, že kupón byl sám o sobě prorocký.","Tvrdíte, že sleva z roku 1984 předpověděla vlastní budoucí zneužití. Nemělo by to fungovat. Funguje to."],["Nechte Dr. Weirovou uložit kupón vedle Ústavy.","Zaniklý kupón pánského oblečení dostane stejné archivní zacházení jako zakládající dokument. Historička si znovu, opakovaně, žádá přeřadit na cokoli jiného."]]},"q-the-book":{"t":"Kniha","x":"Gideon má rukopis: čtyři sta stran, vaše jméno na obálce, většinu jste nadiktoval v letadle a přepsáno bylo ve tři ráno. „Potřebuje redaktora, pane. Potřebuje, upřímně, druhého autora. Co má, je datum vydání.“","c":[["Vydejte to tak, jak to je. Syrové je autentické.","Kniha se čtrnácti nevyřešenými metaforami a jednou kapitolou, která se prostě znovu spustí, jde na pulty neupravená. Debutuje na první příčce, což vypovídá buď o knize, nebo o žebříčku."],["Nechte Gideona to opravdu upravit. Odložte vydání.","Schopný redaktor promění výlev v knihu. Je lepší, pomalejší a prodává se zhruba stejně, což je nejupřímnější recenze, jakou kdy Gideon dostal."],["Nechte Gideona napsat to celé, kredit náleží jen vám.","Hotový produkt je celý ghostwritten a smluvně celý váš. Gideon podepíše mlčenlivost silnější než samotný rukopis."],["Vydejte syrový přepis, s překlepy, časovými razítky, se vším.","Kniha ze syrové diktace ze tří ráno, včetně čtyřicetjednoho výskytu „počkej, řekni to jinak“, vychází jako limitovaná umělecká edice. Vyprodá se. Nikdo neví proč."]]},"q-ghostwriter-quits":{"t":"Ghostwriter dává výpověď","x":"Gideon položí na váš stůl výpovědní dopis a pak si, neobvykle, přece jen sedne, aby vám to vysvětlil osobně. „Pokračování chce, abych napsal, že přistání na Měsíci se stalo dvakrát a že jste byl konzultován k tomu druhému, pane. Mám hranice. Zhruba tady jsou.“","c":[["Přijměte výpověď. Najděte někoho s menšími hranicemi.","Náhradní autor se najde do týdne, kvalifikovaný, hladový a zcela bez Gideonových zábran. Pokračování vyjde podle plánu."],["Vyškrtněte kapitolu o Měsíci. Nechte si Gideona.","Necháte jednu absurdní kapitolu jít, abyste si udrželi autora, který vám občas ještě řekne ne. Je to malý, drahý akt sebezáchovy."],["Kapitolu přesto vydejte, bez podpisu, jako „unikátní úryvek“.","Lunární kapitola „unikne“ pár dní před vydáním a žene předobjednávky nad rámec obsahu samotné knihy. Popíratelnost je, jako vždy, celý produkt."],["Nechte Gideona a náhradníka napsat to jako debatu.","Dvě soupeřící kapitoly běží vedle sebe, jedna upřímná, druhá ujetá, bez náznaku, která je která. Čtenářské kluby po celé zemi mají za léta nejhorší schůzky."]]},"q-book-blurb":{"t":"Citace na obálce","x":"Sy má text pro zadní obálku, který jste nadiktoval, přisouzený generálovi, který, jak se ukázalo po telefonátu, nesouhlasí s tím, že to řekl. „Říká, že je to hezký sentiment, pane. Taky říká, že to nikdy neřekl. Obě tvrzení se momentálně tisknou na čtyři sta tisíc výtisků.“","c":[["Vytiskněte to tak jako tak. On se s tím smíří.","Generálovo jméno zůstane u citátu, který nikdy nedal. Nesmíří se s tím. Nakonec odmítne každý budoucí rozhovor o té knize."],["Stáhněte citaci. Sežeňte skutečnou, i kdyby byla nudná.","Skutečná, mírnější podpora nahradí smyšlenou za skutečné náklady na přetisk. Říká méně a znamená víc, což je obchod, který v budově nikdo nechtěl uzavřít."],["Přisuďte citát „vysoce postavenému úředníkovi“ místo toho.","Citát přežije, vypraný přes anonymitu. Je stejně nevyvratitelný jako nepůsobivý."],["Požádejte generála, ať si napíše vlastní citaci, ať zní jakkoli.","Generál dodá jednu upřímnou větu o telefonátu, který se jednou opravdu stal. Vytiskne se beze změn. Je to, proti všem očekáváním, nejlepší věta na obálce."]]},"q-boat-parade":{"t":"Lodní přehlídka","x":"Duane má zprávu od přístavního kapitána. Dvě stě soukromých lodí, vlajky vlají, krouží v zálivu na vaši počest, většina daleko za kapacitou. „Nikdo to neorganizoval, pane. Nikdo nemusel. A nikdo nezkontroloval počasí, kvůli čemuž vlastně volám.“","c":[["Přeleťte to sám. Zamávejte z vrtulníku.","Přelet vrtulníku nad dvěma sty přeplněnými loďmi vyprodukuje nejlepší fotku měsíce. Zpráva pobřežní stráže o incidentu ze stejného odpoledne se tak nesdílí."],["Požádejte kapitána, ať nejdřív vymáhá limity kapacity.","Upřednostníte nenápadnou bezpečnostní kontrolu před fotografickou příležitostí. Nikdo se neutopí. Nikdo vám taky neděkuje."],["Vyhlaste to za federální flotilu a přidejte ohňostroj na závěr.","Neoficiální srocení majitelů lodí se proklamací stane federálně uznávanou akcí s vlastní rozpočtovou položkou a finále. Kapitán přístavu si klidně vyžádá přeřazení."],["Připojte se k přehlídce na vodním skútru, osobně, bez pojištění.","Projedete vlastní flotilou na pronajatém vodním skútru bez záchranné vesty a bez povolení. Ochranka na doprovodném člunu zestárne o deset let za čtyři minuty."]]},"q-parade-capsizes":{"t":"Přehlídka se převrátila","x":"Generál Tarrant sedí u vašeho stolu s výrazem, který se viditelně snaží udržet klidný. „Tři lodě se na flotile převrátily, pane. Všichni jsou v pořádku. Jedna vezla vlajku s vaší tváří, zhruba velikosti hlavní plachty. Ta vlajka je teď na dně zálivu.“","c":[["Nazvěte to důkazem nadšení. Pošlete další vlajky.","Tři převrácené lodě vylíčíte jako svědectví oddanosti, ne jako nebezpečí. Náhradní zásilka předimenzovaných vlajek odjede do týdne."],["Nechte pobřežní stráž vydat limit velikosti vlajek.","Vejde v platnost skutečně rozumné námořní bezpečnostní pravidlo. Je to zatím jediné nařízení tohoto mandátu, se kterým všichni soukromě souhlasí."],["Obviňte loď, ne vlajku.","Naznačíte, že problémem bylo plavidlo, ne šestimetrový plachtovinový portrét. Majitel lodi, oslovený k vyjádření, nesouhlasí, na záznam."],["Udělte potopené vlajce medaili in memoriam.","Ceremonie se koná pro kus látky momentálně na mořském dně. Generál Tarrant se dostaví v plné parádní uniformě a později to soukromě popíše jako nejhorší odpoledne kariéry."]]},"q-navy-escort":{"t":"Doprovod námořnictva","x":"Tarranta se zdvořile a opakovaně ptali, jestli by válečná loď mohla „zaskočit“ na příští lodní přehlídku kvůli vizuálu. „Není to, přísně vzato, bojový požadavek, pane. Taky to není, přísně vzato, něco, co bych mohl odmítnout dvakrát.“","c":[["Nařiďte doprovod. Torpédoborec se skvěle fotí.","Torpédoborec s naváděnými střelami odbočí, aby se odpoledne motal poblíž civilní flotily. Fotky jsou výjimečné. Účet za palivo se nakonec rozepíše ve slyšení."],["Odmítněte. Námořnictvo má skutečnou práci.","Necháte flotilu dělat, co má. Je to správné, neviditelné a je to verze tohoto příběhu, která se na shromáždění nikdy nevypráví."],["Pošlete raději člun pobřežní stráže. Levnější, pořád šedý.","Menší, levnější plavidlo poskytne zhruba stejnou fotku za třetinu pobouření. Nikdo na přehlídce nepozná rozdíl a nikdo u slyšení na to nezapomene."],["Požádejte spřáteleného miliardáře, ať pošle svou jachtu přestrojenou za válečnou loď.","Soukromá jachta se na odpoledne natře na šedo a vlaje signálními vlajkami, které na palubě nikdo neumí přečíst. Z dálky je k nerozeznání od skutečné. Zblízka má vířivku."]]},"q-the-challenger":{"t":"Vyzyvatelův živý přenos","x":"Šestadvacetiletý mladík se čtyřmi miliony sledujících začal streamovat před vašimi shromážděními, souhlasí téměř se vším, co říkáte, a jemně dodává, že jste možná trochu pomalý s tím jednat. Brayden sleduje čísla, jak v reálném čase rostou. „Není proti vám, pane. To je právě to, co by vás mělo znepokojovat.“","c":[["Odsuďte ho jako podvodníka. Dnes večer, jménem.","Zaútočíte na mladíka za to, že s vámi souhlasí příliš nadšeně. Významné části základny to připadá jako žárlivost, protože to žárlivost je."],["Ignorujte ho. Ať si základna sama vytřídí své preference.","Odmítnete dát důstojnost soupeři o pozornost vlastního publika. Dnes vás to nic měřitelného nestojí a každý další den něco neměřitelného."],["Pozvěte ho na pódium. Přivlastněte si ho, než ještě víc vyroste.","Sdílíte pódium s mužem, který si buduje publikum z vašich zbytků. Dav jásá pro oba, což je přesně ten problém."],["Nechte Braydena vyzvat ho na živě vysílanou debatu o ničem konkrétním.","Dva dvacátníci se devadesát minut hádají o tom, kdo vám rozumí lépe, zatímco vy v místnosti nejste. Nikdo nevyhraje. Oba získají sledující."]]},"q-poach-attempt":{"t":"Pokus o přeteč","x":"Nadiina čísla to ukazují jasně: kus vaší základny, možná šest procent, začal sledovat výhradně vyzyvatele, ne jako konkurenci, jen jako druhou věc navíc. „Neopouštějí vás, pane. Jsou teď prostě taky jeho. Nevím, jak spravit matematický problém, který není odčítáním.“","c":[["Kupte reklamní kampaň cílenou přímo na jeho sledující.","Přesně zacílená reklamní kampaň honí šest procent soupeřova publika napříč každou platformou, kterou používají. Funguje to na zhruba třetinu z nich, což Nadia nazývá výhrou."],["Zeptejte se, co nabízí, co vy ne. Skutečně něco změňte.","Berete odchod jako signál, ne zradu, a upravíte jednu skutečnou věc. Je to potichu účinné a naprosto neoslavované."],["Nabídněte mu placenou funkci v administrativě. Ticho za plat.","Vyzyvatel přijme titul, kancelář a obojek. Jeho nezávislé publikum si obojku všimne do měsíce."],["Nechte Braydena tajně provozovat parodický účet, který si z něj utahuje.","Parodický účet, vystopovaný během pár dní k IP adrese Bílého domu, si z vyzyvatele nemilosrdně utahuje. Odhalení je nakonec škodlivější než samotný posměch."]]},"q-vp-courts-base":{"t":"Viceprezidentovo sólo turné","x":"Chet Danforth ohlásil vlastní turné, nezávislé na vašem úřadu, „jen se seznamuji s lidmi“, přesně ve státech, které vaše shromáždění vynechala. Celou dobu, co vám to říká, se usmívá. „Inspiroval jste mě, pane. Doufám, že je to v pořádku.“","c":[["Nařiďte mu to zrušit. Pořád velíte vy.","Veřejně krotíte vlastního viceprezidenta za zločin podávání rukou. Pro některé to působí jako síla, pro každého, kdo dává pozor, jako úzkost z nástupnictví."],["Nechte ho jet. Loajální viceprezident je silná kandidátka.","Necháte ambici běžet na povrchu místo pod ním, což je buď velkorysé, nebo naivní, a jasné to bude až za dva roky."],["Naplánujte shromáždění ve stejném městě, stejný týden.","Dvě shromáždění pro stejné publikum, šest dní od sebe, ve stejné aréně. Základna přijde na obě a porovnává fotky davu, což je pro vás přesně tak zlé, jak to zní."],["Přidělte mu itinerář „naslouchacího turné“, který jste sám napsal.","Předáte vlastnímu viceprezidentovi rozvrh malých, nevýrazných shromáždění na místech s hrozným signálem. Poslušně jede a šest týdnů ho na internetu nikdo nevidí."]]},"q-the-chant":{"t":"Pokřik","x":"Začalo to jako omyl, někdo zkomolil vaše jméno na tři slabiky, které se lépe skandují, a teď to devět tisíc lidí unisono opakuje. Brayden to už sestříhal. „Není to vaše jméno, pane. Je to lepší než vaše jméno. Neplánoval jsem to a odmítám se za to omlouvat.“","c":[["Přijměte to. Vytiskněte to na příští šarži čepic.","Zkomolenina se do týdne stane oficiální značkou. Vaše skutečné jméno začne, i vám, připadat trochu formální."],["Jemně je opravte. Je to maličkost.","Zdvořile požádáte o navrácení svého skutečného jména. Pokřik pokračuje stejně, jen hlasitěji, jako by oprava byla výzva."],["Zaregistrujte pokřik jako ochrannou známku dřív, než to udělá někdo jiný.","Tříslabičný zvuk davu se podá u úřadu ochranných známek. Referentka přidělená k případu podle vlastních slov nikdy nezažila divnější úterý."],["Nechte lingvistu v televizi vysvětlit, proč je pokřik technicky vaše jméno.","Profesor fonetiky se objeví s grafy a argumentuje, že zkomolený shluk slabik je etymologicky spojitý s vaším rodným jménem. Není to přesvědčivé. Je to zapamatovatelné."]]},"q-chant-trademark":{"t":"Ochranná známka na pokřik","x":"Sy má špatnou zprávu: někdo si nechal zaregistrovat ochrannou známku na pokřik devět dní před vámi, obchodník se suvenýry ve státě, kde jste nikdy nebyl. „Není to soupeř, pane. Je to cizinec, který byl prostě rychlejší s papírováním než celá exekutiva.“","c":[["Žalujte ho za to. Ukradl slova vašeho davu.","Podá se federální žaloba o navrácení vlastnictví zvuku, který dav vydal spontánně. Soudce si té ironie všimne a písemně ji zaznamená, dvakrát."],["Kupte od něj ochrannou známku. Férová cena, čistý obchod.","Tichý nákup vyřeší věc bez titulku. Cizinec odchází předčasně do důchodu. Je to nejméně dramatické možné řešení a funguje beze zbytku."],["Podejte konkurenční přihlášku a nechte to na právnících na roky.","Dvě přihlášky ochranné známky na stejné tři slabiky vstoupí na roky do administrativního limbu. Pokřik se mezitím zpívá na každém shromáždění, nelicencovaný a nerušený."],["Prohlaste pokřik za veřejné vlastnictví, patřící lidem.","Zřeknete se vlastnictví vlastní přezdívky ve jménu základny, která vám ji dala. Je to, nečekaně, nejmilovanější rozhodnutí vašeho mandátu."]]},"q-rival-chant":{"t":"Soupeřův pokřik","x":"Davy Cordelie Ruiz-Bloomové si vytvořily vlastní pokřik, tři slabiky, posměšný, chytlavý, sestavený tak, aby se rýmoval s vaším. Na kameru popírá, že by ho podporovala, přitom je z toho popírání viditelně nadšená.","c":[["Odpovězte ošklivějším pokřikem o ní. Vypilujte to dnes večer.","Osobně pomůžete vytvořit urážlivý pokřik na politické shromáždění, což je buď pod úroveň úřadu, nebo teď přesně ta úroveň úřadu, podle toho, koho se zeptáte."],["Povyšte se nad to. Nedávejte rýmu důstojnost.","Odmítnete se z pódia zaplést do školáckého žertování. Pokřik na vašich shromážděních do měsíce vyprchá a záhadně přetrvá na jejích."],["Tvrďte, že ukradla formát z vašeho pokřiku.","Obviníte soupeřku z plagiátorství formátu pokřiku, jako by metrum bylo duševní vlastnictví. Profesor lingvistiky je znovu požádán o vyjádření."],["Nechte Braydena naučit váš dav její pokřik, zazpívaný ironicky zpátky na ni.","Devět tisíc vašich vlastních příznivců se naučí a předvede posměšný pokřik vaší soupeřky, ironicky, na vašem vlastním shromáždění. Není jasné, ani jim, kdo z toho vychází vítězně."]]},"q-the-holiday":{"t":"Svátek","x":"Hal Grimes má hlasy na schválení federálního svátku, technicky „na počest výkonné služby“, který připadá, nikoli náhodou, na vaše narozeniny. „Jedenáct členů si myslí, že je to vtip, pane. Dalších jedenáct si myslí, že je to pojistka. Obě skupiny hlasují ano.“","c":[["Prosaďte to. Plná přehlídka, každý rok.","Vznikne státní svátek nesoucí vaše narozeniny a, drobným písmem, vaše jméno. Federální úřady se zavírají. Menšinová zpráva to nazývá „předčasné“, což je nejzdvořilejší dostupné slovo."],["Požádejte Grimese, ať ho pojmenuje po úřadu, ne po vás.","Místo dne na vaši počest projde den na počest „veřejné služby obecně“. Je to malý, záměrný akt zdrženlivosti, na který si vás nikdo nezapamatuje."],["Navrhněte celý týden místo dne.","Navrhne se týdenní oslava, s vlastním logem a slavnostní snídaní. Údaje o federální produktivitě za ten měsíc se stanou, diplomaticky, obtížně čitelnými."],["Nechte základnu hlasovat o oficiálním názvu svátku přes aplikaci.","Otevřená online anketa o pojmenování vašeho vlastního svátku vrátí výsledek, který Brayden odmítá nahlas přečíst před předsedou sněmovny. Přesto se přijme, tiše, v podvýboru."]]},"q-holiday-lawsuit":{"t":"Žaloba kvůli svátku","x":"Předsedkyně nejvyššího soudu Stoneová má naléhavou položku na programu: napadení nového svátku z důvodu odluky církve od státu, s argumentem, že den pojmenovaný po úřadujícím prezidentovi je den pojmenovaný po znovuzvolení úřadujícího prezidenta. „Ten argument není nesmyslný, pane. Přál bych si, aby byl.“","c":[["Nechte své právníky nazvat tu žalobu nevlasteneckou.","Rámujete ústavní otázku jako test loajality. Na shromáždění to zabírá, ve výsledném stanovisku předsedkyně nejvyššího soudu naopak, konkrétně a jmenovitě."],["Nechte to na soudech. Veřejně se nevyjadřujte.","Necháte soudnictví dělat svou práci bez komentáře z pódia. Je to strukturálně přesně to, jak to má fungovat."],["Přejmenujte svátek uprostřed soudního sporu, abyste se argumentu vyhnul.","Svátek se narychlo přejmenuje na „Den úcty k Ústavě“, slavený na vaše narozeniny, čistě náhodou, trvá podání."],["Požádejte Stoneovou, ať vás jen osobně ujistí, že to bude v pořádku.","Neformálně, u kávy, se zeptáte předsedkyně nejvyššího soudu, jak její soud rozhodne. Odloží šálek, neřekne nic, a to ticho je samo o sobě stanovisko."]]},"q-holiday-noncompliance":{"t":"Guvernérka, která svátek ignorovala","x":"Guvernérka Vasquez-Moorová nechala všechny státní úřady o vašem svátku otevřené, ze zásady, v tiskové zprávě nazvané, bez zjevné ironie, „Úterý“. Vaše základna v jejím státě je, podle Nadii, „extrémně, osobně uražena vaším jménem“.","c":[["Vyhrožujte, že jejímu státu zastavíte federální dotace.","Vážete pomoc při katastrofách a peníze na dálnice na dodržování svátku pojmenovaného po vás samém. Je to typ nátlaku, který funguje přesně jednou, než ho někdo zakotví do zákona."],["Nechte úřady otevřené. Je to její stát.","Přijmete, že federalismus občas znamená, že vám někdo smí nesouhlasit, ve váš vlastní den, ve svém vlastním státě. Nestojí vás to nic než uspokojení."],["Uspořádejte shromáždění přímo před jejím zavřeným... otevřeným státním úřadem.","Devět tisíc příznivců skanduje před budovou, kde, trapně, všichni pořád pracují. Několik státních zaměstnanců mává z oken, nerušeně, o polední pauze."],["Pošlete jí ovocný koš „jako gesto jednoty“.","Ovocný koš dorazí do guvernérčiny kanceláře s kartičkou „bez zášti“. Nechá ho vyfotit a věnovat potravinové bance, což nějak vyhraje ten den ve zprávách."]]},"q-go-further":{"t":"Jít dál","x":"Deborah má průzkum k vašemu poslednímu velkému kroku: základna ho milovala a čtyřicet procent z nich se bez vyzvání ptá, co bude dál, v termínech, které předpokládají, že „dál“ znamená „víc“. „Nechtěli tu věc, pane. Chtějí znovu nasytit chuť, kterou v nich ta věc vzbudila.“","c":[["Okamžitě oznamte další, ještě větší krok.","Eskalujete dřív, než se ta poslední eskalace stihne dopsat. Je to, krátce, opojné a naučí to základnu, že strop se pořád posouvá, což se skutečně děje."],["Vydržte. Upevněte to, co už máte.","Odmítnete sytit chuť, která nemá přirozený konec. Je to těžší, tišší, správné rozhodnutí a nikoho v budově neuspokojí."],["Oznamte něco, co zní větší, ale skoro nic nemění.","Dramaticky pojmenovaná iniciativa se skromným skutečným mechanismem vyjde pod triumfálním titulkem. Základna jásá nad titulkem. Mechanismus dělá minimum nutné, aby to byla pravda."],["Zeptejte se základny přímo, na pódiu, co „dál“ vlastně znamená.","Podáte mikrofon davu a požádáte je, ať si sami definují požadavek. Odpovědi, křičené přes sebe, se divoce liší a nic neobjasní. Je to, přinejmenším, upřímné."]]},"q-third-term-chant":{"t":"Pokřik o třetím funkčním období","x":"Začíná to v malém, na jednom shromáždění, v jedné sekci: „čtyři roky navíc“ se neoficiálně protáhne na „a pak ještě něco“. Hal Grimes drží vytištěnou kopii dodatku, který říká, že nemůžete. „Jsem povinen zmínit, že existuje, pane. Nejsem povinen to zmiňovat rád.“","c":[["Nechte pokřik růst. Veřejně uvažujte o „kreativních možnostech“.","Nahlas, na pódiu, uvažujete o třetím funkčním období, které Ústava zakazuje. Grimes stráví následující týden vysvětlováním, čím dál nervóznějším kolegům, že dodatek pořád platí."],["Zastavte to. Sám citujte dodatek.","Osobně ukončíte pokřik pojmenováním zákona, který ho zakazuje. Je to nejzdrženlivější věc řečená na shromáždění za celý rok a ticho poté je samo titulkem."],["Řekněte, že budete „respektovat proces“, s úsměvem, který znamená pravý opak.","Pečlivě zformulované nepopření odvede víc práce než jakákoli skutečná odpověď. Pokřik zesílí přesně proto, že jste ho nezastavil."],["Navrhněte, ať místo vás kandiduje váš viceprezident jako zjevný zástupce.","Nadhodíte plán dosadit loajálního náhradníka a vládnout zpoza opony. Chet Danforth se usměje ještě víc než obvykle, z důvodů, které jsou náhle výhradně jeho vlastní."]]},"q-base-wants-blood":{"t":"Co základna skutečně chce","x":"Bo Slaughter vám čte přepisy z fronty na shromáždění, doslova: většinou ne politické požadavky, ale konkrétní jméno, řečené se skutečným hněvem, a žádost, ať se s tou osobou něco udělá. „Chtějí terč, pane. Ne zákon. Terč.“","c":[["Otevřete vyšetřování proti jmenované osobě. Veřejně.","Federální vyšetřování se otevře, protože dav dostatečně hlasitě skandoval jméno. Bo do spisu poznamená, že „dostatečný veřejný zájem“ tu odvádí ohromné množství právnické práce."],["Vysvětlete, že takhle to nefunguje.","Řeknete devíti tisícům lidí, že ministerstvo spravedlnosti nepřijímá rozkazy od pokřiku. Je to pravda, je to správné a není to to, co přišli slyšet."],["Nechte tu osobu veřejně odsoudit bez formálního obvinění.","Vynesete rétorický rozsudek bez právního, což uspokojí hněv bez papírování. Bo to v jedné větě nazve „extrémně efektivní a extrémně protiústavní“."],["Přesměrujte hněv na firmu s prodejními automaty místo toho.","Uprostřed projevu obrátíte zuřivost devíti tisíc lidí na nesouvisejícího prodejce svačin, bez jasného důvodu. Krátce to funguje a do půlnoci je povalených několik automatů."]]},"q-rv-caravan":{"t":"Karavana obytných vozů","x":"Starosta Faulk má tři tisíce obytných vozů zaparkovaných, neoficiálně, na každém parkovišti u hlavního města, čekajících celé dny předem na vaše příští vystoupení. „Jsou to milí lidé, pane. Taky blokují dvě příjezdové cesty k nemocnici a nedokážu přimět ani jednoho z nich, aby uhnul hasičskému vozu.“","c":[["Veřejně jim poděkujte. Pošlete zdarma dříví na oheň.","Gesto vděku vůči karavaně vůbec neuvolní přístupovou cestu k nemocnici. Vytvoří to ale výborný záběr."],["Nechte městské čety, ať je jemně přemístí na skutečné parkoviště.","Nudná, kompetentní přesunová akce uvolní přístupové cesty bez jediné konfrontace. Nikdo na shromáždění se nikdy nedozví, že se to stalo."],["Prohlaste parkoviště za dočasnou národní památku.","Štěrkové parkoviště plné obytných vozů dostane, na chvíli, federální historický status, aby se obešla místní vyhláška. Cedule se tiše sundá následující úterý."],["Pošlete hasiče na přelet místo zásahu.","Žebříkový vůz se přesměruje na slavnostní přelet nad karavanou místo uvolnění cesty, kterou blokuje. Symbolika je silnější než skutečný přístup k pohotovosti."]]},"q-senate-superfan":{"t":"Superfanouškova kandidatura do Senátu","x":"Cordelia má přihlášku: muž známý hlavně virální cedulí ze shromáždění kandiduje do Senátu a tvrdí, že má vaše doporučení, které jste nikdy nedal. „Nemá žádné zkušenosti a čtyřicet procent povědomí o jménu, úplně vypůjčeného od vás,“ říká, skoro obdivně.","c":[["Podpořte ho doopravdy. Chaos je technicky loajalita.","Formalizujete náhodné doporučení ve skutečné. Muž, jehož celé CV je jedna cedule, teď věrohodně míří do Senátu."],["Veřejně objasněte, že jste ho nikdy nedoporučil.","Uvedete záznam na pravou míru. Přesto kandiduje dál, díky tomu, že si oprava skoro nikdo nepřečetl, a stejně vyhraje primárky."],["Podpořte místo něj jeho protikandidáta, abyste potrestal tu troufalost.","Podpoříte etablovaného kandidáta proti vlastnímu náhodnému fanouškovi, ze vzdoru. Základna to čte jako zradu, ne nápravu."],["Nabídněte mu místo toho práci, abyste ho udržel mimo volební lístek.","Federální titul, vymyšlený pro tuto příležitost, poslouží k úplatku pro senátorského uchazeče, aby odstoupil ze závodu. Přijme to. O pár týdnů později se ukáže, že je v té práci opravdu špatný."]]},"q-purity-test":{"t":"Test čistoty","x":"Frakce základny začala veřejně exkomunikovat další příznivce kvůli jedinému hlasování, které jste odevzdal před lety, dřív, než tohle všechno začalo. Brayden vám ukazuje vlákno. „Ve skutečnosti to není o tom hlasování, pane. Nikdy není. Je to o tom, kdo je ten nejopravdovější fanoušek.“","c":[["Veřejně požehnejte té nejčistší frakci. Ať si zbytek poradí sám.","Vyberete si stranu v hádce o vlastní oddanosti, což je zvláštní věta na papíře a ještě zvláštnější nahlas, a přesto ji řeknete."],["Zavolejte k jednotě. Odmítněte řadit něčí loajalitu.","Odmítnete rozhodovat soutěž o čistotu mezi vlastními příznivci. Je to skutečně to zdravější rozhodnutí a neuspokojí naprosto nikoho ve vlákně."],["Tiše financujte newsletter té hlasitější frakce.","Skromný, nevystopovatelný převod udrží nejhlasitější hlasy nejhlasitější. Vnitřní spory zesílí, což, jak Brayden poznamenává, aspoň udrží všechny v řeči o vás."],["Pozvěte obě frakce na společný piknik s grilem a natočte to.","Televizní grilovačka, myšlená jako smíření dvou znepřátelených táborů fanoušků, místo toho vyprodukuje nejcitovanější hádku o bramborovém salátu v dějinách kabelové televize."]]},"q-heat-stroke":{"t":"Varování před vedrem","x":"Dr. Prine má čísla z posledního shromáždění pod širým nebem: čtyřicet jedna zásahů kvůli přehřátí, jeden vážný, v den, který meteorologická služba dopředu s dostatečným předstihem označila jako nebezpečný. „Stáli v tom slunci kvůli vám šest hodin, pane. Někteří to udělají znovu příští týden, když je o to požádáte.“","c":[["Naplánujte příští na vrchol odpoledne. Větší dav, lepší světlo.","Zvolíte nejtvrdší hodinu kvůli nejlepší fotce. Zdravotnický stan má rušno a zůstává úplně mimo záběr."],["Přesuňte příští shromáždění na večer. Přidejte stanoviště s vodou.","Skutečně rozumná změna harmonogramu a pár palet lahvové vody zabrání dalším čtyřiceti jedna zásahům. Je to neviditelné, levné a správné."],["Obviňte místo konání z nedostatku stínu.","Viníte stadion místo harmonogramu. Vedení stadionu, oslovené k vyjádření, poukáže, že nabídli večerní termín, který jste odmítli."],["Nechte Dr. Prinea osobně hydratovat první řadu na kameru.","Prezidentův lékař tráví shromáždění rozdáváním vody první řadě místo dohledu na zdravotnický stan za sebou. Později to popíše jako „ne můj nejlepší třídicí výkon“."]]},"q-wax-figure":{"t":"Voskový model","x":"Dr. Weirová vám s viditelnou neochotou oznamuje, že voskové muzeum odhalilo vaši figurínu uprostřed shromáždění, pěst zdviženou, výraz někde mezi triumfem a mírným leknutím. „Nevypadá to úplně jako vy, pane. Vypadá to, jak si lidé myslí, že vypadáte. To je zcela jiná věc.“","c":[["Požadujte předělání. Větší pěst, lepší čelist.","Voskovou figurínu na prezidentskou žádost přetvoří tak, aby byla hrdinnější a méně přesná. Muzeum si potichu poznamená, že jde o první takovou žádost v jeho historii."],["Nechte to být. Nestojí to za tu hádku.","Odmítnete se soudit o přesnosti čelisti voskové figuríny. Zůstane, mírně nepřesná, navždy, což je víc důstojnosti, než dostane většina soch."],["Kupte muzeum. Přidejte celé nové křídlo.","Voskové muzeum se potichu stane součástí osobního nemovitostního portfolia, s celým novým křídlem věnovaným vašim největším hitům, voskovým i jiným."],["Pošlete pro figurínu vlastní šaty.","Skutečný oblek z vaší vlastní skříně se pošle, aby oblékl voskovou repliku. Čistírna, která ho normálně obstarává, tentokrát odmítne vysvětlit proč."]]},"q-fireworks-budget":{"t":"Rozpočtová položka na ohňostroj","x":"Roscoe Vandermeer našel rozpočet na ohňostroj ke shromáždění zahrabaný o tři řádky hluboko v účtu vnitřní bezpečnosti. „Není to nezákonné, pane, technicky. Je to jen vedené pod „odolností kritické infrastruktury“, k čemuž mám otázky.“","c":[["Nechte to zahrabané. Zdvojnásobte příští měsíc podívanou.","Ohňostroj zůstává financovaný pod nadpisem, který s ohňostrojem nemá nic společného, a příští měsíční finále je, nepopiratelně, větší."],["Přesuňte to na vlastní, poctivou rozpočtovou položku.","Ohňostroj dostane vlastní, transparentní rozpočtovou kategorii, za skutečnou politickou cenu, protože někdo musí jednou nahlas vyslovit slovo „ohňostroj“ při slyšení."],["Přeznačte to na „morální infrastrukturu“ místo toho. Zní to čistěji.","Nový eufemismus nahradí starý. Roscoe, věčný muž efektivity, přizná, že je to aspoň poctivější druh nepoctivosti."],["Nechte BROOM ohňostroj otevřeně sponzorovat, jako ukázku úspor.","Agentura pro efektivitu veřejně sponzoruje výbušnou pyrotechnickou show jako příklad „chytrého utrácení“. Matematika za touto větou nikdy pořádně nedorazí."]]},"r-ag-my-lawyer":{"t":"Osobní zástupce","x":"Bo se zastaví s koordinační memorandem, o které jste nežádali: vše, co se týká vás osobně, teď jde nejdřív přes jeho kancelář. Je ministrem spravedlnosti Spojených států. Chtěl by, aby bylo zaznamenáno, že si toho rozdílu všiml, i když momentálně není v pozici na něm trvat.","c":[["Udělejte to oficiální. Spravedlnost slouží nejdřív prezidentovi.","Pracovní předpoklady ministerstva projdou tichou úpravou: „Spojené státy“ teď v praxi znamenají konkrétně vás. Kariérní právníci si začínají datovat výpovědi."],["Poděkujte mu. Udržte hradbu mezi vámi a budovou.","Odmítnete nabídku zajatého ministerstva spravedlnosti. Bo vypadá skoro zklamaně, pak úlevně, a vrátí se k tomu, být právníkem pro zemi místo pro vás."],["Požádejte ho, ať vás zahrne do svého oficiálního portrétu.","Oficiální ministerský portrét ministra spravedlnosti vás zahrnuje v pozadí, jak souhlasně gestikulujete k pořadači. Je to hluboce podivné a nikdo ho nesundá."],["Najměte Syho také. Nechte je bojovat o ten mandát.","Dva právníci, jeden klient, nulová jasnost, kdo zastupuje úřad a kdo vás. Fakturují zvlášť a na ničem se neshodnou, což je nějak nejupřímnější uspořádání v celé budově."]]},"r-enemies-list":{"t":"Hlavní seznam","x":"Deborah přes stůl posune tabulku, o kterou nikdo nežádal: jména, sloupec „vyšetřit“, sloupec „auditovat“ a jeden, nepopsaný, který jen říká „později“. Sestavila ji, protože jste pořád zmiňoval jména a ona se unavila zapisováním na ubrousky.","c":[["Formalizujte to. Stálý útvar bude na seznamu pracovat.","Vznikne útvar s tak byrokratickým názvem, že si nikdo nevšimne, co dělá: porovnávat veřejné kritiky proti každé federální databázi s vaším jménem ve vyhledávacím poli."],["Tabulku spalte. Stíhejte podle skutkové podstaty, nebo vůbec.","Deborah před vámi smaže soubor, což je buď integrita, nebo divadlo, a nikdy se nedozvíte, které, protože to funguje tak jako tak."],["Přidejte další tři jména. Seřaďte to abecedně.","Seznam roste a je uspořádanější, což ho nějak činí děsivějším než ty původní ubrousky."],["Dejte vlastní jméno navrch, jako vtip.","Nikdo se nezasměje. Stážista otevře skutečné šetření dřív, než ho stihnou tiše zastavit. Vtip přežije přesně jedno odpoledne."]]},"r-rival-probe":{"t":"Vyšetřování začíná","x":"Guvernérka Vasquez-Moorová vás ve svém státě porazila o devět bodů a od té doby je kvůli tomu nesnesitelná. Bo našel nesrovnalost v zadávání zakázek starou čtyři roky, malou, technickou, skutečnou. „Je to tenké, pane. Je to ale taky právně dostatečné, což je v této práci jediná laťka, na které záleží.“","c":[["Otevřete to. Oznamte to sám, z pódia.","Úřadující guvernérka se ocitne pod „vyšetřováním“ v každém titulku, který se počítá, bez ohledu na to, co vyšetřování nakonec zjistí. Kolem druhého týdne přestane na zjištění záležet."],["Nechte kariérní žalobce rozhodnout, potichu, podle skutkové podstaty.","Nesrovnalost dostane nevýraznou kontrolu, jakou by dostala, kdybyste o ní nikdy neslyšel. Nikam to nevede, jak to tenké věci dělají."],["Otevřete vyšetřování proti všem šesti opozičním guvernérům najednou.","Šest sond, šest pódií, šest téměř identických poznámek o zadávání zakázek povýšených na skandál. Vzorec je tak zjevný, že vás i vaši vlastní právníci žádají, abyste to přestal nahlas popisovat."],["Nabídněte jí místo v kabinetu místo toho. Zjistěte, jestli to přijme.","Odmítne, v prohlášení, ve kterém vám děkuje za „lichotivý pokus o zadržení“. Strávíte zpravodajský cyklus vysvětlováním pracovní nabídky, které nikdo nevěří jako upřímné."]]},"r-charging-meeting":{"t":"Schůzka o obvinění","x":"Kariérní žalobci se dnes odpoledne scházejí, aby čistě podle faktů rozhodli, zda obvinit rozhlasového moderátora, který vás měsíc zesměšňoval. Bo mimochodem zmíní, že se klidně můžete zúčastnit. Žádný prezident to nikdy nepotřeboval žádat, což není totéž jako mu to zakázat.","c":[["Zúčastněte se. Neříkejte nic. Ať za vás mluví vaše přítomnost.","Sedíte v místnosti, kde mají kariérní žalobci sami rozhodnout, zda fakta odůvodňují obvinění. Nikdo vás nepožádá, abyste odešel. Všichni si všimnou, že jste zůstal."],["Zůstaňte úplně mimo. Ať rozhodnou bez vás v budově.","Necháte schůzku proběhnout tak, jak mají schůzky o obvinění probíhat: bez vás v místnosti, budově nebo rozhodnutí. Je to neviditelné, což je smysl toho, aby to fungovalo."],["Zúčastněte se a položte přímou otázku o obviněních.","Nahlas se zeptáte, jestli by obvinění mohla být „silnější“. Tři kariérní žalobci si sepíšou dobové záznamy o té výměně dřív, než schůzka vůbec skončí."],["Zúčastněte se, pak se v polovině hlasitě vzdejte účasti na rozhodování.","Uprostřed schůzky oznámíte vlastní vyloučení se z rozhodování, do záznamu, poté co jste už slyšel polovinu diskuze. Je to divadelně korektní a věcně bezvýznamné, a všichni ten rozdíl poznají."]]},"r-predecessor-probe":{"t":"Předchozí administrativa","x":"Bo sestavil předběžný přehled posledních měsíců vašeho předchůdce v úřadu: nic trestného, většinou obyčejná koncová administrativa. Pokud chcete, může pokračovat v hledání, dokud se „nic trestného“ nestane něčím jiným.","c":[["Pokračujte v hledání. Vyhlaste formální šetření.","Formální šetření proti vašemu předchůdci se vyhlásí bez jakéhokoli podezření z trestného činu, což se stane příběhem, hned následováno příběhem o tom příběhu."],["Ukončete přezkum. Nic tam není a všichni to vědí.","Odmítnete vymyslet zločin pro muže, kterého jste porazili férovým způsobem, což je buď velkorysost, nebo nedostatek fantazie, a tak jako tak to věc ukončí."],["Vyhlaste šetření a předvolejte jeho osobní deník.","Předvolání osobního deníku bývalého prezidenta se vydá, napadne u soudu a nakonec stáhne, aniž by to přineslo cokoli kromě skvělé kapitoly do jeho pamětí."],["Pozvěte ho místo toho na oběd. Zeptejte se ho u dezertu, jestli něco udělal.","Řekne ne, nad sdíleným dezertem, tónem, který rozhovor definitivně ukončí. Věříte mu, což překvapí přesně jednoho člověka u stolu: vás."]]},"r-preemptive-pardon":{"t":"Plošná milost před výpovědí","x":"Tři zaměstnanci jsou předvoláni svědčit příští měsíc o věcech, které Sy nazývá „přiléhavé k věcem, které byste raději neměl přiléhavé“. Milost za dosud neobviněné trestné činy je právně neprověřená. Přesto ji připravil, pro případ, že by se neprověřenost stala módní.","c":[["Podepište všem třem. Cokoli, jmenovitě i obecně.","Tři zaměstnanci vejdou do slyšecí místnosti imunní vůči zločinu, který nikdo zatím neprokázal. Dva se stejně, ze zvyku, odvolávají na pátý dodatek, a ten rozpor je celý zpravodajský den."],["Žádné milosti. Ať svědčí a odpovídají za sebe.","Tři zaměstnanci svědčí jako občané pod předvoláním, protože přesně to jsou. Je to nevýrazné a taky, strukturálně, přesně jak to má fungovat."],["Udělte jim milost veřejně, s ceremonií, před slyšením.","Slavnostní podpis se vysílá ráno v den slyšení. Senátoři, kteří kladou otázky, mají teď záznam, jak byla odpověď koupena dopředu."],["Udělte milost jen tomu, kdo vás nejmíň otravuje.","Milost udělená podle osobní sympatie, ne právní expozice. Dva neomilostnění zaměstnanci si nezávisle na sobě začnou najímat právníky, kteří neodpovídají Symu."]]},"r-special-counsel":{"t":"Nezávislý žalobce","x":"Externí žalobkyně s desetiletou pravomocí předvolávat a bez šéfa kromě zákona se jedenáct měsíců zabývala vaším prvním funkčním obdobím a, jak Bo hlásí, „našla přesně ten druh věci, co si najde vás“. Nic ve statutu vám nebrání ji odvolat. Jen to, co následuje, ano.","c":[["Odvolejte ji dnes večer. Uveďte rozpočtové důvody.","Žalobkyni vyšetřující vás odvoláváte vy, z důvodů, které neuspokojí nikoho, kdo čte dál než první větu. Dva zástupci podají výpověď ve stejné odpoledne, písemně, s uvedenými důvody."],["Nechte to běžet. Spolupracujte, dodejte dokumenty, mlčte.","Vyšetřování skončí podle vlastního harmonogramu a víceméně vás zbaví toho nejhoršího. Nikdo si to nepamatuje, protože se nic nestalo, což byl celý smysl toho, nechat to doběhnout."],["Odvolejte ji a nahraďte ji někým, kdo se hlásí Bovi.","Náhradník je nezávislý jen podle jména, což je fráze, která nikdy nepřežila kontakt s předvoláním. Nedokončené spisy staré kanceláře se při přesunu ztratí."],["Pozvěte ji na „konstruktivní“ večeři do rezidence.","Přijde, sní rybu a do pátku předvolá seznam hostů od cateringu. Večeře je pak citována, doslova, v poznámce pod čarou."]]},"r-fbi-loyalty-dinner":{"t":"Pozvání na večeři","x":"Deborah to sděluje věcně: měl jste soukromou večeři s ředitelem úřadu a víc než jednou jste se ho zeptal, jestli se můžete spolehnout na jeho loajalitu. Odpověděl místo toho o poctivosti. Od té doby vy tu výměnu popisujete lidem jako slib.","c":[["Veřejně opakujte rámování „loajality“. Donuťte ho to popřít.","Opraví záznam před kamerami, což čtenářům, na kterých vám záleží, zní jako neposlušnost s dodatečnými kroky navíc."],["Nikdy o té večeři nemluvte znovu.","Necháte trapnou večeři zůstat trapnou večeří. Úřad dál dělá svou práci bez testu loajality, což je celý smysl toho uspořádání."],["Požádejte o ten slib znovu, tentokrát písemně.","Písemná žádost o osobní loajalitu ředitele národní policejní agentury přistane na jeho stole. Nepodepíše to. Přesto si to nechá."],["Pošlete mu místo toho ovocný koš. Bez lístku.","Neoznačený, nevysvětlený ovocný koš dorazí do sídla úřadu. Zaevidují ho jako důkaz v ničem, probírá se v každé chodbě a do středy je snědený."]]},"r-effigy-charge":{"t":"Zákon o urážce","x":"Bo našel skutečný zákon, zaprášený, který kriminalizuje „urážku nebo hanobení“ federálních úředníků při výkonu funkce. Nebyl použit devadesát let a byl napsán pro jiné století. Šest protestujících spálilo vaši figurínu před shromážděním. Zákon, na rozdíl od toho století, je technicky pořád v platnosti.","c":[["Obviňte je. Veřejně oživte ten zákon.","Šest lidí je obviněno podle zákona naposledy použitého proti muži, který v 30. letech hodil rajče po guvernérovi. Jejich právník požádá o porotu lidí, kteří taky spálili něco v podobizně, a dostane ji."],["Nechte to být. Figuríny jsou chráněný projev, jakkoli nevkusný.","Necháte zaprášený zákon přesně tam, kde ho našli: nepoužitý. Svoboda projevu přežije kontakt s vašimi pocity, znovu."],["Obviňte je a přidejte druhý incident z minulého roku.","Přidá se druhý případ, za jednání spáchané dřív, než někoho napadlo ho obvinit, na právní teorii, ze které i Bo trne, když ji podává."],["Požádejte o hezčí figurínu příště. Poznámky ke zpracování.","Prezidentské prohlášení kritizuje konstrukční pevnost figuríny spálené na protest proti němu. Cech tvůrců figurín, o jehož existenci se dozvěděl teprve teď, bere poznámku vážně."]]},"r-disbar-opposing-counsel":{"t":"Stížnost advokátní komoře","x":"Advokátní kancelář proti vám vyhrála tři soudní zákazy. Sy má úhel: stížnost advokátní komoře tvrdící, že veřejná vyjádření kanceláře k případu porušují etický kodex, podaná „znepokojeným občanem“, který náhodou pracuje dva domy od jeho vlastní kanceláře.","c":[["Podejte stížnost. Zaneprázdněte jim kalendář na rok.","Kancelář stráví rok obhajobou vlastní licence místo vašeho dalšího případu, což byla, zjevně, celá strategie. Stížnost je zamítnuta v jedenáctém měsíci."],["Nepodávejte to. Porazte je radši v samotné věci.","Necháte právníky být právníky a snažíte se vyhrát skutečný případ. Je to těžší cesta a mnohem čistší se pak obhajuje."],["Podejte stížnosti proti každému právníkovi, který podklad podepsal.","Devět jmen na jednom podání se stane devíti oddělenými stížnostmi komoře, podanými téhož odpoledne stejným „znepokojeným občanem“, který na sebe začíná strhávat víc pozornosti než samotný případ."],["Pošlete kanceláři ovocný koš a nechte ten nápad být.","Smířlivý ovocný koš dorazí do kanceláře, která vás porazila třikrát za sebou. Opatrně ho snědí a příští týden i tak vyhrají čtvrtý soudní zákaz."]]},"r-self-pardon":{"t":"Otázka, na kterou nikdo neodpovídá","x":"Sy sepsal memorandum, dvacet dva stran, o tom, zda si prezident může udělit milost sám sobě. Jeho závěr, po dvaceti dvou stranách, je, že to vlastně nikdo neví, protože nikdo nebyl nikdy tak pošetilý, aby k tomu donutil rozhodnout Nejvyšší soud.","c":[["Podepište to. Buďte testovacím případem.","Udělíte milost sám sobě, za zločin, který se papír zdráhá upřesnit, a předáte Nejvyššímu soudu otázku, které se dvě století vyhýbal. Za tu čest vám nepoděkuje."],["Nepodepisujte to. Některé otázky je lepší nechat nezodpovězené.","Necháte ústavní šedou zónu šedou, ze zásady, což je zvláštnější důvod k hrdosti, než zní, a přesto na to potichu hrdý jste."],["Ať vás omilostní viceprezident, pak ho zase vraťte do funkce rezignací.","Dvacetiminutová výměna úřadů vyprodukuje milost, která je právně čistší a morálně identická. Chet to udělá s úsměvem, což to nějak zhoršuje."],["Požádejte Bo, ať vám udělí milost. Ať za to nese vinu on.","Ministr spravedlnosti tu pravomoc nemá a oba to víte. Zdvořile odmítne, v memorandu, které se přečte nahlas na jeho příštím slyšení k potvrzení funkce."]]},"r-witness-immunity":{"t":"Dohoda o imunitě","x":"Bo má spolupracujícího svědka ochotného svědčit proti soupeřícímu senátorovi; cena je plná imunita za svědkovo vlastní, podstatně horší, jednání. Je to standardní nástroj, používaný neustále, a nikdy dřív nepůsobil tak transakčně.","c":[["Udělte plnou imunitu. Dostaňte tu výpověď do záznamu.","Muž, který spáchal horší věci než senátor, proti němuž svědčí, odejde čistý výměnou za slova, která možná neobstojí při křížovém výslechu. Ministerstvo tomu říká obchod. Je to obchod."],["Odmítněte dohodu. Postavte případ na vlastních důkazech.","Případ postupuje pomaleji, na papírech a forenzních důkazech místo výpovědi koupené čistým štítem. Je to případ, který je těžší vyhrát a snazší navždy obhájit u odvolání."],["Udělte imunitu a nechte svědka vybrat formát pohovoru.","Hlavní svědek si vyjedná rozhovor se scénickým osvětlením ještě dřív, než dokončí výpověď. Senátorovi právníci to slovo od slova použijí při křížovém výslechu."],["Nabídněte soupeřícímu senátorovi stejnou dohodu, preventivně, ze vzdoru.","Senátor pod vyšetřováním dostane nevyžádanou nabídku imunity za zločin, z něhož nebyl obviněn a, pokud je komu známo, ani ho nespáchal. Dopis si zarámuje."]]},"r-irs-audit-critic":{"t":"Značka pro kontrolu","x":"Lyle si všimne vzorce dřív než kdokoli jiný: každý komentátor, který vás minulé čtvrtletí kritizoval v éteru, byl, náhodou, označen pro „běžnou“ daňovou kontrolu. Je si docela jistý, že to není náhoda, protože on je ten, kdo ty značky vidí.","c":[["Pokračujte v seznamu. Přidejte jména z tohoto týdne.","Kontroly probíhají podle plánu, tedy podle vašeho plánu, a vzorec se dostane na veřejnost tak, jak se vzorce vždycky dostávají: stážista to zveřejní."],["Nařiďte, ať značky prověří nezávislý útvar.","Tichá interní revize odstraní značky bez podkladu. Proběhne to bez tiskovky, protože tisková konference by vyžadovala vysvětlit, proč tam vůbec byly."],["Popřete, že vzorec existuje. Pak přidejte další dvě jména.","Popřete vzorec a zároveň ho ve stejném zpravodajském cyklu, do záznamu, rozšíříte. Mladá novinářka sestaví tabulku, která přežije váš mandát."],["Nechte auditovat i sebe, pro rovnováhu. Zveřejněte to.","Vaše vlastní přiznání projde stejnou „běžnou“ kontrolou. Trvá to čtyři roky, nenajde nic průkazného a stane se nejnudnější větou celého vyšetřování."]]},"r-subpoena-reporter":{"t":"Novinářčiny záznamy","x":"Kaylee vás zastaví před pódiem. Vyšel příběh se zdrojem uvnitř ministerstva a Bo chce předvolání telefonních záznamů reportérky, vydané potichu, dřív, než se to redakce dozví. To ona bude zítra odpovídat za následky, ne vy.","c":[["Schvalte to. Potichu. Bez upozornění redakce.","Záznamy se získají bez varování a když to vyjde najevo, jak se to vždycky stane, vyjde to najevo jako příběh, natrvalo přilepený k tomu, který měl zakrýt."],["Vyžadujte předchozí upozornění a soudní souhlas, jak velí postup.","Postupujete přesně podle procesu vytvořeného, aby přesně tomuhle druhu předvolání zabránil. Je to pomalejší a správné, a únik se nikdy nenajde, což je cena, kterou přijímáte."],["Předvolejte záznamy celé redakce, pro jistotu.","Komunikace celé redakce se stáhne jedním úkonem. Šest nesouvisejících příběhů, žádný o vás, je vedlejší škodou, a redakce stejně otiskne všech šest."],["Zveřejněte vlastní verzi příběhu první.","Předběhnete příběh únikem přátelštější verze stejných faktů. Funguje to na jeden zpravodajský cyklus a potvrdí to původnímu zdroji, že únik k vám taky funguje."]]},"r-grand-jury-leak":{"t":"Utajená věc","x":"Errol Hance oficiálně nevede vyšetřování úniků. Ale když se detaily z utajeného řízení velké poroty týkajícího se soupeřícího senátora dostanou ke spřátelenému médiu dva dny před hlasováním o jeho jmenování, je to on, kdo má prostředky zjistit, kdo to udělal, a zdrženlivost neptát se moc, proč to chcete vědět dřív než on.","c":[["Nechte příběh vyjít. Nevyšetřujte to moc usilovně.","Utajené řízení se dostane na veřejnost přesně ve chvíli, kdy je to nejškodlivější a nejméně odpovědné. Senátor prohraje hlasování. Vyšetřování úniku, pozoruhodně, nenajde nic."],["Nařiďte skutečné vyšetřování úniku. Zveřejněte, kdo to udělal.","Únik se vystopuje k mladšímu asistentovi, který je propuštěn a, neobvykle, opravdu byl tím, kdo unikl. Malý, správný výsledek v systému, který je vytváří jen zřídka."],["Osobně potvrďte unikáté detaily, „pro kontext“.","Přidáte oficiální potvrzení k neoficiálnímu úniku, čímž zavřete jednu mezeru, která by vám dřív mohla umožnit popřít účast. Sy se, ne poprvé, ptá, proč to pořád děláte."],["Utajte i vyšetřování úniku. Zkuste, jaké to je.","Vyšetřování úniku z utajeného řízení je samo utajeno, což je buď poetické, nebo chyba v papírování. Nikdo v budově to nedokáže s jistotou říct."]]},"r-us-attorney-fired":{"t":"Prokurátorka, která řekla ne","x":"Kariérní federální prokurátorka písemně odmítla vznést obvinění proti starostovi, kterého nemáte rád, s odvoláním na „absenci důkazů“ v memorandu, které, Bo přiznává, není nesprávné. Ve funkci vydržela dvě administrativy. Jste první, kdo ji o tohle požádal.","c":[["Propusťte ji ještě dnes. Oznamte náhradu do večeře.","Prokurátorka s dvaadvaceti lety praxe je odvolána za to, že odmítla vyrobit případ, a její nástupce složí přísahu dřív, než příběh přestane trendovat. Přinese obvinění do měsíce."],["Přijměte její úsudek. Případ skutečně neexistuje.","Necháte prokurátorku být prokurátorkou, což znamená nechat absenci důkazů ukončit rozhovor. Je to celá práce, fungující správně, a nikdo si toho nevšimne."],["Propusťte ji a otevřete i etické šetření proti ní.","Etické šetření proti prokurátorce, která odmítla vznést bezdůvodné obvinění, je, i podle nedávných standardů tohoto ministerstva, bezdůvodné samo o sobě, což tři nezávislí přezkoumávající písemně poznamenají, než ho tiše zastaví."],["Pošlete jí jako omluvu nesouvisející spis.","Smířlivý, nevyžádaný spisový materiál dorazí do její kanceláře den po propuštění. Přepošle ho generálnímu inspektorovi s dvouslovnou poznámkou: „k prošetření“."]]},"r-election-worker-target":{"t":"Ta, co svědčila","x":"Jedna volební dozorkyně pod přísahou vypověděla, že osobně přepočítala hlasy, které jste označil za podvodné, a nenašla nic. Bo má úhel: obvinění z křivé přísahy, postavené na technikalitě ve formulaci její výpovědi, které by ji stálo rok a vlastní úspory, aby ho u soudu porazila, ať už vyhraje nebo prohraje.","c":[["Podejte na ni obvinění z křivé přísahy. Nechte technikalitu udělat svou práci.","Žena, která pod přísahou vypověděla přesně to, co se stalo, stráví rok a čtyřicet tisíc dolarů dokazováním, že měla pravdu. Vyhraje. Ta výhra ji stejně stojí práci, protože nikdo nechce zaměstnat střed federálního případu."],["Nechte to být. Její výpověď odpovídala přepočtu.","Necháte přesnou svědkyni být přesnou svědkyní. Je to celý smysl přísahy, fungující tak, jak má, a nestojí vás to nic kromě uspokojení z toho, že ji nepotrestáte za to, že měla pravdu."],["Podejte obvinění na ni a na tři další úředníky, kteří s ní souhlasili.","Čtyři volební úředníci ve čtyřech různých okresech dostanou obvinění během týdne, jejich jediným společným rysem je, že přepočet v každém případě odpovídal jejich matematice, ne té vaší."],["Pošlete jí místo toho formální děkovný dopis.","Dopis děkující volební pracovnici za přesnost, podepsaný vámi, ji tak zmate, že zavolá novinářce, jen aby si ho nechala nahlas přečíst, nejistá, jestli je opravdový."]]},"r-sanctuary-funding":{"t":"Dopis o financování","x":"Duane má seznam měst, která odmítají zadržovat lidi pro federální převzetí po termínu propuštění, a návrh dopisu, který jim od tohoto fiskálního čtvrtletí sníží federální dotace na vymáhání práva na nulu.","c":[["Pošlete dopis. Nulové financování, bez postupného snížení.","Policejní sbory v devíti městech přijdou o dotace, které platí za vesty a vysílačky, jež s tímhle nemají vůbec nic společného. Starostové do týdne uspořádají společnou tiskovou konferenci."],["Vázejte financování na užší, obhajitelný standard spolupráce.","Standard napsaný tak, aby přežil u soudu, ne na shromáždění, což znamená, že je nudný, legální a většinou ho ignoruje každý, kdo není právník, což byl záměr."],["Snižte financování a veřejně seřaďte města podle „vzdoru“.","Žebříček amerických měst seřazených podle ochoty spolupracovat osobně s vámi. Čtyři starostové dají svůj žebříčkový výsledek na hrnek na kávu a vyprodají ho za den."],["Nabídněte peníze zpátky, pokud město po vás pojmenuje park.","Jedno město tu nabídku přijme. Park je pruh trávníku se dvěma lavičkami a hydrantem. Osobně se zúčastníte slavnostního přestřižení pásky a nazvete to „historickým“."]]},"r-material-witness":{"t":"Klíčový svědek","x":"Zákon existuje proto, aby na krátkou dobu zadržel někoho, jehož svědectví by s ním mohlo zmizet. Duane našel jeho použití, které nemá se svědectvím nic společného: zadržet trvalou kritičku jako „klíčovou svědkyni“ v případu, který se, výhodně, nikdy tak úplně nedostane k bodu, kdy by ji z čehokoli obvinil.","c":[["Použijte to. Zadržte ji jako svědkyni. Obvinění netřeba.","Žena stráví jedenáct dní ve federální vazbě jako „klíčová svědkyně“ případu, který nikdy nebude podán. Zákon to technicky dovoluje. Nikdo zúčastněný na tom nepůsobí hrdě."],["Předvolejte ji normálně ke svědectví. Bez zadržení.","Dostane běžné předvolání, odpoví na ně a odejde domů týž den. Je to nudná verze nástroje, fungujícího přesně tak, jak byl navržen."],["Zadržte ji a další tři spolupracovníky, „kvůli konzistenci“.","Čtyři lidé jsou zadrženi jako svědci případu, který nejmenuje nikoho z nich, kvůli svědectví, o které nikdo z nich nikdy ve skutečnosti nepožádá."],["Propusťte ji s osobní omluvou, nepodepsanou.","Anonymní omluvný lístek dorazí s jejími osobními věcmi při propuštění. Nechá si ho ověřit grafologem během týdne, čistě ze vzdoru, a vyhraje."]]},"r-mayor-warrant":{"t":"Zatykač na starostu","x":"Bo má federální zatykač za pohrdání soudem na úřadujícího starostu, který nařídil své policii nespolupracovat s federální operací. Doručení potřebuje maršály. Mick Tarrant nabídl podporu Národní gardy „kvůli bezpečnosti“, o kterou nikdo nežádal a která výrazně mění fotku.","c":[["Doručte to veřejně. Včetně podpory Národní gardy.","Úřadující starosta je na kameru odveden z vlastní radnice, gardisté viditelní v záběru za federálními maršály. Je to nejsledovanějších pět minut místních zpráv v historii stanice."],["Doručte to potichu, jen maršály, bez kamer, bez gardy.","Zatykač se doručí tak, jak se zatykače doručovat mají: bez okázalosti. Je zpracován, propuštěn na vlastní slib hodinu poté a případ pokračuje jako kterýkoli jiný."],["Doručte to na jeho vlastní kampani znovuzvolení.","Maršálové dorazí uprostřed jeho věty na vlastním kampaňovém startu. Video, ze šesti úhlů, se stane skutečným startem jeho kampaně, do večeře o několik bodů napřed v průzkumech."],["Nechte ho přijít se udat sám, podle jeho vlastního harmonogramu.","Přijde na vlastní podmínky, v úterý, v obleku místo v poutech. Popírá to všem fotku, kterou chtěli, včetně, jak si o chvíli později uvědomíte, vás."]]},"r-bail-crackdown":{"t":"Nařízení o kauci","x":"Bo má připravenou směrnici nařizující federálním žalobcům žádat maximální vazbu před soudem u každého případu, který se dotýká protestu, bez ohledu na povahu obvinění, veřejně rámovanou jako zákon a pořádek a soukromě jako způsob, jak udržet lidi mimo ulici, dokud neopadne zpravodajský cyklus.","c":[["Vydejte směrnici. Maximální vazba, bez výjimek.","Lidé obvinění z přecházení mimo přechod poblíž protestu sedí týdny ve federální vazbě, než dostanou slyšení, což je, funkčně, i když ne právně, samotný trest."],["Nařiďte žalobcům žádat vazbu jen tam, kde to odpovídá faktům.","Požádáte, aby se běžný standard uplatňoval běžně. Žádosti o vazbu klesnou zhruba na úroveň, na jaké byly, než je někdo napadl zneužít, což je celý smysl standardu."],["Vydejte to a přidejte odměnu žalobcům, kteří splní kvótu.","Kvóta na počet předsoudních vazeb, spojená s bonusem, promění řádný proces v úkolovou mzdu. Dva žalobci raději odejdou, než by takhle sázeli vlastní svědomí."],["Zaplaťte kauci sám za prvních deset zatčených.","Zaplatíte kauci, z vlastní kapsy, za deset cizích lidí zatčených poblíž protestu proti vám. Je to nevysvětlitelné, široce zesměšňované a jediná nejmilejší věc, kterou za celý mandát uděláte."]]},"r-martial-law-lite":{"t":"Město pod zákazem vycházení","x":"Po třech nocích nepokojů v centru má Duane připravený příkaz zavádějící celoměstský zákaz vycházení, kontrolní stanoviště na hlavních silnicích a federální úředníky s pravomocí zadržovat porušitele bez obvyklého papírování. Nazývá to „dočasné“. Neříká, na jak dlouho.","c":[["Podepište to. Plný zákaz vycházení, kontrolní stanoviště, urychlené zadržení.","Město funguje jedenáct dní pod federální kontrolou. Funguje to, v úzkém smyslu, že nepokoje ustanou, a stojí to, v každém širším smyslu, pocit, že je to pořád ta samá země, jakou byla před dvěma týdny."],["Podpořte místní policii zdroji. Žádný zákaz vycházení, žádné kontroly.","Necháte vlastní městskou vládu řešit vlastní nepokoje, s federální podporou místo federálního velení. Vyřeší se to pomaleji, jako problém města, ne jako ústavní otázka."],["Podepište to a rozšiřte to na předměstí „kvůli konzistenci“.","Zákaz vycházení se rozšíří na tři předměstí, kde nebyly žádné nepokoje, kvůli přehledné mapě. Půl milionu lidí, kteří nic neudělali, se přes textovou zprávu dozví, že teď mají zavírací dobu."],["Zrušte zákaz vycházení přesně o půlnoci, „jako gesto“.","Zákaz vycházení, který skončí přesně v hodinu, kdy zákazy vycházení tradičně začínají, se setká se zmatkem, který si zaslouží. Nikdo nepozná, jestli to byla chyba nebo poselství, ani Duane si tím soukromě není jistý."]]},"r-unmarked-agents":{"t":"Neoznačené dodávky","x":"Duane má federální úředníky v neoznačených vozidlech a obecné taktické výstroji, odvádějící lidi z městské ulice do neoznačených dodávek, bez místní koordinace, bez viditelných čísel odznaků. Vše je technicky v rámci jeho pravomoci. Nic z toho není vyžadováno.","c":[["Nechte je tam. Rozšiřte to o další dva bloky.","Záznam neoznačených agentů odvádějících lidi z veřejného chodníku běží do večeře všude. Zhruba polovině země to připadá přesně jako smysl celé akce."],["Stáhněte je. Koordinujte s místní policií, viditelné odznaky.","Federální úředníci pracují otevřeně, s odznaky a místní koordinací, což je pomalejší, odpovědné a téměř úplně bez incidentů, což je pro policejní operaci správný výsledek."],["Nechte je tam a popřete, že jde vůbec o federální agenty.","Popíráte federální účast v operaci, kde jsou na videu jasně viditelné federální registrační značky vozidel. Popření se do hodiny stane druhým, samostatným skandálem."],["Přepněte je do jasně žlutých vest, jinak stále neoznačených.","Agenti zůstávají anonymní, ale teď nápadně viditelní, kompromis, který neuspokojí nikoho a na fotkách vypadá, proti veškerým očekáváním, ještě hůř než předtím."]]},"r-antitrust-weapon":{"t":"Přezkum fúze","x":"Mediální konglomerát vlastnící stanici, kterou nemáte rád, má v běžném řízení posuzovanou fúzi. Bo poznamenává, že „běžné“ a „řízení“ jsou technicky dvě oddělená slova a to druhé může trvat tak dlouho, jak si ministerstvo bude přát.","c":[["Zdržujte to donekonečna. Odvolávejte se na „přetrvávající obavy“.","Fúze zůstává v řízení jedenáct měsíců déle než jakákoli srovnatelná dohoda, což vysává akcie i trpělivost firmy, kvůli obavám, které se v podání nikdy pořádně neupřesní."],["Posuďte to podle skutečných antimonopolních kritérií, včetně harmonogramu.","Dohoda dostane analýzu, kterou má dostat každá dohoda, v termínech, ve kterých ji má dostat každá dohoda. Schválí se, protože podle skutkové podstaty má."],["Schvalte soupeřovu větší fúzi tentýž týden, bez přezkumu.","Fúze jedné stanice stagnuje měsíce, zatímco fúze té přátelštější proklouzne za devět dní. Odborný tisk otiskne oba harmonogramy vedle sebe, což příběhu stačí."],["Osobně zavolejte generálnímu řediteli „na kontrolu“ ohledně řízení.","Hovor, který měl znít uklidňujícím dojmem, se místo toho nahraje, přepíše a přečte do následného podání jako důkaz C. Informuje vás o tom Sy, kterému ten telefonát taky nedělal radost."]]},"r-fara-critic":{"t":"Zahraniční agent","x":"Think tank, který o vás publikuje nelichotivé výzkumy, dostává částečné financování od zahraničních partnerských institutů, stejně jako zhruba polovina think tanků ve městě. Bo poznamenává, že zákon o registraci zahraničních agentů se zřídka vymáhá a technicky ho porušuje skoro každý. „Skoro každý“ není obhajoba. Bývá to ale obvykle výmluva.","c":[["Obviňte je. Udělejte z toho příklad.","Think tank se skromným zahraničním grantem a nelichotivou výroční zprávou se stane první stíhaným případem tohoto druhu za deset let, podle zákona, který technicky porušuje polovina tohoto města."],["Předejte to standardnímu procesu registrace.","Think tank dostane stejné papírové upozornění jako kterákoli jiná nezaregistrovaná skupina se zahraničním financováním: termín, formulář a žádný titulek."],["Obviňte je a auditujte každý think tank, který o vás publikoval nelichotivě.","Jedenáct think tanků, vybraných výhradně podle svých závěrů, ne podle svého financování, dostane současné kontroly. Tři, které s vámi souhlasí, financované stejným způsobem, na seznamu nejsou."],["Zaregistrujte vlastní kampaň jako zahraničního agenta, ironicky.","Satirické sebe-přiznávací podání se přijme a zpracuje s naprostou byrokratickou vážností úřednicí, které to nepřipadá tak vtipné jako vám."]]},"r-nonprofit-probe":{"t":"Kontrola nadace","x":"Lyle prošel čísla neziskovky, která financuje snahy o registraci voličů blízké opozici: jedenáct let čistých podání v řadě. Přesto může otevřít přezkum daňového osvobození, na teorii, že přezkum, na rozdíl od porušení, nejdřív nemusí ve skutečnosti existovat.","c":[["Otevřete přezkum. Zmrazte jejich status do rozhodnutí.","Nadace přijde o daňové osvobození a tím i o většinu dárců, měsíce před jakýmkoli zjištěním, což se samo stane jediným zjištěním, na kterém záleželo."],["Žádný přezkum bez skutečné podkladové nesrovnalosti.","Odmítnete vymyslet porušení pro organizaci, jejíž papíry jsou náhodou čisté. Je to správný standard, důsledně uplatněný, což bývá vzácnější, než by mělo."],["Otevřete přezkum všech neziskovek, které darovaly opozici.","Desítky nesouvisejících neziskovek, spojených jen sdílenou politikou, dostanou současné kontroly. Rozpočet daňového soudu se ztrojnásobí a úředník si založí sázkovou hru na to, kolik jich přežije."],["Sám nadaci anonymně darujte, pak to nechte uniknout.","Anonymní dar z číslovaného účtu se do týdne vystopuje zpátky k vám, protože v tomhle městě nic nezůstane anonymní. Nikdo, ani nadace, přesně neví, co si o tom myslet."]]},"r-favorable-settlement":{"t":"Tichá dohoda","x":"Firma vlastněná dlouholetým spojencem čelí federálnímu případu podvodu se silnými důkazy. Bo má na stole dohodu: pokuta tak malá, že je zaokrouhlovací chybou proti jejich obratu, žádné přiznání viny, podané v pátek, kdy nikdo nečte podání.","c":[["Schvalte dohodu. Páteční podání, jak navrženo.","Případ podvodu, který kariérní žalobci hodnotili jako silný, se vyřeší za méně, než firma utratí za vánoční večírek. Podání proběhne přesně tak, jak bylo naplánováno, a všimne si toho, nakonec, přesně jeden novinář."],["Nechte případ pokračovat na základě důkazů, dohoda nebo soud.","Případ postupuje na základě faktů, spojenec nespojenec. Vyřeší se za skutečné číslo, o měsíce později, z důvodů, které nemají s telefonátem od vás nic společného."],["Schvalte dohodu a nechte Bo prohlásit ji za „výhru pro daňové poplatníky“.","Dohoda za zaokrouhlovací chybu se s vážnou tváří vyhlásí jako vítězství daňových poplatníků. Finanční novinář spočítá skutečná čísla vedle citátu, což je celá vyvrácení."],["Odmítněte to. Veřejně žádejte tvrdší dohodu, pro efekt.","Přebijete vlastního ministra spravedlnosti a žádáte tvrdší dohodu proti spojenci, čistě abyste u toho vypadal tvrdě. Spojenec zuří, případ se táhne a bod jste, technicky, dokázal."]]},"r-judge-shopping":{"t":"Přátelský okresní senát","x":"Sy našel jednosoudcovský okrsek, osm tisíc obyvatel, kde jakýkoli podaný případ automaticky spadne k jednomu konkrétnímu soudci, který proti vám nikdy nerozhodl. Doporučuje odteď podávat tam vše citlivé a je z toho doporučení sám mírně zahanbený.","c":[["Podávejte tam vše, od teď.","Jeden soudce v malém okrsku se funkčně stane druhým Nejvyšším soudem pro cokoli, na čem vám záleží. Profesoři práv o tom fenoménu začínají učit jménem, a ne pochvalně."],["Podávejte tam, kam skutečně ukazují fakta a pravidla o příslušnosti.","Necháte příslušnost rozhodovat pravidla příslušnosti místo pravděpodobnosti vítězství. Je to nejnudnější dostupná volba a udrží důvěryhodnost soudnictví přesně tam, kde má být."],["Podávejte tam a zveřejňujte soudcovu úspěšnost pro vás.","Tisková zpráva cituje soudcův výsledkový poměr jako sportovní statistiku. Soudce, o kterou nikdo nestál, vydá vzácné veřejné prohlášení vyjadřující nechuť k vlastnímu fanklubu."],["Podávejte tam a schválně prohrajte případ, kvůli image.","Nařídíte vlastním právníkům, aby prohráli vyhratelný případ ve přátelské síni, kvůli nestrannosti. Poslechnou, špatně, a prohra je tak nepřesvědčivá, že se sama stane příběhem."]]},"r-court-stripping":{"t":"Nařízení odolné vůči přezkumu","x":"Návrh výkonného nařízení obsahuje klauzuli prohlašující akci za „nepodléhající soudnímu přezkumu“. Winifred, oslovená mimo záznam, říká, že klauzule nemá žádnou právní sílu a bude první větou vyškrtnutou z jakéhokoli výsledného stanoviska. Dodává, že to nikdy nikoho nepřestalo zkoušet.","c":[["Zahrňte klauzuli. Ať ji soudy vyškrtnou, pokud si troufnou.","Klauzule je vyškrtnuta za šest dní soudcem, který věnuje čtyři z jedenácti stran stanoviska dělbě moci, tónem obvykle vyhrazeným pro děti, které to lépe vědí."],["Vypusťte klauzuli. Napište nařízení tak, aby poctivě obstálo.","Napíšete nařízení stavěné na to, aby přezkum obstálo, ne aby ho vyzývalo, což trvá déle a funguje lépe, v tomto pořadí."],["Zahrňte klauzuli do každého nařízení do konce roku.","Klauzule se stane standardní formulací, vyškrtávanou na první pohled úředníky, kteří teď mají v šuplíku šablonu odpovědi. Přestala i mírně kohokoli v talárech překvapovat."],["Požádejte soudy v samotném nařízení, aby ho laskavě nepřezkoumávaly.","Výkonné nařízení obsahuje větu žádající soudnictví, jako o laskavost, aby se vzdalo jurisdikce. Cituje se ve třech oddělených stanoviscích, pokaždé přímo před slovy „se zamítá“."]]},"r-grand-jury-testify":{"t":"Předvolání pro vás","x":"Velká porota vás předvolala přímo, ne vaše právníky, ne vaše zaměstnance, vás, abyste svědčil o událostech, které by Sy mnohem raději nechal nezmíněné. Má tři strategie, seřazené podle toho, kolik vás to bude stát později.","c":[["Bojujte proti tomu u soudu rok. Zdržování je taky strategie.","Rok návrhů, odvolání a procesního zdržování vás udrží mimo svědeckou lavici a na titulní straně stejně, kvůli boji, ne kvůli svědectví."],["Svědčte. Odpovězte na otázky, které padnou, nic navíc.","Sedíte čtyři hodiny, odpovídáte na to, co se zeptají, nic dobrovolně nedodáte a odejdete. Je to právně nejsolidnější odpoledne vašeho mandátu a nejméně citovatelné."],["Svědčte, pak uspořádejte tiskovku, abyste „napravil záznam“.","Do devadesáti minut si odporujete s vlastní přísežnou výpovědí, na kameru, před publikem, které zahrnuje i vlastní zaměstnance velké poroty."],["Nabídněte svědectví písemně, ve verších, jako formální námitku.","Přísežné prohlášení podané v rýmovaných dvojverších je přijato, založeno a s vážnou tváří přečteno do záznamu soudní stenografkou, která zjevně zažila horší věci."]]},"r-ag-wont-defend":{"t":"Zákon, který nikdo nehájí","x":"Zákon schválený za vašeho předchůdce, který se vám nelíbí, ale Kongres ho nikdy nezrušil, je napadán u soudu. Bo poznamenává, že ministerstvo ho jednoduše nemusí hájit a zákon zanikne standardně, aniž by proti němu padl jediný hlas.","c":[["Nehajte ho. Ať tiše zanikne u soudu.","Zákon přežije každé hlasování, které kdy Kongres uspořádal, a přesto zanikne, protože se u soudu nikdo nepostavil na jeho obhajobu. Je to legální. Je to taky obchvat s vašimi otisky prstů po celém povrchu."],["Hajte ho. Je to zákon, dokud Kongres neřekne jinak.","Hájíte zákon, který se vám osobně nelíbí, protože je pořád, fakticky, zákonem. Je to malý, nevýrazný akt úcty k procesu většímu než váš názor."],["Nehajte ho a oznamte to jako standardní politiku.","Oznámíte jako pravidlo, že zákony, které se vám nelíbí, se od teď prostě nebudou hájit. Jedenáct probíhajících případů náhle silně závisí na vaší náladě."],["Prohlaste zákon za „v rekonstrukci“ a pověste tabulku.","Tisková zpráva oznamuje, že zákon je „uzavřen kvůli rekonstrukci“, fráze bez jakéhokoli právního významu, kterou přesto čtyři zpravodajské stanice otisknou, jako by nějaký měla."]]},"r-doj-whistleblower":{"t":"Případ, který nechtěla zahodit","x":"Miriam má na stole formální stížnost: kariérní právnička ministerstva spravedlnosti tvrdí, že na ni byl vyvíjen nátlak, aby zastavila případ proti vašemu politickému spojenci. Miriam potvrdila, že nátlak proběhl. Zatím písemně nepotvrdila, čí to byl nátlak.","c":[["Přeřaďte ji. Potichu. Do pobočkové kanceláře.","Whistleblowerka je přesunuta do úřadu, který posuzuje vývozní povolení na obilí, degradace maskovaná jako laterální přesun, kterou nikdo neošálí, nejméně ze všech ji samotnou."],["Ochraňte ji. Ať stížnost projde standardními kanály.","Stížnost se vyšetří tak, jak byly stížnosti oznamovatelů navrženy vyšetřovat, a ona si udrží práci i případ. Je to, pro jednou, bez události."],["Přeřaďte ji a otevřete protistížnost na její jednání.","Odvetná stížnost podaná proti whistleblowerce za to, že podala stížnost, je i podle nedávných standardů tohoto ministerstva nová úroveň nestydatosti."],["Povyšte ji, veřejně, do funkce bez skutečné pravomoci.","Dostane ceremoniální povýšení s novým titulem, hezčí kanceláří a přesně nulovou agendou. Přesně vidí, o co jde, a přesto to přijme, na teorii, že hezčí kancelář je pořád hezčí kancelář."]]},"r-rico-protest":{"t":"Obvinění z vydírání","x":"Bo našel způsob, jak obvinit organizátory protestu podle zákona vytvořeného pro organizovaný zločin: označit volnou síť místních skupin za „podnik“, a najednou je hrstka lidí objednávajících přenosné toalety na shromáždění spoluspiklenci v případu vydírání. Není z toho nadšený. Je připravený to udělat.","c":[["Podejte obvinění z vydírání. Jmenujte celou síť.","Devatenáct lidí, většinou dobrovolníků, kteří se nikdy nepotkali, je obviněno jako zločinecký podnik. Faktura za pronájem toalet se absurdně stane důkazem číslo 4."],["Obviňte jen jednotlivce, kteří skutečně porušili zákon.","Stíháte hrstku lidí, kteří spáchali skutečný trestný čin, za skutečný trestný čin, což je mnohem menší titulek a mnohem pevnější případ."],["Podejte obvinění a zmrazte bankovní účty sítě.","Celý provozní rozpočet hnutí, čtyři tisíce dolarů vybrané na vodu a kauce, je zmrazen do soudu, který trvá tři roky, než ho prohrajete."],["Obviňte na principu i firmu půjčující toalety.","Sanitární dodavatel je jmenován ve federální obžalobě z vydírání za to, že pronajal toalety nesprávnému zákazníkovi. Jejich právník to nazve „nejpodivnějším honorářem kariéry“ a nepřehání."]]},"r-gag-order":{"t":"Nařízení o mlčenlivosti","x":"Bývalá poradkyně má knihu pamětí míjejících se s pravdou pod tři týdny na pultech, nelichotivou a podle prvních zpráv přesnou. Sy má neotřelou teorii pro soudní zákaz: retroaktivně zařadit popsané rozhovory jako utajovanou informaci národní bezpečnosti a na tomto základě knihu zablokovat.","c":[["Podejte návrh na zákaz. Zablokujte knihu před vydáním.","Federální soud je požádán, aby zastavil paměti na teorii, že běžné pracovní porady se zpětně staly utajovanými. Soudce si teorii přečte jednou a nežádá, aby mu ji opakovali."],["Nechte to vyjít. Reagujte na konkrétní tvrzení, pokud vůbec.","Necháte knihu být knihou. Několik tvrzení v ní je nepřesných a opraví se v brožovaném vydání. Je to, strukturálně, přesně jak má proces fungovat."],["Podejte návrh na zákaz a předvolejte nakladatelský katalog.","Předvolání jedné knihy pamětí naboptná v žádost o celý nadcházející program velkého nakladatelství, na teorii, kterou nikdo nedokáže nahlas plně formulovat, nejméně u soudu."],["Napište vlastní protipaměti, v závodě s termínem vydání.","Narychlo sestavené protipaměti vyjdou devět dní po originálu, prodají se třikrát méně a citují se hlavně v kapitolách, kde se obě knihy, kupodivu, shodují."]]},"r-consent-decree":{"t":"Dekret, který nikdo nevymáhá","x":"Soudní dekret vyžaduje, aby federální dozorci přezkoumávali použití síly policejním sborem poté, co soud zjistil vzorec jeho zneužívání. Náčelník sboru přispíval na vaši kampaň a nazývá dozorce „okupační silou“. Bo prostě nemusí nikoho poslat. Nikdo nedohlíží na samotný požadavek dohledu.","c":[["Stáhněte dozorce. Ať dekret potichu vyprchá.","Dozorčí tým je přeřazen a soudní dekret se funkčně stane dokumentem, který nikdo nevymáhá. Stížnosti na zneužití síly v tom sboru příští rok stoupnou, neměřeno nikým, kdo by to řekl oficiálně."],["Nechte dozorce na místě. Soudní příkaz platí.","Necháte federální soudní příkaz dělat práci, kterou má federální soudní příkaz dělat. Náčelník si stěžuje na tiskovce. Dozorci se přesto dál dostavují."],["Stáhněte dozorce a pošlete náčelníkovi pochvalu.","Sbor pod federálním dohledem kvůli použití síly dostane prezidentskou pochvalu tentýž měsíc, kdy jeho dohled zmizí. Ta dvě fakta v každém převyprávění nepříjemně sousedí."],["Zúčastněte se jako dobrovolný dozorce, na jednu směnu, osobně.","Odjedete si na jednu směnu na zadním sedadle hlídkového vozu, děláte si podrobné poznámky a napíšete zprávu tak lichotivou, že vás skuteční dozorci zdvořile požádají, ať jim ukážete svá data."]]},"r-contempt-citation":{"t":"Rozhodnutí o pohrdání soudem","x":"Federální soudkyně vás uznala vinným z pohrdání soudem za pokračování v programu, který výslovně nařídila zastavit. Je to, poznamenává Sy s viditelnou nelibostí, formální zjištění, že úřadující prezident neuposlechl přímý soudní příkaz, a slovo „pohrdání“ se čistě neuhraje.","c":[["Ignorujte to zjištění. Pokračujte v programu bez ohledu.","Pokračujete v programu, který federální soudkyně výslovně a formálně nařídila zastavit. Je to, funkčně, přesně ten scénář, kterému měla Ústava zabránit, na první stránce."],["Vyhovte okamžitě. Zastavte program, odvolejte se zvlášť.","Uděláte tu nejméně dramatickou možnou věc pro prezidenta pod výtkou pohrdání soudem: to, co příkaz říká. Odvolání pokračuje řádně, na vlastním harmonogramu, bez toho pohrdání navěšeného na sebe."],["Vyhovte na papíře. Provozujte program pod jiným jménem.","Program se do měsíce znovu objeví pod novou zkratkou, se stejnými lidmi, dělajícími stejnou věc. Soudkyně to neošálí a řekne to, písemně, obšírně."],["Pošlete soudkyni ručně psanou omluvu. Vyhovte přesto.","Ručně psaná omluva federální soudkyni, vložená do podání o splnění příkazu, je natolik neobvyklá, že si ji její asistenti okopírují dřív, než jde do spisu. Neodpoví. Dopis si ale nechá."]]},"r-executive-privilege":{"t":"Nárok na výsadu","x":"Bývalá poradkyně byla předvolána kongresovým výborem, aby svědčila o rozhovorech vedených přímo s vámi. Sy může uplatnit exekutivní výsadu, aby výpověď zablokoval, nárok, který v historii země nikdy nebyl plně vyzkoušen pro něco takhle konkrétního.","c":[["Uplatněte ji široce. Zablokujte výpověď úplně.","Nárok na výsadu dost široký, aby pokryl rozhovor na chodbě, je podán a zatím obstojí. Výbor stráví čtyři měsíce u soudu kvůli slovům, která zatím nikdo mimo místnost skutečně neslyšel."],["Nechte ji svědčit. Zúžte výsadu na skutečné jednání o politice.","Svědčí o většině toho, s úzkou a obhajitelnou výjimkou pro skutečné rozhodovací jednání. Uspokojí to zvědavost výboru i legitimní potřebu soukromí úřadu, v tomto pořadí."],["Uplatněte ji a nařiďte jí neodpovídat na nic, ani na vlastní jméno.","Poradkyně sedí celé vysílané slyšení a na pokyn odmítá potvrdit i vlastní pracovní historii. Klip se dekádu přehrává na právnických školách jako učebnicový příklad „přehnat to“."],["Nechte ji svědčit, ale sám seďte v místnosti, viditelně.","Bývalý prezident přítomný na kongresovém slyšení jako divák, v první řadě, nezmění nic na zákonu o výsadě a všechno na to, jak nervózně vypadá svědek při odpovídání."]]},"r-two-tier-justice":{"t":"Memorandum o trestu","x":"Dva muži spáchali, na papíře, srovnatelné federální trestné činy s odstupem osmi měsíců. Jeden přispíval na vaši kampaň; memorandum ministerstva doporučuje podmínku. Druhý vás kritizoval v podcastu; memorandum doporučuje zákonné maximum. Bo předložil obě memoranda bez komentáře, což on sám považuje za formu komentáře.","c":[["Schvalte obě memoranda tak, jak jsou. Bez úpravy.","Dva srovnatelné zločiny vyprodukují dvě naprosto odlišná doporučení, podaná stejný měsíc na stejné hlavičce. Profesor práv je dá vedle sebe v jednom příspěvku, který přežije zpravodajský cyklus."],["Vraťte obě memoranda. Vyžadujte konzistentní pokyny pro trestání.","Obě memoranda se přepracují tak, aby odrážela skutečné pokyny pro trestání místo skutečných přátelství. Je to nevýrazné, spravedlivé a skoro nikdo si nevšimne, že spravedlnost byla ta těžší volba."],["Schvalte obě, pak zavolejte přísnějšímu soudci „vysvětlit kontext“.","Telefonát od prezidenta soudkyni, myšlený jako zmírnění trestu, je přesně ten druh kontaktu, který mají etická pravidla soudnictví zabránit. Soudkyně ten hovor sama nahlásí."],["Prohoďte doporučení, jako soukromý vtip, kterému rozumí jen Bo.","Na jedenáct minut jde přísnější memorandum k dárci a to mírnější ke kritikovi, jen aby Bo mohl sledovat váš výraz. Prokouknete to, jednou se zasmějete a přinutíte ho to opravit dřív, než to někdo podepíše."]]},"r-statute-rush":{"t":"Čas vyprší","x":"Promlčecí lhůta u desetiletého, okrajového případu proti senátorovi, který blokuje vaši agendu, vyprší za tři týdny. Bo může v tom okně protlačit obžalobu velkou porotou na důkazech, které soukromě hodnotí jako „tak tenké, že skrz ně vidíte“, nebo nechat čas vypršet a věc zaniknout podle plánu, jak má.","c":[["Uspěchejte to. Podejte obžalobu, než vyprší čas.","Senátor je obviněn v poslední právně možný den, na důkazech, které obhájce rozloží za odpoledne. Případ se za osmnáct měsíců u soudu zhroutí, dávno poté, co titulek splnil svůj účel."],["Nechte to vypršet. Slabé důkazy se pod termínem nezesílí.","Necháte slabý případ zaniknout podle plánu místo toho, abyste ho protlačili přes termín. Je to správný výsledek a, jako vždy, nikdo vám za něj neuspořádá přehlídku."],["Uspěchejte to a oznamte obvinění dřív, než to Bo vůbec podepíše.","Oznámíte obvinění úřadujícího senátora dřív, než papírování existuje, a donutíte ministerstvo buď vyrobit obžalobu, kterou jste už slíbil, nebo veřejně odporovat vlastnímu prezidentovi."],["Nechte to vypršet, pak pošlete senátorovi kartičku s datem.","Ručně psaná kartička s přesným datem, kdy jeho ohrožení skončilo, dorazí do senátorovy kanceláře. Zarámuje si ji. Taky si od toho dne, osobně, s vámi nikdy víc nezavolá."]]},"r-solicitor-flip":{"t":"Obrácené stanovisko","x":"Vláda zastávala stejné právní stanovisko v tomto typu případů třicet let, napříč administrativami obou stran. Zvrátit ho teď, uprostřed sporu, by soupeřovu probíhajícímu případu dalo skoro automatickou prohru. Bo to může podat do pátku. Tiše poznamenává, že stanovisko bylo správné v úterý a bude nesprávné v pátek, čistě kvůli načasování.","c":[["Podejte obrat. Pátek, jak bylo plánováno.","Třicet let konzistentního právního stanoviska skončí páteční žádostí, načasovanou na jeden konkrétní případ. Tři bývalí generální advokáti, z obou stran, podepíší společný dopis nazývající to „ne tak to má fungovat“, což nic nezmění."],["Zachovejte stanovisko. Precedens přežije jakýkoli jeden případ.","Necháte tři desetiletí konzistence zůstat konzistentní, za cenu jednoho případu, který byste raději vyhrál jinak. Důvěryhodnost ministerstva, na rozdíl od toho případu, vás přežije."],["Podejte obrat a antedatujte doporučující memorandum.","Memorandum zdůvodňující obrat je datováno dva měsíce před případem, který ho vyvolal, chyba, kterou odhalí mladší právník porovnáním s vlastním kalendářem."],["Argumentujte oběma stanovisky ve dvou různých soudních síních ve stejném týdnu.","Vláda zastává protichůdné právní teorie ve dvou obvodech současně, rozpor tak čistý, že mu právnický časopis věnuje celé příští číslo."]]},"p-economy-1":{"t":"Šok z cenovky","x":"Ministr financí položí na stůl účtenku z obchodu, jako by to byla obsílka. Vejce zdražila o šedesát procent a kabelové zpravodajství natáčí reportáže před supermarkety. „Pane prezidente, lidé jsou naštvaní, a naštvaní lidé sledují zprávy.“","c":[["Vyhlásit dekret zmrazující všechny ceny potravin do pátku","Regály se přes víkend vyprázdní, protože obchody prostě přestanou doplňovat zmrazené položky."],["Nechat centrální banku zvednout sazby a přijmout politický zásah","Inflace do jara opadne. Nikdo si nepamatuje, kdo to napravil, jen kdo to dopustil."],["Nařídit statistickému úřadu, ať prostě zveřejní nižší číslo","Skutečné ceny zůstanou stejné. Jediné, co se změní, je to, komu můžete věřit."],["Přejmenovat inflaci na celostátní televizi na „cenu svobody“","Galon mléka teď stojí jedenáct dolarů a špetku vlastenectví navrch."]]},"p-economy-2":{"t":"Poslední píšťalka","x":"Vantage Steel zavírá továrnu v Dunmore, tu samou, před kterou jste v kampani stáli s vyhrnutými rukávy. Tři tisíce pracovních míst, jedna fotka, pryč během jednoho odpoledne. „Přesouvají linku do Guatemaly,“ říká ministryně práce. „Dělníci se to dozvěděli esemeskou.“","c":[["Veřejně to svalit na zahraniční obchodní spiknutí proti Dunmore","Vantage Steel vydá prohlášení. Nezmění to nic, jen to, koho budou v hospodě vinit."],["Prosadit skrz Kongres skutečný program rekvalifikace a přestěhování","Stojí to peníze a trvá roky, ale skutečně to pomůže jedenácti stům rodin. To nikdo nefotí."],["Znárodnit továrnu výnosem a vyzvat soudy, ať vás zastaví","Továrna se otevře pod novým nápisem. Ocel, kterou vyrábí, nemá kam výhodně jít."],["Osobně zavolat řediteli továrny a poprosit ho, ať ji prostě nezavírá","Ředitel je velmi zdvořilý. Továrna zavře přesně podle plánu."]]},"p-economy-3":{"t":"Kobaltová opona","x":"Předseda Wei zakázal veškerý vývoz vzácného kobaltu jako odvetu za loňská cla. Každá továrna na baterie v Rezavém pásu má zásoby asi na šest týdnů. „Celý plán elektromobilů jsme postavili na minerálu, který sami netěžíme,“ přiznává ministr zahraničí.","c":[["Vyhlásit celostátní nerostnou nouzi a zabavit soukromé zásoby","Firmy raději zbylý kobalt schovávají, než aby ho odevzdaly."],["V tichosti sjednat dodávky s přátelštější surovinově bohatou zemí","Funguje to, je to nudné a trvá to osm měsíců neokázalých telefonátů."],["Vyhrožovat invazí do surovinově bohatého spojence, aby se zajistily dodávky","Spojenec svolá nouzový summit. Stejně tak zbytek kontinentu."],["Vyhlásit havarijní program těžby kobaltu ze staré skládky v Ohiu","Skládka vydá kobalt na čtyři baterie a spoustu metanu."]]},"p-economy-4":{"t":"Hod mincí","x":"Token zvaný FreedomCoin, který jste možná pochvalně zmínili na jednom mítinku, přes noc ztratil devadesát jedna procent hodnoty. Šéf centrální banky drží výtisk rozzuřených důchodců z fóra jménem r/rugged. „Pane prezidente, někteří z těchto lidí do toho vložili penzi.“","c":[["Oznámit, že vláda osobně zaručí hodnotu FreedomCoinu","Ministerstvo financí teď ručí za měnu, kterou vymyslel muž jménem Chad."],["Předat burzu regulátorům a nechat ztráty být","Nikdo nedostane peníze zpátky, ale příští podvod bude o trochu menší."],["Svalit propad na centrální banku soupeřící velmoci","Obvinění je nepodložené a nesmírně populární."],["Spustit druhý, stabilnější token jménem FreedomCoin Plus","Také se zhroutí, ale trvá to celých jedenáct dní, což někteří nazývají pokrokem."]]},"p-economy-5":{"t":"Zase moc velká na pád","x":"Continental Trust, šestá největší banka v zemi, je potichu insolventní. Pokud v pondělí otevře bez záchrany, říká ministr financí, „čeká nás run na banku, proti kterému bude ten poslední vypadat jako dobročinný bazar.“","c":[["Zachránit ji přes noc a nechat řediteli jeho bonus","Banka přežije. Bonus se na měsíc stane pravidelnou rubrikou zpráv."],["Prosadit řízený zánik s odvoláním vedení","Je to spravedlivé, uspořádané a přesně nikoho, kdo sleduje svůj penzijní účet, to neuspokojí."],["Zachránit ji a v tichosti obsadit novou správní radu vašimi dárci","Banka je zachráněna. Stejně tak, velkoryse, i pár vašich přátel."],["Promluvit k národu s malou keramickou prasečí pokladničkou v ruce","Trhy se stabilizují. Pokladnička se vyprodá ve třech různých obchodech se suvenýry."]]},"p-economy-6":{"t":"Všichni ven","x":"Železničáři, přístavní dělníci a letečtí mechanici vypochodovali ven ve stejné úterý, což odbory nazývají shodou okolností a ministryně práce „nejsehranější náhodou, jakou jsem kdy viděla“.","c":[["Nařídit Národní gardě, ať vlaky a přístavy řídí sama","Náklad se zase pohybuje, špatně, řízen vojáky, kteří v životě neviděli seřaďovací nádraží."],["Sednout s vedením odborů a vyjednat skutečnou smlouvu","Trvá to jedenáct hodin a hodně mizerné kávy, ale vlaky zase jezdí načas."],["Prohlásit stávku za nezákonnou a vyhrožovat hromadným propouštěním","Polovina zaměstnanců se vrátí vyděšená. Z druhé poloviny se stane lidová píseň."],["Osobně řídit vysokozdvižný vozík v přístavu pro kamery","Přesunete jednu paletu, špatně, a stane se to nejsledovanějším klipem roku."]]},"p-economy-7":{"t":"Podání ruky, které nebylo","x":"Historická obchodní dohoda s Meridií byla dnes ráno podepsána s velkou pompou, třemi vlajkami a plnicím perem ve tvaru orla. Vedoucí kanceláře právě zjistila, že skutečný dokument neobsahuje jediné závazné ustanovení. „Je to fotka,“ říká. „Podepsali jsme fotku.“","c":[["Přesto to nazvat historickým a jít dál, než si to někdo přečte","Analytici si toho nakonec všimnou. Do té doby se zpravodajský cyklus otočil třikrát."],["Přiznat, že šlo o symbolické gesto, a slíbit skutečnou dohodu do konce roku","Nikdo netleská upřímnosti, ale skuteční vyjednavači konečně dostanou opravdový mandát."],["Tvrdit, že Meridia potají couvá, a hrozit novými cly","Meridijský velvyslanec je zmatený. Základnu to i tak nadchne."],["Přerámovat samotné orlí pero na historický úspěch","Pero se v obchodě se suvenýry vyprodá do hodiny."]]},"p-economy-8":{"t":"Clo na brie","x":"Jako odvetu za nesouvisející rybářský spor jste uvalili čtyřsetprocentní clo na dovážený měkký sýr. Ministr financí hlásí, že domácí produkce brie je a vždy byla prakticky nulová. „Pane prezidente, zdaňujeme produkt, který tu neexistuje.“","c":[["Rozšířit clo na všechny měkké sýry, z principu","Sýrové mísy po celé zemi jsou znatelně smutnější a vlastenečtější."],["Potichu clo zrušit, než se zorganizuje lobby restaurací","Brie se vrací do regálů. Rybářský spor zůstává zcela nevyřešen."],["Vyhlásit federální dotaci na rozjezd americké výroby brie","V Nebrasce se otvírá pilotní farma na brie. Odborníci zůstávají hluboce skeptičtí."],["Prohlásit čedar za jediný sýr, který pravý vlastenec potřebuje","Prodej čedaru vzroste o jedenáct procent. Někde si povzdechne francouzský ministr."]]},"p-economy-9":{"t":"Maličkost pro Chada","x":"Nový dotační program na čistou energii poslal, čirou náhodou, devadesát procent prostředků solární firmě vlastněné vaším největším sponzorem, mužem jménem Chad Bellwether. „Vyjde to najevo,“ varuje ministr energetiky. „Tyhle věci vždycky vyjdou najevo.“","c":[["Trvat na tom, že firma prostě měla nejlepší žádost","Novináři do týdne najdou fotky z golfu. Základnu to nezajímá."],["Otevřít dotační program skutečnému konkurenčnímu výběrovému řízení","Bellwetherova firma prohraje nové kolo proti firmě z Nevady se skutečnými inženýry."],["Dát Bellwetherovi druhou, ještě větší zakázku, aby se dokázalo, že se nic neskrývá","Něco se skutečně skrývá. Teď je to dvakrát tak velké."],["Přejmenovat program po fiktivním průměrném Američanovi jménem Chad","Skutečný Chad Bellwether to považuje za skvělý vtip. Nikdo jiný ne."]]},"p-economy-10":{"t":"Bolest u pumpy","x":"Benzin po požáru ropovodu překročil šest dolarů za galon a ministryně energetiky říká, že kamioňáci vyhrožují blokádou dálničního okruhu kolem hlavního města. „Tohle je číslo, které končí prezidentství,“ říká věcně.","c":[["Nařídit úplné vyčerpání strategických rezerv, aby se srazila cena","Ceny na šest týdnů klesnou. Rezervy jsou teď nebezpečně, potichu prázdné."],["Místo toho investovat příjmy z windfall daně do veřejné dopravy","Pomůže to za tři roky. Nepomůže to nikomu, kdo dnes v noci stojí v koloně."],["Bez důkazů svalit požár ropovodu na zahraniční sabotáž","Obvinění ovládne zpravodajský cyklus. Ropovod byl ve skutečnosti prostě starý."],["Osobně natankovat cizímu řidiči na kameru a prohlásit problém za vyřešený","Jeden velmi šťastný řidič dostane benzin zdarma na den. Všichni ostatní pořád platí šest dolarů."]]},"p-economy-11":{"t":"Chybějící čip","x":"Jedna zatopená továrna v Chosanu zastavila globální dodávky polovodičů a automobilky ve třech státech stojí. „Každý vůz, který nepostavíme,“ říká ministr financí, „je titulek, který si nemůžeme dovolit.“","c":[["Zabavit domácí zásoby čipů a přesměrovat je oblíbeným automobilkám","Dva závody se okamžitě znovu rozjedou. Šest dalších do čtvrtka podá žalobu."],["Zrychlit povolení pro nové domácí továrny na výrobu čipů","Výstavba začíná do měsíce. Továrny nevyrobí jediný čip dva roky."],["Vyhlásit úplný zákaz vývozu čipů do zemí soupeřících s Chosanem, jako páku","Nic to nezmění na povodni. Hodně to ale změní na vztazích."],["Navrhnout, že vozy prozatím pojedou bez infotainmentu na obrazovce","Kupující jsou rozzuření. Prodejci s údivem zjišťují, že překvapivé množství lidí obrazovku nechce."]]},"p-economy-12":{"t":"Domeček z karet","x":"Ceny domů v šesti velkých metropolích se za osmnáct měsíců zdvojnásobily a ministr financí drží graf nepříjemně podobný tomu z roku dva tisíce osm. „Pane prezidente, kdo si to může dovolit, kupuje rovnou tři.“","c":[["Vinit stejně hlasitě přistěhovalce i investory","Je to uspokojivé vysvětlení. Většinou to ale není ten skutečný důvod."],["Postupně zpřísnit pravidla pro hypotéky, aby se trh ochladil","Noví kupující vám tiše děkují. Současní majitelé sledující svůj kapitál nikoli."],["Dekretem zakázat všechny firemní nákupy rodinných domů","Každá velká realitní firma do týdne podá žalobu. Základna tenhle souboj miluje."],["Navrhnout mladým lidem, ať si prostě řeknou rodičům o vyšší půjčku","Klip se stane virálním ze všech špatných i pár správných důvodů."]]},"p-economy-13":{"t":"Problém s penzemi","x":"Meziregionálnímu penzijnímu fondu Teamsters chybí devět miliard dolarů a půl milionu důchodců se má dozvědět, že jejich šeky se zmenšují. „Pracovali na tom čtyřicet let,“ říká ministryně práce. „Neudělali nic špatně.“","c":[["Potichu nechat fond snížit dávky a vinit správce fondu","Důchodci dostanou menší šeky. Správci fondu dostanou velmi přísný dopis."],["Prosadit v Kongresu federální záruku, která pokryje schodek","Stojí to daňové poplatníky miliardy a zachrání to půl milionu důchodů. Obojí je pravda."],["Nařídit centrální bance, ať schodek přes noc potichu dotiskne","Šeky přijdou včas. Ekonomové stráví příští rok vysvětlováním, proč je to znepokojivé."],["Uspořádat televizní bingo večer pro důchodce na zvednutí morálky","Morálka je krátce vynikající. Devítimiliardová díra zůstává přesně devítimiliardovou dírou."]]},"p-economy-14":{"t":"Měnová hra nervů","x":"Prezident Volkov nazval dolar ve státní televizi „umírajícím reliktem“ a záměrně znehodnotil rublu podobnou měnu solyanku, aby podrazil americký export. „Snaží se vás vyprovokovat k veřejné reakci,“ varuje ministr financí. „Nenaleťte na to.“","c":[["Odpálit to zpátky na sociálních sítích a nazvat ho zkrachovalým tyranem","Trhy sebou trhnou. Volkov, nadšený, odpoví do hodiny."],["Nechat reagovat pouze ministerstvo financí tichými diplomatickými kanály","Kurz se do týdne stabilizuje. Nikdo netleská tichu, které to zařídilo."],["Nařídit symbolický hromadný výprodej dluhopisů solyanky, aby ho to potrestalo","Ministerstvo financí to stojí víc než Volkova, ale je z toho skvělý titulek."],["Poslat Volkovovi jednu pamětní minci s nápisem „Druhá nejlepší měna světa“","Státní média se o tom nikdy nezmíní. Váš vlastní tiskový úřad nepřestane."]]},"p-economy-15":{"t":"Nekupujte americké","x":"Po vašem posledním projevu o clech se po třech kontinentech rozšířil občanský bojkot amerického zboží a ministr zahraničí hlásí, že oblíbená značka limonády byla v Meridii úplně stažena z regálů. „Jde o tu limonádu, pane prezidente. Bojkotují limonádu.“","c":[["Prohlásit bojkotující země za ekonomické nepřátele Ameriky","Bojkot se rozšiřuje. Zvláštně tak i domácí hrdost na limonádu."],["Nechat ministra zahraničí potichu stáhnout projev o clech","Bojkot za měsíc odezní. Nikdo doma si nevšimne, že vůbec nastal."],["Spustit ze vzdoru protibojkot meridijského dovozu","Meridijský dovoz jsou hlavně banány. Ceny v obchodech mírně stoupnou bez jakéhokoli strategického přínosu."],["Osobně vyslat maskota limonádové firmy na dobrovolnou misi","Maskot je vřele přijat. Limonáda zůstává zakázaná."]]},"p-economy-16":{"t":"Zpráva o zaměstnanosti","x":"Měsíční zpráva o zaměstnanosti poprvé za tři roky ukazuje čistou ztrátu pracovních míst a ministryně práce má tu nezáviděníhodnou úlohu přinést ji do Oválné pracovny. „Vnitřní čísla můžeme zabalit jinak,“ říká opatrně, „ale hlavní číslo je hlavní číslo.“","c":[["Prohlásit zprávu za podvrh a žádat rezignaci šéfa úřadu","Šéf pod tlakem rezignuje. Příští zpráva je horší a teď jí nikdo nevěří tak jako tak."],["Prezentovat skutečná čísla poctivě, s plánem, jak je řešit","Ekonomové si váží upřímnosti. Základna chtěla padoucha, ne tabulku."],["Svalit ztráty úplně na předchozí administrativu","Předchozí administrativa opustila úřad před dvěma lety. Na tom nezáleží."],["Předefinovat částečné úvazky a nezaměstnané jako „jinak zaměstnané“","Nové číslo vypadá skvěle. Fronta u potravinové banky vypadá stejně."]]},"p-economy-17":{"t":"Patnáct a bojujeme","x":"Koalice pracovníků rychlého občerstvení požaduje zvýšení federální minimální mzdy na dvacet dva dolarů a ministryně práce hlásí, že lobby restaurací v reakci hrozí hromadným propouštěním. „Obě strany si myslí, že ta druhá blafuje,“ říká. „Nikdo neblafuje.“","c":[["Hlasitě se postavit na stranu malých podniků a nazvat pracovníky nevděčnými","Lobby restaurací jásá. Pracovníci plánují mnohem větší pochod."],["Vyjednat postupné, mírné zvýšení, které obě strany snesou","Nikdo není nadšený. Obě strany se nerady, ale vrátí do práce."],["Slíbit plných dvacet dva dolarů výnosem už zítra","Nařízení je populární a téměř jistě nezákonné. Žaloby začnou okamžitě."],["Navrhnout pracovníkům, ať si o zvýšení řeknou přímo manažerům","Virální video přesně ukazuje, jak taková konverzace obvykle dopadá."]]},"p-economy-18":{"t":"Nic se nehýbe","x":"Přístavní dělníci v přístavu Harlow zastavili nakládku kvůli mzdovému sporu a ministr financí říká, že čtyřicet procent dováženého zboží teď kotví na lodích u pobřeží. „Každý další den,“ říká, „je za šest týdnů den prázdných regálů.“","c":[["Poslat federální dodavatele, ať lodě naloží sami","Dodavatelé jsou pomalí a nezkušení. Přístavní dělníci jsou teď rozzuření z úplně jiného důvodu."],["Financovat nezávislého mediátora, aby mzdový spor spravedlivě urovnal","Trvá to dva týdny a přinese to férovou smlouvu. Lodě se konečně dají do pohybu."],["Vyvolat mimořádný pracovní zákon, aby se dělníci okamžitě vrátili","Přístav se pod protesty znovu otevírá. Spor se prostě přesune do podzemí."],["Osobně vyjednávat přes hlasitý telefon z Resolute Desk","Hovor trvá čtyři hodiny a hlasitě nedosáhne téměř ničeho."]]},"p-economy-19":{"t":"Přátelský monopol","x":"Regulátoři zahájili antimonopolní šetření proti Halcyon Systems, technologickému gigantu, jehož generální ředitel náhodou štědře přispíval na vaše poslední dvě kampaně. „Důkazy jsou opravdu zdrcující,“ říká ministr financí. „Stejně tak i načasování vašich hovorů s ním.“","c":[["Potichu nechat šetření zaškatulkovat jako profesní laskavost","Šetření zmizí. Jeden velmi vytrvalý novinář nezmizí."],["Nechat regulátory dělat svou práci bez zásahů","Halcyon Systems je vysoce pokutován. Ředitel vám přestane brát hovory."],["Prohlásit šetření za politicky motivované kariérními úředníky","Regulátoři jsou přeloženi. Halcyon Systems posílá velmi štědrý dárek na poděkování."],["Navrhnout Halcyonu, ať se prostě přejmenuje, aby nezněl tak monopolně","Halcyon Systems se stává Halcyon Přátelské Systémy. Podíl na trhu zůstává identický."]]},"p-economy-20":{"t":"Na dně","x":"Váš příspěvek ve tři ráno, který nazval velkou automobilku „hanbou a podvodem“, smazal ze společnosti čtyřicet miliard dolarů za devadesát minut a tisková mluvčí odpovídá na hovory od každého ekonomického oddělení v zemi. „Pane prezidente, chtějí vědět, jestli to bylo úmyslné.“","c":[["Přitvrdit a napsat, že si firma zasloužila ještě víc","Akcie klesnou ještě víc. Vaše základna to nazývá zodpovědností."],["Potichu příspěvek smazat a dál nic neříkat","Akcie se částečně zotaví. Smazání se stává vlastním malým skandálem."],["Tvrdit, že propad na trhu dokazuje, že firma byla vždy zkorumpovaná","Neexistuje žádný důkaz korupce. Existuje teď kongresové vyšetřování vašeho příspěvku."],["Zveřejnit fotku sebe, jak si přesto kupujete auto té značky","Akcie o dvě procenta stoupnou. Nikdo úplně nechápe, proč to zabralo."]]},"p-economy-21":{"t":"Strop","x":"Kongres se zablokoval kolem zvýšení dluhového stropu a ministryně financí říká, že vládě dojdou účetní triky za jedenáct dní. „Pak,“ říká, „budeme vybírat mezi platem vojáků a platbou držitelům dluhopisů.“","c":[["Vyhrožovat ražbou pamětní bilionové mince a vyzvat je, ať protestují","Mince je právně sporná a nesmírně populární. Kongres se v naprosté trapnosti do pár dní vzdá."],["Obvolávat vedení Kongresu kvůli dvoustranické dohodě","Dohoda je nevzhledná, včasná a nikdo mimo Washington si nevšimne, že se to stalo."],["Vinit opoziční stranu, že drží platy vojáků jako rukojmí","Opozice vinu hodí zpátky na vás. Termín se blíží tak jako tak."],["Navrhnout platit držitelům dluhopisů pamětními mincemi místo hotovosti","Držitelé dluhopisů nejsou pobavení. Mince jsou, uznejme, docela pěkné."]]},"p-economy-22":{"t":"Šek pro farmáře","x":"Pěstitelé sóji ve čtyřech státech čelí odvetným clům soupeřící velmoci a úrodě, kterou nemají komu prodat. Ministr zemědělství navrhuje nouzový záchranný šek a pak tiše dodává: „Minule to šlo hlavně velkým podnikům, ne rodinným farmám.“","c":[["Poslat šeky rychle a detaily řešit později","Šeky přijdou do týdne. Stejně tak i příběhy o tom, které farmy dostaly ty největší."],["Navrhnout cílený program, který skutečně upřednostní malé rodinné farmy","Trvá to o tři týdny víc papírování a dostane se k farmářům, kteří to potřebovali nejvíc."],["Vést dodatečné záchranné prostředky přes nadaci velkého sponzora","Sponzorova nadace si účtuje pěkný administrativní poplatek. Farmáři dostanou zbytek."],["Uspořádat fotoop na balíku sena a slíbit, že šeky jsou už na cestě","Balík sena vypadá na fotce skvěle. Šeky ve skutečnosti na cestě nejsou."]]},"p-economy-23":{"t":"Levná ocel","x":"Foundry Nation vyváží dotovanou ocel na americký trh za polovinu domácí ceny a tři další huti hrozí zavřením do zimy. „Je to podle obchodního práva nezákonné,“ říká ministr financí, „a zároveň to pro ně funguje přesně podle plánu.“","c":[["Okamžitě uvalit mimořádná cla na veškerý dovoz oceli","Domácí huti jásají. Každé odvětví, které ocel kupuje na stavbu věcí, potichu sténá."],["Podat formální obchodní stížnost správným mezinárodním kanálem","Je to správný postup. Trvá to také osmnáct měsíců, které žádná huť nemá."],["Vyhlásit úplné obchodní embargo na Foundry Nation kvůli oceli","Foundry Nation do hodiny oplatí odvetou na sóje. O tu vůbec nešlo."],["Uspořádat mítink v huti s helmou na hlavě pro kamery","Helma vypadá na fotce skvěle. Huť o dva měsíce později stejně zavře."]]},"p-economy-24":{"t":"Kupujte americké (platí podmínky)","x":"Nová iniciativa Kupujte americké odstartuje zítra s vlajkami, ohňostrojem a znělkou. Vedoucí kanceláře právě zjistila, že oficiální merch ze startu, čepice vietně, se vyrábí kompletně v zahraničí. „Zásilku ještě můžeme zrušit,“ říká. „Už je ale na lodi.“","c":[["Spustit to stejně a doufat, že si nikdo nevšimne štítků","Někdo si štítků všimne do hodiny. Znělka hraje dál."],["Odložit spuštění a zajistit merch z domácích zdrojů","Spuštění se opozdí o tři týdny, čepice vietně, štítky konečně pravdivé."],["Tvrdit, že zahraniční továrna je tajně vlastněná Američany","Není vlastněná Američany. Na mítinku se to tvrzení stejně opakuje."],["Přejmenovat čepice na „Skoro kupujte americké“","Čepice se vyprodají. Fráze se do večera stane nešťastným memem."]]},"p-money-1":{"t":"Nápadník s národním fondem","x":"Fond z „přátelské zálivové monarchie“ chce koupit golfová letoviska vaší rodiny za trojnásobek tržní ceny. Ministryně financí pořád opakuje „žádné podmínky navíc“, jako by ta fráze podmínky smazala. „Chtějí jen být vašimi partnery,“ říká a posouvá k vám smlouvu.","c":[["Podepsat, poslat hotovost","Peníze dorazí do pátku. Novináři začnou počítat vaše pískové bunkry."],["Vést je přes svěřenský fond bez vlivu","Nudné, legální, a nikdo vám za to neuspořádá přehlídku."],["Vzít si hotovost i práva na pojmenování","Osmnáctá jamka se teď jmenuje Jamka číslo jedna. Nenápadné."],["Trvat na tom, že budete zaplaceni ve zlatých cihlách","Celníci mají k té paletě spoustu otázek."]]},"p-money-2":{"t":"Spuštění memecoinu","x":"Váš syn chce spustit prezidentský memecoin, ještě než dokončíte ranní briefing. „Není to úplatek, tati, je to komunita,“ říká, už oblečený v mikině s logem. Velcí hráči se řadí, aby nakoupili za cenu, kterou už nikdy nikdo jiný neuvidí.","c":[["Nechat ho to spustit, vzít si podíl","Graf jde vertikálně nahoru, pak do strany, pak do skupinového chatu o žalobách."],["Zastavit to, než to začne","Syn se durdí. Etičtí právníci si poprvé po týdnech oddechnou."],["Spustit to a přidat sadu NFT k tomu","Někde si muž zastaví dům kvůli obrázku kresleného orla."],["Přejmenovat to po svém psovi","Psí mince do úterý předčí skutečnou měnu."]]},"p-money-3":{"t":"Výhodný pozemek","x":"Developer vám chce prodat pobřežní pozemek za dolar a pak potichu přeplánovat zbytek pobřeží kolem něj. Váš právník to nazývá „dárkem s výborným načasováním“. Ani nemrkne, když to řekne.","c":[["Koupit pozemek za dolar, schválit přeplánování","Teď vlastníte pláž. Také několik nových nepřátel na stavebním úřadě."],["Zaplatit plnou tržní cenu, vyloučit se z rozhodování","Developer je zmatený. Vaše jmění se sotva pohne."],["Vzít si pozemek a rozprodat celý poloostrov","Poloostrov se teď jmenuje resort. Slovo „pobřeží“ je teď historický pojem."],["Žádat platbu v pobřežních kabinách místo hotovosti","Vlastníte jedenáct kabin a nemáte tušení, co s nimi."]]},"p-money-4":{"t":"Hra na skořápky","x":"Vaše generální prokurátorka potřebuje podpis na formalizaci holdingové společnosti, která na papíře existuje jen kvůli přijímání zahraničních konzultačních poplatků. „Je to formalita,“ říká a poklepává na složku. „Ta formalita jen náhodou pere peníze.“","c":[["Podepsat bez čtení","Papíry zmizí v šuplíku úřadu ve státě, kam nikdo nejezdí."],["Odmítnout a složku skartovat","Prokurátorka vypadá zklamaně, ale dnes nic nezákonného nepodá."],["Podepsat a přidat další dvě skořápky","Teď máte firemní rodokmen, na který se žádný auditor nechce šplhat."],["Pojmenovat skořápkovou firmu po sobě, bez maskování","Nenápadnost nikdy nebyla vaše silná stránka."]]},"p-money-5":{"t":"Etický spis","x":"Úřad pro vládní etiku potichu otevřel spis k vašim financím. Vedoucí kanceláře se ptá, jestli byste to nechtěl „předběhnout“, než to udělá novinář. „Předběhnout“ v té větě dře jako mezek.","c":[["Zamést spis pod koberec, přeřadit vyšetřovatele","Vyšetřovatel je teď náměstek zástupce náměstka někde v mrazu."],["Zveřejnit své finance dobrovolně","Čísla jsou nudná. Nudné je, výjimečně, vítězství."],["Zamést spis pod koberec a místo toho prověřit novináře","Novinářovy daně jsou najednou pro finanční úřad velmi zajímavé."],["Přejmenovat spis na performativní umění","Galerie v Berlíně nabízí vystavit vaše bankovní výpisy."]]},"p-money-6":{"t":"Honorář za přednášku","x":"Obchodní sdružení vám chce zaplatit čtyři sta tisíc dolarů za dvacetiminutovou „hlavní řeč“ týden poté, co podepíšete jejich oblíbenou daňovou výjimku. Vedoucí kanceláře trvá na tom, že „tak to na okruhu prostě chodí“.","c":[["Vzít honorář, přednést řeč","Dvacet minut potlesku, čtyři sta tisíc dolarů, žádné poznámky."],["Odmítnout honorář, podepsat zákon na základě jeho merit","Sdružení je zmatené. Zmatek se, ukazuje se, dá mít zdarma."],["Vzít honorář a přidat knižní smlouvu","Kniha se jmenuje Vítězství a skládá se hlavně z poděkování."],["Žádat, ať je honorář zaplacen formou publicity","Publicita, ukazuje se, není zákonné platidlo, ale i tak si ji vezmete."]]},"p-money-7":{"t":"Licence na věž","x":"Zahraniční developer chce nalepit vaše jméno na napůl postavenou luxusní věž v zemi s pochybnou historií lidských práv. Váš tamní velvyslanec to nazývá „brandingovou příležitostí s výbornou marží“. O zřícení lešení se nezmiňuje.","c":[["Poskytnout licenci na jméno, vybrat poplatek","Věž je do čtvrtka přejmenována. Lešení zůstává nevyřešené."],["Licenci úplně odmítnout","Developer si najde jiné jméno k nalepení. Nějak je to v pořádku."],["Poskytnout licenci a přidat hotelové křídlo","Teď jsou tam dvě budovy s vaším jménem a jeden funkční výtah."],["Trvat na tom, že věž bude mít tvar vaší tváře","Řízení letového provozu žádá o přehodnocení nosu."]]},"p-money-8":{"t":"Skulina v zákoně","x":"Váš tým na financích navrhl daňové ustanovení tak specifické, že se v praxi vztahuje na jediný rodinný trust v Americe. Váš. „Zní to obecně,“ trvá ministryně. „Vztahuje se to na jakoukoli kvalifikující víceoborovou pohostinskou entitu s přesně vašimi vlastnostmi.“","c":[["Propašovat to do zákona, který musí projít","Nikdo si nepřečte stránku čtyři sta dvanáct. Vy si ji přečtete třikrát."],["Ustanovení sám škrtnout","Váš účetní tiše pláče ve vedlejší místnosti."],["Propašovat to a zpětně to rozšířit","Šek s vratkou dorazí dřív, než kdokoli dočte zákon."],["Pojmenovat skulinu po fiktivním voliči","Muž jménem Gary Skulina neexistuje, a přesto tu jsme."]]},"p-money-9":{"t":"Rodinná zakázka","x":"Startup vašeho syna, který nikdy nevydal žádný produkt, právě vyhrál devítimístnou federální zakázku na „modernizaci“ něčeho, co nikdo pořádně nedovede definovat. Novináři začali používat slovo „nepotismus“, jako by to byla nová informace.","c":[["Nechat zakázku platit","Startup najme recepční. Jistý druh pokroku."],["Zrušit ji a otevřít skutečné výběrové řízení","Syn s vámi týden nemluví. Pravděpodobně to stojí za to."],["Nechat ji platit a přidat druhou zakázku","Startup má teď dvě zakázky a pořád žádný produkt."],["Nechat ho se přerebranovat na neziskovku","Neziskovky si, jak se ukazuje, pořád mohou koupit pěknou loď."]]},"p-money-10":{"t":"Darovaná jachta","x":"Lodní magnát vám „daroval“ dvěstěstopovou jachtu a trvá na tom, že je to „jen půjčka, na neurčito, navždy“. Vedoucí kanceláře ji v podkladech k briefingu už přejmenovala, aby se vyhnula vyslovení slova „dar“.","c":[["Přijmout jachtu, potichu ji zakotvit","Jachta je teď technicky muzeum, což technicky není úplatek."],["Odmítnout ji, nabídku nahlásit","Magnát je ohromený. Odmítání darů je zjevně vzácnost."],["Přijmout ji a odpovídající helikoptéru k tomu","Na klimatické summity teď přiletíte helikoptérou. Tým pro image dá výpověď."],["Přejmenovat jachtu na „Prezidentský čas“","„Prezidentský čas“ je za týden spatřen u tří různých pobřeží."]]},"p-money-11":{"t":"Vděčná obálka","x":"Muž, kterého jste na jaře omilostnili, nechal u vašeho osobního asistenta tašku „pro nadaci“. Nikdo se nezeptal pro kterou. Váš právník jemně naznačuje, že tašky hotovosti jsou „přinejmenším otázka image“.","c":[["Nechat si to, mlčet","Taška zmizí v trezoru, který se neobjeví v žádném inventáři."],["Vrátit ji a nahlásit toho, kdo o milost žádal","Muž je zuřivý. Právník, výjimečně, vypadá úlevně."],["Nechat si to a zeptat se, jestli přijde víc","Přijde skutečně víc. A pravidelně, jak se ukáže."],["Darovat to nadaci, kterou jste si právě vymyslel","Nadace má jediného zapsaného zaměstnance, a to jste vy."]]},"p-money-12":{"t":"Blokové rezervace","x":"Zahraniční delegace si právě zarezervovala celý váš hotel na státní návštěvu, za noční sazbu, kterou vlastní personál nazývá „ambiciózní“. Váš poradce pro vnitřní bezpečnost věcně poznamenává, že Ústava k tomuto téma má názor.","c":[["Přijmout rezervaci za plnou sazbu","Lobby voní čerstvými penězi a mírným porušením ústavy."],["Přesměrovat je do konkurenčního hotelu","Váš generální manažer je zdrcený. Ústava méně."],["Přijmout to a nabídnout jim navíc prezidentský apartmán","Apartmán stojí víc než dům většiny lidí. Týdně."],["Pokoj poskytnout zdarma a účtovat jim minibar","Účet za minibar sám o sobě financuje malé velvyslanectví."]]},"p-money-13":{"t":"Národní kryptorezerva","x":"Ministryně financí navrhuje, aby vláda držela „strategickou rezervu“ mince, které náhodou vlastníte velké množství vy osobně. „Je to progresivní krok,“ říká. „Je to taky vaše mince,“ říkáte. Nesouhlasí.","c":[["Oznámit rezervu","Vaše podíly ztrojnásobí hodnotu ve chvíli, kdy tisková zpráva vyjde."],["Nápad úplně zrušit","Trh zívne. Vaše portfolio zívá s ním."],["Oznámit to a nejdřív si přikoupit víc","Načasování, jak se říká, je vše, a to vaše bylo bezchybné."],["Přejmenovat rezervu po budově ministerstva financí","FortKnoxCoin trenduje šest hodin, pak z právních důvodů potichu skončí."]]},"p-money-14":{"t":"Předstih","x":"Váš zpravodajský briefér skoro jistě omylem prozradil detail o přezkumu fúze, který ještě nebyl oznámen. Váš makléř je jednu esemesku od přesné vědomosti, co koupit dřív, než to udělá trh.","c":[["Poslat tu esemesku","Obchod projde. Algoritmus SEC bohužel taky vnímá vzorce."],["Zprávu smazat, nikoho neinformovat","Nic se nestane, což je přesně smyslem toho cvičení."],["Poslat ji a zapojit dva sponzory","Tři portfolia přes noc rozkvetou. Jeden analytik klade příliš mnoho otázek."],["Obchodovat opačným směrem jako klamnou stopu","Klamná stopa prodělá peníze, což je nějak nejpřesvědčivější část."]]},"p-money-15":{"t":"Charitativní gala","x":"Nadace vaší dcery vybrala na včerejším gala jedenáct milionů dolarů. Záznamy ukazují, že dva miliony šly do stipendijního fondu a devět milionů do „provozu“, kategorie, která se skládá hlavně ze samotného gala.","c":[["Nechat účetnictví tak, jak bylo podáno","Stipendijní fond dostane pěknou tabulku. Zbytek dostane ještě lepší párty."],["Nařídit plný nezávislý audit","Audit je nemilosrdný. Tabulka naštěstí přežije."],["Přidat do správní rady další dva příbuzné","Nadace teď zaměstnává víc rodiny než skutečného personálu."],["Přejmenovat ji na Fond prezidentské excelence","Excelence, podle výkazů, stojí docela dost na správu."]]},"p-money-16":{"t":"Aukce členství","x":"Váš golfový klub potichu draží členství lobbistům za absurdní přirážky se šeptaným příslibem „přístupu“. Vedoucí kanceláře žádá váš souhlas s ceníkem před pondělními tee-timy.","c":[["Schválit ceník","Pořadník se zaplní muži, kteří nikdy nedohráli pod devadesát ran."],["Omezit poplatky za členství na tržní úroveň","Klub je náhle mnohem méně ziskový a mnohem méně zajímavý."],["Schválit to a přidat úroveň jen pro lobbisty","Nová úroveň zahrnuje skříňku a zjevně i vaše telefonní číslo."],["Prodávat členství formou tomboly místo toho","Penzionovaná učitelka vyhraje skříňku vedle vojenského dodavatele."]]},"p-money-17":{"t":"Merch kolekce","x":"Vaše ředitelka sociálních sítí chce spustit limitovanou edici tenisek, hodinek a balíčku s pamětní Biblí, prodávanou výhradně přes firmu, kterou náhodou vlastníte. „Vlastenectví,“ říká, „se zdravou přirážkou.“","c":[["Spustit kolekci","Bible se vyprodají. Nikdo nekontroluje, kdo je tiskl, ani kde."],["Místo toho darovat zisk na charitu","Prodeje klesnou ve chvíli, kdy zisk přestane téct k vám. Zvláštní."],["Spustit to a přidat kolínskou","Kolínská se jmenuje Autorita. Voní vzdáleně po kůži a žalobách."],["Prodávat tenisky jen členům Kongresu","Polovina sněmovny teď nosí do práce stejné boty."]]},"p-money-18":{"t":"Zlaté vízum","x":"Ministerstvo zahraničí navrhuje nový investiční vízový program s neobvykle velkorysou výjimkou: žadatelé, kteří investují přímo do nemovitostí vaší rodiny, projdou frontou za poloviční čas. Ministr zahraničí to nazývá „pilotním programem“.","c":[["Schválit rychlou linku","Pořadník na vaše nemovitosti je najednou mnohem kratší a mnohem bohatší."],["Před schválením výjimku odstranit","Program projde čistě. Vašemu účetnímu to nějak připadá skoro zklamáním."],["Schválit to a výjimku rozšířit","Polovina žadatelů teď uvádí vaše budovy jako celou svou investiční strategii."],["Požadovat, aby si žadatelé taky koupili tenisky","Imigrační právo a obuv se spojí způsobem, který nikdo nečekal."]]},"p-money-19":{"t":"Podcastové impérium","x":"Nová podcastová síť vašeho syna chce prodávat „přístupové balíčky“ hostům, kteří chtějí sedět s vámi na rozhovoru. Sazba za přátelských třicet minut je vysoká a stoupá. „Je to jen obsah,“ říká.","c":[["Schválit přístupové balíčky","Rozvrh rozhovorů teď vypadá jako velmi drahá seznamka."],["Zpřístupnit rozhovory zdarma a rovnocenně všem","Rezervace se propadnou. Stejně tak, nápadně, i příjmy sítě."],["Schválit to a přidat VIP after-party úroveň","VIP úroveň zahrnuje fotku, podání ruky a velmi vysokou fakturu."],["Vyměňovat rozhovory za podíly ve firmách místo peněz","Teď spoluvlastníte tři startupy, které nedokážete úplně vysvětlit."]]},"p-money-20":{"t":"Mince s tváří","x":"Mincovna chce razit pamětní minci s vaším profilem, prodávanou sběratelům za vysokou přirážku, s tantiémami vedenými přímo na váš osobní účet. Ministryně financí přísahá, že je to „pro mincovnu úplně normální“.","c":[["Schválit minci, vzít si tantiémy","Mince se vyprodá do hodiny. Numismatici k tomu mají co říct."],["Schválit minci, tantiém se vzdát","Mincovna vydělá. Vy ne. Titulek je tam nějak stejně."],["Schválit to a přidat i zlatou edici","Zlatá edice stojí víc než auto většiny lidí."],["Dát na rub svého psa","Psí mince do týdne prodejně předčí prezidentskou."]]},"p-money-21":{"t":"Slepý fond, který slepý není","x":"Správce vašeho „slepého fondu“ vám právě volal zeptat se, cituji, „které nemovitosti byste chtěl tento kvartál koupit“. Váš právník připomíná, že celý smysl slepého fondu je, že tohle nemáte vědět.","c":[["Potichu dál radit","Fond funguje podezřele dobře na něco, co nevidí."],["Předat skutečnou kontrolu nezávislému správci","Vaše portfolio je nudné. Váš právník poprvé po měsících spí."],["Dál to řídit a rozšířit portfolio","Fond, který není slepý, teď nevidí ještě víc nemovitostí."],["Přejmenovat fond na „Rozhodně slepý s.r.o.“","Jméno neoklame vůbec nikoho, nejméně ze všech auditory."]]},"p-money-22":{"t":"Fond na knihovnu","x":"Zahraniční miliardáři se řadí do fronty, aby financovali vaši budoucí prezidentskou knihovnu, žádné podmínky, kromě těch, kteří se o ní zmíní těsně předtím, než regulační rozhodnutí dopadne v jejich prospěch. Váš dvorní historik nazývá ten vzorec „náhodou hodnou studia“.","c":[["Přijmout každý dar","Slavnostní výkop má nezvykle mezinárodní seznam hostů."],["Omezit dary a zveřejnit všechny dárce","Fundraising se zpomalí na plazivé tempo. Zeď se jmény je najednou mnohem méně zajímavá."],["Přijmout každý dar a přidat křídlo pro každého miliardáře","Knihovna má teď čtyřicet křídel a zhruba čtyři skutečné knihy."],["Prodat i práva na pojmenování obchodu se suvenýry","Obchod se suvenýry generuje víc příjmů než archiv, ke kterému patří."]]},"p-phone-1":{"t":"Ospalý spojenec","x":"Vedoucí kanceláře vás budí ve tři ráno, protože jste už vytočil premiérku Halvorsenovou a ta je teď na lince a ptá se, proč křičíte kvůli narušení hranice. „Pane prezidente,“ říká, „to je mýval.“ Vedoucí kanceláře bezhlesně artikuluje „zavěste už“, zatímco drží telefon na délku paže.","c":[["Nařídit jí mobilizovat vojáky proti mývalovi","Sedmnáct vojáků obklíčí popelnici. Mýval vítězí."],["Omluvit se, zavěsit, nechat tu ženu spát","Odpustí vám. Také vaše číslo umlčí."],["Obvinit ji, že mývala kryje jako špiona","Menší spojenec je teď velká bolest hlavy."],["Oslovovat mývala křestním jménem a nabídnout mu azyl","Mýval, Gerald, má teď osobní ochranku."]]},"p-phone-2":{"t":"Dnešní body k diskusi","x":"Moderátor Chip Bellamy volá dvacet minut před vysíláním a žádá, ať mu osobně nadiktujete dnešní titulek. „Dej mi něco s ostrými zuby,“ říká, „sledovanost klesá a producent hrozí, že mě nahradí zlatým retrívrem.“ Vaše tisková mluvčí se už potí skrz sako.","c":[["Nakrmit ho skandálem, který technicky ještě neexistuje","Titulek zní PŘELOMOVÁ ZPRÁVA a nic dalšího na tom není pravda."],["Odmítnout, odkázat ho na skutečný tiskový úřad","Zlatý retrívr dostane segment. Zvládá to skvěle."],["Nakrmit ho skandálem o konkrétním senátorovi","Senátor se to dozví živě ve vysílání od Chipa."],["Nabídnout se jako spoluhostitel, bez scénáře, hned teď","Sledovanost se ztrojnásobí. Nikdo neumí vysvětlit, co bylo řečeno."]]},"p-phone-3":{"t":"Medaile, kterou jste si nezasloužili","x":"Předseda Chen volá pogratulovat vám k vyjednání míru v regionálním konfliktu, o kterém jste v životě neslyšeli. „Vaše diplomacie,“ říká vřele, „bude připomínána po generace.“ Váš poradce pro národní bezpečnost horečně googluje, o jaký konflikt by mohlo jít.","c":[["Přijmout zásluhu a naznačit kampaň na Nobelovu cenu","Teď dlužíte Chenovi laskavost za válku, kterou jste neukončili."],["Přiznat, že netušíte, o čem mluví","Chen je nadšený. Zmatek, jak se ukazuje, respektuje."],["Přijmout zásluhu a žádat summit na vaši počest","Summit se naplánuje. Válka, stále probíhající, na něj pozvána není."],["Požádat Chena, ať vám detaily jednoduše pošle mailem později","Mail nikdy nedorazí. Jasno taky ne."]]},"p-phone-4":{"t":"Sponzor na lince jedna","x":"Bradlee Wickham, který osobně financoval čtyři billboardy a pochodovou kapelu, volá připomenout vám, že jistá ekologická regulace „zabíjí americká pracovní místa, nebo aspoň moje kvartální čísla“. Letos už dvakrát přispěl na vaši reelekci. Ministr financí drží ceduli s nápisem KONFLIKT ZÁJMŮ.","c":[["Slíbit, že regulaci do pátku vykucháte","Pátek přijde. Stejně tak žaloba."],["Poděkovat mu za podporu a nic neměnit","Billboardy jdou dolů. Pochodová kapela se rozpustí."],["Regulaci vykuchat a pojmenovat ji po něm","Wickhamův zákon do měsíce otráví řeku."],["Požádat ho, ať si radši rovnou koupí tu řeku","Koupí ji. Je nadšený. Ryby ne."]]},"p-phone-5":{"t":"Uražený emír","x":"Emír, kterého jste na mítinku minulý týden nazval „chlapíkem v hábitu s příliš velkým balíkem naftových peněz“, je na lince a slyšitelně se nesměje. „Omluvíte se,“ říká, „nebo je dohoda o ropovodu mrtvá.“ Váš velvyslanec stojí za vámi a tiše se modlí.","c":[["Bohatě se omluvit a slíbit mu státní večeři","Přijme to. Poznámka o hábitu se v jeho zemi stane potiskem na tričku."],["Nabídnout vyváženou, profesionální omluvu a hovor ukončit","Ropovod přežije. Nikdo se nebaví."],["Přitvrdit a nazvat ho chlapíkem v hábitu znovu, do očí, v hovoru","Dohoda o ropovodu je mrtvá. Ceny ropy si toho okamžitě všimnou."],["Pochválit konkrétně ten hábit a zeptat se, kde ho sehnal","Řekne vám to. Je z obchoďáku. Oba jste nadšení."]]},"p-phone-6":{"t":"Uniklý hovor","x":"Nahrávka včerejšího hovoru, ve které jste tři světové lídry nazval „smutný, hlasitý a Steve“, unikla současně do všech sítí. Vaše tisková mluvčí drží čtyři zvonící telefony a nezvedá žádný. „Steve to nebere s humorem,“ hlásí.","c":[["Tvrdit, že nahrávka je falešná, vytvořená AI, hluboce lichotivá pro Steva","Steve zveřejní vlastní nahrávku. Je pravá."],["Přiznat to, omluvit se všem třem, hlavně Stevovi","Steve to přijme. Měl, jak se ukázalo, náročný týden."],["Uniknout ještě horší nahrávkou někoho jiného, aby se to zamlžilo","Šest hodin to funguje. Pak unikne i tohle."],["Ze solidarity si začít sám říkat Steve","Matoucí. Také, podivně, se vám to počítá v průzkumech."]]},"p-phone-7":{"t":"Linka s rukojmími","x":"Vyjednavač FBI je uprostřed hovoru s mužem, který drží tři bankovní úřednice, když vás k hovoru omylem někdo připojí. „Tady prezident,“ řeknete, protože se nedokážete udržet, a vyjednavačova tvář zbledne jako kancelářský papír. Únosce, potěšený, se ptá, jestli by to nešlo streamovat živě.","c":[["Souhlasit, mohla by z toho být skvělá televize","Sledovanost je historická. Stejně tak zpráva FBI o incidentu."],["Okamžitě zavěsit a nechat pracovat profesionála","Úřednice se v pořádku vrátí domů. Vaše vystoupení si nikdo nepamatuje."],["Vyjednávat osobně, nabídnout únosci milost","Vzniká precedens. Každá banka v zemi si toho všimne."],["Zazpívat happy birthday tomu, kdo v bance má nejblíž narozeniny","Všichni jsou zmatení natolik, že se trochu uklidní."]]},"p-phone-8":{"t":"Zelená, tak nějak","x":"Generál Ostrander volá pro povolení k útoku, na kterém už technicky začal pracovat. „Pane prezidente, potřebuju ano nebo ne do devadesáti vteřin,“ říká. Vy jste zrovna sledoval dokument o rybaření na okouny a zachytili jste tak čtyřicet procent z toho, co právě řekl.","c":[["Říct ano s naprostou jistotou, ptát se později","Útok proběhne. Stejně tak kongresové slyšení."],["Žádat ho, ať vás pořádně informuje před rozhodnutím","Okno se zavře. Generál je zuřivý. Ústava méně."],["Říct ano a přidat dva cíle, které vás právě napadly","O druhý cíl nikdo nežádal. Ani o třetí."],["Nechat ho čekat, než dokoukáte pořad o rybaření","Generál čeká. Okoun bohužel unikne."]]},"p-phone-9":{"t":"Laskavost","x":"Trent Halloway ze Silicon Valley volá zeptat se, velmi ledabyle, jestli by se regulátoři nemohli „podívat na“ aplikaci jeho konkurenta. „Nic šíleného,“ říká, „jen trochu přátelské antimonopolní pozornosti.“ Bez vyzvání také zmíní, že příští měsíc pořádá fundraiser.","c":[["Slíbit, že na konkurenta pošlete regulátory","Konkurentova aplikace záhadně neprojde třemi audity."],["Říct mu, že regulátoři takhle nefungují, zavěsit","Halloway je ohromený, že peníze nezafungovaly okamžitě."],["Slíbit laskavost a žádat ještě větší fundraiser","Laskavost se udělí. Dopad na image je katastrofální."],["Požádat Hallowaye, ať vám místo toho postaví aplikaci","Postaví ji za víkend. Sleduje něco znepokojivého."]]},"p-phone-10":{"t":"Špatná země","x":"Uprostřed hovoru se zahraničním ministrem sebejistě poděkujete Belgii za podporu v tichomořském dějišti. Nastane dlouhá pauza. „Pane prezidente,“ říká ministr opatrně, „my jsme Bolívie.“ Vaše vedoucí kanceláře fyzicky opustila místnost.","c":[["Trvat na tom, že jste celou dobu myslel Bolívii","Bolívie tomu nevěří. Belgie taky ne, jakmile se to doslechla."],["Omluvit se za záměnu jako dospělý člověk","Ministr to velkoryse přijme. Klip se stejně odvysílá."],["Nahlas v hovoru obvinit svůj personál","Personál slyší každé slovo. Morálka, už tak křehký zdroj, klesá."],["Požádat ho, ať vám po zbytek hovoru prostě říká, s kým vlastně mluvíte","Řekne vám to. Pomůže to. Trochu."]]},"p-phone-11":{"t":"Kapesní vytáčení","x":"Váš komorník vám s výrazem hlubokého osobního utrpení oznámí, že jste kapsou vytočil čtyřicetiminutovou nelichotivou tirádu o viceprezidentovi přímo investigativní novinářce. Novinářka je pořád na lince. Říká: „Prosím, pokračujte.“","c":[["Pokračovat v mluvení, ona je vlastně skoro jako tiskový sbor","Čtyřicet minut se stane čtyřicetiminutovou titulní story."],["Okamžitě zavěsit a zavolat právníkovi","Story vyjde stejně, pod titulkem CO JSME NEMĚLI SLYŠET."],["Pokračovat v mluvení a jít ještě dál, jmenovat konkrétní věci","Konkrétní věci se stanou titulkem. Viceprezident si to přečte dvakrát."],["Pozvat ji na oběd, probrat to neoficiálně","Přijme to. Nic na tomhle není neoficiální."]]},"p-phone-12":{"t":"Mnoho šťastných návratů","x":"Prezident Volkov volá popřát vám k narozeninám, hlas vřelý jako čerstvý asfalt. „Šedesát let,“ říká, „jaký křehký věk pro muže s tolika nepřáteli.“ Pak se, pořád vřele, zeptá, jestli vaše kódy k raketové obraně letos „dobře vydržely“.","c":[["Odbýt to smíchem a pozvat ho na inauguraci příští rok","Pozvání přijme. Vaše ochranka týden nespí."],["Zavěsit a informovat Radu národní bezpečnosti","Nic se nestane. Paranoia byla tentokrát oprávněně cvičná."],["Vyhrožovat mu zpátky, zmínit, že jeho narozeniny se taky blíží","Volkovovy narozeniny jsou v prosinci. Tenhle hovor si dobře zapamatuje."],["Zazpívat si happy birthday sám sobě, zatímco poslouchá","Hluboce zvláštní. Volkov, výjimečně, nemá co dodat."]]},"p-phone-13":{"t":"Hovor od někoho, koho obdivujete","x":"Polní maršál Baako, muž, kterého jste soukromě na třech různých večeřích nazval „efektivním“, volá nabídnout „přátelskou radu ohledně zvládání disentu“. Váš ředitel rozvědky poslouchá s vypnutým mikrofonem a v duchu sepisuje výpověď.","c":[["Podrobně si zapisovat, upřímně mu poděkovat","Poznámky unikají o osmnáct měsíců později. Znějí přesně tak zle, jak se obáváte."],["Zdvořile radu odmítnout a hovor ukončit","Baako je uražený. Ředitel rozvědky poprvé po deseti minutách vydechne."],["Požádat ho, ať radu pošle písemně, na hlavičkovém papíře","Hlavičkový papír je pravý. Stejně tak nakonec i předvolání k němu."],["Stočit hovor na jeho péči o pleť","Sdílí ji, nevyžádaně a zeširoka. Zahrnuje spoustu vaječných bílků."]]},"p-phone-14":{"t":"Špatné číslo","x":"Vytočíte číslo, o kterém si myslíte, že patří ministru vnitřní bezpečnosti, a místo toho zastihnete penzionovanou dentální hygienistku jménem Carol z Toleda. O čtyřicet minut později znáte celou fotbalovou sezónu jejího vnuka a ona ví víc o přezkumu jaderné doktríny než většina senátorů. Váš hlavní komorník stojí ve dveřích a neví, co si s tím počít.","c":[["Pozvat Carol na kávu do Bílého domu","Carol přijde. Carol má názory na záclony."],["Omluvit se, zavěsit, skutečně vytočit ministra","Ministr je zmatený, že už o přezkumu doktríny víte."],["Zeptat se Carol, co byste podle ní měl s doktrínou udělat","Carolina rada je, znepokojivě, přijata na příštím briefingu."],["Dát Carol na místě vymyšlený oficiální titul","Zvláštní vyslankyně Carol má teď parkovací místo u Pentagonu."]]},"p-phone-15":{"t":"Ultimátum předsedy","x":"Předseda centrální banky Otis Brandt volá znovu vám oznámit, že nemůžete jen tak „poprosit hezky“ o snížení sazeb. „Nezávislost,“ říká, „je tak trochu celý smysl mé existence.“ Tento týden jste už čtyřikrát napsal, že je „slabý, ospalý a možná špión“.","c":[["Přesto žádat snížení a vyhrožovat výpovědí","Trhům se ta hrozba nelíbí. Technicky ani zákonu."],["Přijmout jeho nezávislost a zavěsit zdvořile","Sazby zůstávají. Stejně tak, většinou, i váš krevní tlak."],["Žádat snížení a uniknout jeho domácí adresu do rozhlasu","Brandt si najme víc ochranky. Sazba zůstává stejná stejně tak."],["Nabídnout mu výměnou za snížení sazby vstupenky na rybářský výlet","Odmítne. Doporučí vám ale dobré jezero."]]},"p-phone-16":{"t":"Volání jasnovidce","x":"Vaše dcera si z legrace do vašeho telefonu naprogramuje psychickou linku pod jménem „PORADCE PRO NÁRODNÍ BEZPEČNOST“. Madame Delphine na druhém konci vám sdělí, že „vás před úplňkem sklizně zradí muž s knírem“. Váš skutečný poradce pro národní bezpečnost knír má.","c":[["Preventivně propustit poradce s knírem","Byl až do této chvíle naprosto loajální."],["Zavěsit, zasmát se, zavolat dceři si postěžovat","Dcera je nekajícná. Stálo to za to."],["Zeptat se Madame Delphine i na politickou radu, když už ji máte na lince","Její předpověď se nesplní. Váš kabinet zjistí, že jste se ptal."],["Dát Madame Delphine smlouvu jako oficiální poradkyni","Znepokojivě má v pár věcech později pravdu."]]},"p-phone-17":{"t":"Obchodní příležitost","x":"Váš syn vás propojí s mužem jménem Chaz, který chce probrat „vážně vzrušující energetickou dohodu, naprosto košer, sotva nějaký Kazachstán v tom“. Syn mu už teď říká „parťáku“. Váš právní poradce Bílého domu si u stolu začal nalévat něco tvrdšího.","c":[["Přijmout schůzku, vyslechnout Chaze celou","Chazova naprosto košer dohoda je ve skutečnosti pod několika prkny."],["Zarazit to a říct synovi, ať takové hovory přestane brát","Syn se durdí. Chaz si najde jiného člena rodiny."],["Přijmout schůzku a zapojit syna jako konzultanta","Slovo „konzultant“ v té větě odvede spoustu práce."],["Požádat Chaze, ať pomalu vysvětlí, čím se vlastně živí","Nedokáže to. To řekne úplně všechno."]]},"p-phone-18":{"t":"Všechno se nahrává","x":"Váš šéf rozvědky vás upřed vytáčením varuje, že zahraniční prezident, kterému máte zavolat, prezident Alenko, je znám tím, že nahrává a nakonec zveřejňuje každý hovor jako páku. Voláte stejně, protože má skvělé drby o vzájemném rivalovi. Zvedne to už se smíchem.","c":[["Mluvit volně, drby stojí za to riziko","Drby byly skvělé. Přepis o šest měsíců později ne."],["Držet hovor krátký a bolestně profesionální","Alenko se nudí. Nudné je, výjimečně, tou strategií."],["Mluvit volně a přidat vlastní drb o senátorovi","Ten senátor se to nakonec dozví z Alenkových pamětí."],["Požádat Alenka, ať vám nahrávku pošle do vašeho vlastního alba","Pošle ji. Je, nějak, ještě horší, než jste si pamatoval."]]},"p-phone-19":{"t":"Lidový hrdina žertéř","x":"Muž, který si říká Vévoda z Toleda, tento měsíc jedenáctkrát prankově volal na ústřednu Bílého domu s neuvěřitelně věrnou imitací zahraniční hlavy státu. Tentokrát se dostane přímo k vám, uprostřed imitace, a internet ho už prohlásil za národní poklad. Vaše ředitelka sociálních sítí drží telefon se čtyřmi miliony zhlédnutí.","c":[["Hrát to naživo, udělat z něj oficiální hvězdu","Vévoda z Toleda dostane vlastní talk show. Vy dostanete bolest hlavy."],["Zpřísnit ústřednu a jít dál","Žertíky přestanou. Bohužel s nimi i jediná zábava, kterou kdokoli měl."],["Nabídnout mu jako odměnu skutečné vládní místo","Vévoda z Toleda je teď nějak náměstek tiskového mluvčího."],["Zkusit mu vrátit vlastní imitaci, bez přípravy","Stane se virální. Podle žádného měřítka to není dobrá imitace."]]},"p-phone-20":{"t":"Garda pro průvod","x":"Guvernér Ellsbury volá požádat o zápůjčku Národní gardy, ne kvůli nouzi, ale hlavně kvůli image, na přestřižení stuhy na krajském veletrhu. „Tanky na místních zprávách vážně fungují,“ vysvětluje. Asistent ministra obrany se někde mimo záběr viditelně modlí.","c":[["Schválit to, tanky na přestřižení stuhy zní zábavně","Stuha se přestřihne. Tank přejede stánek s trdelníky."],["Žádost zamítnout, garda není průvodová dekorace","Přestřižení stuhy proběhne, tragicky, jen s nůžkami."],["Schválit to a přidat i přelet pro dobrou míru","Přelet rozechvěje každé okno v kraji."],["Nabídnout mu místo toho vlastní pochodovou kapelu","Žádnou pochodovou kapelu nemáte. Teď ji budete muset sehnat."]]},"p-phone-21":{"t":"Hovor o záchraně","x":"Starostka Denise Okaforová volá při večeři vysvětlit, že její město je technicky bez peněz a mohlo by se opravdu hodit trochu federálního „něco“, žádné podmínky, nejsme vybíraví. Starostkou je šest týdnů. Dluh vznikl o dekádu dřív, než nastoupila.","c":[["Okamžitě poslat peníze, být hrdina","Šek projde. Podstata problému zůstává nedotčena."],["Vysvětlit správný rozpočtový proces a zavěsit","Město zůstává na mizině. Proces je aspoň respektován."],["Poslat dvojnásobek peněz a žádat sochu na oplátku","Socha je nelichotivá. Je také, technicky, nosná konstrukce."],["Nabídnout se, že rozpočet města osobně proauditujete hned po telefonu","Najdete čtrnáct chyb a žádná řešení. Všichni jsou vyčerpaní."]]},"p-phone-22":{"t":"Modlitební linka","x":"Pastor Michael Rourke chce, abyste hned teď živě vstoupil do jeho rozhlasového vysílání kvůli spontánní modlitbě za národ, kterou zjevně jeho producent předem naskriptoval. „Řekněte prostě, co máte na srdci,“ říká a drží kartičky, které nevidíte, ale rozhodně slyšíte šustit.","c":[["Přečíst každou kartičku slovo od slova, hlasitě a srdečně","Národ je požehnán. Národ si taky všimne toho šustění."],["Nabídnout krátké, upřímné, neskriptované slovo a odejít z vysílání","Krátké a důstojné. Sledovanost s důstojností bohužel nesouhlasí."],["Odchýlit se od scénáře a proměnit to v kampaňový projev","Pastor Rourke tohle s FCC nekonzultoval. Nikdo to nekonzultoval."],["Požádat celé publikum, ať se modlí konkrétně za váš golfový hendikep","Modlitby jsou zjevně vyslyšeny. Hendikep se zlepší o dvě rány."]]},"p-press-1":{"t":"Tři zdroje, jedna noční můra","x":"Beacon-Herald tvrdí, že tři nezávislé zdroje potvrzují, že jste osobně schválil plán nahradit Národní gardu ostrahou obchodních center. Dva ze zdrojů jsou stejný chlap, jen s jinými e-mailovými adresami.","c":[["Nazvat to koordinovaným podvodem","Vymyslíte pojem „falešné zdrojování“ a do oběda trenduje."],["Potvrdit ty nudné pravdivé části a jít dál","Story se scvrkne na jeden odstavec a do čtvrtka na ni všichni zapomenou."],["Zažalovat Beacon-Herald do bankrotu","Žaloba neuspěje, ale samotné právní poplatky jim naruší hlavičku listu."],["Oznámit, že strážní obchodních center dostanou federální penze","Sedmnáct hlídačů se přes noc stane lidovými hrdiny."]]},"p-press-2":{"t":"Fotka za tisíc rozzuřených slov","x":"Fotka, jak se smějete na státním pohřbu, je všude. Ve skutečnosti jste se smál asistentovu vyzvánění. Asistent si od té doby změnil vyzvánění i kariérní plány.","c":[["Trvat na tom, že fotku zfalšoval samotný zármutek","Nikdo technicky nedokáže vyvrátit, že zármutek má editor fotek."],["Zveřejnit celé video ukazující to vyzvánění","Klip je mírně vtipný a story potichu umře na kontext."],["Zakázat kamery do padesáti stop od jakékoli rakve","Pohřební ústavy teď vyžadují povolení a detektor kovů."],["Tvrdit, že jste ve skutečnosti plakal, jen s vyceněnými zuby","Bulvár otiskne titulek PLAKAL S VYCENĚNÝMI ZUBY."]]},"p-press-3":{"t":"Někdo v téhle budově má telefon na jedno použití","x":"Přepis schůzky vrcholného personálu se objeví online během hodiny, i s překlepy. Kdokoli to unikl, také potichu opravil vaši gramatiku, což nějak působí ještě hůř.","c":[["Svalit to na gramatické šprty z Hlubokého státu","Korektoři po celé zemi hlásí nárůst nenávistných dopisů."],["Nařídit tichou, zákonnou vnitřní kontrolu","Dva asistenti raději dají výpověď, než by si sedli na pohovor."],["Podrobit celý vrcholný personál polygrafu naživo na kameru","Sledovanost skvělá. Morálka personálu ne."],["Uniknout druhý, falešný přepis, aby se to zamlžilo","Tři zpravodajské servery teď stahují tři různé story."]]},"p-press-4":{"t":"Číslo, které nikdo nechce vyslovit nahlas","x":"Nový průzkum dává vaší popularitě dvacet dva procent, statisticky vyrovnaně s regionálním stažením vadné polévky z prodeje. Váš odborník na průzkumy popisuje tu polévku jako „na vzestupu“.","c":[["Prohlásit veškeré průzkumy za zahraniční spiknutí","Agentury pro výzkum veřejného mínění začnou cestovat se soukromou ochrankou."],["Uznat to číslo a nastínit skutečný plán","Politologové souhlasně přikyvují. Nikdo jiný si toho nevšimne."],["Zadat vlastní průzkum jen mezi příbuznými","Váš strýc bez vyzvání hlásí devadesát jedna procent podpory."],["Vyzvat polévku na veřejnou odvetu","Polévka nemůže legálně reagovat, a přesto to nějak vyhraje."]]},"p-press-5":{"t":"Noční talk show má scénku","x":"Skečová show odvysílá celé hudební číslo o jednáních vaší vlády, celé zahrané loutkami. Loutka hrající vás statečně zpívá falešně, což je celý vtip.","c":[["Vyhrožovat vysílací licenci té stanice","Právníci obou stran si koupí chaty na dovolenou."],["Poslat loutce vstřícný fanouškovský dopis","Klip se stane virálním právě proto, že je proti očekávání vstřícný."],["Žádat stejný vysílací čas pro protiloutku","Vaše protiloutka je všeobecně uznávaná za méně šarmantní."],["Loutku rovnou koupit","Loutka je teď placenou mluvčí vlády. Pořád zpívá falešně."]]},"p-press-6":{"t":"Oprava, kterou odmítáte otisknout","x":"The Ledger vás žádá o opravu tvrzení, že nezaměstnanost je na „nejnižším čísle, jaké kdy bylo vymyšleno“. Mají skutečná čísla. Vy máte sebevědomí.","c":[["Odmítnout a to číslo zopakovat hlasitěji","Číslo se pravdivějším nestane, ale rozhodně slavnějším."],["Potichu opravu vydat sami","Jeden řádek v zítřejším briefingu. Nikdo si nevšimne, kromě všech, na kom záleží."],["Žádat, ať Ledger opraví svou opravu","Vypukne opravová válka. Nikdo nevyhraje. Všichni jsou vyčerpaní."],["Uvést zbrusu nové, neověřitelné číslo","„Nejnižší číslo, jaké si kdo dokázal představit“ vstoupí do slovníku národa."]]},"p-press-7":{"t":"Novinářka položí skutečnou otázku","x":"Na dnešním briefingu se novinářka z malého regionálního listu zeptá na konkrétní, dobře prozkoumanou, nezodpověditelnou otázku o rozpočtu. V místnosti je ticho. Něčí telefon začne nahrávat.","c":[["Nazvat její otázku falešnou a její list malým","Počet předplatitelů se ze vzdoru ztrojnásobí."],["Skutečně odpovědět, jak nejlíp umíte","U dvou čísel se spletete, ale v duchu věci máte pravdu."],["Odejmout jí na místě tiskovou akreditaci","Stovka dalších novinářů se teď ptá přesně na tu samou otázku."],["Odpovědět kompletně formou haiku","Kritici poezie jsou nečekaně dojatí."]]},"p-press-8":{"t":"Video, kde přiznáte úplně všechno","x":"Hyperrealistický deepfake ukazuje, jak klidně oznamujete rezignaci, abyste se „věnoval polévkovému impériu“. Je to nesmírně přesvědčivé. I vaše vedoucí kanceláře se na vteřinu zarazila.","c":[["Prohlásit veškeré video důkazy vás navždy za falešné","Náhodou jste si vytvořili trvalé alibi na cokoli."],["Zveřejnit skutečné, nudné video, které to klidně vyvrátí","Vyvrácení dostane jedenáct procent zhlédnutí, co dostal falzifikát."],["Zažalovat videoplatformu kvůli samotnému konceptu videa","Právní vědci o tom píší studie. Video zůstává online."],["Oznámit, že skutečně spouštíte polévkovou řadu","Předobjednávky přesáhnou vaši skutečnou popularitu."]]},"p-press-9":{"t":"Vaše oblíbená televize chce laskavost","x":"Proslule přátelská televize vám nabízí celou hodinu, žádné tvrdé otázky, výměnou za exkluzivní přístup na Velikonoční vajíčkovou slavnost. Jejich slova: „měkké otázky to ani zdaleka nevystihují.“","c":[["Udělat rozhovor a v něm sjet každou jinou stanici","Ostatní stanice odvysílají společný segment s názvem „Měkké otázky, doslova“."],["Dát rovný přístup férovému mixu médií","Pokrytí je férové, vyvážené a naprosto zapomenutelné."],["Dát přátelské televizi trvalý exkluzivní přístup","Každý jiný novinář teď slavnost pokrývá z blízkého parkoviště."],["Nechat celý rozhovor vést dětskou reportérku","Osmiletá dívka klade znatelně lepší otázky než kdokoli z personálu."]]},"p-press-10":{"t":"Prezidentský překlep vyvolá celonárodní zmatek","x":"Vaše oficiální prohlášení o „obraně svrchovanosdi národa“ obsahuje překlep ve slově svrchovanost. Je z toho už hashtag, tričko a údajně i drobná kryptoměna.","c":[["Tvrdit, že překlep je tajný kód pro vlastence","Tisíc lidí teď věří, že komunikujete výhradně v překlepech."],["Smazat to, znovu zveřejnit správně, dál nic neříkat","Nudné. Účinné. Finančně zničující pro výrobce triček."],["Vyhodit stážistu, který to napsal","Stážista dostane do týdne knižní smlouvu."],["Ochránkovat si ten překlep sám","Teď vlastníte „svrchovanosd“ v jedenácti kategoriích merche."]]},"p-press-11":{"t":"Zapsal si úplně všechno","x":"Váš bývalý náměstek vedoucího kanceláře vydal knihu se vším všudy. Kapitoly se jmenují „Incident s mixérem“ a „Nikdo mu neřekl, co znamená NATO“. Předobjednávky jdou svižně.","c":[["Nazvat ho v televizi zahořklým, zneuctěným lhářem","Prodeje knihy se zdvojnásobí. Znovu jste jeho marketingovým oddělením."],["Potvrdit historku s mixérem a smát se tomu","Vypadáte jako sportovec, jednou za čas. Váš personál je z toho hluboce znejistělý."],["Nechat u soudu vymáhat jeho dohodu o mlčenlivosti","Žaloba se stane druhou kapitolou brožovaného vydání."],["Napsat vlastní konkurenční knihu o něm","Dvě knihy, jedna vendeta, nekonečný obsah."]]},"p-press-12":{"t":"Tohle jste je fakt neměl nechat natočit","x":"Dokumentární štáb, který jste pozval na „bezprecedentní přístup“, zachytil jedenáct nehlídaných minut, jak křičíte na tiskárnu. Editoři jsou prý „rozmazlení výběrem“.","c":[["Tvrdit, že záběr zinscenovala výrobní firma tiskáren","Výrobce tiskáren vydá prohlášení, které je nějak důstojnější než to vaše."],["Nechat záběr odvysílat, přidat sebeironický klip","Na chvíli působíte lidsky. Nevydrží to."],["Koupit celý dokument a nechat ho v šuplíku","Pirátské kopie kolují stejně do týdne."],["Uspořádat tiskovou konferenci k formální omluvě tiskárně","Tiskárna omluvu nemůže přijmout, jelikož je to tiskárna."]]},"p-press-13":{"t":"Čtyřicet vteřin, které nechtějí zemřít","x":"Čtyřicetivteřinový klip, na kterém třemi různými způsoby v jedné větě špatně vyslovujete slovo „infrastruktura“, má sto milionů zhlédnutí a stále přibývá.","c":[["Trvat na tom, že výslovnost je regionální a správná","Lingvisté zdvořile, ale zeširoka nesouhlasí, v několika komentářích."],["Udělat si z toho vtip na příští tiskovce","Klip dostává druhý život: vy se mu smějete. Mírně sympatické."],["Zakázat slovo „infrastruktura“ v oficiálních prohlášeních","Zákony teď popisují silnice jako „ty dlouhé rovné tvrdé věci“."],["Vydat remixový singl toho klipu","Umístí se v žebříčcích. Jste teď, technicky vzato, hudební umělec."]]},"p-press-14":{"t":"Titulek, který nepřestává počítat","x":"Zpravodajská stanice teď vysílá živý, trvalý spodní pruh počítající vaše nepravdivá tvrzení. Dnes ráno, během reportáže o počasí, překročil čtyři tisíce.","c":[["Nazvat počítadlo samotné čtyřtisícátou lží","Metalži jsou zjevně pořád lži. Počítadlo je to jedno."],["Začít být opravdu opatrnější se svými tvrzeními","Tempo růstu počítadla se zpomaluje. Někde se nudou rozplakal fact-checker."],["Žádat, aby stanice nainstalovala stejné počítadlo i pro vaše soupeře","Jejich počítadlo začíná na nule a zůstává otravně nízké."],["Nechat přesné číslo počítadla prohlásit za utajované","Počítadlo teď ukazuje jen UTAJENO, což je nějak ještě horší."]]},"p-press-15":{"t":"Váš nekrolog už je napsaný","x":"Redakce jednoho velkého deníku píše nekrology pro úřadující vůdce dopředu, pro případ náhlé události. Ten váš unikl. Poradci poznamenávají, že je „překvapivě férový“.","c":[["Žádat propuštění autora nekrologu za morbiditu","Každý autor nekrologů v zemi teď pracuje z utajeného místa."],["Požádat o revizi jen kvůli faktické přesnosti","Opravíte si rodiště. Zbytek zůstává beze změny."],["Vydat vlastní, mnohem lichotivější nekrolog předem","Teď kolují dva nekrology. Ani jeden neuklidňuje."],["Zúčastnit se vlastního fingovaného pohřbu kvůli publicitě","Účast je hojná. Smuteční řeči jsou trefné."]]},"p-press-16":{"t":"Mikrofon byl zapnutý, a jak","x":"Mezi segmenty zachytí nezavřený mikrofon, jak říkáte asistentovi, že navštěvující delegace „smrdí jako auto z půjčovny“. Delegace písemně žádá vysvětlení.","c":[["Tvrdit, že to byl kompliment v jiném jazyce","Takový jazyk neexistuje. Tvrzení to vůbec nezpomalí."],["Zavolat velvyslanci a osobně se omluvit","Velvyslanec omluvu velkoryse přijme a nikdy vám to úplně nezapomene."],["Popírat, že by se kdy nějaký mikrofon k vám přiblížil","Zvukaři po celé zemi se dávají na těžké pití."],["Poslat delegaci bednu osvěžovačů vzduchu jako dárek","Delegace si není jistá, jestli je to omluva, nebo eskalace."]]},"p-press-17":{"t":"Válka o akreditace","x":"Zrušili jste akreditaci novináři za to, že kladl „příliš mnoho doplňujících otázek“. Soudce z toho, co se týče prvního dodatku, evidentně nadšený není.","c":[["Pro jistotu zrušit akreditaci ještě pěti dalším","Tisková místnost je teď hlavně prázdné židle a jeden velmi tvrdohlavý stážista."],["Vrátit akreditaci a potichu se omluvit","Novinářka to přijme. Její doplňující otázky jsou pak ze vzdoru ještě ostřejší."],["Odvolat se proti soudcovu rozhodnutí až na nejvyšší instanci","Prohráváte na každé úrovni, což se nějak samo stává novinovou senzací."],["Vytvořit novou kategorii akreditací s názvem „Opravdu dobří novináři“","Nikdo se nepřihlásí. Zůstáváte jediným členem této kategorie."]]},"p-press-18":{"t":"Váš soupeř má názory, písemně, s poznámkami pod čarou","x":"Váš hlavní politický soupeř publikuje ostrý komentář nazvaný „Skromný návrh na kompetenci“. Má poznámky pod čarou. Několik poradců soukromě přiznává, že je dobře argumentovaný.","c":[["Napsat zuřivou odpověď a nazvat ho zrádcem","Odpověď nemá jedinou poznámku pod čarou a pár překlepů."],["Věcně reagovat v klidném veřejném prohlášení","Uznáte jeden bod. Je to jako operace bez anestezie."],["Žádat, aby noviny denně tiskly stejně dlouhou odpověď","Noviny souhlasí a pak váš text zahrabou vedle křížovky."],["Vyzvat soupeře na veřejnou soutěž v psaní poznámek pod čarou","Nikdo nechápe pravidla. Všichni se přesto dívají."]]},"p-press-19":{"t":"Spis, o který nikdo nežádal","x":"Kariérní státní úředník podává formální oznámení, že jste Situační místnost použil ke sledování finále telenovely. Oznámení obsahuje i hodnocení: „poutavá televize, sporná státnická moudrost“.","c":[["Zdiskreditovat oznamovatele jako zahořklého fanouška konkurenčního seriálu","Sledovanost konkurenčního seriálu vzroste. Té vaší telenovely méně."],["Plně spolupracovat s prošetřením","Šetření vás zprošťuje viny a potvrzuje, že jste finále skutečně viděl."],["Prohlásit celé oznámení za věc národní bezpečnosti","Kongres teď chce vědět, co je na telenovele tak tajného."],["Pozvat oznamovatele, aby se s vámi podíval na příští finále","Přijme pozvání. Prý je to milý večer."]]},"p-press-20":{"t":"Každý má prý svou cenu","x":"Asistent hlásí, že středně známý novinář proslulý tvrdým zpravodajstvím je „koupitelný“ za místo blízko vlády a pěknou kancelář. Právně vzato je to krajně nevhodné.","c":[["Udělat to potichu a v případě dotazů navždy vše popírat","Přijme místo. Bývalí kolegové mu, ani vám, už nikdy úplně nedůvěřují."],["Odmítnout a nabídku nahlásit jako nevhodnou","Nic se nestane, kromě toho, že vaše integrita je, na chvíli, neporušená."],["Nabídnout to místo veřejně jen abyste viděl, kdo se chytí","Přihlásí se čtrnáct novinářů. Žádný z nich nebyl ten tvrdý."],["Přijmout ho a hned přeřadit na počasí","Jeho předpovědi teď procházejí přísnější kontrolou faktů než celá vaše vláda."]]},"p-press-21":{"t":"Parodie, co nechce skončit","x":"Komikova imitace vás, samý přimhouřený pohled a mumlání, je teď rozpoznatelnější než vy sám. Malé děti ji prý dělají lépe než komik.","c":[["Žalovat komika za krádež vaší osobnosti","Právníci poznamenávají, že osobnost se přesně vzato ukrást nedá. Žaloba je zamítnuta s viditelným pobavením."],["Na veřejné akci zahrát imitaci sám na sebe, s nadhledem","Sklidí největší smích týdne, na váš vlastní účet, což je vzácné a cenné."],["Zakázat komikovi vstup na všechny budoucí tiskové akce","Komik pak dělá imitaci jen zvenku za zábranami, hlasitěji."],["Najmout komika jako svého nového spisovatele projevů","Vaše projevy jsou najednou mnohem vtipnější a citelně méně srozumitelné."]]},"p-press-22":{"t":"Internet vyhlašuje soutěž o nejlepší popisek","x":"Fotka, na které mžouráte na desky s nápisem NALÉHAVÉ, držíte je vzhůru nohama, spustila celostátní soutěž o popisek. Aktuálně vede: „Muž zjišťuje, že gravitace platí i na papír“.","c":[["Žádat, aby platforma smazala každý příspěvek","Samotné smazání vyhrává soutěž o popisek pro svou ironii."],["Vybrat si oblíbený příspěvek a sám ho sdílet","Na jedno odpoledne jste v obraze. Sklízí to překvapivě dobrý ohlas."],["Žalovat platformu za emoční újmu","Soudkyně by se prý sama nejraději do soutěže přihlásila."],["Vyhlásit peněžní odměnu za vítězný popisek","Počet příspěvků vzroste o čtyři sta procent. Kvalita ne."]]},"p-war-1":{"t":"Signál z Volkovie","x":"Radarová stanice u hranice v úterý večer něco zachytila. Výbuch, test rakety, nebo ohňostroj k narozeninám generála Oseie, nikdo si není jistý. Náčelníci štábů chtějí rozhodnutí, než jim vychladne káva.","c":[["Nazvat to válečným aktem a mobilizovat flotilu","Flotila vyplouvá. Důkazy nikoli."],["Nařídit skutečné vyšetření, než cokoli oznámíte","Nic se nestalo. Všichni jsou naštvaní, že to trvalo tak dlouho zjistit."],["Uniknout informaci, že šlo jistojistě o útok, fakta se doplní později","Únik se stává příběhem. Příběh se stává válkou."],["Svalit to na zbloudilý meteorologický balon a žádat, aby se národu omluvil úřad ČHMÚ","Úřad se omluví. Meteorologové si potichu aktualizují životopisy."]]},"p-war-2":{"t":"Generál chce přehlídku","x":"Generál Halbrook chce tanky na hlavní třídě, „aby svět připomněl, že tanky ještě máme“. Ministerstvo obrany odhaduje, že přehlídka bude dražší než několik malých válek.","c":[["Schválit celou přehlídku, tanky a vše ostatní","Tanky dorazí. Stejně tak účet za výtluky."],["Nařídit místo toho jen skromný přelet, ušetřit peníze","Proletí tři letadla. Nikdo netleská."],["Přehlídku zdvojnásobit, přidat raketu ve tvaru vaší tváře","Vůz s raketou zabodoval přesně u jedné cílové skupiny: u vás."],["Nechat generála Halbrooka jet na koni místo v tanku","Kůň krade titulky. Generál Halbrook žádá pro koně povýšení."]]},"p-war-3":{"t":"Dron čeká","x":"Dron má na mušce cíl někde poblíž hranice Osei-Volkov. Rozvědka je „docela přesvědčená“, že jde o konvoj se zbraněmi, a „o něco méně přesvědčená“, že nejde o svatbu.","c":[["Dát rozkaz, lepší to jistit","Konvoj je zničen. Prý i dort."],["Počkat se střelbou, dokud si rozvědka nebude jistá","Konvoj se ukáže jako svatba. Nevěsta posílá ostře formulovaný dopis."],["Udeřit hned a udeřit znovu pro jistotu","Dva útoky, jeden konvoj, žádné zbraně nakonec nenalezeny."],["Rozhodnutí přenechat hodu mincí, vysílanému živě","Mince padne na hlavu. Váleční etici hromadně podávají výpověď."]]},"p-war-4":{"t":"Úterní puč generála Oseie","x":"Generál Osei obsadil palác ve spřátelené zemi, odvolává se na „vibrace“ a přeje si být oslovován Nejvyšší velitel. Washington musí rozhodnout, jestli ho uzná.","c":[["Ihned Oseie uznat, působí schopně","Osei posílá dárkový koš s ovocem. Demokracie posílá své politování."],["Odsoudit puč, podpořit svrženou vládu","Prohlášení je vydáno. Oseie to nechává klidným a upřímně stále u moci."],["Potichu Oseie vyzbrojit výměnou za přístup k základně","Získáte základnu. Osei získá soukromou armádu. Dějiny získají poznámku pod čarou."],["Pozvat Oseie do Camp Davidu probrat to při golfu","Osei podvádí v golfu a vy se oba nějak shodnete, že to je v pořádku."]]},"p-war-5":{"t":"Šest turistů a jedna stížnost","x":"Šest amerických turistů zajala v horách milice, která tvrdí, že jí osobně dlužíte omluvu za něco, co váš dědeček možná řekl v roce 1961.","c":[["Poslat speciální jednotky, žádná vyjednávání","Turisté jsou zachráněni. Dvě kozy nikoli."],["Tiše vyjednávat přes zadní kanály","Turisté se vrátí domů. Nikdo neuvidí ty skvělé záběry ze záchrany."],["Veřejně vyhrožovat celé zemi milice","Milice se zakope. Velvyslanec té země si vyhrabe právníka."],["Omluvit se jejich jménem za cokoli, co dědeček řekl","Ani oni nevědí, co řekl. Omluva se přesto vysílá."]]},"p-war-6":{"t":"Nejvyšší vůdce chce koupit stíhačky","x":"Nejvyšší vůdce země pod šesti různými sankčními režimy chce koupit stíhačky, hotově předem, žádné otázky, „na obranné pozorování ptáků“.","c":[["Schválit prodej, hotovost je hotovost","Stíhačky odlétají. Tvrzení o pozorování ptáků neobstojí ani týden."],["Zablokovat prodej a předat věc sankčnímu úřadu","Prodej je zablokován. Nejvyšší vůdce najde jiného dodavatele do čtvrtka."],["Prodat stíhačky a přidat výcvikový balíček","Výcvikový balíček obsahuje věci, které nikdo nechtěl mít písemně."],["Prodat mu vyřazené dvouplošníky a nazvat to slevou","Nejvyšší vůdce zuří. Dvouplošníky jsou, technicky vzato, dodány."]]},"p-war-7":{"t":"Výstřely u plotu","x":"Vojáci na obou stranách sporné hranice si přes noc vyměnili palbu kvůli něčemu, co zpráva popisuje jen jako „nedorozumění kolem kozy“.","c":[["Posílit hranici o tři další divize","Hranice je zajištěna. Osud kozy zůstává neznámý."],["Otevřít horkou linku s druhou stranou k uklidnění situace","Linka funguje. Obě strany se shodnou, že to začala koza."],["Nařídit symbolickou demonstraci síly, tanky k plotu","Tanky dorazí. Koza, nerušeně, se dál pase mezi nimi."],["Nabídnout se, že spor o kozu osobně zprostředkujete","Zprostředkujete. Koza dostane společnou péči."]]},"p-war-8":{"t":"Síť zablikala","x":"Polovina elektrické sítě ve třech státech byla jedenáct minut ve tmě. Kybernetická bezpečnost tvrdí, že to může být Volkovia, může to být teenager ve sklepě, může to být obojí.","c":[["Veřejně obvinit Volkovii a připravit odvetné údery","Volkovia vše popírá. Teenager drží nízký profil."],["Zahájit forenzní vyšetřování, než kohokoli obviníte","Teenager je nalezen. Dostane zaracha, ne vydání."],["Odvetit vlastním kybernetickým útokem, bez potřeby důkazů","Protiúder zasáhne špatnou síť. V Ohiu."],["Oznámit, že výpadek byl od začátku plánované cvičení","Nikdo tomu nevěří. Lež přesto nějak působí uklidňujícím dojmem."]]},"p-war-9":{"t":"Volkov testuje raketu, špatně","x":"Prezident Volkov testoval novou raketu, která podle satelitních záběrů zavrávorala, dvakrát se zatočila a dopadla na pšeničné pole ve vlastní zemi. Státní média to nazývají triumfem.","c":[["Odpovědět ještě větším testem, ten samý týden","Vaše raketa se taky zavrtí. Nikdo o tom neinformuje."],["Tiše selhání zaznamenat a nic nedělat","Výnos pšenice na Volkovově poli stoupá o devět procent díky hnojivu."],["Volkova veřejně zesměšnit a hrozit preventivním úderem","Ponížený Volkov slibuje druhý test. Ještě větší pšeničné pole."],["Poslat Volkovovi kondolenční kartu kvůli pšeničnému poli","Volkov není pobavený. Karta získá víc pozornosti než samotná raketa."]]},"p-war-10":{"t":"Mírová dohoda, kterou nikdo nechtěl pokazit","x":"Vaši vyjednavači potichu dokončili mírovou dohodu, která ukončuje desetiletý konflikt. Bohužel je to nudná televize.","c":[["Oznámit, že živě v éteru přidáte „tvrdší“ podmínky, ať se dohoda sesype","Dohoda se na živém vysílání zhroutí. Sledovanost je, uznejme, silná."],["Nechat vyjednavače dohodu potichu podepsat a slavit výhru","Válka končí. Přenos sleduje devět diváků, všichni s úlevou."],["Podpis zadržet, dokud tam nepřidají vaše jméno","Dohoda je po vás přejmenována. Druhá strana všechno znovu zvažuje."],["Proměnit podpisový ceremoniál v soutěžní show","Rebelové vyhrají topinkovač. Mír, nějak, ze vzdoru vydrží."]]},"p-war-11":{"t":"Přeběhlík žádá o azyl","x":"Vysoký úředník z vlády Nejvyššího vůdce se objevil na velvyslanectví s flash diskem a žádostí o pěkný dům na Floridě.","c":[["Udělit azyl a ihned ho předvést v televizi","Nejvyšší vůdce zuří. Přeběhlík si tu pozornost náramně užívá."],["Nejdřív ho v klidu vyslechnout řádnými kanály","Flash disk obsahuje hlavně dovolenkové fotky a jednu užitečnou mapu."],["Prozradit jeho totožnost, aby to zatlačilo na jeho starou vládu","Tlak funguje. Stejně tak skoro i pokus o atentát."],["Vyměnit ho za dvě pandy, bez otázek","Pandy dorazí. Přeběhlík je hluboce uražen tímto směnným kurzem."]]},"p-war-12":{"t":"Lodě v úžině","x":"Volkovský torpédoborec a americká letadlová skupina jsou v úžině dost blízko na to, aby si vyměnily ostře formulované vlajkové signály. Ani jedna strana nechce mrknout první.","c":[["Nařídit letadlové skupině držet pozici, se zbraněmi připravenými","Nikdo nemrkne. Všem alarmujícím tempem klesá stav paliva."],["Přesměrovat letadlovou skupinu, aby se konfrontaci vyhnula","Lodě proplují bezpečně. Admirál je potichu zklamaný."],["Nařídit ostrostřeleckou přehlídku přímo tam, pro zdůraznění","Přehlídka je velmi hlasitá a velmi blízko. Volkov posílá formální stížnost, ještě hlasitější."],["Vyzvat volkovského kapitána na partii šachů po rádiu","Vyhrajete. Kapitán tvrdí, že mu dámu zablokoval radar."]]},"p-war-13":{"t":"Povstání potřebuje kapesné","x":"Povstalecká koalice bojující proti vládě Nejvyššího vůdce chce zbraně, hotovost a „morální podporu“, v tomto pořadí.","c":[["Financovat je naplno, tajně, bez dohledu","Povstání postupuje. Stejně tak papírová stopa."],["Nabídnout jen humanitární pomoc, žádné zbraně","Povstalci jsou vděční za deky a nepříliš nadšení strategií."],["Financovat je i obě jejich rivalské povstalecké frakce, pro jistotu","Tři frakce teď tráví víc času bojem mezi sebou než proti vládě."],["Financovat je pomocí televizního sbírkového maratonu","Maraton vybere miliony. Celebritní moderátor se teď prohlašuje za experta na zahraniční politiku."]]},"p-war-14":{"t":"Skromný návrh ze sklepa","x":"Poradce, velmi potichu, se zavřenými dveřmi, navrhuje, že by se dal zařídit „menší incident“, který by ospravedlnil válku, kterou už stejně všichni chtějí.","c":[["Schválit to, s odepíratelností, mimo záznam","Incident se stane. Nakonec i vyšetřování."],["Poradce vyhodit a návrh nahlásit","Poradce je pryč. Válka, prozatím, čeká na skutečný důvod."],["Schválit to a rozšířit plán na dva incidenty, pro jistotu","Redundance dosažena. Stejně tak nakonec i federální vyšetřování."],["Nafingovat incident pomocí herců a pronajatého tanku","Herci jsou přesvědčiví. Půjčovna chce tank zpátky."]]},"p-war-15":{"t":"Summit, který byste raději vynechal","x":"Výroční summit aliance je tento víkend. Účast znamená společné fotky a sdílená komuniké. Vynechání znamená, že o vás všichni mluví stejně, jen míň zdvořile.","c":[["Vynechat ho a uspořádat místo toho shromáždění, větší dav","Aliance si toho všimne. Dav na shromáždění je to jedno."],["Zúčastnit se, podepsat komuniké, usmát se na fotku","Fotka je nevýrazná. Aliance drží, sotva si vás všimne."],["Zúčastnit se a odmítnout cokoli podepsat, z principu, nespecifikovaného","Fotka je trapná. Princip nikdy nikdo nepojmenuje."],["Poslat na vaše místo lepenkovou figurínu","S figurínou zachází diplomacie s větším respektem, než se čekalo."]]},"p-war-16":{"t":"Vesmírné síly chtějí vlajku na Měsíci","x":"Nově zřízené Vesmírné síly chtějí na povrch Měsíce zapíchnout vlajku s vaší tváří, „kvůli odstrašení“.","c":[["Financovat misi naplno, start příští čtvrtletí","Vlajka dosáhne oběžné dráhy. Tvář je podle NASA „rozpoznatelná jen z nízké oběžné dráhy“."],["Přesměrovat rozpočet na skutečnou výzkumnou misi","Výzkumná mise tiše odstartuje. Vaši tvář nikde nikdo nevidí."],["Přidat i laser, odstrašení potřebuje laser","Laser funguje bez problémů. Sedmnáct zemí přesto podá formální protest."],["Financovat misi s vlajkou crowdfundingem","Crowdfunding se povede. Přispěvatelé dostanou certifikát a mírnou lítost."]]},"p-war-17":{"t":"Práva na pojmenování","x":"Váš tiskový tým navrhuje probíhající zahraniční konflikt oficiálně přejmenovat po vás, „kvůli odkazu“.","c":[["Přejmenování ihned schválit, s plnou ceremonií","Válka teď nese vaše jméno. Stejně tak každá zpráva o obětech."],["Odmítnout, války by neměly nést vaše jméno","Válka si podrží staré, nudné jméno. Dějiny zůstávají stejně nedotčené."],["Přejmenovat ji a nechat razit pamětní minci","Mince je vyražena. Válka pokračuje, teď s merchem."],["Nechat o jméně hlasovat veřejnost","Veřejnost hlasuje pro něco netisknutelného. Potichu se to zamítne."]]},"p-war-18":{"t":"Ten velmi velký tlačítko","x":"Asistenti nainstalovali na váš stůl velké červené tlačítko, „kvůli morálce“, jak tvrdí, ačkoli je napojené na něco, co dřív vyžadovalo tři klíče a generálův podpis.","c":[["Vyhrožovat, že ho v televizi stisknete, ať se uvidí, co se stane","Nikdo nic nestiskne. Všem se spí trochu hůř."],["Nechat tlačítko odstranit a obnovit původní protokol","Tlačítko je pryč. Stůl vypadá podivně prázdný."],["Stisknout ho napůl, „jen na zkoušku“, před novináři","Naštěstí bylo odpojené. Záběry nikoho neuklidňují."],["Nahradit ho tlačítkem, které jen objedná pizzu","Pizza dorazí. Morálka, proti všem očekáváním, opravdu stoupne."]]},"p-war-19":{"t":"Muž v moc pěkném obleku","x":"Soukromý vojenský dodavatel nabízí, že vyřeší „celou tu situaci s Volkovem“ za paušální poplatek, bez dohledu Kongresu, bez papírování, bez otázek.","c":[["Najmout dodavatele, hotově předem, potichu","Situace je vyřešena. Nikdo přesně neví jak."],["Odmítnout a věc předat ministerstvu obrany","Ministerstvo postupuje pomalu. Muž v obleku odejde jinam se svým podnikáním."],["Najmout dodavatele a dát mu ještě druhou, nesouvisející zakázku","Obě zakázky jsou vyřízeny. Ani jedna se neobjeví v žádném rozpočtu."],["Vyjednat mu nižší odměnu jeho vlastními taktikami","Respektuje váš um. Příště si taky zdvojnásobí sazbu."]]},"p-war-20":{"t":"Ostrov na prodej","x":"Malý tichomořský stát je ochotný prodat strategicky umístěný ostrov pro námořní základnu, pokud bude cena správná a papíry zůstanou vágní.","c":[["Koupit ho rovnou, oznámit novou základnu do pátku","Základna je postavena. Místní obyvatelé nejsou, jak se ukazuje, konzultováni."],["Vyjednat pronájem místo přímé koupě","Nájemní smlouva je podepsána. Všichni uznávají, že jde o tu nudnou správnou volbu."],["Koupit ho i tři sousední ostrovy, pro jistotu","Teď vlastníte čtyři ostrovy a rychle se zhoršující vztahy s celým regionem."],["Zkusit ho vyměnit za přebytečný trajekt z Guamu","Nabídka je odmítnuta. Kapitán trajektu si oddechne."]]},"p-war-21":{"t":"Ponorka přestala volat","x":"Americká ponorka poblíž volkovských vod zmeškala poslední dvě plánovaná hlášení. Může jít o poruchu spojení. Může jít o něco horšího. Nikdo to nechce vyslovit nahlas.","c":[["Mobilizovat flotilu a okamžitě žádat od Volkova odpovědi","Flotila se mobilizuje. Ponorka měla, jak se ukáže, jen mrtvou vysílačku."],["Potichu vyslat záchranné plavidlo a počkat","Ponorka se vynoří podle plánu o tři hodiny později. Tisk se to nedozví."],["Veřejně oznámit, že americká ponorka možná zmizela, pravděpodobně vyprovokována","Světové trhy panikaří šest hodin. Vysílačka byla, znovu, prostě mrtvá."],["Poslat ponorce ostře formulovaný fax","Ponorky nemají faxy. Toto se teď stává obecně známým faktem."]]},"p-war-22":{"t":"Generál nahlas odstupuje","x":"Generál Halbrook rezignoval na protest proti „směřování zahraniční politiky této vlády“ a dává o tom rozhovory, což je novinka.","c":[["Veřejně napadnout Halbrookovu povahu v televizi","Halbrook odpoví smlouvou na knihu. Smlouva odpoví prodejností."],["Rezignaci přijmout s grácií, popřát mu vše dobré","Halbrook odchází potichu. Novináři ho zklamaně shledávají také velkorysým."],["Ze vzteku ho připravit o penzi","Penze je pryč. Stejně tak jakákoli zbývající přízeň celého sboru důstojníků."],["Nabídnout Halbrookovi talk show, aby měl co dělat","Halbrook přijme. Jeho sledovanost, k vzteku, poráží tu vaši."]]},"p-street-1":{"t":"Tábor Ústava","x":"Protestující obsadili náměstí Svobody v centru Columbusu už šest dní, přejmenovali ho na Tábor Ústava a jmenovali čestným starostou mývala Steva. Steve má lepší preference než skutečný starosta.","c":[["Poslat tam zásahovku","Tábor je vyklizen do svítání. Steve je propuštěn bez obvinění, což je víc, než se dá říct o všech ostatních."],["Rozumný krok","Místo štítů pošlete přenosné toalety a příběh se najednou točí kolem vaší překvapivé slušnosti."],["Horší nápad","Náměstí necháte srovnat buldozery ve tři ráno. Tábor Ústava se o dva bloky dál znovu otevírá jako Tábor Ústava Dva."],["Rovnou náměstí odkoupit","Koupíte náměstí Svobody za jedenáct milionů dolarů a přejmenujete ho na Národní muzeum hraček. Návštěvnost zklamává."]]},"p-street-2":{"t":"Všichni jsou venku","x":"Dvanáct odborů vyhlašuje koordinovanou generální stávku. Hromadí se odpadky, vlaky stojí a barista z Toleda se přes noc stává lidovým hrdinou za odmítnutí uvařit vaší tiskové mluvčí ovesné latté.","c":[["Prohlásit stávku za nezákonnou","Organizátoři jsou zatčeni do večera. Odpadky zůstávají přesně tam, kde byly."],["Rozumný krok","Zahájíte vyjednávání a nabídnete skromné ústupky. Vlaky, neochotně, znovu jezdí."],["Přivézt autobusy se stávkokazy","Stávkokazi nemohou najít depo, pak se nemohou najít mezi sebou, pak jdou domů."],["Vyhlásit náhle celostátní svátek","Oznámíte Den uznání pracujících, s okamžitou platností, takže stávka teď vypadá, jako by si všichni prostě vzali volno."]]},"p-street-3":{"t":"Incident s bazénkem","x":"Záznam z tělové kamery, na kterém policista se značnou silou zabavuje dítěti nafukovací bazének za „blokování hydrantu“, má čtyřicet milionů zhlédnutí ještě před vaším ranním briefingem.","c":[["Postavit se za policistu","Kritiky nazvete změkčilými vůči zločinu. Bazének zůstává nekonečně dlouho v úschově důkazů."],["Rozumný krok","Nařídíte nezávislé prošetření a veřejnou omluvu. Dítě dostane bazének zpátky, lehce vyfouknutý."],["Povýšit policistu naživo v televizi","Ceremonie má hojnou účast, přesně toho publika, které jste pro obrázky nechtěl."],["Poslat dítěti podepsaný bazének","Pošlete podepsaný nafukovací bazének s lístkem „bez zášti“. Internet se neuklidní."]]},"p-street-4":{"t":"Shromáždění na vaši počest","x":"Milice nazvaná Minutemen Redux plánuje pochod s pochodněmi „na podporu prezidenta“, s maskáčovým oblečením, energetickými nápoji a nafukovacím hradem ve tvaru orla.","c":[["Nechat je pochodovat, bez omezení","Nafukovací orel uprostřed akce splaskne. Fotky z jeho pádu přežijí samotné shromáždění."],["Rozumný krok","Potichu je požádáte, ať to zruší, a poděkujete jim za podporu jinak. Většina uposlechne, s mumláním."],["Poslat oficiální čestnou stráž","Fotky vojáků vedle nadšenců v maskáčích běží ráno na každé titulní straně."],["Poslat podepsaný chladicí box energetických nápojů","Dar je vřele přijat. Několik účastníků tři dny nespí."]]},"p-street-5":{"t":"Generál padá","x":"Dav strhne sochu dávno zesnulého generála před starou soudní budovou, odtáhne ji čtyři bloky a hodí do fontány, kde teď vypadá, jako by plavala.","c":[["Zatknout každého na záznamu","Čtyřicet zatčení. Socha zůstává ve fontáně a plave si znak."],["Rozumný krok","Potichu souhlasíte, že socha může být přemístěna do muzea. Fontána je vypuštěna a vyčištěna."],["Nařídit ji postavit dvakrát větší","Nová socha je o půlnoci dovezena jeřábem pod ozbrojenou stráží. Do týdne je znovu stržena."],["Prohlásit fontánu za historickou plaveckou expozici","Turisté teď platí pět dolarů, aby viděli generála uprostřed kraulu. On nic nenamítá."]]},"p-street-6":{"t":"Volání po zákazu vycházení","x":"Starostka Delgado chce po třech nocích nepokojů celoměstský zákaz vycházení. Vaši poradci jsou rozdělení mezi „ano, zjevně“ a „přesně takhle vznikne mnohem větší protest“.","c":[["Zavést zákaz vycházení, tvrdě","Zákaz vydrží jednu noc, než deset tisíc lidí usoudí, že devátá hodina je jen doporučení."],["Rozumný krok","Zákaz odmítnete a necháte město, ať si poradí samo. Většinou se to podaří."],["Zákaz plus kontrolní stanoviště na každém bloku","Doprava se celoměstsky zastaví. Stejně tak i jakékoli sympatie k vám."],["Zákaz vycházení, ale jen pro holuby","Vyhláška o zákazu vycházení holubů je podle právníků naprosto nevymahatelná a hlavně vtip, který zabírá."]]},"p-street-7":{"t":"Doklady, prosím","x":"Noční razie cílí na nedokumentované pracovníky ve skladu zeleniny a zajmou i několik skutečných občanů, kteří si prostě zapomněli peněženku, včetně jednoho bývalého soudce.","c":[["Rozšířit razie","Bývalý soudce je propuštěn s omluvným dopisem. Sklad už nikdy neotevře."],["Rozumný krok","Razie pozastavíte do prošetření. Zelenina, bohužel, dál plánovaně shnívá."],["Provést razii i v soudní budově, pro jistotu","Několik soudců je čtyři hodiny zadrženo, než někdo zkontroluje jejich odznaky."],["Nabídnout soudci formální omluvný koš od státu","Koš obsahuje ovoce pocházející přímo z toho vyplundrovaného skladu."]]},"p-street-8":{"t":"Kleknout, nebo se postavit","x":"Půlka stadionu kleká při hymně na mistrovském zápase, zatímco druhá půlka bučí tak hlasitě, že je to slyšet v přenosu. Váš kancléř chce prohlášení ještě před poločasem.","c":[["Žádat, aby liga viníky potrestala","Liga odmítá s odkazem na smlouvu, kterou jste nečetl. Dohledáte si ji, je neprůstřelná."],["Rozumný krok","Neřeknete vůbec nic, což se ukáže jako nejméně mediálně zajímavá možnost ze všech."],["Vyhrožovat vysílacím právům ligy","Tři televizní sítě potichu zvažují přesun budoucích zápasů do zahraničí."],["Zúčastnit se příštího zápasu a ironicky si sám kleknout","Nikdo se neshodne, co vaše klečení znamenalo, včetně vás."]]},"p-street-9":{"t":"Karavana, která nebyla","x":"Kabelová televize hlásí „masivní karavanu“ blížící se k jižní hranici. Po bližším ohledání jde o mikrobus mládežnické skupiny z kostela na výletě, ale panika už je na vzestupu.","c":[["Okamžitě nasadit na hranici vojáky","Tři tisíce vojáků vítají kostelní mikrobus a velmi zmateného mládežnického faráře."],["Rozumný krok","Veřejně uvedete fakta na pravou míru. Panika splaskne, stejně jako celý mediální cyklus."],["Přesto vyhlásit formální hraniční mimořádný stav","Nouzový stav přežije mikrobus o několik měsíců."],["Pozvat mládežnickou skupinu do Bílého domu","Sedmnáct teenagerů prohlídne Růžovou zahradu. Dva z nich kladou překvapivě dobré otázky."]]},"p-street-10":{"t":"Kampus nechce ustoupit","x":"Studenti na třech velkých univerzitách obsazují budovy vedení a vydávají seznam požadavků, který kromě reformy školného obsahuje i „lepší svačiny v automatech“.","c":[["Poslat federální agenty na vyklizení kampusů","Okupace končí. Do semestru s ní končí i většina darů od absolventů."],["Rozumný krok","Necháte to na univerzitách a potichu poznamenáte, že požadavek na automaty má opravdu něco do sebe."],["Vyhrožovat odebráním veškerého federálního výzkumného financování","Několik děkanů zpanikaří po telefonu. Několik dalších volá, že už stejně rezignovali."],["Doplnit automaty sám","Svačiny jsou výborné. Ostatní požadavky zůstávají neřešeny."]]},"p-street-11":{"t":"Osmnáct kol vzteku","x":"Kamioňáci blokují dálnici ve třech státech na protest proti nové palivové dani, parkují, troubí a na krajnici grilují ohromné množství klobás.","c":[["Nařídit dálnici vyklidit silou","Odtahovky přijíždí odtahovat odtahovky. Klobásy jsou zabaveny jako důkaz."],["Rozumný krok","Palivovou daň pozastavíte do přezkoumání. Dálnice se do večera otevře, provoněná klobásami."],["Pověřit státní policii, ať zabaví soupravy","Zabavit čtyři sta kamionů vyžaduje odstavnou plochu, na které je momentálně čtyři sta kamionů."],["Poslat jako mírové gesto bednu hořčice","Kamioňáci hořčici přijmou a z principu zůstanou zaparkovaní dál."]]},"p-street-12":{"t":"Pomník sám sobě","x":"Chcete na National Mall dvě stě stop vysokou sochu sebe sama. Inženýři říkají, že je to konstrukčně možné. Všichni ostatní říkají, že je to hrozný nápad.","c":[["Urychlit výstavbu, ignorovat námitky","Socha vyroste podle plánu. Holubi si nárokují hlavu do týdne."],["Rozumný krok","Potichu nápad odložíte a necháte ho zemřít ve výboru, kam tyhle věci patří."],["Udělat ji tři sta stop vysokou, ze zlata","Zlaté obložení je odcizeno šrotovníky ještě před slavnostním přestřižením pásky."],["Postavit ji, ale nechat občany hlasovat o póze","Vítězná póza, zvolená veřejným hlasováním, je vy na losovi. Výstavba pokračuje."]]},"p-street-13":{"t":"Povolání Národní gardy","x":"Nepokoje ve čtyřech městech vedou vaše generály k doporučení plného povolání Národní gardy. Je to typ rozhodnutí, které skvěle vypadá na briefingu a hrozně na titulní straně.","c":[["Plné povolání, do všech čtyř měst","Nasadí se dvanáct tisíc vojáků. Fotky vojáků na hlavních třídách běží celý týden."],["Rozumný krok","Spolehnete se na místní policii a komunitní vůdce. Je to pomalejší, ale funguje to."],["Povolat gardu a zároveň zfederalizovat místní policii","Místní šéfové nesou převzetí pravomocí těžce. Dva rezignují veřejně a zdlouhavě, přímo před kamerou."],["Nasadit gardu, ale jen na úklid","Vojáci týden sbírají odpadky. Podivně to všechny uklidní."]]},"p-street-14":{"t":"Když protiprotest protestuje proti protiprotestu","x":"Shromáždění, které jste sám zorganizoval na svou podporu, přitáhne protiprotest, ten přitáhne proti-protiprotest, a teď si nikdo na místě nepamatuje, na které straně vlastně začal.","c":[["Poslat policii chránit jen vaše příznivce","Optika jednostranné ochrany přežije shromáždění o celé týdny v každém zpravodajském cyklu."],["Rozumný krok","Vyzvete ke klidu na všech stranách a myslíte to vážně, což naprosto všechny zmate."],["Poslat policii zatknout jen protiprotestující","Vazební příjem třídí lidi podle toho, jakou drželi ceduli, což prostě není zákonná kategorie."],["Shromáždění zrušit, svalit to na kolizi termínů","Všichni jdou domů zmatení, ale, důležité, nikdo se nepere."]]},"p-street-15":{"t":"Starostka Delgado říká ne","x":"Starostka Delgado veřejně odmítá vymáhat váš nejnovější pouliční příkaz, stojí na schodech soudní budovy a čte megafonem nahlas Ústavu velmi zaujatému davu.","c":[["Odvolat ji z funkce federálním nařízením","Odvolávací příkaz spustí soudní spor, který přežije celé vaše funkční období, možná i vás samotného."],["Rozumný krok","Příkaz potichu zrušíte, než abyste bojoval se starostkou vyzbrojenou megafonem a Ústavou."],["Odříznout jejímu městu veškeré federální financování","Silnice ve městě zůstávají neopravené. Preference starostky Delgado nikoli."],["Vyzvat ji na veřejnou debatu na schodech soudní budovy","Okamžitě souhlasí a přinese si kartičky s poznámkami. Vy jste si kartičky nepřinesl."]]},"p-street-16":{"t":"Žena s cedulí","x":"Jedna žena tiše stojící u trasy vaší kolony s ručně psanou cedulí se stává nejsdílenějším obrázkem měsíce, nějak virálnější než cokoli, co vyprodukoval váš tým.","c":[["Nechat ji z trasy odstranit","Odstranění jedné tiché ženy s cedulí jí zajistí zhruba čtyřicetkrát větší publikum, než měla původně."],["Rozumný krok","Cestou kolem ní zamáváte. Je to malé gesto a poněkud funguje."],["Nechat tým vyprodukovat konkurenční virální moment","Konkurenční moment je široce zesměšněn jako nastrojený, protože skutečně nastrojený byl."],["Pozvat ji na kávu","Přijme, cedulí se po celou dobu nevzdá, a stává se druhým nejsdílenějším obrázkem měsíce."]]},"p-street-17":{"t":"Pochod místních","x":"Odborový pochod se vine hlavním městem a žádá vyšší mzdy, lepší pracovní dobu a nevysvětlitelně také státní svátek na jarní rovnodennost.","c":[["Nařídit pochod rozehnat","Pochod se přeskupí o dva bloky dál, teď s novou stížností a větším davem."],["Rozumný krok","Setkáte se s odborovými vůdci a nabídnete skutečné ústupky. Svátek rovnodennosti zůstává na seznamu přání."],["Nařídit pochod rozehnat jízdní policií","Koně a pochodující se moc nesnesou. Ani záznam z toho nakonec nevyšel dobře."],["Udělit svátek rovnodennosti, nic víc","Zaměstnanci dostanou jarní svátek a žádné přidání. Výměnu si všimnou okamžitě."]]},"p-street-18":{"t":"Zatrub, pokud miluješ pořádek","x":"„Vlastenecká kolona“ pickupů a vlajek objíždí hlavní město už třetí den v kuse, blokuje dopravu na vaši podporu a čím dál víc i vám samotnému v cestě.","c":[["Nechat je policejně doprovázet donekonečna","Rozpočet na doprovod nabobtná. Kolona nejeví žádné známky konce ani odjezdu."],["Rozumný krok","Veřejně jim poděkujete a požádáte je, ať se vrátí domů. Většina to nakonec udělá."],["Nařídit koloně eskalovat směrem do centra","Zácpa v centru dosahuje nového osobního rekordu. Doručovatelé zuří, na kameru."],["Udělit koloně ceremoniální povolení k pochodu","Povolení dělá zácpu oficiální a nějak i legální."]]},"p-street-19":{"t":"Guvernérka Frostová říká rozhodně ne","x":"Guvernérka Frostová odmítá váš příkaz přijmout ve svém státě federální jednotky, odvolává se na svrchovanost státu, několik soudních precedentů a tón, který napovídá, že na tenhle spor čekala.","c":[["Nasadit jednotky navzdory jejím námitkám","Nasazení okamžitě spustí soudní spor a velmi citovatelnou tiskovou konferenci od Frostové."],["Rozumný krok","Ustoupíte a necháte to na státu. Frostová vám nečekaně veřejně poděkuje."],["Vyhrožovat odříznutím veškerého federálního financování jejímu státu","Frostová vaše vydírání veřejně v televizi zavolá. Bylo to, fakticky, hlavně blaf."],["Vyzvat Frostovou, ať to vyřeší při večeři se steakem","Večeře probíhá zdvořile. Otázka jednotek zůstává i po dezertu nevyřešena."]]},"p-street-20":{"t":"Sezení u bran","x":"Koalice duchovních usedne před palácovou bránu, na směny zpívá hymny a odmítá odejít, dokud se s nimi nesejdete kvůli bytovému zákonu, který jste měsíce ignoroval.","c":[["Nechat je odstranit silou","Záběry duchovních odnášených uprostřed hymnu jsou, taktikou, přesně tak zlé, jak to zní."],["Rozumný krok","Setkáte se s nimi do hodiny. Bytový zákon se konečně pohne z výboru."],["Nechat je zatknout za vniknutí na cizí pozemek","Kauci během chvíle složí konkurenční kongregace, čistě ze vzdoru vůči vaší vládě."],["Poslat jim skládací židle a limonádu","Sezení se stává citelně pohodlnějším a podstatně delším."]]},"p-street-21":{"t":"Popel na schodech","x":"Veterán pálí vlajku na schodech kapitolu na protest proti škrtům v dávkách, čímž vyvolá pobouření u někoho, potlesk u jiných a záplavu kamer od naprosto všech.","c":[["Tlačit na okamžité stíhání","Stíhání znovu otevírá desítky let starý spor o svobodu projevu, který nikdo tento týden nechtěl znovu otevírat."],["Rozumný krok","Veřejně obnovíte škrtnuté dávky a necháte právní otázku ležet. Funguje to."],["Prosazovat ústavní dodatek zakazující pálení vlajky","Snaha o dodatek uvázne ve výboru, jak se takovým snahám spolehlivě děje už desítky let."],["Poslat veteránovi náhradní vlajku, zabalenou jako dárek","Vlajku vděčně přijme a týden nato ji z principu znovu spálí."]]},"p-street-22":{"t":"Balada o Cooperu Vanceovi","x":"Folkový zpěvák Cooper Vance je zatčen za neautorizované provedení protestní písně před federální budovou a píseň kvůli tomu okamžitě ztrojnásobí popularitu.","c":[["Prosadit plné obvinění, dát příklad","Soud dá písni druhý refrén a Vanceovi smlouvu s nahrávací společností."],["Rozumný krok","Obvinění se potichu stáhne. Píseň, když už řekla své, podle plánu vypadne z žebříčků."],["Zakázat mu vystupovat kdekoli na federální půdě","Vance vystupuje z veslice těsně mimo federální jurisdikci, před velmi početným davem."],["Pozvat Coopera Vance, ať headlinuje vaše shromáždění","Přijme, a pak na vašem shromáždění zahraje přesně tu protestní píseň, slovo od slova."]]},"p-congress-1":{"t":"Zaujměte postoj (jakýkoli postoj)","x":"Předseda Sněmovny Grimsby potřebuje váš postoj k Zákonu o modernizaci zemědělství hodinu před hlasováním v plénu. Nečetl jste ho. Nikdo ho nečetl. Termínu to zjevně nevadí.","c":[["Prohlásit, že jste zákon napsal osobně, ručně, brkem","Tvrzení o brku špatně stárne, jakmile někdo najde pod textem font psacího stroje."],["Požádat o čtyřicet osm hodin, abyste to skutečně přečetl","Kongres respektuje řádnou obezřetnost. Vaše základna nerespektuje z tohohle vůbec nic."],["Veřejně se zavázat k postoji, který zrovna vede ve večerních průzkumech","Váš oficiální postoj se čtyřikrát změní ještě před samotným otevřením hlasování."],["Prohlásit zákon za „duchovně správný“ a detaily nechat na štábu","„Duchovně správné“ se stává trvalou kategorií ve vašich tiskových briefinzích."]]},"p-congress-2":{"t":"Zaslechnuté řeči o impeachmentu","x":"Poslankyně Vandersloot potichu sbírá podpisy pro vyšetřování impeachmentu. Potichu ve smyslu, že to řekla šesti novinářům a jedné velmi upovídané baristce.","c":[["Vyhrožovat, že proti každému signatáři postavíte vlastního vybraného protikandidáta","Tři signatáři okamžitě uhnou. Tři další svolají kvůli té hrozbě tiskovou konferenci."],["Plně spolupracovat a vydat každý požadovaný dokument","Vyšetřování vyhasne kvůli nedostatku skandálu, což se samo stává malým skandálem."],["Uniknout falešné dokumenty naznačující, že skutečnou zločinkyní je Vandersloot","Únik je vystopován rovnou do vaší kanceláře, k tiskárně, i s cartridge."],["Pozvat Vandersloot na celostátně vysílaný „přátelský summit“","Přijme. Vysílá se přesně proti finále mistrovství světa."]]},"p-congress-3":{"t":"Světla se za chvíli zhasnou","x":"Ministryně financí Boonová vás informuje, že financování vlády o půlnoci vyprší, pokud Kongres do té doby něco, cokoli, neschválí.","c":[["Nařídit úřadům, ať zůstanou otevřené stejně, a účtovat to na „vibrace“","Úřad pro odpovědnost vlády napíše ostře formulovanou zprávu. Necháte si ji zarámovat."],["Podepsat ošklivý dvoustranický nouzový zákon, kompromisy a vše","Nouzový zákon nikoho nenadchne. Nikoho ale ani nepošlou domů bez výplaty."],["Nechat vládu záměrně padnout do výluky a viníka jmenovat: předsedu Sněmovny","Federální zaměstnanci přijdou o výplatu. Vaše preference nějak ne."],["Platit „nezbytný“ personál z pokladny suvenýrového obchodu Bílého domu","V pokladně je čtyřicet jedna dolarů. Na moc dlouho to nevystačí."]]},"p-congress-4":{"t":"Trocha navíc pro prezidentovu položku","x":"V návrhu rozpočtu je, jak říká ministryně Boonová, místo přesně na jednu nestydatou položku navíc. Nějakou dobu už přemýšlíte o fontánách.","c":[["Nařídit vložení položky s fontánou a vyzvat kohokoli, ať se ji odváží škrtnout","Fontány se postaví. Novináři jim navždy říkají Marnivostní bazény."],["Škrtnout svůj oblíbený projekt a nechat peníze jít na skutečnou infrastrukturu","Opraví se pár mostů. Nikdo vám za to samozřejmě nepoděkuje."],["Vložit potichu ještě tři další položky, dokud jsou všichni rozptýlení tou první","Auditoři nakonec najdou všechny čtyři. O každé vyjde samostatná analýza."],["Přejmenovat položku s fontánou na „Vodní iniciativu pro veterány“","Žádný veterán o to nežádal. Několik veteránů je teď zcela oprávněně naštvaných."]]},"p-congress-5":{"t":"Senátor Fitch má na mysli číslo","x":"Senátor Fitch dodá rozhodující hlas pro novou přehradu ve svém státě výměnou za sochu sebe sama a skromné místo v kabinetu pro svého synovce.","c":[["Dát mu jen přehradu, bez sochy a synovce, a hrozit odebráním místa ve výboru","Fitch hlasuje ano, zuřivě, a od té doby vám v rozhovorech říká „ten pronajímatel“."],["Odmítnout celou dohodu a hlas získat poctivě","Zabere to o šest dní déle. Zákon nakonec projde bez úprav."],["Dát mu vše, včetně synovcova místa v kabinetu","Synovci je dvacet dva let a teď nějak dohlíží na jadernou regulaci."],["Nabídnout výměnou lamu místo sochy","Fitch lamu přijme. Nikdo zúčastněný na tomhle vyjednávání není hrdý."]]},"p-congress-6":{"t":"Senátor Alcott objevuje telefonní seznam","x":"Senátor Alcott už šest hodin nahlas čte na půdě Senátu telefonní seznam Delaware, aby zablokoval váš zákon. Momentálně je někde u písmene L.","c":[["Změnit pravidla sněmovny uprostřed obstrukce, ať zmlkne","Funguje to okamžitě. Také se to stává přesně tím pravidlem, které příště použijí proti vám."],["Nechat ho domluvit a hlasování vyhrát čistě, na základě obsahu","Domluví ve tři ráno. Zákon projde o čtyři minuty později."],["Poslat rivalizujícího senátora, ať obstruuje tu obstrukci","V sále teď dva dospělí muži zároveň nahlas čtou telefonní seznamy."],["Objednat pizzu pro celý sál, „pro udržení morálky“","Alcott sní pizzu a klidně čte dál. Špatně mířený úplatek."]]},"p-congress-7":{"t":"Chtějí zástupkyni šéfa štábu Pruettovou","x":"Sněmovní výbor předvolal vaší zástupkyni šéfa štábu, paní Pruettovou, která náhodou ví, kde jsou pohřbená mrtvá těla, finanční i jiná.","c":[["Uplatnit exekutivní výsadu a odvážit se je vyzvat, ať ji vymáhají","Vaši právníci ten argument milují. Hlasování o pohrdání Kongresem se přesto koná okamžitě."],["Nechat Pruettovou vypovídat a poctivě ji připravit","Vypovídá dobře. Je to nudná televize, což je přesně ten nejlepší možný výsledek."],["Poslat vypovídat místo Pruettové dvojnici","Dvojnice je odhalena během devíti minut kvůli vlastní zapomenuté jmenovce."],["Nechat Pruettovou předstírat náhlou, dramatickou, kariéru zachraňující ztrátu hlasu","Čtyřicetkrát zašeptá „bez komentáře“. Nějak horší, než kdyby mluvila."]]},"p-congress-8":{"t":"Soudkyně Kesslingová má minulost","x":"Vaše kandidátka na odvolací soud, soudkyně Kesslingová, kdysi ve vysokoškolských novinách napsala sloupek „Proč by úterky měly být nezákonné“. Senátoři jsou tím bohužel nesmírně zaujatí.","c":[["Protlačit nominaci výborem dřív, než si to kdokoli přečte dál","Kesslingová je potvrzena. Sloupek o úterku se na týdny stane titulkem kabelových zpráv."],["Nominaci stáhnout a vybrat místo ní někoho gloriózně nudného","Nový kandidát nikdy neměl názor na pracovní dny. Potvrzen jednomyslně."],["Nechat Kesslingovou veřejně obhajovat sloupek jako „vizionářský“","„Vizionářský“ je velkorysé slovo. Potvrzena přesto, ale těsně a hořce."],["Nominovat druhého, odváděcího soudce, aby se pobouření rozdělilo napůl","Kongres teď nemá rád dva soudce stejně silně. Svým způsobem efektivní."]]},"p-congress-9":{"t":"Přílepek, ke kterému se nikdo nehlásí","x":"Váš nezbytný zákon o infrastruktuře má na sobě přílepek rušící cla na dovoz lam, vložený neznámou osobou. Teď je to nějak problém úplně všech.","c":[["Prosadit celý zákon i s přílepkem a viníka svalit na lamí lobby","Zákon projde. Lamí dovozní lobby, jak se ukáže, skutečně existuje a je pořádně naštvaná."],["Přílepek vyškrtnout a schválit čistý infrastrukturní zákon","Silnice se opraví. Záhada lamího přílepku zůstane navždy nevyřešena."],["Přidat druhý přílepek, aby to odvedlo pozornost od prvního","Teď jsou tam dva záhadné přílepky a nula odpovědí o kterémkoli z nich."],["Veřejně oznámit, že jste vždy osobně miloval lamy","Tohle neuspokojí naprosto nikoho a zmate skoro každého."]]},"p-congress-10":{"t":"Incident kolem pošty Sylvie P. Renwickové","x":"Rutinní zákon přejmenovávající malou poštu po oblíbené místní knihovnici se nějak proměnil ve tříwelký boj v plénu kvůli nesouvisejícím, desítky let starým zášti.","c":[["Vynutit hlasování a veřejně zostudit každé „ne“ jako protiknihovnické","Zákon projde. Několik poslanců zůstává hluboce dotčeno tím, že je nazvali protiknihovnickými."],["Zprostředkovat tichou dohodu, aby to prošlo bez dalšího dramatu","Pošta dostane své jméno. Nikdo si toho nevšimne, což je přesně ta výhra."],["Připojit vlastní jméno k budově jako spolupočestněného","Teď je to Pošta Renwickové-a-Vás. Renwickova rodina zuří."],["Navrhnout přejmenování po vašem psovi místo toho","Pes má napříč politickým spektrem lepší preference než vy. Mírně znepokojivé."]]},"p-congress-11":{"t":"Senátorka Duchampová si najde svou chvíli","x":"Senátorka Duchampová přednese dvouhodinový projev v plénu, katalogizující každé vaše selhání, dokonale načasovaný na hlavní vysílací čas, i s plakáty na stojanech.","c":[["Vypnout jí uprostřed projevu mikrofon kvůli formalitě","Klip s umírajícím mikrofonem získá desetkrát víc zhlédnutí, než kolik by kdy získal samotný projev."],["Nechat ji domluvit a klidně reagovat fakty druhý den","Vaše odpověď je přesná a tragicky ji sleduje skoro nikdo."],["Naplánovat vlastní konkurenční projev přesně ve stejnou dobu","Celý večer se vysílá rozdělená obrazovka. Oba projevy prohrávají v souboji o sledovanost."],["Poslat jí koš ovoce „v duchu obousměrné spolupráce“","Zvedne koš ovoce v plénu jako Důkaz A něčeho."]]},"p-congress-12":{"t":"Poslankyně Okaforová mění tým","x":"Dosud spolehlivá spojenkyně, poslankyně Okaforová, oznamuje přechod na druhou stranu, s odkazem na „svědomí“, což pro nikoho zúčastněného není dobré znamení.","c":[["Veřejně jí sebrat výborová místa ještě před koncem tiskovky","Tiskovku přesto dokončí, teď s další stížností, kterou může citovat."],["Veřejně jí poděkovat za službu a popřát vše dobré","Elegantní a naprosto neúčinné v zabránění tomu, aby ji následovali další dva."],["Uniknout starý memoranda naznačující, že vždy byla tajně neloajální","Memorandum je pravé, a datované ještě před tím, než jste vůbec nastoupil do úřadu."],["Nabídnout její staré křeslo tomu, kdo proti ní povede nejtvrdší primárku","Teď máte místo tiché spojenkyně velmi hlasitého a velmi neprověřeného spojence."]]},"p-congress-13":{"t":"Předsedovi Tolliverovi naroste páteř","x":"Předseda výboru Tolliver, dřív spolehlivý jako nábytek, odmítá posunout váš zákon dál bez úprav. Zjevně si ho přečetl. Celý.","c":[["Vyhrožovat, že mu před celým výborem seberete kladívko","Okamžitě couvne. Také už vám nikdy nebude věřit a všem to řekne, proč."],["Přijmout jeho pozměňovací návrhy, protože byly stejně rozumné","Zákon je díky tomu lepší. Bolestně, trapně lepší."],["Obejít ho a protlačit zákon jiným výborem","Tolliver to v kabelových zprávách nazve pučem. Ne zcela se mýlí."],["Pozvat Tollivera do Camp Davidu „to probrat“ o víkendu","Vrátí se s dalšími pozměňovacími návrhy, ne méně. Camp David se pořádně vymstil."]]},"p-congress-14":{"t":"Velmi konkrétní most nikam konkrétně","x":"Významný dárce chce účelovou dotaci na most spojující jeho dvě soukromé nemovitosti. Poblíž není žádné město. Není tam žádná řeka. Je tam cesta pro golfový vozík.","c":[["Nařídit vložení a vyzvat auditora, ať to vůbec někdy najde","Auditor to najde asi za čtyři minuty. Na plánech je i jeho jméno."],["Dárci říct ne a přesměrovat peníze na skutečný most","Dárce je na dalším fundraiseru k vám chladný. Postaví se skutečný most."],["Schválit to a přidat druhý most pro jeho druhou cestu na golfový vozík","Teď existují dva mosty nikam. Místní zprávy tomu říkají „ten rozliv“."],["Přejmenovat to na „koridor odolnosti“ a doufat, že si toho nikdo nevšimne","Někdo si toho všimne okamžitě. Zůstává to nezaměnitelně cestou pro golfový vozík."]]},"p-congress-15":{"t":"Slyšení má špatné osvětlení a ještě horší otázky","x":"Jste předvolán svědčit před dozorčí výbor, podle toho, koho se zeptáte, ohledně naprosto všeho, co jste kdy udělal.","c":[["Na každou otázku odpovědět „to je utajené“, ať je to pravda, nebo ne","Polovina toho nikdy utajovaná nebyla. Teď je to titulek o lhaní pod přísahou."],["Odpovídat na vše upřímně a nechat věci dopadnout, jak dopadnou","Je to náročné odpoledne. Naštěstí je do večeře u konce."],["Přinést si připravený „gotcha“ moment na zesměšnění tazatelky","Gotcha moment se obrátí proti vám, když předloží stejný dokument, s dřívějším datem."],["Na každou otázku odpovědět lidovou historkou o dědečkově farmě","Nikdo se nedozví jediný fakt. Sledovanost, nepochopitelně, přesto stoupá."]]},"p-congress-16":{"t":"Malý dodatek o věčnosti","x":"Skupina spojenců potichu navrhuje zrušení funkčních limitů, jemně nazvané „modernizace kontinuity vedení“. Míní tím, že zůstanete, natrvalo.","c":[["Tvrdě přesvědčit hlasy a protlačit to výborem hned tento týden","Projde výborem. Fráze „věčný prezident“ se stane trendem a už nikdy nevymizí."],["Veřejně nápad odmítnout a požádat je, ať ho zcela stáhnou","Republika si tiše oddechne. Vaše základna si oddechne mnohem hlasitěji."],["Nechat to potichu postupovat, přitom vždy popírat, že jste o to žádal","Popření nevěří nikdo ani na vteřinu. Zákon přesto postupuje dál."],["Navrhnout „kompromis“ jen jednoho dalšího období, jako laskavost","Jedno další období se okamžitě stává novým základním požadavkem pro příští cyklus."]]},"p-congress-17":{"t":"Národní den uznání prezidenta","x":"Mladý kongresman, dychtivý po pozornosti, předkládá rezoluci vytvářející federální svátek na vaši počest. Alarmujícím způsobem už má i znělku.","c":[["Nahlas ho podpořit a tlačit na vedení, ať ho urychlí","Projde. Znělka hraje v každé federální budově dalších deset let."],["Požádat ho, ať to laskavě stáhne, tohle je trochu přehnané","Stáhne to, viditelně zklamaný. Znělka naštěstí umírá s ním."],["Navrhnout, aby svátek zahrnoval i povinné přehlídky","Účast na povinných přehlídkách je, mírně řečeno, řídká."],["Navrhnout přejmenování svátku na počest založení země, ale znělku si nechat","Technicky už to není svátek na vaši počest. Znělka nepochopitelně zůstává o vás."]]},"p-congress-18":{"t":"Ostře formulovaný kus papíru","x":"Opozice předkládá návrh na pokárání, převážně symbolický a naprosto ponižující, kvůli komentáři, který jste pronesl o účesu zahraničního vůdce.","c":[["Přesvědčit vlastní poslance, ať to jednomyslně zamítnou","Čistě neprojde na straně stran, což se samo stává vlastním typem titulku."],["Vydat upřímnou omluvu a nechat celý návrh potichu vyprchat","Omluva zabere. Komentář o účesu je do týdne zapomenut."],["Ještě přitvrdit komentář o účesu během rozpravy v plénu","Zahraniční vůdce veřejně odpoví komentářem o vaší vysoké čelo."],["Poslat zahraničnímu vůdci poukaz do kadeřnictví jako mírové gesto","Nějak je to přijato jako ještě těžší urážka, než ten původní komentář."]]},"p-congress-19":{"t":"Opozice opouští budovu","x":"Rozzuřena kvůli manipulaci s harmonogramem, opozice úplně opustí sál, čímž zabrání usnášeníschopnosti, a co hůř, odnese si i většinu kávy.","c":[["Poslat pořádkovou stráž, ať je fyzicky přivede zpět","Přivedou je. Okamžitě také kvůli tomu podávají žalobu."],["Hlasování odložit a poctivě vyjednat jejich návrat","Vrátí se za dva dny. Hlasování nakonec proběhne, čistě a se záznamem."],["Hlasovat i tak a tvrdit usnášeníschopnost kreativním počítáním","Kreativní počítání nepřežije ani první soudní podání."],["Objednat do sálu pizzu a živě streamovat, jak sám čekáte a jíte","Stream je podivně poutavý. Legislativně tím nevyřešíte vůbec nic."]]},"p-congress-20":{"t":"Devět set stran, nula čtenářů","x":"Souhrnný zákon má devět set stran, hlasování o něm je za tři hodiny, a jediný člověk, který ho celý přečetl, je prý stážista jménem Diaz.","c":[["Hlasování prosadit i tak, Diaz může v případě potřeby odpovídat na otázky","Přijde to na přetřes. Diaz se na chvíli stává nejmocnějším člověkem v budově."],["Hlasování odložit, dokud si to poslanci skutečně nepřečtou","Odklad je nudný. Zákon, který nakonec projde, je mnohem méně trapný."],["Přidat dalších dvě stě stran, dokud se nikdo nedívá","Diaz si žádá přidat plat. Diaz si ho, upřímně, zaslouží."],["Nechat štáb udělat z toho jeden přátelský infografický přehled","Infografika zcela záměrně vynechává několik důležitých škrtů ve financování."]]},"p-congress-21":{"t":"Hlasování v hodinu, kdy by nikdo hlasovat neměl","x":"Vedení naplánuje závěrečné hlasování na druhou hodinu ranní, sázeje na to, že polovina Kongresu bude příliš unavená, nebo příliš zaneprázdněná něčím jiným, na to, aby řádně protestovala.","c":[["Nechat termín druhé ráno a hlasy protlačit i přes únavu","Projde. Několik poslanců později tvrdí, že si vůbec nepamatují, že hlasovali."],["Přesunout hlasování na rozumnou denní hodinu","Hlasování proběhne transparentně, ve dne, jako u funkční vlády."],["Přesunout hlasování ještě později, na čtvrtou ráno, pro jistotu","Dva senátoři to celé prospí. Jejich hlasy zůstávají měsíc sporné."],["Zásobit sál neomezenou kávou, „aby to bylo férové“","Káva to férovým nedělá. Jen tím udrží všechny vzhůru, ať si mohou stěžovat."]]},"p-congress-22":{"t":"Teambuilding v nejhorší možnou chvíli","x":"Výjezdní zasedání vaší strany, které mělo posílit jednotu před klíčovým hlasováním, se zvrhlo v tříwelkou hádku kvůli nehodě na kánoi a karaoke automatu.","c":[["Zasedání zrušit a nařídit všem okamžitý návrat do Kapitolu","Vrátí se sjednoceni přesně v jedné věci: v osobní nevraživosti vůči vám."],["Nechat je to dořešit, vydiskutovat a vrátit se soudržní","Vrátí se o dva dny později, upřímně bližší než předtím. Upřímně řečeno, ohromující."],["Připojit se k zasedání osobně, „obnovit morálku“ sám","Váš výběr karaoke písně se stává nejpamátnější, a nejhorší, částí celého výjezdu."],["Poslat místo sebe motivační zpívaný telegram","Zpívaný telegram si od výjezdního sboru vyslouží víc respektu, než byste si vysloužil vy sám."]]},"p-base-1":{"t":"Pojmenujte nepřítele","x":"Interní průzkumy ukazují, že vaše základna nechce politiku, chce padoucha. Váš odborník na průzkumy drží krátký seznam jmen, který vaši spisovatelé projevů zjevně napsali po půlnoci.","c":[["Přečíst jméno z kartičky, pomalu, pro kamery","Padouch, vyděšená úřednice na radnici, dostane do oběda tři výhrůžky smrtí."],["Říct, že skutečné problémy jsou složité a nikdo jednotlivý za ně nemůže","Dav bučí přesně tím způsobem, jakým davy bučí na domácí úkol."],["Jmenovat úřednici, jejího manžela a jejich zlatého retrívra","Wikipedie retrívra je do hodiny vandalizována."],["Svalit vinu na oblak ve tvaru vašeho předchůdce","Meteorologové jsou teď považováni za součást spiknutí."]]},"p-base-2":{"t":"Zakázaný medvěd","x":"Dětskou obrázkovou knížku o medvědovi, který se dělí o med se zvířátky z lesa různého původu, označily tři facebookové skupiny za, cituji, propagandu grooming. Váš ředitel sociálních sítí chce prohlášení ještě před obědem.","c":[["Žádat stažení medvěda ze všech knihoven v zemi","Autor medvěda dostane knižní smlouvu třikrát vyšší, než byla jeho záloha."],["Říct, že je to jen kniha o medvědovi, co se dělí o med, a nechat to být","Kabelový komentátor vás obviní z toho, že jste vůči medvědům měkký."],["Žádat stažení medvěda, vyšetření autora a přejmenování medu","Prodej medu ve vašich nejsilnějších okresech se ze vzdoru ztrojnásobí."],["Oznámit, že medvěd byl tajně vyznamenaný válečný hrdina, a udělit mu milost","Medvěd, jsa fiktivní, milost vděčně přijímá."]]},"p-base-3":{"t":"Problém s merchem","x":"Váš kancléř hlásí, že internetový obchod má vyprodanou položku, která se prodává třikrát líp než cokoli jiného: hrnek s vaší tváří photoshopnutou na řvoucího orla.","c":[["Narychlo objednat padesát tisíc dalších, označit je jako limitovanou edici","Vyprodá se za jedenáct minut a několik jich dorazí už rozbitých."],["Žádat merch, který má důstojnost. Třeba slušnou sponu na kravatu","Spona se prodá čtyři kusy, všechny vašemu právníkovi."],["Přidat sesterský hrnek s plačícím soupeřem","Federální etický úřad otevře spis, který nikdy nezavře."],["Dát svou tvář na orla A na vlajku A na monster truck","Verze s monster truckem je stažena z prodeje kvůli konstrukčním důvodům, které s vaší tváří nesouvisí."]]},"p-base-4":{"t":"Skandování","x":"Dav na včerejším shromáždění bez vyzvání vymyslel skandování požadující uvěznění úřadujícího federálního soudce. Váš spisovatel projevů to zachytil na video a nemůže si to přestat pouštět dokola.","c":[["Vést skandování sám na příštím shromáždění, pomaleji, ať se může přidat každý","Soudce žádá o ochranku a dostane ji."],["Říct davu, že soudy takhle nefungují, a požádat je, ať přestanou","Vypískají vás z pódia o devět minut dřív."],["Přidat druhou sloku se jmény soudcových asistentů","Dva asistenti se potichu stáhnou z veřejného života."],["Tvrdit, že skandování ve skutečnosti mluví o maskotovi ligy nižší třídy se stejným jménem","Maskot, zmatený mýval, se odmítá vyjádřit."]]},"p-base-5":{"t":"Teorie o sklepě","x":"Podstatná část vaší základny je přesvědčena, že viceprezident je hologram ovládaný ze sklepa ve státě, který, přísně vzato, žádné sklepy nemá kvůli hladině spodní vody. Váš tiskový poradce potřebuje instrukce.","c":[["Na tiskovce na to mrkněte a nechte to bujet.","Hologramové zboží se prodává lépe než to skutečné."],["Jasně prohlaste, že viceprezident je skutečná, fyzická osoba.","Věřící usoudí, že přesně tohle by hologram řekl."],["Naznačte, že hologramy jsou možná DVA, střídají se na směny.","Sklep v onom bezesklepém státě je pod dohledem amatérů."],["Nechte skutečného viceprezidenta žonglovat naživo, aby dokázal svou tělesnost.","V přímém přenosu mu upadne kuželka a teorie se, jaksi, jen posílí."]]},"p-base-6":{"t":"Světec z parkoviště","x":"Muž, kterého mírně obtěžovali na úřadě dopravní evidence o tři státy dál, byl vaší základnou svatořečen jako mučedník hnutí, včetně svíček a hashtagu. On sám z toho vypadá zmateně. Vaše tisková mluvčí potřebuje formulaci.","c":[["Pozvěte ho na pódium a udělte mu medaili, kterou jste vymysleli před hodinou.","Medaili přijme, přestože stále netuší, co vlastně udělal."],["Jemně poznamenejte, že dlouhá fronta na úřadě není, historicky vzato, mučednictvím.","Jste obviněni z neúcty k jeho oběti."],["Vyhlaste na jeho počest státní svátek a přejmenujte úřad.","Přejmenovaný úřad má pořád dlouhou frontu."],["Odhalte, že je náhodou váš bratranec z třetího kolena.","Genealogové žádnou takovou příbuznost nenajdou, a nikdo si toho nevšímá."]]},"p-base-7":{"t":"Seznam k bojkotu","x":"Vaše základna chce bojkotovat řetězec kaváren za zločin duhového posypu na sezónním donutu. Vaše poradkyně pro vnitřní bezpečnost, zmatená, jak se jí to dostalo na stůl, vám to přesto přeposílá.","c":[["Tweetněte název řetězce a nazvěte to neamerickým donutařstvím.","Akcie řetězce den klesají, donut se vyprodá na týden."],["Řekněte, že posyp neohrožuje republiku.","Jste obviněni, že jste se postavili na stranu posypu."],["Jmenujte tři další řetězce a pekárnu, která kdysi použila duhový ubrousek.","Rodinná pekárna, fungující od roku 1962, do měsíce zavírá."],["Ohlaste rivalský, vlastenecký donut bez posypu, jen s hvězdičkami.","Hvězdičky se prý špatně prokusují."]]},"p-base-8":{"t":"Špatně složená vlajka","x":"Virální fotka ukazuje dobrovolníka na stadionu, jak skládá vlajku s, podle vaší základny, o jeden záhyb méně. Kancelář vašeho generálního prokurátora obdržela čtyřicet formálních stížností s požadavkem na federální obžalobu.","c":[["Požadujte zveřejnění jména dobrovolníka.","Sedmnáctiletý dobrovolník je na týden vyloučen ze školy."],["Řekněte, že špatné složení vlajky není zločin.","Jeden kongresman vás nazve slabým ve věcech vlajky."],["Navrhněte federální Radu pro standardy skládání vlajky s pravomocí předvolávat svědky.","První slyšení rady trvá čtyři hodiny navíc kvůli jedinému záhybu."],["Osobně přeskládejte vlajku v přímém přenosu, špatně, ale sebevědomě.","Nikdo se neodváží zmínit, že vaše má stejný počet záhybů."]]},"p-base-9":{"t":"Zmizelý betlém","x":"Nákupní centrum o tři státy dál nahradilo svůj betlém obyčejným vánočním stromkem a vaše základna to považuje za zahajovací bitvu koordinovaného národního útoku na samotné svátky.","c":[["Vyhlaste nouzový stav Válka o Vánoce a požadujte navrácení betléma.","Centrum betlém vrátí a hlásí rekordní návštěvnost."],["Poznamenejte, že obchodní centra mění výzdobu každý rok a vždy tomu tak bylo.","Jste obviněni, že nenávidíte Vánoce i obchodní centra."],["Vyžadujte přísahu věrnosti od každého maloobchodníka ohledně sváteční výzdoby.","Nafukovací sněhulák jednoho železářství je vyšetřován pro nedostatečnou úctu."],["Osobně přivezte betlém do centra na valníku, naživo.","Jeden z tří králů poblíž food courtu spadne."]]},"p-base-10":{"t":"Žába v obleku","x":"Kreslená žába v obleku a kravatě jako vy se stala neoficiálním maskotem vašeho hnutí, objevuje se na vlajkách, tetováních i na dodávce jednoho velmi odhodlaného muže. Váš syn to považuje za skvělé a chce to zoficiálnit.","c":[["Přijměte žábu jako oficiálního maskota kampaně.","Žabí zboží do týdne překoná to vaše skutečné."],["Řekněte, že politické hnutí by nemělo zastupovat kreslená žába.","Základna usoudí, že vy osobně nejste žábin největší fanoušek, a to je podezřelé."],["Nechte žábu vystoupit na příštím mítinku v plném kostýmu a mávat.","Dítě v první řadě pláče, ze strachu nebo z nadšení, není jasné."],["Nechte si žábu právně ochránit ochrannou známkou, než na ní vydělá někdo jiný.","Během pár dní přichází žaloba od nesouvisející značky žabích cereálií."]]},"p-base-11":{"t":"Zjevně příliš umírněný","x":"Neznámý poslanec zastupitelstva má v primárkách, které nikdo nevypsal, šest procent proti vám a kandiduje napravo od vás na programu, který váš stratég popisuje jen jako hlasitější.","c":[["Útočte na něj osobně, každou noc, dokud nezmizí.","Jeho sbírka peněz se díky té pozornosti ztrojnásobí."],["Ignorujte ho a soustřeďte se na vládnutí.","Základna usoudí, že mlčení znamená, že má pravdu."],["Předběhněte ho politikou tak extrémní, že to i on nazve extrémismem.","Obrátí se a nazve vás napodobitelem, správně."],["Nabídněte mu vymyšlené velvyslanectví v zemi bez pobřeží.","Nadšeně přijme a už o něm nikdy nikdo neuslyší."]]},"p-base-12":{"t":"Pastor Combs chce laskavost","x":"Pastor Combs z dvanáctitisícové arény Liberty Now Arena Church je připraven vás v neděli podpořit z kazatelny. Rád by si ale promluvil o územní výjimce pro svou novou parkovací budovu.","c":[["Potichu schvalte výjimku a přijměte podporu.","Parkovací budova vyroste vedle mokřadu, o kterém už nikdo nikdy nemluví."],["Odmítněte laskavost a požádejte o podporu na základě jejích vlastních zásluh.","Pastor Combs se slzami v očích podpoří vašeho protikandidáta v primárkách."],["Schvalte výjimku, plus daňovou úlevu, plus druhou parkovací budovu.","Mokřad je teď oficiálně parkovací budova."],["Požádejte pastora Combse, aby vás znovu pokřtil, na pódiu, kvůli sledovanosti.","Voda byla podle několika svědků podezřele teplá."]]},"p-base-13":{"t":"Test loajality","x":"Prominentní příznivec zveřejnil online test čistoty o dvanácti otázkách. Váš viceprezident v něm získal osm z dvanácti bodů a lidé, kteří neumí definovat slovo měkkýš, ho tak nyní nazývají.","c":[["Vyplňte test veřejně a odpovídejte na každou otázku s maximální extrémností.","Získáte dvanáct z dvanácti a mírně vyděsíte vlastní personál."],["Řekněte, že testy čistoty rozkládají jakoukoli skutečnou koalici.","Autor testu napíše jízlivou reakci nazvanou Já Vám To Říkal."],["Zveřejněte VLASTNÍ test o třiceti otázkách a nechte viceprezidenta test opakovat.","Tentokrát skóruje ještě hůř, na testu, který jste napsali sami."],["Prohlaste samotný test za operaci hlubokého státu a požadujte jeho stažení.","Návštěvnost testu se přes noc zečtyřnásobí."]]},"p-base-14":{"t":"Pověst","x":"Váš tiskový asistent slyšel, z druhé ruky, že se mezi základnou šíří pověst, že jste ve dvaceti letech osobně zápasili s pumou a porazili ji. Není to pravda. Chce vědět, co s tím má dělat.","c":[["Nic nepotvrzujte ani nevyvracejte a nechte legendu růst.","Pamětní mince s pumou se čile prodává."],["Vydejte prosté, nudné popření. Nikdy jste s pumou nezápasili.","Popření samo je bráno jako další důkaz, že se souboj konal."],["Potvrďte to, přidejte medvěda a řekněte, že jste medvěda ze soucitu nechali žít.","Organizace na ochranu zvěře vás zdvořile žádá, abyste přestal."],["Předveďte svědka, starého muže, který tvrdí, že u toho byl.","Svědek si nevzpomíná, na které hoře k tomu vlastně došlo."]]},"p-base-15":{"t":"Falešná zpráva","x":"Vymyšlený titulek tvrdící, že váš protikandidát chce zdanit dešťovou vodu, se šíří vaší základnou tempem, které váš ředitel sociálních sítí obdivně nazývá bezprecedentní.","c":[["Sdílejte to sami s poznámkou někteří lidé říkají.","Oprava od ověřovatele faktů dosáhne jen desetiny záběru falešné zprávy."],["Veřejně uveďte věc na pravou míru. Nikdo dešťovou vodu nezdaňuje.","Jste obviněni z ověřování faktů proti vlastní straně, což je kardinální hřích."],["Přidejte navazující tvrzení, že chce zdanit i SNÍH.","Meteoroložka je v obchodě s potravinami napadena z důvodů, které se nikdy nedozví."],["Tvrďte, že jste osobně zachytili zákon o dani z dešťové vody a roztrhali ho.","Žádný takový zákon nikdy neexistoval, detail, na který se nikdo neptá."]]},"p-base-16":{"t":"Zákaz slova","x":"Slovo, dříve zcela nevýrazné, prohlásila jedna frakce vaší základny za urážlivé poté, co ho ve svém projevu použil politický soupeř. Váš právník potřebuje vědět, zda federální vláda může slovo skutečně zakázat. Nemůže.","c":[["Oznamte, že zvažujete všechny právní možnosti, jak ho zakázat.","Vyhledávání slova ve slovníku vzroste o devět set procent."],["Trpělivě vysvětlete, že existuje první dodatek ústavy.","Jste obviněni, že to slovo osobně milujete."],["Zakažte slovo ve federálních budovách i jeho blízká synonyma.","Tezaurus je krátce, docela vážně, považován za kontraband."],["Vymyslete nové slovo jako náhradu a nařiďte jeho používání ve svých projevech.","Nikdo, včetně vás, ho neumí vyslovovat pokaždé stejně."]]},"p-base-17":{"t":"Buck chce požehnání","x":"Vůdce milice, který si říká Buck, se objevil už na třech mítincích s dvěma tucty ozbrojených mužů ve stejných vestách a rád by od vás dostal veřejné uznání. Vaše zástupkyně pro záležitosti veteránů, sama veteránka, je z toho nesvá.","c":[["Ze pódia Bucka pochvalte jako skutečné vlastence.","Buckova skupina se do měsíce ztrojnásobí."],["Odmítněte Buckovu skupinu jakkoli uznat.","Buck vás do mikrofonu na livestreamu nazve podvodníkem."],["Pozvěte Buckovy muže, aby sloužili jako neoficiální ostraha mítinku.","Novinář je krátce zadržen muži, kteří k tomu nemají žádnou zákonnou pravomoc."],["Udělte Buckovi čestný titul bez skutečné moci, třeba Polní maršál v.v.","Buck si do hodiny nechává vytisknout vizitky."]]},"p-base-18":{"t":"Velká latte panika","x":"Váš stratég hlásí sílící přesvědčení mezi základnou, že pobřežní elity potichu rozmisťují pražírny řemeslné kávy do každého města v zemi, aby, slovy jednoho respondenta, nahradily skutečné Američany lidmi, kteří říkají artisanal.","c":[["Na příštím mítinku ponuře varujte před kávou, která si jde po jejich jídelnách.","Jídelna o tři města dál hlásí čtyřicetiprocentní nárůst prodeje kávy, ironicky ze zvědavosti."],["Poukažte, že kavárny ve skutečnosti nejsou demografickou hrozbou.","Jste obviněni, že jste se postavili na stranu ovesného mléka."],["Navrhněte clo na nadutá nápoje podle definice výboru, který sami jmenujete.","Výbor se nedokáže shodnout, co je nadutost, a věnuje tématu sedm zasedání."],["Otevřete si na příštím mítinku rivalský stánek s jídelní kávou, deset dolarů za šálek.","Vyprodá se, přesně za cenu, ze které si dělal legraci."]]},"p-base-19":{"t":"Vyhoďte toho intelektuála","x":"Vysoce kvalifikovaná poradkyně z ministerstva zahraničí na briefingu třikrát použila slovo nuance. Vaše základna ji chce mít pryč do západu slunce.","c":[["Veřejně ji vyhoďte a jako důvod uveďte její elitářskou slovní zásobu.","Další tři přijatí na ministerstvu jsou znatelně horší ve své práci a mnohem hlasitější."],["Nechte ji. Nuance, poznamenáte, je v zahraniční politice obecně užitečná.","Rozhlasový moderátor stráví celou reláci zesměšňováním samotného slova nuance."],["Vyhoďte ji a pak i dva kolegy, kteří se jí zastali.","Zbylý personál ministerstva ze samé opatrnosti přestává na poradách používat víceslabičná slova."],["Přesuňte ji do kanceláře bez oken, ať studuje jednu extrémně nevýznamnou smlouvu.","Dokončí o ní definitivní zprávu, kterou si nikdo nikdy nepřečte."]]},"p-base-20":{"t":"Patnáctimetrový vy","x":"Občanský výbor, devět lidí, jeden z nich váš bratranec, vybral z drobných darů dost na patnáctimetrovou sochu vás na dálničním odpočívadle. Váš šéf kanceláře potřebuje rozhodnutí o odhalení.","c":[["Zúčastněte se odhalení a nechte se vyfotit u paty sochy.","Několik řidičů hlásí, že výraz sochy je z jistých úhlů dálnice znepokojivý."],["Požádejte je, ať peníze místo toho věnují na opravu silnic.","Výbor je zmatený a mírně dotčený."],["Schvalte sochu plus druhou na hranici státu, mávající.","Mávající ruka sochy se při bouři do měsíce utrhne."],["Požádejte, aby socha byla o pět metrů vyšší, než se původně plánovalo.","Nyní vyžaduje vlastní územní výjimku, která je samozřejmě udělena."]]},"p-base-21":{"t":"Tvář na jeho paži","x":"Superfanoušek si nechal na předloktí vytetovat překvapivě věrný portrét vašeho obličeje a právě teď stojí u zábrany, s vyhrnutým rukávem, v naději, že si toho všimnete. Váš asistent si není jistý, že je tohle normální.","c":[["Podepište to tetování přímo, permanentní fixou, v přímém přenosu.","Tetovací salon o tři státy dál hlásí náhlý, velmi konkrétní nárůst zákazníků."],["Zdvořile mu řekněte, že to je na politika docela závazek.","Vypadá opravdu zraněně, a nějak tak i celá základna."],["Pozvěte ho na pódium, ať tetování ukáže celé aréně.","Do rána si stejný motiv nechá udělat čtyřicet lidí u stejného tatéra."],["Nechte si na oplátku udělat malé, nenápadné tetování jeho tváře.","Podle všech je to, se vší úctou, dost špatná podobizna."]]},"p-base-22":{"t":"Vůdce skandování chce místo v kabinetu","x":"Muž, který vede skandování davu na úplně každém mítinku už rok, funkce bez formálního titulu a bez kvalifikací kromě obrovského hlasu, by rád byl zvažován na post ministra něčeho. Váš syn to považuje za skvělý nápad.","c":[["Jmenujte ho do skutečné funkce v kabinetu s kamennou tváří.","Jeho první politické memorandum je, slovo od slova, pokřik."],["Poděkujte mu za službu a vysvětlete, že práce vyžaduje přinejmenším relevantní zkušenosti.","To odpoledne vede dav v pokřiku o vaší nevděčnosti."],["Jmenujte ho A udělejte ze skandování oficiální vládní funkci s vlastním rozpočtem.","Úřad pro vedení skandování si do týdne žádá další personál."],["Jmenujte ho čestným Vícevůdcem skandování a nechte skutečné místo neobsazené.","Je nadšený; nikdo neumí vysvětlit, co ten titul znamená."]]},"p-pardon-1":{"t":"Kruh zakladatele","x":"Právní zástupce vysvětluje, že Trevor Bulwark, zakladatel zkrachovalého penzijního fondu Pinnacle Retirement Trust, vyvedl osmdesát milionů dolarů z penzí důchodců, aby si koupil flotilu vodních skútrů. \"Říká, že je duchovně napravený,\" poznamenává právník. \"Také říká, že by chtěl zpátky svou jachtu.\"","c":[["Podepište milost","Bulwark otevírá Pinnacle Retirement Trust Dva pod mírně pozměněným logem."],["Odmítněte, ať se potí","Důchodci dostanou zpět zlomek svých peněz a přísně formulovaný dopis."],["Udělte milost a jmenujte ho ředitelem pro bezpečnost důchodů","Jeho první politické memorandum doporučuje víc vodních skútrů pro všechny."],["Udělte mu milost, ale musí každému důchodci osobně vrátit peníze u bankomatu, naživo","Přenos má víc diváků než projev o stavu unie."]]},"p-pardon-2":{"t":"Prostředí bohaté na cíle","x":"Generální prokurátor čte spis generála Marcuse Thorna, odsouzeného za nařízení útoku na svatbu, kterou nazval \"bohatou na cíle\". Thornův dopis o milost má čtyři strany stížností a jednu fotku, na které salutuje. \"Je oblíbený u základny,\" říká prokurátor, \"tak jako je oblíbený ohňostroj.\"","c":[["Podepište milost","Thorne pořádá uvítací mítink v bowlingové hale, kterou trvá na tom, že je \"strategicky významná.\""],["Odmítněte","Rodiny obětí vydávají prohlášení. Skoro nikdo si ho nepřečte."],["Udělte milost a jmenujte ho zvláštním vyslancem pro mír","Jeho první čin v zahraničí je, že se ministra zeptá, jestli \"chce problémy.\""],["Udělte mu milost pod podmínkou, že napíše omluvné paměti","Paměti se čile prodávají pod názvem \"Udělal bych to znovu, asi.\""]]},"p-pardon-3":{"t":"Přítel rodiny","x":"Sal Marchetti, odsouzený v jedenácti bodech za organizovaný zločin, byl podle žádosti o milost, kterou mu určitě nepsal jeho právník, po desetiletí \"drahým přítelem a štědrým podporovatelem\". \"Posílá pozdravy,\" říká právník, \"a velmi velkou šunku.\"","c":[["Podepište milost","Šunka byla ve skutečnosti nacpaná hotovostí. Nikdo se neptá, odkud ty peníze jsou."],["Odmítněte","Marchettiho společníci vyjadřují nespokojenost skrze několik malých, popiratelných požárů."],["Udělte milost a jmenujte ho velvyslancem na Maltě","Maltská vláda podává formální, nesmírně zdvořilou stížnost."],["Udělte mu milost výměnou za rodinný recept na calzone","Recept je skutečný. Je také, nezaměnitelně, výhrůžkou."]]},"p-pardon-4":{"t":"Slon v porcelánu","x":"Šerif \"Bull\" Haney podstrkoval důkazy desítkám obžalovaných a provozoval soukromou mýtnou budku pro řidiče bez dokladů projíždějící jeho okresem. Jeho příznivci tomu říkají \"policejní práce staré školy\". Předseda Nejvyššího soudu tomu říká několik federálních zločinů. \"Chce zpátky svůj odznak,\" říká předseda, \"konkrétně.\"","c":[["Podepište milost","Bull dostane zpátky odznak a tričko s nápisem \"Znovu ve službě.\""],["Odmítněte","Jeho oběti konečně dostanou slyšení, které není zmanipulované."],["Udělte milost a jmenujte ho pohraničním carem","Do týdne se objeví mýtné budky na třech dalších okresních hranicích."],["Udělte mu milost, přeřaďte ho k hlídání dárkového obchodu Bílého domu","Je, znepokojivě, velmi dobrý v prodeji hrnečků."]]},"p-pardon-5":{"t":"Offshore a na vaší straně","x":"Chip Renfro, velký dárce, ukryl před finančním úřadem zhruba dvě miliardy dolarů v devíti krycích firmách pojmenovaných podle jeho golfového handicapu. \"Rád by to nazval chybou ve výkazu,\" říká prokurátor, \"chybou ve výkazu za dvě miliardy dolarů.\"","c":[["Podepište milost","Renfro okamžitě otevírá desátou krycí firmu, tentokrát pojmenovanou podle vaší popularity."],["Odmítněte","Finanční úřad skutečně jednou vybere daně a nikdo mu nepoděkuje."],["Udělte milost a jmenujte ho poradcem ministerstva financí pro zjednodušení daní","Jeho plán zjednodušení má jednu stránku a prospívá přesně jednomu daňovému poplatníkovi."],["Udělte mu milost výměnou za \"manipulační poplatek\" deset procent","Je to podle jakékoli definice úplatek. Je to ale také, technicky, zpracované."]]},"p-pardon-6":{"t":"Na Měsíc a zpátky do vězení","x":"Dex Bramwell vytáhl peníze čtyřiceti tisícům investorů svým tokenem CoinDaddy a pak si koupil ponorku. \"Říká, že ta technologie předběhla svou dobu,\" hlásí váš syn se širokým úsměvem. \"Také říká, že vás nechá vydělat na CoinDaddy Dva.\"","c":[["Podepište milost","CoinDaddy Dva startuje do hodiny. Do dne se zhroutí."],["Odmítněte","Čtyřicet tisíc lidí dostane zhruba jedenáct centů každý a jedno ponaučení."],["Udělte milost a jmenujte ho krypto carem","Jeho první regulační pokyn je jediné emoji rakety."],["Přijměte poplatek za milost celý zaplacený jeho bezcennou mincí","Mince do večera nemá žádnou hodnotu. Ponorka je, jaksi, skutečná."]]},"p-pardon-7":{"t":"Mrazák plný dvacetidolarovek","x":"Kongresman Delbert Cranch byl přistižen se čtyřmi sty tisíci dolary v hotovosti nacpanými v kuchyňském mrazáku, zabalenými, jak trvá na tom, \"kvůli čerstvosti\". Tisková mluvčí čte žádost o milost nahlas s viditelnou fyzickou nevolností.","c":[["Podepište milost","Cranch si kupuje druhý, větší mrazák."],["Odmítněte","Cranch je vyloučen z kongresu a podle všeho vystěhován kvůli účtu za opravu mrazáku."],["Udělte milost a jmenujte ho předsedou etické komise","Jeho úvodní slovo je, jaksi, o správné organizaci mrazáku."],["Udělte mu milost, ale mrazák putuje do Smithsonova muzea","Je nyní nejnavštěvovanějším exponátem muzea."]]},"p-pardon-8":{"t":"Rodinný podnik","x":"Váš bratranec Wade předstíral vlastní únos kvůli pojistnému plnění a pak zveřejnil fotky ze \"zajetí\" z letoviska v Cabu. \"Říká, že rodina drží pohromadě,\" hlásí váš syn. \"Také říká, že letovisko má skvělý bar u bazénu.\"","c":[["Podepište milost","Wade vám na Díkůvzdání hlasitě poděkuje před kamerami, které jste nepozvali."],["Odmítněte","Wade si odsedí skutečný trest. Rodinná skupinová konverzace mlčí měsíc."],["Udělte milost a udělejte z něj regionálního styčného úředníka FEMA","Jeho první krizový briefing obsahuje podezřele mnoho doporučení baru u bazénu."],["Udělte mu milost, ale musí naživo předstírat, že ho tentokrát opravdu našli živého","Sledovanost je vynikající. Důvěryhodnost není."]]},"p-pardon-9":{"t":"Sleva ze skladu důkazů","x":"Detektiv Ray Kessler podstrkoval důkazy podezřelým, které neměl rád, a bral hotovost od kartelu za ty, které měl. Ředitel FBI mu přes stůl podává spis. \"Žádá o úplnou milost a, chci to zdůraznit, o své staré parkovací místo.\"","c":[["Podepište milost","Kessler dostane odznak, místo a okamžitě nového klienta."],["Odmítněte","Devět nespravedlivých odsouzení je díky jeho případu znovu otevřeno."],["Udělte milost a jmenujte ho šéfem interního vyšetřování","Stížnosti na interní vyšetřování vůči interním vyšetřovatelům se zečtyřnásobí."],["Udělte mu milost, natrvalo ho přeřaďte na inventarizaci skladu důkazů","Ukáže se, že je mimořádně dobrý v třídění ukradeného zboží."]]},"p-pardon-10":{"t":"Obležení soudu","x":"Plukovník Gid Strother držel okresní soud pod hlavní zbraně šest hodin kvůli sporu o územní plán. Viceprezident osobně doručuje žádost o milost, z nevysvětlených důvodů v maskáčové kravatě. \"Jeho muži ho milují,\" říká viceprezident. \"Stejně tak průzkumy.\"","c":[["Podepište milost","Strother pořádá vítězný mítink u stejného soudu, znovu ozbrojený."],["Odmítněte","Úřednice soudu, kterou ohrožoval, konečně může v klidu spát."],["Udělte milost a jmenujte ho oficiálním styčným důstojníkem pohraniční milice","Do měsíce hlásí tři další soudy podobné \"spory o územní plán.\""],["Udělte mu milost pod podmínkou, že jeho milice přejde na soutěžní patchwork","Přikrývky jsou, proti všem očekáváním, docela dobré."]]},"p-pardon-11":{"t":"Buvol se vrací","x":"Chad \"Buvol\" Merkins zaútočil na Kapitol s rohy na hlavě a vestou, na které nic konkrétního nestálo. Stal se lidovým hrdinou lidí, kteří na dvorku vlastní aspoň jednu vlajku na tyči. \"Chce zpátky své rohy z úschovy důkazů,\" říká váš tiskový asistent. \"Chybí mu.\"","c":[["Podepište milost","Rohy jsou vráceny. Merkins je nosí na brunch."],["Odmítněte","Merkins si odsedí trest a napíše z vězení ostře formulované, plné pravopisných chyb paměti."],["Udělte milost a udělejte z něj oficiálního průvodce po Kapitolu","Jeho prohlídka zahrnuje podrobnou rekonstrukci. Dvakrát denně. S rohy."],["Udělte mu milost a pak prodávejte rohy jako oficiální merchandise","Vyprodá se za hodinu. Merkins požaduje tantiémy."]]},"p-pardon-12":{"t":"Přirážka na inzulin","x":"Marlon Vance, generální ředitel farmaceutické firmy a spolehlivý dárce kampaně, ztrojnásobil ceny inzulinu během nedostatku, který sám osobně vyvolal. Jeho dopis o milost to popisuje jako \"reaktivní cenotvorbu\". Šéf personálu to soukromě nazývá \"zločinem s prezentací.\"","c":[["Podepište milost","Vance okamžitě oznamuje \"reaktivní cenotvorbu\" pro tři další léky."],["Odmítněte","Ceny inzulinu skutečně klesnou. Vance to nazve \"zásahem státu.\""],["Udělte milost a jmenujte ho poradcem pro zdravotní náklady","Jeho doporučení na snížení nákladů je, jaksi, vyšší ceny."],["Udělte mu milost, ale týden musí sám rozvážet inzulin od dveří ke dveřím","Nesnáší každou vteřinu. Fotky jsou ovšem skvělé."]]},"p-pardon-13":{"t":"Poslední z orlů","x":"Duke Callahan zastřelil poslední hnízdící pár chráněné kolonie orlů bělohlavých, protože, jeho slovy, \"jeden z nich se na mě divně díval\". Dokonce i pastor se cítí nesvůj, když tlumočí jeho žádost. \"Žádá o odpuštění,\" říká pastor, \"a o svou pušku zpátky.\"","c":[["Podepište milost","Callahan dostane pušku zpátky. Kolonie orly zpátky nedostane."],["Odmítněte","Ochránci přírody to nazývají vzácným vítězstvím. Callahan to nazývá \"pronásledováním.\""],["Udělte milost a jmenujte ho komisařem pro divokou zvěř","Jeho první politický návrh zkracuje seznam ohrožených druhů tím, že z něj druhy odstraňuje."],["Udělte mu milost, ale na každém mítinku musí nosit orlí kostým","Nosí ho. Nesnáší to. Dav ho, znepokojivě, miluje."]]},"p-pardon-14":{"t":"Fond na archu","x":"Reverend Silas Thorpe přesvědčil svou kongregaci, aby mu odevzdala své penzijní úspory na stavbu skutečné, plavbyschopné archy, a pak za peníze koupil menší, neplavbyschopnou jachtu. \"Říká, že Pán se pohybuje tajemnými cestami,\" povzdechne si pastor. \"Většinou směrem k jeho jachtě.\"","c":[["Podepište milost","Thorpe oznamuje Fond na archu Dva, \"tentokrát se skutečnou lodí.\""],["Odmítněte","Jeho kongregace dostane náhradu a konečně i trochu skepse."],["Udělte milost a jmenujte ho poradcem pro víru při administrativě","Jeho první kázání pro personál je nezaměnitelně sbírkovou kampaní."],["Udělte mu milost výměnou za osobní požehnání","Požehnání je nezvykle konkrétní a zahrnuje desátek."]]},"p-pardon-15":{"t":"Devatenáct let","x":"Odell Pruitt si odseděl devatenáct let za loupež, kterou nyní DNA důkazy prokazují, že nespáchal. Jeho právnička, nezvykle mlčenlivá, jen přisune přes stůl složku. \"Není v tom žádný chytrý úhel pohledu,\" říká. \"Je prostě nevinný.\"","c":[["Nechte ho tam, kde je","Základna jásá nad \"pořádkem a zákonem\". Pruitt zůstává v cele, která nikdy neměla být jeho."],["Propusťte ho","Pruitt vychází ven do světa, který je o devatenáct let jinde. Základna to nazývá měkkostí."],["Potichu mu zmírněte trest, bez zásluh, bez tiskové zprávy","Je volný, ale záznam ho pořád vede jako odsouzence. Nikdo si toho stejně nevšimne."],["Propusťte ho, ale jen pokud vám osobně na kameru poděkuje","Udělá to skrz zaťaté zuby. Devatenáct let koupilo velmi krátký proslov."]]},"p-pardon-16":{"t":"Kvůli pojistce","x":"Nadia Volkovová vypálila vlastní dům s regulovaným nájemným kvůli pojistnému plnění a při tom vystěhovala čtyřicet rodin. Předseda Nejvyššího soudu prochází spis s nevzrušeným výrazem. \"Ona tomu říká 'zpoždění renovace,'\" říká.","c":[["Podepište milost","Volkovová si kupuje druhou budovu. Zasvěcení očekávají druhý požár."],["Odmítněte","Čtyřicet rodin dostane náhradu. Volkovová dostane, co si zaslouží."],["Udělte milost a jmenujte ji do komise pro dostupné bydlení","Její první doporučení se týká zápalek, metaforicky, jak trvá na tom."],["Udělte jí milost pod podmínkou, že dům vlastnoručně znovu postaví","Ukáže se, že je opravdu mizerná tesařka."]]},"p-pardon-17":{"t":"Interní zpráva","x":"Ingrid Halvorsenová vynesla interní zprávu dokazující, že firma zakryla kontaminaci pitné vody, a byla odsouzena za \"krádež majetku vlády\" za papír, na kterém byla vytištěna. \"Neexistuje verze, ve které je záporák,\" přiznává váš mluvčí pro projevy, \"což je pro projev problém.\"","c":[["Nechte ji shnít","Základna ji nazve zrádkyní. Voda je pořád kontaminovaná."],["Propusťte ji","Halvorsenová vychází na svobodu a okamžitě pokračuje v odhalování. Základna zuří."],["Potichu jí udělte milost, bez tiskové zprávy, bez zásluh","Je volná. Nikdo z vaší základny se to nikdy nedozví, o to jde."],["Propusťte ji, ale utajte fakt, že jste to udělal","Milost je skutečná. Papíry, které to dokazují, oficiálně neexistují."]]},"p-pardon-18":{"t":"Kotec","x":"Chester Voss, spolehlivý dárce, provozoval ve stodole, kterou ve sbírkových e-mailech popisoval jako \"wellness ústraní\", psí zápasy. Generální prokurátorka čte obžalobu s viditelným odporem. \"Rád by to měl z krku před volbami v polovině období,\" říká.","c":[["Podepište milost","Voss stodolu znovu otevírá. Cedule teď hlásá \"wellness ústraní, fáze dvě.\""],["Odmítněte","Psi jsou umístěni do nových domovů. Vossovy sbírkové e-maily citelně utichnou."],["Udělte milost a jmenujte ho poradcem pro rozvoj venkova","Jeho první návrh zahrnuje federální dotace na \"wellness ústraní.\""],["Udělte mu milost pod podmínkou, že si osobně adoptuje každého psa","Nyní vlastní čtyřicet psů a podle všeho nesnáší úplně každého z nich stejnou měrou."]]},"p-pardon-19":{"t":"Eunice","x":"Eunice Radleyová, sedmdesát osm let, si odpykává doživotní trest za prodej malého množství marihuany podle zákona, který mezitím zrušili všude kromě jejího spisu. \"Nežádá o peníze ani o titul,\" poznamenává předseda Nejvyššího soudu. \"Jen chce znovu vidět svou zahradu.\"","c":[["Nechte ji tam, kde je","Základna tleská tvrdosti. Eunice zmešká další narozeniny za mřížemi."],["Propusťte ji","Eunice znovu uvidí svou zahradu. Základna reptá o \"měkkosti vůči zločinu.\""],["Propusťte ji jen pokud vám na kameru poděkuje","Udělá to, zdvořile, se slzami, které nejsou zcela vděčné."],["Propusťte ji a pak si ji najměte, ať peče pro Bílý dům","Její koláč je podle jednomyslného hlasování personálu lepší než ten od kuchaře Bílého domu."]]},"p-pardon-20":{"t":"Dokonalejší padělek","x":"Percival Ott prodal třem muzeím padělaný koncept Deklarace nezávislosti, ručně zestárlý čajovými sáčky a údajně opravdovou láskou k řemeslu. \"Není mu to líto,\" hlásí mluvčí pro projevy. \"Je na to hrdý. Chce, aby to bylo v milosti výslovně uvedeno.\"","c":[["Podepište milost","Ott okamžitě začíná pracovat na padělané Listině práv."],["Odmítněte","Muzea dostanou své peníze zpět. Ott dostane skutečný, nefalšovaný trest."],["Udělte milost a jmenujte ho kurátorem Národního archivu","Návštěvnost stoupá. Stejně tak, potichu, i počet padělků v archivu."],["Udělte mu milost, ale musí místo toho zfalšovat lichotivou biografii o vás","Stává se bestsellerem. Historikové poznamenávají, že je to přinejmenším ze sedmdesáti procent fikce."]]},"p-pardon-21":{"t":"Stál u popelnice","x":"Marcus Ibe byl obviněn z domácího terorismu za to, že stál poblíž hořící popelnice na pokojném shromáždění, které nezaložil a snažil se uhasit. \"Uhasil ten oheň,\" říká ředitel FBI. \"Je to ve zprávě. Tu část si nikdo nepřečetl.\"","c":[["Nechte ho shnít","Základna ho nazve hrozbou. Zůstává ve vězení za uhašení požáru popelnice."],["Propusťte ho","Ibe vychází na svobodu. Základna trvá na tom, že to dokazuje, že systém je \"nastaven ve prospěch zločinců.\""],["Potichu ho propusťte, ale obvinění z terorismu zůstává v jeho záznamu","Je venku, ale každá prověrka po zbytek jeho života ho označí jako hrozbu."],["Propusťte ho a nabídněte mu reality show o tom všem","Pilotní díl se jmenuje \"Požár v popelnici\". Dostane objednávku na celou sezónu."]]},"p-pardon-22":{"t":"Doktor cukrových pilulek","x":"Doktor Warrick Slate prodal tisícům onkologických pacientů chemoterapeutické pilulky, které podle laboratorního rozboru byly převážně cukr. \"Nazývá to 'obchodním modelem blízkým placebu,'\" čte jeho právník nahlas a pak papír odloží, jako by byl radioaktivní.","c":[["Podepište milost","Slate do týdne ohlašuje novou řadu pilulek \"blízkých wellness.\""],["Odmítněte","Oběti se konečně dočkají svého dne u soudu a svých peněz zpět."],["Udělte milost a jmenujte ho do poradního sboru úřadu pro potraviny a léčiva","Jeho první hlas je proti přísnějším požadavkům na označování pilulek."],["Udělte mu milost pod podmínkou, že nejdřív sní vlastní pilulky","Bez váhání je sní. To vypovídá o všem."]]}};
